pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny post-residuals (< 10) are "dead space"
    // since item sizes can be as small as 1 in this interface; still, gaps that
    // cannot fit the next item are wasted. Penalize unusable gaps heavily.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Gap too small for the lookahead item -> dead space penalty,
            // stronger the smaller (more useless) the gap is.
            let deadness = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 30.0 + 40.0 * deadness;
        } else if post_residual >= next_item_size {
            // Reward leaving a gap that still accommodates the next item,
            // especially a snug one (low slack after the hypothetical next item).
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 15.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the ONLY bin that fits the item,
    // strongly prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of open bins; the more bins
    // already open, the stronger the push to consolidate into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);
    score += pressure * 3.0;

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large relative to capacity or no good consolidation exists. Base cost of
    // opening a bin, discounted when item is big.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        score = 45.0 - 30.0 * size_frac;
        // If other bins fit and mean residual is large, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
        }
    } else {
        // Favor bins whose residual is close to what we consume (tight packing)
        // relative to the fleet mean residual.
        score += 5.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny slivers are dead space
    } else if post_residual < 20 {
        score += 15.0;
    } else {
        // Larger residuals: mild convex penalty so big gaps are discouraged but not fatal
        let r = post_residual as f64;
        score += 0.05 * r * r / bin_capacity as f64;
    }

    // Reward perfect fit
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // blocking the next item
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when existing bins would waste badly
    if bin_residual == bin_capacity {
        score = 30.0 + open_bins_count as f64 * 0.4;
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when it's the last chance
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing next item with this one in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual below the minimum plausible item size (~1/10 of capacity) is waste.
    let min_item = bin_capacity as f64 / 10.0;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += (min_item - post_residual as f64) * 6.0;
    }

    // Perfect fit bonus: nothing left over is highly desirable.
    if post_residual == 0 {
        score -= bin_capacity as f64 * 0.5;
    }

    // Reward leaving room for the lookahead item (k=2) if it fits exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= next_item_size as f64 * 0.8;
        } else if (post_residual as u64) < next_item_size as u64 && post_residual > 0 {
            // Post-residual too small for next item: dead space relative to lookahead.
            score += (next_item_size as f64 - post_residual as f64) * 2.5;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (penalize the alternative implicitly).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
    score += pressure * 1.5;

    // Slight stream-phase term: late in stream, waste matters more (no future to reuse gaps).
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * (post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current bin fits are poor
    // (large dead space would be created) or no bins fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + pressure * 0.5;
        if fitting_bins_count == 0 {
            score -= bin_capacity as f64 * 0.8;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that can't fit the next item (wasted capacity).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can still accommodate the lookahead item.
            score -= 6.0;
        }
        // Perfect chain fit: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Penalize leaving a residual in the awkward zone that few future items fit.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream: prefer closing bins out, penalize spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Many open bins: encourage filling existing ones rather than opening more.
    score += (open_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Compare against mean residual: bins below mean residual are "fuller", favor them.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: neutral baseline with slight bias toward using open bins
    // unless they are all poor fits (handled by penalties above).
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Mid-range gaps (10..30) are moderately wasteful.
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0 * (30.0 - post_residual as f64) / 20.0;
    }

    // Reward near-perfect fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual - next_item_size < 10 {
                score -= 10.0; // lookahead completes the bin nicely
            }
        } else {
            score += 6.0; // lookahead cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless fit is tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 1.0 + 0.05 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    score *= pressure;

    // New-bin candidate: only attractive when item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a bin; discount when item is large (would waste little).
        score = 55.0 - 30.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
        if fitting_bins_count == 1 {
            score += 45.0; // an open bin fits fine; do not open a new one
        }
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 8.0; // new bin leaves room for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are "dead space".
    let min_useful = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 + (min_useful - post_residual) as f64 * 4.0;
    }

    // Small-but-marginal gaps: penalize residuals below ~20 harshly
    // (unlikely to fit future items of unknown distribution cleanly).
    if post_residual >= min_useful && post_residual < 20 {
        score += 25.0 - (post_residual - min_useful) as f64;
    }

    // Reward when the lookahead item fits exactly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (post_residual - next_item_size) as f64 * 0.5;
    }
    // Penalize when lookahead item almost fits but not quite (wasted potential).
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0
        && next_item_size - post_residual <= 10 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good.
    score += open_bins_count as f64 * 0.8;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bin fit is bad
    // (large post residual relative to capacity or dead space).
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its residual is maximal, so start neutral
        // and adjust based on how wasteful the best alternative would be.
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
        // If an existing bin would leave a near-perfect fit, prefer it.
        if post_residual < 5 && bin_residual != bin_capacity {
            score += 50.0;
        }
    }

    // Mild preference for tighter fits overall relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight late-stream conservatism: consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps heavily.
    let min_item = 1u32;
    if post_residual > 0 {
        // A gap is "dead" if it is smaller than the smallest possible item (1)
        // or too small for the lookahead item. Penalize proportionally to waste.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0; // tiny unusable gap -> big penalty
        }
        if next_item_size > 0 && post_residual < next_item_size {
            // gap can't fit the next item: dead space for lookahead
            score += (next_item_size - post_residual) as f64 * 1.5;
        } else if next_item_size > 0 && post_residual >= next_item_size {
            // gap can host the next item: reward tight chaining
            score -= (post_residual - next_item_size) as f64 * 0.5;
        }
    } else {
        // Perfect fill: strong reward
        score -= 60.0;
    }

    // Reward tight fits (high fill ratio of this placement)
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 10.0;

    // Open-bin pressure: fewer open bins favored when residuals are large;
    // discourage spreading when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    score += pressure * (mean_residual / bin_capacity as f64) * 0.8;

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make empty bin moderately attractive only when
    // the current item is large relative to residuals elsewhere.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > mean_residual * 0.9;
        if large_item {
            score -= 15.0;
        } else {
            score += 12.0; // prefer existing bins for small items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fit — big reward.
        score -= 40.0;
    } else if post_residual < 10 {
        // Tiny dead space: nearly unusable for any item (min size 10 in classic
        // setting, but interface allows 1..100 — still, small gaps are risky).
        score += (10.0 - post_residual as f64) * 6.0;
    }

    // Non-linear penalty on post_residual relative to bin capacity.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    score += 3.0 * (pr / cap) * (pr / cap) * 10.0;

    // Reward tight fits: gap between residual and item size small.
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score -= 20.0 * (1.0 - tightness).max(0.0) * (1.0 - tightness).max(0.0);

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only allow opening a new bin if this bin's fit is bad.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; opening new bin keeps large residual for future.
        score = 55.0 + 0.5 * mean_residual;
        // If lookahead fits well into the fresh residual, mild bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Lookahead synergy: if next item fits the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to what's coming next.
        score += 4.0;
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping.
    // Favor tight fits: reward low post_residual super-linearly.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Dead-space penalty: residuals too small for any plausible item (items >= 1),
    // strongly penalize near-zero residuals late in the stream.
    let dead = (-norm_pr + 0.15).max(0.0);
    score += 40.0 * dead * dead * (0.5 + progress);

    // Stream-progress coupling: early on, prefer keeping flexibility (higher residual);
    // later, prefer tight packing aggressively.
    let flex = (1.0 - progress).powi(2);
    score -= 25.0 * flex * norm_pr;
    score += 15.0 * progress * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral baseline with slight discouragement,
    // unless residuals of open bins are poor or none fit.
    if bin_residual == bin_capacity {
        let poor_fits = (mean_residual - pr).abs() < 1e-9;
        let mut bias = 30.0;
        // If mean residual of open bins is small, opening a new bin is attractive.
        bias -= (mean_residual / cap).max(0.0) * 45.0;
        // Late in stream, slightly discourage opening new bins.
        bias += 20.0 * progress;
        // Lookahead: if next item is large, a fresh bin is valuable.
        let n = next_item_size as f64;
        if n > 0.0 {
            bias -= (n / cap).max(0.0) * 20.0 * (1.0 - progress);
        }
        if poor_fits && open_bins_count > 0 {
            bias -= 10.0;
        }
        score = bias;
    }

    // Lookahead synergy: reward leaving post_residual that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        // Penalize residuals that block the next item.
        score += 8.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating open bins when residuals are scattered.
    if open_bins_count > 1 {
        score += 2.0 * ((mean_residual - pr).abs() / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: fill the bin as completely as possible.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly into the post residual,
    // penalize if next item is close but wastes the bin.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (next - post_residual as f64).abs() < 1.0 {
            score -= 500.0;
        } else if next_item_size == post_residual {
            score -= 500.0;
        }
        if next_item_size > post_residual {
            // next item can't use leftover space; leftover is dead unless tiny
            if post_residual < 10 {
                score -= 20.0; // small dead space is acceptable
            } else {
                score += 15.0;
            }
        } else {
            // next item fits: leftover split between two items is good
            score -= 30.0;
        }
    }

    // Relative-to-mean-residual coupling: prefer bins whose residual deviates
    // usefully from the mean (tight bins first for tight fits).
    let res = post_residual as f64;
    let dev = res - mean_residual;
    score += 0.5 * dev;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Only open a new bin when existing residuals are poor fits.
        let tightness = if next_item_size > 0 {
            (next_item_size as f64 / bin_capacity as f64)
        } else {
            item_size as f64 / bin_capacity as f64
        };
        // Penalize new bins mildly; escalate when stream is late and bins are many.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 + 80.0 * progress - 40.0 * (open_bins_count as f64).ln().max(0.0);
        // If the item is large, opening fresh is more attractive.
        score -= 30.0 * tightness;
    }

    // Slight preference for tighter bins overall.
    score += 0.3 * (bin_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band it falls into
    let q = (bin_capacity / 4) as f64; // quarter-class granularity
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward perfect / near-perfect fits (post_residual in small residue classes)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Integer-division thresholds: penalize dead space that no future item can fill.
    // Items are 1..=100; residual below ~10 is nearly dead -> big penalty.
    if post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Modulo coupling: post_residual % 10 measures alignment with common item sizes
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0; // residual divisible by 10 is reusable
    } else if m >= 7 {
        score += 6.0; // awkward 7..9 sliver
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 {
                score -= 15.0;
            }
            score += nxt_post as f64 * 0.15;
        } else {
            // next item cannot use this residual: penalize large residuals less
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Class-band reward for landing residual in a "harmonic" band (multiples of quarter capacity)
    let band = (post_frac * 4.0).round() / 4.0;
    if (post_frac - band).abs() < 0.02 && post_residual > 0 {
        score -= 5.0;
    }

    // Last-chance bonus: only one fitting bin -> prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive if the item
    // is large relative to typical residuals and current bins are crowded.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // penalize new bins, but less when item is huge or many bins are open
        score += 45.0
            - 0.25 * item_size as f64
            - 1.5 * open_bins_count as f64
            - 10.0 * progress;
        if next_item_size > item_size && next_item_size > bin_capacity / 2 {
            score -= 15.0; // big follower: fresh bin may help
        }
    }

    // Slight preference for tighter bins overall
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host a plausible
    // future item (small unusable gaps) are heavily penalized.
    // Treat gaps < 10 (or < next item if it's larger) as dead space.
    let min_useful = if next_item_size > 0 { next_item_size.min(80).max(10) } else { 10 };
    if post_residual < min_useful && post_residual > 0 {
        // Dead space: the smaller the gap, the more "wasted" it is.
        score += (min_useful - post_residual) as f64 * 6.0;
        // Absolute dead zones get an extra flat penalty.
        score += 15.0;
    }

    // Perfect-fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits: post_residual close to 0 is good.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this placement (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits: mild reward proportional to slack after next item.
        let after_next = post_residual - next_item_size;
        score -= 10.0 * (1.0 - after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item cannot use this residual: extra dead-space penalty.
        score += 20.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 20.0 + 8.0 * pressure + 15.0 * progress;
    } else {
        // Existing bin: reward slightly more when open_bins_count is high.
        score -= 3.0 * pressure;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight — using it is efficient consolidation.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= 2.0 * residual_gap.min(50.0);
    } else {
        // Bin is looser than average: mild penalty to prefer tighter bins.
        score += 1.0 * (-residual_gap).min(50.0);
    }

    // Small regularization against pathological scores.
    score += post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness;

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward bins that leave room for the lookahead item (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chained = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - chained / bin_capacity as f64);
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit the item.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 30.0 + 25.0 * scarcity + 20.0 * (1.0 - progress) - 0.15 * open_bins_count as f64;
        // If fit is very tight elsewhere, new bin is less attractive.
        if post_residual == 0 && item_size == bin_capacity {
            score -= 40.0;
        }
    }

    // Mild coupling with global mean residual: prefer bins near the mean (keeps balance).
    score += 0.08 * (bin_residual as f64 - mean_residual).abs();

    // Encourage filling bins fully as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual mod 25 defines "waste classes"
    let post_class = post_residual % 25;
    // Residuals in {0, 25, 50, 75} are harmonically aligned (easy to fill later)
    let aligned = (post_class == 0) as f64;
    score -= 14.0 * aligned;

    // Penalize awkward dead space: post_residual in 1..10 is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    }
    // Sweet spot residuals 25..=50 are highly reusable
    if post_residual >= 25 && post_residual <= 50 {
        score -= 10.0;
    }

    // Integer division thresholds: post_residual / 20 tier reward
    let tier = post_residual / 20;
    score -= 3.0 * tier as f64;

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Exact harmonic match bonus: post_residual - next is aligned or zero
            let gap = post_residual - next_item_size;
            if gap % 25 == 0 || gap == 0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to overshoot
            score += 4.0 + (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins cost more early when open bins are few; discourage mid-stream hoarding
        score += 18.0 + 10.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bin is wasteful
        score += mean_residual * 0.25;
        // But if item is large relative to capacity, fresh bin is fine
        score -= (item_size as f64 / cap) * 15.0;
    }

    // Mild preference for tighter bins when many bins are open (reduce fragmentation)
    score += (mean_residual - post_residual as f64) * 0.05;

    // Fraction-of-capacity fill reward: item/capacity quartile bonus
    let q = (item_size * 4) / bin_capacity;
    score -= 2.0 * q as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize very small dead space that nothing can reuse (item sizes >= 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // Mild competition bonus proportional to scarcity of alternatives.
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when the item fits poorly
    // in existing bins or open bins are nearly full.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tightness = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0
            - 25.0 * tightness
            - 10.0 * progress
            - 0.5 * open_bins_count as f64;
        // Opening a new bin is good if item is large relative to mean residual.
        if item_size as f64 > mean_residual {
            score -= 20.0;
        }
    } else {
        // Prefer filling bins that are already relatively full.
        let fullness = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * fullness;
    }

    // Global dispersion: if residuals vary a lot, favor consolidating into
    // below-mean bins to normalize future fits.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Time horizon: late in the stream, be greedier (minimize waste now).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100 domain -> assume small gap threshold)
    // are unusable dead space; penalize quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item fits almost exactly (chain-friendly).
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 8.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Open-bins pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + progress * 2.0);

    // Pull score toward mean residual context: bins far below mean residual are already tight,
    // prefer them (lower residual = tighter bin = better fit).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_base = bin_capacity as f64 - item_size as f64;
        score = new_bin_base + open_bins_count as f64 * 2.0 - 10.0;
        // If exactly one fitting bin exists, opening a new bin is rarely better.
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
        // Early stream: opening bins is cheap-ish.
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // residue classes (multiples of 10, 5, 25) are more reusable later.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr % 10 == 0 && pr > 0 {
        class_bonus += 6.0;
    } else if pr % 5 == 0 && pr > 0 {
        class_bonus += 3.0;
    }
    if pr % 25 == 0 && pr > 0 {
        class_bonus += 4.0;
    }
    // Very small dead space is excellent (near-perfect fit).
    if pr <= 2 {
        class_bonus += 25.0;
    } else if pr <= 5 {
        class_bonus += 12.0;
    } else if pr <= 10 {
        class_bonus += 5.0;
    }
    // Dead space in the awkward band 11..=19 is nearly unusable (items >= 10,
    // so only tiny items fit): penalize heavily.
    if pr >= 11 && pr <= 19 {
        class_bonus -= 15.0;
    } else if pr >= 20 && pr <= 29 {
        class_bonus -= 4.0;
    }
    score -= class_bonus;

    // Lookahead harmony: does the next item fit the post-residual?
    if next_item_size > 0 && next_item_size <= pr {
        // Exact harmonic match (pr is a multiple of next item size) is ideal.
        if pr % next_item_size == 0 {
            score -= 10.0;
        } else {
            let nxt_post = pr - next_item_size;
            if nxt_post <= 5 {
                score -= 8.0;
            } else if nxt_post <= 15 {
                score -= 3.0;
            } else {
                score -= 1.0;
            }
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here regardless; slight penalty for leaving
        // residual that nothing can chain into.
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large or current bins are mostly full / fragmented.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Prefer new bin for large items, or late in the stream when open
        // bins have low mean residual (little room left overall).
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        let new_bin_bonus = 30.0 * fill_ratio + 20.0 * mean_tightness + 10.0 * progress;
        score -= new_bin_bonus;
        // Baseline: an empty bin has residual = capacity; normalize so the
        // comparison against open bins is fair.
        score -= (bin_capacity - post_residual) as f64 * 0.0;
        score -= bin_capacity as f64 * 0.55;
    }

    // Mild preference for filling bins that are already relatively full.
    let used = bin_capacity.saturating_sub(bin_residual);
    score -= (used as f64 / bin_capacity as f64) * 4.0;

    // Slight penalty for spreading across too many open bins.
    score += (open_bins_count as f64).sqrt() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), normalized by capacity.
    score = (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Aggressive 2-step lookahead: strongly reward exact chain fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits perfectly into the resulting residual -> excellent.
            let chain = post_residual - next_item_size;
            score -= 60.0 - (chain as f64 * 0.5);
            // Perfect 2-item fill (residual fully consumed by both items).
            if chain == 0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here -> penalize dead space proportionally.
            score += (next_item_size as f64) * 0.3;
        }
    } else {
        // Last item: pure tightness fit.
        score -= 10.0;
    }

    // Reward exploiting the mean residual structure: bins with residual
    // below mean are "scarce space" bins; using them is good.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.4;
    } else {
        score += (resid - mean_residual) * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening new bin is attractive for big items late in the stream
        // with many open bins (fresh bin gives full flexibility).
        score += 55.0 - item_frac * 30.0 - progress * 10.0 - crowding * 0.5;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.15;
        }
    }

    // Mild penalty for very small leftover fragments (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Penalize dead space that is too small for typical items (unusable gap).
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 50.0;
        }
        // Non-linear penalty for large but awkward residuals.
        let pr = post_residual as f64;
        score += 0.02 * pr * pr / bin_capacity as f64;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            if gap == 0.0 {
                score -= 500.0; // perfect 2-chain
            } else {
                score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += 0.5 * (nxt - pr);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 0.0;
    }

    // Relative to mean residual: prefer bins already more filled than average.
    let pr = post_residual as f64;
    score += 0.3 * (mean_residual - pr);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // and the item is large (better to keep small residual bins for small items).
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        let pressure = if next_item_size > 0 && next_item_size >= item_size { 1.0 } else { 0.0 };
        // Default penalty; reduced when the fit elsewhere would be poor and item is big.
        score += 80.0 - 60.0 * fit_quality - 40.0 * pressure;
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // Many open bins with low mean residual => avoid spreading.
        if mean_residual > 40.0 {
            score += 30.0;
        }
    }

    // Slight preference for bins with small residual overall (best-fit flavor).
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: prefer bins where the item fills them exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins where the next item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            // Reward tight two-item packing: item + next item nearly fills the bin.
            score -= 2.5 * (next_item_size as f64);
            score -= 0.5 * (bin_capacity as f64 - leftover_after_next as f64);
            if leftover_after_next == 0 {
                score -= 400.0; // exact two-item completion
            }
        } else {
            // Next item won't fit here; penalize proportionally to the wasted gap.
            let gap = next_item_size - post_residual;
            score += 0.3 * (gap as f64);
        }
    }

    // Relative-to-mean-residual matching: prefer bins whose residual is close to
    // (but >=) the item size, i.e., tight fits relative to fleet state.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 8.0 * tightness;

    // Penalize bins much tighter than the fleet mean (they're precious small-capacity bins)
    if (bin_residual as f64) < mean_residual {
        score += 0.4 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win by default...
        score += 60.0;
        // ...but if very few bins fit, opening fresh is reasonable.
        if fitting_bins_count <= 1 {
            score -= 120.0;
        }
        // Lookahead: an empty bin can host item + next item comfortably.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 0.2 * (next_item_size as f64);
        }
    }

    // Mild early-stream preference for opening bins (build a diverse pool),
    // mild late-stream preference for consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Slight penalty when many bins are open already (consolidation pressure).
    score += 0.5 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

