pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post-residual (perfect chain), mildly when it fits.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves further residue: partial credit
            // proportional to how well it consumes the leftover space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
        } else {
            // Next item cannot use this bin's residue: penalize dead space,
            // scaled by how close the residue is to being "wasted".
            score += 100.0;
        }
    }

    // Penalize tiny unusable residues (dead space) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10 - post_residual) as f64;
    }

    // Compare against mean residual: bins with residual far below mean are
    // already tight; prefer packing into bins with larger-than-mean residual
    // to balance load across bins.
    score -= 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer reusing existing bins over opening new ones: the new-bin candidate
    // has bin_residual == bin_capacity (post_residual == 100), which should
    // score worse than a decent existing fit unless the item is huge.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Early in the stream, be more willing to open bins (cheap flexibility);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: minimize leftover space after placement.
    let mut score = post;

    // Tight-fit reward: strongly favor near-perfect fills.
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * cap * 0.6;

    // Dead-space penalty: leftover space that no future item (>=10, or >=1) can use.
    let min_item = if total_items > 0 && item_size >= 10 { 10.0 } else { 1.0 };
    if post > 0.0 && post < min_item {
        score += cap * 2.0; // unusable sliver
    } else if post > 0.0 && post < 2.0 * min_item {
        score += cap * 0.5; // hard-to-fill small gap
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 1.5;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current bins fit poorly and the item is large relative to capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = item / cap; // large items deserve a fresh bin
        let crowded = (open_bins_count as f64).ln() + 1.0;
        let mean_gap = (mean_residual - item).max(0.0) / cap;
        score += cap * (0.8 + mean_gap * 2.0) - fit_quality * cap * 1.2 + crowded * 5.0;
        // Lookahead: if next item is small, a fresh bin wastes its large residual.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let pair_fill = (item + nxt) / cap;
            if pair_fill <= 1.0 {
                score -= cap * 0.8; // fresh bin could host both items
            } else {
                score += cap * 0.4;
            }
        }
    } else if next_item_size > 0 {
        // Lookahead coupling for existing bins: reward bins whose post-residual
        // exactly accommodates the next item (chained packing).
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if diff < min_item {
            score -= cap * 1.0;
        } else {
            score += diff * 0.35;
        }
    }

    // Time horizon: early in the stream, be conservative (keep bins balanced);
    // late in the stream, prioritize immediate compaction.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - post) * (0.4 - 0.6 * progress);

    // Mild preference to fill bins with larger residuals when many bins are open.
    score -= residual / cap * (open_bins_count as f64).min(10.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (modulo arithmetic) ---
    // Residuals in "nice" classes (multiples of 10, or small enough to be
    // easily filled by typical items) are less dead; penalize awkward classes.
    let pr = post_residual;
    let class10 = pr % 10; // 0 = perfectly harmonious with decimal capacity
    let class25 = pr % 25;
    score += 0.6 * (class10 as f64) * 0.1;          // mild penalty off multiples of 10
    if class25 == 0 { score -= 1.5; }               // bonus for 25/50/75 residuals
    if pr % 20 == 0 { score -= 1.0; }               // bonus for multiples of 20
    if pr % 30 == 0 { score -= 0.8; }
    if pr % 7 == 0 && pr > 0 { score += 0.4; }      // awkward class penalty

    // Integer-division thresholds on post_residual: tiny residuals are dead space.
    if pr == 0 {
        score -= 6.0; // perfect fill: strongly preferred
    } else if pr < 10 {
        score += 8.0; // unusable dead space below min item size
    } else if pr < 20 {
        score += 2.5;
    } else if pr > 60 {
        score += 1.0; // leaving a big hole wastes the bin
    }

    // --- Lookahead coupling: does next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item chains nicely: reward, scaled by how tightly it fits.
            let tightness = 1.0 - ((pr - next_item_size) as f64) / (bin_capacity as f64);
            score -= 2.0 + 2.0 * tightness;
            // Harmonic chain bonus: next item lands post-residual on a nice class
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 1.5; }
            if pr2 == 0 { score -= 3.0; }
        } else {
            // Next item will NOT fit here: penalize, harder if residual is big.
            score += 1.0 + 0.02 * (pr as f64);
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 4.0; // only bin that fits: strongly prefer using it
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost, modulated by stream progress and load.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 12.0
            + 6.0 * progress                       // later in stream: bins already sunk cost
            - 1.5 * (open_bins_count as f64).ln().max(0.0);
        // If current item is large and would leave a bad residual elsewhere,
        // fresh bin is more attractive.
        if item_size > 70 { score -= 2.0; }
        // If mean residual across open bins is small, open bins are nearly
        // full anyway: new bin is fine.
        if mean_residual < 15.0 { score -= 2.5; }
        // If next item is large, keep open bins' space for it; new bin now is good.
        if next_item_size >= 60 { score -= 2.0; }
    } else {
        // Prefer filling existing bins when mean residual is high (avoid sprawl).
        score -= 0.03 * mean_residual;
        // Slight preference for fewer open bins (consolidation).
        score -= 0.05 * (open_bins_count as f64);
    }

    // --- Fit tightness reward: smaller post_residual relative to item is best-fit ---
    score -= 0.5 * (item_size as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here after placement; penalize proportionally
        let deficit = (next_item_size - post_residual) as f64;
        score += 8.0 + 0.15 * deficit;
    }

    // Reward tight fits relative to bin capacity (waste minimization)
    let waste_ratio = post_residual as f64 / cap;
    score += 20.0 * waste_ratio * waste_ratio;

    // Compare against mean residual across open bins: prefer bins with above-average residual
    // (consume the loosest bin first), leaving tight bins for small future items.
    if post_residual as f64 > mean_residual {
        score -= 0.25 * (post_residual as f64 - mean_residual).min(30.0);
    } else {
        score += 0.25 * (mean_residual - post_residual as f64).min(30.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 40.0; // would leave big hole in an existing bin
        if poor_fit && fitting_bins_count > 1 {
            score -= 30.0 + 10.0 * progress;
        } else {
            // discourage opening new bins otherwise
            score += 40.0 + 5.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic coupling of post residual with stream progress.
    // Late in the stream, tight fits (small post_residual) matter more.
    let mut score = x * x * (0.5 + 1.5 * progress) + x * (1.0 - progress);

    // Smooth non-linear penalty for dead space relative to mean residual of open bins.
    let dead = ((pr - mean_residual) / cap).tanh();
    score += 0.8 * dead * dead;

    // Reward last-chance bins smoothly (avoid opening new bins unnecessarily).
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - progress) * (1.0 - progress) + 1.0;
    }

    // Lookahead coupling: prefer bins whose post residual still fits the next item,
    // penalize otherwise with a smooth saturating term.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = ((pr - nxt) / cap).tanh();
            score -= 1.5 * (1.0 - slack * slack);
        } else {
            let gap = ((nxt - pr) / cap).tanh();
            score += 1.2 * gap * gap;
        }
    }

    // Mild pressure against accumulating many open bins late in the stream.
    score += 0.01 * open_bins_count as f64 * progress;

    score
}

