    // Penalize if next item would be blocked by the remaining gap.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // New empty bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 18.0 + 3.0 * open_bins_count as f64;
        // But attractive for huge items that leave little dead space.
        if item_size >= 70 {
            score -= 30.0;
        }
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: zero waste is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item's size (chain of perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item can still fit here afterwards: good, reward proportionally.
            score -= 0.5 * next_item_size as f64;
        } else {
            // Next item won't fit in the leftover: penalize dead space,
            // worse when leftover is small and unusable.
            let waste = post_residual as f64;
            score += 0.75 * waste;
        }

        // If after this placement the residual can't fit the next item AND
        // the next item is large, prefer bins where the leftover remains useful.
        if post_residual < next_item_size && post_residual > 0 {
            let tightness = post_residual as f64 / next_item_size as f64;
            score += 20.0 * (1.0 - tightness);
        }
    }

    // Compare post_residual relative to mean residual of open bins:
    // filling below-average-residual (tight) bins is preferred.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Penalize leaving large unusable gaps relative to the minimum item size (1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // tiny slivers are nearly dead space
    }

    // Early in the stream, be more willing to open/spread across bins;
    // late in the stream, pack tightly (weight residual more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: only choose a fresh bin when no open bin fits well,
    // i.e., make empty-bin score moderately high but not prohibitive.
    if bin_residual == bin_capacity {
        score += 150.0;
        // Late in the stream, opening new bins is costlier.
        score += 100.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * fill_ratio * fill_ratio;

    // Penalize large dead space relative to smallest plausible future item.
    if post_residual > 0 {
        score += 0.5 * (post_residual as f64).sqrt();
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            if post_residual == next_item_size {
                score -= 10.0; // chain fit: next item closes this bin
            }
        } else {
            score += 3.0; // dead space the known next item can't use
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fit_gap = mean_residual - item_size as f64;
        let mut new_bin_score = cap - item_size as f64; // baseline waste of fresh bin
        new_bin_score += open_bins_count as f64 * 1.5;  // mild consolidation pressure
        if next_item_size > 0 && (cap - item_size as f64) >= next_item_size as f64 {
            new_bin_score -= 4.0;
        }
        // Late in stream, prefer filling existing bins harder.
        new_bin_score += 10.0 * progress;
        // If mean residual is large, open bins are wasteful; opening new is fine.
        new_bin_score -= 0.3 * mean_residual.max(0.0);
        if avg_fit_gap < 0.0 {
            new_bin_score -= 5.0; // item doesn't fit typical open residual anyway
        }
        score = new_bin_score.max(score * 0.2);
        return score;
    }

    // Slight preference for bins below mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_norm = item_size as f64 / bin_residual.max(1) as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post-residual (tight fit)
    let mut score = post;

    // Smooth non-linear tightness reward: quadratic coupling of fit ratio with stream progress
    score -= 25.0 * (fit_norm * fit_norm) * (0.5 + 0.5 * progress);

    // Penalize dead space relative to capacity, amplified late in the stream
    let dead = post / cap;
    score += 20.0 * dead * dead * (1.0 + progress);

    // Lookahead coupling: reward if post_residual matches next item smoothly
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        let g = gap / cap;
        score += 15.0 * g * g;
        // extra reward for exact next-item fit, scaled by progress
        score -= 10.0 * (-g * g * 20.0).exp() * (0.3 + 0.7 * progress);
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (0.5 + 0.5 * progress);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.5 * open_bins_count as f64 * (post / cap);

    // Slight preference for emptier-than-mean bins early, fuller-than-mean late
    score += (mean_residual - post) * (0.4 - 0.6 * progress);

    // New-bin candidate: neutral-ish baseline with smooth decay so it loses to good fits
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual;

    // Perfect-fit reward: post_residual near zero or exactly a small harmonic divisor.
    if post == 0 {
        score -= 1000.0;
    } else if post <= eighth {
        score -= 150.0;
    } else if post <= quarter {
        score -= 40.0;
    } else {
        // Large dead space: penalize more strongly the larger it is.
        score += (post as f64) * 0.6;
    }

    // Integer division thresholds on post_residual: reward residuals that are
    // multiples of small item classes (likely reusable by future items).
    let reusable = (post % 10 == 0) || (post % 20 == 0) || (post % 25 == 0);
    if reusable {
        score -= 60.0;
    } else {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post {
        score -= 80.0;
        // Extra reward if next item nearly fills the remaining space exactly.
        let gap = post - next_item_size;
        if gap <= eighth {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's remainder: penalize dead space.
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: empty bin should only win when current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 250.0;
        // But if the current bin's post_residual is unusable for next item,
        // opening fresh is less bad.
        if next_item_size > 0 && post > 0 && next_item_size > post {
            score -= 100.0;
        }
        // Late in stream, prefer reusing open bins to avoid stranded bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 50.0;
    }

    // Tight-fit bonus: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 50.0 * fill_ratio;
    }

    // Mean residual coupling: if this bin's residual is far below mean (tight bin),
    // prefer filling it to keep many mid-size residuals available.
    let resid_gap = mean_residual - post as f64;
    if resid_gap > 0.0 {
        score -= resid_gap * 0.3;
    } else {
        score += (-resid_gap) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are unusable.
    let min_item = 1u32; // items can be as small as 1
    if post_residual > 0 && post_residual < 10 {
        // unusable dead space: heavy penalty proportional to its blocking effect
        score += 60.0 + (10 - post_residual as i32).max(0) as f64 * 8.0;
    }
    // Perfect fit is golden
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item (k=2 lookahead synergy)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Penalize if post_residual is just below the next item (near-useless gap)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Tight fit reward: fraction of bin consumed
    let fill_fraction = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_fraction;

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent
    let pressure = open_bins_count as f64 / (1.0 + total_items as f64 / 50.0);
    score += 6.0 * pressure * (1.0 - fill_fraction);

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a new bin
        score += 15.0 + 4.0 * open_bins_count as f64;
        // if current bin's post-residual is dead space, opening new bin is fine
        if post_residual > 0 && post_residual < 10 && bin_residual != bin_capacity {
            score -= 50.0;
        }
    } else {
        // prefer bins whose residual is close to mean (balance) mildly
        score += 0.05 * (bin_residual as f64 - mean_residual).abs();
    }

    // Late-stream tightening: waste less as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins where next item also fits snugly
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = (post_residual - next_item_size) as f64;
        score -= 50.0 - 0.5 * lookahead_waste;
        // bonus if pair exactly fills the bin
        if post_residual == next_item_size {
            score -= 500.0;
        }
    } else if next_item_size > 0 {
        // next item cannot follow in this bin -> penalize dead space
        score += 0.75 * post_residual as f64;
    }

    // Penalize residual far below mean residual (fragmenting a good bin)
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += 0.3 * dev;
    } else {
        score += 0.1 * dev; // slight reward for keeping above-average residual
    }

    // Last chance bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Discard new-bin option unless item is large or no good fit exists
    if bin_residual == bin_capacity {
        score += 120.0;
        if item_size >= 60 || fitting_bins_count == 0 {
            score -= 150.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Reward tight fits: penalize relative fill ratio of this bin.
    let fill = (bin_residual as f64 - post) / cap;
    score -= 25.0 * fill * fill;

    // Penalize unusable dead space: post_residual too small for any plausible item (min size 1 -> dead only if 0).
    if post_residual > 0 && post_residual < 8 {
        score += 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // next item still fits here: bonus proportional to how well it fills the remaining space.
            let nxt_fill = nxt / post.max(1.0);
            score -= 15.0 * nxt_fill;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            // blocking: residual left is too small for the next item -> penalty scaled by wasted fraction.
            let waste = post / cap;
            score += 20.0 * waste;
        }
        // Perfect chain: item + next item exactly fills the bin.
        if post_residual as f64 == nxt {
            score -= 30.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Prefer bins with smaller residual among fitting bins (best-fit bias), scaled by global state.
    let resid_frac = post / cap;
    score += 10.0 * resid_frac;

    // Global state coupling: when many bins are open and mean residual is low, consolidate;
    // when mean residual is high, be pickier about placements that leave large residuals.
    if mean_residual > 0.0 {
        let spread = (post - mean_residual) / cap;
        score += 8.0 * spread;
        if post > mean_residual {
            score += 5.0 * (post - mean_residual) / cap;
        }
    }

    // Time horizon: early in the stream, be conservative (favor new bins to keep flexibility);
    // late in the stream, squeeze everything into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if progress < 0.25 {
        if bin_residual == bin_capacity {
            score -= 10.0 * (0.25 - progress) * 4.0;
        }
    } else {
        if bin_residual == bin_capacity {
            score += 30.0 * progress;
        } else {
            score -= 20.0 * progress;
        }
    }

    // Bin-count pressure: many open bins -> discourage opening new ones.
    if bin_residual == bin_capacity {
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    // Exact fit is always ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: waste after placement, with non-linear penalty on mid-range residuals
    let mut score = pr
        + 25.0 * prn * (1.0 - prn) * 4.0 * (1.0 - progress)
        - 30.0 * prn * prn * progress;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - prn;
    score -= 40.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Lookahead coupling: quadratic interaction of post_residual with next item fit
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let reuse = 1.0 - ((pr - nx) / cap);
            score -= 20.0 * reuse * reuse * (1.0 + progress);
        } else {
            score += 10.0 * ((nx - pr) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin pressure: strong reward if this is the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (0.5 + 0.5 * progress);
    }

    // Penalize spreading across many open bins when mean residual is low
    score += 0.5 * (open_bins_count as f64).ln() * (mean_residual / cap) * (1.0 - progress);

    // New-bin candidate handling: discourage opening a new bin unless residuals are poor
    if bin_residual == bin_capacity {
        score = pr + 15.0 + 20.0 * (1.0 - progress) * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are near-perfect packings; reward them.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: post_residual divides capacity nicely (residue in {0, 5, 10, 20, 25, 50})
    let nice = [0u32, 5, 10, 20, 25, 50];
    if nice.contains(&post_residual) {
        score -= 12.0;
    }

    // Integer-division thresholds: residual quarters
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score -= 8.0; // very tight fit, excellent
    } else if post_residual <= half {
        score -= 3.0;
    } else {
        score += 4.0; // wasteful large leftover
    }

    // Modulo coupling: does post_residual align with next item's harmonic class?
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        // If next item fits exactly into post residual -> huge reward.
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            // Reward small gaps; penalize gap in awkward middle class (11..=30)
            if gap <= 10 {
                score -= 6.0;
            } else if gap <= 30 {
                score += 5.0;
            } else {
                score -= 1.0;
            }
            // Harmonic: next item divides the residual evenly
            if post_residual % next_item_size == 0 {
                score -= 7.0;
            }
        } else {
            // next item cannot fit here anyway; mild penalty for leaving big dead space
            score += pr / cap * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 20.0;
        // but if no open bin fits well, opening is fine
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
        // late in stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    // Mean-residual harmony: prefer bins close to mean residual (balanced packing)
    score += (bin_residual as f64 - mean_residual).abs() * 0.05;

    // Small constant tiebreak against many open bins
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A gap is "dead" if it's smaller than the minimum plausible item size (1),
    // but practically: gaps below ~10 waste capacity in long streams.
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    } else if post_residual > 10 && post_residual <= 20 {
        score += 15.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 40.0;

    // Open-bin pressure: when many bins are open, prefer consolidating
    // (avoid opening new bins); when few bins are open, new bins are cheaper.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only fitting bin, heavily favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: make it attractive only when current bins fit poorly
    // (large post_residual elsewhere is already penalized). Add a mild
    // exploration bonus so a fresh bin beats a bad fit but not a decent one.
    if bin_residual == bin_capacity {
        score -= 30.0;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            score -= 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 80.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Mean-residual coupling: if this bin is far below average residual,
    // it is "dying" — prefer filling it.
    if (bin_residual as f64 - mean_residual) < -10.0 {
        score -= 10.0;
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize wasted dead space non-linearly (small residuals are hard to reuse).
    let post = post_residual as f64;
    score += 12.0 / (1.0 + post / 10.0);

    // 2-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            // reward tightness of the follow-up fit
            let slack = post - next;
            score -= 20.0 - 0.5 * slack;
            if slack == 0.0 {
                score -= 15.0; // perfect 2-item pairing
            }
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += 0.15 * (next - post);
        }
    }

    // Compare against mean residual: prefer bins whose post residual stays near mean
    // (keeps a healthy spread of reusable gaps) or below it (tight fit).
    let dev = post - mean_residual;
    score += 0.25 * dev.abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score += 10.0; // last-chance bin exists; discourage new bin
        }
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for filling larger residual bins when many bins are open.
    score -= 0.05 * (bin_residual as f64 - item_size as f64).signum() * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Creating a gap that cannot fit the next item is mildly wasteful.
            score += 4.0;
            // Extra penalty if next item would need a near-full bin.
            if next_item_size + post_residual > bin_capacity {
                score += 3.0;
            }
        }
    }

    // Perfect fit celebration.
    if post_residual == 0 {
        score -= 40.0;
    }

    // New-bin candidate logic: an empty bin is a long-term resource.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early (many items remain) or when
        // open bins are already crowded on average.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowd = mean_residual / (bin_capacity as f64);
        let mut new_bin_bonus = 20.0 * (1.0 - progress);
        if item_size > 60 && crowd < 0.35 {
            new_bin_bonus += 10.0; // big item deserves fresh space
        }
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            new_bin_bonus += 5.0; // next item cannot share with this one
        }
        // Discourage opening new bins when plenty of slack exists elsewhere.
        if mean_residual > item_size as f64 + 15.0 {
            new_bin_bonus -= 12.0;
        }
        score -= new_bin_bonus;
    } else {
        // Slight preference for reusing bins with less residual overall
        // (keeps larger holes available for larger future items).
        score += 0.05 * ((bin_residual as f64) - mean_residual).max(0.0);
    }

    // Late in the stream, consolidation matters more: favor bins that close out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress > 0.8 && post_residual < 15 {
        score -= 10.0 * progress;
    }

    // Mild penalty for proliferating bins when many are already open.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: normalized post residual
    let mut score = post / cap;

    // Non-linear polynomial coupling with stream progress:
    // late in the stream, tight fits (small post_residual) become more valuable
    let tightness = 1.0 - (post / cap);
    let progress_coupling = progress * tightness * tightness;
    score -= 0.6 * progress_coupling;

    // Quadratic penalty on mid-range dead space, amplified by progress
    let dead = (post / cap) * (1.0 - post / cap);
    score += 0.4 * dead * (0.5 + progress);

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 1.5;
    }

    // New bin candidate: penalize mildly, less so late when residuals fragment
    if bin_residual == bin_capacity {
        score += 0.35 - 0.2 * progress;
    }

    // Lookahead coupling: if next item fits post_residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 0.3 * (1.0 - (next_item_size as f64 / cap)) * (0.5 + progress);
    } else if next_item_size > 0 {
        // next item cannot follow: penalize wasting residual
        score += 0.15 * progress;
    }

    // Smooth coupling with mean residual state
    score += 0.1 * (post - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual (mod arithmetic) ---
    // Residuals that fall into "useful" small classes are less penalized.
    let cap = bin_capacity as f64;
    let pr = post_residual as u32;

    // Perfect-fit reward: zero dead space is ideal.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Modulo classes: residuals divisible by common small item sizes (10,20,25)
        // remain "harmonically usable" by future items; penalize odd/prime-like leftovers.
        let harmonic_bonus = if pr % 10 == 0 {
            12.0
        } else if pr % 5 == 0 {
            6.0
        } else if pr % 25 == 0 {
            10.0
        } else {
            0.0
        };
        score -= harmonic_bonus;

        // Fractional capacity classes: post_residual as a fraction of capacity.
        let frac = pr as f64 / cap;
        if frac < 0.10 {
            // Tiny leftover: bin is effectively closed, small reward.
            score -= 8.0;
        } else if frac < 0.30 {
            // Dangerous mid zone: dead space that few items can use.
            score += 10.0 * (0.30 - frac);
        }

        // Integer-division threshold: how many size-10 slots remain.
        let slots = pr / 10;
        score -= slots as f64 * 1.5;
    }

    // --- Lookahead coupling (k=2) ---
    if next_item_size > 0 && pr >= next_item_size {
        // Next item fits exactly in the leftover: strong pairing reward.
        let slack = (pr - next_item_size) as f64;
        if slack == 0.0 {
            score -= 500.0;
        } else if slack <= 10.0 {
            score -= 40.0;
        } else {
            score -= 15.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize proportional waste.
        score += (next_item_size as f64).min(40.0) * 0.5;
    }

    // --- Last-chance bin pressure ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        // This is the only open bin that fits; strongly prefer using it
        // over opening a new bin.
        score -= 60.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin should only win for large items or when no
        // open bin fits; make it expensive by default.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / cap;
        if fitting_bins_count == 0 {
            // No alternative: new bin is fine.
            score -= 50.0;
        } else {
            // Prefer existing bins unless item is huge and bins are fragmented.
            score += 80.0 - 30.0 * item_frac - 20.0 * progress;
        }
    }

    // --- Mild tie-breaking by fragmentation of the fleet ---
    score += (open_bins_count as f64) * 0.05 + (mean_residual - post_residual as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space too small for any item: penalize quadratically.
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 4.0;
    }

    // Reward tight fits (small relative waste).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - waste_ratio) * 20.0;

    // Open-bin pressure: discourage spreading when many bins are open,
    // encourage consolidation into fewer bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise we must open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it moderately attractive only when the item
    // would leave a bad fit elsewhere or few fitting bins exist.
    if bin_residual == bin_capacity {
        score = 55.0 + waste_ratio * 10.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        if post_residual >= 10 {
            score -= 15.0; // roomy new bin keeps flexibility
        }
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
        // Extra reward if next item then fits almost perfectly.
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post-residual unusable for the known next item: penalize.
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (fill fuller bins first, keep emptier bins flexible).
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // Late-stream tightening: as the stream progresses, be stricter about waste.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += waste_ratio * 30.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: this bin absorbs the item
    // and the next item exactly fills the remainder.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }

    // Partial lookahead reward: next item still fits after this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0;
        // Prefer bins where the leftover after the next item is small
        // (tight 2-step packing chain).
        let after_next = post_residual - next_item_size;
        score -= 20.0 * (1.0 - after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalty proportional to lookahead mismatch: dead space the next
        // item cannot use.
        let gap = (next_item_size as f64 - post_residual as f64).abs();
        score += 0.5 * gap;
    }

    // Reward tight fits relative to current item (small post_residual good,
    // but avoid near-zero unusable slivers unless next item is tiny).
    let pr = post_residual as f64;
    if pr > 0.0 && pr < 10.0 {
        // sliver penalty: space likely wasted
        score += 25.0 * (10.0 - pr) / 10.0;
    }

    // Compare against mean residual: bins with residual close to item size
    // are ideal targets; far-above-mean bins should be preserved for
    // larger future items.
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize so we only open a new bin
    // when no open bin offers a decent fit; relax the penalty late in the
    // stream and when many bins are already open (spreading load).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let base = 60.0;
        let spread_bonus = 5.0 * open_bins_count as f64;
        let lookahead_bonus = if next_item_size > 0 && next_item_size <= bin_capacity {
            0.3 * next_item_size as f64
        } else {
            0.0
        };
        score += base + spread_bonus + lookahead_bonus - 20.0 * progress;
        // Perfect 2-step chain starting a fresh bin is also fine.
        if next_item_size > 0 && item_size + next_item_size == bin_capacity {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    score += 0.6 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Reward exact or near-exact fits heavily.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size < post_residual {
            // next item fits but leaves leftover: mild reward proportional to resulting tightness
            let nxt_left = pr - nr;
            score -= 8.0 * (1.0 - nxt_left / bin_capacity as f64);
            score += 0.3 * nxt_left;
        } else {
            // next item cannot fit here: slight penalty scaled by how much it misses
            score += 0.15 * (nr - pr);
        }
    }

    // Last-chance bin: this is the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening new bins when good alternatives exist.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of consuming a fresh bin.
        score += 35.0;
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If current item would leave awkward dead space in any bin, new bin more attractive
        // for large items; less so for small items.
        score += 0.1 * item_size as f64;
        // Few open bins -> more willing to open (spread load early).
        score -= 3.0 * (open_bins_count as f64).min(10.0);
        // If the mean residual is small (bins nearly full), opening a new bin is reasonable.
        score -= 0.2 * mean_residual;
        // If next item is large and no bin will hold both, prefer new bin.
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 15.0;
        }
    } else {
        // Slight preference for reusing bins that are already partially filled,
        // scaled by how full the bin already is (fragmentation avoidance).
        let used = (bin_capacity - bin_residual) as f64;
        score -= 0.05 * used;
        // Prefer bins whose residual is close to mean residual (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Global pressure: many open bins -> discourage spreading, favor tight fills.
    if open_bins_count > 8 {
        score += 0.4 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: quadratic coupling of post-residual with stream progress.
    // Early: prefer tight fits (low post residual). Late: allow more slack.
    let mut score = pr * (0.9 + 0.6 * progress) - 30.0 * x * (1.0 - x) * (1.0 - progress);

    // Smooth non-linear interaction: reward filling when few fitting bins exist.
    let scarcity = 1.0 / (fitting_bins_count as f64);
    score -= 12.0 * scarcity * (item_size as f64 / cap) * (1.0 - x);

    // Penalize leaving dead space smaller than the smallest plausible item (<= ~10% cap)
    // via a smooth bump centered at small x, weighted by progress.
    let dead = ((x - 0.1) / 0.1).powi(2);
    score += 15.0 * (-dead).exp() * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits in post residual, reward strongly (smooth gate).
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as i32 as f64;
        let margin = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 20.0 * fits * margin.max(0.0) * (1.0 - 0.5 * progress);
    }

    // Mild penalty for spreading across many open bins when mean residual is low.
    score += 0.05 * (open_bins_count as f64) * (mean_residual / cap).powi(2) * progress;

    // New-bin candidate: make empty bin attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - scarcity) + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect-fit classes get strong rewards.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward near-zero post residual (tight fit).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 12 {
        score -= 60.0;
    }

    // Modulo-10 harmonic classes: residuals that are multiples of 10 remain
    // "usable" by the common item-size grid; penalize odd/dead classes.
    let r10 = post_residual % 10;
    if r10 == 0 {
        score -= 25.0;
    } else if r10 >= 7 {
        score += 10.0;
    }

    // Small residuals below the minimum item size are dead space.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0;
    }

    // Integer-division threshold: residual usable by next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
            // exact fit for lookahead item is excellent
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            score += 30.0 * (1.0 - post / cap);
        }
    } else {
        // last item: prefer any fit, tightest wins
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Prefer filling bins that are already relatively full (low residual),
    // best-fit style, scaled by how many bins compete.
    let fullness = 1.0 - (bin_residual as f64) / cap;
    score -= 20.0 * fullness;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 45.0 * pressure;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 20.0; // saving space for a bigger next item
        }
    }

    // Slight preference to spread load when many bins open and mean residual high.
    if open_bins_count > 2 && mean_residual > 40.0 {
        score += 5.0;
    }

    // Progress factor: later in stream, tighten packing more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fullness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (below min item size 1, but practically
    // below typical item sizes) are nearly unusable. Penalize non-linearly.
    if post_residual > 0 {
        // gap below 10 is dead space (interface min item = 1, but be conservative)
        if post_residual < 10 {
            score += 60.0;
        } else if post_residual < 20 {
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
        // prefer residual that could fit the lookahead item
        if next_item_size > 0 {
            if post_residual >= next_item_size {
                score -= 6.0;
            } else {
                score += (next_item_size - post_residual) as f64 * 0.3;
            }
        }
    } else {
        // perfect fit: strong reward
        score -= 40.0;
    }

    // Tightness reward: filling the bin well
    score -= (item_size as f64 / bin_capacity as f64) * 15.0;

    // Open bins pressure: with many open bins, favor consolidating into existing ones
    // (penalize the new-bin candidate relatively more when many bins are open).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (3.0 + 5.0 * progress);
    if bin_residual == bin_capacity {
        // new bin candidate
        score += 20.0 + pressure;
        // but if no open bin fits well (this is the only fitting candidate and fit is poor),
        // opening a new bin is fine — soften penalty
        if fitting_bins_count <= 1 && post_residual > 0 && (post_residual as f64) < 10.0 {
            score -= 25.0;
        }
    } else {
        // existing bin: reward when it's the last chance (avoid opening a bin)
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // slight reward for using bins with small residuals relative to mean
        score -= (mean_residual - bin_residual as f64) * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: zero dead space is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins whose post_residual matches the next item exactly.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.8 * gap; // penalize mismatch with next item
        if post_residual == next_item_size {
            score -= 300.0; // exact 2-step chain: perfect fill next round
        }
        // Penalize leaving dead space that the next item cannot use.
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // Penalize opening a new bin when good fitting bins exist.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 150.0;
        // Allow new bin only if lookahead chains well into a fresh bin.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 100.0;
        }
    }

    // Slight preference for tighter fills overall.
    score += 0.2 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual non-linearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize leaving dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
    }
    // Reward leaving room exactly for the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }
    // Reward reserving space for a smaller-or-equal next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // Many alternatives: mild penalty to preserve flexibility elsewhere.
    if fitting_bins_count > 3 {
        score += 3.0;
    }

    // Time horizon: early in the stream, be conservative about opening new bins;
    // late in the stream, prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0 * (bin_residual as f64 / bin_capacity as f64);
    score += progress * 2.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state coupling: if mean residual is high, prefer filling bins
    // that are below-average full (consolidate); if low, chase tight fits.
    let mean_gap = mean_residual - bin_residual as f64;
    score += 0.05 * mean_gap;

    // Penalize opening new bins when open bins exist and fit well.
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let new_bin_penalty = 30.0
            + 5.0 * (open_bins_count as f64)
            - (1.0 - fit_ratio) * 10.0;
        score += new_bin_penalty;
        // Allow a new bin if item is huge relative to mean residual of open bins.
        if (item_size as f64) > mean_residual + 20.0 {
            score -= 25.0;
        }
    }

    // Bonus for near-perfect packing (residual in the awkward 1..10 band is bad).
    if post_residual >= 1 && post_residual <= 9 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = pr / cap;

    let mut score = pr;

    // Non-linear waste penalty: quadratic in normalized post residual
    score += 30.0 * fit_ratio * fit_ratio;

    // Reward tight fits (small post residual) more strongly later in stream
    let tightness = 1.0 - fit_ratio;
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += 20.0 * (next_item_size as f64 - pr) / cap;
    } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 10.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: prefer using a nearly-full bin before opening new ones
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: make it costly unless the item truly fits poorly elsewhere
    if bin_residual == bin_capacity {
        score = pr + 60.0 * (1.0 - progress) + 0.5 * mean_residual;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the residual: classify post_residual into capacity fractions.
    let cap = bin_capacity as f64;
    let quarter = (bin_capacity / 4) as f64;
    let half = (bin_capacity / 2) as f64;

    // Perfect fit: near-zero post residual is excellent.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    } else {
        // Dead-space penalty: residuals that no future item (1..=100) can use
        // are worse than small usable slivers. Penalize "orphan" classes.
        let r = post_residual;
        // modulo-10 harmonic classes: residuals that are multiples of 10 are
        // reusable by typical item granularities.
        if r % 10 == 0 {
            score -= 6.0;
        }
        // penalize residuals in awkward bands (just above half, just above quarter)
        let rf = r as f64;
        if rf > half && rf < half + quarter * 0.5 {
            score += 8.0; // 51..62 dead-ish zone
        }
        if rf > quarter && rf < quarter * 1.5 {
            score -= 3.0; // 26..37 reasonably reusable
        }
        if rf < quarter {
            score -= 4.0 * (1.0 - rf / quarter); // smaller sliver = better
        }
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; slight penalty proportional to overflow gap
            score += 2.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it over
    // opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 12.0;
    }
    // Many fitting bins: encourage tightest fit implicitly via post_residual,
    // but add mild penalty proportional to open bins to discourage bin sprawl.
    score += 0.15 * open_bins_count as f64;

    // Progress term: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / cap);

    // Compare against mean residual: bins far below mean residual are already
    // tight; favor them slightly.
    score += 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate: empty bin has full residual. Make it unattractive
    // unless the item is huge (would leave unusable space anywhere) or no
    // real alternative. post_residual == cap means brand-new bin.
    if post_residual == bin_capacity {
        score += 15.0;
        // but if item is large (> 3/4 capacity), a fresh bin is fine
        if (item_size as f64) > 0.75 * cap {
            score -= 18.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: overwhelmingly reward zero dead space.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized.
    if post_residual > 0 && post_residual <= 12 {
        score += (13.0 - post_residual as f64) * 25.0;
    }

    // Lookahead (k=2): reward bins whose post_residual can host the next item;
    // penalize gaps that strand the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= next_item_size as f64 * 0.8;
        } else if post_residual > 0 {
            score += 20.0;
        }
    }

    // Last-chance bin: strongly favor it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize via open_bins_count pressure, but relax
    // proportionally for large items that would leave a tight residual anyway.
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 30.0 + 40.0;
        score -= item_size as f64 * 0.5;
    }

    // Mild pressure toward bins tighter than the current mean residual.
    score += (mean_residual - bin_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
