pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that becomes unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Lookahead coupling: reward if next item fits into post_residual.
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0 * (1.0 - (post_residual as f64 + 1.0) / (next_item_size as f64 + 1.0));
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when existing bins are crowded
    // or the fit into any open bin would be poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = mean_residual / bin_capacity as f64;
        let poor_fit_elsewhere = fit_ratio < 0.9;
        if crowding < 0.35 && poor_fit_elsewhere {
            score -= 25.0 + 10.0 * progress;
        } else {
            score += 40.0;
        }
    }

    // Global state: many open bins with small residuals -> prefer consolidation.
    if open_bins_count > 4 && bin_residual < mean_residual {
        score -= 5.0;
    } else if open_bins_count > 4 && bin_residual > mean_residual {
        score += 3.0;
    }

    // Time horizon: early in the stream, be pickier about tight fits; later,
    // accept decent fits to close bins out.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Smooth non-linear coupling: polynomial terms in normalized residual and progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let n2 = norm_pr * norm_pr;

    // Early stream: prefer tight fits (low post_residual) mildly; late stream: strongly penalize waste
    score += 40.0 * n2 * (0.5 + p2);
    score -= 30.0 * progress * n2 * (1.0 - norm_pr);

    // Perfect fit reward, stronger late in stream
    let fit_bonus = if pr == 0 { 120.0 } else { 0.0 };
    score -= fit_bonus * (0.6 + 0.8 * progress);

    // Near-perfect fit (residual < smallest possible item ~1): smooth reward via cubic falloff
    score -= 60.0 * (1.0 - norm_pr).powi(3) * (0.4 + 0.6 * progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 70.0 * (1.0 + progress);
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        if next_item_size as f64 <= pr {
            score -= 35.0 * (1.0 - diff / cap) * (0.5 + progress);
        } else {
            score += 15.0 * progress;
        }
    }

    // Many open bins: encourage consolidation into existing bins (penalize spreading)
    score += (open_bins_count as f64).ln().max(0.0) * 6.0 * norm_pr * (0.3 + p3);

    // Penalize new-bin opening mildly, more so early (bins get reused later)
    if bin_residual == bin_capacity {
        score += 25.0 * (1.2 - progress) + 10.0 * (open_bins_count as f64).sqrt();
    }

    // Dead-space penalty: residual too small for typical future items, smoothed
    score += 20.0 * (1.0 - norm_pr * 4.0).max(0.0) * norm_pr * (1.0 - progress);

    // Mild tie-break toward bins with low mean residual spread (tighter packing)
    score -= 5.0 * (mean_residual / cap) * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity-fraction classes. Leftovers in low classes (tiny slivers) are
    // dead space -> penalize; leftovers that are large chunks are reusable.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post = post_residual as f64;

    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual <= eighth {
        // Unusable sliver (<=12): dead space penalty.
        score += 25.0 + (eighth - post_residual) as f64;
    } else if post_residual <= quarter {
        // Small leftover (13..25): only useful for tiny items; mild penalty.
        score += 8.0;
    } else if post_residual <= 2 * quarter {
        // Mid leftover (26..50): decent reusable chunk; mild reward.
        score -= 6.0;
    } else {
        // Large leftover (>50): bin still very open; reward.
        score -= 12.0;
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // reward heavily; if next item fits, mild reward; if it cannot fit,
    // penalize slightly (this bin becomes dead for the next step).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: opening a new bin should only win when no open bin
    // offers a good fit. Penalize the fresh bin, scaled by how many bins
    // could otherwise fit the item and by mean residual availability.
    if bin_residual == bin_capacity {
        score += 55.0 + 2.0 * fitting_bins_count as f64
            + (mean_residual / 10.0).min(20.0);
    }

    // Fraction-of-capacity coupling: reward bins whose fill ratio crosses
    // harmonic thresholds (>= 1/2, >= 3/4 full).
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    if fill >= 0.75 {
        score -= 10.0;
    } else if fill >= 0.5 {
        score -= 4.0;
    }

    // Late in the stream, prefer closing bins out (lower post residual
    // relatively more) to avoid straggler bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward residuals that can host the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // dead space relative to next item
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when this placement would create dead space
    // or when open bins are already tight.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual > 0 && post_residual < 10 { 30.0 } else { 0.0 };
        score += 15.0 + open_bins_count as f64 * -0.5 + dead_space_penalty;
        // opening a bin is fine if current bin would leave tiny unusable gap
        if post_residual > 0 && post_residual < 10 {
            score -= 40.0;
        }
    }

    // Mild pressure: prefer filling existing bins when many are open.
    score += open_bins_count as f64 * 0.3;

    // Prefer bins with residuals close to item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 5.0;

    // Late in stream, be more aggressive at avoiding new bins.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual != bin_capacity {
            score -= progress * 4.0;
        }
    }

    // Slight preference for bins below mean residual (consolidating space).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- 2-step lookahead core: does the NEXT item fit the leftover? ---
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            // Reward exact / tight 2-step chains strongly.
            let tightness = 1.0 - ((post_residual as f64) - nxt) / (bin_capacity as f64);
            score -= 40.0 + 30.0 * tightness * tightness;
            // Perfect chain (post_residual == next_item_size) is ideal.
            if post_residual == next_item_size {
                score -= 50.0;
            }
        } else if next_item_size <= bin_residual && post_residual < next_item_size {
            // Next item fits the bin NOW but not after this placement:
            // penalize proportionally to how much we "steal" its space.
            let stolen = (next_item_size - post_residual) as f64;
            score += 15.0 + 0.5 * stolen;
        }
    }

    // --- Waste shaping relative to mean residual ---
    let pr = post_residual as f64;
    if pr < mean_residual {
        // Creating below-average residual: penalize dead space if unusable.
        if next_item_size > 0 && (post_residual as f64) < (next_item_size as f64) {
            score += 0.6 * (mean_residual - pr);
        }
    } else {
        // Keeping residual above the mean is mildly good (flexibility).
        score -= 0.2 * (pr - mean_residual);
    }

    // --- Last-chance bin: strongly prefer using it before opening new ---
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when nothing fits well:
        // costly if other bins can fit the item.
        score = 120.0 + (fitting_bins_count as f64) * 25.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        // If next item is small enough to share a fresh bin chain, soften.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0;
        }
    }

    // Small tie-break: prefer fuller bins (smaller residual) generally.
    score += 0.05 * (bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

