            score -= 10.0;
        } else {
            // Next item won't fit here; penalize leaving awkward leftover.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; cheaper early, costlier late.
        score = bin_capacity as f64 * (1.0 - 0.3 * progress) + 15.0;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score += 20.0; // a last-chance bin exists, prefer using it
        }
        // If open bins are on average quite full, opening fresh is reasonable.
        if mean_residual < item_size as f64 {
            score -= 10.0;
        }
    }

    // Mild preference to fill fuller bins when many bins are open.
    if open_bins_count > 4 {
        score -= (bin_capacity - bin_residual) as f64 * 0.1;
    }

    // Tie-breaker: prefer bins whose residual is close to mean residual (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, mildly de-emphasized early, emphasized late
    let mut score = pr * (0.8 + 0.4 * progress);

    // Non-linear polynomial coupling between normalized post_residual and progress
    let t = norm_pr;
    let p = progress;
    score += cap * (t * t * (1.0 - t)) * (0.5 + 1.5 * p * p);
    score += cap * (t * t * t) * (0.3 * p);

    // Penalize dead space that cannot fit the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap > 0.0 {
            let g = gap / cap;
            score += cap * g * g * (1.0 + p);
        } else {
            // reward bins that can also host the lookahead item
            score -= 4.0 + 6.0 * p;
        }
    } else {
        // last item: prefer tightest fit strongly
        score -= 10.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 10.0 * p;
    }

    // Mild preference for bins below mean residual (consolidating emptier bins)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening a bin unless residuals are getting fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).max(0.0).min(1.0);
        score += 6.0 - 8.0 * fragmentation * fragmentation - 4.0 * p;
    }

    // Slight tie-break toward bins with more remaining relative space when many bins open
    score += 0.02 * (open_bins_count as f64) * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize capacity into eighths.
    let eighth = bin_capacity as f64 / 8.0;
    let class = (post_residual as f64 / eighth).floor() as i32;

    // Dead-space penalty grows superlinearly for mid-class residuals
    // (residuals that are too big to waste but too small to be useful).
    let mid_class = (class >= 2 && class <= 5) as i32 as f64;
    score += mid_class * (post_residual as f64 * 0.35);

    // Perfect or near-perfect fit reward (post_residual in lowest harmonic class).
    if class <= 1 {
        score -= 25.0;
    }

    // Integer-division harmonic: exact fill when post_residual divides capacity cleanly.
    if post_residual > 0 && bin_capacity % post_residual == 0 {
        score -= 12.0;
    }

    // Lookahead: reward if next item fits exactly in post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a small stranded residual.
            if post_residual < next_item_size && post_residual > 0 {
                score += post_residual as f64 * 0.5;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + item_size as f64 * 0.2;
    }

    // New-bin candidate: keep it attractive only when open bins are crowded
    // or the fit here is poor. Penalize opening bins early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
        let poor_fit = (item_size as f64 / bin_capacity as f64) < 0.5;
        let mut new_bin_score = 55.0 * crowded + 30.0 * progress;
        if poor_fit { new_bin_score -= 20.0; }
        if fitting_bins_count <= 1 { new_bin_score += 40.0; }
        score = score.min(new_bin_score) * 0.5 + new_bin_score * 0.5;
        if !poor_fit && fitting_bins_count > 1 { score += 25.0; }
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already well-filled; reward finishing it off.
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score -= (dev * 0.1).min(10.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit: extremely desirable.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: small unusable gaps (1..=12) are heavily penalized,
    // with the worst zone around residual 1..=6.
    if post_residual > 0 && post_residual <= 12 {
        let depth = 12.0 - post_residual as f64; // 0..12
        score += depth * depth * 4.0;
    }

    // Post-residual that cannot fit even the smallest plausible item (<=10) is dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward leaving room for the lookahead item (good chaining).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + next_item_size as f64 * 0.5;
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize moderately to prefer bins that chain.
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bins pressure: with many open bins, discourage opening yet another bin.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: slightly above a well-packed existing bin.
        score += open_bins_count as f64 * 5.0 + mean_residual * 0.3;
        // Opening a new bin is fine early in the stream, worse later.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 30.0;
    } else {
        // Prefer tighter existing bins when several fit (best-fit coupling).
        score -= (bin_capacity - bin_residual) as f64 * 0.2;
    }

    // Mild bonus for bins already below mean residual (consolidating fragmentation).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with mild non-linearity
    score += 0.15 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64);

    // 2-step lookahead: reward exact match of post_residual to next item size
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if post_residual == next_item_size {
            // Perfect chain: this bin will be exactly filled by the next item
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item can also fit here; reward proportional closeness
            let gap = pr - nr;
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
            // Penalize leaving space that is awkward relative to next item
            score += 0.10 * gap;
        } else {
            // Next item cannot use the leftover: penalize dead space
            let dead = nr - pr;
            score += 0.20 * dead;
            // Extra penalty if the dead space is large but nonzero
            if pr > 0 && pr < 10 {
                score += 12.0;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far from mean are less flexible
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are fragmented (high mean residual) or late in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 85.0
            + 0.35 * mean_residual
            + 10.0 * progress
            + (open_bins_count as f64).sqrt() * 4.0;
        // If next item is huge, a fresh bin is a safe host for it later
        if next_item_size >= 70 {
            score -= 15.0;
        }
        // Never open a new bin when a perfect lookahead chain exists elsewhere;
        // that is handled by the -60 above, but keep new bin from ever winning
        // when this bin itself could chain perfectly.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 20.0;
        }
    }

    // Late-stream consolidation: near the end, avoid leaving many small residuals
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.85 && post_residual > 0 && post_residual < 10 {
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize progress through the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness: reward high fill ratio of the bin after placement
    let fill_after = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 2.5 * fill_after;

    // Penalize dead space that no plausible item can use.
    // Items are >= 1, but small residuals are hard to fill: quadratic penalty on tiny post-residuals.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 1.5 * dead * dead * 100.0 / 100.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strongly favor this bin
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size < post_residual {
            // next item fits: mild reward proportional to how well it fills leftover
            let nxt_fill = next_item_size as f64 / post_residual as f64;
            score -= 4.0 * nxt_fill;
        } else {
            // next item won't fit here: penalize proportionally to the waste gap
            let gap = (next_item_size - post_residual) as f64;
            score += 0.03 * gap;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // With many options, prefer tighter competition: slight penalty per extra option
        score += 0.4 * (fitting_bins_count as f64 - 1.0);
    }

    // Global state coupling: prefer bins with residuals close to the mean residual
    // (keeps bin pool homogeneous, preserves extreme bins for awkward items)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Time horizon: early in the stream, opening new bins is cheap (future items can fill them);
    // late in the stream, consolidate aggressively into open bins.
    let consolidation = progress * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, costly late
        score += consolidation;
        score -= 2.0 * (1.0 - progress);
        // If next item is large and this bin is empty, an empty bin is flexible
        if next_item_size > bin_capacity / 2 {
            score -= 3.0;
        }
    } else {
        // Existing bin: reward grows as stream progresses
        score -= consolidation * 0.5;
    }

    // Many open bins: encourage closing them out by filling them
    score += 0.15 * open_bins_count as f64 * (1.0 - progress);

    // Exact fit bonus
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let item = item_size as f64 / cap;
    let next = next_item_size as f64 / cap;

    // Base: quadratic penalty on post_residual (dead space), smoothed by progress
    let mut score = norm_pr * norm_pr * (1.0 + progress) * cap;

    // Smooth cubic coupling of post_residual with stream progress
    score += norm_pr.powi(3) * (0.5 + progress) * cap;

    // Reward tight fits: subtract a smooth function of item fraction
    score -= (item * (1.0 - item)) * (2.0 + 2.0 * progress) * cap;

    // Lookahead coupling: smooth interaction between post_residual and next item size
    let gap = norm_pr - next;
    score += gap * gap * (1.0 + 2.0 * progress) * cap * 0.5;

    // Last-chance bonus: smooth exponential reward when this bin is the only fitting one
    if fitting_bins_count == 1 {
        score -= 4.0 * cap * (1.0 - norm_pr);
    }

    // Slight preference for bins below mean residual (consolidation), smooth in progress
    score += (norm_pr - mean_residual / cap) * (1.0 + progress) * cap * 0.25;

    // Penalize spreading across many bins smoothly as stream progresses
    score += (open_bins_count as f64).ln1p() * norm_pr * cap * 0.1 * (1.0 + progress);

    // New-bin candidate: make it mildly unattractive unless post_residual is huge
    if bin_residual == bin_capacity {
        score += cap * (0.6 + 0.4 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space into
    // capacity-fraction bands. Leftovers in "awkward" bands get penalized.
    let half = bin_capacity / 2;
    let third = bin_capacity / 3;
    let quarter = bin_capacity / 4;

    if post_residual == 0 {
        // Perfect closure — strongly reward.
        score -= 1000.0;
    } else if post_residual < quarter {
        // Tiny dead space: nearly useless leftover.
        score += 40.0 * (quarter - post_residual) as f64 / quarter as f64;
    } else if post_residual < third {
        // Small leftover band.
        score += 10.0;
    } else if post_residual == half {
        // Exactly half full: ideal reusable state.
        score -= 60.0;
    } else if post_residual < half {
        // Mid band: moderately reusable.
        score -= 15.0;
    } else {
        // Large leftover: fine, stays flexible.
        score -= 5.0;
    }

    // Modulo-arithmetic coupling: leftover that is a multiple of common
    // item granularities is more likely to be filled later.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 5 == 0 && post_residual % 10 != 0 {
        score -= 3.0;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // this is a perfect pairing — reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0;
        } else if next_item_size <= post_residual {
            // Next item fits: leftover quality matters less.
            score -= 20.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item will NOT fit here: if this is the last fitting bin,
            // penalize blocking ourselves.
            if fitting_bins_count == 1 {
                score += 25.0;
            }
            // If next item is large and this bin would be left with a
            // residual smaller than typical items, penalize.
            if post_residual < 20 && next_item_size > 50 {
                score += 15.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate (empty bin): only prefer opening a new bin when
    // the item is large and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        if item_size > half {
            // Large item into fresh bin is natural.
            score -= 30.0;
        } else {
            // Small item into a fresh bin wastes capacity.
            score += 150.0;
        }
        // Early in the stream, having few bins makes fresh bins cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 20.0;
    }

    // Congestion control: many open bins with high mean residual means we
    // are spreading too thin; prefer tightening existing bins.
    if mean_residual > half as f64 && open_bins_count > 3 {
        score += 5.0 * (mean_residual - half as f64) / half as f64;
    }

    // Prefer filling bins that are already more than half consumed.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += (11.0 - post_residual as f64) * 8.0;
    }
    // Mid-range gaps that almost certainly can't host future items (items >= 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap <= 10 {
            score -= 35.0 - gap as f64;
        } else {
            score -= 10.0;
        }
    }
    // Penalize leaving a gap the next item cannot use at all.
    if next_item_size > post_residual && post_residual > 0 {
        score += 15.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + progress * 2.0);

    // New-bin candidate handling: make fresh bins attractive only when
    // existing bins would create dead space or mean residual is low.
    if bin_residual == bin_capacity {
        let dead_space_risk = if post_residual > 0 && post_residual < 10 { 60.0 } else { 0.0 };
        score -= 25.0 - dead_space_risk;
        score += mean_residual * 0.3; // if open bins have lots of room, prefer them
    }

    // Prefer bins whose residual is close to mean residual (balance spreading).
    score -= (mean_residual - bin_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    let mut score = post;

    // Perfect lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0 + 40.0 * (1.0 - progress);
    }
    // Near-match: next item fits with small slack.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post - nxt;
        score -= 30.0 * (1.0 - slack / cap) * (1.0 - 0.5 * progress);
    } else if next_item_size > 0 && post_residual > 0.0 {
        // Dead space: next item cannot use the leftover.
        score += 25.0 * (1.0 - post / cap);
    }

    // Reward tight fits relative to mean residual across open bins.
    if post < mean_residual {
        score -= (mean_residual - post).min(30.0);
    } else {
        score += (post - mean_residual).min(30.0) * 0.5;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin offers a decent
    // lookahead fit, or when many bins are open and residuals are fragmented.
    if bin_residual == bin_capacity {
        let good_lookahead = next_item_size > 0 && post_residual >= next_item_size;
        if fitting_bins_count > 0 && good_lookahead {
            score += 80.0; // keep using existing bins when lookahead is good
        } else if fitting_bins_count == 1 {
            score += 20.0; // mild penalty; last-chance bin usually wins
        } else if open_bins_count > 0 {
            score -= 10.0 + 5.0 * (open_bins_count as f64).sqrt().min(5.0);
        }
        // Prefer opening new bins early in the stream.
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: strongly reward near-perfect fits (small dead space).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tightness * tightness * item_size as f64;

    // Lookahead: if the next item can fit into the post residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let pair_waste = (post_residual - next_item_size) as f64;
            score -= 2.0 * (1.0 - pair_waste / bin_capacity as f64);
        } else {
            // Next item won't chain here; penalize leaving a medium unusable gap.
            if post_residual > 0 && post_residual < next_item_size {
                score += 0.5 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Fragmentation penalty: penalize bins whose residual deviates far from the mean residual
    // (keeps the pool of open bins homogeneous and combinable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate handling: only prefer a fresh bin when no open bin fits well
    // or the item leaves a very poor residual in existing bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with stream progress and open-bin count.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 + 2.0 * progress + 0.3 * open_bins_count as f64;
        // If the item perfectly fills a fresh bin, opening is cheap.
        if post_residual == 0 {
            score -= 8.0;
        }
        // If next item is large and this item is small, opening a new bin preserves big residuals.
        if next_item_size > post_residual + item_size && item_size < bin_capacity / 3 {
            score -= 3.0;
        }
    } else {
        // Slight reward for using existing bins early (keeps bin count low).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 1.0 + progress;
    }

    // Exact-fill bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Penalize very small leftover slivers that no realistic item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + progress * (1.0 - norm_pr)) * (1.0 - progress + (progress * progress) * 0.5);
    score += 40.0 * poly;
    // Reward tight fits, scaled smoothly by progress
    let tightness = 1.0 - norm_pr;
    score -= 60.0 * tightness * tightness * (1.0 + progress);
    // Penalize dead space that cannot fit typical future items
    let dead = norm_pr * norm_pr * norm_pr;
    score += 25.0 * dead * (0.5 + progress);
    // Last-chance bin: strong reward, modulated by progress
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - progress * 0.3);
    }
    // Many open bins: mild penalty to prefer consolidation
    score += (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - norm_pr);
    // Lookahead: favor bins whose post_residual still fits the next item
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 12.0 * (1.0 - progress * 0.5);
    } else if next_item_size > 0 {
        score += 6.0 * (1.0 - norm_pr) * progress;
    }
    // Mean residual coupling: prefer bins near mean to keep balance
    let dev = (pr - mean_residual).abs() / cap;
    score += 8.0 * dev * dev;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual (mod-10 buckets): penalize "awkward" classes.
    let class = (post_residual % 10) as f64;
    score += class * 0.8;

    // Integer-division threshold: how many size-10 slots remain (dead-space granularity).
    let slots = (post_residual / 10) as f64;
    score -= slots * 2.0;

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Fraction of bin wasted: quadratic dead-space penalty.
    let waste_frac = post_residual as f64 / cap;
    score += waste_frac * waste_frac * 30.0;

    // Lookahead: penalize if next item cannot fit into post_residual (harmonic mismatch),
    // reward if it fits snugly.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 12.0; // next item forced elsewhere: this bin's leftover likely dead
        } else {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 60.0; // perfect chaining
            } else if gap <= 10 {
                score -= 25.0;
            } else {
                score += gap as f64 * 0.3;
            }
        }
    } else {
        // Last item: strongly prefer emptying residual completely.
        score += post_residual as f64 * 1.5;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate (empty bin): only attractive when existing residuals are bad.
    if bin_residual == bin_capacity {
        let mean_penalty = (mean_residual - post_residual as f64).max(0.0);
        score = cap * 0.55 + mean_penalty * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0; // fresh bin pairs well with next item
        }
        if fitting_bins_count <= 1 {
            score -= 20.0; // no good alternative: opening a new bin is fine
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (<= 10) are pure waste; penalize hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 20 {
        // Small gap that only tiny items can use: moderate penalty.
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 30.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + 2.5 * open_bins_count as f64;
    } else {
        // Mild reward for consolidating into existing bins.
        score -= 0.5 * open_bins_count as f64;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to the known next item.
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins close to the mean residual to keep
    // the bin profile balanced.
    score += 0.2 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: perfect match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here; penalize large leftover dead space
            let dead = post_residual as f64 / bin_capacity as f64;
            score += 15.0 * dead;
        }
    }

    // Relative-to-mean residual coupling: prefer bins tighter than average
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so open bins with decent fit win,
    // but allow opening when post_residual would be tiny/unusable
    if bin_residual == bin_capacity {
        score = 0.5 * bin_capacity as f64 + 10.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.2 * next_item_size as f64;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a non-linear term.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tight * tight;

    // Penalize creating unusable dead space: post_residual too small for the
    // smallest plausible future item (<= 10) but nonzero.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item can fit into the resulting residual,
    // reward this placement; otherwise penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // open bins exist that could accommodate the item and residual mass is high.
    if bin_residual == bin_capacity {
        let open_pressure = if open_bins_count > 0 { open_bins_count as f64 } else { 1.0 };
        let avg_usable = mean_residual / open_pressure;
        score += 30.0 + 3.0 * avg_usable;
        // Early in the stream, opening bins is cheaper (exploration).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 20.0 * (1.0 - progress);
    }

    // Mild preference for fuller bins among comparable residuals.
    score -= 0.05 * (item_size as f64);

    // Slight penalty for accumulating many open bins with large mean residual
    // (fragmentation signal).
    if open_bins_count > 3 && mean_residual > 0.5 * bin_capacity as f64 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let fit = item_size as f64 / cap;
    let nxt = next_item_size as f64 / cap;

    // Base: prefer small post residual, non-linearly
    let mut score = norm_pr * norm_pr * cap;

    // Smooth interaction: tight fits rewarded more as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + progress) * 12.0;

    // Penalize dead space that cannot fit the next item (smooth coupling)
    if next_item_size > 0 && pr > 0 {
        let gap = (nxt - norm_pr).max(0.0);
        score += gap * gap * cap * (0.5 + 0.5 * progress);
    }

    // Last-chance bonus: only fitting bin gets a strong smooth discount
    if fitting_bins_count == 1 {
        score -= 8.0 + 6.0 * progress;
    }

    // Penalize scattering across many open bins, weighted by residual spread
    let spread = (mean_residual - pr).abs() / cap;
    score += spread * spread * (4.0 + 4.0 * progress);

    // Mild penalty for opening a new bin early in the stream
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Item-size coupling: large items prefer very tight bins
    score -= fit * tightness * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space via integer division.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class thresholds: post_residual buckets of size 10 (capacity fraction).
    let class = post_residual / 10; // 0..=10
    let class_penalty = match class {
        0 => -30.0,          // perfect fit, tiny dead space
        1 => -12.0,          // excellent (fits smallest item class)
        2 => -5.0,           // good
        3 | 4 => 0.0,        // neutral mid-range
        5 => 4.0,            // awkward half-full
        6 | 7 => 2.0,        // large gap but reusable
        _ => 6.0,            // near-empty bin wasted on small item
    };
    score += class_penalty;

    // Modulo-arithmetic harmonic: post_residual divisible by common item sizes
    // (10, 20, 25, 50) is more reusable.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 5 == 0 { score -= 2.0; }
        else { score += 1.5; }
    }

    // Lookahead: does the next item fit into the resulting residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward proportional fit quality of the lookahead.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack * 0.15;
        } else {
            // Next item won't fit here; penalize leaving this bin stranded.
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // Many candidates: mild preference for tighter bins (already via post_residual).
        score += (fitting_bins_count as f64).ln() * 1.5;
    }

    // New-bin candidate handling: opening fresh is only good when no open bin
    // gives a decent fit (post_residual large) or stream is nearly done.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Penalize new bins early/mid stream unless item is huge.
        let item_frac = item_size as f64 / cap;
        let mut new_bin_score = 45.0 - item_frac * 30.0 + progress * 10.0;
        if item_size >= 70 { new_bin_score -= 20.0; }
        if fitting_bins_count == 0 { new_bin_score -= 100.0; } // forced new bin
        score = new_bin_score;
    }

    // Slight pull toward bins near the mean residual (keeps bin set balanced).
    score += ((post_residual as f64) - mean_residual).abs() * 0.03;

    // Tie-breaker: prefer filling bins that are already quite full.
    let fill_frac = 1.0 - (bin_residual as f64) / cap;
    score -= fill_frac * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftovers are unusable -> heavy penalty.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 40.0; // dead space smaller than min item
        } else if post_residual <= 20 {
            score += 18.0;
        } else if post_residual <= 35 {
            score += 6.0;
        }
    } else {
        score -= 60.0; // perfect fit: fill bin exactly
    }

    // Reward tight fits (high fill ratio of the residual consumed).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Last-chance bin: strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, encourage consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.8 * open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Prefer bins whose residual is near the mean (balanced packing).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    // Lookahead: if next item fits into post_residual, reward leaving usable space.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item won't fit here; small residual becomes dead space
            score += 8.0;
        }
    }

    // New empty bin candidate: only attractive when current bin would leave bad dead space
    // or fit is very loose.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        let mut new_bin_score = 55.0 + 1.2 * open_bins_count as f64;
        if item_size >= 80 {
            new_bin_score -= 25.0; // big items deserve a fresh bin
        }
        if fit_ratio < 0.35 {
            new_bin_score -= 30.0; // loose fit in existing bins -> fresh bin better
        }
        score = score.min(new_bin_score.min(score));
        // If this is the new-bin call, its score is the alternative; keep it competitive
        // but not dominant unless justified.
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: perfect match leaves exactly room for the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item still fits, but penalize leftover slack after both placements.
            let after_next = post_residual - next_item_size;
            score += after_next as f64 * 0.3;
            score -= 15.0;
        } else {
            // Next item won't fit here: penalize the unusable gap more when it's small.
            let gap = post_residual as f64;
            if gap < 10.0 {
                score += 25.0;
            } else {
                score += gap * 0.5;
            }
        }
    } else {
        // Last item: prefer tightest fit (smallest post_residual naturally).
        score += 5.0;
    }

    // Compare against mean residual across open bins.
    let resid = post_residual as f64;
    if resid > mean_residual {
        score += (resid - mean_residual) * 0.4;
    } else {
        score -= (mean_residual - resid) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        let good_fit = next_item_size > 0 && post_residual <= next_item_size;
        if good_fit || fitting_bins_count == 0 {
            score -= 20.0;
        } else {
            score += 40.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Late in the stream, consolidate into existing bins more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: perfect or near-perfect placement gets strong discount.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        let tight = 1.0 - (post_residual as f64) / cap;
        score -= 40.0 * tight * tight;
    }

    // Penalize large dead space relative to the smallest useful item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Lookahead coupling: favor bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.3 * next_item_size as f64;
        } else if post_residual > 0 {
            score += 10.0; // creates a gap the next item cannot use
        }
    }

    // New-bin candidate handling: only attractive when open bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        score += 30.0 + pressure;
        // Early in the stream, opening bins is cheap; later, discourage it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
    } else {
        // Reward using bins with below-average residual (consolidate emptier space).
        score -= 0.2 * (mean_residual - bin_residual as f64).max(-cap) / cap * 10.0;
    }

    // Mild preference for filling bins that are already mostly full.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 15.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) * 40.0
                 - norm_pr * progress * 20.0;
    score += coupling;

    // Dead-space penalty: quadratic in tightness of the fit
    let fit_tightness = 1.0 - norm_pr;
    score -= fit_tightness * fit_tightness * item_size as f64 * 0.8;

    // Last-chance bonus: smooth exponential reward when few fitting bins
    let last_chance = 1.0 / (fitting_bins_count as f64).max(1.0);
    score -= last_chance * 15.0 * (1.0 - progress * 0.5);

    // Lookahead: penalize if next item fits poorly in post residual (smooth term)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx).max(0.0);
        let waste = (nx - pr).max(0.0);
        score += waste * 0.5 - slack * 0.1 * progress;
    }

    // Slight preference to fill bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * (item_size as f64 / cap) * 3.0;

    // Mean-residual regularization
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify leftover space by
    // integer division into capacity fractions (quarters, fifths, tenths).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Exact-fill reward: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty for tiny unusable leftovers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Class of post_residual via division thresholds on capacity fractions.
    let frac = post / cap; // 0..1
    let class = (frac * 10.0).floor() as u32; // 0..9 tenths
    score += match class {
        0 => 0.0,                    // nearly full: excellent
        1 => 5.0,
        2 => 12.0,
        3 => 20.0,
        4 => 30.0,
        5 => 42.0,
        6 => 55.0,
        7 => 70.0,
        8 => 88.0,
        _ => 110.0,                  // nearly empty: wasteful placement
    };

    // Modulo arithmetic: leftover compatible with common item sizes (10..80)
    // is reusable. Reward if post_residual mod 10 == 0 (aligned with grid).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how tightly next item fits.
            let slack = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - slack / cap);
        } else {
            // Next item cannot use this bin's leftover: mild penalty scaled
            // by how much of the leftover next item would waste.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 10.0 * (overshoot / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 250.0;
        // Cheaper to open new bin early in stream or when many bins already open
        // and mean residual is low (existing bins are cluttered).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 60.0 * progress;
        if (mean_residual / cap) < 0.25 && open_bins_count > 0 {
            score -= 80.0;
        }
        // If item is large, new bin is often better.
        if item_size > bin_capacity / 2 {
            score -= 40.0;
        }
    }

    // Prefer bins whose residual is far below mean (consolidate emptier bins).
    score += 20.0 * ((bin_residual as f64 - mean_residual) / cap);

    // Slight preference for tight fit relative to item size.
    score += 10.0 * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer packing tighter bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.6 + 0.8 * progress);

    // Prefer bins below mean residual (tighter bins) to consolidate space.
    score -= (mean_residual - bin_residual as f64) * 0.4;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    }
    // If next item cannot fit the post residual but post residual is large, mild penalty.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // New-bin candidate: keep it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post-residual close to next item size (tight but usable).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item: penalize proportionally.
        let waste = (next_item_size - post_residual) as f64;
        score += 25.0 * (waste / bin_capacity as f64);
    }

    // Prefer bins whose residual is below mean residual (tighter packing).
    score -= 15.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // Last fitting bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize tiny unusable leftovers (dead space < 10).
    if post_residual < 10 {
        score += 20.0;
    }

    // Early in stream: slightly favor filling existing bins to keep bin count low.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 35.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.89;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with quadratic dead-space penalty.
    let mut score = pr
        + 60.0 * norm_pr * norm_pr
        - 40.0 * norm_pr * norm_pr * norm_pr;

    // Perfect-fit reward (smooth bump near zero residual).
    score -= 55.0 * (-pr / 8.0).exp();

    // Tight-fit reward: item fills most of the bin.
    let fill = item_size as f64 / cap;
    score -= 25.0 * fill * (1.0 - norm_pr);

    // Lookahead coupling: reward leaving space the next item can use.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            let gap = (pr - n) / cap;
            score -= 18.0 * (1.0 - gap) * (1.0 - gap);
        } else {
            score += 10.0 * (n - pr) / cap;
        }
    }

    // Stream-progress polynomial coupling: early on, favor consolidation;
    // later, tolerate fragmentation less (penalize residual more).
    let prog_term = progress * (1.0 - progress) * 4.0;
    score += pr * (0.25 + 0.5 * progress) - 30.0 * prog_term * (1.0 - norm_pr);

    // Last-chance bin: strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 + progress);
    }

    // Mild penalty for leaving residual that no typical small item fits into.
    if pr < 10.0 && pr > 0.0 {
        score += 8.0 * (10.0 - pr);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: capacity fractions (C/4, C/2, 3C/4) as integer thresholds
    let q = bin_capacity / 4; // 25
    let half = bin_capacity / 2; // 50
    let threeq = 3 * q; // 75

    // Class of the resulting residual via integer division (harmonic bucket 0..4)
    let res_class = post_residual / q; // 0..4

    // Reward tight fits: residual in the lowest harmonic class gets a strong discount
    score -= (4 - res_class.min(4)) as f64 * 8.0;

    // Perfect-fill class: post_residual in {0, small dead zone} heavily favored
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual < 10 {
        score -= 6.0;
    }

    // Penalize "awkward" residuals: post_residual in (10, q) is prime dead space
    if post_residual > 10 && post_residual < q {
        score += 10.0;
        // modulo-5 class: residuals congruent to 1..4 mod 5 are less reusable
        if post_residual % 5 != 0 {
            score += 4.0;
        }
    }

    // Coupling with next item (k=2 lookahead): reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item chains into this bin: strong reward, scaled by tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 - (slack / half as f64) * 6.0;
            if next_item_size + post_residual == bin_capacity {
                score -= 25.0; // two-item exact fill
            }
        } else {
            // next item cannot use leftover: penalize proportionally to wasted class
            score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.3;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid forcing a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Many open bins: discourage fragmenting capacity further
    score += open_bins_count as f64 * 0.6;

    // Mean residual coupling: prefer bins whose residual is below mean (concentrate waste)
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // New-bin candidate: neutral-ish but slightly penalized so it only wins for bad fits
    if bin_residual == bin_capacity {
        score += 22.0;
    }

    // Progress term: late in the stream, prefer closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (4 - res_class.min(4)) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) / (bin_residual as f64) * 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins (penalize the new-bin candidate).
    if bin_residual == bin_capacity {
        score += 15.0 + (open_bins_count as f64) * 2.0;
    }

    // Lookahead: if next item could exactly fill the post_residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item cannot fit in post_residual but could fit a fuller bin, mild penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 5.0;
    }

    // Mean residual coupling: prefer bins whose residual is below the mean
    // (fill the emptiest-but-fitting bins first to consolidate space).
    score += ((bin_residual as f64) - mean_residual) * 0.3;

    // Late in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 100.0;
    }
    // Post-residual slightly above next item size wastes little; slightly below forces new bin.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap < 0.0 {
            // Item won't chain: dead space relative to next item, penalize proportionally.
            score += (-gap) * 0.5;
        } else if gap > 0.0 && gap <= 10.0 {
            // Near-match: mild reward to encourage close chaining.
            score -= 5.0 * (1.0 - gap / 10.0);
        }
    }

    // Prefer bins whose residual is below the mean residual (tighter packing).
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly reward using it instead of opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize very small unusable post-residuals (dead space).
    if post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Slight preference for filling existing bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // New-bin candidate should only win when all open fits are poor.
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Penalize dead space that is too small to be useful later.
    // Items range 1..100; residuals below ~min future item are waste.
    let waste_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < waste_threshold {
        score += 60.0 * (waste_threshold - post_residual as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            // Next item fits: mild reward proportional to how well it fills.
            score -= 20.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: mild penalty for tight residuals
            // that leave the next item stranded.
            let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
            score += 15.0 * tightness;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin should only win when
    // existing fits are poor. Give the empty bin a baseline penalty that
    // shrinks late in the stream or when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 150.0 - 60.0 * progress - 10.0 * open_pressure;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 50.0 * fill_ratio;
    }

    // Prefer bins whose residual deviates favorably from the mean:
    // bins with below-mean residual are "more full", prefer filling them.
    let dev = mean_residual - bin_residual as f64;
    score += 0.5 * dev;

    // Mild preference for bins with small residuals overall (best-fit bias).
    score += 0.1 * (bin_residual as f64 - post_residual as f64) * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: quadratic polynomial in post_residual, modulated by stream progress.
    // Early on, prefer tight fits (low post_residual); later, tolerate larger residuals.
    let mut score = pr_norm * pr_norm * (2.0 + 2.0 * progress) + pr_norm * (1.0 - progress);

    // Smooth non-linear coupling: cubic interaction between residual fraction and progress.
    score += 0.8 * pr_norm * pr_norm * pr_norm * (1.0 - progress) * (1.0 - progress);

    // Penalize residuals that cannot fit the next item (dead space), smoothly scaled.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 2.5 * (ns - pr) / cap * (0.5 + 0.5 * progress);
        } else {
            // Reward residual that nicely fits next item without much waste.
            score -= 1.2 * (1.0 - (pr - ns) / cap) * (pr - ns) / cap;
        }
    } else {
        // Last item: strongly reward zero waste.
        score -= 2.0 * (1.0 - pr_norm);
    }

    // Last-chance bonus: if this is the only fitting bin, favor using it.
    if fitting_bins_count == 1 {
        score -= 1.5 + 1.5 * progress;
    }

    // Mild penalty tied to crowding of open bins relative to mean residual.
    score += 0.3 * (mean_residual / cap - pr_norm).abs();

    // Slight preference for fewer open bins when residuals are comparable.
    score += 0.01 * open_bins_count as f64 * pr_norm;

    // New-bin candidate: make it unattractive unless it genuinely beats tight fits.
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * (1.0 - progress) + 0.02 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: mod-10 classes capture how "usable"
    // the leftover space is for typical item granularities (items 1..100).
    let pr = post_residual;
    let class = (pr % 10) as f64;

    // Perfect fit is ideal.
    if pr == 0 {
        score -= 1000.0;
    } else {
        // Reward leftovers that are multiples of common sizes (10/20/25/50):
        // these are reusable by future items.
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 6.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // Penalize dead-space classes: leftovers in (0,10) are nearly unusable
        // for mid/large items; small odd remainders are worst.
        if pr < 10 {
            score += 40.0 + class * 2.0;
        }
        // Harmonic divisor count: more divisors => more future fits.
        let mut divs = 0u32;
        let mut d = 1u32;
        while d * d <= pr {
            if pr % d == 0 { divs += 2; }
            d += 1;
        }
        score -= divs as f64 * 1.5;
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // Reward leaving room for the known next item.
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 + slack * 0.3;
            // Extra reward if next item then leaves a harmonic remainder.
            if (pr - next_item_size) % 10 == 0 { score -= 8.0; }
        } else {
            // Penalize blocking the next item into this bin's class.
            score += 15.0;
            if pr < 10 { score += 20.0; }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is bad
    // and the stream is early enough to amortize the new bin.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // Empty bin baseline: attractive only if best existing fit is poor.
        let fit_quality = if pr + item_size <= bin_capacity { (bin_capacity - pr - item_size) as f64 } else { 0.0 };
        let _ = fit_quality;
        let open_penalty = 90.0 * (1.0 - progress);
        // New bin is penalized when many bins are open and mean residual is large.
        score = 100.0 + open_penalty + (mean_residual * 0.4) + (open_bins_count as f64 * 2.0);
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            // Large next item: fresh bin is more valuable.
            score -= 30.0;
        }
    }

    // Mild preference for tighter (fuller) bins overall.
    score += (bin_capacity as f64 - bin_residual as f64).recip() * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100)
    // are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    } else if post_residual > 0 && post_residual < item_size {
        // gap smaller than current item: likely dead space, mild penalty
        score += 0.5 * post_residual as f64;
    }

    // Reward tight fits (small usable residual relative to item).
    score -= 0.8 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to new bins
    // and encourage consolidating into existing ones.
    let pressure = open_bins_count as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when current bins are crowded/tight.
        score += 20.0 + 150.0 * pressure;
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    } else {
        score -= 5.0 * pressure;
    }

    // Lookahead: if the next item could exactly use this bin's post-residual,
    // reward leaving that residue; if post-residual is useless for next item, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next_item_size (item+next fill bin perfectly).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Tight match bonus: strong reward when next item exactly fills leftover.
        score -= 60.0 * (-gap / 12.0).exp();
        // Mild general reward for leaving space usable by the next item.
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Penalize dead space the next item cannot use.
            score += 0.35 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize very small post-residuals that become unusable dead space,
    // unless the next item matches them (handled above).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Prefer bins whose residual is below mean (tighter packing), reward
    // filling the emptiest relative to the fleet average.
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when no good fit exists; add a
    // dynamic penalty that decays as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 55.0 - 25.0 * progress;
        // Extra penalty if open bins can already fit the item.
        if fitting_bins_count > 0 {
            score += 30.0;
        }
    }

    // Small preference for placing large items into tight bins.
    score += 0.1 * item_size as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post_residual quadratically.
    let pr = post_residual as f64;
    score += 0.05 * pr * pr / bin_capacity as f64;

    // Lookahead: if the next item fits the post residual, this placement chains well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            score += 3.0;
        }
        // Exact chain: next item fills the bin completely.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else {
        // Last item: strongly prefer fullest packing.
        score -= 5.0;
    }

    // Last chance: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Prefer bins already below mean residual (more filled than average).
    let residual_f = bin_residual as f64;
    score += 0.3 * (residual_f - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - residual_f).max(0.0);

    // New-bin candidate: only attractive when item is huge relative to capacity
    // or existing fits are all very loose.
    if bin_residual == bin_capacity {
        let ratio = item_size as f64 / bin_capacity as f64;
        if ratio > 0.7 {
            score -= 20.0 * (ratio - 0.7);
        } else {
            score += 6.0;
        }
        // Late in stream, opening fresh bins is fine (future unknown anyway).
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 5.0 * t;
    }

    // Mildly discourage scattering across many open bins when item is small.
    if item_size < 30 && open_bins_count > 3 && bin_residual != bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Tight fits are rewarded more as the stream progresses
    let tightness = 1.0 - pr_norm;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize residuals too small to be useful later (dead space), smoothly
    let useless = (1.0 - pr_norm).powi(3);
    score += 10.0 * useless * (1.0 - progress);

    // Non-linear interaction: quadratic in progress times normalized residual
    score += 4.0 * pr_norm * pr_norm * (progress * (1.0 - progress) * 4.0);

    // Last-chance bin: strong smooth bonus
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Prefer bins below mean residual slightly (pack tight bins first)
    score += 0.3 * (pr - mean_residual);

    // Lookahead: if next item fits the post residual, reward
    if next_item_size > 0 {
        let fits_next = (next_item_size as f64 <= pr) as i32 as f64;
        let gap = (pr - next_item_size as f64) / cap;
        score -= 6.0 * fits_next * (1.0 - gap.abs());
        // Penalize post residual that exactly matches nothing (awkward size)
        score += 3.0 * fits_next * gap * gap;
    } else {
        // Last item: minimize leftover hard
        score += 0.5 * pr_norm;
    }

    // Mild penalty for opening new bins late in the stream
    let is_new = (bin_residual == bin_capacity) as i32 as f64;
    score += is_new * (8.0 + 6.0 * progress) / (1.0 + (open_bins_count as f64).ln().max(1.0));

    // Reward using existing bins with moderate fill, smooth in progress
    if is_new < 0.5 {
        score -= 2.0 * tightness * (1.0 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: exact quarter/half classes are ideal.
    let q = post_residual % (bin_capacity / 4);
    let half = bin_capacity / 2;
    let mut bonus = 0.0;
    if post_residual == 0 {
        bonus -= 60.0; // perfect fill
    } else if post_residual == half {
        bonus -= 25.0; // exact half
    } else if q == 0 {
        bonus -= 15.0; // exact quarter multiple
    } else if post_residual > half {
        bonus -= 6.0; // still roomy, can host future items
    } else if q <= 5 {
        bonus -= 8.0; // near-quarter residual, small dead space
    } else {
        bonus += 10.0; // awkward mid-class residual
    }

    // Next-item lookahead: reward residuals that can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            bonus -= 12.0;
            // harmonic class of slack after hosting next item
            let sq = slack as u32 % (bin_capacity / 4);
            if sq == 0 { bonus -= 10.0; }
            else if sq <= 5 { bonus -= 5.0; }
            else { bonus += slack * 0.15; }
        } else {
            bonus += 8.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        bonus -= 20.0;
    }

    // Penalize opening a new bin when decent fits exist, unless item is huge.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        bonus += 18.0 - 22.0 * fill_ratio; // big items justify new bins
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            bonus -= 10.0; // new bin can host pair
        }
    }

    // Progress coupling: later in stream, tighten packing (punish loose residuals).
    let progress = step_index as f64 / total_items.max(1) as f64;
    bonus -= progress * (mean_residual - post_residual as f64) * 0.25;

    // Mild penalty for many open bins to encourage consolidation.
    bonus += open_bins_count as f64 * 0.05;

    score += bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Strict dead-space avoidance: residuals too small for any item (1..=10)
    // are unusable dead space -> heavy penalty proportional to wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual >= 10 {
        // Usable leftover: mild reward scaled by how well it matches typical item sizes.
        score -= 3.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0; // leftover can host the lookahead item
        }
        // Penalize leftovers that are awkwardly close to but below next item.
        if next_item_size > 0 && post_residual >= (next_item_size as f64 * 0.6) as u32 && post_residual < next_item_size {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoids opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer filling existing ones,
    // discourages bin proliferation.
    score += open_bins_count as f64 * 1.5;

    // New-bin candidate handling: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if no open bin fits well (best existing post_residual is dead space),
        // opening fresh is better: discount the new bin.
        if fitting_bins_count == 0 {
            score -= 45.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Early in the stream, tolerate more bins for better packing later.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 8.0;
    } else {
        // Reward tight fits relative to bin state.
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= fill_ratio * 10.0;
        // Prefer bins whose residual deviates favorably from the mean residual.
        score += (mean_residual - bin_residual as f64) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (post_residual == 0 is ideal).
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tight-fit bonus: strongly reward small dead space.
        score -= 300.0 / (post_residual as f64);
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 80.0;
        // Extra reward if next item fills the bin completely after two placements.
        if post_residual == next_item_size {
            score -= 120.0;
        }
        // Reward chain fits relative to mean residual (dense packing trend).
        if (post_residual as f64) <= mean_residual {
            score -= 30.0;
        }
    } else if next_item_size > 0 {
        // Penalize leaving residual that the next item cannot use (dead space risk).
        score += 40.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Penalize opening a new bin when existing bins fit, unless residual is very tight.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 60.0;
    }

    // Prefer placing into bins with smaller residual before placement (tightest fit first).
    score += 0.3 * (bin_residual as f64 - post_residual as f64);

    // Late-stream pressure: be more aggressive about filling bins tightly as stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 50.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Many open bins: discourage spreading, favor consolidating into tight fits.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic bonus for small post-residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact / near-exact fill gets a large reward.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize dead space that no plausible future item (>=10) can use,
    // scaled by how late in the stream we are.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual < 10 {
        // already rewarded; unusable sliver is actually fine (bin is "closed")
    }
    let dead = (post_residual as f64).min(9.0);
    score += dead * (0.5 + 0.5 * (1.0 - progress));

    // Lookahead coupling: reward bins whose post-residual fits the next item well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = 1.0 - (post_residual - next_item_size) as f64 / (bin_capacity as f64);
        score -= 12.0 * next_fit;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot fit here; mild penalty proportional to wasted potential
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing fits are poor (large post-residual) or many bins are congested.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for wasting a fresh bin.
        score += 15.0;
        // But if placing here would leave a big awkward residual in an existing
        // bin, opening fresh becomes relatively better: the comparison already
        // reflects post_residual, so add pressure when many bins are open
        // (consolidation phase) and reward keeping open-bin count low.
        score += 2.0 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into existing bins.
        score += 20.0 * progress;
        // If the item perfectly fits a fresh bin (rare), allow it.
        if item_size == bin_capacity {
            score -= 200.0;
        }
    }

    // Prefer bins with below-mean residual (they are the "tight" ones);
    // spreading items across bins with high residual is wasteful.
    let bin_res_f = bin_residual as f64;
    if bin_res_f < mean_residual {
        score -= 6.0 * (mean_residual - bin_res_f) / (bin_capacity as f64);
    } else {
        score += 3.0 * (bin_res_f - mean_residual) / (bin_capacity as f64);
    }

    // Mild global pressure: with many open bins, favor filling existing ones.
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Small deterministic tie-breaker keyed on residuals to diversify choices.
    score += ((bin_residual as f64 * 0.37 + item_size as f64 * 0.11).sin()) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / c;
    let norm_post = pr / c;

    // Non-linear polynomial coupling: quadratic in post_residual modulated by progress
    score += norm_post * norm_post * (20.0 + 40.0 * t) * (1.0 - fit_ratio);

    // Dead-space penalty: small residuals are useless; smooth cubic falloff
    let dead = 1.0 - norm_post;
    score -= dead * dead * dead * (15.0 + 25.0 * t);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 + 50.0 * t;
    }

    // Crowd penalty: many open bins -> prefer tightening existing bins
    score += (open_bins_count as f64).ln() * norm_post * 5.0;

    // Lookahead coupling: reward residuals that fit next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let compat = 1.0 - ((pr - nx) / c).abs();
        score -= compat * compat * (10.0 + 20.0 * (1.0 - t));
    }

    // New-bin candidate: penalize relative to mean residual state
    if bin_residual == bin_capacity {
        score += 25.0 + 35.0 * t + mean_residual * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: modulo arithmetic on capacity ---
    // Residuals that are "harmonically useful" (divisible into common item sizes)
    // should be rewarded (subtract), awkward residuals penalized (add).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let ir = item_size as f64;

    // Class A: post_residual exactly 0 -> perfect fit, strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Class B: post_residual falls into small "dead zone" (< 10, min item size)
    // => unusable dead space, penalize proportionally.
    if post_residual < 10 && post_residual > 0 {
        score += (10 - post_residual) as f64 * 3.0;
    }

    // Class C: harmonic divisibility — residual divisible by common item
    // granularities (5, 10, 20, 25) is reusable. Reward via modulo tests.
    let mod5 = post_residual % 5 == 0;
    let mod10 = post_residual % 10 == 0;
    let mod25 = post_residual % 25 == 0;
    if mod25 {
        score -= 8.0;
    } else if mod10 {
        score -= 5.0;
    } else if mod5 {
        score -= 2.0;
    } else {
        // awkward residual, mild penalty
        score += 2.0;
    }

    // Integer-division thresholds: how many "typical" items (size ~ mean item
    // estimate = capacity - mean_residual proxy) still fit in post_residual.
    let typical = (cap - mean_residual).max(1.0);
    let fits_future = (pr / typical).floor();
    score -= fits_future * 4.0;

    // --- Lookahead coupling (k=2): does next_item_size fit the post residual? ---
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if next_item_size <= post_residual {
            // Chain fit: reward, stronger when it's a tight chain.
            let tightness = nx / (post_residual as f64);
            score -= 10.0 + 8.0 * tightness;
            // Harmonic match: next item divides residual nicely.
            if post_residual % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            // Next item cannot use leftover: penalize leftover more.
            score += pr * 0.15;
        }
    }

    // --- Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation). ---
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // --- New-bin candidate handling: an empty bin has residual == capacity.
    // Opening a new bin is only attractive when no open bin fits well.
    // Give the empty bin a baseline penalty that grows with open_bins_count
    // and with how well this item would otherwise fit. ---
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin: penalize so it loses against decent fits.
        score += 25.0 + 2.0 * open_bins_count as f64;
        // But if item is large relative to capacity, new bin is fine (large
        // items leave little choice anyway): reduce penalty.
        let frac = ir / cap;
        score -= 20.0 * frac;
        // If mean residual across open bins is small (bins are full-ish),
        // opening a new bin is natural: reduce penalty.
        score -= (mean_residual / cap) * 10.0;
        // If next item is large and would need a fresh bin anyway, slight relief.
        if next_item_size >= 60 {
            score -= 5.0;
        }
    }

    // --- Tightness reward: prefer bins where item fills a large fraction of
    // the residual (best-fit style), scaled by capacity fraction classes. ---
    let fill = ir / bin_residual as f64;
    score -= fill * 12.0;

    // --- Stream progression: early in the stream, keep bins open/loose
    // (favor using existing bins); late in the stream, prioritize tight fits. ---
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * pr * 0.05;   // early: leftover space matters more
    score -= progress * fill * 6.0;          // late: tightness matters more

    // --- Many open bins: discourage spreading into bins with high residual
    // dispersion from the mean (keep residuals homogeneous). ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // (below a usability threshold) are heavily penalized.
    let usable_threshold: f64 = 10.0; // min item size baseline
    if (post_residual as f64) < usable_threshold {
        score += 60.0; // unusable gap -> strong penalty
    } else if post_residual == 0 {
        score -= 25.0; // perfect fill is the best outcome
    }

    // Non-linear penalty on medium dead space: gaps that can't fit typical
    // next items are worse than they look.
    if post_residual > 0 && post_residual < next_item_size && next_item_size > 0 {
        score += 15.0; // residual can't hold the lookahead item
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; penalize opening new bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 20.0 + 10.0 * pressure;
        // But if no existing bin fits well (all residuals tiny), opening
        // a fresh bin can be right; soften penalty when mean residual is low.
        if mean_residual < 15.0 {
            score -= 25.0;
        }
    } else {
        // Existing bin: slight reward that grows with open-bin pressure.
        score -= 2.0 * pressure;
    }

    // Early-stream exploration: when few items have arrived, mildly prefer
    // filling existing bins to establish dense packing patterns.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if progress < 0.2 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Lookahead coupling: if the next item would fit exactly in the
    // post_residual, reward this placement for a chained perfect fill.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item (perfect chaining).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            // Slack after hypothetically placing the next item too:
            // tighter chains (small slack) are better.
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow into this bin: penalize proportionally
            // to how far off we are, scaled by lookahead size.
            let gap = (next_item_size - post_residual) as f64;
            score += 4.0 * (gap / next_item_size as f64).min(1.0);
        }
    } else {
        // Last item: minimize leftover as strongly as possible.
        score += 30.0;
    }

    // Relative-to-mean residual shaping: bins tighter than the average are
    // preferred targets; bins looser than average get a mild penalty.
    score += 0.6 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make opening a fresh bin unattractive unless the
    // item is large relative to capacity (poor fits elsewhere get outweighed
    // by the penalties above).
    if bin_residual == bin_capacity {
        score += 15.0 + 0.3 * (item_size as f64);
    }

    // Mild pressure to close nearly-full bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual <= 5 {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual), with mild non-linearity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Last-chance bin: heavily favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.25 * (post_residual - next_item_size) as f64;
        } else {
            score += 8.0 + 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Penalize new bins when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64 / bin_capacity as f64).powi(2);
        let global_pressure = mean_residual / bin_capacity as f64;
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early on or with many fitting bins, opening new bins is cheap; later it is costly.
        let new_bin_penalty = 45.0 * (1.0 - 0.5 * time_frac) * (1.0 - 0.3 * tightness)
            - 10.0 * (1.0 - global_pressure);
        score += new_bin_penalty;
        // If the item is huge and nothing else fits well, new bin is less bad.
        if item_size >= 70 && fitting_bins_count <= 2 {
            score -= 25.0;
        }
    }

    // Slight preference for filling bins with below-average residual (consolidation).
    if bin_residual < bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.05 * diff;
    }

    // Discourage leaving residuals that are hard to reuse (prime-gap-like awkward zones).
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 15.0; // tiny dead space
    } else if pr >= 10 && pr < 20 {
        score -= 5.0; // still usable for small items
    }

    // Mild diversification pressure: many open bins -> prefer filling existing ones.
    score += 0.4 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress * (1.0 - progress) * 4.0; // peaks at 1 mid-stream, 0 at ends
    score -= t * (pr * pr / cap) * 0.8;
    score += t * (norm_pr * norm_pr) * 25.0;

    // Reward tight fits smoothly (quadratic in fill ratio)
    let fill = item_size as f64 / cap;
    score -= fill * fill * 30.0;

    // Penalize dead space relative to mean residual, smooth coupling
    let dev = (pr - mean_residual) / cap;
    score += dev.abs() * dev.abs() * 40.0;

    // Last-chance bonus (smooth ramp)
    if fitting_bins_count == 1 {
        score -= 12.0 + 20.0 * t;
    }

    // Lookahead coupling: favor residuals that can host next item, quadratic in gap
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += (gap / cap) * (gap / cap) * 35.0;
    }

    // Mild penalty for bin proliferation
    score += (open_bins_count as f64).ln() * 2.0;

    // Smooth preference for moderate residuals as stream progresses
    score += t * (norm_pr - 0.5).powi(2) * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // capacity-fraction buckets. Small classes (near 0) are "dead space"
    // and should be penalized; mid classes are reusable.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;

    // Dead-space penalty: leftover < smallest plausible item (10) is wasted.
    if post_residual < 10 {
        score += 60.0 * (1.0 - pr / 10.0);
    }

    // Harmonic bucket reward: leftover divisible into useful chunks.
    // Buckets at capacity fractions: (0, 1/4, 1/2, 3/4, 1]
    let frac = pr / c;
    let bucket = (frac * 4.0).floor() as u32; // 0..=3
    match bucket {
        0 => score -= 5.0,               // tight fit, good packing
        1 => score -= 12.0,              // sweet spot for mid items
        2 => score -= 8.0,               // decent
        _ => {}                          // nearly empty, neutral
    }

    // Integer-division harmonic: how many items of the NEXT item's size
    // fit in the leftover? More future fits => stronger reward.
    if next_item_size > 0 {
        let future_fits = post_residual / next_item_size;
        score -= 6.0 * future_fits as f64;
        // Exact harmonic match: leftover is a multiple of next size
        if post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin fits badly.
    if bin_residual == bin_capacity {
        // A fresh bin has full residual; make it slightly unattractive unless
        // the item is large and would leave an awkward class in existing bins.
        let awkward = post_residual > 0 && post_residual < 15;
        score += if awkward { 5.0 } else { 20.0 };
        // Prefer new bin late in stream when many bins are open but fragmented
        if open_bins_count > 8 && mean_residual < 30.0 {
            score -= 15.0;
        }
    }

    // Modulo harmonic tie-breaker: leftover congruent to 0 mod 10 packs well
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Mild progression scaling: tighten decisions as stream advances.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small for the smallest plausible item.
    let min_item = 1u32;
    let dead_threshold = 10u32; // items are >= 10 in the classic regime; treat gaps < ~10 as dead
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64; // dead space penalty
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing the bin exactly.
        score -= 25.0;
    } else {
        // Tight-but-usable fits are mildly rewarded.
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= 8.0 * tightness;
    }

    // Penalize leaving a gap that cannot fit the known next item (wasted pair opportunity).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0; // next item can also go here: chain placements
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing ones
    // rather than spreading; opening a new bin is penalized implicitly via residual=capacity.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open,
        // and when plenty of open bins could fit the item.
        score += 18.0 + 6.0 * open_pressure + 2.0 * fitting_bins_count as f64;
        // Early in the stream, opening bins is cheaper (build diversity).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    } else {
        // Existing bin that is the ONLY fitting bin: last chance, avoid opening a bin.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
        // Prefer bins with below-average residual (keep some bins roomy for big items).
        let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
        score += 5.0 * dev;
    }

    // Mild global pressure: as stream progresses, discourage fragmentation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: next item exactly fills post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 60.0; // perfect chain: this bin will be exactly filled by next item
        } else {
            // reward tight chains, decay with slack
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // next item cannot use this bin's leftover: penalize dead space relative to mean residual
        let dead = post_residual as f64;
        score += 0.5 * dead;
        score += 10.0 * (dead - mean_residual).max(0.0);
    }

    // Reward leaving residuals that are small (tight fit overall)
    score -= 0.3 * (bin_capacity as f64 - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins fit well, especially late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 30.0 * progress;
        // But if the item leaves a residual matching next_item_size in a fresh bin,
        // soften the penalty (opening may enable a perfect chain).
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            if slack == 0.0 {
                score -= 45.0;
            }
        }
    }

    // Mild pressure toward bins with residuals below the mean (compact the pack).
    score += 0.2 * (mean_residual - bin_residual as f64);

    // Small penalty for very large leftovers that few items can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable fragment
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize large post-residual non-linearly.
    let t = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * t * t;

    // Exact fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Dead space: residual too small for any plausible future item (sizes >= 1,
    // but small residuals < 10 are nearly unusable in classic streams).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item cannot fit here; slight penalty for stranding space.
            score += 5.0 + 0.1 * (post_residual as f64);
        }
    }

    // Prefer fuller bins relative to the mean residual (balance consolidation).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Early in the stream: encourage opening bins to spread load (exploration);
    // later: consolidate into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses, less when
        // few bins are open or item is large relative to capacity.
        let mut new_bin_penalty = 20.0 + 40.0 * progress;
        if item_size > bin_capacity / 2 {
            new_bin_penalty -= 10.0;
        }
        if open_bins_count == 0 {
            new_bin_penalty -= 50.0;
        }
        // If next item is large and current item leaves a good gap, new bin ok.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual < next_item_size + 10 {
            new_bin_penalty -= 15.0;
        }
        score += new_bin_penalty;
    } else {
        // Existing bin: early exploration bonus for opening capacity spread.
        score -= 10.0 * (1.0 - progress);
    }

    // Many open bins: push toward consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item_norm = item_size as f64 / cap;
    let next_norm = next_item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    score += pr_norm * (2.0 + 6.0 * p2 + 10.0 * p3) * cap * 0.5;

    // Reward tight fits more strongly as the stream progresses
    score -= item_norm * cap * (1.0 + 2.0 * progress);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 && post_residual > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * (0.5 + p2);
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 * (0.5 + progress);
    }

    // Slight penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.05 * pr_norm;

    // Mean-residual coupling: prefer bins near the mean (keeps residuals uniform)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * (0.1 + 0.3 * p2);

    // Prefer bins whose post-residual matches the next item smoothly
    if next_item_size > 0 {
        let match_err = (pr - next_norm * cap).abs() / cap;
        score -= 5.0 * (1.0 - match_err.min(1.0)) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual by modulo classes
    let cap_f = bin_capacity as f64;
    let post = post_residual as f64;
    let frac = post / cap_f; // capacity fraction of leftover

    // Small leftovers are dead space -> penalize strongly
    if post_residual == 0 {
        score -= 50.0; // perfect fit, best possible
    } else if post_residual < 10 {
        score += 30.0; // tiny dead space
    } else {
        // reward leftovers that form "harmonic" usable classes
        // leftover usable if next item or a small item could fit
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // modulo classes: leftovers divisible by common item granularities (e.g. 10, 20, 25)
        if post_residual % 10 == 0 { score -= 6.0; }
        if post_residual % 20 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        // penalize awkward mid-range leftovers (just above half capacity is wasteful)
        if frac > 0.5 && frac < 0.75 { score += 8.0 * (frac - 0.5); }
    }

    // Last-chance bin: strongly prefer using it before opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is terrible
    if bin_residual == bin_capacity {
        // opening a new bin is only attractive if the item leaves a bad residual elsewhere
        let elsewhere_bad = post_residual > 0 && post_residual < item_size / 2;
        if elsewhere_bad { score -= 5.0; } else { score += 25.0; }
        // early stream: opening bins is fine; late stream: consolidate
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer bins tighter than the mean residual (good packing density)
    score -= 0.3 * (mean_residual - post).max(-50.0).min(50.0);

    // Slight preference for bins whose residual is close to item size (snug fit)
    let snug = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * snug;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (1..=10) are pure waste; penalize them quadratically.
    if post_residual < 10 {
        score += 200.0 + (10 - post_residual) as f64 * 30.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // already-open bins rather than spawning new ones.
    score += open_bins_count as f64 * 3.0;

    // New-bin candidate: make it attractive only when the current bin's
    // post-fit would leave a large dead gap, or when the item fits poorly
    // relative to the mean residual.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; large post_residual is natural here,
        // so soften the raw residual penalty for empty bins.
        score -= 40.0;
        // If the item nearly fills a fresh bin, opening is great.
        if post_residual <= 10 {
            score -= 100.0;
        }
    }

    // Lookahead: if the next item fits in the post residual, reward it;
    // if the next item cannot fit the post residual but could fit the
    // current residual, penalize wasting that space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else if bin_residual >= next_item_size && bin_residual != bin_capacity {
            score += 20.0;
        }
    }

    // Mild preference for filling bins below the mean residual (tight packs).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post-residual (perfect chain), mildly when it fits.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits but leaves further residue: partial credit
            // proportional to how well it consumes the leftover space.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
        } else {
            // Next item cannot use this bin's residue: penalize dead space,
            // scaled by how close the residue is to being "wasted".
            score += 100.0;
        }
    }

    // Penalize tiny unusable residues (dead space) non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0 * (10 - post_residual) as f64;
    }

    // Compare against mean residual: bins with residual far below mean are
    // already tight; prefer packing into bins with larger-than-mean residual
    // to balance load across bins.
    score -= 0.5 * ((post_residual as f64) - mean_residual);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 150.0;
    }

    // Prefer reusing existing bins over opening new ones: the new-bin candidate
    // has bin_residual == bin_capacity (post_residual == 100), which should
    // score worse than a decent existing fit unless the item is huge.
    if bin_residual == bin_capacity {
        score += 30.0;
    }

    // Early in the stream, be more willing to open bins (cheap flexibility);
    // late in the stream, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) more than linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that can't fit even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; slight penalty if we waste a big residual.
            score += 5.0 * (next_item_size as f64 - post_residual as f64).max(0.0) / 100.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, prefer filling existing bins; later, allow opening new bins more readily.
        let new_bin_bonus = 10.0 + 15.0 * progress;
        score -= new_bin_bonus;
        // If the item leaves a nice residual for typical items, new bin is good.
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
    }

    // Prefer filling bins whose residual deviates from the mean (consolidate fragmentation).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild preference for bins with larger residuals when many bins are open.
    score -= 0.02 * (open_bins_count as f64) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = if total_items > 1 { step_index as f64 / (total_items as f64 - 1.0) } else { 0.0 };
    let norm_pr = pr / cap; // normalized post residual in [0,1]

    // Base: post residual (prefer tight fits = low residual)
    let mut score = pr;

    // Non-linear polynomial coupling of residual with stream progress:
    // early: tolerate moderate residual; late: strongly punish waste.
    let waste_penalty = norm_pr * norm_pr * (1.0 + 3.0 * progress * progress);
    score += 60.0 * waste_penalty;

    // Sweet-spot reward: residual just above next item size is ideal (smooth bump)
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let gap = (pr - ns) / cap;
        let bump = (-40.0 * gap * gap).exp(); // smooth Gaussian coupling
        score -= 25.0 * bump * (0.5 + 0.5 * progress);
        // penalize leaving residual that can't fit the lookahead item
        if pr < ns {
            score += 15.0 * (1.0 - pr / ns.max(1.0)) * (0.3 + 0.7 * progress);
        }
    }

    // Last chance: strongly favor using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 35.0 + 20.0 * progress;
    }

    // Mild preference to fill bins with below-average residual (balance consolidation)
    let dev = (mean_residual - pr) / cap;
    score -= 8.0 * dev * (1.0 - progress);

    // Discard spreading items across too many bins late in stream
    score += 0.5 * open_bins_count as f64 * progress * (norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "nice"
    // residue classes (multiples of 10, 5, 25) are more reusable later.
    let pr = post_residual;
    let mut class_bonus = 0.0;
    if pr % 10 == 0 && pr > 0 {
        class_bonus += 6.0;
    } else if pr % 5 == 0 && pr > 0 {
        class_bonus += 3.0;
    }
    if pr % 25 == 0 && pr > 0 {
        class_bonus += 4.0;
    }
    // Very small dead space is excellent (near-perfect fit).
    if pr <= 2 {
        class_bonus += 25.0;
    } else if pr <= 5 {
        class_bonus += 12.0;
    } else if pr <= 10 {
        class_bonus += 5.0;
    }
    // Dead space in the awkward band 11..=19 is nearly unusable (items >= 10,
    // so only tiny items fit): penalize heavily.
    if pr >= 11 && pr <= 19 {
        class_bonus -= 15.0;
    } else if pr >= 20 && pr <= 29 {
        class_bonus -= 4.0;
    }
    score -= class_bonus;

    // Lookahead harmony: does the next item fit the post-residual?
    if next_item_size > 0 && next_item_size <= pr {
        // Exact harmonic match (pr is a multiple of next item size) is ideal.
        if pr % next_item_size == 0 {
            score -= 10.0;
        } else {
            let nxt_post = pr - next_item_size;
            if nxt_post <= 5 {
                score -= 8.0;
            } else if nxt_post <= 15 {
                score -= 3.0;
            } else {
                score -= 1.0;
            }
        }
    } else if next_item_size > pr && next_item_size > 0 {
        // Next item won't fit here regardless; slight penalty for leaving
        // residual that nothing can chain into.
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large or current bins are mostly full / fragmented.
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Prefer new bin for large items, or late in the stream when open
        // bins have low mean residual (little room left overall).
        let mean_tightness = 1.0 - (mean_residual / bin_capacity as f64);
        let new_bin_bonus = 30.0 * fill_ratio + 20.0 * mean_tightness + 10.0 * progress;
        score -= new_bin_bonus;
        // Baseline: an empty bin has residual = capacity; normalize so the
        // comparison against open bins is fair.
        score -= (bin_capacity - post_residual) as f64 * 0.0;
        score -= bin_capacity as f64 * 0.55;
    }

    // Mild preference for filling bins that are already relatively full.
    let used = bin_capacity.saturating_sub(bin_residual);
    score -= (used as f64 / bin_capacity as f64) * 4.0;

    // Slight penalty for spreading across too many open bins.
    score += (open_bins_count as f64).sqrt() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (< next_item_size) are nearly useless.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // Dead space: cannot fit the next item at all.
            score += 18.0 * (1.0 - (post_residual as f64) / (next_item_size as f64).max(1.0));
        } else if post_residual == next_item_size {
            // Perfect fit for lookahead: strongly reward.
            score -= 25.0;
        }
    }

    // Zero residual is ideal (bin perfectly closed).
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tightness reward: fractional fill quality.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize tiny unusable gaps in absolute terms (<= 10 is dead for typical items).
    if post_residual > 0 && post_residual <= 10 {
        score += 14.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of bins, but only mildly so good fits win.
    let progress = (step_index as f64) / (total_items.max(1) as f64);
    score += 0.35 * (open_bins_count as f64).sqrt() * (0.5 + 0.5 * progress);

    // New-bin candidate (empty bin): penalize unless current bin would leave bad dead space.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual > 0
            && post_residual < next_item_size.min(10);
        score += if bad_fit { 0.0 } else { 26.0 };
        // Empty bin leaves max residual; add its residual cost too.
        score += 10.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below mean (tighter bins).
    score += 0.10 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
