}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    let mut score = post;

    // Penalize unusable dead space super-linearly (small leftovers are fine, mid-sized gaps are waste).
    let waste_frac = post / cap;
    score += 30.0 * waste_frac * waste_frac;

    // Reward tight fits (post_residual near zero).
    score -= 12.0 * (1.0 - waste_frac).powi(4);

    if bin_residual == bin_capacity {
        // New-bin candidate: strongly discourage opening a new bin when existing bins fit,
        // unless this is the only option (fitting_bins_count == 0 refers to other bins).
        if fitting_bins_count == 0 {
            score -= 5.0; // last resort: allow new bin
        } else {
            score += 45.0 + 0.6 * mean_residual + 2.0 * open_bins_count as f64;
        }
    } else {
        // Existing bin: mild bonus for reusing bins, stronger late in the stream.
        score -= 3.0 + 5.0 * progress;

        // Lookahead: if the next item exactly fills the post residual, big reward.
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 20.0;
            } else if post_residual >= next_item_size {
                score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
            } else {
                // Next item won't fit here; slight penalty if this bin would be nearly empty after.
                if post_residual > bin_capacity / 2 {
                    score += 4.0;
                }
            }
        }
    }

    // Prefer bins with below-average residual (concentrate fill).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // Slight pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr;

    // Quadratic-cubic coupling: as stream progresses, penalize large residuals more (dead space matters later)
    score += 12.0 * norm_pr * norm_pr * (0.5 + progress) * cap * 0.1;
    score -= 8.0 * norm_pr * norm_pr * norm_pr * (1.0 - progress) * cap * 0.1;

    // Coupling with mean residual: bins deviating from mean are penalized smoothly
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 + progress);

    // Lookahead coupling: reward residuals that can still hold the next item, smoothly
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 4.0 * (gap / cap) * (gap / cap) * cap * 0.2;
    }

    // Last-chance bin: strong smooth reward scaled by tightness of fit
    if fitting_bins_count == 1 && bin_residual >= item_size {
        let tightness = (bin_residual - item_size) as f64 / cap;
        score -= 15.0 * (1.0 - tightness) * (1.0 + 0.5 * progress);
    }

    // New-bin candidate: penalize opening a new bin progressively more as stream advances
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo 10 define "usable" classes.
    let r = post_residual % 10;
    let dead_penalty = match r {
        0 => -6.0,               // perfectly aligned residual, reusable by common sizes
        1 | 2 | 3 => 4.0,        // slivers: nearly dead space
        4 | 5 | 6 => 1.5,        // half-class: can host medium items
        _ => 2.5,                // 7..9: awkward but sometimes usable
    };
    score += dead_penalty;

    // Zero residual is perfect packing.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit reward: item nearly fills the bin.
    let fill = item_size as f64 / bin_capacity as f64;
    if fill > 0.85 {
        score -= 12.0 * (fill - 0.85);
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Harmonic pairing: exact modular match with next item is gold.
            let pair = post_residual - next_item_size;
            if pair % 10 == 0 {
                score -= 10.0;
            } else {
                score -= 4.0;
            }
        } else {
            // Bin becomes useless for the next item; penalize proportionally to waste.
            score += 3.0 + (next_item_size as f64 - post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a bin should only win when the fit here is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin; make it competitive but not dominant.
        score = 55.0 + 0.1 * mean_residual;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 5.0; // big next item may prefer fresh space
        }
        if open_bins_count == 0 {
            score -= 40.0; // must open when nothing is open
        }
    }

    // Progress modulation: pack tighter early, relax near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    // Spread awareness: many open bins -> prefer consolidating into low-residual bins.
    if open_bins_count > 3 {
        score += (mean_residual - post_residual as f64) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny slivers are dead space
    } else if post_residual < 20 {
        score += 15.0;
    } else {
        // Larger residuals: mild convex penalty so big gaps are discouraged but not fatal
        let r = post_residual as f64;
        score += 0.05 * r * r / bin_capacity as f64;
    }

    // Reward perfect fit
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // blocking the next item
    }

    // Mean residual coupling: prefer bins whose residual is below mean (tighter bins)
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when existing bins would waste badly
    if bin_residual == bin_capacity {
        score = 30.0 + open_bins_count as f64 * 0.4;
        if fitting_bins_count == 1 {
            score += 50.0; // never open a new bin when it's the last chance
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing next item with this one in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step lookahead match: post_residual == next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - diff / (bin_capacity as f64));
        // Perfect match: strong bonus
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // If the next item cannot fit in the post residual, penalize dead space
        if (post_residual as u32) < next_item_size {
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: just minimize waste
        score = post_residual as f64;
    }

    // Penalize tiny unusable residuals (dead space) non-linearly
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New empty bin candidate: penalize mildly unless it's the only option;
    // opening bins early wastes capacity, but allow when current bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 45.0 };
        score += pressure;
        // Slight discount when many items remain and mean residual is low (bins nearly full)
        score -= 0.05 * mean_residual;
    }

    // Slight preference for fuller bins relative to mean residual
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Progress-aware tight packing: later in the stream, avoid fragmentation more
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * 0.1 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;

    // Base: prefer minimizing leftover space (best-fit core).
    let mut score = post;

    // Reward tight fits: post_residual as a fraction of capacity.
    let tightness = post / cap;
    score += tightness * 25.0;

    // Penalize dead space that is too small to be useful later
    // (below the minimum item size the stream can produce), but
    // reward "perfect-ish" fits strongly.
    let min_item = 1.0f64;
    if post > 0.0 && post < min_item * 2.0 {
        score += 10.0;
    }
    if post == 0.0 {
        score -= 15.0; // perfect fit
    }

    // Lookahead coupling: if the next item can fit into the post-residual,
    // leaving that space is valuable -> reward; otherwise the residual is
    // more likely to become waste -> mild penalty.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= (1.0 - post / cap) * 8.0;
        } else {
            score += (nxt - post) / cap * 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Time horizon: early in the stream, be more conservative about
    // fragmenting bins (long stream ahead -> keep residuals large);
    // late in the stream, squeeze hard.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post / cap) * 5.0;

    // Global state: many open bins with large mean residual -> we have
    // slack; prefer reusing bins with big residuals less aggressively
    // (keep them for bigger items). Few open bins -> be flexible.
    let openness = (open_bins_count as f64).ln1p();
    score += (mean_residual - post) / cap * openness * 2.0;

    // New-bin candidate handling: an empty bin has full residual.
    // Only choose it when no open bin offers a decent fit, i.e. when
    // the item is large relative to available residuals. Penalize the
    // empty bin mildly so it wins only when open bins score badly.
    if bin_residual == bin_capacity {
        score += 12.0 + (item / cap) * 20.0;
        // But if this is a big item and few bins fit it, allow new bin.
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_frac = post / cap;
    let fit_frac = item_size as f64 / cap;

    // Base: prefer small post-residual, with smooth non-linear penalty that
    // grows super-linearly for medium dead space but relaxes near-full bins.
    let mut score = post
        - 12.0 * (1.0 - post_frac).powi(3) * post_frac
        + 18.0 * post_frac * (1.0 - post_frac) * (0.5 + 0.5 * progress);

    // Tightness reward: coupling of fill fraction with stream progress.
    score -= 10.0 * fit_frac * fit_frac * (1.0 + progress);

    // Penalize residual close to but not at zero (unusable gap), smoothly.
    score += 8.0 * (post_frac * (1.0 - post_frac)).powi(2) * (1.0 - progress);

    // Mean-residual coupling: prefer bins deviating below the mean residual
    // (concentrate filling), scaled smoothly.
    score += 0.05 * (mean_residual - bin_residual as f64).max(0.0) * (0.5 + progress);

    // Lookahead: if next item fits in the post-residual, reward strongly.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Smooth penalty when next item cannot follow into this bin.
        score += 3.0 * (1.0 - (next_item_size as f64 / cap)) * post_frac;
    }

    // New-bin candidate handling: only attractive when this is the last
    // fitting bin (scarcity) and stream is not just starting.
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;
    if is_new_bin {
        if fitting_bins_count <= 1 {
            score -= 15.0 * (1.0 - progress) * 0.0 + 15.0 * (0.3 + 0.7 * progress);
        } else {
            score += 25.0 + 10.0 * open_bins_count as f64;
        }
    }

    // Last-chance bonus for existing bins when few can fit the item.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 8.0 * (1.0 + 0.5 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into
    // capacity fractions. Residuals in the lowest "usable" classes are good.
    let cls = post_residual / 10; // integer division threshold classes (0..=10)
    match cls {
        0 => score -= 30.0,                 // near-perfect fill
        1 => score -= 20.0,                 // excellent
        2 => score -= 12.0,                 // good
        3 => score -= 6.0,                  // decent
        4 | 5 => score -= 2.0,              // neutral band
        6 | 7 => score += 6.0,              // awkward dead space
        8 => score += 12.0,                 // large but not large enough
        _ => score += 18.0,                 // nearly empty bin being nibbled
    }

    // Modulo arithmetic on post_residual: residuals that divide the capacity
    // nicely (multiples of 10, 20, 25, 50) pair well with common item sizes.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0;
    } else if pr % 50 == 0 {
        score -= 14.0;
    } else if pr % 25 == 0 {
        score -= 9.0;
    } else if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 2.0;
    } else {
        score += 3.0; // ragged residual, unlikely to be exactly filled later
    }

    // Coupling with lookahead item (k=2): reward residuals that can host the
    // next item, penalize near-misses (dead space just below next size).
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // extra reward if next item fills residual exactly or near-exactly
            let gap = pr - next_item_size;
            if gap <= 5 {
                score -= 12.0;
            } else if gap <= 15 {
                score -= 4.0;
            }
        } else if pr > 0 && next_item_size - pr <= 10 {
            // tantalizing near-miss: dead space that almost fits the next item
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }
    // Many fitting bins means this choice is less critical; slight penalty
    // for dumping into a crowded field.
    if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0).min(5.0);
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // the current item is large (would leave tiny dead space elsewhere) or
    // when existing residuals are too fragmented to be useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let frag = (mean_residual - post_residual as f64).abs();
        // Base penalty keeps new bins from winning trivially; relax it when
        // the item is big (harmonic class of item itself) or late in stream.
        let mut nb = 20.0;
        if item_size >= 70 {
            nb -= 18.0;
        } else if item_size >= 50 {
            nb -= 10.0;
        }
        if mean_residual < 15.0 {
            nb -= 12.0; // existing bins nearly full -> fresh bin reasonable
        }
        if frag > 30.0 {
            nb -= 5.0;
        }
        if progress > 0.8 {
            nb -= 3.0;
        }
        score += nb;
    }

    // Mild preference for tighter bins early (first-fit flavor) via mean
    // residual deviation: bins tighter than average get a bonus.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.15;

    // Small normalized tiebreaker on wasted fraction of capacity.
    score += (post_residual as f64 / cap) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gap <= 10 is essentially dead space (min item size is 1..100, but tiny
    // gaps rarely get reused); gap 0 is perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 5 {
        score += 25.0; // near-dead gap: penalize hard
    } else if post_residual <= 10 {
        score += 15.0;
    } else if post_residual <= 20 {
        score += 6.0;
    }

    // Reward placements that leave a gap reusable by the lookahead item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0;
        } else {
            // lookahead cannot fit in the gap -> dead-space risk
            score += 5.0;
        }
    }

    // Tightness reward: fraction of bin filled by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.35 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: make the empty bin attractive only when it is a
    // genuinely better strategic choice. Base penalty keeps it competitive
    // only against bins that would create bad dead space.
    if bin_residual == bin_capacity {
        score += 30.0 + 2.0 * open_bins_count as f64;
        // Opening a new bin is fine early on or when item is large.
        score -= 25.0 * fill_ratio;
        score -= 10.0 * (1.0 - progress);
        // If mean residual across open bins is large, spreading is cheap.
        score -= (mean_residual / bin_capacity as f64) * 8.0;
    }

    // Slight preference for bins tighter than the average residual.
    score -= (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 200.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, strongly reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 150.0 - next_fit_quality * 1.5;
    } else if next_item_size > 0 {
        // next item won't fit here: penalize wasting a good bin on a bad fit
        score += 40.0;
    }

    // Relative to mean residual: prefer bins with less residual than average (tighter bins)
    let rel = (bin_residual as f64) - mean_residual;
    score += rel * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        score += 60.0;
        // opening new bin is better if next item is large and current post_residual is large waste
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 30.0;
        }
    }

    // Early in stream: be conservative, keep bins flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 15.0;

    // More open bins: slight pressure to fill existing ones rather than open more
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 + 0.35 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 {
        // Reward bins where the next item fits snugly afterwards.
        score -= 6.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly so we only open when no good fit exists,
    // but relax as stream progresses and bins accumulate.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score += 18.0 + 20.0 * (1.0 - progress) / pressure;
    }

    // Prefer bins whose residual is close to the mean residual (balance load).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Mild bonus for bins with small residuals overall (fill nearly-full bins).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling: residual^2 normalized, damped by stream progress.
    let pr_norm = pr / cap;
    score += 18.0 * pr_norm * pr_norm * (1.0 - progress);

    // Reward tight fits with a smooth cubic term on fill ratio.
    let fill = 1.0 - pr_norm;
    score -= 14.0 * fill * fill * fill;

    // Lookahead: smooth reward if next item can use the remaining space.
    if next_item_size > 0 {
        let fits = (next_item_size as f64 <= pr) as f64;
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 10.0 * fits * (1.0 - gap) * (1.0 - progress);
        score += 6.0 * (1.0 - fits) * (pr_norm * pr_norm);
    }

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could fit; smooth coupling with
    // open-bin count and mean residual (many open bins with slack => reuse them).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let slack = (mean_residual / cap).max(0.0);
        score += 30.0 + 8.0 * (open_bins_count as f64).sqrt() + 20.0 * slack * (1.0 - progress);
        // Allow new bin if item is huge relative to typical residuals (smooth term).
        score -= 25.0 * (item_size as f64 / cap) * (1.0 - slack);
    }

    // Mild diversity pressure: bins far from mean residual are slightly discouraged.
    score += 2.0 * ((bin_residual as f64 - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bucket by integer division on C/5
    let c = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post / (c / 5.0)).floor() as f64; // 0..5 harmonic class

    // Reward tight fits: small post_residual gets strong subtraction
    score -= (c - post) / c * 12.0;

    // Penalize "dead zone" residuals that can host few typical items
    if post > 0.0 && post < 10.0 {
        score += 25.0; // unusable sliver
    }

    // Harmonic class coupling: mid classes (2,3) are valuable dead-space sinks
    match class as u32 {
        0 => score -= 8.0,                 // near-perfect fill
        1 => score -= 3.0,                 // decent
        2 => score += 0.0,
        3 => score += 4.0,
        4 => score += 8.0,                 // large leftover, but reusable
        _ => {}
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = post - nxt;
            score -= (c - slack) / c * 10.0;
            // exact match is ideal
            if slack == 0.0 {
                score -= 15.0;
            }
        } else {
            score += 6.0; // next item won't reuse this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Many fitting bins: mild penalty to prefer consolidation
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(4.0);
    }

    // Empty new-bin candidate: default worse than good fits, but better than bad fits
    if bin_residual == bin_capacity {
        score = c * 0.55 + mean_residual * 0.15;
        // late in stream, or few open bins, opening is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 10.0 + open_bins_count as f64 * 0.5;
    }

    // Modulo tie-breaker on post_residual to spread harmonic classes
    score += (post_residual % 7) as f64 * 0.25;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly useless.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        // Unusable sliver: heavy penalty scaled by how close to zero it is.
        score += (10 - post_residual) as f64 * 8.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Moderate gaps (10..30) are risky unless next item can use them.
    if post_residual >= 10 && post_residual < 30 {
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0; // lookahead item fits the gap -> good
        } else {
            score += 12.0;
        }
    }

    // Prefer bins whose residual is tight relative to item (high fill ratio).
    let fill = item_size as f64 / bin_residual as f64;
    score -= fill * 20.0;

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: many open bins -> discourage spreading, favor new-bin only if fits are bad.
    let pressure = open_bins_count as f64 * 0.5;
    score += pressure * (1.0 - fill);

    // New-bin candidate: only attractive when item barely fits anywhere
    // (i.e., item is large relative to residual) or open-bin count is low.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a bin; discounted for large items that need space.
        score = 45.0 - tightness * 30.0 + pressure;
        if fitting_bins_count <= 1 {
            score -= 20.0; // few alternatives -> new bin is fine
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0; // next item fits nicely in fresh bin
        }
    }

    // Slight preference for using bins with residuals below mean (tight packing).
    if bin_residual != bin_capacity {
        let d = bin_residual as f64 - mean_residual;
        score += d * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
