            score -= 30.0; // chain of perfect fits
        } else if nxt_post < 10 {
            score += 12.0; // next item would create dead space
        } else {
            score -= 5.0;
        }
        // modulo harmony: next item divides post_residual class
        if pr % next_item_size.max(1) == 0 && next_item_size > 0 {
            score -= 8.0;
        }
        let _ = nxt;
    }
    if next_item_size > 0 && pr < next_item_size && pr >= 10 {
        score += 10.0; // bin becomes dead for the known next item
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: keep fresh bins attractive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64) * 8.0 + mean_residual * 0.4;
        score = cap - crowded * 0.5; // baseline ~100 minus crowding pressure
        if fitting_bins_count == 0 {
            score -= 50.0; // nothing fits: must open
        }
    }

    // Slight preference for tighter (fuller) bins overall
    score -= (1.0 - frac) * 5.0;

    // Progress modulation: late in stream, tighten more aggressively
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
