pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize large dead space quadratically (hard-to-fill leftovers).
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: reward if the next item can fit into the post-residual (chain packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item won't chain here; penalize proportionally to the leftover gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.6 * gap.min(60.0);
        }
    } else {
        // Last item: just minimize final waste aggressively.
        score -= 40.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
        if post_residual <= 10 {
            score -= 30.0; // near-perfect fill in last chance bin
        }
    }

    // New-bin candidate handling: make empty bins attractive only when existing
    // fits are poor or mean residual is large relative to item.
    if bin_residual == bin_capacity {
        let poor_fit_penalty = (bin_capacity as f64 - item_size as f64) * 1.1;
        let crowd_bonus = (open_bins_count as f64).ln().max(0.0) * 8.0;
        let mean_pull = (mean_residual - item_size as f64).abs() * 0.4;
        score = score.max(0.0) + poor_fit_penalty - crowd_bonus - mean_pull;
        // Time factor: late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild preference for bins with residual close to mean (balance load).
    if bin_residual != bin_capacity {
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    // Few open bins: slight bonus to fill existing bins rather than sprawl.
    score -= 2.0 * (open_bins_count as f64).min(10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let x = pr / cap; // normalized post residual in [0,1]

    // Non-linear waste penalty: quadratic coupling with stream progress
    score += 6.0 * x * x * (0.5 + progress);

    // Reward tight fits: cubic smooth term
    score -= 4.0 * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Lookahead coupling: penalize if next item cannot use this residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 3.0 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 1.5 * (pr - nxt) / cap;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0;
    }

    // Penalize crowding many bins with high mean residual (poor utilization)
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // New-bin candidate: mild penalty so it only wins when open bins are bad
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "waste bands".
    // Residuals that are small multiples of common item sizes (10,20,25,50)
    // are reusable; others are dead space.
    let pr = post_residual;
    let class = pr % 10;
    let harmonic_bonus: f64 = if pr == 0 {
        -60.0 // perfect fit
    } else if class == 0 {
        -18.0 // multiple of 10: highly reusable
    } else if pr % 25 == 0 {
        -14.0
    } else if pr % 5 == 0 {
        -6.0
    } else {
        8.0 + class as f64 // odd residue: dead-space penalty
    };
    score += harmonic_bonus;

    // Integer-division thresholds: does post_residual fit the lookahead item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits: reward scaled by how snugly
            let snug = (pr - next_item_size) as f64;
            score -= 22.0 - snug * 0.25;
        } else {
            // lookahead would be stranded in this bin
            score += 14.0;
        }
    } else {
        // last item: only post_residual matters, tighten aggressively
        score -= 10.0;
    }

    // Fraction of capacity consumed: reward near-full bins (harmonic of capacity).
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        if fitting_bins_count > 1 && mean_residual >= item_size as f64 + 20.0 {
            score += 25.0; // good fits exist, keep them intact
        } else {
            score -= 12.0 + fragmentation * 0.1;
        }
    }

    // Late-stream pressure: consolidate to close bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 + (open_bins_count as f64).ln().max(0.0);

    // Penalize leaving residual in the awkward 1..9 band (worst harmonic class).
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item (<= 8)
    // are almost certainly wasted, so punish them hard.
    if post_residual > 0 && post_residual <= 8 {
        score += 60.0;
    } else if post_residual > 8 && post_residual < 20 {
        // Moderately awkward gaps: only items of narrow range can use them.
        score += 18.0;
    }

    // Reward very tight fits (perfect packing) with a strong discount.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 4 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement sets up a chain fill — reward it.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 8 {
        score -= 35.0;
    }
    // If next item cannot use the post residual at all, dead space is more likely.
    if next_item_size > post_residual && post_residual > 0 {
        score += 10.0;
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && post_residual > 8 {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than spreading; penalize the new-bin candidate implicitly through residual
    // (full residual) plus an explicit term.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0) * (4.0 + 6.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, softened when few bins are open
        // early in the stream.
        score += 25.0 + pressure;
    }

    // Slight preference for bins whose residual is close to the item (best-fit flavor)
    score += (bin_residual as f64 - item_size as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Base: prefer tight fits (low post_residual), with mild nonlinearity
    score += 0.5 * (post / cap) * (post / cap) * cap;

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // next item can't use this residual: penalize dead space, worse if large
        score += 6.0 * (post / cap) * (post / cap);
    }

    // Prefer bins whose residual is below mean (using up crowded bins)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    } else {
        score += 2.0 * ((bin_residual as f64) - mean_residual) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in stream: mild preference for filling existing bins over opening new
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more early, allow later
        score += 8.0 + 10.0 * progress;
    } else {
        score -= 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if the next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64) / cap;
        } else {
            // next item cannot use this leftover: mild penalty scaled by wasted space
            score += 4.0 * post_residual as f64 / cap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: neutral-ish base, but discourage opening a new bin
    // when a good fit exists elsewhere; encourage it when existing residuals are tight.
    if bin_residual == bin_capacity {
        score = cap * 0.55;
        if fitting_bins_count > 0 {
            // only open new bin if existing bins fit poorly (large leftover after best fit unknown,
            // so use mean residual as proxy: small mean residual => existing bins nearly full)
            if mean_residual < item_size as f64 * 0.6 {
                score -= 20.0;
            } else {
                score += 30.0 + 10.0 * fit_ratio;
            }
        }
        // late in stream, avoid proliferating bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Global balance: prefer bins whose residual deviates favorably from the mean
    score += 3.0 * (bin_residual as f64 - mean_residual) / cap;

    // Slight preference for more-filled bins as stream progresses
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 {
        (step_index as f64 + 1.0) / (total_items as f64)
    } else {
        0.0
    };

    // Normalized fill ratio of this bin after placement
    let fill = 1.0 - (post_residual as f64 / bin_capacity as f64);

    // Non-linear polynomial coupling: reward high fill, amplified as stream progresses
    let fill_term = fill * fill * (1.0 + fill * (1.0 + 3.0 * progress));
    score -= 40.0 * fill_term;

    // Dead-space penalty: quadratic in post_residual, weighted by progress
    // (late in stream, small residuals are more valuable to eliminate)
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * dead * dead * (0.5 + progress);

    // Lookahead coupling: reward if the next item fits into the post residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
        score -= 12.0 * snug * (0.4 + 0.6 * progress);
    } else if next_item_size > post_residual && post_residual > 0 {
        // penalize residuals that cannot host the lookahead item
        score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Slight preference to spread load when many bins are open with high mean residual
    score += 0.05 * (open_bins_count as f64).sqrt() * (mean_residual - post_residual as f64).abs() * 0.1;

    // Mild penalty for opening a brand-new bin when good fits exist late in the stream
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals in small "dead" classes
    // (1..=9) are nearly unusable for items >=10, so penalize them hard.
    let dead_class = if post_residual == 0 { 0.0 } else if post_residual < 10 { 60.0 } else { 0.0 };
    score += dead_class;

    // Modulo-10 harmonic: perfect decadal residuals are ideal (fit any 10-aligned item).
    let r10 = post_residual % 10;
    score += (10 - r10) as f64 * 1.5;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 80.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a chain placement — reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 50.0;
        } else if post_residual >= next_item_size {
            // harmonic class of next item vs post residual divisibility
            if post_residual % next_item_size == 0 {
                score -= 25.0;
            }
            score += (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot follow here; penalize proportional to leftover waste class
            score += (next_item_size - post_residual).min(9) as f64 * 2.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin before opening new.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // mean residual across open bins is small (all bins nearly full) or the
    // item is large. Otherwise discourage so we fill existing bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_frac = mean_residual / bin_capacity as f64;
        // fresh-bin bonus grows when existing bins are nearly exhausted
        let fresh_bonus = 30.0 * (1.0 - mean_frac) - 10.0 * progress;
        score += fresh_bonus;
        // large items prefer fresh bins if they'd leave dead space elsewhere
        if item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual is harmonically aligned with item size class
        let item_class = item_size / 10;
        let bin_class = bin_residual / 10;
        if bin_class >= item_class {
            score -= 5.0;
        }
    }

    // Mild preference for tighter bins among open ones (lower residual = better fit).
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the minimum item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver
    } else if post_residual < 20 {
        score += 25.0; // nearly unusable
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Prefer tight relative fit.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Open-bin pressure: discourage spreading across many bins unless fit is excellent.
    if open_bins_count > 4 {
        score += 0.6 * (open_bins_count as f64 - 4.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 15.0; // dead space relative to the known next demand
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    // or open bins are very full on average.
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 2.0 + mean_residual / 10.0;
        score += 30.0 + pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: open new bin
        }
    }

    // Slight early-stream preference for keeping bins open and flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.15 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: waste = post_residual, but scale relative to capacity.
    score = post_residual as f64 / bin_capacity as f64 * 100.0;

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect 2-chain
        } else if post_residual >= next_item_size {
            // reward proportionally to how well next item fills post_residual
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * fill;
        } else {
            // next item won't fit here: penalize small unusable leftovers
            if post_residual < 10 {
                score += 25.0; // dead space
            } else {
                score += 8.0 * (1.0 - post_residual as f64 / 100.0);
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: only attractive if current residuals are tight/fragmented.
    if bin_residual == bin_capacity {
        // baseline score for a fresh bin; penalize if open bins can still absorb items
        score += 55.0;
        if mean_residual > item_size as f64 * 1.5 {
            score += 30.0; // plenty of room elsewhere, don't open new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // big item coming, fresh bin may be useful
        }
    }

    // Prefer tighter bins (small residual before placement) slightly.
    score += 0.05 * (bin_residual as f64 - post_residual as f64) * (post_residual as f64 / bin_capacity as f64);

    // Mild pressure toward consolidating bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0 * (mean_residual / bin_capacity as f64);

    // Favor bins with residuals below mean (tighter packing).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize bins whose residual is close to item size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize post-residual dead space that is too small to hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead: reward bins whose post-residual exactly or nearly fits next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            score -= 8.0 * (1.0 - gap as f64 / bin_capacity as f64);
        } else {
            score += 4.0; // next item won't fit here; mild penalty
        }
    }

    // Last-chance bin: strongly favor using the only bin that can fit.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin wastes the residual of this bin.
    if bin_residual == bin_capacity {
        // Only attractive when current bins are crowded or this item fits nothing well.
        let pressure = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Prefer new bin when existing residuals are large (poor fits) and late in stream.
        score = 40.0 + 60.0 * pressure + 20.0 * time_frac + post_residual as f64;
        if fitting_bins_count <= 2 {
            score -= 35.0; // few alternatives: opening a bin is reasonable
        }
    } else if fitting_bins_count > 0 {
        // Mild bonus for reusing bins to keep bin count low.
        score -= 3.0;
    }

    // Global state: when many bins are open with large mean residual, discourage
    // leaving medium dead space (fragmentation control).
    let frag = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * frag;

    // Late-stream tightening: as stream progresses, be greedier about tight fits.
    let horizon = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * horizon * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Tight fits favored: quadratic reward for small post_residual
    let tightness = 1.0 - post / cap;
    score -= tightness * tightness * 18.0;

    // Dead-space penalty grows non-linearly with post_residual
    let dead = (post / cap).powi(3);
    score += dead * 25.0;

    // Stream progress coupling: early on prefer spreading (new bins),
    // late prefer tight packing
    let spread_bias = (1.0 - progress) * (1.0 - progress) * 8.0;
    score += spread_bias * (post / cap);

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let ratio = next_item_size as f64 / post;
        score -= 12.0 * (1.0 - (ratio - 0.5).abs() * 2.0);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate calibration: penalize opening new bins when
    // open bins have decent mean residual and many bins are open
    if bin_residual == bin_capacity {
        score += 6.0 + progress * 10.0 + (open_bins_count as f64).sqrt() * 1.5;
        if mean_residual > item_size as f64 {
            score -= 2.0;
        }
    }

    // Mean-residual coupling: prefer bins close to mean residual (balance)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += dev * dev * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: small leftovers are dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 25.0; // perfect fit
    } else if pr < 10 {
        score += 40.0; // tiny dead space, unusable for min-size items
    } else if pr <= 20 {
        score += 12.0;
    } else if pr <= 33 {
        score += 4.0;
    } else if pr <= 50 {
        score -= 3.0;
    } else {
        score -= 6.0;
    }

    // Modulo structure: residuals that are multiples of common item sizes
    // (10/20/25/50) are reusable "harmonic" pockets.
    if pr % 10 == 0 { score -= 5.0; }
    if pr % 25 == 0 && pr > 0 { score -= 3.0; }
    if pr % 7 == 0 && pr > 0 { score -= 1.0; }

    // Lookahead: reward if next item fits in the post residual (chaining),
    // penalize if next item would leave an even worse class.
    if next_item_size > 0 {
        if next_item_size <= pr {
            score -= 10.0;
            // exact chain fit is golden
            if pr - next_item_size < 10 && pr == next_item_size { score -= 5.0; }
            if (pr - next_item_size) % 10 == 0 { score -= 2.0; }
        } else {
            score += 8.0; // next item won't fit here; bin likely closes
        }
        // Harmonic threshold classes of the next item
        let nclass = match next_item_size {
            0..=20 => 0,
            21..=40 => 1,
            41..=60 => 2,
            _ => 3,
        };
        let pclass = match pr {
            0..=20 => 0,
            21..=40 => 1,
            41..=60 => 2,
            _ => 3,
        };
        if nclass >= pclass { score -= 2.0; } else { score += 2.0; }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when current bin would be
    // badly fragmented; otherwise discourage spreading.
    if bin_residual == bin_capacity {
        let tight = post_residual as f64 / bin_capacity as f64;
        if tight < 0.2 {
            score -= 8.0; // item is huge relative to capacity, fresh bin fine
        } else {
            score += 18.0; // prefer existing bins for normal items
        }
        // late in the stream, consolidation matters more
        let t = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * t;
    }

    // Prefer filling bins below mean residual (tighter bins first).
    let diff = mean_residual - bin_residual as f64;
    score += 0.15 * diff;

    // Mild pressure to use many-open-bins situations efficiently.
    if open_bins_count > 4 && post_residual > 50 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits (perfect fills get a large discount).
    if post_residual == 0 {
        score -= 100.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 30.0 * tightness;
    }

    // Dead space is worse if the leftover gap cannot host the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 20.0;
    }

    // Open-bin pressure: discourage proliferation of bins, but keep last-chance bins attractive.
    score += 4.0 * open_bins_count as f64;
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Prefer bins whose residual deviates from the mean in a useful way
    // (a bin with less residual than average is more "loaded"; fill it first).
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Late in the stream, avoid leaving tiny fragments; early on, allow exploration.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 15.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New empty bin candidate: penalize opening a new bin unless the current
    // bins would leave very poor fits.
    if bin_residual == bin_capacity {
        score += 55.0 + 6.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual to next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        // Perfect chain: post_residual == next_item_size -> next item fills bin exactly
        if diff < 0.5 {
            score -= 60.0;
        } else if post_residual as f64 > nxt {
            // next item fits: reward proportionally to tightness
            score -= 25.0 * (nxt / post_residual as f64);
            // bonus if next item then leaves a small residue (< 10)
            let post2 = post_residual as f64 - nxt;
            if post2 < 10.0 {
                score -= 15.0;
            }
        } else {
            // next item won't fit here: penalize wasted lookahead potential
            score += 10.0 * (1.0 - nxt / (bin_capacity as f64));
        }
    }

    // Relative to mean residual: prefer bins whose post_residual deviates favorably
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        let dev = (post_f - mean_residual) / mean_residual;
        if post_f < mean_residual {
            score -= 8.0 * dev.abs().min(2.0);
        } else {
            score += 5.0 * dev.min(2.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New empty bin candidate: only attractive when it enables a perfect 2-step chain
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64 - item_size as f64).abs() < 0.5 {
            score -= 55.0;
        } else {
            score += 20.0; // discourage opening new bins by default
        }
    }

    // Penalize tiny dead space that can never be used by typical items
    if post_f > 0.0 && post_f < 10.0 {
        score -= 12.0; // nearly-perfect fill is great
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_f / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio through the stream (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative fill of this placement.
    let fill = item_size as f64 / bin_capacity as f64;

    // Reward tight fits: small post_residual relative to capacity.
    score -= 60.0 * (1.0 - post_residual as f64 / bin_capacity as f64) * fill;

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Slight penalty when many bins compete equally (prefer spreading load
    // across bins with larger residuals, i.e., best-fit dominance).
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead coupling: if the next item would fit the post-residual,
    // reward this placement (chain potential); otherwise penalize dead space
    // that neither the next item nor typical small items can use.
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        } else {
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Global state coupling: penalize bins whose residual deviates strongly
    // above the mean (prefer consuming bins closer to the fleet average),
    // modulated by how many bins are open.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev * (open_bins_count as f64).ln().max(1.0);

    // Early stream: be slightly more willing to open new bins (keep options
    // open); late stream: strongly prefer filling existing bins.
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin is attractive only when the
    // item is large or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced for large items.
        score = bin_capacity as f64 - 25.0 * fill;
        // If open bins can fit, make new bin slightly worse than a decent fit.
        if fitting_bins_count > 0 {
            score += 6.0;
        }
        // Late in the stream, opening new bins is more costly.
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = x * x * (1.0 - t) + 2.0 * x * x * x * t;
    score += 40.0 * poly;

    // Reward tight fits more strongly as the stream progresses
    let tight = 1.0 - x;
    score -= 30.0 * tight * tight * (0.5 + t);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dev = (pr as f64 - mean_residual) / cap;
    score += 15.0 * dev * dev;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - (gap / cap).abs());
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Slight preference for consolidating into fewer bins late in stream
    score += 0.05 * open_bins_count as f64 * (1.0 - t);

    // New-bin candidate: make empty bin mildly attractive only when current bin fit is poor
    if bin_residual == bin_capacity {
        score += 12.0 - 20.0 * tight * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which "resonance band" the leftover lands in.
    // Classes based on integer division thresholds of capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual / 10) % 4; // harmonic class buckets: 0..3

    // Reward small, "harmonically clean" residuals (tight fits).
    match class {
        0 => { score -= 30.0; }                       // near-perfect fit band
        1 => { score -= 10.0; }                       // decent band
        2 => { score += 5.0; }                        // mediocre dead space
        _ => { score += 15.0; }                       // large unusable leftover
    }

    // Non-linear penalty on wasted fraction of capacity.
    let waste = pr / c;
    score += 40.0 * waste * waste;

    // Lookahead coupling: if the next item can fit exactly in post_residual,
    // strongly reward this placement (chained fit).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if post_residual >= next_item_size {
            let chain_fit = (pr - ni).abs();
            score -= 20.0 * (1.0 - chain_fit / c);
            // harmonic match: next item divides residual evenly
            if next_item_size > 0 && post_residual % next_item_size == 0 {
                score -= 12.0;
            }
        } else {
            // next item cannot follow here; penalize slightly more if residual is small
            score += 8.0 * (1.0 - pr / c);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 25.0;
        if post_residual > 0 && post_residual < 10 {
            score -= 20.0; // almost perfect fit in the only option
        }
    }

    // New-bin candidate handling: an empty bin has large residual; make it
    // attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream position.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 45.0 - 10.0 * progress;
        // If many open bins already, discourage yet another one mildly.
        score += open_bins_count as f64 * 0.5;
        // But if mean residual across open bins is tiny, new bin is fine.
        if mean_residual < 10.0 {
            score -= 30.0;
        }
    } else {
        // Reward using existing bins, more so when bin residual is close to item.
        let tightness = 1.0 - (bin_residual - item_size) as f64 / c;
        score -= 15.0 * tightness * tightness;
        // Prefer bins whose residual is harmonically aligned with item size.
        if item_size > 0 && bin_residual % item_size == 0 {
            score -= 10.0;
        }
    }

    // Mean-residual drift correction: keep overall residual spread balanced.
    score += 0.05 * (mean_residual - pr).abs();

    // Small deterministic tie-breaker via step progression.
    score += 0.001 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: residuals too small for any item (min size 1..100 unknown,
    // but small gaps < 12 are almost always unusable) are heavily penalized.
    if post_residual > 0 && post_residual < 12 {
        score += 150.0;
    } else if post_residual < 25 {
        score += 40.0;
    }

    // Reward tight fits relative to capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open-bin pressure: with many open bins, discourage opening a new one
    // (this call is the empty-bin candidate when bin_residual == bin_capacity).
    if bin_residual == bin_capacity {
        score += 80.0 + 12.0 * open_bins_count as f64;
    } else {
        // Slight preference for bins that are already more filled.
        score += 10.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover == 0 {
            score -= 400.0;
        } else if leftover < 12 {
            score += 60.0; // would leave new dead space
        } else {
            score -= 50.0;
        }
    }

    // Mean-residual coupling: prefer bins below mean residual (more filled than average).
    score += 0.5 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let match_gap = (pr - nxt).abs();
        // Perfect lookahead match: big reward.
        if match_gap < 0.5 {
            score -= 45.0;
        } else if pr >= nxt {
            // Next item fits exactly-ish: reward proportional to closeness.
            score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
        } else {
            // Next item won't fit: penalize wasted residual relative to next item.
            score += 0.35 * (nxt - pr).min(40.0);
        }
        // Bonus if post_residual leaves room for next item AND the one after conceptually (tight packing).
        if pr >= nxt && pr - nxt < 10.0 {
            score -= 12.0;
        }
    }

    // Penalize large post_residual relative to mean residual (wasting space in fat bins).
    score += 0.25 * (post_residual as f64 - mean_residual).max(0.0);

    // Reward tight fits: small post_residual is good (already in base score).
    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current options are terrible.
    if bin_residual == bin_capacity {
        score += 55.0;
        // Allow new bin early in stream or when no bin gives a good lookahead fit is
        // handled implicitly: if all open bins score high due to dead space, new bin wins.
        if next_item_size > 0 && (next_item_size as f64 - post_residual as f64).abs() < 0.5 {
            score -= 40.0; // fresh bin perfectly matches next item
        }
    }

    // Mild penalty per open bin to encourage consolidation late in stream.
    score += 0.4 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: reward low post_residual non-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 4.0 + 0.05 * next_item_size as f64;
    }
    // Reward bins whose leftover exactly accommodates the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Penalize spreading across too many open bins when residuals are large.
    if open_bins_count > 2 {
        score += 0.15 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);
    }

    // Early in the stream, be slightly conservative (favor filling existing bins);
    // later, allow more freedom to open bins for good fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: open only if it promises a very good future fit
        // (e.g., next item nearly fills it) or late in the stream.
        let pull = 6.0 - 4.0 * progress;
        if next_item_size > 0 {
            score += pull + (next_item_size as f64 - post_residual as f64).abs() * 0.1;
        } else {
            score += pull;
        }
    }

    // Mild penalty for very large unusable leftovers relative to mean residual.
    if post_residual as f64 > mean_residual + 10.0 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, prefer filling bins loosely (waste tolerated); late, demand tight fits.
    let tightness = pr / cap;
    score += 30.0 * progress * tightness * tightness;

    // Non-linear penalty for leaving residual close to the next item's need
    // (dead space that the lookahead cannot use) — smooth via normalized gap.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx) / cap;
        let unusable = if pr >= nx { (gap * gap) } else { ((nx - pr) / cap).powi(2) * 0.5 };
        score += 25.0 * unusable;
    }

    // Reward near-perfect fits with a smooth saturating term.
    let fit_quality = 1.0 - (pr / cap).powi(2);
    score -= 20.0 * fit_quality * fit_quality;

    // Scarcity bonus: if this is the only fitting bin, smooth sigmoid-like reward.
    let scarcity = 1.0 / (1.0 + (fitting_bins_count as f64 - 1.0).exp());
    score -= 15.0 * scarcity;

    // Penalize bins far from mean residual (fragmentation), smoothly.
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: make it attractive only when no good fit exists,
    // via smooth coupling with post_residual of open bins (which is low for full bins).
    if bin_residual == bin_capacity {
        score = 0.6 * cap + 0.4 * pr + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover belongs to a
    // "usable" residue class (small, likely fillable later) get rewarded.
    let pr = post_residual;
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let class_bonus = match pr {
        0 => 60.0, // perfect fit, huge reward
        x if x <= eighth => 25.0,
        x if x <= quarter => 8.0,
        x if (x % 10) == 0 => 6.0, // residue aligned with item grid
        _ => 0.0,
    };
    score -= class_bonus;

    // Penalize post_residuals in awkward mid-range classes (dead space).
    if pr > quarter && pr < bin_capacity / 2 && (pr % 10) != 0 {
        score += 10.0;
    }

    // Lookahead coupling: if the next item exactly fills post_residual,
    // strongly favor this bin (harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            let pair_waste = (pr - next_item_size) as f64;
            score += pair_waste * 0.6;
        } else {
            // next item cannot use this residue: mild penalty proportional
            // to how much residue will be stranded
            score += (pr as f64) * 0.15;
        }
    } else {
        // last item: only perfect fits matter
        if pr == 0 { score -= 50.0; }
    }

    // Tightness ratio reward: fraction of the bin consumed by this item.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 20.0;

    // Last-chance bin: if this is the only fitting bin, opening a new bin
    // wastes this residual entirely; reward using it unless fit is awful.
    if fitting_bins_count == 1 {
        score -= 18.0;
        if pr as f64 > cap * 0.4 { score += 12.0; } // but bad fits still penalized
    }

    // New-bin candidate handling: an empty bin has huge residual; make it
    // attractive only when no open bin fits well (post_residual small).
    if bin_residual == bin_capacity {
        // neutral baseline slightly above a good fit, below a bad fit
        score = cap * 0.55 + (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // prefer new bin if next item likely pairs with a fresh half
            if next_item_size >= bin_capacity / 2 { score -= 10.0; }
        }
        if fitting_bins_count == 0 { score -= 30.0; }
    }

    // Mild pressure to consolidate as stream progresses and bins accumulate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (mean_residual / cap) * 5.0;
    score += (open_bins_count as f64).ln().max(0.0) * 0.8;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space non-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 30.0 / (1.0 + tightness * 4.0);

    // Reward filling a bin nearly completely.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: only bin that fits -> strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, avoid opening new ones.
    let new_bin = (bin_residual == bin_capacity) as f64;
    score += new_bin * (8.0 + open_bins_count as f64 * 2.5);

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item almost fits, slight penalty for leaving a just-too-small gap.
    if next_item_size > post_residual && post_residual > 0 && (next_item_size - post_residual) <= 5 {
        score += 8.0;
    }

    // Mild pressure to close bins far below mean residual (consolidation).
    if !new_bin_bool(bin_residual, bin_capacity) && (bin_residual as f64) < mean_residual {
        score += 2.0;
    }

    score
}

#[inline]
fn new_bin_bool(bin_residual: u32, bin_capacity: u32) -> bool {
    bin_residual == bin_capacity
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits snugly into post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size < post_residual {
            let leftover = post_residual - next_item_size;
            score -= 30.0 * (1.0 - leftover as f64 / bin_capacity as f64);
        } else {
            // next item cannot follow: penalize dead space
            score += 0.35 * post_residual as f64;
        }
    }

    // Compare against mean residual across open bins
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Tight fit reward (small post residual is good)
    score -= 0.4 * (bin_capacity - post_residual) as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 40.0 + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 50.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally wasted space
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 25.0;

    // Penalize post_residual that cannot fit a typical future item (dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable sliver
    } else if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        score += 12.0; // residual can't fit lookahead item
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { fit_ratio.min(1.0) };
        // Opening a new bin is penalized unless current fits are bad
        score += 20.0;
        score -= pressure * 45.0;
        // Early in stream, more willing to open bins (build diversity)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
        // Many open bins with slack -> discourage new bin
        if mean_residual > 30.0 {
            score += (mean_residual - 30.0) * 0.4;
        }
    }

    // Mild preference for bins below mean residual (balance load)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 20.0 * poly;

    // Reward tight fits, stronger late in the stream
    score -= 15.0 * (1.0 - norm_pr).powi(3) * (0.5 + progress);

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 10.0 * (nxt - pr) / cap * (0.5 + progress);
        } else {
            score -= 5.0 * (1.0 - (pr - nxt) / cap) * progress;
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0 * (0.5 + progress);
    }

    // New-bin candidate: discourage unless residual is large relative to mean
    if bin_residual == bin_capacity {
        score += 12.0 + 10.0 * (1.0 - progress) - 4.0 * (mean_residual / cap);
    }

    // Mild diversification pressure
    score += (open_bins_count as f64).sqrt() * 0.5 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: low post_residual is desirable (tight fit).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Reward tight fits strongly (post_residual near 0).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    } else if post_residual <= 20 {
        score -= 4.0;
    }

    // Dead-space class: leftovers that are too small for the minimum item size (1..100 range,
    // but treat <10 as near-dead) are penalized, especially if next item cannot use them.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // leftover cannot host the lookahead item: penalize proportionally to its size
            score += post * 0.35;
            if post_residual <= 10 {
                score += 15.0; // dead-space class
            }
        } else {
            // leftover can chain: reward, more if the chain is tight
            let chain_waste = post_residual - next_item_size;
            score -= (bin_capacity as f64 - chain_waste as f64) * 0.05;
            if chain_waste == 0 {
                score -= 20.0; // perfect two-item fill
            }
        }
    } else {
        // Last item: only exact fits matter.
        if post_residual == 0 {
            score -= 40.0;
        }
    }

    // Modulo/harmonic class of post_residual relative to capacity quarters.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter;
    score += class as f64 * 3.0; // higher class (more empty) = worse

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it moderately unattractive unless it is a genuinely better
    // harmonic class (score already = post_residual = full capacity there).
    if bin_residual == bin_capacity {
        score += 8.0;
        // Early in the stream, opening bins is cheaper; late, consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Prefer bins whose residual is below mean (tighter bins first).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    // Harmonic coupling: item_size classes (small items fit anywhere; large items
    // should go into bins where they leave a class-0 or class-1 remainder).
    let rem = post_residual % 10;
    if rem <= 2 {
        score -= 3.0; // near-multiple-of-10 leftovers are reusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: gaps too small for typical items are wasted.
    let dead_threshold = 12.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward bins whose residual tightly matches the item (good fit).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 20.0;

    // Penalize opening a new bin when open bins can still absorb the item,
    // unless this bin is the last chance to fit.
    if bin_residual == bin_capacity {
        // New-bin candidate: prefer it only when item is large or no good fit exists.
        if item_size >= 60 {
            score -= 15.0;
        }
        score += open_bins_count as f64 * 3.0;
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
    } else if fitting_bins_count == 1 {
        // Last fitting bin: strong preference to use it and avoid opening a bin.
        score -= 30.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    if open_bins_count > 4 {
        score += (open_bins_count as f64 - 4.0) * 2.0;
    }

    // Lookahead: if next item can use the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item cannot fit in post residual, mild penalty for fragmentation.
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 5.0;
    }

    // Stream progression: later in the stream, tighten up (avoid new bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 8.0;

    // Prefer bins below mean residual (they are tighter; keep loose bins for future).
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fill (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0; // perfect chain: this bin becomes exactly full
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot follow here; penalize leftover dead space
            let dead = (post_residual as f64).min(next_item_size as f64);
            score += 0.5 * dead;
        }
    }

    // Penalize post_residual that becomes unusable (below minimum item size 1..100 => small slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: make empty bin attractive only when open bins fit poorly
    if bin_residual == bin_capacity {
        // default mild penalty so existing bins are preferred when decent
        score += 15.0;
        // but if mean residual is small relative to item, opening fresh is better
        if (mean_residual as f64) < item_size as f64 * 1.2 {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            score -= 20.0;
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are good targets
    score -= 0.3 * (bin_residual as f64 - mean_residual);

    // Early stream: slightly discourage hoarding many bins early
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.3 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Time horizon: later in the stream -> tighten packing (penalize loose fits more).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 12.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Reward tight fits strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Dead-space penalty: residual too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual,
    // reward this bin heavily (perfect chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            // post-residual too small for the known next item -> dead space risk
            score += 10.0 * (1.0 - progress);
        }
    }

    // Global state coupling: prefer filling bins when many bins are open
    // (consolidation), but prefer opening fresh bins when few are open and fit is poor.
    let open_pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    score += open_pressure * (bin_residual as f64 - item_size as f64) * 0.15;

    // Mean residual alignment: bins whose residual is near the mean are "typical"
    // targets; extreme outliers either hoard space or are nearly full.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate: only attractive when no good fit exists among open bins
    // or the current fit would leave awkward space.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 0.6 * bin_capacity as f64;
        let no_alternatives = fitting_bins_count <= 1;
        if poor_fit || no_alternatives {
            score -= 15.0;
        } else {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Penalize large dead space non-linearly
    score += 18.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits (small post residual) especially late in stream
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.6 * progress);

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into resulting post_residual
    if next_item_size > 0 {
        if (post_residual as u32) >= next_item_size {
            score -= 8.0 + 6.0 * progress;
        } else {
            score += 4.0 * (1.0 - (pr - next_item_size as f64).abs() / cap);
        }
    }

    // Slight preference to keep mean residual spread balanced
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    let tight = (bin_capacity as f64 * 0.10).max(3.0);
    if post_residual <= tight as u32 {
        score -= 25.0;
    } else if post_residual <= 2 * tight as u32 {
        score -= 10.0;
    }

    // Penalize post_residuals in "dead zones": residues that few item sizes can fill.
    // Classify post_residual by modulo 10 class; classes near 0 (residual ~10,20,...)
    // are easy to fill, odd/small classes are harder.
    let r = post_residual % 10;
    match r {
        0 => score -= 6.0,          // exact decade residual: highly fillable
        1 | 2 | 3 => score += 8.0,  // tiny sliver: likely dead space
        8 | 9 => score += 4.0,      // awkward off-decade
        _ => {}
    }

    // Harmonic class of the item: large items (>= 50, half capacity) are precious;
    // placing them in a nearly-full bin is good.
    let half = bin_capacity / 2;
    if item_size >= half {
        score -= (item_size - half) as f64 * 0.5;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if post_residual - next_item_size <= tight as u32 {
            score -= 12.0;
        }
        // Next item shares a harmonic decade class with post_residual -> compatible.
        if (next_item_size % 10) == r {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item can't use this bin anyway; slight penalty for wasting tight fits.
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless post_residual would be tiny/dead).
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 20.0;
    }

    // New-bin candidate bias: an empty bin has post_residual == bin_capacity.
    // Prefer reusing open bins unless the empty-bin score would be genuinely low.
    if bin_residual == bin_capacity {
        // Opening new bins early in the stream is cheap; later it is costly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 + 40.0 * progress + (open_bins_count as f64).sqrt() * 3.0;
        // But if item is huge and no open bin fits well, new bin is fine:
        if item_size > bin_capacity * 3 / 4 {
            score -= 25.0;
        }
    }

    // Mild pressure toward balance with mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to plausibly hold a
    // future item are dead weight. Penalize the "unusable gap" band hard.
    let dead_threshold = 12.0f64;
    let pr = post_residual as f64;
    if pr > 0.0 && pr < dead_threshold {
        // The smaller the unusable sliver relative to the threshold, the worse.
        score += (dead_threshold - pr) * 6.0;
    }

    // Reward tight fits (small but still usable residual).
    let tightness = 1.0 - (pr / bin_capacity as f64);
    score -= tightness * 8.0;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few,
    // filling existing bins is cheap so reward it mildly.
    let pressure = (open_bins_count as f64).ln() + 1.0;
    score += pressure * 2.0;

    // New-bin candidate (empty bin): only attractive when the item is large
    // relative to typical residuals or no real bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0;
        if item_size >= 60 {
            score -= 12.0; // big items are fine to start fresh
        }
        if pr as f64 > mean_residual {
            score -= 4.0;
        }
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this residual; residual is likelier dead space
        score += pr * 0.05;
    }

    // Late in the stream, prefer closing bins tightly (less fragmentation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * pr * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    if post_residual == next_item_size && next_item_size > 0 {
        // exact 2-step chain: current item + next item fills bin
        score -= 500.0;
    }

    // Lookahead: penalize residuals that cannot host next item, reward those that can
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 30.0 + 0.5 * next_item_size as f64;
        } else {
            score += 40.0;
        }
        // near-match bonus: residual slightly above next item
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 && gap <= 10.0 {
            score -= 20.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Penalize creating large dead space (waste) nonlinearly
    if post_residual > 0 {
        if let Some(nx) = (next_item_size > 0).then(|| next_item_size) {
            if post_residual < nx {
                score += 0.8 * post_residual as f64;
            }
        }
    }

    // Late in stream: consolidate, avoid new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 150.0 * progress + 25.0;
    }

    // Many open bins: discourage opening more
    score += 2.0 * open_bins_count as f64 * if bin_residual == bin_capacity { 1.0 } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that can't fit the next item (wasted capacity).
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            score += 12.0 * (next_item_size - post_residual) as f64;
        } else if post_residual >= next_item_size {
            // Reward bins that can still accommodate the lookahead item.
            score -= 6.0;
        }
        // Perfect chain fit: item + next item exactly fills the bin.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // Penalize leaving a residual in the awkward zone that few future items fit.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Late in the stream: prefer closing bins out, penalize spreading across bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Many open bins: encourage filling existing ones rather than opening more.
    score += (open_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Compare against mean residual: bins below mean residual are "fuller", favor them.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New-bin candidate: neutral baseline with slight bias toward using open bins
    // unless they are all poor fits (handled by penalties above).
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: penalize post-residual, but non-linearly (waste grows quadratically).
    let mut score = norm_pr * (1.0 + 0.8 * norm_pr);

    // Smooth coupling with stream progress: early on, tolerate slack; late, be greedy.
    let progress_weight = 0.5 + 1.5 * progress;
    score *= progress_weight;

    // Reward tight fits (small post_residual relative to item size) via smooth term.
    let tightness = fit_ratio / (fit_ratio + norm_pr + 1e-6);
    score -= 1.2 * tightness;

    // Penalize dead space that next item cannot use (smooth interaction).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).max(0.0) / cap;
        score += 0.9 * gap * gap;
        // Reward leaving room exactly for the next item.
        let match_bonus = 1.0 - ((pr - next_item_size as f64) / cap).abs();
        score -= 0.6 * match_bonus.max(0.0);
    }

    // Last-chance bin: strongly favor using it (avoid opening a new bin).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    // Many open bins: prefer consolidation; few bins: prefer spreading.
    let spread = (open_bins_count as f64 / (1.0 + mean_residual / cap)).ln_1p();
    score += 0.15 * spread * norm_pr;

    // New-bin candidate: keep it neutral-to-slightly-high unless residual is large.
    if bin_residual == bin_capacity {
        score += 0.5 + 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward exact fills and tiny dead space,
    // penalize awkward mid-range leftovers that few future items can use.
    if post_residual == 0 {
        score -= 30.0; // perfect fill
    } else if post_residual < 10 {
        score -= 10.0; // nearly full, small dead space
    } else if post_residual <= 20 {
        score += 5.0; // awkward zone: too small for most items, too big to ignore
    } else if post_residual <= 50 {
        score += 1.5;
    }

    // Modulo-10 harmonic penalty: residuals not aligned to coarse size classes
    // in the small-residual regime are harder to pair with future items.
    if post_residual > 0 && post_residual < 30 && post_residual % 10 != 0 {
        score += 3.0;
    }

    // Lookahead coupling (k=2): reward bins that can also host the next item,
    // penalize proportionally to the mismatch otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 14.0;
        } else {
            let gap = (next_item_size - post_residual).min(60);
            score += gap as f64 * 0.18;
        }
    }

    // Last-chance bin: if this is the only open bin that fits, using it avoids
    // opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild pressure to close out bins when many are open.
    score += open_bins_count as f64 * 0.3;
    score += (mean_residual - post_residual as f64) * 0.05;

    // New-bin candidate: prefer opening a fresh bin only when the fit elsewhere
    // is genuinely poor (large post_residual) or few bins fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.92;
        // If the item is large, a fresh bin is often a good home.
        if item_size >= 60 {
            score -= 6.0;
        }
        if next_item_size > 0 && next_item_size >= 70 {
            score -= 4.0;
        }
        // If many open bins already fit, discourage proliferation.
        if fitting_bins_count >= 3 {
            score += 12.0;
        }
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in small unusable gaps is heavily penalized.
    // Gaps below ~10 (or below next item's size) are "dead" — add a large nonlinear penalty.
    let dead_threshold = if next_item_size > 0 { next_item_size.min(20) } else { 10 };
    if post_residual < dead_threshold {
        score += 40.0 + (dead_threshold - post_residual) as f64 * 3.0;
    } else {
        // Smooth reward for tight fits (low post_residual relative to capacity).
        score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward when this bin's residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Lookahead: if next item fits in post_residual, reward; otherwise penalize.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else {
            score += 8.0;
        }
    }

    // Open bins pressure: discourage scattering across many bins unless fit is excellent.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced packing),
    // but favor tighter-than-mean bins slightly.
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how badly existing bins fit.
        let poor_fit_pressure = if post_residual == bin_capacity - item_size {
            // This is the empty-bin call; estimate fit quality of alternatives via mean_residual.
            (mean_residual - item_size as f64).max(0.0)
        } else {
            0.0
        };
        score += 35.0 - poor_fit_pressure.min(35.0);
        // Late in the stream, opening fresh bins is slightly cheaper (fewer future conflicts).
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack.
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (-slack / 12.0).exp();
    }
    // Next item cannot fit in the leftover: dead space penalty.
    else if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 8.0 * (dead / 20.0).min(3.0);
    }

    // Penalize residual far above mean residual (wasteful bin usage).
    score += 0.5 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item nearly fills a fresh bin
    // or no good fits exist among open bins.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill >= 0.9 {
            score -= 40.0;
        } else if fitting_bins_count > 0 {
            score += 20.0 * (1.0 - fill);
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Slight preference for tight fits overall.
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: quadratic bonus for small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Exact-ish fit reward (post_residual <= 5 is near-perfect).
    if post_residual <= 5 {
        score -= 40.0;
    }

    // Lookahead coupling: penalize if post_residual is a tempting-but-wasteful
    // slot for the next item (next item fits with lots of leftover), reward if
    // post_residual becomes nearly unusable for the next item but this placement
    // was tight anyway.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nr {
            let leftover_after_next = pr - nr;
            // If next item would also fit snugly here, this bin is very valuable.
            if leftover_after_next <= 8.0 {
                score -= 25.0;
            } else {
                // Mild penalty: saving space for next item elsewhere might be better
                score += 0.15 * leftover_after_next;
            }
        } else {
            // Post residual can't host next item; only good if it's tiny dead space.
            if pr <= 10.0 {
                score -= 10.0;
            } else {
                score += 0.2 * (pr - 10.0);
            }
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin to avoid opening one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Crowding pressure: many open bins with slack -> prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let crowd = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.05 * crowd * (1.0 - progress);

    // Global residual alignment: penalize if this bin's residual deviates wildly
    // from the mean residual (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate logic: opening a new bin is only attractive when no
    // existing bin fits well (post_residual large on open bins) or stream is
    // early with plenty of capacity slack expected.
    if bin_residual == bin_capacity {
        let base = 55.0;
        // Early stream: new bins are cheap; late stream: consolidate.
        let horizon = 1.0 - progress;
        let mut new_score = base - 25.0 * horizon;
        // If many fitting bins exist and mean residual is small, discourage new bin.
        if fitting_bins_count > 0 && mean_residual < 40.0 {
            new_score += 30.0;
        }
        // If the only alternative residuals are huge, allow new bin.
        if post_residual as f64 > 0.6 * bin_capacity as f64 && fitting_bins_count <= 2 {
            new_score -= 20.0;
        }
        score = score.min(score) + new_score; // new bin uses its own score path
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Normalized tightness of the fit: how well item fills the bin.
    let fit_ratio = 1.0 - (post_residual as f64) / cap; // 1.0 = perfect fill

    // Smooth non-linear reward for tight fits, scaled by stream progress.
    let tight_reward = (fit_ratio * fit_ratio) * (1.0 + 2.0 * progress * progress) * 30.0;
    score -= tight_reward;

    // Penalize residual far from mean residual (dead-space dispersion), smoothed polynomially.
    let dev = (post_residual as f64 - mean_residual) / cap;
    score += dev * dev * 20.0 * (1.0 + progress);

    // Last-chance bonus: only one bin fits; strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0 + 20.0 * progress;
    }

    // Lookahead coupling: reward if next item fits into post_residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain = (next_item_size as f64) / (post_residual as f64 + 1.0);
        score -= 25.0 * chain * (1.0 + chain);
    } else if next_item_size > post_residual {
        // Penalize leaving a residual too small for the next item.
        score += 10.0 * (1.0 - (post_residual as f64) / (next_item_size as f64));
    }

    // Mild penalty for spreading across many open bins early; relax later.
    let spread = open_bins_count as f64 / (1.0 + total_items as f64);
    score += spread * 15.0 * (1.0 - progress);

    // Prefer new empty bin only when current fit is terrible: penalize new-bin
    // candidate (post_residual == bin_capacity) unless residual-based fit is bad.
    if bin_residual == bin_capacity {
        score += 25.0 - 20.0 * (fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // classes (multiples of common item sizes / small remainders) are rewarded.
    let pr = post_residual;
    let class = pr % 10;
    let mut bonus = 0.0;
    if pr == 0 {
        bonus = 60.0; // perfect fit is king
    } else if class == 0 {
        bonus = 25.0; // leftover aligns with decadal item sizes
    } else if class <= 2 {
        bonus = 12.0; // tiny dead space, nearly perfect
    } else if pr <= 9 {
        bonus = 18.0; // small leftover likely unusable but cheap
    } else {
        // penalize awkward mid-range leftovers
        bonus = -(class as f64) * 0.8;
    }
    score -= bonus;

    // Integer-division threshold: leftover that can host next item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + 0.3 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        score += 8.0; // cannot chain next item here
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor.
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64).sqrt() * 2.0;
        score += 40.0 - 30.0 * tight + 10.0 * progress - pressure;
        if item_size > 60 { score -= 15.0; } // big items start fresh bins nicely
        if next_item_size > 0 && next_item_size + item_size > bin_capacity {
            score -= 10.0; // next item won't pair anyway
        }
    }

    // Prefer fuller bins: relative fill fraction coupling.
    let fill = (bin_capacity - bin_residual) as f64 / cap;
    score -= 15.0 * fill * fill;

    // Discourage scattering across many open bins when mean residual is high.
    if (post_residual as f64) > mean_residual + 20.0 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: residuals too small for the smallest item (1..=10)
    // are essentially unusable; push such bins heavily to the bottom of preference
    // unless they are exactly zero (perfect fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 2.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Mild best-fit sharpening: prefer bins whose residual was already tight.
    score += (bin_residual as f64) * 0.05;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // reward this placement (chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that neither fits the next item nor is useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 5.0;
    }

    // New-bin candidate logic: opening a new bin is only attractive when the
    // item would leave a large, structured residual or few bins fit well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0;
        // Open bins pressure: with many open bins, opening another is worse.
        score += open_bins_count as f64 * 1.5;
        // If many bins fit, prefer using an existing one.
        if fitting_bins_count > 1 {
            score += 12.0;
        }
        // If no existing bin leaves a usable residual, new bin becomes better
        // (existing bins get the dead-space penalty above).
        if post_residual >= next_item_size && next_item_size > 0 {
            score -= 8.0;
        }
    }

    // Mean residual coupling: when open bins are already loose, be pickier
    // about wasting space (tighten dead-space pressure).
    score += (mean_residual - post_residual as f64).abs() * 0.02;

    // Slight early-stream conservatism: keep bins flexible early on.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * 0.03 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item well.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Strong reward for near-exact match with the next item.
        score -= 30.0 * (1.0 - gap / bin_capacity as f64).max(0.0);

        // Perfect chain: item fits now AND next item fits exactly after.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving a residual that is too small for the next item (dead space).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: minimize waste directly.
        score += 20.0;
    }

    // Tight fit reward: prefer bins that end up nearly full.
    score -= 15.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Compare against mean residual: bins with residual far above mean are less attractive
    // unless the item fills them well.
    let mean_gap = bin_residual as f64 - mean_residual;
    score += 0.15 * mean_gap;

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when open bins could take the item, especially
    // early in the stream; relax late when many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 30.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins whose post-fit residual is small.
    let tightness = (post_residual as f64 / bin_capacity as f64).powi(3);
    score += 40.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Penalize wasted residual that no plausible future item can use.
    if next_item_size > 0 {
        let gap = post_residual as f64;
        if gap > 0.0 && (next_item_size as f64) > gap {
            // dead space relative to lookahead item
            score += 0.5 * (gap / bin_capacity as f64) * (next_item_size as f64 - gap);
        } else if next_item_size as u32 == post_residual {
            // lookahead chains perfectly into this bin
            score -= 60.0;
        } else if (next_item_size as u32) < post_residual {
            score -= 10.0 * (next_item_size as f64 / gap.max(1.0));
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when current open bins fit poorly.
    if bin_residual == bin_capacity {
        let poor_fit_pressure = if fitting_bins_count == 0 {
            200.0
        } else {
            let best_possible = (bin_capacity - item_size) as f64;
            (best_possible / bin_capacity as f64).powi(2) * 50.0
        };
        // Opening a bin costs; discourage early, encourage when many bins already open
        // and mean residual is fragmented.
        let fragmentation = if mean_residual > 0.0 {
            (mean_residual / bin_capacity as f64).powi(2)
        } else {
            1.0
        };
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 120.0 - poor_fit_pressure - 60.0 * fragmentation - 30.0 * progress;
        // reserve space for large lookahead items in a fresh bin
        if next_item_size >= item_size {
            score -= 15.0;
        }
    }

    // Mild preference for bins with residual close to item size among many fitting bins.
    if fitting_bins_count > 1 {
        let slack = (bin_residual - item_size) as f64;
        score += 0.3 * slack;
    }

    // Encourage consolidating residual as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, mildly convex in normalized residual
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Non-linear coupling of residual with stream progress:
    // early on, tolerate large residuals; later, penalize them more sharply
    let progress_coupling = pr * (progress * progress) * 2.5;
    score += progress_coupling;

    // Smooth interaction: residual relative to mean residual across open bins
    let rel_mean = if mean_residual > 0.0 { pr / mean_residual } else { 1.0 };
    score += 4.0 * (rel_mean - 1.0) * (rel_mean - 1.0) * (1.0 - progress);

    // Penalize fragmentation: many open bins with wasted space
    let open_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    score += 0.6 * open_pressure * norm_pr;

    // Reward tight fits: small post residual gets subtractive bonus
    let tightness = (cap - pr) / cap; // fraction filled
    score -= 15.0 * tightness * tightness * tightness;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        let diff = pr - next_item_size as f64;
        if diff >= 0.0 {
            score -= 10.0 * (1.0 - diff / cap);
        } else {
            // next item cannot fit: mild penalty proportional to overshoot
            score += 0.5 * (-diff / cap) * (1.0 + progress);
        }
    } else {
        // last item: strongly prefer minimal post residual
        score -= 10.0;
    }

    // New-bin candidate: make empty bin mildly unattractive unless current bins are bad fits
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 12.0 + 8.0 * progress };
        score += scarcity;
        score += 5.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that fall into "usable" classes
    // Classes via integer division thresholds: residual buckets of width 10.
    let pr = post_residual as u32;
    let class = pr / 10;
    // Residuals in low classes (0..=2) are dead space -> penalize; high classes are fine.
    match class {
        0 => score += 25.0,               // 0..9: nearly full, excellent, but tiny waste
        1 => score -= 8.0,                // 10..19: good
        2 => score -= 3.0,                // 20..29: decent
        3 => score -= 0.0,
        4 => score += 4.0,
        5 => score += 8.0,
        6 => score += 14.0,
        _ => score += 20.0,               // >69 left: poor fit
    }

    // Modulo arithmetic: residuals that are multiples of common small sizes are reusable.
    if pr > 0 {
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 4.0; }
        if pr % 5 == 0 && pr % 10 != 0 { score -= 1.5; }
    }

    // Exact fit is perfect.
    if pr == 0 { score -= 40.0; }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= pr {
        score -= 12.0;
        // Harmonic alignment: next item exactly consumes a class boundary
        if (pr - next_item_size) % 10 == 0 { score -= 6.0; }
        if next_item_size == pr { score -= 15.0; }
    } else if next_item_size > pr {
        // next item cannot use this residual; residual likely dead -> mild penalty scaled by size
        score += (pr as f64) * 0.05;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when fit is bad.
    if bin_residual == bin_capacity {
        // Empty bin baseline: neutral-ish score; penalize when many bins already open
        // and this bin would fragment capacity usage.
        score = 55.0 + 0.15 * (open_bins_count as f64);
        if item_size <= 30 { score -= 10.0; }   // small items: fresh bin fine
        if next_item_size > 0 && next_item_size > 100 - item_size { score += 8.0; }
    }

    // Progress: early in stream, slightly prefer consolidation into existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 3.0;

    // Mean residual coupling: if this bin's residual deviates strongly from mean, adjust.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item are worthless — penalize them heavily.
    let dead_threshold = 10u32;
    if post_residual < dead_threshold {
        score -= 40.0 * (dead_threshold - post_residual) as f64;
    } else {
        // Superlinear waste: small-but-usable gaps are still risky.
        score += (post_residual as f64).powi(2) / (bin_capacity as f64);
    }

    // Tight fit reward: filling most of the residual is excellent.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fill_ratio > 0.8 {
        score -= 25.0 * (fill_ratio - 0.8);
    }

    // Lookahead: if next item fits in post_residual, reward keeping it open.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0; // dead space relative to lookahead
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidation into
    // tighter fits; few bins -> more freedom.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        score += 15.0 + scarcity * 25.0 + pressure * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size
    if next_item_size > 0 {
        let lookahead_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // Perfect chain: reward strongly when next item exactly fills this bin after
            score -= 40.0 * (1.0 - lookahead_gap / bin_capacity as f64);
            if post_residual == next_item_size {
                score -= 25.0; // exact 2-item chain completion
            }
        } else {
            // Post residual too small for next item: dead space penalty
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Prefer tight fits relative to mean residual of open bins
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    let tightness = (post_residual as f64 - mean_r) / bin_capacity as f64;
    score += 10.0 * tightness;

    // Penalize large wasted residual (dead space)
    if post_residual > 0 && post_residual < 10 {
        score -= 8.0; // nearly full bin is excellent
    }
    if post_residual > bin_capacity as u32 / 2 {
        score += 6.0; // leaving more than half empty is wasteful
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild penalty for opening new bins when many are already open
    if bin_residual == bin_capacity {
        score += 5.0 + 0.3 * open_bins_count as f64;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 3.0; // new bin fine if current item is large
        }
    }

    // Slight early-stream preference for consolidation
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * (1.0 - progress) * (mean_r / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual) with a non-linear squash.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        let dead = if next_item_size > 0 && next_item_size <= post_residual { 0.0 } else { post_residual as f64 };
        score += 0.35 * dead;
    }

    // Lookahead synergy: if the next item fits exactly into the resulting gap, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 12.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here: slight penalty for leaving a misleading gap.
            score += 1.5;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // Many options: sharpen discrimination among candidates by fill level.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 3.0 * fill;
    }

    // New-bin candidate handling: make an empty bin attractive only when current fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_tight = 1.0 - (mean_residual / bin_capacity as f64);
        // Empty bin is penalized mildly when good fits exist elsewhere; reward late in stream
        // or when open bins are mostly full (high avg tightness).
        let mut nb = 4.0 - 6.0 * avg_tight - 3.0 * progress;
        if fitting_bins_count == 0 { nb -= 20.0; } // must open a bin anyway
        if next_item_size > 0 && next_item_size <= bin_capacity { nb -= 1.0; }
        score += nb;
    }

    // Global pressure: with many open bins, prefer consolidating into fuller bins.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 0.8 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if open bins have large mean residual, avoid adding more
    // fragmented small residuals; if mean residual is small, tight fits matter more.
    let mean_tight = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score += 2.0 * mean_tight * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in the stream, keep bins flexible (moderate residuals OK);
    // late in the stream, aggressively minimize post_residual.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Perfect fit celebration.
    if post_residual == 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    let norm_item = item_size as f64 / bin_capacity as f64;
    let norm_next = next_item_size as f64 / bin_capacity as f64;

    // Non-linear coupling: dead space penalty grows quadratically with progress
    score += 40.0 * progress * norm_post * norm_post;

    // Reward tight fits more strongly as stream progresses (smooth interaction)
    score -= 25.0 * (1.0 - progress) * (1.0 - norm_post) * (1.0 - norm_post);

    // Coupling with next item: reward residuals that fit the lookahead item smoothly
    if next_item_size > 0 {
        let fits_next = (norm_post - norm_next).max(0.0);
        let exact = 1.0 - (norm_post - norm_next).abs();
        score -= 15.0 * exact.max(0.0) * (1.0 - progress);
        score += 10.0 * fits_next * fits_next * progress;
    }

    // Last-chance bin: strong reward to use it (avoid opening a new bin)
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 * (1.0 + progress);
    }

    // Penalize spreading across many open bins mildly, smooth in open_bins_count
    let open_norm = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 8.0 * open_norm * norm_post;

    // Mean residual deviation term: prefer bins near mean residual (smooth)
    let dev = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev * dev;

    // New-bin candidate: penalize opening a new bin unless residuals are all poor
    if bin_residual == bin_capacity {
        let mean_fullness = 1.0 - mean_residual / bin_capacity as f64;
        score += 20.0 * (1.0 - mean_fullness) * (1.0 - progress) + 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: post_residual mod 10 buckets
    let class = (post_residual % 10) as f64;
    score += class * 0.35; // penalize "ugly" residues that pair poorly

    // Perfect / near-perfect fits get strong rewards
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Integer-division thresholds: leftover that can host common size classes
    // (sizes 1..100 unknown distribution; favor leftovers divisible into useful chunks)
    let useful = post_residual / 10; // number of 10-slots
    score -= useful as f64 * 3.0;

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // harmonic match: next item exactly fills or leaves good residue
            let nxt_post = post_residual - next_item_size;
            if nxt_post == 0 {
                score -= 120.0;
            } else if nxt_post <= 10 {
                score -= 40.0;
            }
            score -= 15.0;
        } else {
            // next item won't fit here; penalize if we waste a big residual
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // Fraction of capacity consumed by this placement
    let fill = (item_size as f64) / cap;
    score -= fill * 20.0;

    // Progress-based bias: late in the stream, tighten bins; early, allow slack
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    // Prefer bins with residual close to mean (keep pool homogeneous),
    // unless it's a new-bin candidate
    if bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
    } else {
        // New bin: only attractive when few fitting bins exist or item is large
        score += 45.0
            - (fitting_bins_count as f64) * 12.0
            - fill * 10.0;
    }

    // Penalize creating dead space between 11 and 20 (hardest to fill)
    if post_residual > 10 && post_residual < 21 {
        score += 12.0;
    }

    // Mild penalty for accumulating too many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if no plausible future item (>=1) can use it well;
    // treat gaps below a threshold as waste.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward exact / near-exact fills strongly.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 3 {
        score -= 60.0;
    }

    // Tightness: reward small post_residual relative to capacity.
    score -= 30.0 * (1.0 - (post_residual as f64) / bin_capacity as f64);

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 50.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    score += 5.0 * open_bins_count as f64;

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 60.0 + 3.0 * open_bins_count as f64;
        // But if item is large, opening a new bin is less painful.
        score -= 0.3 * item_size as f64;
    }

    // Mean-residual coupling: prefer bins whose residual is near the mean
    // (keeps bin states balanced); avoid bins far below mean (fragmented).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // Slight late-stream tightening: as stream progresses, prefer tighter fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for exact or near-exact fills.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // matches the next item size exactly or closely.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let diff = (post_residual as f64 - next).abs();
        if post_residual as u32 == next_item_size {
            score -= 800.0; // perfect 2-chain: next item fills this bin exactly
        } else if (post_residual as f64) >= next {
            // next item fits; reward tightness of the 2-step chain
            score -= 300.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item does NOT fit: penalize proportionally to wasted lookahead
            score += 150.0 * (diff / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual across open bins:
    // leaving less than average residual is good (tight packing).
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 2.0 * (mean_residual - pr);
    } else {
        score += 1.0 * (pr - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when no open bin gives a tight fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score += 400.0;
        // but if the item is large and would leave a big dead space in any
        // existing bin, opening fresh is relatively better
        let dead = post_residual as f64;
        if dead > 0.35 * bin_capacity as f64 {
            score -= 350.0;
        }
        // early in the stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 100.0 * (1.0 - progress);
        // many open bins with high mean residual -> prefer reusing them
        if open_bins_count > 0 && mean_residual > item_size as f64 {
            score += 120.0;
        }
    }

    // Small tie-breaker favoring tighter fits overall.
    score += 0.01 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but heavily penalize unusable dead space.
    let dead = if post_residual > 0 && post_residual < 10 { 40.0 } else { 0.0 };
    score += dead;

    // Lookahead: reward if the next item fits into post_residual (chaining),
    // penalize if post_residual is large but useless for the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            // wasted space relative to lookahead item
            score += 0.10 * (post_residual as f64).min(next_item_size as f64);
        }
    }

    // Last-chance bin: strongly reward using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive;
    // only attractive when existing fits are poor (high mean residual scatter
    // or this would create a large fresh residual useful for big items).
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_pressure = open_bins_count as f64;
        let new_bin_cost = 45.0 + 3.0 * open_pressure * (1.0 - 0.5 * progress);
        score += new_bin_cost;
        // A fresh bin is more attractive late in the stream or when many
        // open bins have tiny residuals (fragmented state).
        if mean_residual < 15.0 {
            score -= 10.0;
        }
        if next_item_size > 60 {
            score -= 15.0;
        }
    } else {
        // Existing bin: reward matching mean residual (balanced usage),
        // penalize bins far below mean residual (hoarding space).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.08 * dev;
    }

    // Mild time-decay: early on, keep bins tight for the long horizon;
    // late, tolerate looser fits to avoid opening bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * (1.0 + 2.0 * progress * norm_pr + 3.0 * progress * progress * (1.0 - norm_pr) * (1.0 - norm_pr));

    let mut score = poly * cap;

    // Reward tight fits, more strongly as stream progresses
    let tight = 1.0 - norm_pr;
    score -= 12.0 * tight * tight * (0.5 + progress);

    // Penalize dead space relative to mean residual of open bins
    score += 0.15 * (pr - mean_residual) * (1.0 + progress);

    // Lookahead: favor bins whose post-residual can host the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 6.0 * (1.0 - (pr - nxt) / cap) * (0.4 + 0.6 * progress);
        } else {
            score += 4.0 + 6.0 * progress;
        }
    }

    // Last-chance bin bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Mild penalty for proliferating bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: prefer only when it yields a good future fit
    if bin_residual == bin_capacity {
        score += 8.0 - 10.0 * progress;
        if next_item_size > 0 && pr as u32 >= next_item_size {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual via integer division thresholds
    // Class 0: perfect fit (post_residual == 0) -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Class of "dead space": post_residual smaller than the smallest possible item
        if post_residual < 10 {
            score += 60.0; // unusable sliver
        } else if post_residual <= 20 {
            score += 15.0; // barely usable
        } else if post_residual <= 40 {
            score += 5.0;
        }
        // Harmonic class: post_residual mod (capacity/4) classes
        let quarter = bin_capacity / 4;
        let class = (post_residual % quarter.max(1)) as f64;
        score += class * 0.35;

        // Reward when next item fits exactly into post_residual (chain packing)
        if next_item_size > 0 {
            if next_item_size == post_residual {
                score -= 120.0;
            } else if next_item_size < post_residual {
                let gap = (post_residual - next_item_size) as f64;
                if gap <= 10.0 {
                    score -= 25.0 * (1.0 - gap / 10.0);
                } else {
                    score += gap * 0.25;
                }
            } else {
                // next item cannot fit here: residual likely dead
                score += 20.0;
            }
        }
    }

    // Tight fit relative reward: fraction of bin used by this item
    let fill = item_size as f64 / cap;
    score -= 40.0 * fill;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when plenty of open bins have room
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of a fresh bin
        score = cap as f64 * 0.9 + 50.0;
        // allow new bin only if existing bins are badly fragmented
        let fragmentation = (mean_residual / cap).max(0.0).min(1.0);
        score -= 90.0 * fragmentation;
        // early in stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * (1.0 - progress);
        if fitting_bins_count == 0 {
            score -= 500.0; // no alternative
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Mid-range gaps (10..30) are moderately wasteful.
    if post_residual >= 10 && post_residual < 30 {
        score += 8.0 * (30.0 - post_residual as f64) / 20.0;
    }

    // Reward near-perfect fits (exact fill is ideal).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward leaving room for the lookahead item if it fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            if post_residual - next_item_size < 10 {
                score -= 10.0; // lookahead completes the bin nicely
            }
        } else {
            score += 6.0; // lookahead cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage proliferation of bins unless fit is tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = 1.0 + 0.05 * open_bins_count as f64 * (1.0 - 0.5 * progress);
    score *= pressure;

    // New-bin candidate: only attractive when item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a bin; discount when item is large (would waste little).
        score = 55.0 - 30.0 * tightness;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        }
        if fitting_bins_count == 1 {
            score += 45.0; // an open bin fits fine; do not open a new one
        }
        if next_item_size > 0 && bin_capacity - item_size >= next_item_size {
            score -= 8.0; // new bin leaves room for lookahead
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward a perfect 2-step match: next item exactly fills leftover space.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match: next item fits with small slack.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 / (1.0 + slack);
    }
    // Next item cannot fit: penalize proportionally to wasted opportunity.
    else if next_item_size > 0 {
        let miss = (next_item_size - post_residual) as f64;
        score += 10.0 * miss / bin_capacity as f64;
    }

    // Tight fit for current item: small post_residual is good dead-space-wise.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.2;

    // Penalize creating unusable tiny slivers (dead space below min plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    // (high mean residual spread) or few bins can fit the item.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0; // fresh bin serves next item well
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements that nearly fill the bin.
    let fill_ratio = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * fill_ratio * fill_ratio * (item_size as f64);

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.15 * (next_item_size as f64);
        } else {
            // Penalize leaving residual just below the next item (wasted slot).
            let gap = post_residual as f64 - (next_item_size as f64);
            if gap > -15.0 && gap < 0.0 {
                score += 6.0;
            }
        }
    }

    // Global state: many open bins with high mean residual -> prefer consolidating.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let residual_spread = mean_residual - post_residual as f64;
    score += 0.3 * residual_spread.abs() * (1.0 - progress);

    // Prefer bins with residual close to mean (balance load) early on.
    score += 0.2 * (bin_residual as f64 - mean_residual).abs() * progress;

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is chosen only when placement elsewhere is terrible.
        score += 35.0;
        // Early in stream with few bins, opening fresh bins is cheaper.
        score -= 20.0 * (1.0 - progress) * (1.0 / (1.0 + open_bins_count as f64));
        // If next item is large, a fresh bin gives flexibility.
        if next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Mild penalty for accumulating too many open bins late in the stream.
    score += 0.05 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let item = item_size as f64;

    // Base: strongly favor tight fits (small post_residual), with a
    // non-linear quadratic/quartic shaping so near-zero residuals dominate.
    let post_norm = post / cap;
    let mut score = post * (1.0 + 2.0 * post_norm * post_norm);

    // Smooth stream-progress coupling: early in the stream, keep bins a bit
    // looser (slight bonus for larger post_residual); late in the stream,
    // tighten aggressively (penalize any slack quadratically).
    let progress_tilt = (0.5 - progress) * cap * 0.6;
    score += -progress_tilt * (1.0 - post_norm) * (1.0 - post_norm)
        + progress * post_norm * post_norm * cap * 0.8;

    // Lookahead coupling: if the next item can fill this bin's post-residual
    // well, reward; if post-residual is awkwardly small for the next item,
    // penalize dead space smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let gap_norm = (gap / cap).clamp(0.0, 1.0);
        // smooth penalty growing with |post - next|, reduced when gap small
        score += gap_norm * gap_norm * cap * 0.5;
        // bonus if next item exactly complements this bin
        let complement = (1.0 - gap_norm).clamp(0.0, 1.0);
        score -= complement * complement * cap * 0.35;
    }

    // Scarcity pressure: when this is the only fitting bin, reward using it
    // (subtract), smoothly scaled by how tight the fit is.
    if fitting_bins_count <= 1 && bin_residual != bin_capacity {
        let tightness = 1.0 - post_norm;
        score -= cap * 1.5 * tightness * tightness;
    }

    // New-bin candidate handling: penalize opening a new bin, more so when
    // other bins fit and when many bins are already open (fragmentation).
    if bin_residual == bin_capacity {
        score += cap * (2.0 + 0.15 * open_bins_count as f64);
        if fitting_bins_count > 0 {
            score += cap * 1.5;
        }
    }

    // Mild dispersion term: avoid making this bin's residual deviate far
    // from the mean residual of open bins (smooth, non-linear).
    let dev = (post - mean_residual) / cap;
    score += dev.abs() * cap * 0.2 * (1.0 - progress);

    // Tiny item-size interaction: prefer placing larger items into
    // already-open bins (keeps small items as flexible filler).
    score -= (item / cap) * (1.0 - post_norm) * 4.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction classes.
    // Class 0: near-perfect fit (<= 5), Class 1: small remainder (<= 15),
    // Class 2: quarter-ish (<= 25), Class 3: half-ish (<= 50), Class 4: large.
    let cls = if post_residual <= 5 { 0u32 }
        else if post_residual <= 15 { 1 }
        else if post_residual <= 25 { 2 }
        else if post_residual <= 50 { 3 }
        else { 4 };

    // Reward good classes (subtract), penalize bad ones (add).
    let class_bonus = match cls {
        0 => 60.0,
        1 => 35.0,
        2 => 15.0,
        3 => 0.0,
        _ => -20.0, // large dead space: penalty via less subtraction
    };
    score -= class_bonus;

    // Integer-division harmonic: post_residual divisible by small numbers is more
    // likely to be filled by future small items.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 8.0; }
        else if post_residual % 5 == 0 { score -= 4.0; }
    }

    // Lookahead coupling: does next_item_size fit into post_residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        // chainable: reward, scaled by how tightly the next item also fits
        let chain_tight = (post_residual - next_item_size) as f64;
        score -= 20.0 - 0.2 * chain_tight;
    } else if next_item_size > post_residual {
        // dead space relative to next item: penalize proportionally
        score += 0.15 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalty for spreading load thin across many open bins when mean residual is high.
    if open_bins_count > 4 && (post_residual as f64) > mean_residual {
        score += 5.0;
    }

    // Mild pressure toward consolidation as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64) / bin_capacity as f64;

    // New-bin candidate: neutral-ish baseline; only preferred when item fits poorly everywhere.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, offset by its pristine flexibility
        score += 40.0 - 0.3 * item_size as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 10.0; // fresh bin can absorb anything next
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residual gaps too small for the minimum
    // item (size 1) are not dead, but gaps that no typical item can use
    // (very small nonzero gaps) are heavily penalized.
    if post_residual > 0 {
        let dead_threshold = 10.0;
        if (post_residual as f64) < dead_threshold {
            // The smaller (and thus more useless) the gap, the bigger the penalty.
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 8.0;

    // Exact fit is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for leaving a gap
        // that the lookahead cannot use.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins (penalize the new-bin candidate implicitly via
    // its large residual, but add explicit pressure).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * (bin_residual as f64 / bin_capacity as f64);

    // Prefer bins whose residual is below the mean residual (fill emptier-
    // than-average bins less; fill tighter bins more).
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Penalize it mildly so we only open a new bin when no existing bin gives
    // a good fit, but scale the penalty down when open bins are numerous and
    // the fit would be terrible.
    if bin_residual == bin_capacity {
        let bad_fit = (item_size as f64) < 0.5 * bin_capacity as f64;
        if bad_fit {
            score += 10.0 + 0.5 * open_bins_count as f64;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: strongly reward when the next item fits exactly or well.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect match: bin becomes exactly full after next item.
            score -= 60.0;
        } else if post_residual >= next_item_size {
            let next_post = post_residual - next_item_size;
            // Reward tight fit of the next item; penalize large leftover after it.
            score -= (next_item_size as f64) * 0.5;
            score += (next_post as f64) * 0.3;
        } else {
            // Next item cannot follow in this bin: penalize proportionally.
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Compare against mean residual across open bins: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.4;

    // Penalize creating unusable dead space (small residuals that few items fit).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: discourage opening a new bin unless current bins are poor fits.
    if bin_residual == bin_capacity {
        score += 30.0 + (open_bins_count as f64) * 0.5;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Exact-fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize leaving a residual that is just barely too small
    // for the next item (wasted dead space), reward leaving a useful gap.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if (post_residual as f64) < nx && (post_residual as f64) >= nx * 0.5 {
            score += 12.0; // next item almost fits but won't: dead space risk
        }
        if post_residual as f64 >= nx {
            score -= 8.0; // gap remains usable by the known next item
        }
        // If the next item exactly consumes the post residual, big synergy.
        if post_residual as u32 == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fitting bins exist and the
    // residual landscape is fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // New bin is attractive only when mean residual is small (open bins are full)
        // or the item is huge relative to typical residuals.
        let new_bin_bonus = 18.0 * (avg_fit / bin_capacity as f64) - 10.0 * (item_size as f64 / bin_capacity as f64);
        score -= new_bin_bonus;
        // Early in the stream, allow more bins; late, consolidate.
        score += 8.0 * (1.0 - progress);
        // Many open bins: discourage proliferation.
        score += 1.5 * open_bins_count as f64;
    } else {
        // Slight preference for bins with residuals near the mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Mild penalty for leaving large unusable gaps relative to smallest possible item (1).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny sliver: nearly dead space
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let fit_norm = pr / cap;

    // Non-linear polynomial coupling: post_residual penalized more heavily
    // as stream progresses (dead space matters more late).
    let poly = fit_norm * fit_norm * (0.5 + progress) + fit_norm * progress * progress;
    score += 30.0 * poly;

    // Reward tight fits with smooth interaction between fill ratio and progress.
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 12.0 * fill * fill * (1.0 + progress);

    // Last-chance bin: smooth reward scaled by how snug the fit is.
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - fit_norm) * (0.5 + progress);
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Prefer bins with lower mean residual (concentrate waste) — smooth coupling.
    score += 0.05 * (mean_residual - pr).max(0.0);

    // Mild penalty for proliferation of open bins, smoothed by progress.
    score += 0.3 * open_bins_count as f64 * progress;

    // New-bin candidate: only attractive when no tight option exists.
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Harmonic class of post_residual: residues that are "dead" (too small
    // for the smallest plausible item) are heavily penalized.
    let dead_threshold = 10u32.min(bin_capacity / 10);
    if post_residual < dead_threshold {
        score += 50.0 + (dead_threshold - post_residual) as f64 * 3.0;
    }

    // Harmonic classes via integer division of post_residual into capacity
    // fractions: bins whose post_residual lands in a "useful" class are rewarded.
    let frac_class = post_residual / (bin_capacity / 4).max(1); // 0..4 classes
    score -= match frac_class {
        0 => 15.0, // very tight: near-perfect fit
        1 => 8.0,  // quarter-full remainder: still useful
        2 => 2.0,
        3 => -1.0,
        _ => 0.0,
    };

    // Modulo-10 harmonic: residuals divisible by 10 pair well with typical
    // item sizes; reward multiples of 10, penalize odd residues.
    if post_residual % 10 == 0 {
        score -= 6.0;
    } else if post_residual % 2 == 1 {
        score += 2.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            if next_post < dead_threshold {
                score -= 20.0; // chain of two near-perfect fits
            } else {
                score -= 10.0 * (1.0 - next_post as f64 / bin_capacity as f64);
            }
        } else {
            // Next item cannot use this residue: penalize leaving residue
            // in a class the lookahead can't consume.
            score += 5.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize spreading residual wealth when many bins are open and mean
    // residual is low (fragmentation pressure).
    if open_bins_count > 2 {
        let frag = (mean_residual - post_residual as f64).abs();
        score += frag * 0.3 * (open_bins_count as f64).ln().max(1.0);
    }

    // New-bin candidate: only attractive early in the stream or when this
    // item leaves a badly fragmented residue in every open bin.
    if bin_residual == bin_capacity {
        let early_bonus = (1.0 - progress) * 20.0;
        score += 25.0 - early_bonus;
        if post_residual == bin_capacity {
            // base case for the empty-bin call itself; keep it neutral-ish
            score -= 10.0;
        }
    }

    // Slight preference for tighter fits overall (best-fit core signal).
    score += (bin_residual - item_size) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item are dead weight; penalize them quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 6.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += (20.0 - post_residual as f64) * 1.5;
    }

    // Reward tight fits: residual almost exactly consumed.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 12.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Open-bin pressure: penalize using bins when many are open,
    // encouraging consolidation into existing bins rather than spreading.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using the only bin that fits,
    // otherwise a new bin must be opened.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current fit is terrible
    // (large dead space would result) or no bin fits well.
    if bin_residual == bin_capacity {
        let dead_space_penalty = if post_residual < 10 { 40.0 } else { 0.0 };
        score += 8.0 + dead_space_penalty
            - if post_residual >= 10 { 6.0 } else { 0.0 };
        // If next item could combine with current item in a fresh bin,
        // opening a new bin becomes more attractive.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // Lookahead: avoid leaving a gap that neither the next item nor
    // anything useful can fill.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
        score += 4.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0;
    }

    // Late in the stream, prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize post_residual relative to mean residual
    score += 0.35 * (post_residual as f64 - mean_residual);

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let match_bonus = (1.0 - gap / bin_capacity as f64).max(0.0);
        score -= 12.0 * match_bonus * match_bonus;
        // Perfect chain: next item fills bin exactly
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving dead space next item can't use
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
        // If next item can't fit here but could fit the post_residual of another bin,
        // slightly penalize wasting residual larger than next item by a lot
        if post_residual > next_item_size * 2 {
            score += 2.0;
        }
    } else {
        // Last item: prefer minimal post residual strongly
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        // Default penalty for opening a new bin
        score += 30.0;
        // But if many open bins are nearly full (mean residual small), opening is fine
        score -= (mean_residual / 10.0).min(20.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // fresh bin can chain next item too
        }
    }

    // Late in stream: consolidate, discourage opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Crowding: with many open bins, favor bins with small residual (tight packing)
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strong preference for minimal waste.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Lookahead: penalize residuals that cannot host the next item (dead space),
    // reward residuals that exactly or nearly fit it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            let dead = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.15 * dead;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize bins with residuals far from the mean residual (keep pool uniform),
    // mildly, so fragmented outliers are deprioritized.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Progress-dependent pressure: later in the stream, consolidation matters more;
    // early on, allow spreading to build a good residual portfolio.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: prefer filling existing ones rather than proliferating.
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: an empty bin should only win when the item is
    // large (poor fit anywhere) or no real bin offers a decent fit.
    if bin_residual == bin_capacity {
        let base = 45.0 + 0.4 * item_size as f64;
        let scarcity = if fitting_bins_count == 0 { 30.0 } else { 0.0 };
        score = base + scarcity + 0.1 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, large residuals are fine; late in the stream, penalize them harder.
    let norm_pr = pr / cap;
    let coupling = norm_pr * norm_pr * (0.5 + 1.5 * progress) * cap;
    score += coupling;

    // Smooth quadratic penalty for post_residual relative to mean residual:
    // creating residuals well below the mean wastes space.
    let dev = pr - mean_residual;
    score += 0.15 * dev * dev / cap;

    // New-bin candidate: penalize mildly early, more strongly if many bins open.
    let is_new_bin = bin_residual == bin_capacity && item_size > 0;
    if is_new_bin {
        score += 8.0 + 2.0 * (open_bins_count as f64).sqrt() + 10.0 * progress;
        // But if next item is large, opening a fresh bin is attractive.
        if (next_item_size as f64) > 0.6 * cap {
            score -= 12.0;
        }
    } else {
        // Tight fit reward: smooth bell around small post_residual.
        let tight = (pr / cap) * (1.0 - pr / cap);
        score -= 6.0 * tight * (1.0 + progress);

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 {
            score -= 15.0;
        }

        // Lookahead: reward leaving residual that can host the next item exactly.
        if next_item_size > 0 && next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 5.0 * (1.0 - gap / cap);
        }
        // Penalize residuals too small for the smallest plausible future item.
        if next_item_size > 0 && post_residual < next_item_size {
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: small leftovers are "dead space"
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: near-perfect fit (leftover < 10% of capacity) -> strong reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= bin_capacity / 10 {
        score -= 25.0;
    } else if post_residual <= bin_capacity / 5 {
        score -= 8.0;
    } else if post_residual <= bin_capacity / 3 {
        score -= 2.0;
    } else {
        // large leftover: penalize mildly, scaled by how much of capacity is wasted
        score += 0.15 * (pr - cap / 3.0);
    }

    // Harmonic residue classes on post_residual (mod 10 granularity)
    match post_residual % 10 {
        0 => score -= 6.0,                 // round leftover, likely reusable
        1 | 9 => score -= 1.0,
        2 | 8 => score += 0.5,
        3 | 7 => score += 1.0,
        4 | 6 => score += 1.5,
        _ => {}                            // 5: neutral
    }

    // Integer-division thresholds: leftover usable by lookahead item?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // lookahead fits here: reward proportional to tightness of that fit
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // lookahead cannot use the leftover: penalize wasted potential
            let gap = (next_item_size - post_residual) as f64;
            score += 0.10 * gap.min(cap);
        }
        // leftover exactly divisible by lookahead size class
        if next_item_size > 0 && post_residual % next_item_size == 0 && post_residual > 0 {
            score -= 5.0;
        }
    } else {
        // last item: prefer zero-waste placement
        score -= 0.5 * pr;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bins fit poorly
    if bin_residual == bin_capacity && bin_capacity > 0 {
        let perfect = cap - item_size as f64;
        // baseline: new bin leaves (cap - item) residual; compare with mean open residual
        score = perfect;
        if fitting_bins_count == 0 {
            score -= 15.0; // must open a bin anyway
        }
        if open_bins_count == 0 {
            score -= 10.0;
        }
        // late in the stream, discourage bin proliferation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // if mean residual across open bins is large, prefer reusing them
        score += 0.05 * (mean_residual - perfect).max(0.0);
    }

    // Mild tie-break: prefer bins with residual close to item (tight fit)
    score += 0.05 * ((bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: penalize small unusable gaps heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward when the leftover can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 8.0;
    }

    // Open bins pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Prefer bins with residuals close to the item (tight fits).
    let tightness = (bin_residual - item_size) as f64;
    score += tightness * 0.3;

    // New-bin candidate: mild penalty so it's only chosen when fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.05;
    }

    // Late-stream consolidation bias.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, penalize dead space relative to capacity.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64) * (post_residual as f64 / bin_capacity as f64) * bin_capacity as f64;

    // Aggressive 2-step lookahead: perfect match of next item into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact fill of this bin by the next item
        } else if post_residual >= next_item_size {
            // next item fits here: reward proportionally to how well it fills remainder
            let after2 = post_residual - next_item_size;
            score -= 25.0 * (1.0 - after2 as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder: penalize large leftover
            let waste = post_residual as f64 - (bin_capacity as f64 - next_item_size as f64).max(0.0);
            score += 0.5 * waste.max(0.0);
        }
    } else {
        // last item: pure tight-fit preference
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Relative-to-mean-residual coupling: placing into a bin whose residual is
    // far below mean concentrates space usage; slightly reward that.
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // New-bin candidate: keep it attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 10.0;
        }
    }

    // Slight stream-phase modulation: late in the stream, be more frugal with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 60.0 * fit_ratio * fit_ratio;

    // Penalize very small dead space that is hard to reuse later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead coupling: reward leaving residual that matches the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.35 * gap;
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item: just minimize waste.
        score += 0.1 * post_residual as f64;
    }

    // Global pressure: many open bins with low mean residual -> consolidate.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual);
    score += 2.0 * pressure * (1.0 - fit_ratio);

    // Time horizon: early in stream, opening new bins is cheaper; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or when a fitting bin exists.
        score += 55.0 * (0.3 + 0.7 * progress);
        if fitting_bins_count >= 1 {
            score += 20.0;
        }
    } else {
        score -= 10.0 * progress * fit_ratio;
    }

    // Mild preference for bins with residual close to item size (perfect-ish fit).
    let slack = (bin_residual as i64 - item_size as i64) as f64;
    score += 0.15 * slack.abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let br = bin_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: non-linear polynomial in post_residual (normalized)
    let x = pr / cap; // normalized post residual in [0,1)
    let mut score = x * x * (3.0 - 2.0 * x) * cap; // smoothstep-shaped penalty: tiny residuals heavily penalized

    // Quadratic coupling of post_residual with stream progress
    // Later in the stream: prefer tighter packing (smaller post_residual) more aggressively
    score += progress * (pr * pr) / cap;

    // Reward filling the bin well: subtract a smooth function of fill ratio
    let fill = (br - pr) / cap;
    score -= 2.0 * fill * fill * cap;

    // Coupling with mean residual: bins with residual near mean are "typical"; prefer bins whose
    // post residual is close to mean residual (smooth Gaussian-like coupling)
    let d = pr - mean_residual;
    score += 0.05 * d * d / cap;

    // Lookahead: if next item fits into post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 1.0 + 2.0 * (next_item_size as f64 / pr.max(1.0));
    }
    // If next item is slightly larger than post residual, penalize creating a near-miss dead zone
    if next_item_size > 0 && (next_item_size as f64) > pr && pr > 0.0 {
        let gap = next_item_size as f64 - pr;
        if gap < 10.0 {
            score += (10.0 - gap) * 2.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Many open bins: discourage opening new bins (new empty bin has max residual, so
    // its polynomial penalty is low; add a term proportional to open bins to counteract)
    score += 0.15 * open_bins_count as f64 * (1.0 - x);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which "slot size" class it falls into.
    // Class boundaries at multiples of 25 (quarters of capacity) and fine classes of 10.
    let coarse_class = post_residual / 25;        // 0..4
    let fine_class = post_residual / 10;          // 0..10
    let dead = post_residual < 10;                // unusable dead space (min item size)

    // Penalize dead space heavily; reward residuals that can host the lookahead item.
    if dead {
        score += 40.0;
    } else {
        // Harmonic reward: residual divisible-ish into useful chunks gets bonus.
        let harmony = if post_residual % 25 == 0 {
            -6.0
        } else if post_residual % 10 == 0 {
            -3.0
        } else {
            0.0
        };
        score += harmony;
    }

    // Lookahead coupling: if next item fits into the post residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * next_item_size as f64;
            // even better if post_residual - next_item_size is itself a clean class
            let r2 = post_residual - next_item_size;
            if r2 % 10 == 0 { score -= 2.0; }
        } else {
            // post residual too small for lookahead: mild penalty scaled by closeness
            let gap = (next_item_size - post_residual) as f64;
            score += 0.10 * gap.min(20.0);
        }
    }

    // Tight fit reward: fraction of bin consumed by this item.
    let fill = item_size as f64 / cap;
    score -= 12.0 * fill;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: slight penalty to spreading into more bins' residual pool.
    score += 0.15 * open_bins_count as f64;

    // Deviation from mean residual: prefer bins whose residual stays near the mean
    // (keeps class structure balanced across bins).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // New-bin candidate: neutral-ish baseline so it wins only when all fits are bad.
    if bin_residual == bin_capacity {
        // Opening a fresh bin costs one bin; make it lose to decent fits but beat dead space.
        score = 45.0 - 5.0 * fill;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
        // Late in the stream, slightly discourage opening bins (fewer chances to fill).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
