pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 + 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space relative to the lookahead item.
            let gap = (next_item_size - post_residual) as f64;
            score += 25.0 + 0.5 * gap;
        }
    } else {
        // Last item: prefer minimal residual as usual (already base score).
        score -= 10.0;
    }

    // Compare residual against the mean residual of open bins:
    // leaving much more residual than average wastes capacity elsewhere.
    score += 0.4 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: mildly discourage opening a new bin early on,
    // but encourage it when the item fits badly in every open bin.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit = (post_residual as f64) < 0.25 * bin_capacity as f64;
        if poor_fit && next_item_size > 0 && post_residual < next_item_size {
            score -= 150.0; // open a fresh bin rather than fragmenting
        } else {
            score += 30.0 + 50.0 * (1.0 - progress);
        }
    }

    // Slight preference for fuller bins when many bins are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
