pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64;

    // Base: prefer tight fits (small post_residual)
    let mut score = post;

    // Reward tightness non-linearly: normalized fill ratio squared
    let fill = fit / cap;
    score -= 18.0 * fill * fill * (1.0 - post / cap);

    // Perfect-fit reward with smooth exponential coupling
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tight = 1.0 - (post / cap);
        score -= 12.0 * tight * tight;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= post {
            let slack = post - nx;
            // next item fills leftover smoothly
            let coupling = 1.0 - (slack / cap);
            score -= 15.0 * coupling * coupling;
        } else {
            // penalize leaving residual too small for the known next item
            score += 0.15 * (nx - post).min(cap) * (1.0 + progress);
        }
    }

    // Stream progress: as stream advances, tolerate less fragmentation
    score += 6.0 * progress * (post / cap) * (post / cap);

    // Mean-residual deviation: prefer bins whose residual is near the mean
    // (keeps bin pool homogeneous, avoids stranding outliers)
    let dev = (post - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when no open bin is a good fit
    if bin_residual == bin_capacity {
        let openness = open_bins_count as f64;
        // opening cost grows mildly with number of open bins and progress
        score += 30.0 + 2.0 * openness * (0.5 + progress);
        // but if item is large relative to capacity, opening fresh is fine
        score -= 20.0 * fill * fill;
    }

    // Mild penalty for creating dead space that nothing between 1..=post can use well
    let small_waste = (post / cap) * (post / cap);
    score += 4.0 * small_waste * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in (0,10) is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // unusable sliver penalty
    }
    // Modulo-10 harmonic classes: residuals divisible by 10 pair better with
    // typical item sizes
    if post_residual % 10 == 0 {
        score -= 12.0;
    } else if post_residual % 5 == 0 {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: residual class after that hypothetical placement
        let post2 = post_residual - next_item_size;
        if post2 % 10 == 0 {
            score -= 25.0;
        }
        if post2 < 10 && post2 > 0 {
            score += 20.0;
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's remainder anyway; residual is dead
        // unless a future small item comes. Penalize large stranded remainders.
        score += 0.15 * post_residual as f64;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item is large
    // relative to mean residual (poor fits everywhere) or when opening keeps
    // open-bin count manageable
    if bin_residual == bin_capacity {
        let poor_fit_everywhere = (mean_residual - item_size as f64) < 15.0;
        let crowded = open_bins_count > 8;
        if poor_fit_everywhere || crowded {
            score -= 30.0;
        } else {
            score += 55.0; // prefer fitting into an existing bin
        }
        // Fresh bin has clean residual == capacity, harmonic bonus
        if bin_capacity % 10 == 0 {
            score -= 5.0;
        }
    }

    // Progress-aware mild pressure: late in stream, consolidate more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual % 10 == 0) as i32 as f64;

    // Prefer bins whose residual is close to the item (tight fit)
    let tightness = (bin_residual - item_size) as f64;
    score += 0.1 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (<10) are unusable for min-size items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Medium dead space (10..25) is half-unusable: soft penalty.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }
    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Tightness bonus: fraction of bin consumed by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bins pressure: when many bins are open, prefer filling existing ones
    // (penalize opening new bins / spreading).
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins are open or residual
        // capacity across open bins is scarce relative to the item.
        let total_free = mean_residual * open_bins_count as f64;
        let scarcity = (item_size as f64 / (total_free + 1.0)).min(3.0);
        score += 10.0 + 6.0 * open_bins_count as f64 - 15.0 * scarcity;
        // Late in the stream, closing out bins is cheap; discourage new bins more.
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.7 {
            score += 10.0;
        }
    } else {
        // Existing bin: mild reward scaled by how much it beats mean residual.
        score -= (mean_residual - bin_residual as f64).max(0.0).min(50.0) * 0.2;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // big bonus for reserving that space; if next item barely misses, penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 9 {
            score += 6.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward when post_residual matches the next item exactly (2-step lookahead).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (-gap / 12.0).exp();
        // Penalize residual too small for next item (dead space for lookahead).
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: prefer tightest fit only.
        score += 40.0;
    }

    // Relative-to-mean residual shaping: bins far below mean residual are tight, keep them;
    // bins with large residual relative to mean waste capacity.
    let res = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.6 * (res - mean_residual).max(0.0);
        score -= 0.3 * (mean_residual - res).max(0.0).min(30.0);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive if it enables a near-perfect next placement,
    // otherwise discourage opening new bins while open ones can fit.
    if bin_residual == bin_capacity {
        let perfect_next = next_item_size > 0 && (bin_capacity as i64 - next_item_size as i64) == item_size as i64;
        if perfect_next {
            score -= 55.0;
        } else {
            score += 45.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild progression term: later in stream, tighten packing (prefer small residuals more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
