            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Global state: when many open bins exist with large mean residual,
    // prefer consolidating into existing bins rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 {
        score -= 8.0 * (mean_residual / bin_capacity as f64) * (open_bins_count as f64).ln();
    }

    // Time horizon: late in the stream, waste matters more (no future to fill gaps);
    // early on, allow slightly looser fits to build flexible bins.
    score *= 1.0 + 0.3 * progress;

    // New-bin candidate: penalize opening a new bin unless the item is large
    // and current bins have poor residual structure.
    if bin_residual == bin_capacity {
        score += 45.0
            - 20.0 * (item_size as f64 / bin_capacity as f64)
            - 10.0 * (mean_residual / bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        }
    }

    // Small deterministic tie-breaker based on bin fullness ordering.
    score += 0.01 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Base: prefer tight fits via smooth non-linear penalty on residual
    let mut score = post.powf(1.5) / cap.sqrt();

    // Smooth polynomial coupling: residual waste weighted by stream progress
    let waste_curve = norm_post * norm_post * (1.0 + progress * 2.0);
    score += 40.0 * waste_curve;

    // Interaction: small post-residual is valuable late in the stream
    score -= 25.0 * (1.0 - norm_post).powf(2.0) * (0.5 + progress);

    // Dead-space penalty: residual too small to fit typical items, smoothed
    let dead = ((post - next_item_size as f64).abs() / cap).powf(2.0);
    score += 10.0 * dead * (1.0 + progress);

    // Last-chance bonus: keep usable residual when few fitting bins
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 15.0 * last_chance * (1.0 - norm_post);

    // New-bin candidate: penalize slightly unless open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score += 5.0 + 20.0 * fragmentation * (1.0 - progress);
        score -= 10.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.02 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space into residue classes mod 10
    let class = post_residual % 10;
    // Penalize leftovers that are "awkward" (small nonzero remainders waste space)
    if post_residual > 0 && post_residual <= 10 {
        score += 30.0 * (1.0 - class as f64 / 10.0);
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Harmonic fractions of capacity: leftover in quarters
    let quarter = bin_capacity / 4;
    if post_residual == quarter || post_residual == 2 * quarter || post_residual == 3 * quarter {
        score -= 40.0; // clean harmonic leftover likely reusable
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size < post_residual {
            score -= 20.0;
        } else {
            score += 15.0; // next item won't fit here; leftover becomes dead space
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        score += 80.0 + 5.0 * open_bins_count as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin still accommodates next item
        }
    }

    // Prefer filling bins below mean residual (tighter bins first)
    score += 0.5 * (mean_residual - post_residual as f64);

    // Mild progression tilt: later in stream, prefer tighter packing
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward tight fits (small post_residual but still usable).
    if post_residual >= 10 && post_residual <= 25 {
        score -= 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Pressure from number of open bins: discourage opening more bins.
    let open_pressure = open_bins_count as f64 * 1.5;
    score += open_pressure;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless open bins are scarce or fit is poor.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 2.0;
        if post_residual > 50 {
            score -= 20.0; // large leftover in a fresh bin is fine
        }
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 10.0;
    } else if next_item_size > 0 && (post_residual as i64 - next_item_size as i64).abs() <= 5 {
        score += 8.0; // near-miss wastes space for the next item
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Stream progression: late in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit).
    score += 0.05 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let match_gap = post_residual as f64 - nxt;
            // Strong reward when the next item exactly fills this bin afterwards.
            score -= 30.0 * (1.0 - match_gap / bin_capacity as f64);
            // Extra bonus for perfect 2-item fill (post_residual == next_item_size).
            if match_gap == 0.0 {
                score -= 50.0;
            }
        } else {
            // Post-residual too small for next item: dead space penalty scaled by waste.
            let dead = nxt - post_residual as f64;
            score += 0.3 * dead;
        }
    }

    // Penalize post_residual that is unusably small relative to mean residual context.
    let mean_r = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) < mean_r * 0.25 {
        score += 10.0 * (mean_r * 0.25 - post_residual as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Less penalty late in the stream or when few bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * progress;
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    // Mild preference to fill nearly-full bins to close them out.
    if post_residual <= 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream: later on, consolidate into open bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward near-perfect fits: dead space of 0..=3 is excellent.
    if post_residual <= 3 {
        score -= 25.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize awkward mid-range dead space that few future items can use.
    if post_residual > 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if the next item fits into the post residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 18.0 - slack * 0.35;
        } else {
            // Next item would not fit here; slight penalty proportional to wasted opportunity.
            score += 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, use it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: prefer opening a new bin only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base handicap: existing bins with reasonable fits should win.
        score += 8.0;
        // But a fresh bin preserves a large, flexible residual; more attractive early in the stream
        // and when the mean residual of open bins is already high (open bins are fragmented).
        score -= 12.0 * (1.0 - progress);
        score -= (mean_residual / bin_capacity as f64).clamp(0.0, 1.0) * 10.0;
        if open_bins_count == 0 {
            score -= 50.0;
        }
        // If the item is large, a fresh bin keeps room for complementary medium items.
        if item_size > bin_capacity / 2 {
            score -= 6.0;
        }
    }

    // Global fragmentation pressure: when mean residual across open bins is small,
    // avoid spreading items thin; when large, prefer filling the emptiest useful bin.
    let mean_frac = mean_residual / bin_capacity as f64;
    score += (mean_frac - 0.5) * (post_residual as f64 - (bin_capacity as f64 - item_size as f64)) * 0.15;

    // Mild open-bins pressure: many open bins -> discourage opening yet another one.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 1.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;
    let mut score = pr as f64;
    // smooth non-linear coupling of post_residual with stream progress
    score += 12.0 * (x - 0.5) * (x - 0.5) * (progress - 0.5) * cap;
    score -= 8.0 * x * (1.0 - x) * (1.0 - progress);
    // penalize large post residual late in stream (dead space)
    score += 15.0 * x * x * progress;
    // reward tight fits
    score -= 10.0 * (1.0 - x) * (1.0 - x);
    // last chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }
    // lookahead: reward if next item fits post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - x);
    } else if next_item_size > 0 {
        score += 4.0 * x;
    }
    // mean residual deviation coupling
    score += 3.0 * (pr - mean_residual) / cap;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Small dead spaces are unusable for typical items (10..80): penalize.
    if post_residual < 10 {
        score += 120.0;
    }

    // Modulo-class logic on post_residual (capacity = 100): classify leftovers
    // by their usefulness for the NEXT item.
    if next_item_size > 0 {
        let fits_next = next_item_size <= post_residual;
        if fits_next {
            // Reward exact harmonic match: post_residual is a multiple/divisor-friendly class
            let ratio = post_residual as f64 / next_item_size as f64;
            if (ratio - ratio.round()).abs() < 0.01 {
                score -= 60.0; // next item fills bin exactly
            } else {
                score -= 25.0; // next item still fits comfortably
            }
        } else {
            // Next item won't fit here; penalize proportionally to wasted lookahead
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    }

    // Integer-division threshold classes on post_residual:
    // post_residual / 10 gives harmonic deciles of remaining capacity.
    let decile = post_residual / 10;
    match decile {
        0 => score += 80.0,   // 1..9: dead space
        1 => score += 20.0,   // 10..19: only tiny items fit
        2 => score -= 5.0,    // 20..29
        3 => score -= 10.0,   // 30..39
        4 => score -= 15.0,   // 40..49
        5 => score -= 18.0,   // 50..59: versatile
        _ => score -= 10.0,   // 60+: large leftovers, flexible
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 150.0;
        // More attractive late in the stream? No — early bins amortize better;
        // slightly cheaper to open when many items remain.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
        // If current bin would leave a tiny unusable remainder, new bin becomes better.
        if post_residual < 10 {
            score -= 200.0;
        }
        // If next item is huge and current bin is nearly full, prefer fresh bin.
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 30 {
            score -= 60.0;
        }
    }

    // Mild penalty for proliferating open bins relative to mean residual.
    if open_bins_count > 4 && (bin_residual as f64) < mean_residual {
        score += 5.0;
    }

    // Small tie-break: prefer tighter fits (lower post_residual already does this);
    // add slight noise-free coupling with item size for stability.
    score += item_size as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never fit the smallest
    // plausible item are pure waste — penalize them hard.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    } else {
        // Reward large, still-usable residuals.
        score -= (post_residual as f64) * 0.15;
    }

    // Perfect fits are gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual,
    // strongly favor this bin (sets up a chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack * 0.2;
    }
    // If next item does NOT fit, this bin becomes a likely dead end.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 15.0;
    }

    // Last-chance bin: using it avoids opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: penalize spreading across many open bins.
    score += (open_bins_count as f64) * 1.5;

    // Slight preference for tighter bins among equals.
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Mild stream-position drift: late in the stream, be more conservative
    // about leaving awkward gaps.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if post_residual < 20 {
        score += progress * 10.0;
    }

    // New-bin candidate: only attractive when open bins would leave bad gaps.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin, offset by its full flexibility.
        score = 45.0 - (open_bins_count as f64) * 0.5;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // 2-step lookahead: penalize post_residual that is too small for the next item
    // (dead space), reward post_residual that can host the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.6;
        } else {
            score -= 8.0;
        }
    }

    // Compare post_residual against mean residual: leaving less than average
    // residual is good (tight packing).
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor the only bin that can fit the item.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a
    // perfect lookahead match; otherwise prefer existing bins.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 35.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0; // no existing bin fits, must open new one
        }
    }

    // Early in the stream, be more selective (favor tight fits).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 - 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space quadratically; small residuals are precious.
    let pr = post_residual as f64;
    score += 0.35 * pr * pr / bin_capacity as f64;

    // Strong reward for perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Last-chance bin: heavily favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward if the next item can fit in the post residual (chaining).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 12.0 + 0.25 * nxt;
        } else {
            // Penalize creating residual that wastes space relative to the next item.
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            score += 0.15 * gap;
        }
    }

    // Time horizon: early on, be willing to open new bins; late in the stream,
    // consolidate aggressively into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 20.0 * progress;

    // Global state coupling: many open bins with high mean residual -> prefer
    // spreading load; few bins -> pack tightly.
    if open_bins_count > 0 {
        let density = mean_residual / bin_capacity as f64;
        score += 8.0 * density - 0.5 * open_bins_count as f64;
    }

    // New-bin candidate: only attractive when current item is small relative to
    // capacity or no good fits exist (penalize default so it loses ties).
    if bin_residual == bin_capacity {
        score += 30.0 - 0.2 * item_size as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference for bins whose residual is close to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 15.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr;

    // Smooth non-linear coupling: post_residual polynomial in stream progress
    // Late in the stream, small residuals are more valuable (tight packing preferred)
    let tightness = 1.0 - norm_pr * norm_pr;
    let progress_coupling = progress * progress * (1.0 - progress) * 4.0;
    score += progress_coupling * norm_pr * 30.0;
    score -= tightness * norm_item * 10.0;

    // Penalize residuals that cannot fit the next item (smooth quadratic gap)
    if next_item_size > 0 {
        let gap = pr - next_item_size as f64;
        if gap < 0.0 {
            score += gap * gap * 0.05;
        } else {
            score -= (1.0 - (-gap / cap).exp()) * 5.0;
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // Slight penalty for spreading across many bins relative to mean residual
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 8.0;

    // Mild reward for large fills early (keep bins openable)
    score -= (1.0 - progress) * norm_item * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are ideal.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Modulo classes: residuals that are multiples of common item sizes are reusable.
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 { score -= 25.0; }
        if pr % 5 == 0 { score -= 10.0; }
        if pr % 20 == 0 { score -= 12.0; }
        // Dead zones: residuals in awkward bands are hard to fill.
        if pr < 10 { score += 40.0; }
        if pr >= 45 && pr <= 55 { score += 15.0; }
    }

    // Lookahead: does next item fit exactly into post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            if gap <= 10 { score -= 40.0; }
            if gap % 10 == 0 { score -= 8.0; }
        } else {
            // next item won't fit here; slight penalty for large leftover
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full / poor fit.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // penalize new bins early; allow them late or when mean residual is low
        score += 150.0 * (1.0 - progress) + 100.0 * pressure;
        if item_size > 60 { score -= 30.0; } // big items justify fresh bins
    }

    // Prefer tighter existing bins (small residual relative to item).
    score += (bin_residual as f64 - item_size as f64) * 0.2;

    // Mild reward when this bin is far below the mean residual (balancing).
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    } else if post_residual < 35 {
        score += 3.0;
    }

    // Reward tight fits (small post_residual relative to item)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Reward exact / near-exact fills
    if post_residual == 0 {
        score -= 20.0;
    }

    // Pressure from number of open bins: prefer compacting when many bins open
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // New-bin candidate: penalize opening a new bin when stream is early/mid
    // unless open bin fits are poor (fitting_bins_count small handled above).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 30.0 - 15.0 * progress;
        // If next item is large, a fresh bin is more attractive
        if next_item_size > 60 {
            score -= 20.0;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (more filled)
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual large enough to host next item: reward proportionally.
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_ratio = next_item_size as f64 / post_residual as f64;
        score -= 25.0 * fit_ratio;
    } else if next_item_size > 0 {
        // Dead space: post residual too small for the next item.
        let waste = (next_item_size - post_residual) as f64;
        score += 0.35 * waste;
    }

    // Penalize leaving tiny unusable slivers (< 10, min item size).
    if post_residual < 10 {
        score += 30.0;
    }

    // Compare against mean residual: bins already tight vs loose.
    let mean_post = mean_residual - item_size as f64;
    score += 0.15 * (post_residual as f64 - mean_post);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Early in stream: prefer keeping residuals large/flexible.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.10 * post_residual as f64;

    // New-bin candidate: only attractive when current fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = next_item_size > 0 && post_residual < next_item_size.min(10);
        if bad_fit || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            score += 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: small post residual relative to item size
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 20.0 / (1.0 + tightness);

    // Penalize large dead space that no typical item can use
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny slivers are dead space
    }

    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + (next_item_size as f64) * 0.05;
        } else {
            // penalize leaving residual just below next item (worst case)
            let gap = next_item_size as f64 - post_residual as f64;
            if gap < 10.0 {
                score += 6.0 - gap * 0.5;
            }
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Fragmentation pressure: prefer bins below mean residual (consolidate large spaces)
    score += (post_residual as f64 - mean_residual) * 0.3;

    // New bin candidate: penalize opening a new bin early, less so late in stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 - 20.0 * progress;
        // opening a new bin is attractive if it can host next item too with room
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 10.0;
        }
    }

    // Mild preference for filling bins with larger residual when many bins open
    score -= (open_bins_count as f64).ln().max(0.0) * (post_residual as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth non-linear coupling: post_residual penalized more heavily later in the stream
    let progress_curve = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 12.0 * progress_curve * norm_pr * norm_pr * cap;

    // Reward tight fits: small post_residual relative to item size
    score -= 8.0 * norm_item * (1.0 - norm_pr) * cap * (1.0 - progress_curve);

    // Dead-space penalty: post_residual too small to ever fit a future item
    let dead = if norm_pr > 0.0 && norm_pr < norm_next && norm_next > 0.0 {
        (norm_next - norm_pr) / norm_next
    } else {
        0.0
    };
    score += 10.0 * dead * pr * (0.5 + 0.5 * progress);

    // Next-item lookahead: favor bins whose post_residual can still host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0 * norm_next * cap * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild preference against bins far from mean residual (keeps residual distribution balanced)
    score += 0.05 * (pr - mean_residual).abs();

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 6.0 + 14.0 * progress * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: partition capacity into 5 bands.
    let band = post_residual / 20; // 0..=5
    // Dead-space penalty grows superlinearly in the lowest bands.
    score += match band {
        0 => 18.0,               // 1..19 residual: nearly unusable
        1 => 8.0,                // 20..39
        2 => 2.0,                // 40..59
        3 => -2.0,               // 60..79: roomy, good
        _ => -4.0,               // 80..100
    };

    // Perfect-fit reward: residual exactly divisible by common item sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual == 0 {
        score -= 25.0; // exact fill is ideal
    }

    // Modulo coupling with next item: if next item fits exactly into post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual % next_item_size == 0 {
            score -= 10.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in this bin's future residual: penalize slightly
        // unless this bin is nearly full anyway.
        score += (post_residual < next_item_size) as i32 as f64 * 4.0;
    }

    // Last-chance bonus: only one bin fits the item; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: fresh empty bin gets a moderate default,
    // discounted late in the stream or when open bins are congested.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 20.0 * progress - 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative, must open
        }
    }

    // Mild tie-breaker: prefer bins tighter than the mean residual.
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strongly reward.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Strict dead-space avoidance: residuals too small for any item (items >= 1,
    // but practically tiny gaps < 10 are near-unusable) are heavily penalized.
    let dead_zone = 10.0f64;
    if (post_residual as f64) < dead_zone {
        score += (dead_zone - post_residual as f64) * 12.0;
    }

    // Post-residual that cannot host the lookahead item is less valuable.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 8.0;
    } else if next_item_size > 0 && post_residual == next_item_size {
        // Perfect setup for the next item: reward.
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (large dead space would be created). Penalize default new bin otherwise.
    if bin_residual == bin_capacity {
        score += 60.0;
        // Early in stream, new bins are cheap; later, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
        score += open_bins_count as f64 * 0.5;
    }

    // Open-bins pressure: when many bins are open, prefer tightening the tightest.
    score += (post_residual as f64 - mean_residual) * 0.3;
    score += open_bins_count as f64 * (post_residual as f64) * 0.05;

    // Prefer filling larger residuals with larger items implicitly:
    // a big item leaving a small post_residual is good if it's usable.
    if post_residual >= 10 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Aggressive 2-step lookahead: perfect match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // exact chain fit is ideal
        } else if post_residual > next_item_size {
            // next item fits, but penalize by leftover after the chain
            let chain_left = post_residual - next_item_size;
            score += 0.4 * chain_left as f64;
            score -= 15.0; // still reward that the chain fits at all
        } else {
            // next item does NOT fit here: dead space risk
            let gap = (next_item_size - post_residual) as f64;
            score += 0.8 * gap;
        }
    } else {
        // last item: strongly prefer minimal residual
        score += 0.5 * post_residual as f64;
    }

    // Compare residual against mean residual of open bins
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: only bin that can fit the item -> strong reward
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit, especially early/mid stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let waste = (bin_capacity - item_size) as f64;
        score += 30.0 + 0.5 * waste * (1.0 - progress);
        // a new bin is acceptable if it enables a perfect next-item chain
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 55.0;
        }
    }

    // Prefer consolidating into few bins
    score += 0.2 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post-residual, with non-linear penalty on awkward gaps.
    let pr = post_residual as f64;
    score += 0.35 * (pr / 10.0).powi(2);

    // Lookahead: reward bins whose post-residual can host the next item (chain packing).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual as f64 >= nx {
            score -= 12.0 * (1.0 - (nx / 100.0));
        } else {
            // Dead space that the next item cannot use is penalized more late in stream.
            let t = step_index as f64 / total_items.max(1) as f64;
            score += 6.0 * t * (nx - pr).max(0.0) / 20.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Tight-fit reward: near-exact fills are excellent.
    if post_residual <= 5 {
        score -= 15.0;
    }

    // Avoid leaving residuals that nothing can ever use (below minimum item size 1..100 unknown,
    // treat < 10 as risky dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Global state: when many bins are open and mean residual is high, prefer reusing
    // bins with below-average residual (consolidation).
    if open_bins_count > 0 {
        let diff = mean_residual - bin_residual as f64;
        score += 0.08 * diff;
    }

    // New-bin candidate handling: empty bin gets a mild opening cost that grows with
    // how many bins are already open, but shrinks if the item is large.
    if bin_residual == bin_capacity {
        let open_cost = 4.0 + 0.5 * open_bins_count as f64;
        let big_item_bonus = 0.25 * item_size as f64;
        score += open_cost - big_item_bonus;
        // If next item is large and current item leaves little room, opening fresh is fine.
        if next_item_size >= 50 && item_size >= 50 {
            score -= 6.0;
        }
    }

    // Progress horizon: early in the stream, be slightly conservative about opening bins;
    // late in the stream, prioritize closing bins out (favor fuller bins).
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * t * (1.0 - pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: quadratic penalty on wasted space, modulated by stream progress.
    let mut score = x * x * (1.0 + progress) * cap;

    // Cubic coupling: late in the stream, small residuals are increasingly bad.
    score += (x - 0.5) * (x - 0.5) * (x - 0.5) * cap * progress * 2.0;

    // Reward tight fits: subtract when post_residual is small relative to item size.
    let tight = 1.0 - x;
    score -= tight * tight * item_size as f64 * 0.5;

    // Last-chance bonus: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

    // Lookahead: penalize if next item cannot fit into post_residual.
    if next_item_size > 0 {
        let gap = next_item_size as f64 - pr;
        if gap > 0.0 {
            score += gap * (0.3 + 0.7 * progress);
        } else {
            score -= 5.0;
        }
    }

    // Penalize deviation from mean residual (encourage balanced bins).
    score += (pr - mean_residual).abs() * 0.25;

    // New-bin candidate: smooth bias that grows when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64 * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in [1,9] is nearly unusable
    // (min item is 10), so penalize small nonzero post-residuals hard.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        score += 25.0 * (10 - pr) as f64;
    }
    // Perfect fit reward
    if pr == 0 {
        score -= 30.0;
    }

    // Harmonic classes via integer division: post_residual in [10,19] is a
    // "one small item" slot — mildly desirable; [20,49] medium; large residual
    // keeps bin flexible.
    let class = pr / 10;
    match class {
        1 => score += 3.0,      // 10..19: only fits tiny items, some waste risk
        2 | 3 => score -= 4.0,  // 20..39: useful mid slots
        4 | 5 => score -= 6.0,  // 40..59: very useful
        _ => {}
    }

    // Pairing with lookahead: if next item exactly fits the post_residual,
    // strongly reward this bin (perfect chain).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr && pr - next_item_size < 10 {
            // next item would leave near-dead space
            score += 8.0;
        } else if next_item_size > pr {
            // next item can't go here; residual stays for later items
            score += 2.0;
        }
    } else {
        // Last item: minimize leftover waste aggressively
        score += pr as f64 * 0.5;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: empty bin residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is good when current item is large and the
        // post_residual still forms a useful class (>= 20), or when many
        // open bins already exist with small mean residual (fragmentation).
        let pr_frac = post_residual as f64 / cap;
        if pr_frac >= 0.2 {
            score -= 10.0 + 5.0 * pr_frac;
        } else {
            // placing a large item in a fresh bin creates a bad small class
            score += 12.0;
        }
        // With few open bins, prefer packing into existing bins.
        if open_bins_count <= 2 {
            score += 10.0;
        }
        // Late in the stream, prefer using existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Coupling with mean residual: if this bin's residual is far below the
    // mean, it's a "tight" bin — good to fill it now.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 && bin_res_f < mean_residual {
        score -= 3.0 * (mean_residual - bin_res_f) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item.max(10) {
        score += 500.0;
    }

    // Penalize small unusable gaps (< 20) much harder than proportional residual.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 8.0;
    }

    // Reward tight fits strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage proliferation of bins.
    score += open_bins_count as f64 * 2.5;

    // Mean residual coupling: prefer filling bins with above-average residual less
    // (keep big residual bins flexible), favor below-mean bins for tight fits.
    if (bin_residual as f64) > mean_residual + 20.0 && post_residual > 0 {
        score += 5.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit post residual but could fit another residual, slight penalty.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 4.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: a fresh empty bin should only win when the item
    // fits poorly everywhere else.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0 + open_bins_count as f64 * 1.5;
        // But if the best alternative would leave tiny dead space, new bin is fine.
        if post_residual > 40 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fit), scaled to bin capacity.
    score += (post_residual as f64 / bin_capacity as f64) * 50.0;

    // Aggressive 2-step lookahead: reward if the next item exactly fits the
    // residual left behind (perfect chaining), penalize if it overshoots.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if (post_residual as f64 - next).abs() < 1.0 {
            score -= 120.0; // perfect chain: post_residual == next_item_size
        } else if post_residual as f64 >= next {
            score -= 60.0 * (1.0 - (post_residual as f64 - next) / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: dead-space penalty grows with waste
            score += 0.5 * (post_residual as f64) * (next / bin_capacity as f64);
        }
    }

    // Coupling with mean residual: bins already below average residual are
    // "loose" — filling them is cheap; above-average residual bins should be
    // filled preferentially to consolidate space.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize opening new bins when plenty of open bins exist and fit is loose.
    if bin_residual == bin_capacity {
        // brand-new bin candidate: only attractive if item is large relative to capacity
        // and no open bin fits well; baseline cost of a fresh bin.
        score += 25.0 + 0.5 * (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    // Early in the stream, be slightly more willing to open bins (future items unknown);
    // late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Prefer leaving residuals that are hard to fill (small odd leftovers) even less.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny unusable sliver
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins that end up nearly full.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Perfect fit gets a large bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0;
    }

    // Lookahead: penalize leaving a gap that could have fit the next item
    // (dead space the next item can't use), but reward leaving a gap the
    // next item exactly fills.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item could still go here; slight bonus for keeping a
            // useful residual, scaled by how well it would fill.
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 8.0 * next_fill;
        } else {
            // Gap too small for the next item: penalize proportionally to
            // how wasted it is, unless the bin is almost full anyway.
            let waste = post_residual as f64 / next_item_size.max(1) as f64;
            score += 6.0 * waste;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when no open bin offers a decent fit. Penalize the empty-bin
    // candidate, but relax the penalty when the current bin's fit is bad
    // (large post_residual) or when many bins fit (plenty of options).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 25.0;
        // If this bin's post-fit residual is large, the fit is poor;
        // make a new bin more attractive.
        if post_residual as f64 > mean_residual {
            new_bin_penalty -= 10.0;
        }
        // Late in the stream, consolidating is cheaper than opening bins.
        let progress = if total_items > 0 {
            step_index as f64 / total_items as f64
        } else {
            0.0
        };
        new_bin_penalty += 15.0 * progress;
        // If several bins already fit, no reason to open another.
        if fitting_bins_count > 2 {
            new_bin_penalty += 10.0;
        }
        score += new_bin_penalty;
    }

    // Global state: prefer packing into bins whose residual is above the
    // mean (consumes the "roomier" bins first, keeping tight bins tight).
    let residual_diff = bin_residual as f64 - mean_residual;
    score += 0.05 * residual_diff;

    // Mild penalty for scattering across many open bins when residual
    // is small relative to capacity (encourages consolidation).
    if open_bins_count > 3 && post_residual > 0 && post_residual < bin_capacity / 5 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer small post-residual, with non-linear (quadratic) coupling
    let mut score = pr + 0.9 * (pr / cap) * pr;

    // Smooth polynomial interaction between post-residual and stream progress:
    // later in the stream, tight fits matter more; dead space penalized super-linearly
    let norm_pr = pr / cap;
    let interact = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 18.0 * interact;

    // Reward near-perfect fits smoothly (post_residual close to 0 or very small)
    score -= 12.0 * (-pr / (0.25 * cap)).exp();

    // Penalize leaving a residual that likely becomes dead space: pr < smallest item
    let dead = ((10.0 - pr) / 10.0).max(0.0);
    score += 8.0 * dead * dead;

    // Lookahead: bonus if next item can use the resulting residual
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if ni <= pr {
            let fit_quality = 1.0 - ((pr - ni) / cap).abs();
            score -= 6.0 * fit_quality;
        } else {
            score += 4.0 * ((ni - pr) / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: keep it competitive only when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).max(0.0);
        score = 0.5 * cap + 10.0 * fragmentation * fragmentation - 5.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that no plausible item (1..=100) can use
    // is the worst outcome. Classify post_residual into usability bands.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit — strongly reward.
        score -= 1000.0;
    } else if pr < 10 {
        // Tiny dead space; nearly perfect.
        score -= 200.0 + (10 - pr) as f64 * 10.0;
    } else if pr <= 50 {
        // Usable mid-range residual: reward proportionally to how much stays usable.
        score -= 50.0 + (50 - pr) as f64 * 0.5;
    } else {
        // Large residual is fine (bin stays flexible) — mild reward.
        score -= 20.0;
    }

    // Harmonic classes via integer division: residual mod common item sizes.
    // If post_residual is an exact multiple of a common small size, future items
    // can tile it perfectly — reward.
    for m in [10u32, 20, 25, 50] {
        if pr >= m && pr % m == 0 {
            score -= 30.0;
            break;
        }
    }

    // Lookahead coupling: can next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0; // perfect chain
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            if slack < 10 {
                score -= 150.0; // near-perfect chain
            } else {
                score -= 20.0;
            }
        } else {
            // Next item cannot fit here; residual becomes dead weight for the lookahead.
            score += (next_item_size - pr).min(50) as f64 * 0.8;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are crowded
    // or this item fits terribly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = open_bins_count as f64 * mean_residual < 60.0;
        score += 80.0 + 60.0 * (1.0 - progress);
        if crowded {
            score -= 100.0; // few usable bins left: allow opening
        }
        if item_size >= 80 {
            score -= 40.0; // huge item: fresh bin often best
        }
    } else {
        // Prefer bins whose residual is closest to the item (tight fit) among open bins.
        let tightness = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
        score += tightness * 40.0;
    }

    // Mild preference to keep mean residual balanced: avoid dumping into already-small bins.
    if (bin_residual as f64) < mean_residual * 0.5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that can never be filled again are pure waste.
    // Assume future items are at least ~10 units; a residual below that threshold is dead.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += 1000.0; // catastrophic: unusable sliver
    } else if (post_residual as f64) < dead_threshold * 2.0 {
        // small gap: only fillable by tiny items, penalize extra
        score += 40.0 * (dead_threshold * 2.0 - post_residual as f64);
    }

    // Penalize residual that cannot fit the lookahead item (dead space w.r.t. next item),
    // but reward residual that exactly accommodates it.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64) >= nr {
            score -= 8.0; // lookahead fits, good chaining
        } else {
            score += 0.5 * (nr - post_residual as f64); // partial dead space penalty
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open
    // and this bin is a decent fit. New-bin candidate (residual == capacity) gets a penalty
    // that grows with open_bins_count and with how well existing bins fit.
    if bin_residual == bin_capacity {
        // new bin candidate: base cost of opening a bin
        score += 25.0 + 3.0 * open_bins_count as f64;
        // if this is the only fitting bin, opening new may still be necessary -> soften
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // early in stream, opening bins is cheaper
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    } else {
        // existing bin: reward using it, especially when it's the last chance
        if fitting_bins_count == 1 {
            score -= 30.0;
        }
        // reward tight fits relative to mean residual
        score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: minimal dead space after placement.
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward bins whose post_residual exactly matches
    // the next item (chain fit), penalize near-misses proportionally.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if gap == 0.0 {
            score -= 50.0;
        } else if (post_residual as i64 - next_item_size as i64) > 0 {
            // next item fits exactly-ish; reward tight couplings
            score -= 40.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit in leftover: penalize leftover a bit more
            score += 10.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative-to-mean adjustment: bins with residual far below the mean
    // are the "tight" bins; placing there consolidates waste.
    let residual_f = bin_residual as f64;
    score += 0.5 * (residual_f - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless the current item
    // is large and would leave a very small unusable remainder elsewhere.
    if bin_residual == bin_capacity {
        let tightness = (item_size as f64) / (bin_capacity as f64);
        score += 45.0 - 30.0 * tightness;
        // Lookahead: opening a new bin is good if next item pairs with the remainder
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 20.0 * ((bin_capacity - item_size - next_item_size) as f64 / bin_capacity as f64);
        }
    }

    // Late in the stream: be conservative with new bins, prefer filling existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 15.0 * progress;
    } else {
        score -= 10.0 * progress;
    }

    // Slight penalty for spreading across many open bins.
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: near-perfect packing gets strong discount.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    if fit_ratio > 0.85 {
        score -= 25.0 * (fit_ratio - 0.85) / 0.15;
    }

    // Penalize dead space that no future item (>=10) can use.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // tiny dead space is fine (bin nearly full)
    } else if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // next item won't fit here; slightly penalize leaving medium gaps
            score += (post_residual as f64) * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when item is large relative
    // to capacity or no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        if large_item > 0.6 {
            score -= 10.0 * large_item; // big items start fresh bins
        } else {
            score += 20.0 + 10.0 * (1.0 - large_item); // discourage wasting fresh bins
        }
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into existing bins (penalize new bins implicitly
    // by rewarding bins below mean residual, i.e. fuller ones).
    if bin_residual < bin_capacity {
        score -= 0.15 * (mean_residual - bin_residual as f64).max(0.0);
    }

    // Time horizon: early in stream, be exploratory (favor tight fits more);
    // late in stream, prefer filling existing bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - fit_ratio).max(0.0) * -1.0; // relax fit strictness late
    score -= 5.0 * (1.0 - progress) * fit_ratio; // extra tight-fit reward early

    // Crowding: when many bins are open, avoid creating more low-residual sprawl.
    if open_bins_count > 8 {
        score += 0.5 * ((open_bins_count - 8) as f64).min(10.0) * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let pr = post_residual as f64;
    let prn = pr / bin_capacity as f64;
    let p1 = 1.0 - progress;
    let coupling = prn * prn * (1.0 + 2.0 * p1) - prn * p1 * p1;
    score += 40.0 * coupling;

    // Reward tight fits more strongly as stream progresses
    let fit = 1.0 - prn;
    score -= 30.0 * fit * fit * (0.5 + progress);

    // Penalize dead space relative to mean residual (smooth quadratic)
    let dead = (pr - mean_residual) / bin_capacity as f64;
    score += 15.0 * dead * dead * p1;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: penalize if next item cannot use the post residual
    if next_item_size > 0 && next_item_size > post_residual {
        score += 10.0 * (1.0 - prn * prn);
    } else if next_item_size > 0 {
        score -= 8.0 * (1.0 - (next_item_size as f64 / pr).abs().min(1.0));
    }

    // Mild penalty on bin proliferation early on
    score += 0.5 * (open_bins_count as f64) * p1 * p1;

    // New-bin candidate: prefer it only when residuals are large and stream is early
    if bin_residual == bin_capacity {
        score -= 12.0 * p1 * p1 * (1.0 - mean_residual / bin_capacity as f64);
        score += 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" classes
    // (large enough to likely fit a future item) should be preferred.
    let post = post_residual as i64;
    let cap = bin_capacity as i64;

    // Dead-space penalty: residuals in the awkward zone (1..=9) are nearly unusable.
    if post > 0 && post < 10 {
        score += 25.0;
    }

    // Harmonic class reward via integer division thresholds on post_residual.
    // Residuals that are multiples of common item-size blocks (10s) are "harmonic"
    // with the item-size granularity and likely reusable.
    let harmonic = post % 10 == 0 && post > 0;
    if harmonic {
        score -= 8.0;
    }

    // Class of residual by quarter-capacity tiers.
    let quarter = cap / 4;
    if post >= 3 * quarter {
        score -= 5.0; // very roomy leftover, good bin to keep filling
    } else if post >= quarter {
        score -= 2.0;
    } else if post > 0 {
        score += 6.0; // small but not dead leftover: moderately wasteful
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post as u32 {
            score -= 30.0;
        } else if next_item_size <= post as u32 {
            // next item fits: reward scaled by how well it fills leftover
            let fill = next_item_size as f64 / post as f64;
            score -= 6.0 + 10.0 * fill;
        } else {
            // next item won't fit here; penalize leaving large-but-not-fitting space
            let gap = next_item_size as f64 - post as f64;
            if gap < 20.0 {
                score += gap * 0.5;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, softened when many items remain
        // and open bins are congested.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / bin_capacity as f64);
        score = 40.0 - 10.0 * progress + congestion * 2.0;
        // If the current item is large relative to capacity, new bin is fine.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
        // If next item is large and current item small, better to pack current
        // into an existing bin and save the new bin for the big one.
        if next_item_size > bin_capacity / 2 && item_size < bin_capacity / 4 {
            score += 20.0;
        }
    }

    // Mild tie-break toward tighter bins when many bins are open.
    score += 0.01 * open_bins_count as f64 * (post as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A post_residual that is too small to fit typical future items (>= 10) is wasted space.
    let dead_threshold = 9.0;
    if (post_residual as f64) < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual as f64);
    }
    // Also penalize moderately small residuals that likely become dead space,
    // scaled by how small they are relative to capacity.
    if post_residual > 0 && post_residual < 30 {
        score += 0.5 * (30 - post_residual) as f64;
    }

    // Reward tight fits: small post_residual gets a bonus.
    score -= 1.5 * (bin_capacity - post_residual.min(bin_capacity)) as f64 * 0.0; // no-op guard
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    score += 2.0 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 5.0; // next item won't fit here; mild penalty
    }

    // New-bin candidate handling: empty bin gets a moderate default score;
    // only chosen when open bins offer poor fits.
    if bin_residual == bin_capacity {
        score += 10.0 + mean_residual * 0.1;
    }

    // Stream progression: later in the stream, prefer consolidating into open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fills (small post_residual already handled).

    // Aggressive 2-step lookahead: perfect chain reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // post_residual exactly matches next item: bin becomes perfectly full after next step
            score -= 60.0;
        } else if post_residual > next_item_size {
            // next item fits after this placement; reward closeness of the chain
            let chain_gap = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - chain_gap / bin_capacity as f64);
        } else {
            // next item won't fit: penalize proportionally to stranded space
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.15 * stranded;
        }
    }

    // Compare against mean residual: bins already fragmented get deprioritized
    score += 0.10 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist among open bins
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive if item is large relative to capacity
        // (few open bins could host it well) or stream is early
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let item_frac = item_size as f64 / bin_capacity as f64;
        score += 30.0 - 25.0 * item_frac + 10.0 * progress;
        if open_bins_count == 0 {
            score -= 100.0; // nothing open: must open
        }
    }

    // Small reward for very tight placements overall
    if post_residual < 10 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) nonlinearly.
    score -= 40.0 * (-post_residual as f64 / 12.0).exp();

    // Penalize dead space that cannot plausibly host future items:
    // if post_residual is below the smallest plausible item (1..100 stream),
    // small residuals are near-useless.
    if post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if next item needs more space than post_residual,
    // this bin's leftover is likely dead.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (post_residual - next_item_size) as f64 / 10.0;
        } else {
            score += 8.0 * (next_item_size - post_residual).min(30) as f64 / 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is attractive only when
    // existing residuals are large and fragmented relative to the item.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = mean_residual - item_size as f64;
        // Penalize new bin when open bins are well-utilized / few.
        score += 15.0 + open_bins_count as f64 * 2.0;
        // Reward new bin when mean residual is much larger than the item
        // (existing bins are too full relative to typical slack) and stream is young.
        score -= (fragmentation * 0.5).max(0.0) * (1.0 - progress) * 2.0;
        // Late in the stream, prefer consolidating into open bins.
        score += progress * 20.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.5;

    // Prefer bins whose residual deviates from the mean in a useful way:
    // filling below-average-residual bins keeps large slack bins flexible.
    if bin_residual < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = post / cap;

    // Base: quadratic penalty on post residual (dead space), scaled by stream progress
    let mut score = post * (1.0 + 0.5 * progress) + 40.0 * fit_norm * fit_norm;

    // Cubic coupling of post-residual with progress: late stream punishes waste more
    score += 30.0 * fit_norm.powi(3) * (0.5 + progress);

    // Last-chance bonus: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 25.0 * (1.0 - post / cap) * (nxt / cap);
        } else {
            // penalize leaving residual that no typical item can use
            score += 10.0 * (1.0 - post / cap) * (1.0 - progress);
        }
    }

    // Prefer bins tighter than mean residual (better fill)
    score += 8.0 * ((post - mean_residual) / cap);

    // Mild preference for using existing bins over opening new ones,
    // weakening as open bins accumulate
    if bin_residual == bin_capacity {
        score += 15.0 + 5.0 * (open_bins_count as f64).sqrt();
    } else {
        score -= 5.0;
    }

    // Smooth progress interaction: exact-fill reward decays over time
    if post == 0 {
        score -= 50.0 * (1.0 - 0.3 * progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Harmonic class of post_residual modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = (bin_capacity / 4) as u32;
    let eighth = (bin_capacity / 8) as u32;
    let r8 = post_residual % eighth.max(1);
    let r4 = post_residual % quarter.max(1);

    // Reward post-residuals that align with common small-item classes (multiples of 8, 16).
    if r8 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if r4 == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Integer division thresholds: dead space penalty grows in steps.
    if post_residual < eighth {
        score += 25.0; // nearly unusable sliver
    } else if post_residual < quarter {
        score += 8.0;
    } else if post_residual > (bin_capacity * 3 / 4) {
        score -= 4.0; // large leftover, still flexible
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let exact = next_item_size == post_residual;
        score -= if exact { 40.0 } else { 18.0 * (next_item_size as f64 / pr.max(1.0)) };
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover won't serve next item: penalize proportionally
        score += 6.0 * (1.0 - pr / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: make it attractive only when open bins are fragmented.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        // Prefer new bin when existing residuals are small and many bins open.
        score += 20.0 + 30.0 * fragmentation + 10.0 * progress;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open new bin
        }
    }

    // Mild preference to balance residuals toward mean.
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 {
        let gap = post_residual as f64;
        // Anything below ~10 (min item size) is pure dead space.
        if gap < 10.0 {
            score += (10.0 - gap) * 12.0;
        } else if gap < 20.0 {
            score += (20.0 - gap) * 4.0;
        } else if gap < 30.0 {
            score += (30.0 - gap) * 1.5;
        }
    } else {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Exact-fill bonus scaled by tightness.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 15.0 * tightness * tightness;

    // Open-bin pressure: prefer filling existing bins when many are open,
    // but tolerate new bins early in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    score += bin_pressure * 2.0 * (0.3 + 0.7 * progress);

    // Mean residual coupling: if this bin is far from the mean residual,
    // placing here either wastes a big gap or concentrates small ones.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Partial lookahead fit: mild reward proportional to how well it fits.
        score -= 5.0 * (next_item_size as f64 / post_residual as f64);
    }

    // New-bin candidate: opening a fresh bin is only attractive when no open bin
    // gives a tight fit; penalize new bins when good alternatives exist.
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count > 0 {
            let best_possible = 0.0f64;
            let _ = best_possible;
            // If any open bin could fit tightly, discourage new bin more.
            score += 10.0 * (fitting_bins_count as f64).min(3.0);
        }
        // Early stream: new bins are cheaper.
        score -= 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Near-match: next item fits with small slack -> moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item won't fit: dead space penalty grows with tightness of fit now.
        let waste = (post_residual as f64 / bin_capacity as f64).powi(2);
        score += 15.0 * waste;
    }

    // Penalize small unusable residuals (< typical minimum item size).
    if post_residual < 10 {
        score += 20.0;
    }

    // Relative to mean residual: prefer bins whose residual deviates favorably.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: prefer it only when it enables a perfect 2-step chain,
    // otherwise penalize slightly so existing bins are used first.
    if bin_residual == bin_capacity {
        if next_item_size > 0 && (bin_capacity - item_size) == next_item_size {
            score -= 35.0;
        } else {
            score += 10.0;
        }
    }

    // Late in stream: tighten packing, avoid leaving many open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (open_bins_count as f64 / (open_bins_count.max(1) as f64 + 5.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post-residual is good, but reward exactness).
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating tiny dead space that nothing can reuse (1..9 units).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward; if this
    // placement wastes space the next item could have used, penalize.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size {
            score -= 5.0 * (next_item_size as f64 / post_residual as f64);
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // New-bin candidate handling: only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; shrink as stream progresses (sunk bins).
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut open_cost = 40.0 - 20.0 * progress;
        // If many bins are open with slack, discourage opening yet another.
        open_cost += 2.0 * open_bins_count as f64;
        // If mean residual is large, opening a new bin is wasteful.
        open_cost += mean_residual * 0.3;
        // If next item is large, a fresh bin gives future flexibility.
        if next_item_size >= 50 {
            open_cost -= 10.0;
        }
        // If only one bin fits and it's this empty candidate, allow it.
        if fitting_bins_count == 0 {
            open_cost -= 100.0;
        }
        score = open_cost + post_residual as f64;
    }

    // Mild preference for fuller bins relative to global mean residual.
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual cost, mildly non-linear (dead space penalty grows quadratically)
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Stream-progress coupling: late in the stream, tolerate less waste (quadratic in progress)
    let late = progress * progress;
    score += 60.0 * late * norm_pr;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 25.0 * progress * tightness * tightness;

    // Last-chance bin: strong bonus, scaled by progress
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: if next item fits exactly in post_residual, reward this placement
    if next_item_size > 0 && next_item_size <= post_residual {
        let diff = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - diff / cap);
    } else if next_item_size > post_residual && next_item_size > 0 {
        score += 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins below mean residual (concentrate waste)
    let dev = (mean_residual - pr) / cap;
    score -= 15.0 * dev * (1.0 - progress);

    // New-bin candidate penalty: discourage opening new bins unless residual is very small
    if bin_residual == bin_capacity {
        score += 35.0 - 20.0 * progress;
        // But allow new bins when open bins are nearly full on average
        score -= 20.0 * (1.0 - mean_residual / cap) * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod 10 buckets capture
    // "how far from a nice fill" the bin ends up after placement.
    let harmonic_class = post_residual % 10;
    // Penalize residuals that are small-but-unusable (dead space of 1..=9),
    // with the worst class being tiny odd leftovers.
    if post_residual > 0 {
        score += match harmonic_class {
            0 => -6.0,                       // perfectly harmonic residual
            5 => -3.0,                       // half-harmonic
            2 | 4 | 6 | 8 => -1.5,           // even classes: friendlier
            1 | 3 | 7 | 9 => 2.5,            // odd classes: awkward
            _ => 0.0,
        };
    }

    // Integer-division thresholds on post_residual: a residual that could
    // still host a mid-size item (>= 20) is valuable; a residual that can
    // only host nothing is dead space.
    if post_residual >= 50 {
        score -= 4.0;
    } else if post_residual >= 30 {
        score -= 2.0;
    } else if post_residual >= 10 {
        score += 1.0;
    } else if post_residual == 0 {
        score -= 10.0; // perfect fit: strongly preferred
    } else {
        score += 5.0; // dead space 1..=9
    }

    // Lookahead coupling: does the residual class match the next item's class?
    if next_item_size > 0 && post_residual >= next_item_size {
        // Next item fits here afterwards: big reward.
        score -= 3.0 + (next_item_size as f64) / 10.0;
        // Extra reward if post_residual - next_item lands on a harmonic class.
        let nxt_post = post_residual - next_item_size;
        if nxt_post % 10 == 0 {
            score -= 2.0;
        } else if nxt_post % 5 == 0 {
            score -= 1.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item will not fit here: mild penalty proportional to overshoot class.
        let gap = next_item_size - post_residual;
        score += (gap % 10) as f64 * 0.2;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible (creates dead space).
    if fitting_bins_count == 1 && post_residual >= 0 {
        score -= 3.0;
        if post_residual < 10 && post_residual > 0 {
            score += 4.0; // but not if it would strand dead space
        }
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer reusing an existing bin with a decent fit; only open a new
        // bin when all fits are bad (large post_residual dead space) or few
        // bins are open early in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let best_existing_bonus = 6.0 + progress * 4.0;
        score += best_existing_bonus;
        // Opening early is cheaper when few bins exist and mean residual is high.
        if open_bins_count < 3 {
            score -= 2.0;
        }
        if mean_residual < 15.0 {
            score -= 1.5;
        }
    }

    // Slight tie-break toward fuller bins relative to the fleet mean residual.
    score -= (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in (0, 10) are unusable for the
    // minimum item size; penalize them hard so we prefer either exact fits
    // or residuals that remain serviceable.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Residuals just above the minimum item size are fragile; mildly penalize.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small usable leftover) proportionally.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.25;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly reward this placement (creates a perfect two-item chain).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits: mild reward proportional to how well it fills.
        score -= (post_residual as f64 - next_item_size as f64) * 0.5;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use the leftover; penalize proportional to waste.
        score += post_residual as f64 * 0.3;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over spreading; make new bins relatively less attractive.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Mean residual coupling: if this bin's residual is below average, it is
    // relatively full — reward using it; if above average, penalize slightly.
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: baseline so it's chosen only when it genuinely
    // beats all open bins (tight fits / lookahead chains win otherwise).
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
    }

    // Late-stream consolidation: near the end, minimize fragmentation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual)
    score -= 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // 2-step lookahead: if the next item fits into the post_residual, reward heavily
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // next item fits: bonus proportional to how well it fills the remainder
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * fill;
            // perfect 2-item completion of the bin
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // next item cannot use the leftover space: penalize dead space
            score += 6.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
    }

    // Compare post_residual against mean residual: leaving below-average slack is good
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize opening a new bin when decent alternatives exist
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
        // allow new bin early in the stream when few bins are open
        if open_bins_count < 2 {
            score -= 12.0;
        }
    }

    // Slight preference for reusing bins as stream progresses
    score += 0.001 * step_index as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small dead space quadratically: residuals that nothing can use.
        let tiny = if post_residual < 10 { 1.0 } else { 0.0 };
        score += tiny * (10.0 - post_residual as f64).powi(2) * 4.0;
    }

    // Lookahead: bonus if the next item fits into post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0 + (post_residual - next_item_size) as f64 * 0.5;
        } else {
            // Next item won't chain here; penalize wasted residual relative to mean state.
            score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;
        }
    } else {
        // Last item: prefer exact fill above all.
        score -= (bin_capacity - post_residual) as f64 * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, favor using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    } else if fitting_bins_count > 1 {
        // Multiple options: prefer the bin whose residual is closest to the item (best fit).
        score -= (bin_residual - item_size) as f64 * 0.8;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are large and unusable, or late in the stream with many open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let usable = fitting_bins_count > 0; // 0 => no open bin fits, new bin is forced anyway
        if usable {
            // Penalize opening a new bin mildly; scale with stream progress and open bins.
            score += 40.0 + progress * 30.0 + (open_bins_count as f64) * 2.0;
            // But if mean residual is huge (fragmented state), opening a fresh bin is fine.
            score -= mean_residual * 0.4;
        } else {
            // Forced new bin: neutral-ish, slight preference for early opening.
            score -= 10.0;
        }
    }

    // Time horizon: early in stream, keep bins tight for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Mild preference for bins already below mean residual (consolidation).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit_frac = item_size as f64 / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr_norm * (1.0 + 0.6 * pr_norm);

    // Smooth polynomial coupling with stream progress:
    // early on, keep bins flexible (penalize very small residuals mildly less),
    // late in stream, strongly favor filling bins tightly.
    let tightness = 1.0 - (pr_norm * pr_norm);
    score += 0.8 * progress * tightness * fit_frac;
    score -= 0.5 * (1.0 - progress) * pr_norm * (1.0 - pr_norm);

    // Dead-space penalty: cubic growth for unusable slivers
    if pr > 0 {
        let dead = 1.0 - (pr / cap).min(1.0);
        score += 0.3 * dead * dead * dead;
    }

    // Lookahead coupling: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        let gap = (nx - pr_norm).abs();
        score += 0.9 * fit_next * (0.5 + 0.5 * progress) * (1.0 - gap);
        score -= 0.4 * (1.0 - fit_next) * (1.0 - progress);
    }

    // Last-chance bonus: only bin that fits; strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    } else {
        // mild penalty for spreading across many fitting bins
        score += 0.05 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mean residual coupling: prefer bins deviating smoothly from mean to balance load
    let dev = (pr - mean_residual) / cap;
    score += 0.2 * dev * dev - 0.1 * dev;

    // New-bin candidate: penalize opening a bin unless residuals are all poor
    if bin_residual == bin_capacity {
        let pressure = (mean_residual / cap).powi(2);
        score += 2.5 - 2.0 * pressure * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_class = (post_residual % 10) as f64;
    let post_half = (post_residual / (bin_capacity / 2).max(1)) as f64; // 0,1,2 by integer division

    // Reward residuals that form "harmonic" classes likely to be filled later.
    // Class 0 mod 10 residuals are ideal (small dead space, aligned sizes).
    score -= (10.0 - post_class) * 0.35 * (post / cap);

    // Penalize large residuals in the awkward middle band (cap/3..cap/2)
    // via integer-division thresholds on post_residual.
    if post_residual > bin_capacity / 3 && post_residual < bin_capacity / 2 {
        score += 6.0;
    }
    // Small residuals (< 10) are near-perfect closures: strong reward.
    if post_residual < 10 {
        score -= 8.0;
    }
    // Half-full threshold class: residual exactly cap/2 or cap/4 are flexible.
    if post_residual == bin_capacity / 2 || post_residual == bin_capacity / 4 {
        score -= 3.0;
    }

    // Lookahead coupling: next item's harmonic class vs post_residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item fits here: reward exact/near-exact couplings.
            let gap = post_residual - next_item_size;
            score -= 4.0 + (10 - (gap % 10) as i64).min(10) as f64 * 0.2;
        } else {
            // Next item cannot fit: penalize more when this bin was our only option.
            score += 2.0 + if fitting_bins_count <= 1 { 4.0 } else { 0.0 };
        }
        // Penalize if next item's class leaves a dead zone modulo 10.
        let nz = (next_item_size % 10) as f64;
        if nz > 0.0 && post > 0.0 && (post % 10.0) < nz {
            score += 1.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 7.0;
    }

    // Stream progression: late in stream, prefer closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress * (post / cap);

    // New-bin candidate (empty bin): make it moderately attractive only when
    // open bins are congested or residual would be dead space.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (mean_residual / cap + 1.0);
        score = cap as f64 * 0.9 - congestion * 2.0 - progress * 5.0;
        if item_size > bin_capacity * 3 / 4 {
            score -= 10.0; // big items prefer fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    }
    // Penalize leaving a gap that neither fits the next item nor is useful.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 20 {
        score += 25.0;
    }

    // Open-bin pressure: with many open bins, favor filling existing ones;
    // with few open bins, opening a new bin is cheaper.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 6.0;

    // Prefer bins whose residual is far below the mean (tighter bins get priority).
    score += (mean_residual - bin_residual as f64) * 0.4;

    // New-bin candidate: penalize mildly so it only wins when open bins are bad,
    // but relax the penalty when open-bin count is high (spread load).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 55.0 - pressure * 4.0 + post_residual as f64 * 0.3;
        score += new_bin_penalty.max(5.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Dead space: post_residual too small for the next item.
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += 0.6 * waste;
    }

    // Reward bins whose residual is far below the mean (tight, well-packed bins).
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New empty bin candidate: only attractive when current bins are crowded.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score += 55.0 - 40.0 * pressure;
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
    }

    // Slight late-stream conservatism: keep residuals usable near the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 20.0;

    // Penalize wasted space quadratically for very small leftovers (dead space)
    if post_residual < 10 {
        score -= 15.0;
    } else {
        score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when existing fits are poor
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Prefer new bins early (long horizon ahead), penalize late
        score += 30.0 * (1.0 - progress) - 10.0 * progress;
        // If item is large and next item too, a fresh bin gives flexibility
        if next_item_size > 0 && next_item_size + item_size > bin_capacity / 2 {
            score -= 12.0;
        }
        // Few open bins with high mean residual: reuse is likely fine
        if open_bins_count > 0 && mean_residual > item_size as f64 * 1.5 {
            score += 20.0;
        }
    }

    // Lookahead: if next item fits exactly into post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 18.0;
        } else {
            score += gap * 0.3;
        }
    }
    // If next item cannot fit in the leftover, mild penalty proportional to waste
    if next_item_size > post_residual {
        score += (next_item_size - post_residual) as f64 * 0.15;
    }

    // Prefer bins whose residual is closest to the item (perfect-fitting bonus)
    let fit_gap = (bin_residual - item_size) as f64;
    score += fit_gap * 0.1;

    // Mild preference for bins below mean residual (consolidate emptier bins)
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Time-horizon modulation: as stream progresses, tighten packing more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Crowding: many open bins -> favor filling existing ones
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post_norm = post / cap;

    let mut score = post;

    // Smooth non-linear waste penalty: quadratic coupling of post-residual with stream progress
    score += 40.0 * post_norm * post_norm * (0.4 + 0.6 * progress);

    // Cubic interaction: penalize small dead space more as stream progresses
    score += 25.0 * post_norm.powi(3) * progress;

    // Favor tight fits relative to mean residual (smooth coupling)
    let mean_norm = mean_residual / cap;
    score -= 30.0 * post_norm * (1.0 - mean_norm).clamp(0.0, 1.0);

    // Last-chance bin bonus (smooth, not piecewise)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 18.0 * last_chance * (1.0 - post_norm);

    // Lookahead coupling: reward residual that can still hold the next item
    if next_item_size > 0 {
        let next_norm = next_item_size as f64 / cap;
        let usable = (post_norm - next_norm).max(0.0);
        score -= 15.0 * usable;
        // penalize residual just barely unable to fit next item (smoothly)
        let gap = (next_norm - post_norm).max(0.0);
        score += 20.0 * (1.0 - gap).clamp(0.0, 1.0) * gap;
    }

    // Mild penalty for bin scarcity coupling
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * post_norm;

    // New-bin candidate: neutral-ish baseline with smooth progress discount
    if bin_residual == bin_capacity {
        score = cap * (0.55 + 0.35 * progress) - 12.0 * last_chance;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band it falls into
    let q = (bin_capacity / 4) as f64; // quarter-class granularity
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Reward perfect / near-perfect fits (post_residual in small residue classes)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Integer-division thresholds: penalize dead space that no future item can fill.
    // Items are 1..=100; residual below ~10 is nearly dead -> big penalty.
    if post_residual < 10 {
        score += 25.0 * (10 - post_residual) as f64;
    }

    // Modulo coupling: post_residual % 10 measures alignment with common item sizes
    let m = post_residual % 10;
    if m == 0 {
        score -= 8.0; // residual divisible by 10 is reusable
    } else if m >= 7 {
        score += 6.0; // awkward 7..9 sliver
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            let nxt_post = post_residual - next_item_size;
            if nxt_post <= 10 {
                score -= 15.0;
            }
            score += nxt_post as f64 * 0.15;
        } else {
            // next item cannot use this residual: penalize large residuals less
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Class-band reward for landing residual in a "harmonic" band (multiples of quarter capacity)
    let band = (post_frac * 4.0).round() / 4.0;
    if (post_frac - band).abs() < 0.02 && post_residual > 0 {
        score -= 5.0;
    }

    // Last-chance bonus: only one fitting bin -> prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive if the item
    // is large relative to typical residuals and current bins are crowded.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // penalize new bins, but less when item is huge or many bins are open
        score += 45.0
            - 0.25 * item_size as f64
            - 1.5 * open_bins_count as f64
            - 10.0 * progress;
        if next_item_size > item_size && next_item_size > bin_capacity / 2 {
            score -= 15.0; // big follower: fresh bin may help
        }
    }

    // Slight preference for tighter bins overall
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..=9) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 3.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual can still fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 8.0; // dead space for the known next item
        }
    }

    // Open-bins pressure: with many open bins, prefer filling existing ones.
    let pressure = (open_bins_count as f64).ln() * 6.0;
    score -= pressure;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly.
    if bin_residual == bin_capacity {
        score = 55.0 + mean_residual * 0.4 + pressure;
        if fitting_bins_count == 1 {
            score += 30.0; // don't open new bin when a last-chance bin exists
        }
        if post_residual < 10 {
            score += 20.0;
        }
    }

    // Late-stream consolidation: tighten up as the stream ends.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits the next item -> strong reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;

        if post == next {
            score -= 25.0;
        } else if post > next {
            // Next item fits, but reward tighter matches more (less leftover after two items).
            let gap = post - next;
            if gap <= 10.0 {
                score -= 12.0 - 0.6 * gap;
            } else {
                // Large leftover after both items: penalize proportionally.
                score += 0.15 * gap;
            }
        } else {
            // Next item won't fit here; penalize based on how badly the match fails.
            let miss = next - post;
            score += 0.5 * miss.min(50.0);
        }

        // Relative-to-mean coupling: bins tighter than the mean are better targets.
        let tightness = mean_residual - post;
        score += 0.08 * tightness;
    } else {
        // Last item: simply prefer minimal post_residual, tiny bonus for exact fit.
        if post_residual == 0 {
            score -= 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    }

    // Early in the stream, keep bins open and flexible; late, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;

    // Discourage wasting a nearly-empty (large residual) bin on a small item.
    if (bin_residual as f64) > mean_residual + 20.0 && item_size < 30 {
        score += 5.0;
    }

    // New empty bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic decay of value as post_residual shrinks.
    let frac = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - frac) * (1.0 - frac) * 20.0;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0;
        // Extra reward for a snug two-item chain.
        let chain_slack = post_residual - next_item_size;
        score -= (chain_slack as f64).min(10.0) * 0.8;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Penalize creating dead space the next item cannot use.
        score += (next_item_size as f64 - post_residual as f64) * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Penalize bins that are already fragmented relative to the mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += dev.abs() * 0.3;

    // Early in the stream, be more willing to fill existing bins; later, be pickier.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 8.0;

    // New-bin candidate: make it unattractive unless post_residual (full capacity)
    // offers a clearly better long-term platform than a poor fit.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 0.5;
        // Late in the stream, opening fresh bins is less valuable.
        score += progress * 20.0;
        // But if the current item is small and bins are crowded, a fresh bin
        // with lots of room for the lookahead item is reasonable.
        if next_item_size > 0 && item_size < 40 {
            score -= 12.0;
        }
    }

    // Slight preference for larger items into emptier bins.
    score += (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    let mut score = pr;

    // Reward tight fits: quadratic coupling between item size and fill fraction
    let fill = it / cap;
    score -= 30.0 * fill * (1.0 - pr / cap);

    // Non-linear dead-space penalty: small residuals relative to capacity are risky
    let dead = pr / cap;
    score += 12.0 * dead * dead * (1.0 - progress);

    // Lookahead: penalize if next item cannot fit in post-residual, reward if it can
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 8.0 * (1.0 - progress) * (nxt - pr) / cap;
        } else {
            score -= 5.0 * (pr - nxt) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (1.0 - progress);
    }

    // More open bins -> prefer consolidating into existing bins
    score += 0.5 * open_bins_count as f64 * dead;

    // Deviation from mean residual: prefer bins that reduce residual variance
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: make it unattractive unless residual is large and fits are scarce
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 2.0 * fitting_bins_count as f64;
        if next_item_size > 0 && next_item_size as f64 > cap * 0.7 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space.
    // Residuals divisible by 25 (quarter-capacity classes) are prime slots.
    let pr = post_residual;
    if pr == 0 {
        score -= 30.0; // perfect fit, best possible outcome
    } else {
        let quarter = (pr % 25 == 0) as i32 as f64;
        let half = (pr % 50 == 0) as i32 as f64;
        score -= 12.0 * half + 6.0 * quarter;

        // Penalize dead space in the awkward band 1..=9 (unusable for items >=10)
        if pr < 10 {
            score += 25.0;
        }
        // Integer-division threshold: leftover that still admits a mid-size item is good
        if pr >= 50 { score -= 8.0; }
        else if pr >= 25 { score -= 3.0; }
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0;
        } else if next_item_size <= pr {
            let new_post = pr - next_item_size;
            // penalize if the chain creates tiny dead space
            if new_post < 10 && new_post > 0 {
                score += 6.0;
            } else {
                score -= 5.0;
            }
        } else {
            // next item won't fit here; mild penalty scaled by overflow gap
            score += ((next_item_size - pr) as f64).min(15.0) * 0.3;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid forcing a bad split.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a bin is attractive when existing
    // residuals are fragmented (high mean residual spread) or many bins open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Prefer new bin when current bin would leave a mid-range awkward residual
        // and the stream is still early/mid (many items left to fill it).
        let awkward = if pr >= 10 && pr < 25 { 1.0 } else { 0.0 };
        score = 45.0 - 20.0 * awkward * (1.0 - progress) - fragmentation.min(20.0) * 0.5
                - (open_bins_count as f64).min(10.0) * 0.5;
        // If the item is large relative to capacity, reusing an open bin is safer
        if item_size > 60 {
            score += 15.0;
        }
        // Late in the stream, prefer consolidation into open bins
        if progress > 0.85 {
            score += 20.0;
        }
    }

    // Mild preference for tighter bins overall (best-fit flavor) via mean residual coupling
    score -= (cap - mean_residual).max(0.0) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps that are too small to be useful later
    // are heavily penalized. Define "unusable" threshold relative to the
    // smallest plausible item (1..100 range => use 10 as conservative floor,
    // but adapt via next_item_size lookahead).
    let min_useful = if next_item_size > 0 { (next_item_size as f64 * 0.5).max(10.0) } else { 10.0 };
    if post_residual > 0 && (post_residual as f64) < min_useful {
        // Dead space: penalize proportionally to how close the gap is to zero.
        let dead = (min_useful - post_residual as f64) / min_useful;
        score += 25.0 * dead;
    }

    // Reward tight fits (small positive post_residual that stays usable).
    if post_residual > 0 && post_residual <= 15 {
        score -= 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling
    // existing bins when the count is high, but allow opening a new bin when
    // the current bin would leave a large awkward residual.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 3.0 * pressure;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless dead space penalty dominates).
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin has post_residual == capacity - item.
    // Only make it attractive when placing here avoids creating dead space in
    // an existing bin; otherwise penalize slightly to prefer consolidation.
    if bin_residual == bin_capacity {
        // New bin: score is just capacity - item_size (large residual).
        // Add mild penalty so tight fits in open bins win, but subtract a bit
        // when open bins are few (early stream, expansion is fine).
        score -= (2.0 * (total_items as f64 - step_index as f64) / total_items.max(1) as f64).min(2.0);
    }

    // Lookahead coupling: if the next item would fit exactly in the post
    // residual, reward this placement (chaining).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect or near-perfect fit
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    }

    // 2-step lookahead: reward when next item fits into post_residual
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 180.0; // perfect chain placement
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 10.0 {
                score -= 100.0 - slack * 4.0;
            } else {
                // penalize leaving a gap next item can't chain into
                score += slack * 0.35;
            }
        } else {
            // next item won't fit here at all: mild penalty for tight fit
            score += 15.0;
        }
    }

    // Tightness of the current fit relative to bin capacity
    let tightness = item_size as f64 / bin_residual as f64;
    score -= tightness * 40.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Relative residual vs mean: prefer filling bins below-average residual (fuller bins)
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Penalize creating very small unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // New-bin candidate: only open when current bins are quite full
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        if avg_fill > 0.55 {
            score += 35.0; // keep using open bins
        } else {
            score -= 10.0; // open a fresh bin when open bins are fragmented
        }
    }

    // Early stream: slightly prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.0 - progress) * 0.4;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (dead-space penalty, quadratic in waste).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 25.0 * fit_ratio * fit_ratio;

    // Lookahead: if the next item exactly fills the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // reward proportionally good leftover for next item
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 12.0 * next_fit;
        } else {
            // post residual too small for next item: penalize dead space
            score += 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        // penalize opening new bins when many open bins exist that fit
        score += 20.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count <= 1 {
            score -= 45.0; // nothing fits well elsewhere -> open new bin
        }
        if item_size >= 50 {
            score -= 10.0; // big items like fresh bins
        }
    }

    // Global state coupling: when mean residual is high, prefer consuming it.
    if bin_residual as f64 > mean_residual {
        score -= 4.0;
    } else {
        score += 2.0;
    }

    // Time horizon: early in stream, be conservative with new bins; late, tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small exact-fill jackpot.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let residual_norm = post / cap;

    // Base: prefer tight fits (small post_residual), with smooth non-linear shaping.
    let mut score = post * (1.0 + 0.8 * residual_norm * residual_norm);

    // Dead-space penalty: residuals too small to be useful later (below min item size).
    let dead = (1.0 - post / 10.0).max(0.0);
    score += 6.0 * dead * dead;

    // Stream-progress coupling: tighten bin preference as stream advances.
    score *= 1.0 + 0.5 * progress * residual_norm;

    // Last-chance bonus: strongly reward using a bin when few fit.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // Lookahead: penalize leaving residual that barely misses next item;
    // reward residuals that can fit next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= 4.0 * (nxt / cap);
        } else {
            let gap = (nxt - post) / cap;
            score += 5.0 * gap * gap * (1.0 + progress);
        }
    }

    // New-bin candidate logic: opening a bin is attractive when open bins are
    // nearly full on average or the current fit is poor; discouraged early.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let mean_frac = mean_residual / cap;
        let avg_fill = 1.0 - mean_frac;
        let fit_quality = 1.0 - residual_norm; // for new bin this is item fraction
        let openness = (open_bins_count as f64).ln().max(0.0);
        let new_bin_bias = 8.0
            - 6.0 * avg_fill * avg_fill
            - 4.0 * progress
            + 2.0 * openness
            - 3.0 * fit_quality;
        score += new_bin_bias;
    } else {
        // Slight preference to consolidate into fewer bins.
        score += 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes on capacity
    let pr = post_residual;
    let class = pr % 10;
    // Penalize residuals that are "dead" (too small for typical items)
    if pr > 0 && pr < 10 {
        score += 40.0;
    }
    // Reward residuals in classes likely reusable (multiples of 10, 20, 25, 50)
    if class == 0 {
        score -= 12.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 50 == 0 && pr > 0 {
        score -= 6.0;
    }

    // Integer-division thresholds on post_residual
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if pr >= half {
        score -= 10.0;
    } else if pr >= quarter {
        score -= 4.0;
    } else if pr > 0 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size <= pr {
            score -= 8.0;
            // harmonic class match between next item and residual
            if next_item_size % 10 == class {
                score -= 6.0;
            }
        } else {
            score += 10.0;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize slightly unless open bins are fragmented
    if bin_residual == bin_capacity {
        score += 15.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        // open new bin early when stream is young and mean residual is small
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.3 && mean_residual < cap * 0.2 {
            score -= 5.0;
        }
    }

    // Fragmentation pressure: prefer bins below mean residual (tighter fills)
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space that almost nothing can use
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Reward bins whose residual closely matches the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.15;

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 20.0;
        } else {
            score -= 8.0 * (1.0 - gap as f64 / post_residual as f64);
        }
    }
    // Penalize placements that leave a gap the next item cannot use.
    if next_item_size > post_residual as u32 && post_residual > 0 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins below mean residual (fill emptier-trending bins less).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate: make it attractive only when open-bin fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 * 0.9 + open_bins_count as f64 * 2.0;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
        // If only one bin fits and it's tight, opening new bin is less attractive.
        if fitting_bins_count == 1 {
            score += 25.0;
        }
        // If next item is large and residuals are small, a fresh bin is valuable.
        if next_item_size > 0 && mean_residual < next_item_size as f64 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: item + next item exactly fill the bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Reward if next item fits into post_residual (good lookahead), scaled by how snugly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.35;
    } else if next_item_size > 0 {
        // Next item does not fit: penalize dead space in the leftover region.
        let dead = (post_residual as f64).min(next_item_size as f64);
        score += dead * 0.25;
    }

    // Penalize tiny unusable leftovers that don't match next item (likely dead space).
    if post_residual < 10 && post_residual != next_item_size {
        score += 15.0;
    }

    // Prefer tighter fits relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening a new bin unless nothing decent exists among open bins.
    if bin_residual == bin_capacity {
        let open_fits_well = next_item_size > 0 && post_residual == next_item_size;
        let base_penalty = if open_fits_well { 0.0 } else { 20.0 };
        score += base_penalty + (open_bins_count as f64 * 0.5);
        // Late in the stream, avoid opening new bins even more.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness;

    // Penalize large dead space if the next item cannot use it.
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // Dead space that even the lookahead item can't use.
            score += 0.35 * post_residual as f64;
        } else {
            // Reward bins where the next item also fits (chaining).
            let chained_waste = post_residual - next_item_size;
            score -= 0.5 * (chained_waste as f64).min(20.0);
        }
    } else {
        // Last item: minimize waste directly.
        score += 0.6 * post_residual as f64;
    }

    // Last-chance bonus: only one fitting bin; strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0 + 0.1 * item_size as f64;
        // But if this placement leaves unusable space for the next item, soften.
        if next_item_size > 0 && next_item_size > post_residual {
            score += 6.0;
        }
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 25.0 + 2.0 * open_bins_count as f64;
        // Early in the stream, opening bins is cheaper (build a portfolio).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
        // If many open bins can fit, discourage new bin.
        score += 3.0 * fitting_bins_count as f64;
        // If mean residual is large, open bins have room; discourage new bin.
        score += 0.15 * mean_residual;
        // If the next item is huge, a fresh bin is more valuable.
        score -= 0.2 * next_item_size as f64;
    } else {
        // Mild penalty for using a bin whose residual is far from mean (imbalance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Prefer bins with smaller residual overall (best-fit bias), scaled by progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.1 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, with non-linear sharpening.
    let mut score = pr as f64;

    // Smooth non-linear coupling: low post-residual is rewarded more as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 40.0 * tightness * tightness * (0.5 + progress);

    // Polynomial penalty on residual, amplified late in the stream (dead space costs more later).
    let quad = norm_pr * norm_pr;
    let quart = quad * quad;
    score += 30.0 * quad * (0.4 + 0.6 * progress) + 50.0 * quart * progress;

    // Lookahead: reward leaving room for the next item, smoothly via residual match.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n).abs() / cap;
        score -= 20.0 * (1.0 - gap) * (1.0 - gap) * (1.0 - progress);
        // Penalize post-residual just barely below next item size (unusable sliver).
        if pr < n && pr > 0.0 {
            score += 15.0 * (n - pr) / cap * (1.0 + progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // Mild penalty for spreading across many bins; scale with open bin count.
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: make it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        let fit_quality = (mean_residual - item_size as f64).abs();
        score = cap - 10.0 + fit_quality + 20.0 * progress;
        if fitting_bins_count == 1 {
            score += 60.0; // keep the last-chance open bin preferred
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: leftovers divisible by common item
    // sizes (10/20/25/50) are "usable" and get a strong reward; odd fragments
    // are penalized proportionally to how awkward they are.
    let mut class_bonus = 0.0f64;
    for &m in &[50u32, 25, 20, 10, 5] {
        if post_residual % m == 0 && post_residual > 0 {
            class_bonus = m as f64 * 2.0;
            break;
        }
    }
    score -= class_bonus;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space that no future item (min size 1, but realistically
    // >= 10 in classic streams) can ever use.
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post_residual can exactly host the
    // next item (chain packing), reward mildly if it can merely host it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // leftover below next item's size: penalize by the unusable gap
            score += (next_item_size - post_residual) as f64 * 0.4;
        }
    }

    // Last-chance logic: if this is the only fitting bin, prefer using it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline slightly above a good fit, but
    // attractive when open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let base = bin_capacity as f64 * 0.55;
        score = score.max(base) - (mean_residual / bin_capacity as f64) * 20.0;
        // late in the stream, avoid spawning bins unnecessarily
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 15.0;
    }

    // Mildly favor tighter bins (small residual before placement) among ties.
    score += (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual gap is "dead" if it is smaller than the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0; // unusable sliver
    }
    // Dead space relative to next item: gap that cannot host the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 30.0;
    }
    // Near-perfect fit reward (gap small but still usable by tiny items)
    else if post_residual <= 5 {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, prefer tighter packing
    let pressure = open_bins_count as f64;
    score += pressure * 0.6 * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: penalize bins deviating from mean residual
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev.abs();

    // Early stream: be more permissive with new bins; late stream: pack tightly
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    if bin_residual == bin_capacity {
        let mut nb = 20.0 + progress * 15.0;
        // If item would fit nicely in an existing bin, opening new is worse
        if next_item_size > 0 && post_residual < next_item_size {
            nb -= 10.0; // new bin keeps space for next item
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

