        } else if next_item_size > 0 {
            // penalize dead space the next item cannot use
            let dead = post_residual as f64;
            score += 0.3 * dead;
        }

        // reward small post_residual relative to mean residual (tight fit)
        let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        score -= 0.4 * (mean_r - post_residual as f64);

        // last-chance bin: strongly favor using it before opening a new bin
        if fitting_bins_count == 1 && bin_residual >= item_size {
            score -= 120.0;
        }

        // penalize very small unusable leftovers (< 10 cannot hold any item)
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // new-bin candidate: prefer it only when open bins would leave large waste
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_capacity - item_size) as f64;
        score = 150.0 + 0.5 * waste_if_open;
        if next_item_size > 0 && waste_if_open as u32 >= next_item_size {
            score -= 40.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post_residual.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Penalize unusable dead space: residual too small for any plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Global pressure: when many bins are open relative to progress, discourage new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * pressure;
    } else {
        score -= 3.0 * pressure.ln().max(0.0);
    }

    // Prefer bins with below-average residual (fill emptier bins first keeps spread tight).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Mild early-stream exploration: tolerate imperfect fits early.
    score *= 1.0 - 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let norm_post = post / cap;
    let p = progress;
    let coupling = norm_post * norm_post * (0.5 + 1.5 * p) + norm_post * (1.0 - p) * (1.0 - p);
    score += 25.0 * coupling;

    // Penalize waste when few bins can fit the item (last-chance bonus).
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * p;
    }

    // Discourage tight fits that leave dead space unusable for the lookahead item.
    if next_item_size > 0 && (next_item_size as f64) > post {
        score += 6.0 + 10.0 * (next_item_size as f64 - post) / cap;
    } else if next_item_size > 0 {
        score -= 4.0 * (1.0 - (post - next_item_size as f64) / cap);
    }

    // Mild preference for bins deviating from mean residual (balance-aware).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Slight bias toward opening new bins early, consolidating late.
    score += 2.0 * p * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: residuals divisible by small classes
    // are more reusable by typical item sizes.
    let pr = post_residual;
    if pr > 0 {
        // Class A: post_residual divisible by 10 (common item granularity)
        if pr % 10 == 0 {
            score -= 8.0;
        }
        // Class B: divisible by 5
        else if pr % 5 == 0 {
            score -= 4.0;
        }
        // Class C: small odd dead space (hard to reuse) — penalize
        if pr < 10 {
            score += 25.0;
        }
    }

    // Integer-division thresholds: residual in [next_item_size, next_item_size+9)
    // can host the next item exactly-ish — reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack <= 5 {
            score -= 15.0;
        } else {
            score -= 3.0;
        }
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space relative to lookahead item.
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly so we prefer good fits in open bins,
    // but keep it attractive when open-bin residuals are large/fragmented.
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1;
    }

    // Prefer fuller bins (small residual before placement).
    score += (bin_residual as f64) * 0.05;

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable for
    // any realistic item (min size 1, but tiny gaps are waste) — hard penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Gaps just above small-item range are also near-dead space.
    if post_residual >= 10 && post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * tightness;

    // Perfect fit: zero waste is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0 - slack; // near-perfect chain fit
        } else {
            score -= 10.0;
        }
    }
    // Penalize if next item would NOT fit here (bin likely becomes dead space).
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 12.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; mildly penalize new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln().max(0.0) * (1.0 + progress);
    score += pressure * 2.0;

    // Mean-residual coupling: if this bin is above average fullness
    // (low residual vs mean), it's a good consolidation target.
    if (bin_residual as f64) < mean_residual {
        score -= 8.0;
    } else {
        score += 4.0;
    }

    // New-bin candidate: only attractive when no good fit exists;
    // an empty bin starts with full flexibility, so give it a moderate
    // baseline that the bonuses above can override.
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
        // But if the item is large, a fresh bin avoids fragmentation.
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

