    score += (post_residual as f64 / bin_capacity as f64).powi(2) * 40.0;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    }

    // 2-step lookahead: reward if next item exactly fits post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0; // chain fit: excellent
        } else if next_item_size <= post_residual {
            // next item fits but leaves further residue: mild bonus proportional to tightness
            score -= 15.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item will NOT fit in this residual: penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.35;
        }
    }

    // Penalize bins with residual far below mean (they are poor reuse candidates)
    score += (mean_residual - post_residual as f64).abs() * 0.15;

    // Last-chance bin: strong reward to use it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when fits are poor or stream is early
    if bin_residual == bin_capacity {
        let bad_fit = if next_item_size > 0 && next_item_size > post_residual { 1.0 } else { 0.0 };
        score += 25.0; // default penalty: prefer existing bins
        score -= bad_fit * 20.0; // if item doesn't chain anywhere, opening fresh is OK
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0; // early stream: new bins cheaper
    }

    // Prefer filling bins when many are open (avoid bin proliferation)
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

