    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize large dead space if the item barely fits (waste risk).
    if post_residual < item_size as f64 * 0.15 {
        score += 6.0;
    }

    // Lookahead: if the next item can use the post-residual, reward this bin.
    if next_item_size > 0 {
