    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 3 {
        score += 1.5; // plenty of alternatives, no urgency
    }

    // Global residual pressure: if mean residual is small, conserve space by
    // preferring bins whose post-residual stays usable.
    let mr = mean_residual;
    if mr < 25.0 {
        score += (25.0 - mr) * 0.08;
    }

    // Prefer placing into already-open bins over opening new ones,
    // more strongly early in the stream (many items still to come).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_bias = 10.0 * (1.0 - progress);
    if bin_residual == bin_capacity {
        score += new_bin_bias;
    } else {
        score -= 2.0;
    }

    // Mild preference for bins with residual close to item size (best-fit flavor).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
