    }

    // Slight penalty for spreading across many bins vs mean residual alignment.
    score += 0.05 * (pr - mean_residual).abs();

    // Mild pressure to consolidate into fewer bins.
    score += 0.02 * open_bins_count as f64 * coupling;

    // New-bin candidate: penalize opening a fresh bin unless item is large
    // relative to residual alternatives (empty bin has pr == cap).
    if bin_residual == bin_capacity {
        score += 15.0 - 10.0 * (it / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: quarter classes of capacity.
    let q = post_residual / (bin_capacity / 4); // 0..=4 class of dead space
    let quarter = (bin_capacity / 4) as f64;

    // Reward small post_residual non-linearly (tight fits are good).
    score -= (cap - post_residual as f64) * 0.35;

    // Penalize leaving awkward dead-space classes: residuals in (0, 10)
    // are nearly unusable for items >= 1 but wasteful; residuals that are
    // exact divisors of common item sizes are valuable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny dead sliver
    }
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0; // class-aligned residual, easy to refill
    }
    if post_residual % 5 == 0 && post_residual > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            score -= 10.0 - (npr as f64) * 0.2;
            if npr % 10 == 0 { score -= 5.0; }
        } else {
            score += 6.0; // next item can't use this bin's leftover
        }
    } else {
        // Last item: just minimize waste.
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin
    // offers a decent harmonic fit.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with tight fits win.
        score = cap * 0.9;
        if fitting_bins_count == 0 {
            score -= cap; // must open a new bin
        } else if next_item_size > 0 && post_residual == 0 {
            score -= cap;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        return score;
    }

    // Quarter-class penalty: residuals just above a quarter boundary are
    // worse than just below (wasted fraction of a usable class).
    let frac = (post_residual as f64) % quarter;
    if frac > 0.0 && frac < quarter * 0.25 {
        score += 4.0;
    }

    // Prefer bins whose residual is below mean (filling the emptiest-ish but tight bins).
    score += (post_residual as f64 - mean_residual) * 0.15;

    // Mild pressure to keep number of open bins low.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable
    // for typical item sizes; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - (post_residual as f64) * 5.0;
    }
    // Zero residual is a perfect fit — reward strongly.
    if post_residual == 0 {
        score -= 120.0;
    }
    // Exact fit for the lookahead item too (residual equals next size).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 45.0;
    }
    // Penalize leaving a gap that cannot fit the next item (dead space for lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0;
    }
    // Reward leaving a gap that exactly accommodates the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: prefer consolidating into existing bins
    // when many bins are already open.
    if bin_residual < bin_capacity {
        score -= (open_bins_count as f64) * 2.0;
    } else {
        // New-bin candidate: penalize opening a new bin, more so early
        // in the stream and when open bins have plenty of room.
        score += 30.0 + 40.0 * (1.0 - step_index as f64 / total_items.max(1) as f64)
            + (mean_residual / bin_capacity as f64) * 25.0;
    }

    // Mild preference for tighter fits overall.
    score += (post_residual as f64) / (bin_capacity as f64) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

