            score += 6.0;
        }
    } else {
        // Last item: prefer minimizing waste completely.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }

    // Many open bins: prefer consolidating into fuller bins.
    let avg_fill = 1.0 - mean_residual / (bin_capacity as f64 * open_bins_count.max(1) as f64).max(1.0);
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * avg_fill * (0.5 + progress);

    // New-bin candidate handling: only attractive late or when current bin fit is bad.
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > 60.0; // item tiny relative to bin
        if progress > 0.6 || bad_fit {
            score -= 8.0 + 20.0 * progress;
        } else {
            score += 30.0; // early on, prefer filling open bins
        }
    }

    // Slight preference for bins whose residual is close to mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let mut score = pr;

    // Reward tight fits: quadratic coupling of fill ratio with stream progress
    let fill = (bin_residual - post_residual) as f64 / cap;
    score -= 40.0 * fill * fill * (0.5 + progress);

    // Penalize large dead space non-linearly, amplified late in the stream
    let dead = pr / cap;
    score += 60.0 * dead * dead * (1.0 + progress);

    // Reward last-chance bins (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + progress);
    }
    // Mild penalty when many bins compete (prefer consolidation)
    if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Lookahead coupling: reward leaving room close to next item size
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        let match_bonus = (1.0 - gap / cap).max(0.0);
        score -= 12.0 * match_bonus * match_bonus * (0.5 + progress);
        // Penalize residuals too small for the next item
        if pr < nxt {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Mean residual coupling: prefer bins near the mean (balanced packing)
    let dev = (pr - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Slight preference for existing bins vs new bin late in stream
    if bin_residual == bin_capacity {
        score += 10.0 * (0.3 + progress);
    } else {
        score -= 2.0 * (1.0 - progress);
    }

    // Smooth sigmoid gating on item scarcity near stream end
    let end_gate = 1.0 / (1.0 + (-(progress - 0.8) * 20.0).exp());
    score += 5.0 * end_gate * dead;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post residual: modulo classes mod 10 and mod 25
    let m10 = post_residual % 10;
    let m25 = post_residual % 25;
    // Penalize residuals in awkward harmonic classes (small nonzero remainders = dead space)
    if post_residual > 0 {
        if m10 >= 1 && m10 <= 4 {
            score += 6.0 - m10 as f64; // tiny unusable slivers
        }
        if m25 == 0 {
            score -= 4.0; // perfectly divisible residual is reusable
        }
    }

    // Capacity-fraction thresholds on post_residual
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    if (post_residual as f64) <= quarter {
        score += 8.0; // near-dead bin
    } else if (post_residual as f64) <= half {
        score -= 2.0; // sweet zone: still half-usable
    } else {
        score -= 5.0; // roomy bin, prefer filling it
    }

    // Integer-division harmony: item and next item fill a clean fraction together
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 12.0; // perfect lookahead fit
        } else if post_residual >= next_item_size {
            let combo = post_residual - next_item_size;
            if combo % 10 == 0 {
                score -= 6.0;
            }
            if combo <= 5 && combo > 0 {
                score += 5.0; // lookahead creates sliver
            }
        } else {
            score += 4.0; // next item won't fit here either
        }
    }

    // Last-chance bonus: only this bin fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: neutralize raw residual, add mild exploration cost that
    // shrinks as the stream progresses; prefer new bins only when open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap * 0.5 + open_bins_count as f64 * 3.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size > item_size && next_item_size <= bin_capacity {
            score -= 3.0; // new bin can absorb the bigger lookahead item
        }
    }

    // Mild tie-break toward bins below mean residual (balance load)
    if (post_residual as f64) < mean_residual {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to be useful
    // later are heavily penalized (non-linearly).
    if post_residual > 0 {
        // Dead space threshold: gaps below ~20 are rarely reusable.
        let dead_threshold = 20.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
