    // Reward bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 25.0;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded
    // or the fit would leave bad dead space.
    if bin_residual == bin_capacity {
        // Base penalty so new bins are not opened frivolously.
        score += 55.0 + (open_bins_count as f64 * 2.0);
        // But if the item would leave a very tight residual, a fresh bin
        // becomes relatively better.
        let fresh_post = bin_capacity - item_size;
        if fresh_post <= 5 {
            score -= 60.0;
