        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 20.0;
    }

    // Open-bin pressure: many open bins -> favor filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Lookahead: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 12.0;
    }

    // Mean residual coupling: bins far below mean residual are "waste" bins;
    // prefer placing into them to balance residuals.
    if (bin_residual as f64) > mean_residual {
        score -= (bin_residual as f64 - mean_residual) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

