    }

    // Tight fit reward for the current item.
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 20.0 * tightness;

    // Penalize bins far below the mean residual (wasteful choice) unless it's a last-chance bin.
    score += 0.3 * (mean_residual - post_residual as f64).abs();

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when open bins would create big dead space.
    if bin_residual == bin_capacity {
