        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0;
        }
    }

    // Early in the stream, allow slightly more openness to new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 15.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

