    // New-bin candidate: penalize opening a new bin unless current fits are bad
    if bin_residual == bin_capacity {
        score += 10.0;
        // allow new bin early in stream or when open bins are congested
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score -= 6.0;
        }
        if open_bins_count > 12 {
            score -= 4.0;
        }
        // if mean residual is small (bins nearly full), new bin is fine
        if mean_residual < 15.0 {
            score -= 8.0;
        }
    }

    // Mild preference for tighter bins overall
    score += (bin_residual as f64 - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable dead space: small gaps that likely can't host future items.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward perfect / near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Reward bins whose residual is "consumed" proportionally well.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bins pressure: with many open bins, favor consolidating into existing bins
    // (penalize the new-bin candidate).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.6 + 0.8 * progress);
    if bin_residual == bin_capacity {
        score += pressure * 2.0;
    } else {
        score -= pressure * 0.15;
    }

    // Lookahead: if the next item fits the post-residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If post-residual is just barely too small for the next item, it's dead space.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Mild alignment with mean residual: prefer bins whose resulting residual
    // is close to the mean (keeps a balanced portfolio of gaps).
    score += 0.1 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Post residual can still hold the next item: good lookahead fit.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack.min(25.0) * 0.4;
    }

    // Penalize dead space: post residual too small for next item (and too small
    // for the minimum plausible item). Waste scales quadratically with tightness.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post_residual as f64;
        score += (next_item_size - post_residual) as f64 * 0.9 + dead * dead * 0.02;
    }

    // Relative-to-mean coupling: prefer bins tighter than the mean residual.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Discourage opening a new bin while good open bins exist, unless residual
    // would be large and unusable (favor consolidation of tight bins).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64;
        score += 30.0 + pressure * 2.0 - progress * 10.0;
        // A new bin is attractive when the current bin would leave a tiny unusable gap.
        if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
            score -= 45.0;
        }
    }

    // Mild reward for filling bins very full (post residual near zero is fine
    // only when nothing small follows); keep baseline ordering by post_residual.
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residuals too small to plausibly host future items.
    if post_residual < 10 {
        score -= 8.0; // nearly full bin is a great outcome
    } else if post_residual < 30 {
        score += 4.0; // awkward mid-range dead space
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual > 50 {
            score += 10.0; // wasteful placement in last bin, soften
        }
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0; // chaining future item into this bin is valuable
        } else if next_item_size <= bin_residual {
            // next item would have fit now but not after this placement
            score += 6.0;
        }
        // If post_residual exactly complements next item, big bonus
        if post_residual == next_item_size {
            score -= 14.0;
        }
    }

    // Prefer fuller bins among many open bins (best-fit flavor).
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 6.0 * fullness;

    // Global state coupling: many open bins with high mean residual -> encourage
    // consolidation into existing bins rather than opening new ones.
    if bin_residual != bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score -= 5.0 * pressure;
    }

    // New-bin candidate handling: an empty bin is only attractive when the
    // item is huge relative to typical residuals or no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let bad_fit = post_residual as f64 / bin_capacity as f64;
        // Opening a new bin costs ~1 bin; do it only for very poor fits elsewhere
        // or when the stream is young and structure is still forming.
        score += 18.0 - 10.0 * bad_fit - 6.0 * (1.0 - progress);
        if item_size >= 60 {
            score -= 8.0; // large items deserve a fresh bin
        }
    }

    // Mild time-horizon modulation: late in the stream, be greedy (minimize
    // residual now); early, keep flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: waste after placement, non-linearly amplified (dead space is superlinear bad).
    let mut score = post + 0.008 * post * post / cap;

    // Tight-fit reward: strong cubic discount as post_residual approaches 0.
    let tight = 1.0 - post / cap;
    score -= 30.0 * tight * tight * tight;

    // Lookahead coupling: reward if the next item fits exactly into post_residual,
    // penalize if post_residual is awkward relative to the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if post >= nxt {
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            score += 0.03 * gap;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Stream-progress coupling: later in the stream, consolidate more aggressively
    // (penalize spreading into many bins); smooth polynomial interaction with progress.
    let spread = (mean_residual - post).abs();
    score += progress * 0.05 * spread;

    // New-bin candidate: make empty bins moderately attractive only when open bins
    // are congested (few fitting bins) or mean residual is low; otherwise penalize.
    if bin_residual == bin_capacity {
        let congestion = 1.0 / (fitting_bins_count as f64 + 1.0);
        score = cap * 0.5 + 20.0 * (1.0 - progress) - 30.0 * congestion - 0.1 * mean_residual;
    }

    // Mild penalty for opening into a bin that is already well-filled relative to mean.
    score += 0.02 * (mean_residual - post).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: residues divisible by small moduli are
    // more reusable by typical item sizes, so penalize them less.
    let pr = post_residual;
    let gcd_like = |x: u32| -> f64 {
        let mut h = 0.0;
        for m in [2u32, 4, 5, 10, 20, 25, 50] {
            if x % m == 0 {
                h += 1.0 / m as f64;
            }
        }
        h
    };
    // Reward leftovers that sit on "harmonic" grid points (highly divisible).
    score -= 12.0 * gcd_like(pr);

    // Integer-division thresholds: leftover in [0..=10] is near-perfect fit.
    let class = pr / 10; // 0..10 harmonic class of the leftover
    score -= match class {
        0 => 20.0,               // 0..=10 dead space: excellent
        1 => 8.0,                // 11..=20: still usable by small items
        2 => 2.0,                // 21..=30: mid-range
        3 => 0.0,
        4 => -2.0,               // 41..=50: half-empty bin, very reusable
        5 => -1.0,
        _ => 1.0,                // large leftover: mild penalty vs opening new bin
    };

    // Penalize leftovers that no plausible next item (10..80) would fit well:
    // leftover < 10 is a true dead zone unless it is zero.
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly reward this bin (perfect chaining).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / bin_capacity as f64);
        }
        // If next item is bigger than leftover but this is the only fitting bin,
        // accept anyway (last-chance bonus).
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 18.0;
        }
    }

    // Last-chance bin before opening a new bin: favor using it.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // New-bin candidate handling: fresh empty bin gets a mild baseline so we
    // only open it when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 35.0 + 0.05 * open_bins_count as f64;
    } else {
        // Prefer fuller bins: compare residual to mean residual of open bins.
        score += 0.25 * (mean_residual - bin_residual as f64);
    }

    // Late in the stream, consolidate: fewer bins preferred, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * (bin_residual as f64 - mean_residual);

    // Waste fraction coupling: penalize proportional waste of this placement.
    score += 10.0 * (post_residual as f64 / bin_capacity as f64).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps in (0, 10) are unusable for any item
    // (min item size 1 per interface note, but tiny gaps rarely fit future items).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fill: strong reward
        score -= 100.0;
    }

    // Reward tight fits (post_residual small relative to item size)
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score += tightness * 20.0;

    // Last chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: penalize spreading across many open bins
    score += open_bins_count as f64 * 1.5;

    // Prefer bins with residual below the mean (filling fuller bins first)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        }
    }

    // New-bin candidate: mildly discourage opening a new bin unless residual
    // pressure is low or item is huge; scale with stream progression.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 - progress * 10.0;
        if item_size >= 80 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strong bonus for near-exact fill.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            score -= 150.0 - (post_residual - next_item_size) as f64;
        } else {
            // wasted lookahead space penalty, scaled by how badly it misses
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative-to-mean coupling: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // Penalize opening a new bin when decent fits exist: make empty-bin candidate
    // less attractive unless residuals are all small.
    if bin_residual == bin_capacity {
        score += 50.0 + mean_residual * 0.2;
        // but if the current item is large relative to capacity, new bin is fine
        if item_size > bin_capacity * 3 / 4 {
            score -= 100.0;
        }
    }

    // Late in stream: be more greedy about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Lookahead: reward bins whose leftover can host the next item (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 14.0;
        // Extra reward for near-perfect two-item packing.
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space: leftover too small for any plausible future item.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: it's only attractive when existing bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin; grows with open bins (fragmentation cost).
        score += 16.0 + 1.5 * open_bins_count as f64;
        // Early in the stream, keep bins consolidated; later, allow spreading.
        score += 10.0 * (1.0 - progress);
        // If the new bin would leave a large, reusable residual (small item), soften penalty.
        score -= 0.15 * post_residual as f64;
        // If mean residual across open bins is very low (bins nearly full), opening is fine.
        if mean_residual < item_size as f64 {
            score -= 12.0;
        }
    } else {
        // Reusing an open bin: reward keeping mean residual balanced (avoid one huge + many tiny).
        let imbalance = (mean_residual - post_residual as f64).abs();
        score += 0.08 * imbalance;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post residual, with a non-linear polynomial shaping.
    let mut score = pr;

    // Smooth polynomial coupling of post residual with stream progress.
    // Early: mild preference for tight fits; Late: stronger tightening.
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (1.0 - progress);
    score += 30.0 * poly;

    // Penalize large post residual that cannot fit the next item (dead space).
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 15.0 * (1.0 - pr / ni) * (0.5 + progress);
        } else {
            // Reward leaving room exactly usable by next item.
            score -= 8.0 * (1.0 - ((pr - ni) / cap)).min(1.0);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 + 10.0 * progress;
    }

    // Mild penalty when this bin is much above mean residual (keeps balance).
    score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);

    // New-bin candidate: penalize slightly so it is chosen only when fits are bad,
    // more so late in the stream.
    if bin_residual == bin_capacity {
        score += 12.0 + 18.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual modulo 10 buckets
    let pr_mod = post_residual % 10;
    // Dead-space penalty: leftovers in (0..10) are nearly unusable for items >=10
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Harmonic reward: post_residual divisible by common item granularities
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 12.0;
    }
    if post_residual % 20 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 && post_residual > 0 {
        score -= 10.0;
    }
    // Perfect fit
    if post_residual == 0 {
        score -= 100.0;
    }

    // Lookahead harmonic coupling: can next item exactly fill the post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let left2 = post_residual - next_item_size;
            if left2 == 0 {
                score -= 40.0;
            } else if left2 % 10 == 0 {
                score -= 15.0;
            } else if left2 < 10 {
                score += 10.0;
            }
        } else {
            // next item cannot use this leftover; penalize small leftovers more
            if post_residual < next_item_size && post_residual < 15 {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when no good fit exists
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = 55.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative
        } else if fitting_bins_count == 1 {
            score += 5.0; // last chance bin exists, prefer it slightly
        }
        // large items (>= 60) pair well with fresh bins
        if item_size >= 60 {
            score -= 10.0;
        }
        // early stream: opening bins is cheap
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Tight-fit bonus: item fills most of the bin
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Penalize placing into bins whose residual is far above mean (fragmentation spread)
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev.abs();

    // Prefer denser packing when many bins are open
    score += 0.3 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small to hold any future
    // item (assumed min size ~1..10) are pure waste. Penalize the "unusable
    // gap" band super-linearly.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 30.0;
    }

    // Reward tight fits: small post_residual in the usable band is good.
    if post_residual > 10 && post_residual <= 25 {
        score -= (25 - post_residual) as f64 * 1.5;
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (unless it creates dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        if post_residual > 10 {
            score -= 40.0;
        } else {
            score -= 10.0;
        }
    }

    // Open-bin pressure: many open bins -> prefer consolidating into
    // existing bins; few open bins -> opening a new bin is cheaper.
    let pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only when few bins are open or the
        // item fits nowhere well (would create dead space in every bin).
        score -= pressure - 8.0;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    } else {
        // Existing bin gets slight consolidation reward proportional to pressure.
        score -= 0.5;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 45.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Mild preference to fill emptier bins first when many are open.
    score += (post_residual as f64 - mean_residual).max(-20.0).min(20.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fill is ideal regardless of lookahead.
    if post_residual == 0 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the leftover.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if post_residual == next_item_size {
            score -= 120.0; // perfect 2-step chain
        } else if post_residual > next_item_size {
            // leftover after the next item would also land here: smaller leftover better
            score -= 40.0 * (1.0 - (post - nxt) / bin_capacity as f64);
        } else {
            // dead space: next item cannot use the residue
            score += 60.0 * (nxt - post) / nxt.max(1.0);
        }
    }

    // Penalize tiny unusable residues relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it moderately attractive only when it beats bad fits.
    if bin_residual == bin_capacity {
        score = 150.0 + 0.1 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 0.5 * next_item_size as f64; // fresh bin pairs well with big next item
        }
    }

    // Mild preference for tightening residual spread across open bins.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Late-stream urgency: close bins out as the stream ends.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize large dead space nonlinearly (waste grows superlinearly).
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead * dead;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Penalize residuals that are too small to ever be useful again.
            if post_residual < 10 {
                score += 15.0;
            }
        }
        // Extra reward if next item fits almost exactly in post residual.
        let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
        if next_fit <= 1.0 {
            score -= 8.0 * next_fit;
        }
    }

    // Global state coupling: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones; when few bins are open, new bins are cheap.
    let openness = open_bins_count as f64 / (1.0 + total_items as f64 * 0.05);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus penalty scaled by stream progress and openness.
        score += 20.0 + 30.0 * (step_index as f64 / total_items.max(1) as f64) + 25.0 * openness.min(2.0);
    } else {
        // Using an existing bin is rewarded more as the stream progresses.
        score -= 5.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balanced usage),
    // penalize outliers that hoard space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Prefer bins with smaller residual overall (fill emptier-of-space bins first).
    score += 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: quadratic growth of dead-space penalty with progress
    let dead_penalty = norm_pr * norm_pr * (0.5 + 2.0 * progress) * cap;
    score += dead_penalty;

    // Reward tight fits (small post_residual) more strongly later in the stream
    let tightness = 1.0 - norm_pr;
    score -= tightness * tightness * (1.0 + 3.0 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // Penalize opening new bins when many open bins exist and residuals are high
    if bin_residual == bin_capacity {
        let crowd = (open_bins_count as f64).ln().max(0.0);
        score += 8.0 + crowd * (2.0 + 4.0 * progress);
    } else {
        // Prefer bins with residuals close to the mean residual (balance)
        let dev = (bin_residual as f64 - mean_residual).abs() / cap;
        score += dev * (3.0 + 5.0 * progress);
    }

    // Lookahead: reward leaving room for the next item; penalize blocking it
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if pr >= n {
            score -= 6.0 * (n / cap) * (1.0 + progress);
        } else {
            score += 5.0 * (1.0 - pr / n.max(1.0)) * (1.0 + progress);
        }
    }

    // Mild preference for consolidating into fewer bins early on
    score += (open_bins_count as f64) * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" multiples
    // (highly divisible residuals are easier to fill with common item sizes).
    let pr = post_residual;
    if pr > 0 {
        let divisibility_bonus = match pr % 10 {
            0 => 6.0,
            5 => 3.0,
            2 | 4 | 6 | 8 => 1.0,
            _ => 0.0,
        };
        score -= divisibility_bonus;

        // Integer-division thresholds: classify residual into harmonic bands.
        let band = pr / (bin_capacity / 4); // 0..=4
        score -= band as f64 * 2.0;

        // Dead-space penalty: residual too small for the smallest plausible item.
        if pr < 10 && pr > 0 {
            score += 25.0;
        }
    } else {
        // Perfect closure is ideal.
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            score -= 4.0;
            // Harmonic residue match between next item and post_residual
            if pr % 10 == next_item_size % 10 {
                score -= 3.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin attractive only when current
    // fit is poor (large post_residual means wasteful placement).
    if bin_residual == bin_capacity {
        // Neutral baseline: slightly worse than a perfect fit, better than waste.
        score = cap * 0.35;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild pressure toward consolidating bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post_residual as f64 / cap) * 6.0;

    // Prefer bins tighter than the mean (better packing density).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..=10)
    // can use are pure waste; penalize them quadratically.
    if post_residual > 0 && post_residual <= 10 {
        score += (11 - post_residual) as f64 * 12.0;
    }
    // "Almost full" bins are excellent: reward very tight fits.
    if post_residual <= 3 {
        score -= 25.0;
    }

    // Reward exact-ish fits relative to item size scale.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= tightness * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidation
    // (penalize spreading); when few open, tolerate new bins less.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Mean-residual coupling: if this bin is far below mean residual, it's a
    // poor consolidation target; nudge score up.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e., this call is the fresh bin and item is large relative to residuals).
    if bin_residual == bin_capacity {
        let fresh_bonus = 20.0 + item_size as f64 * 0.3;
        // Opening is good if existing bins are nearly full (small mean residual).
        score = score - fresh_bonus + mean_residual * 0.5;
        if fitting_bins_count == 1 {
            score += 60.0; // another bin exists that fits; prefer it over opening
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near-perfect match: next item fits with small slack
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize dead space below next item size (unusable for lookahead item)
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += 12.0 * (dead / next_item_size as f64);
    }

    // Compare residual against mean residual: prefer filling below-average bins
    let residual_f = bin_residual as f64;
    if residual_f < mean_residual {
        score -= (mean_residual - residual_f) * 0.5;
    } else {
        score += (residual_f - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Tight fits (small post residual) generally preferred
    score -= 10.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Early in stream: mildly prefer keeping bins flexible (large post_residual)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    // Slight penalty for opening a new bin when alternatives exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but heavily reward near-exact fits.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_quality = 1.0 - (pr / cap).powf(2.0);
    score -= 30.0 * fit_quality;

    // Penalize dead space that no plausible future item can use.
    // Items are 1..=100; residual smaller than ~min item is dead.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 1.0 {
            score -= 40.0;
        } else if nxt <= pr {
            score -= 8.0 * (1.0 - ((pr - nxt) / cap));
        } else {
            // next item won't fit here: mild penalty proportional to wasted pairing potential
            score += 3.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // more competition: slight penalty to keep discrimination sharp
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Time horizon: early in the stream, be more conservative about filling bins tightly
    // (keep flexibility); late in the stream, aggressive consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fit_quality;

    // Global state: many open bins with high mean residual -> favor consolidating into
    // existing bins rather than spreading.
    let mean_r = mean_residual;
    if bin_residual < bin_capacity {
        // consolidation pressure grows with open_bins_count and mean_residual
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0) * (mean_r / cap);
    }

    // New-bin candidate handling: empty bin should only win when current bin fit is bad
    // or the bin is a poor host for upcoming work.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by stream position and congestion.
        let mut new_bin_cost = 18.0;
        // If item is large, opening a fresh bin is more natural (large items pair poorly).
        new_bin_cost -= 0.1 * item_size as f64;
        // Late in stream with many bins open, avoid new bins.
        new_bin_cost += 15.0 * progress * (open_bins_count as f64).ln().max(1.0);
        // If many bins fit the item, opening new bin is wasteful.
        new_bin_cost += 6.0 * (fitting_bins_count as f64);
        score += new_bin_cost;
    }

    // Slight preference for fuller bins (lower residual before placement).
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: post-residual (prefer tight fits)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: tolerate larger residuals (bins can be topped up later).
    // Late in the stream: heavily penalize wasted space.
    let pr_norm = pr / cap; // 0..1
    let poly = pr_norm * pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm); // peaks mid-range residuals
    score += poly * cap * (0.5 + 2.0 * progress);

    // Smooth progress-driven discount for filling an existing bin well.
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * cap * (0.3 + 0.7 * progress);

    // Dead-space penalty: residual too small to plausibly fit future items,
    // penalized smoothly and more strongly late in the stream.
    let dead_threshold = 10.0f64.min(cap * 0.2);
    if pr_norm > 0.0 && pr < dead_threshold {
        let d = (dead_threshold - pr) / dead_threshold;
        score += d * d * cap * (0.4 + 1.2 * progress);
    }

    // Last-chance bonus: only fitting bin — smooth reward.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: if the next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let gap = pr - nxt;
            let gap_norm = gap / cap;
            score -= 15.0 * (1.0 - gap_norm) * (1.0 - gap_norm);
        } else {
            // Next item won't fit here; mild penalty scaled by overflow ratio.
            let over = (nxt - pr) / cap;
            score += 6.0 * over * (0.5 + progress);
        }
    }

    // Congestion: many open bins with low mean residual -> prefer consolidating
    // into existing bins (penalize opening/keeping sparse bins).
    let mean_norm = mean_residual / cap;
    let congestion = (open_bins_count as f64).ln_1p();
    score += congestion * mean_norm * (2.0 + 4.0 * progress);

    // Brand-new empty bin candidate: penalize mildly, more when open bins exist
    // and stream is progressing (encourages consolidation), but allow early.
    if bin_residual == bin_capacity {
        let base = 8.0 + 14.0 * progress + 2.0 * (open_bins_count as f64).ln_1p();
        // If current item is large relative to capacity, new bin is more attractive.
        let large = (item_size as f64) / cap;
        score = base - 10.0 * large * large;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify residual into capacity-fraction buckets.
    // Residuals that are "nice" fractions of capacity (0, C/4, C/2, 3C/4) are more reusable.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    let three_quarter = 3 * bin_capacity / 4;

    // Reward exact harmonic classes
    if post_residual == 0 {
        score -= 30.0; // perfect fit, ideal
    } else if post_residual == quarter || post_residual == half || post_residual == three_quarter {
        score -= 12.0;
    } else {
        // Penalize residuals in awkward modulo classes (small dead space)
        let m = post_residual % 10;
        if m != 0 {
            score += (10 - m) as f64 * 0.6; // near-multiple-of-10 residuals are better
        }
        // Very small residuals are dead space
        if pr < 10.0 {
            score += 25.0;
        } else if pr < 20.0 {
            score += 10.0;
        }
    }

    // Integer-division thresholds: does the NEXT item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size > post_residual {
            // next item won't chain here; penalize proportionally to how close it was
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.15;
        } else {
            // next item chains nicely; reward, more if the chained residual is harmonic
            let chained = post_residual - next_item_size;
            if chained % 10 == 0 {
                score -= 8.0;
            }
            score -= 4.0;
        }
    }

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / c;
        score += 40.0 * (1.0 - crowding); // high mean residual -> new bin expensive
        if post_residual == bin_capacity {
            score -= 5.0; // slight tiebreak preference for fresh bin when bins are empty-ish
        }
    }

    // Late in the stream, prefer tightening existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to fit the
    // smallest plausible item are "dead". Penalize them nonlinearly.
    if post_residual > 0 {
        // Fraction of the bin wasted.
        let waste = post_residual as f64 / bin_capacity as f64;
        if post_residual < 10 {
            // Unusable sliver: hard penalty so we avoid leaving scraps.
            score += 60.0 + 40.0 * waste;
        } else if post_residual < 20 {
            // Likely only usable by tiny items: strong penalty.
            score += 25.0 + 20.0 * waste;
        } else if post_residual < 40 {
            // Moderate gap: mild penalty.
            score += 8.0 * waste;
        }
    } else {
        // Perfect fit: reward strongly.
        score -= 30.0;
    }

    // Lookahead coupling: if the next item fits the post-residual exactly-ish,
    // reward this placement; if it can't fit anywhere, don't leave a gap it needs.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item can still use this bin: small reward.
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < next_item_size {
            // Gap is smaller than the next item: mild penalty for stranding it.
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // residuals are small (fragmentation risk); encourage using existing bins
    // when mean residual is large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual < bin_capacity {
        score -= pressure * 0.5;
        // Coupling with mean residual: bins with residual below mean are
        // better targets (tighten them); bins above mean are worse.
        score += (mean_residual - bin_residual as f64) * 0.05;
    } else {
        // New-bin candidate: penalize mildly so it's chosen only when
        // open bins are genuinely fragmented, but keep pressure so that
        // many open bins discourage opening yet another one.
        score += pressure * 0.8;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly favored.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // 2-step lookahead: reward when the next item exactly fills the post-residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits too: mild reward proportional to how snugly.
            score -= 50.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit: penalize leaving a gap smaller than next item.
            score += 80.0 * (1.0 - (post_residual as f64 / next_item_size as f64));
        }
    }

    // Penalize small unusable dead space (below minimum item size).
    if post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }

    // Compare against mean residual: bins already tight get priority.
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 300.0;
    }

    // Prefer keeping large residuals available early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (post_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 40.0;

    // Slight penalty when many bins are open: encourage consolidation.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportional to wasted fraction of residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize large post-residuals that can't fit the next item (dead space).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        } else {
            // Residual still useful for the lookahead item: reward.
            score -= 0.6 * (post_residual as f64 / bin_capacity as f64)
                * (1.0 - (post_residual as f64 - next_item_size as f64) / bin_capacity as f64);
        }
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins.
    score += 0.25 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Global mean residual coupling: if this bin's residual is below mean,
    // it's "smaller" than average — prefer packing into tighter bins.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * dev;

    // Time horizon: early in stream, be more willing to open new bins
    // (keep bins tight for future); late in stream, fill existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus horizon-dependent penalty.
        score += 10.0 + 40.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    } else {
        score -= 6.0 * progress;
    }

    // Mild nonlinearity: squashed sigmoid on post-residual to sharpen
    // preference for small leftovers.
    let pr = post_residual as f64 / bin_capacity as f64;
    score += 6.0 * (pr * pr * (2.0 - pr));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear reward for tight fits: quadratic coupling of post_residual with capacity.
    score -= (1.0 - (pr / cap).powi(2)) * (0.35 * cap);

    // Dead-space penalty when residual can't hold the lookahead item, coupled with stream progress.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let waste = (nx - pr).max(0.0);
        score += waste * (1.0 + progress) * 0.9;
        // Reward bins that can also fit the next item (smooth sigmoid-like gate).
        let fits_next = (pr >= nx) as f64;
        score -= fits_next * nx * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 0.6 * cap * (1.0 + 0.5 * progress);
    }

    // New-bin candidate: penalize opening a new bin mildly, more so late in the stream
    // or when many bins are open with slack that could absorb fragmentation.
    if bin_residual == bin_capacity {
        score += cap * (0.55 + 0.35 * progress) + 0.05 * open_bins_count as f64;
    } else {
        // Slight penalty for leaving residual far from the mean residual (fragmentation coupling).
        score += ((pr - mean_residual) / cap).abs() * cap * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity quarters
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    score += (class as f64) * 0.35;

    // Reward near-perfect fits (post_residual in lowest harmonic band)
    if post_residual <= bin_capacity / 20 {
        score -= 18.0;
    }
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space penalty: post_residual too small for the smallest plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    }

    // Lookahead: reward if next item fits into post_residual (chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0 + (post_residual - next_item_size) as f64 * 0.15;
    }
    // Penalize if post_residual almost fits next item (wasted chain)
    if next_item_size > post_residual && next_item_size - post_residual <= 5 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it if it fits
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 12.0 + 20.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Opening a new bin is fine if the item is large
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer filling bins that are already low-residual (tight packing)
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 10.0;

    // Mean residual coupling: when open bins are roomy on average, avoid wasting
    if post_residual as f64 > mean_residual {
        score += 4.0;
    }

    // Mild penalty per extra open bin to encourage consolidation
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small gaps (< 10, minimum item size) are pure waste.
    if post_residual < 10 {
        score -= 50.0; // perfect fill is excellent
    } else if post_residual <= 20 {
        // small unusable-ish gap: penalize heavily
        score += (20.0 - post_residual as f64) * 2.0;
    }

    // Reward tight fits relative to item size
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: prefer filling existing bins over opening new ones
    if bin_residual == bin_capacity {
        // new-bin candidate: only attractive when few bins fit the item
        score += 25.0 + (fitting_bins_count as f64) * 8.0;
    } else {
        score -= 5.0;
    }

    // Last chance: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > post_residual && post_residual < 10 && bin_residual != bin_capacity {
        score += 5.0; // dead space that next item can't use
    }

    // Prefer bins with lower residual among comparable options (mean-residual coupling)
    if bin_residual != bin_capacity {
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly favor perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 50.0 + post_residual as f64;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual > next_item_size {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 40.0 - slack as f64 * 2.0;
            }
        } else {
            // next item cannot fit here: penalize small dead space left behind
            let dead = post_residual;
            if dead < 10 {
                score += (10 - dead) as f64 * 3.0;
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // Penalize wasting a large bin residual on a small item early in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 40 {
        score += (post_residual as f64 - 40.0) * (0.3 + 0.7 * progress);
    }

    // Slight preference for filling existing bins when many are open.
    score += open_bins_count as f64 * 0.05;

    // New-bin candidate: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0 - (fitting_bins_count as f64) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: the closer the bin is filled to capacity, the better.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize leaving awkward dead space (small but nonzero post_residual).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if the next item exactly fits the post residual,
    // penalize if next item fits but leaves another awkward gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size > post_residual {
            score += 8.0; // next item won't fit here; mild penalty for hoarding space
        } else {
            let nxt_gap = post_residual - next_item_size;
            score += 0.15 * nxt_gap as f64;
            if nxt_gap < 10 && nxt_gap > 0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless residual is large
    // (i.e., existing bins are nearly full anyway).
    if bin_residual == bin_capacity {
        let avg_load = bin_capacity as f64 - mean_residual;
        let pressure = avg_load / bin_capacity as f64;
        score += 45.0 * (1.0 - pressure);
        // Late in the stream, avoid spawning extra bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    } else {
        // Favor bins whose residual is close to the mean (balance load).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Many open bins: prefer consolidation into existing bins.
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 20.0 * poly;

    // Penalize dead space that can't fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress);
        } else {
            score -= 3.0 * (pr - nxt).min(30.0) / cap;
        }
    }

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: mild penalty, relaxed late in the stream
    if bin_residual == bin_capacity {
        score += 8.0 - 6.0 * progress;
    }

    // Coupling with mean residual of open bins
    score += 0.5 * (pr - mean_residual) / cap * (1.0 + open_bins_count as f64).ln();

    // Smooth tightness reward
    score -= 10.0 * (item_size as f64 / bin_residual.max(1) as f64) * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual (modulo arithmetic) ---
    // Residuals in "nice" classes (multiples of 10, or small enough to be
    // easily filled by typical items) are less dead; penalize awkward classes.
    let pr = post_residual;
    let class10 = pr % 10; // 0 = perfectly harmonious with decimal capacity
    let class25 = pr % 25;
    score += 0.6 * (class10 as f64) * 0.1;          // mild penalty off multiples of 10
    if class25 == 0 { score -= 1.5; }               // bonus for 25/50/75 residuals
    if pr % 20 == 0 { score -= 1.0; }               // bonus for multiples of 20
    if pr % 30 == 0 { score -= 0.8; }
    if pr % 7 == 0 && pr > 0 { score += 0.4; }      // awkward class penalty

    // Integer-division thresholds on post_residual: tiny residuals are dead space.
    if pr == 0 {
        score -= 6.0; // perfect fill: strongly preferred
    } else if pr < 10 {
        score += 8.0; // unusable dead space below min item size
    } else if pr < 20 {
        score += 2.5;
    } else if pr > 60 {
        score += 1.0; // leaving a big hole wastes the bin
    }

    // --- Lookahead coupling: does next item fit the post-residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item chains nicely: reward, scaled by how tightly it fits.
            let tightness = 1.0 - ((pr - next_item_size) as f64) / (bin_capacity as f64);
            score -= 2.0 + 2.0 * tightness;
            // Harmonic chain bonus: next item lands post-residual on a nice class
            let pr2 = pr - next_item_size;
            if pr2 % 10 == 0 { score -= 1.5; }
            if pr2 == 0 { score -= 3.0; }
        } else {
            // Next item will NOT fit here: penalize, harder if residual is big.
            score += 1.0 + 0.02 * (pr as f64);
        }
    }

    // --- Last-chance bin logic ---
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 4.0; // only bin that fits: strongly prefer using it
    }

    // --- New-bin candidate handling ---
    if bin_residual == bin_capacity {
        // Opening a new bin: base cost, modulated by stream progress and load.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = 12.0
            + 6.0 * progress                       // later in stream: bins already sunk cost
            - 1.5 * (open_bins_count as f64).ln().max(0.0);
        // If current item is large and would leave a bad residual elsewhere,
        // fresh bin is more attractive.
        if item_size > 70 { score -= 2.0; }
        // If mean residual across open bins is small, open bins are nearly
        // full anyway: new bin is fine.
        if mean_residual < 15.0 { score -= 2.5; }
        // If next item is large, keep open bins' space for it; new bin now is good.
        if next_item_size >= 60 { score -= 2.0; }
    } else {
        // Prefer filling existing bins when mean residual is high (avoid sprawl).
        score -= 0.03 * mean_residual;
        // Slight preference for fewer open bins (consolidation).
        score -= 0.05 * (open_bins_count as f64);
    }

    // --- Fit tightness reward: smaller post_residual relative to item is best-fit ---
    score -= 0.5 * (item_size as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the minimum plausible item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual <= 15 {
        score += 12.0;
    }

    // Reward tight fits (small post residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 8.0 * tightness;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage new bins and
    // encourage filling existing ones.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    if bin_residual == bin_capacity {
        // Candidate for a brand-new bin: penalize when many bins are open
        // or when the item fits reasonably well somewhere else.
        score += 20.0 * pressure;
        if fitting_bins_count > 0 && post_residual <= bin_capacity as f64 as u32 / 2 {
            score += 15.0;
        }
    } else {
        score -= 6.0 * pressure;
    }

    // Lookahead: if the next item fits exactly in the post residual,
    // reward this placement (sets up a perfect follow-up).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0;
    }

    // Mean-residual coupling: bins far below mean residual are good targets
    // for consolidation (balance residuals across open bins).
    score -= 0.05 * (mean_residual - bin_residual as f64);

    // Slight stream-progression bias: late in the stream, prefer
    // consolidating into existing bins even harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits (post_residual == 0)
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // 2-step lookahead: if next item fits exactly into post_residual, strong reward
        if next_item_size > 0 {
            if post_residual == next_item_size {
                score -= 150.0;
            } else if post_residual >= next_item_size {
                score -= 40.0;
            } else {
                // post_residual too small for next item: penalize dead space
                score += (post_residual as f64) * 0.5;
            }
        }

        // Relative-to-mean-residual coupling: bins tighter than mean are more valuable
        let tightness = mean_residual - post_residual as f64;
        score += tightness * 0.3;

        // Penalize very small unusable post residuals (wasted space)
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize so it's only chosen when all fits are terrible
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if next item is large and this is early, opening fresh may be fine
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 30.0;
        }
    }

    // Late in the stream: prefer consolidating into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if open_bins_count > 2 {
        score += open_bins_count as f64 * progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let is_new_bin = bin_residual == bin_capacity;
    let progress = step_index as f64 / (total_items.max(1) as f64);

    // Tight-fit reward: strongly favor bins where the item leaves little waste
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit gets a big bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer it
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 25.0;
    }

    // Lookahead: penalize if the leftover space is just barely too small for the
    // next item (dead space), reward if next item exactly fits the leftover.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size > post_residual && next_item_size <= post_residual + 10 {
            // awkward dead space the next item can't use
            score += 10.0 + (post_residual as f64) * 0.1;
        } else if next_item_size < post_residual {
            // leftover still usable by next item: mild reward
            score -= 4.0;
        }
    }

    // Prefer filling bins with smaller residuals first (best-fit style)
    score += (bin_residual as f64) * 0.15;

    // Global state: if many bins are open with high mean residual, encourage
    // consolidating into existing bins rather than opening new ones.
    if is_new_bin {
        let consolidation_pressure = (mean_residual / bin_capacity as f64) * (open_bins_count as f64).sqrt();
        score += 30.0 + 20.0 * consolidation_pressure;

        // Late in the stream, opening new bins is more costly (fewer items left
        // to fill them); early on, allow more freedom.
        score += 20.0 * progress;

        // If no existing bin fits well (post_residual large relative to item),
        // soften the new-bin penalty.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
        if next_item_size > 0 && next_item_size > item_size && item_size >= bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Mild preference for bins whose residual deviates from the mean
    // (move toward homogenization of residuals for future packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling: penalize residuals that are too large (wasteful) or awkward
    score += 40.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits, stronger late in the stream
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Interaction of post_residual with mean residual: prefer bins below/above mean smoothly
    let mean_norm = mean_residual / cap;
    score += 15.0 * (norm_pr - mean_norm) * (norm_pr - mean_norm);

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly
    if next_item_size > 0 && next_item_size as f64 <= pr {
        let fit_ratio = next_item_size as f64 / pr;
        score -= 25.0 * fit_ratio * (1.0 - fit_ratio) * 4.0 * (0.5 + progress);
    } else if next_item_size > 0 {
        // next item cannot fit here; penalize proportionally to wasted potential
        score += 8.0 * (1.0 - pr / (next_item_size as f64)).max(0.0);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive early or when no good fit exists
    if bin_residual == bin_capacity {
        score += 10.0 + 20.0 * progress - 5.0 * (fitting_bins_count as f64);
    }

    // Mild pressure from number of open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: harmonic class of post_residual
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Exact fill is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Modulo classes: penalize residuals that are "wasted" dead space
    // Residuals below the minimum item size (1..=10) are dead space
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Harmonic fraction classes of capacity: prefer post_residual near k * (cap/4)
    let quarter = cap / 4.0;
    let frac = ((pr / quarter) - (pr / quarter).round()).abs();
    score += frac * 6.0;

    // Integer division threshold on post_residual class
    let class = post_residual / 20; // 0..5 harmonic classes
    score += class as f64 * 3.0;

    // Lookahead: reward if next item fits in post_residual (chaining)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward if next item fills the bin exactly after placement
        if next_item_size == post_residual {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use this residual; penalize proportionally
        score += (next_item_size as f64 - pr) * 0.15;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let penalty = 40.0
            + open_bins_count as f64 * 2.0
            + (mean_residual - pr).abs() * 0.5;
        // If item is large relative to typical residual, opening fresh is ok
        let relief = if item_size as f64 > mean_residual { 15.0 } else { 0.0 };
        score += penalty - relief;
    }

    // Progression: slightly prefer filling older bins early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Penalty for creating residual much larger than mean (fragmentation)
    if pr > mean_residual * 1.5 {
        score += (pr - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward tight fits relative to bin capacity.
    score -= (item_size as f64 / bin_capacity as f64) * 20.0;

    // Open-bin pressure: with many open bins, discourage opening new ones;
    // penalize spreading residual thin across many bins.
    score += open_bins_count as f64 * 1.5;
    if bin_residual < bin_capacity {
        // Slight bonus for using an already open (partially filled) bin.
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // Penalize if post residual is too small for next item but nonzero (dead space blocks lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins) to consolidate.
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Late in stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 12.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when post_residual exactly matches next item,
    // or when post_residual + next_item_size would be consumed.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size <= 10 {
            score -= 150.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // Dead space relative to the lookahead item: penalize proportionally.
            let dead = post_residual as f64 / next_item_size as f64;
            score += 80.0 * dead;
        }
    }

    // Compare post_residual against mean residual: leaving a bin far below mean
    // residual wastes capacity elsewhere; prefer bins that end near/below mean.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // Penalize leaving large residual when many bins are open (fragmentation).
    score += 0.3 * (open_bins_count as f64) * (post_residual as f64 / bin_capacity as f64);

    // Early in the stream, be slightly more willing to open fresh bins for big items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, or for large items with poor fits elsewhere.
        let open_bonus = 60.0 * (1.0 - progress);
        score -= open_bonus;
        if next_item_size > 0 && item_size >= next_item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: fraction of bin consumed by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill * fill;

    // Penalize dead space relative to smallest plausible future item (1..100 unknown dist).
    if post_residual > 0 {
        let dead = (post_residual as f64 / bin_capacity as f64).powf(1.5);
        score += 10.0 * dead;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // mild reward proportional to how well next item uses leftover
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * next_fill;
        } else {
            // next item won't fit here; penalize leaving a gap smaller than next item
            score += 8.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Time horizon: early in the stream, be conservative (prefer tight fits,
    // avoid fragmenting); late in the stream, prioritize closing bins out.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * fill;

    // Many open bins: encourage consolidation by penalizing bins far from mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev * (open_bins_count as f64).sqrt();

    // New-bin candidate handling: an empty bin is a fallback; make it attractive
    // only when the item is large or fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let large_item_bonus = 20.0 * fill;
        score -= large_item_bonus;
        // discourage opening new bins when plenty of open bins exist with room
        score += 3.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * (1.0 - norm_pr);
    score += 40.0 * poly;

    // Penalize residual that is unusable for typical items (dead space), smoothly
    let dead = (-norm_pr * 10.0).exp();
    score += 25.0 * dead * (0.5 + 0.5 * progress);

    // Reward tight fits: item filling most of the bin
    let fill = item_size as f64 / cap;
    score -= 30.0 * fill * fill * (1.0 - norm_pr);

    // Lookahead: if next item fits in post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 8.0 * (next_item_size as f64 / cap) * (1.0 - progress);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Dampen preference for spreading across many bins late in stream
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - progress);

    // Mean residual coupling: prefer bins near mean residual (smoothness)
    let dev = (pr - mean_residual).abs() / cap;
    score += 10.0 * dev * dev;

    // New-bin candidate: make empty bin mildly attractive only when residuals are poor
    if bin_residual == bin_capacity {
        score = 60.0 + 40.0 * (1.0 - progress) - 30.0 * (mean_residual / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: bins whose leftover falls into
    // "nice" residue classes are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Penalize dead space that cannot hold typical small items (1..=20).
    if pr < 10 && pr > 0 {
        score += 12.0;
    } else if pr == 0 {
        score -= 8.0; // perfect closure is excellent
    }

    // Modulo-class logic: residuals divisible by common item sizes (10/20/25/50)
    // are harmonically reusable.
    let harmonic_bonus = if pr % 10 == 0 {
        6.0
    } else if pr % 25 == 0 {
        4.0
    } else if pr % 20 == 0 {
        3.0
    } else if pr % 5 == 0 {
        1.5
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Fractional capacity classes of the residual.
    let frac = prf / cap;
    if frac >= 0.5 {
        score -= 4.0; // half-full-or-more capacity left is valuable
    } else if frac >= 0.25 {
        score -= 1.0;
    } else if frac > 0.0 {
        score += 2.0; // small slivers are risky
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly reward this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 15.0;
        } else if next_item_size <= pr {
            // next item fits: leftover after next placement matters
            let pr2 = pr - next_item_size;
            score -= 3.0 + (pr2 % 10 == 0) as i32 as f64 * 3.0;
        } else {
            score += 2.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 0.3;

    // Slight preference for tighter fits as the stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual - item_size) as f64 / cap * progress;

    // New-bin candidate: prefer it only when it beats very poor fits.
    if bin_residual == bin_capacity {
        score += 14.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..small)
    // can plausibly fill are dead weight. Penalize tiny unusable gaps hard.
    if post_residual > 0 {
        let dead_threshold = 12.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        }
        // Perfect fit is heavily rewarded
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Tightness reward: fraction of the bin's space consumed by this placement
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance pressure: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage opening new bins when many are already open.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 20.0 + 3.0 * (open_bins_count as f64);
        // But if no open bin fits at all, new bin is the only choice; soften penalty
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Lookahead: if next item is large, a fresh bin is more attractive
        if next_item_size > 0 {
            score -= (next_item_size as f64 / 100.0) * 15.0;
        }
    } else {
        // Reward placing into bins with larger residuals relative to mean
        score -= (bin_residual as f64 - mean_residual) * 0.5;
        // Lookahead compatibility: bonus if post_residual fits the next item exactly well
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 10.0;
        }
        // Penalize wasting a big residual on a small item
        if (item_size as f64) < bin_residual as f64 * 0.4 {
            score += 12.0;
        }
    }

    // Mild stream-progression pressure: later in the stream, prefer closing bins
    // tightly rather than spreading across many.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + (post_residual - next_item_size) as f64 * 0.15;
        } else {
            // post_residual too small for next item: penalize wasted dead space
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // Perfect chaining: next item exactly fills remaining space
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: just minimize waste
        score += 10.0;
    }

    // Relative to mean residual: prefer bins with residual below mean (tighter bins)
    score += (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Many open bins: discourage spreading; prefer filling existing bins tightly
    if open_bins_count > 4 {
        score -= 5.0;
    }

    // Early in stream: slightly favor keeping flexibility (larger post_residual ok)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        // Penalize opening a new bin unless current item is large relative to capacity
        score += 40.0;
        if item_size > bin_capacity / 2 {
            score -= 35.0;
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score += 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize wasted relative capacity more strongly for large items.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * (item_size as f64 / bin_capacity as f64) * 12.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly (or well) into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            let next_waste = post_residual - next_item_size;
            score -= (next_item_size as f64 / bin_capacity as f64) * 10.0;
            score += next_waste as f64 * 0.05;
        } else {
            // Next item won't fit here; slight penalty proportional to leftover dead space.
            score += (post_residual as f64 / bin_capacity as f64) * 3.0;
        }
    } else {
        // Last item overall: just minimize waste.
        score += post_residual as f64 * 0.1;
    }

    // New-bin candidate handling: opening a new bin is attractive only when this item
    // would leave a large awkward residual in an existing bin, or few bins fit.
    if bin_residual == bin_capacity {
        // Baseline new-bin score: prefer it when existing fit is poor.
        let fit_quality = post_residual as f64 / bin_capacity as f64; // = 1 - item/C for new bin
        score = 55.0 + fit_quality * 10.0;
        if fitting_bins_count <= 2 {
            score -= 15.0; // scarcity of alternatives favors new bin
        }
        if next_item_size > 0 && next_item_size <= (bin_capacity - item_size) {
            score -= 8.0; // new bin can host the next item too
        }
    } else {
        // Penalize leaving residuals that are hard to fill (small odd gaps).
        if post_residual > 0 && post_residual < 10 {
            score += 6.0;
        }
        // Mild bonus for bins already below mean residual (consolidate emptier bins).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
        // Early stream: be slightly greedy toward tight fits; late stream: conserve bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 3.0;
        // Many open bins: discourage spreading; favor filling existing ones harder.
        score -= (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with smooth polynomial shaping
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    // Early stream: prefer tight fits (penalize large residual more via convexity)
    // Late stream: tolerate larger residuals slightly (bins will close anyway)
    let curvature = 1.0 + 0.8 * p2 + 0.5 * p3;
    score += curvature * pr_norm * pr_norm * 20.0;

    // Reward filling bins nearly completely, stronger as stream progresses
    let fill = 1.0 - pr_norm;
    score -= fill * fill * (10.0 + 15.0 * progress);

    // Dead-space penalty: residuals too small for typical items
    let next_norm = next_item_size as f64 / cap;
    if next_item_size > 0 {
        let waste = (next_norm - pr_norm).max(0.0);
        score += waste * waste * 30.0;
        // Bonus if next item fits exactly-ish
        let snug = 1.0 - (next_norm - pr_norm).abs() * 4.0;
        if snug > 0.0 {
            score -= snug * 8.0 * (0.5 + progress);
        }
    }

    // Last-chance bin: strong reward to use it
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Mild penalty when many bins open and this one is far from mean residual
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 5.0 * (open_bins_count as f64).ln().max(1.0);

    // Discourage opening new bins early when a reasonable fit exists
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * (1.0 - progress);
    }

    // Smooth item-size coupling: prefer placing larger items into tighter bins
    let size_norm = item_size as f64 / cap;
    score -= size_norm * fill * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits; reward small post_residual strongly.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    score = pr + (pr / cap) * (pr / cap) * 20.0;

    // Harmonic class of post_residual: classify dead space by integer division on capacity fractions.
    let class = post_residual / 10; // 0..=10 classes
    // Penalize classes that are hard to fill (small unusable leftovers, e.g. 1..9, 11..19 style gaps)
    let class_penalty = match class {
        0 => -60.0,                       // near-perfect fit, huge reward
        1 => 12.0,                        // 10-19 left: awkward
        2 => 4.0,                         // 20-29: moderately useful
        3 => 2.0,
        4 => 0.0,
        5 => -2.0,
        6 => -1.0,
        7 => -3.0,
        8 => -5.0,
        9 => -8.0,
        _ => -10.0,                       // nearly empty bin
    };
    score += class_penalty;

    // Modulo coupling: post_residual matching common small-item sizes (harmonic divisors)
    let harmonics: [u32; 6] = [10, 20, 25, 50, 33, 34];
    for h in harmonics.iter() {
        if post_residual >= *h && post_residual - *h < 5 {
            score -= 6.0; // residual lands just above a harmonic size -> likely reusable
        }
        if post_residual > 0 && post_residual < *h && *h - post_residual <= 3 {
            score += 5.0; // just below a harmonic -> dead space risk
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use leftover: penalize proportionally
            score += (next_item_size as f64 - pr).min(cap) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full.
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + open_f * 2.0 - progress * 10.0;
        if mean_residual > item_size as f64 * 1.5 {
            score += 15.0; // plenty of space already open; avoid new bin
        }
    }

    // Prefer bins whose residual is already below mean (consolidation).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    // Slight preference for fuller bins overall.
    score += (1.0 - (bin_residual as f64) / cap) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual == 0 {
        score -= 40.0; // perfect fill is ideal
    } else if post_residual <= 20 {
        // residual usable only by small items; mildly penalize
        score += 15.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Reward tight fits relative to bin capacity
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: many open bins -> prefer consolidating into existing bins,
    // penalize opening new ones.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate handling: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 1.5
            + (mean_residual / bin_capacity as f64) * 20.0;
        // new bin is good if next item is large and nothing fits well
        if post_residual as f64 > mean_residual {
            score += 10.0 + pressure;
        } else {
            score += 30.0 + pressure;
        }
        // lookahead: if next item is big, a fresh bin is more valuable
        score -= next_item_size as f64 * 0.2;
    } else {
        // existing bin that can also host the next item is valuable
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 12.0;
        }
        // penalize leaving residual that blocks a large next item
        if next_item_size > post_residual && next_item_size > 0 {
            score += 5.0;
        }
    }

    // Late in stream: tighten up, avoid wasting capacity
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> huge reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits comfortably but not perfectly.
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 - slack * 0.4;
        if slack <= 5.0 {
            score -= 10.0; // tight near-match is very good
        }
    }
    // Next item does NOT fit: post_residual becomes dead space unless it's 0.
    else if next_item_size > 0 && post_residual > 0 {
        score += 15.0 + post_residual as f64 * 0.15;
    }

    // Zero post-residual is always ideal (bin perfectly closed now).
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize creating unusable slivers (below minimum item size 1..10 range).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Compare against mean residual: filling a bin below average is good.
    score -= (mean_residual - post_residual as f64) * 0.25;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New empty bin candidate: penalize unless few bins fit the item or residual is large.
    if bin_residual == bin_capacity {
        let penalty = 40.0 + (open_bins_count as f64) * 2.0;
        score += penalty;
        if fitting_bins_count <= 1 {
            score -= 45.0; // forced to open a new bin anyway
        }
        if next_item_size > 0 && item_size + next_item_size > bin_capacity {
            score -= 20.0; // current item won't combine with next; fresh bin OK
        }
    }

    // Slight preference to fill older/tighter bins as stream progresses.
    score += (step_index as f64 / (total_items.max(1) as f64)) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: penalize bins whose residual is close to item size
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score -= 30.0 * (1.0 - tightness).exp();

    // Penalize large post-residual dead space (unusable fragments)
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // small dead space is bad
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 0.15 * next_item_size as f64;
        } else {
            score += 5.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last chance: strongly favor using the only fitting bin to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: make empty bins less attractive unless open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        // discourage new bins mildly; escalate when many bins already open
        score += 25.0 + 3.0 * open_bins_count as f64;
        // but if item is large relative to mean residual, opening fresh may be fine
        let mean_res = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        if item_size as f64 > mean_res + 0.5 * (bin_capacity as f64 - mean_res) {
            score -= 20.0;
        }
        // early in stream, allow new bins more freely
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Global state coupling: when mean residual is small, prefer bins with residual near mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.1 * dev;

    // Time horizon: late in the stream, be greedier (favor tightest fits harder)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * (1.0 - tightness);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual (tight fit preferred)
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // early on, tolerate larger residuals (bins can still be filled later);
    // late in the stream, dead space becomes costly.
    let progress_weight = 0.35 + 1.15 * progress * progress;
    score += progress_weight * 60.0 * norm_pr * norm_pr;

    // Smooth convex penalty for leaving awkward mid-range gaps
    // (residuals just below typical small items are worst).
    let gap_curve = 4.0 * norm_pr * (1.0 - norm_pr); // peaks at half-full residual
    score += 25.0 * gap_curve * (1.0 - progress);

    // Lookahead: reward if next item fits exactly into post residual
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let fit_quality = 1.0 - (pr - nx) / cap;
            score -= 30.0 * fit_quality * fit_quality;
        } else {
            // penalize residuals that cannot host the lookahead item
            score += 12.0 * (nx - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive early or when open bins are messy
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64 / (open_bins_count as f64 + 4.0)) * mean_residual / cap;
        score += 55.0 * (1.0 - progress) + 40.0 * open_pressure;
        if fitting_bins_count > 0 {
            score += 20.0; // discourage new bin when alternatives exist
        }
    }

    // Mild diversity term: prefer bins whose residual differs from mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual).abs() / cap;
    score += 8.0 * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: classify dead space by residue classes
    let pr = post_residual;
    let class: u32 = if pr == 0 { 0 } else { pr % 10 };
    // Small residues (1,2,3) create nearly unusable slivers -> penalize
    if class >= 1 && class <= 3 && pr > 0 {
        score += 12.0 * (4.0 - class as f64);
    }
    // Residues that are likely future item sizes (multiples of 5/10) are valuable
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    } else if pr % 5 == 0 && pr > 0 {
        score -= 4.0;
    }

    // Integer-division thresholds: how many "typical" items (>=10) still fit
    let slots = pr / 10;
    score -= slots as f64 * 3.0;

    // Lookahead coupling: does next item fit exactly in post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 500.0;
        } else if next_item_size <= pr {
            // next fits: reward proportional to tightness
            let tight = (pr - next_item_size) as f64;
            score -= 60.0 / (1.0 + tight / 10.0);
        } else {
            // next item does not fit here: penalize proportionally to overshoot
            let over = (next_item_size - pr) as f64;
            score += 15.0 * (1.0 - 1.0 / (1.0 + over / 20.0));
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Prefer tight fits relative to item size
    score += (item_size as f64) * 0.05;

    // Penalize bins far below mean residual (fragmented outliers) mildly
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    }

    // Early in stream, be more willing to open new bins (keep options open)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New bin candidate: base cost plus remaining-space penalty;
        // cheaper to open early, expensive late
        score = 40.0 + (1.0 - progress) * 20.0 + (post_residual as f64) * 0.1;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual is "dead" if it is too small to hold even the smallest plausible item.
    if post_residual > 0 {
        // Non-linear blowup for tiny residuals (1..=10): quadratic wedge.
        if post_residual <= 10 {
            score += (11 - post_residual) as f64 * (11 - post_residual) as f64 * 1.5;
        }
        // Medium dead zones (11..=20): moderately bad, item sizes below 10 are rare.
        else if post_residual <= 20 {
            score += (21 - post_residual) as f64 * 2.0;
        }
        // Residuals that exactly accommodate common small item sizes are valuable:
        // reward near-perfect "shaped" residuals.
        for anchor in [10u32, 20, 25, 30, 40, 50] {
            if post_residual == anchor {
                score -= 6.0;
            }
        }
    } else {
        // Perfect fill: strong reward.
        score -= 25.0;
    }

    // Reward tight fits relative to item size (best-fit flavor with sharpening).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few bins are open, filling existing bins is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (2.0 + 3.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Lookahead coupling: if the next item fits the post-residual, this placement
    // chains nicely; if the next item would fit better elsewhere, mild penalty.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_quality = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 4.0 + 6.0 * chain_quality;
        } else if next_item_size <= bin_residual && post_residual > 0 && post_residual <= 15 {
            // Next item fits the bin only before this placement; penalize wasting it.
            score += 8.0;
        }
    }

    // New-bin candidate logic: only attractive when current open bins are crowded
    // (low mean residual) or the fit here is terrible.
    if bin_residual == bin_capacity {
        let crowded = mean_residual < item_size as f64 * 1.2;
        let bad_fit = (bin_residual - item_size) <= 10;
        if crowded || bad_fit {
            score -= 10.0;
        } else {
            score += 12.0 + mean_residual * 0.05;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small post_residual is already low; amplify).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into the
    // post-residual, this is a perfect chain -> strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 150.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 70.0;
        }
        // Penalize leaving residual that is *almost* but not quite usable
        // by the next item (dead space trap).
        if post_residual < next_item_size && next_item_size - post_residual <= 8 {
            score += 30.0;
        }
        // Penalize leaving a residual larger than the max plausible item
        // when it's much larger than next item (wasted slack).
        if post_residual > next_item_size + 40 {
            score += 10.0;
        }
    }

    // Compare post_residual against mean residual: creating an outlier
    // residual far from the mean is bad (hard-to-fill hole or wasted space).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large relative to capacity (big items fill fresh bins efficiently).
    if bin_residual == bin_capacity {
        score += 25.0;
        if item_size >= 70 {
            score -= 35.0;
        }
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 20.0; // fresh bin will serve next item
        }
    }

    // Early in the stream, be slightly more willing to open bins to build
    // a good residual pool; late in the stream, consolidate tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: quadratic bonus for small post residuals.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Exact / near-exact fill gets a strong bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 12.0 * (post_residual as f64 / next_item_size as f64).ln().max(0.0);
        } else {
            // leftover too small for next item: penalize dead space proportionally
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 20.0 * waste * waste;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize opening new bins when open bins are underutilized.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline offset plus pressure terms.
        score += 30.0;
        score += 8.0 * open_bins_count as f64;
        score -= 0.5 * mean_residual;
        // Early in the stream, opening bins is cheap; late, it is costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 * progress;
    } else {
        // Existing bins get a mild preference, stronger when many bins are open.
        score -= 5.0 + 2.0 * open_bins_count as f64;
    }

    // Prefer bins whose residual deviates favorably from the mean (balance exploitation).
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.15 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, mildly non-linearly warped
    let mut score = pr + 20.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, keep bins tight (penalize large post_residual more);
    // later, tolerate spread residuals.
    let warp = 0.5 + 1.5 * progress * progress;
    score *= warp;

    // Interaction: squared progress * post_residual (favor filling bins as stream matures)
    score -= 15.0 * progress * progress * (cap - pr);

    // Penalize dead space that cannot fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 0.6 * (nx - pr) * (1.0 + progress);
        } else {
            // reward residuals that still fit the next item, smoothly
            score -= 0.3 * (pr - nx).min(cap - pr);
        }
    }

    // Last-chance bin: strongly favor using it (avoid opening a new bin)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // New-bin candidate: penalize mildly, unless open bins are nearly full
    if bin_residual == bin_capacity {
        let tight = mean_residual / cap;
        score = cap + 10.0 * (1.0 - tight) - 8.0 * progress;
    }

    // Mean-residual coupling: prefer bins close to the mean residual (balance)
    let dev = (pr - mean_residual).abs();
    score += 0.1 * dev * (1.0 - progress);

    // Mild reward when few bins fit the item (conserve alternatives)
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable"
    // residue classes (multiples of common small item sizes) are favored.
    let cap_frac = post_residual as f64 / bin_capacity as f64;

    // Penalize large leftover waste quadratically, but with harmonic-class relief.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Class bonus: post_residual divisible by 10 or 25 leaves "clean" slots.
    let class_bonus = if post_residual == 0 {
        12.0 // perfect fit — best possible outcome
    } else if post_residual % 25 == 0 {
        6.0
    } else if post_residual % 10 == 0 {
        4.0
    } else if post_residual % 5 == 0 {
        2.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Lookahead: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 5.0;
            if slack == 0 {
                score -= 8.0; // chain of perfect fits
            } else if slack <= 10 {
                score -= 3.0;
            }
            // harmonic match: next item aligns with residual class
            if slack % 10 == 0 { score -= 1.5; }
        } else {
            // next item cannot use this bin's leftover: penalize proportionally
            score += 0.05 * next_item_size as f64 * cap_frac;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 9.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, prefer tighter fits (smaller post_residual).
        score -= 0.5 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: empty bin gets a mild handicap so we prefer
    // reusing open bins, unless the fit is terrible or it's a perfect class fit.
    if bin_residual == bin_capacity {
        score += 10.0; // default penalty for opening a new bin
        if post_residual != 0 && post_residual % 10 != 0 && post_residual < 15 {
            score -= 12.0; // terrible leftover -> new bin is fine
        }
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 10.0; // starting fresh for a perfect chain is acceptable
        }
    }

    // Late-stream consolidation: as stream progresses, prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 3.0 * progress * cap_frac;

    // Encourage balancing residual pool: bins far above mean residual are
    // attractive targets (drain the big ones first).
    score -= 0.25 * (mean_residual - post_residual as f64).max(0.0);

    // Dead-space penalty: leftover too small for the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any item
    // (items are >= 1, but gaps below a practical threshold are hard to reuse)
    let dead_threshold = 12.0f64;
    if (post_residual as f64) < dead_threshold {
        // Quadratic penalty on unusable slivers
        score += (dead_threshold - post_residual as f64) * (dead_threshold - post_residual as f64) * 2.0;
    }

    // Reward tight fits (post_residual near zero)
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins and avoid opening new ones unless residual is large.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 * (0.5 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bin pressure
        score += 25.0 + bin_pressure * 2.0;
    } else {
        // Reward using existing bins, more so when many are open
        score -= bin_pressure * 0.8;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // this placement chains perfectly; reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size <= 5 {
            score -= 15.0;
        }
        // Penalize leaving a gap just under the next item size (near-miss dead space)
        if post_residual > 0 && post_residual < next_item_size && post_residual < dead_threshold {
            score += 10.0;
        }
    }

    // Prefer bins whose residual deviates strongly from the mean (consolidate)
    let dev = (bin_residual as f64 - mean_residual).abs();
    if bin_residual < bin_capacity && dev > 20.0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward bins whose post-residual
    // exactly accommodates the next item (perfect 2-item packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect two-item match: best possible outcome
        } else if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to tightness of the 2-step fit
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
            // extra bonus if remaining slack is small enough to stay useful
            if slack <= 10.0 {
                score -= 10.0;
            }
        } else {
            // next item cannot fit here: penalize proportionally to the gap
            let gap = (next_item_size - post_residual) as f64;
            score += 15.0 + 0.5 * gap;
        }
    }

    // Tight single-step fit bonus: minimal dead space relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    // Penalize bins that deviate from the mean residual (avoid fragmenting
    // the "healthy middle" of the residual pool).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance logic: if this is the only bin that fits, using it beats
    // opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        // but if the fit leaves a very large unusable remainder, soften it
        if post_residual > 50 && next_item_size > post_residual {
            score += 20.0;
        }
    }

    // New-bin candidate handling: an empty bin is a fallback. Prefer it only
    // when no open bin offers a good (tight) fit. Penalize it mildly so that
    // decent fits in open bins win, but keep it below badly fragmented bins.
    if bin_residual == bin_capacity {
        score += 12.0;
        // early in the stream, opening bins is cheap and often good
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 15.0 * (1.0 - progress);
    }

    // Late in the stream, squeeze existing bins harder before opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual != bin_capacity {
        score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);
    }

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac * bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item can't fit in the post-residual,
    // but reward if it fits snugly (chaining placements).
    if next_item_size > 0 {
        if next_item_size > post_residual {
            score += 3.0 * (next_item_size - post_residual) as f64;
        } else {
            let gap = post_residual - next_item_size;
            score -= 4.0;
            score += 0.15 * gap as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening new bins when many bins are already open and fragmented.
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline cost of a fresh bin plus fragmentation pressure.
        score += 20.0;
        score += 2.0 * open_bins_count as f64;
        // Late in the stream, avoid opening new bins unless residual is hopeless.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 * progress;
        // If existing mean residual can accommodate the item comfortably, discourage new bin.
        if mean_residual > item_size as f64 + 5.0 {
            score += 10.0;
        }
    } else {
        // Existing bin: slight reward when its residual is below average (tight bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 2.0;
        }
        // Early stream: be lenient about spreading load; late stream: pack tightly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress) * (item_size as f64 / bin_capacity as f64);
    }

    // Discourage leaving small unusable slivers (< smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: penalize post residual, smoothed by polynomial shaping
    let mut score = norm_pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Non-linear coupling: post residual matters more early (keep bins flexible),
    // tight fits matter more late (pack densely as stream ends)
    let tightness = 1.0 - norm_pr;
    score -= 2.0 * tightness * tightness * (0.5 + progress);

    // Reward near-perfect fills with smooth cubic falloff
    let perfect = (norm_pr * (1.0 - norm_pr) * 4.0).powi(3);
    score -= 1.5 * perfect;

    // Lookahead coupling: penalize if post residual can't fit next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let gap = norm_pr - nx;
        let sig = 1.0 / (1.0 + (-8.0 * gap).exp());
        score += 1.2 * sig * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer this bin if it's the only fitting one
    if fitting_bins_count == 1 {
        score -= 3.0 * (1.0 - progress * 0.3);
    }

    // Mild penalty for many open bins with high mean residual (fragmentation)
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * (mean_residual / cap);

    // New-bin candidate: make it attractive only when residual space is unusable
    if bin_residual == bin_capacity {
        score = cap - 0.5 + 4.0 * tightness * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by 10 are "harmonic"
    // (more likely to be exactly filled by future items from a 1..100 stream).
    let pr = post_residual;
    let harmonic = if pr == 0 { 0.0 }
        else if pr % 10 == 0 { -6.0 }
        else if pr % 5 == 0 { -2.0 }
        else { 0.0 };
    score += harmonic;

    // Dead-space penalty for small unusable residues (below min item size).
    if pr > 0 && pr < 10 {
        score += 25.0;
    }

    // Perfect fit is golden.
    if pr == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            // next item fits: reward proportional to how harmonic the new residue is
            let nr = pr - next_item_size;
            if nr % 10 == 0 { score -= 8.0; }
            if nr == 0 { score -= 15.0; }
        } else {
            // next item cannot use this residue: penalize large leftover
            score += (next_item_size - pr).min(20) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when existing bins
    // would leave badly non-harmonic residues, or when the open-bin pool is bloated.
    if bin_residual == bin_capacity {
        // base penalty so new bins are used only when clearly better
        score += 15.0;
        if open_bins_count as f64 > mean_residual.max(1.0) * 0.5 + 2.0 {
            score += 5.0;
        }
        // a fresh bin is attractive if the item is large relative to capacity
        let frac = item_size as f64 / cap;
        if frac > 0.6 { score -= 12.0; }
    } else {
        // favor tighter fits among open bins: reward small post_residual
        score -= (cap - post_residual as f64) * 0.05;
    }

    // Progress modulation: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 3.0;
    score += (post_residual as f64 - mean_residual) * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

