    // on large leftover space so that "just barely fits" is strongly favored.
    score += 0.35 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Lookahead: penalize residuals that cannot host the next item (dead space),
    // reward residuals that can host it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (next_item_size as f64 / bin_capacity as f64);
        } else {
            score += 5.0 + 0.25 * post_residual as f64;
        }
    }

    // Last-chance: if this is the only fitting bin, heavily favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: discourage spreading items; prefer consolidating into
    // bins with already-small residuals (fill-to-close behavior).
    if open_bins_count > 4 {
        score += 0.10 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);
    }

    // Global mean residual coupling: a bin whose residual is below the mean
    // is "tighter" than average; reward filling tight bins further.
    let bin_res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let tightness = (mean_residual - bin_res_f) / bin_capacity as f64;
        score -= 6.0 * tightness;
    }

    // Time horizon: early in the stream, allow more exploratory packing
    // (mild preference for new bins to keep flexibility); late in the stream,
    // aggressively minimize leftover space since future payoff is limited.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.5 * (1.0 - progress);

    // New-bin candidate: penalize opening a new bin unless the current item
