        score += fit_gap * cap * 0.6 * (0.5 + progress);
        if nxt <= pr {
            score -= 15.0 * (1.0 - fit_gap);
        }
    }

    // Mean residual coupling: prefer bins deviating from the mean toward tight fits.
    score += (mean_residual - pr).abs() * 0.3 * (1.0 - progress);

    // Mild new-bin avoidance pressure scaled with open bins.
    if bin_residual == bin_capacity {
        score += 12.0 + 3.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill (0), perfect-halves (50),
    // and small residues divisible by common item sizes are valuable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit — ideal
    } else {
        // dead-space class: residue too small for the smallest plausible item
        if pr < 10 {
            score += 40.0 * (10 - pr) as f64 / 10.0;
        }
        // residues that are multiples of 25 or 20 pair well with common sizes
        if pr % 25 == 0 { score -= 12.0; }
        if pr % 20 == 0 { score -= 8.0; }
        if pr % 10 == 0 { score -= 4.0; }
        // odd/prime-ish residues are dead weight
        if pr % 2 == 1 { score += 3.0; }
        if pr % 5 != 0 && pr % 2 != 0 && pr % 3 != 0 { score += 5.0; }
    }

    // Lookahead coupling: does post_residual exactly fit the next item?
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 35.0; // chain-friendly exact match
        } else if pr >= next_item_size {
            let slack = (pr - next_item_size) as f64;
            score -= 14.0 * (1.0 - slack / cap).max(0.0);
            // harmonic class of leftover after next item
            let after = pr - next_item_size;
            if after % 25 == 0 || after == 0 { score -= 6.0; }
        } else {
            // next item cannot use this residue: penalize proportionally
            let gap = (next_item_size - pr) as f64;
            score += 10.0 + 20.0 * (gap / cap);
        }
    } else {
        // last item: prefer tightest packing, weight small residuals heavily
        score = score * 1.5;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad
    if bin_residual == bin_capacity {
        // fresh bin: baseline attractive, but not when a tight fit exists elsewhere
        score = cap * 0.45;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0; // new bin can chain large items
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative — must open
        }
    }

    // Fractional-capacity harmonic tiers on post_residual
    let frac = post_residual as f64 / cap;
    if frac <= 0.05 { score -= 10.0; }
    else if frac <= 0.15 { score -= 5.0; }
    else if frac >= 0.75 { score += 6.0; } // large leftover wastes a bin slot

    // Early stream: keep bins balanced; late stream: squeeze hard
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * (post_residual as f64 - mean_residual).abs() * 0.3;
    score += progress * post_residual as f64 * 0.15;

    // Mild preference for consolidating into fewer bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero post_residuals are unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fill is ideal.
        score -= 60.0;
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * fill;

    // Reward residuals that can still host the next item (lookahead k=2).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space relative to the next item's needs.
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // over opening new bins; the empty-bin candidate gets penalized here.
    if bin_residual == bin_capacity {
        // New-bin candidate baseline: must lose unless current bins are bad.
        score += 35.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin is flexible for lookahead
        }
    } else {
        // Existing-bin bonus grows with open bin count (consolidation pressure).
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins below the mean residual (i.e., fuller bins) to compact load.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, be slightly more willing to open bins for flexibility.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
