pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: prefer small post residual (tight fit), with non-linear shaping
    let mut score = pr as f64;

    // Smooth non-linear polynomial coupling with stream progress:
    // early on, prefer leaving mid-size space (x around 0.3-0.5); late, prefer very tight fits.
    let target = 0.45 - 0.30 * progress;
    let dev = x - target;
    score += 120.0 * dev * dev;

    // Reward near-perfect fits strongly, smoothly (quartic in x)
    score -= 60.0 * (1.0 - x) * (1.0 - x) * (1.0 - x) * (1.0 - x);

    // Penalize large dead space non-linearly, more so late in the stream
    score += 40.0 * x * x * (0.5 + progress);

    // Lookahead coupling: if next item fits in post residual, reward smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let slack = x - nx;
        if slack >= 0.0 {
            score -= 25.0 * slack * (1.0 - slack) * (1.0 + progress);
        } else {
            score += 15.0 * (-slack) * (-slack) * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0 * (1.0 - x) * (1.0 + progress);
    }

    // Mean-residual divergence penalty: keep bin residuals balanced smoothly
    let md = (x * cap - mean_residual) / cap;
    score += 10.0 * md * md;

    // Mild penalty for many open bins to discourage fragmentation
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: squared residual pressure
    let tight = 1.0 - (post_residual as f64) / cap;
    score -= 40.0 * tight * tight;

    // Harmonic class of post_residual: perfect fits (0) and residual classes
    // that pair well with common item sizes get bonuses.
    if post_residual == 0 {
        score -= 60.0; // perfect closure
    } else {
        let pr = post_residual;
        // Class A: residual in [1..=10] -> near-dead space, penalize mildly
        if pr <= 10 {
            score += 8.0;
        }
        // Class B: residual in harmonic bands matching typical item sizes
        let band = pr / 10; // integer division: 0..10 harmonic classes
        match band {
            1 => score -= 10.0,  // 11-20: fits small items
            2 => score -= 6.0,   // 21-30
            3 => score -= 4.0,   // 31-40
            4 => score -= 2.0,   // 41-50
            _ => {}              // 51+: large residual, no bonus
        }
        // Modulo-5 structure: residuals divisible by 5 pair with 5-multiples
        if pr % 5 == 0 {
            score -= 3.0;
        }
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // next item fits exactly-ish: strong reward
            let gap = post_residual - next_item_size;
            score -= 25.0 - 0.5 * gap as f64;
            if gap == 0 {
                score -= 30.0; // chain closure
            }
        } else {
            // next item won't fit here: penalize creating stranded residual
            let waste = post_residual as f64;
            score += 0.15 * waste;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        let avg_fit = (mean_residual - item_size as f64).max(0.0);
        let pressure = avg_fit / cap; // high when open bins have big residuals
        let early = (step_index as f64) / (total_items.max(1) as f64);
        // Early on, opening bins is cheap; late, prefer filling existing bins
        score += 55.0 - 40.0 * pressure - 20.0 * (1.0 - early);
        // If next item is huge, a fresh bin is safer
        if next_item_size >= 60 {
            score -= 10.0;
        }
    } else {
        // Existing bin: reward keeping bins balanced with mean residual
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Prefer consolidating into fewer bins when many are open
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual below the minimum item size (1) is pure waste; residual in
    // the 1..=9 band is "nearly dead" since typical items are larger.
    if post_residual == 0 {
        score -= 40.0; // perfect fit: ideal
    } else if post_residual < 10 {
        // dead space band: the smaller the gap, the more wasted the bin
        score += (10 - post_residual) as f64 * 6.0;
    } else {
        // larger gaps: mildly prefer larger leftovers (more reusable)
        score += 8.0 - (post_residual as f64).min(30.0) * 0.1;
    }

    // Tightness reward: fraction of the item that matches the residual exactly.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Lookahead (k=2): if the next item fits the post residual, reward;
    // if not, penalize leaving a gap that blocks the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
        } else if post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // favor filling existing bins to allow bin consolidation.
    score += (open_bins_count as f64) * 1.5;

    // Mean residual coupling: prefer bins whose residual is close to the mean
    // (keeps the bin pool homogeneous and predictable).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Stream progression: early on, be picky (penalize mediocre fits less
    // aggressively later when consolidation matters more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 5.0;

    // New-bin candidate: an empty bin should only win when no open bin fits
    // well; penalize it so poor fits in open bins are preferred over waste.
    if bin_residual == bin_capacity {
        score += 18.0 + (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base weight on post residual (tight fits preferred).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward exact/near match of next item into post_residual.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual >= next_item_size {
            // next item fits here afterwards: reward closeness to perfect chaining
            score -= (bin_capacity as f64 - gap) * 0.9;
            if gap == 0.0 {
                score -= 40.0; // perfect two-item chain
            }
        } else {
            // next item cannot follow into this bin: penalize leftover dead space
            let dead = post_residual as f64;
            score += dead * 0.35;
            // extra penalty if dead space is too small for typical items (unusable)
            if dead < 10.0 {
                score += 25.0;
            }
        }
    }

    // Compare against mean residual: placing into a bin with residual near mean keeps diversity,
    // but bins with much larger residual than mean are good candidates to fill down.
    let res = bin_residual as f64;
    if res > mean_residual + 20.0 {
        score -= 8.0; // prefer draining large-residual bins
    } else if res < mean_residual - 20.0 {
        score += 5.0; // avoid making tiny residuals tinier
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin should only win when no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // neutral-ish baseline; slight penalty so good existing fits win
        score += 5.0;
        // but if many open bins are already fragmented, opening fresh is fine
        if open_bins_count > 0 && mean_residual < 15.0 {
            score -= 20.0;
        }
        // early stream: prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 3.0;
    }

    // Mild preference to keep number of open bins low when many are open.
    if open_bins_count > 8 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    // Items are >= 1; if post_residual is tiny but nonzero, it's wasted space.
    if post_residual > 0 {
        let waste = (post_residual as f64) / (bin_capacity as f64);
        score += 20.0 * waste * waste * waste;
    }
    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // Next item won't fit here; penalize leaving awkward residual.
            score += 4.0;
        }
        // Reward leaving exactly room for next item (chain fit).
        if post_residual == next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than opening new ones.
    let open_pressure = (open_bins_count as f64) / (1.0 + (total_items as f64) * 0.05);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize opening a new bin, scaled by open pressure.
        score += 10.0 + 20.0 * open_pressure;
        // But if no existing bin fits well (post_residual large relative to residual),
        // the penalty above competes naturally; add mild bonus for fresh bin early in stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // Global residual balance: prefer bins whose residual is below mean
    // (fill fuller bins first, keep emptier bins flexible).
    if bin_residual as f64 > mean_residual {
        score += 3.0 * ((bin_residual as f64) - mean_residual) / (bin_capacity as f64);
    } else {
        score -= 2.0 * (mean_residual - bin_residual as f64) / (bin_capacity as f64);
    }

    // Time-horizon modulation: later in the stream, be more aggressive about
    // closing bins tightly (reward filling any residual).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    // Slight preference for bins with residual close to item_size (best-fit core).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
