    let mut score = pr + 40.0 * pr_norm * pr_norm + 25.0 * pr_norm * pr_norm * pr_norm;

    // Stream-progress coupling: later in the stream, residual waste matters more
    score *= 1.0 + 0.6 * progress * (1.0 - progress) * 2.0;

    // Reward tight fits: subtract when post_residual is small relative to capacity
    let tightness = 1.0 - pr_norm;
    score -= 30.0 * tightness * tightness;

