    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let fit_frac = next_item_size as f64 / cap;
        score -= 12.0 * (1.0 - (pr_norm - fit_frac)) * (1.0 - fit_frac);
    } else if next_item_size > 0 {
        // penalize leaving residual that cannot host the next item
        score += 8.0 * pr_norm * (1.0 - progress);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * progress;
    }

    // Mean-residual coupling: prefer bins deviating below mean residual (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    // Slight penalty for proliferation of open bins
    score += open_bins_count as f64 * 0.15;

    // New-bin candidate: make empty bins moderately attractive only for large items
    if bin_residual == bin_capacity {
        score += 10.0 - 10.0 * (item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
