    let pr = post_residual as i64;
    if pr > 0 && pr < 10 {
        score += 25.0; // dead-space penalty
    }
    // Modulo-10 classes: residuals that are multiples of 10 align with common item sizes
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size < post_residual {
            let waste = post_residual - next_item_size;
            // harmonic class on waste after next item
            if waste < 10 {
                score += 12.0;
            } else if waste % 10 == 0 {
                score -= 6.0;
            }
            score += (waste as f64) * 0.15;
        } else {
            // next item won't fit here: mild penalty, this bin closes anyway
            score += 4.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base penalty to prefer existing bins
        score += 30.0;
        // but if existing fit leaves awkward residue, new bin becomes attractive
        if post_residual > 0 && post_residual < 10 {
            score -= 35.0;
        }
        // early in stream, or many open bins with high mean residual: prefer reusing
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * (1.0 - progress);
        score += (open_bins_count as f64).min(10.0);
        // if mean residual is large, open bins are underused -> penalize new bin
        score += (mean_residual - 20.0).max(0.0) * 0.5;
    }

    // Mild penalty for very large item in nearly-full bin creating fragmentation
    if item_size as f64 > 0.6 * cap && post_residual > 20 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
