    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A post_residual is "dead" if it cannot hold the next item (or any typical item).
    let min_item = 1u32.max(next_item_size.min(100));
    if post_residual > 0 && post_residual < min_item {
        score += 25.0; // pure dead space created
    }
    // Dead space relative to next item: gap that wastes capacity for the lookahead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 0.6 * gap;
    }

    // Reward leaving room exactly for the next item (perfect lookahead pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }
    // Reward residuals that can still accommodate the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bins pressure: when many bins are open, discourage spreading into new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure; only attractive when
        // existing bins would create bad fits (their scores carry dead-space penalties).
        score += 30.0 + 4.0 * pressure;
        // Slightly cheaper to open a bin early when mean residual is already low.
        score -= 0.05 * mean_residual;
    } else {
        // Mild penalty for using bins with large residual spread from mean (imbalance).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.03 * dev;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fit (small post_residual) — already captured by post_residual.

    // Aggressive 2-step lookahead: reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        if (post_residual as u32) == next_item_size {
            // Perfect chain: next item exactly consumes the leftover.
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item fits: reward proportional to how much it consumes.
            let consumed_ratio = ni / pr;
            score -= 25.0 * consumed_ratio;
            // Penalize the leftover-after-next to push toward exact chaining.
            let leftover_after_next = pr - ni;
            score += 0.35 * leftover_after_next;
        } else {
            // Next item cannot fit here: this residual is dead space relative to lookahead.
            score += 0.25 * (ni - pr);
        }

        // Coupling with mean residual: if this bin's post residual is below mean,
        // it is a compact bin — favor it; above mean — penalize fragmentation.
        score += 0.5 * (pr - mean_residual);

        // If no open bin can fit the next item, keep some bins with large residuals:
        // penalize creating a small residual when the stream may need big slots.
        let fits_next = next_item_size <= post_residual;
        if !fits_next && post_residual < next_item_size {
            score += 5.0;
        }
    } else {
        // Last item: simply minimize waste beyond tightness.
        score += 0.1 * post_residual as f64;
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has post_residual = C - item.
    // Only prefer it when the item is large (poor fit candidates elsewhere) or
    // when no open bin offers a decent chain with the next item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin mildly; tight fits in existing bins should win.
        score += 30.0;
        // But if the item is large relative to capacity, a fresh bin is fine.
        let large_item = (item_size as f64) / (bin_capacity as f64) > 0.6;
        if large_item {
            score -= 20.0;
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 15.0 * (1.0 - progress);
    }

    // Fragmentation guard: penalize residuals that are too small to be useful
    // for typical items (below the minimum item size of the stream).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Mild preference for consolidating into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus (residual exactly consumed).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if the next item exactly fits the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            // next item fits: mildly reward leaving usable space
            let next_fit = next_item_size as f64 / post_residual.max(1) as f64;
            score -= 12.0 * next_fit;
        } else {
            // next item won't fit in leftover: penalize dead space proportional to waste
            let waste = (next_item_size - post_residual) as f64;
            score += 0.25 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: empty bin starts from post_residual = capacity - item.
    // Penalize opening a new bin unless it's genuinely better than squeezing.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin, reduced when few bins are open (early stream)
        // or when no open bin fits well.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut new_bin_cost = 40.0 + 30.0 * progress;
        // If other bins fit poorly (large mean residual vs item), opening new bin
        // becomes more attractive.
        if fitting_bins_count > 0 {
            let avg_gap = (mean_residual - item_size as f64).abs();
            if avg_gap > 30.0 {
                new_bin_cost -= 25.0;
            }
        }
        // Reward new bin when next item pairs well with the item just placed.
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            new_bin_cost -= 20.0;
        }
        score += new_bin_cost;
    } else {
        // Open-bin preference: slight bias toward already-open bins.
        score -= 5.0;
        // Prefer bins with smaller residuals among fitting bins (best-fit flavor),
        // scaled by how many alternatives exist.
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score -= 8.0 * scarcity * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;
        // Penalize leaving very small, hard-to-use slivers unless next item matches.
        if post_residual > 0 && post_residual < 10 {
            if next_item_size == 0 || next_item_size > post_residual {
                score += 15.0;
            }
        }
    }

    // Global state coupling: many open bins with high mean residual -> consolidate.
    if open_bins_count > 3 && mean_residual > 50.0 {
        score += 0.08 * mean_residual;
    }

    // Time horizon: late in the stream, avoid opening new bins even more.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        if bin_residual == bin_capacity {
            score += 20.0 * progress * progress;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer small post residual (tight fit), with non-linear sharpening.
    let mut score = post * (1.0 + 0.8 * progress);

    // Quadratic coupling: dead space becomes more costly as the stream progresses.
    score += 0.004 * post * post / cap;

    // Perfect-fit reward (smooth, non-linear).
    score -= 12.0 * (1.0 - post / cap).powf(8.0);

    // Lookahead: penalize if the next item cannot use this residual.
    if next_item_size > 0 {
        let gap = post - next_item_size as f64;
        if gap < 0.0 {
            score += 6.0 * (-gap) / cap * (0.5 + progress);
        } else {
            score -= 2.0 * (gap / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 * (0.5 + 0.5 * progress);
    }

    // Penalize crowding when many bins are open but residual is wasted.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * (post / cap);

    // Mean residual coupling: if this bin is far above the mean residual, mildly discourage.
    score += 0.15 * ((post - mean_residual) / cap).abs();

    // New-bin candidate: make it attractive only when no existing bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with decent fit win; relax as stream progresses.
        let mut new_bin_score = cap * 0.9 + 20.0 * progress;
        if next_item_size > 0 {
            // A fresh bin is attractive if it can host the next item too.
            if next_item_size as f64 <= cap - item_size as f64 {
                new_bin_score -= 25.0;
            }
        }
        if fitting_bins_count == 1 {
            new_bin_score += 30.0; // don't abandon the only fitting bin
        }
        score = score.min(new_bin_score) + new_bin_score * 0.5;
        return new_bin_score.max(score.min(new_bin_score));
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity fraction band does it land in?
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize residuals in "dead zones": too small to fit small items (1..10) is fine,
    // but residuals in (0, 10) that can't hold min item are pure waste unless ~0.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Harmonic band penalty: residuals just above common item sizes are awkward.
    // Classify by integer division thresholds on post_residual.
    let band = post_residual / 10; // 0..10 harmonic class
    score += match band {
        0 => 20.0,                       // 0..9: dead space
        1 => 12.0,                       // 10..19: only tiny items fit
        2 => 6.0,                        // 20..29
        3 => 2.0,                        // 30..39
        4 => 0.0,                        // 40..49: versatile
        5 => -2.0,                       // 50..59: half-bin, good
        6 => 0.0,
        7 => 2.0,
        8 => 5.0,
        9 => 8.0,
        _ => -5.0,                       // full bin: excellent
    };

    // Reward tight fits (small post_residual) non-linearly.
    score -= (1.0 - frac) * (1.0 - frac) * 15.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size < post_residual {
            // residual after the lookahead pair
            let pr2 = post_residual as f64 - next_item_size as f64;
            score -= (pr2 / cap) * 10.0;
            if pr2 == 0.0 {
                score -= 30.0;
            }
        } else {
            // next item won't fit here: residual becomes stranded longer; mild penalty
            score += 4.0;
            // modulo harmonic: does post_residual share a divisor class with next item?
            if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
                score -= 3.0; // divisible class: future multiples may combine
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: make it moderately attractive only when open bins are crowded.
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64;
        let avg_tightness = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        // new bin baseline: its residual equals capacity (frac = 1) so tight-fit term helps;
        // add penalty that shrinks as existing bins get full or numerous.
        score += 18.0 - avg_tightness * 20.0 - (crowd / (crowd + 4.0)) * 10.0;
        // early stream: slightly prefer consolidating into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += (1.0 - progress) * 8.0;
        // if lookahead is huge, a fresh bin is valuable
        if next_item_size >= 60 {
            score -= 10.0;
        }
    }

    // Mean-residual harmony: prefer bins close to the mean residual (balanced packing),
    // penalize outliers, scaled mildly.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (dev / cap) * 6.0;

    // Modulo-5 harmonic class of item_size vs post_residual alignment.
    if post_residual > 0 && item_size % 5 == 0 && post_residual % 5 == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible future item (<= ~10) are pure waste. Penalize
    // quadratically the "unusable fraction" of the post residual.
    let unusable_threshold = 10.0f64;
    if (post_residual as f64) < unusable_threshold {
        score += 40.0 * (unusable_threshold - post_residual as f64);
    }

    // Penalize mid-range dead space (too small for medium items, too big to ignore)
    // using a bump centered around residual ~ 25..40.
    let pr = post_residual as f64;
    let bump = ((pr - 32.0) / 20.0).powi(2);
    if pr > 0.0 && pr < 55.0 {
        score += 12.0 * (-bump).exp();
    }

    // Reward tight fits (small post residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; slightly penalize leaving this bin stranded.
            score += 5.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading; with few bins, opening new ones is cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
    score += 3.0 * pressure * (0.5 + 0.5 * progress);

    // New-bin candidate: only attractive when existing residuals are large
    // (i.e., current bins are poor fits) or nothing else fits well.
    if bin_residual == bin_capacity {
        let base = 55.0;
        let spread_bonus = (mean_residual - pr.min(mean_residual)).abs() * 0.2;
        score = base + spread_bonus + 0.5 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact match between post_residual and next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64).max(0.0);

        // Perfect chain: item fills bin, next item fills remainder exactly.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Next item cannot fit in the remainder: dead space unless near-zero.
        if next_item_size > post_residual {
            if post_residual < 10 {
                score -= 25.0; // tiny waste is fine (near-perfect packing)
            } else {
                score += 0.5 * (post_residual as f64 - (bin_capacity as f64 - next_item_size as f64)).max(0.0);
            }
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 20.0;
    }

    // Relative-to-mean coupling: bins with residual well above mean are good targets;
    // avoid leaving this bin far below mean (fragmenting small residuals).
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 0.3 * (mean_residual - pr).max(0.0);
        score -= 0.15 * (pr - mean_residual).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as i64 - next_item_size as i64).abs() as f64
        } else {
            0.0
        };
        // Penalize opening new bins early in the stream; allow later when open bins are fragmented.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 60.0 * (1.0 - progress) - 0.2 * open_bins_count as f64;
        if next_item_size == 0 {
            score += 50.0; // never open a bin for the last item
        }
        if poor_fit < 5.0 && next_item_size > 0 {
            score -= 20.0; // a fresh bin pairs perfectly with the next item
        }
    }

    // Prefer filling fuller bins overall (best-fit flavor with lookahead bias).
    score -= 0.1 * (bin_residual as f64 - item_size as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that no typical next item could use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable slivers
    }

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain fit
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 2.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing bins fit poorly or there are many open bins with fragmented space.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        let mut nb = 30.0;
        // More attractive early in the stream (plenty of future items to fill it).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        nb -= 15.0 * (1.0 - progress);
        // Less attractive when open bins are fragmented (high mean residual but poor fits).
        if mean_residual > item_size as f64 {
            nb += 10.0;
        }
        // If few bins fit the item, opening a new bin is less bad.
        if fitting_bins_count <= 1 {
            nb -= 18.0;
        }
        // Many open bins: spreading load is fine.
        nb -= (open_bins_count as f64).min(10.0);
        score += nb;
    }

    // Global state coupling: prefer filling bins whose residual deviates
    // favorably from the mean (consolidate fragmentation).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild time pressure: late in the stream, close out bins aggressively.
    score -= 5.0 * (step_index as f64 / (total_items.max(1) as f64)) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress in (0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Non-linear polynomial coupling: dead-space penalty grows quadratically with
    // progress (early on, waste is cheap; late, waste is expensive).
    let dead_space = post_residual as f64 / cap;
    score += 40.0 * dead_space * dead_space * (0.5 + p2);

    // Smooth interaction: reward tight fits (small post_residual) more strongly
    // as the stream progresses.
    let tightness = 1.0 - dead_space;
    score -= 25.0 * tightness * tightness * tightness * (0.3 + 0.7 * progress);

    // Lookahead coupling: penalize residuals that cannot accommodate the next item,
    // with a smooth sigmoid-like ramp based on how far next_item_size exceeds post_residual.
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0) / cap;
        let ramp = gap * gap / (gap * gap + 0.05);
        score += 30.0 * ramp * (0.4 + 0.6 * p2);
        // Reward residuals that exactly leave room for the next item (smooth kernel).
        let match_err = (post_residual as f64 - next_item_size as f64) / cap;
        score -= 18.0 * (-match_err * match_err / 0.01).exp() * (1.0 - progress * 0.5);
    }

    // Last-chance bin: strong smooth reward scaled by how few fitting bins exist.
    if fitting_bins_count <= 1 {
        score -= 35.0 * (1.0 - dead_space * dead_space);
    }

    // Congestion coupling: with many open bins, prefer filling existing ones
    // (penalize opening/spreading); smooth quadratic in open_bins_count.
    let congestion = open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    score += 15.0 * congestion * dead_space;
    score -= 10.0 * congestion * tightness;

    // Mean-residual anchoring: penalize bins deviating from the fleet mean
    // (keeps residual distribution balanced), smooth quadratic.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev * dev / (cap * cap) * 100.0;

    // New-bin candidate: penalize opening a fresh bin unless item is huge
    // relative to capacity (smooth polynomial gate, no piecewise constants).
    if bin_residual == bin_capacity {
        let fullness = item_size as f64 / cap;
        let gate = fullness * fullness * fullness;
        score += 20.0 * (1.0 - gate) * (0.5 + congestion);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (0) strongly rewarded,
    // tiny unusable slivers (<10) penalized heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score += 50.0;
    } else if post_residual <= 20 {
        score += 15.0;
    }

    // Class by integer division: residual buckets of size 25 (capacity quarters).
    let quarter = post_residual / 25;
    score -= match quarter {
        0 => 0.0,          // 0..24: mostly dead space
        1 => 8.0,          // 25..49: fits mid items
        2 => 12.0,         // 50..74: very reusable
        _ => 20.0,         // 75..99: excellent
    };

    // Lookahead: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // waste = post_residual - next_item_size; smaller waste is better
            score -= (post_residual - next_item_size) as f64 * 1.5;
        } else {
            // next item won't fit here; large leftover is fine, small leftover is dead space
            let leftover = post_residual;
            if leftover < next_item_size && leftover < 10 {
                score += 30.0;
            }
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: mildly penalize opening new bins early, allow it late
    // or when open bins are already crowded (mean residual low).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = (mean_residual - post_residual as f64) / bin_capacity as f64;
        score += 120.0 - 60.0 * progress - 40.0 * crowding.max(0.0);
        if post_residual == 0 { score += 25.0; } // perfect fit never beats a new bin's 0 residual
    }

    // Slight preference for tighter bins when many are open.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // ---- Strict dead space avoidance ----
    // Residuals in a small "dead zone" are almost certainly unusable by any
    // future item: every unit left there is pure waste. Penalize the depth
    // into the dead zone quadratically, so a nearly-closed bin (residual ~1)
    // is treated as worse than a bin keeping a modest, recoverable gap.
    let dead_threshold: f64 = 12.0;
    if pr > 0.0 && pr < dead_threshold {
        let depth = (dead_threshold - pr) / dead_threshold; // 0..1
        score += depth * depth * 30.0;
    }

    // Perfect closure: zero leftover is the ideal outcome.
    if post_residual == 0 {
        score -= 15.0;
    }

    // ---- open_bins_count pressure ----
    // Many open bins => fragmentation risk. Reward filling existing bins and
    // punish opening yet another one, with a saturating (log) pressure curve.
    let open_pressure = (open_bins_count as f64).ln().max(0.0);
    if is_new_bin {
        score += 5.0 + open_pressure * 8.0;
    } else {
        score -= open_pressure * 2.0;
    }

    // Last-chance bin: if this is the ONLY open bin that fits the item,
    // strongly prefer it over opening a fresh bin (keeps bin count down).
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 20.0;
    }

    // ---- Lookahead coupling (k=2) ----
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size == post_residual {
            // This placement sets up an exact fit for the next item.
            score -= 25.0;
        } else if pr > 0.0 && nxt > pr {
            // Leftover cannot host the next item: penalize proportionally to
            // how stranded the gap is relative to the incoming demand.
            score += (pr / nxt) * 3.0;
        }
    }

    // ---- Best-fit flavor vs. current fleet state ----
    // Bins tighter than the fleet mean are the "compact" ones; using them
    // first consolidates waste into few bins.
    if !is_new_bin && mean_residual > pr {
        score -= (mean_residual - pr) * 0.3;
    }

    // ---- Stream progression pressure ----
    // Late in the stream, opening new bins is increasingly costly; tighten up.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if is_new_bin {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit bonus: reward exact fills aggressively.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if next item exactly matches post_residual, strongly favor.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            // Next item also fits here: chain bonus proportional to tightness.
            let chain_tightness = next_item_size as f64 / (post_residual as f64);
            score -= 50.0 + 100.0 * chain_tightness;
        } else {
            // Next item will NOT fit here: penalize leaving residual that wastes space.
            let waste = post_residual as f64 - next_item_size as f64;
            score += 20.0 + 0.5 * waste;
        }
    }

    // Compare post_residual relative to mean residual of open bins.
    // Leaving much less than the mean residual means we are tightening a bin (good);
    // leaving much more than mean means this bin stays loose while others tighten (bad).
    let mean_gap = post_residual as f64 - mean_residual;
    score += 0.3 * mean_gap;

    // Penalize large dead space (unusable chunks) nonlinearly.
    if post_residual > 0 {
        let dead = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * dead * dead;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when no open bin is tight
    // and the item is large enough that a fresh bin is genuinely useful.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_pressure = open_bins_count as f64;
        // Base penalty for opening a new bin.
        score += 200.0;
        // But relax if the item is huge (little room elsewhere anyway) and
        // open bins are already loose (mean residual high).
        let item_frac = item_size as f64 / bin_capacity as f64;
        score -= 120.0 * item_frac * (mean_residual / bin_capacity as f64) * (1.0 + 0.5 * progress);
        // Mild relief with many open bins (consolidation pressure low).
        score -= 5.0 * open_pressure.ln().max(0.0);
    }

    // Small penalty for very tight fits that leave tiny residuals (< 10),
    // unless next item can use them (already handled above).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let residual = bin_residual as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let next = next_item_size as f64;

    // ---- NEW-BIN CANDIDATE ----
    if bin_residual == bin_capacity {
        // Base attractiveness of fresh capacity; penalize opening bins when
        // existing bins are roomy, reward when existing bins are tight.
        let mut s = 110.0
            - 0.35 * item
            + 0.9 * mean_residual
            - 4.0 * (open_bins_count as f64).ln().max(0.0)
            + 25.0 * progress;
        // If many bins already fit the item, opening a new one is wasteful.
        s += 12.0 * (fitting_bins_count as f64).min(5.0);
        // Lookahead: a fresh bin always fits the next item, mildly good.
        s -= 3.0;
        // Late in the stream, avoid proliferating bins.
        s += 30.0 * progress * progress;
        return s;
    }

    // ---- EXISTING BIN SCORING ----
    // Core: reward tight fits (small post residual) with diminishing returns.
    let mut score = post.powf(0.85);

    // Perfect-fill bonus: residual exactly consumed is ideal.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead synergy: if the leftover exactly fits the next item, big reward.
    if next > 0.0 {
        let gap = (post - next).abs();
        if gap == 0.0 {
            score -= 25.0;
        } else if post >= next {
            // leftover can host next item: reward proportionally to snugness
            score -= 12.0 * (1.0 - gap / cap);
        } else {
            // leftover too small for next item: mild penalty for dead space
            score += 0.08 * post;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0 + 0.15 * residual;
    }

    // Penalize leaving tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Prefer bins whose residual was already small (compact packing) and
    // penalize spreading across many open bins.
    score += 0.05 * (residual - item).abs();
    score += 1.5 * (open_bins_count as f64);

    // Early stream: be slightly exploratory, favor tighter fits harder later.
    score -= 8.0 * (1.0 - progress) * (1.0 - post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let prog_sq = progress * progress;

    // Base: strongly prefer tight fits (small post_residual) via non-linear coupling
    let post = post_residual as f64;
    let tight = (post / bin_capacity as f64).powi(3);
    score += tight * 40.0 * (0.5 + prog_sq);

    // Dead-space penalty: post_residual that cannot fit the lookahead item
    if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * (1.5 + 2.0 * prog_sq);
    }

    // Reward if post_residual exactly accommodates next item (perfect chaining)
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strong reward to use the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Penalize opening new bins late in the stream when a fit exists
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + 80.0 * prog_sq;
        if fitting_bins_count > 0 {
            score += 20.0 * prog_sq;
        }
    } else {
        // Mild reward for using existing bins when many are open
        score -= (open_bins_count.min(20) as f64) * 0.8;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter than average)
    score -= (mean_residual - post) * 0.4;

    // Smooth interaction: item size vs residual ratio shaping
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 12.0 * (1.0 - prog_sq * 0.5);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity divided into 10-unit classes.
    let class = post_residual / 10;
    // Small post-residual classes are good (tight fit): reward them.
    score -= match class {
        0 => 40.0,
        1 => 25.0,
        2 => 12.0,
        3 => 4.0,
        _ => 0.0,
    };

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize dead space: if next item cannot fit into post_residual,
    // the leftover is likely wasted. Modulo-style check on next item class.
    if next_item_size > post_residual && next_item_size > 0 {
        // Dead space magnitude scaled by how far next item misses.
        let miss = (next_item_size - post_residual) as f64;
        score += 8.0 + miss * 0.3;
    } else if next_item_size > 0 {
        // Next item fits: reward leaving a usable gap, especially harmonic alignment.
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 - slack * 0.15;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish score; only chosen when open bins fit poorly.
    // Base it on capacity fraction so it competes with mediocre residuals.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.55 - 10.0;
        // Late in stream, slightly discourage opening extra bins.
        if step_index as f64 / total_items.max(1) as f64 > 0.7 {
            score += 12.0;
        }
    }

    // Mild penalty for proliferation of open bins with large mean residual.
    if open_bins_count > 4 && mean_residual > 30.0 && bin_residual != bin_capacity {
        score += (mean_residual - 30.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny nonzero gaps are the worst outcome.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 60.0 * (10.0 - post_residual as f64) / 10.0;
        } else if post_residual < 20 {
            score += 25.0 * (20.0 - post_residual as f64) / 10.0;
        }
    }

    // Reward near-perfect fills.
    if post_residual == 0 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    }

    // Lookahead: if the next item fits in the post residual, this is a great chain.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0 + 0.3 * next_item_size as f64;
    }
    // If next item just barely misses, the residual is likely dead space.
    if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual && post_residual < next_item_size {
        score += 0.2 * post_residual as f64;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bin pressure: with many open bins, prefer compacting into existing ones.
    score -= 3.0 * open_bins_count as f64;

    // Prefer bins tighter than the mean residual (good fits relative to fleet).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, be more willing to open bins; late, compact hard.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when few bins open or early on.
        score -= 40.0 * (1.0 - progress) + 2.0 * (20usize.saturating_sub(open_bins_count)) as f64;
    } else {
        score -= 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: bin residual after this item exactly matches next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Penalize dead space that is too small for the next item (unusable gap).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 25.0 + 0.5 * (next_item_size - post_residual) as f64;
    }

    // Reward partial-fit of next item (leaves a gap the next item can partially use).
    if next_item_size > 0 && post_residual > next_item_size {
        score -= 0.15 * next_item_size as f64;
    }

    // Tight fits are good: small post_residual relative to capacity.
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer fuller bins relative to the mean residual across open bins.
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Late in the stream, waste matters more: extra penalty on leftover space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.2 * post_residual as f64;

    // Mild penalty when many bins are open: encourage consolidation.
    score += 0.05 * open_bins_count as f64;

    // New-bin candidate: only attractive when no tight option exists.
    if bin_residual == bin_capacity {
        score += 20.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for dead space: residuals too small for typical future items
    let dead_threshold = 15.0;
    if post_residual as f64 > 0.0 && (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 2.5;
    }

    // Reward tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 12.0;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Many open bins: discourage spreading, prefer filling existing bins
    if open_bins_count > 3 {
        let pressure = ((open_bins_count as f64).ln() + 1.0).min(3.0);
        if bin_residual != bin_capacity {
            score -= pressure * 4.0;
        } else {
            score += pressure * 6.0;
        }
    }

    // Mean residual coupling: prefer bins with residual below mean (denser bins)
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += diff * 0.3;
    }

    // Time horizon: early in stream, be picky (penalize loose fits); later, fill greedily
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * (post_residual as f64 / bin_capacity as f64) * 10.0;
    score -= progress * 5.0;

    // New-bin candidate: only attractive when current bin fits are all poor
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 > bin_capacity as f64 * 0.5;
        if poor_fit && next_item_size > 0 && next_item_size as f64 > mean_residual {
            score -= 8.0;
        } else {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let tightness = 1.0 - norm_pr; // how full the bin becomes
    let poly = tightness * tightness * (1.0 + progress * 2.0) - tightness * progress;
    score -= 30.0 * poly;

    // Penalize large dead space more than linearly (cubic term)
    score += 8.0 * norm_pr * norm_pr * norm_pr * cap;

    // Reward near-perfect fits strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0 * (1.0 - post_residual as f64 / 10.0);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: reward leaving space that still fits the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack_fit = (pr - nxt) / cap;
            score -= 10.0 * (1.0 - slack_fit) * (0.5 + progress);
        } else {
            score += 6.0 * (nxt - pr) / cap;
        }
    }

    // Slight preference for consolidating into fewer bins when many are open
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Keep new-bin option from winning unless current fit is poor
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) * (1.0 - norm_item);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals in "dead zones"
    // (very small, unusable slivers) should be penalized.
    let cap = bin_capacity as f64;
    let post_f = post_residual as f64;

    // Class 1: tiny dead space (< 10, unusable for items >= 10... but sizes
    // can be as small as 1, so weight by how "wasteful" the sliver is
    // relative to the smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0 * (1.0 - post_f / 10.0);
    }

    // Class 2: perfect / near-perfect fit -> strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Harmonic class via integer division thresholds: residuals that can
    // still host a "half bin" (50) or "quarter bin" (25) chunk are valuable.
    if post_residual >= 50 {
        score -= 8.0;
    } else if post_residual >= 25 {
        score -= 4.0;
    } else if post_residual >= 10 {
        score += 2.0; // awkward middle zone
    }

    // Modulo-arithmetic harmonic classes on post_residual.
    let m = post_residual % 10;
    if m == 0 && post_residual > 0 {
        score -= 3.0; // round residuals pair well with typical item sizes
    } else if m >= 7 {
        score += 2.5; // awkward remainder class
    }

    // Lookahead: if the next item fits exactly into the post residual,
    // this placement chains nicely.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 4.0;
            } else if gap < 10 {
                score += 2.0;
            }
        } else {
            // Next item will not fit here regardless; mild penalty for
            // leaving a large but not-quite-next-item residual.
            score += 1.5;
        }
    }

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 14.0;
        if post_residual < 10 {
            score -= 6.0; // near-perfect fill on last chance
        }
    }

    // New-bin candidate handling: only prefer a fresh bin when existing
    // residuals are on average large and this item fits poorly everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a new bin is chosen only when clearly better.
        score += 10.0;
        // If mean residual is large and this item leaves a clean residual
        // in a fresh bin, a new bin becomes attractive.
        if mean_residual > 40.0 {
            score -= 8.0;
        }
        if mean_residual > 60.0 {
            score -= 6.0;
        }
        // Early in the stream, keeping bins tidy pays off long-term.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.25 {
            score -= 4.0;
        }
        // Many open bins: discourage opening yet another one.
        if open_bins_count > 8 {
            score += 6.0 * ((open_bins_count as f64 - 8.0).min(10.0) / 10.0);
        }
    } else {
        // Reward using bins whose residual is already below the mean
        // (tightening nearly-full bins first).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Slight global pressure to keep total open bins down.
    score += 0.15 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled mildly.
    score += (post_residual as f64 / bin_capacity as f64) * 20.0;

    // Strict dead-space avoidance: post_residual that no future item (1..=100)
    // can use is pure waste. Penalize unusable gaps quadratically.
    if post_residual > 0 {
        // smallest item is 1, so any gap >=1 is technically usable, but tiny gaps
        // (< 10) are statistically dead space under typical distributions.
        let dead = 10u32.saturating_sub(post_residual);
        score += (dead as f64) * (dead as f64) * 0.8;
    }

    // Perfect fill reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead (k=2): if the next item fits exactly in the post_residual,
    // strongly favor this placement (chain fill).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            // next item still fits afterward: mild bonus proportional to leftover.
            let after2 = post_residual - next_item_size;
            score -= 10.0 - (after2 as f64 * 0.1);
        } else {
            // next item won't fit here; penalize gaps smaller than next_item_size.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance pressure: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing
    // ones rather than opening new bins; with few open bins, new bins are cheap.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_pressure = (open_bins_count as f64).sqrt() * (2.0 + 4.0 * progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += 15.0 + open_pressure;
    } else {
        score -= open_pressure * 0.5;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is a "nearly full" bin — finishing it off is good.
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= dev * 0.4;
    } else {
        score += (-dev) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact-ish fits (very low post residual)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    }

    // 2-step lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            if gap <= 10.0 {
                score -= 35.0 - gap * 2.0;
            } else {
                // next item fits but leaves more slack: mild penalty for wasteful large gap
                score += gap * 0.15;
            }
        } else {
            // next item cannot fit here: penalize proportional to overflow amount
            let over = (next_item_size - post_residual) as f64;
            score += over * 0.5;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new empty bin unless nothing else fits well
    if bin_residual == bin_capacity {
        score += 25.0;
        // If next item is large, new bin is more attractive
        if next_item_size >= 60 {
            score -= 20.0;
        }
    }

    // Late in stream: favor tighter packing, fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    // Slight penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale down score when the item fills a large fraction of the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 0.6 * fill_ratio * (bin_residual as f64);

    // Penalize large dead space relative to typical item sizes.
    if post_residual > 0 && post_residual < 10 {
        score -= 12.0; // near-perfect fit bonus
    }

    // Lookahead: if the next item exactly fits the post-residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - gap / bin_capacity as f64);
    }
    // If next item cannot fit here, mildly penalize hoarding space it could use elsewhere.
    if next_item_size > post_residual && next_item_size > 0 {
        score += 3.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless remaining open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Open new bin when open bins are nearly full (low mean residual) or stream is ending.
        let open_bonus = if fragmentation < 0.25 { -6.0 } else { 10.0 + 8.0 * (1.0 - progress) };
        score += open_bonus + 0.05 * open_bins_count as f64;
    }

    // Slight preference for bins below mean residual (balance across bins).
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer minimal post-residual, with non-linear (quadratic) penalty growth
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, tight packing matters more (dead space compounds); later, relax slightly
    let progress_coupling = 1.0 + 0.8 * progress * (1.0 - progress) * 4.0;
    score *= progress_coupling;

    // Penalize residual that is too small for the next item (wasted lookahead space),
    // smoothly via a cubic in the shortfall ratio
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            let shortfall = (ni - pr) / cap;
            score += 60.0 * shortfall * shortfall * shortfall * cap;
        } else {
            // reward residual that can still host the next item
            let usable = (pr - ni) / cap;
            score -= 15.0 * usable * (1.0 - usable);
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0 * (1.0 - norm_pr);
    }

    // New-bin candidate handling: empty bin should lose unless the fit here is bad
    if bin_residual == bin_capacity {
        // penalize opening a new bin, more when many bins are open and mean residual is high
        score += 30.0 + 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // but smooth relief when the item would leave a very fragmented residual elsewhere:
        // the base pr for the empty bin is large (cap - item), which naturally competes.
        let fragmentation = 1.0 - ((cap - pr) / cap).powi(2);
        score -= 20.0 * fragmentation * (1.0 - progress);
    }

    // Mild penalty for deviating from mean residual: keeps residual distribution homogeneous
    let dev = (pr - mean_residual) / cap;
    score += 10.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals in the same class as
    // typical item sizes are reusable; odd/dead classes are penalized.
    let class = (post_residual % 10) as f64;
    let class_bonus = (5.0 - (class - 5.0).abs()) / 5.0; // peak at class 5 (half-cap multiples)
    score -= 2.0 * class_bonus;

    // Penalize post_residuals in dead zones: too small to fit any item (1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    // Integer-division threshold: residual usable iff post_residual/10 >= 1
    score -= 4.0 * (post_residual / 10) as f64;

    // Coupling with next item: if post_residual exactly fits next_item_size, big reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 * (post_residual as f64 - next_item_size as f64).min(10.0) / 10.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // residual too small for lookahead: mild penalty scaled by deadness
        score += 3.0 * (1.0 - post_residual as f64 / cap_f);
    }

    // Fraction of capacity filled by this placement — reward high fill
    let fill_frac = item_size as f64 / cap_f;
    score -= 8.0 * fill_frac;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate: make it unattractive unless residual would be perfectly harmonious
    if bin_residual == bin_capacity {
        score += 6.0;
        // allow new bin early in stream or when open bins are nearly full on average
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 6.0 * progress;
        score -= 4.0 * (1.0 - mean_residual / cap_f).clamp(0.0, 1.0);
    }

    // Prefer bins tighter than the mean residual (best-fit flavor with harmonic twist)
    score += 3.0 * ((bin_residual as f64 - mean_residual) / cap_f).clamp(-1.0, 1.0);

    // Modulo-25 harmonic alignment: residuals at 25/50/75 are versatile split points
    if post_residual % 25 == 0 && post_residual > 0 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead-space penalty: small post_residual gaps are often unusable
    // (items are >= 1, but small gaps waste capacity). Penalize gaps that
    // cannot fit the next item or typical small items.
    if post_residual > 0 {
        let gap_usable_for_next = next_item_size > 0 && (post_residual as u32) >= next_item_size;
        if !gap_usable_for_next {
            // Unusable gap: penalize proportionally to how much capacity is wasted
            score += 30.0 + (post_residual as f64) * 0.8;
        } else {
            // Usable gap: mild reward for leaving room for the lookahead item
            score -= 15.0;
        }
    }

    // Tight fit reward: fraction of bin used by this placement.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= fill_ratio * 50.0;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are large relative to the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        // Cheaper to open a new bin early in the stream (more items to come).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= (1.0 - progress) * 40.0;
        // Discourage new bins when many bins are already open.
        score += open_bins_count as f64 * 8.0;
        // If mean residual can comfortably fit the item, opening a new bin is wasteful.
        if mean_residual > item_size as f64 * 1.5 {
            score += 60.0;
        }
        // If no open bin fits well (large item), new bin is more acceptable.
        if item_size as f64 > mean_residual {
            score -= 50.0;
        }
    }

    // Open-bins pressure: mildly prefer bins with below-average residual
    // (consolidate waste into fewer bins).
    if bin_residual != bin_capacity {
        let diff = (bin_residual as f64) - mean_residual;
        score += diff * 0.3;
        score += open_bins_count as f64 * 0.5;
    }

    // Lookahead synergy: reward leaving exactly room for next item, penalize
    // leaving slightly-too-small gaps.
    if next_item_size > 0 {
        if post_residual as u32 == next_item_size {
            score -= 80.0;
        } else if post_residual > 0 && (post_residual as u32) < next_item_size {
            score += (next_item_size - post_residual) as f64 * 1.5;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 1000.0; // bin becomes exactly reusable
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // small slack (1..=9) is nearly a perfect match
            if slack <= 9.0 {
                score -= 60.0 - slack * 5.0;
            } else {
                // penalize leaving dead space the next item can't use
                score += slack * 0.5;
            }
        } else {
            // next item won't fit in leftover: dead space
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.8;
        }
    }

    // Reward tight fits now (small post residual) especially when scarce.
    if fitting_bins_count == 1 {
        score -= 40.0; // last chance bin: strongly prefer using it
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Relative to mean residual: prefer bins that are already tight
    let mean_gap = mean_residual - post_residual as f64;
    score -= mean_gap * 0.3;

    // New-bin candidate handling: keep it attractive only when open bins are messy
    if bin_residual == bin_capacity {
        let mess = if open_bins_count > 0 { mean_residual } else { 0.0 };
        // open new bin if existing residuals are large (poor fits available)
        score = 50.0 + mess * 0.6;
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 300.0; // fresh bin perfectly sized for next item
        }
    }

    // late-stream: consolidate more aggressively
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 6.0 * tight * tight;

    // Penalize dead space that no plausible future item can use:
    // leftover smaller than the smallest item (1) is fine, but small
    // unusable slivers relative to the next item are wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 4.0 + 0.05 * (next_item_size - post_residual) as f64;
    }

    // Lookahead harmony: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 8.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate handling: a fresh bin should only win when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
        // Early in the stream, prefer filling existing bins less strictly.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 4.0 * (1.0 - progress);
        // If next item is large, opening a fresh bin now is more attractive.
        score -= 0.03 * next_item_size as f64;
    }

    // Prefer bins whose residual is below average (consolidate fullness).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Mild preference for fewer open bins (encourage bin consolidation).
    score += 0.02 * open_bins_count as f64;

    // Slight time-decay of aggressive packing as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * (1.0 - progress) * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear waste penalty: quadratic in post_residual, damped as stream progresses
    score += 0.6 * (pr / cap) * (1.0 + pr / cap) * (1.0 - 0.5 * progress);

    // Reward tight fits: near-zero post_residual strongly favored (cubic falloff)
    let tightness = 1.0 - (pr / cap);
    score -= 15.0 * tightness * tightness * tightness;

    // Lookahead coupling: penalize residuals that cannot fit the next item
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += 0.5 * (ni - pr) * (1.0 + progress);
        } else {
            // reward leaving a gap that exactly accommodates the next item
            let gap_fit = 1.0 - ((pr - ni) / cap);
            score -= 4.0 * gap_fit * gap_fit;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0 * (1.0 - progress * 0.5);
    }

    // Compare against mean residual: bins tighter than average are preferred
    score += 0.3 * (mean_residual - pr);

    // New-bin candidate: neutral-ish baseline, slightly penalized so it's chosen
    // only when open bins offer poor fits (high post_residual / dead space)
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.2 * progress) - 10.0 * (1.0 - (mean_residual / cap).min(1.0));
        if fitting_bins_count == 1 {
            score += 25.0; // avoid opening a new bin when a sole bin still fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Base tightness reward: strongly favor minimal post_residual (best-fit core).
    let post = post_residual as f64;
    score += 8.0 * (post / cap).powi(2);

    // Harmonic class of post_residual: dead-space penalty via integer-division
    // thresholds. Residuals that cannot hold even the smallest item are pure waste.
    if post_residual < 1 {
        score -= 100.0;
    } else if post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 10.0;
    }

    // Modulo-class logic: residuals that are multiples of common item sizes
    // are "harmonic" and likely reusable; reward them.
    let harmonics: [u32; 6] = [5, 10, 20, 25, 50, 100];
    let mut harmonic_bonus = 0.0;
    for &h in &harmonics {
        if h > 0 && post_residual % h == 0 && post_residual > 0 {
            harmonic_bonus += 6.0;
        }
    }
    score -= harmonic_bonus.min(18.0);

    // Lookahead: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pairing
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // partial-harmonic: next item divides the residual nearly evenly
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 8.0;
            }
        } else {
            // next item won't fit here: penalize residuals just barely too small
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 12.0; // frustrating near-miss dead space
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is terrible
    // or the bin is nearly full anyway.
    if bin_residual == bin_capacity {
        // Brand-new bin: neutral baseline, with slight preference when many open
        // bins already exist and mean residual is low (bins are packed tight).
        score = 30.0 + 2.0 * (open_bins_count as f64).sqrt();
        if post_residual == 0 {
            score -= 50.0; // item exactly fills a fresh bin
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Discourage new bins early in the stream when open bins are loose.
        if open_bins_count > 0 && mean_residual > 30.0 {
            score += 20.0;
        }
    } else {
        // Filling an existing bin: reward keeping bins closed.
        score -= 3.0 * (bin_residual as f64 / cap);
        // Mild pressure to consolidate when many bins are open.
        score -= 0.3 * (open_bins_count as f64).ln().max(0.0);
    }

    // Exact-fill celebration.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Stream progression: late in the stream, be more conservative about waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 500.0;
    }

    // Dead-space penalty: small unusable gaps (nothing between 1 and min item can use it)
    // treat residual < 10 as dead space since items are >= 1 but tiny gaps waste capacity
    if post_residual > 0 && post_residual < 10 {
        score += 300.0;
    } else if post_residual < 25 {
        score += 120.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strongly favor
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 200.0 - (slack as f64) * 4.0;
        if slack == 0 {
            score -= 300.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // residual can't host next item: mild penalty
        score += 30.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // new-bin candidate baseline
        score = 100.0 + (open_bins_count as f64) * 5.0 + mean_residual * 0.5;
        // if few fitting bins and open bins are fragmented, opening new bin may be fine
        if fitting_bins_count == 0 {
            score -= 150.0;
        }
        // late in stream, prefer existing bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 50.0;
    }

    // Prefer bins with lower residual overall (tighter packing)
    score += (bin_residual as f64 - post_residual as f64) * 0.0; // no-op guard
    score -= mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly favor bins whose post_residual exactly matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if post_residual == next_item_size {
            score -= 500.0; // chain fit: next item fills this bin perfectly
        } else if (post_residual as u32) >= next_item_size {
            score -= (next_item_size as f64) * 0.8; // next item can still use leftover
        } else {
            // leftover too small for next item: penalize dead space, worse when tight
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // near-miss bonus
        if diff > 0 && diff <= 5 {
            score -= (6 - diff) as f64 * 10.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.6;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 300.0;
    }

    // Penalize opening a new bin when good open bins exist (new-bin candidate gets base residual = capacity)
    if bin_residual == bin_capacity {
        score += 150.0 + open_bins_count as f64 * 5.0;
    }

    // Prefer filling fuller bins early/late in stream
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (item_size as f64 / bin_capacity as f64) * (50.0 + 100.0 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Penalize dead space relative to smallest plausible item (1..100 interface).
        let dead_weight = if post_residual < 10 { 12.0 } else { 6.0 };
        score += dead_weight * (post_residual as f64 / bin_capacity as f64).powi(2);
    }

    // Lookahead: if next item fits in the post residual, big reward for keeping this bin viable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_quality = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 10.0 + 15.0 * chain_quality;
        } else {
            // Post residual cannot host next item: penalize proportionally to wasted potential.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 + 0.5 * post_residual as f64;
    }

    // New-bin candidate handling: opening a new bin is only attractive when existing
    // residuals are poor and the stream is early/mid.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let global_pressure = (mean_residual / bin_capacity as f64).powi(2);
        // Early stream with many open bins and high mean residual -> prefer spreading.
        score += 8.0;
        score -= 25.0 * progress * (1.0 - global_pressure);
        score -= 10.0 * global_pressure * (open_bins_count as f64).ln1p();
        // Never open a new bin for a tiny item when a decent fit exists elsewhere.
        if item_size < 20 {
            score += 15.0;
        }
    }

    // Mild preference for bins tighter than the current average residual (consolidation).
    score += 2.0 * (bin_residual as f64 - mean_residual) / bin_capacity as f64;

    // Late-stream consolidation: fewer open bins desired near the end.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 2.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr as f64;
    let poly = x * x * (1.0 - progress) + x * (0.5 + 0.5 * progress);
    score += 40.0 * poly;

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - x) * (1.0 - x) * (10.0 + 30.0 * progress);

    // Penalize dead space that can't fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 8.0 + 12.0 * progress;
    } else if next_item_size > 0 {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 6.0 * (1.0 - slack) * (1.0 - slack);
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Mild penalty when bin deviates from mean residual (keeps bin pool homogeneous)
    score += 0.05 * ((pr - mean_residual) * (pr - mean_residual)) / cap;

    // Slight preference to reuse open bins over opening new ones late in stream
    score += if bin_residual == bin_capacity { 5.0 + 10.0 * progress } else { 0.0 };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: residues modulo capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class 1: post_residual in [0,10) -> near-perfect fill, strong reward.
    if post_residual < 10 {
        score -= 40.0;
    }
    // Class 2: post_residual divisible by 10 (harmonic grid) -> easier future fits.
    if post_residual % 10 == 0 {
        score -= 12.0;
    }
    // Class 3: dead-zone class (post_residual in 11..=19): too small for most items.
    if post_residual >= 11 && post_residual <= 19 {
        score += 25.0;
    }
    // Class 4: mid harmonic band 40..=60: flexible for mid-size items.
    if post_residual >= 40 && post_residual <= 60 {
        score -= 8.0;
    }

    // Integer-division thresholds: quarter/half classes of capacity.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual <= quarter {
        score += 5.0; // small leftover, mildly risky
    } else if post_residual >= half {
        score -= 5.0; // roomy bin, good target
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / cap);
        } else {
            score += 10.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate: penalize proportionally to how full open bins are,
    // but allow opening when mean residual is small (bins nearly exhausted).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score = cap - 30.0 * (1.0 - progress);
        if mean_residual < item_size as f64 + 5.0 {
            score -= 10.0; // existing bins are tight; new bin is reasonable
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to fill bins with higher residual first (balance pressure).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit is extremely desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to residual (fill fraction).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill;

    // Lookahead: bonus if the next item exactly fits the post residual.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // mild bonus if next item can still fit afterwards
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // penalize leaving a gap that blocks the next item
        score += 8.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: when many bins are open, discourage opening a new bin.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as open bins grow and stream progresses.
        score += 12.0 + 2.5 * open_bins_count as f64 + 15.0 * progress;
        // Only attractive if nothing fits well: residual of this call equals capacity,
        // so the item would leave capacity - item_size behind.
        score += (bin_capacity - item_size) as f64 * 0.3;
    } else {
        // Using existing bins relieves pressure slightly.
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins with below-average residual (tighter bins fill faster).
    score -= 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead: post_residual exactly matches next item -> strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // leftover after next item would fit; prefer small leftover
            let after_next = (post_residual - next_item_size) as f64;
            score -= 12.0 - 0.15 * after_next;
        } else {
            // next item won't fit: penalize residual just below next_item_size (dead space)
            let gap = (next_item_size - post_residual) as f64;
            score += 0.25 * gap;
        }
    } else {
        // last item: minimize leftover strongly
        score += 0.5 * post_residual as f64;
    }

    // Reward tight fills relative to capacity
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill;

    // Deviation from mean residual: prefer bins that deviate (consolidate large residuals)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in stream: slightly discourage opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize unless residuals across bins are tight
        score += 5.0 + 10.0 * (1.0 - progress);
        if post_residual as f64 >= mean_residual && open_bins_count > 0 {
            score += 3.0;
        }
    }

    // Small bonus for many open bins being consolidated (reduce bin count pressure)
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Perfect fit is extremely attractive.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 15.0; // small dead space is nearly perfect
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + 8.0 * (next_item_size as f64 / 100.0);
        } else {
            // Penalize leaving a gap that the next item cannot use.
            score += 6.0 * (1.0 - post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize new-bin candidate (bin_residual == bin_capacity) mildly, so it is
    // chosen only when all open bins fit poorly.
    if bin_residual == bin_capacity {
        score += 25.0;
        // But if the item is large and nothing else fits well, opening a new bin
        // is fine: soften penalty when item consumes most of the bin.
        if item_size >= 60 {
            score -= 15.0;
        }
        // Late in the stream, avoid opening bins with tiny expected leftover use.
        let progress = step_index as f64 / (total_items as f64).max(1.0);
        score += 10.0 * progress;
    }

    // Global state coupling: when open bins have high mean residual, prefer
    // filling them rather than fragmenting space.
    if bin_residual < bin_capacity {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }

    // Mild preference to use bins with larger residuals for large items
    // (keeps small residuals available for small items).
    let size_frac = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * size_frac * (bin_residual as f64 / bin_capacity as f64);

    // Penalize creating residuals that no plausible item (>=10) can fill.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * post / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let coupling = post * (0.5 + 0.5 * (progress * std::f64::consts::PI).sin());
    score += 0.3 * coupling;

    // Penalize post_residual that is unusable for a plausible next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let usable = (post - nxt).max(0.0);
        let waste = post - usable;
        score += 0.8 * waste;
    }

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 5.0 * tightness * tightness;

    // Last-chance bin bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Slight preference for bins with residuals near the mean (balance)
    score += 0.05 * (post - mean_residual).abs();

    // Mild penalty for opening a new bin when many bins are open
    if bin_residual == bin_capacity {
        score += 3.0 + 0.02 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual classes mod 10 and mod 20.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class10 = (post_residual % 10) as f64;
    let class20 = (post_residual % 20) as f64;

    // Penalize "awkward" residual classes: small nonzero mod-10 remainders are dead space
    // that few future items (sizes 1..100) can use efficiently.
    if post_residual > 0 {
        if class10 >= 1.0 && class10 <= 3.0 {
            score += 12.0 - 2.0 * class10;
        }
        if class20 >= 11.0 && class20 <= 13.0 {
            score += 6.0;
        }
        // Perfectly reusable classes (multiples of 10) get a mild reward.
        if class10 == 0.0 && post_residual <= 50 {
            score -= 4.0;
        }
    } else {
        // Perfect fill: strongly reward closing a bin exactly.
        score -= 25.0;
    }

    // Fraction of capacity wasted after placement.
    score += 0.15 * (pr / cap) * (pr / cap) * cap;

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0; // chain fill
        } else if next_item_size <= post_residual {
            let nxt = next_item_size as f64;
            let frac = nxt / pr.max(1.0);
            // Reward high fill fraction of the leftover, penalize mid-range splits.
            if frac > 0.8 {
                score -= 10.0;
            } else if frac < 0.35 {
                score += 3.0;
            }
            // Harmonic check: post_residual - next_item_size still in a good class.
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // Next item cannot use this residual at all: dead space likely.
            score += 4.0 + 0.05 * pr;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless residual is tiny and useless).
    if fitting_bins_count == 1 {
        score -= 15.0;
        if post_residual > 0 && post_residual < 10 {
            score += 10.0; // but near-exhausted bin is fine to leave
        }
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits poorly everywhere else. Base cost of a fresh bin.
    if bin_residual == bin_capacity {
        score = 0.45 * cap + 0.3 * (open_bins_count as f64);
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
        if next_item_size > 0 && next_item_size >= (bin_capacity as u32) - item_size {
            score -= 8.0; // next item pairs well with this one in a fresh bin
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.02 * (open_bins_count as f64) * (pr / cap);

    // Progress-aware tightening: later in the stream, exact fills matter more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (10.0 - 0.1 * class10);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable small gaps are heavily penalized.
    // A residual gap is "dead" if it is too small to hold even the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 30 {
        score += 6.0;
    }

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Coupling: dead space is worse when many bins are already open (bin pressure).
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if post_residual > 0 && post_residual < 10 {
        score += 10.0 * pressure;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward this placement.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use this gap: gap is likely wasted.
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Mild bonus for tight fit relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Slight preference to keep scores comparable for the new-bin candidate:
    // an empty bin has post_residual == bin_capacity (100), giving a high base score,
    // so open bins with reasonable fits are naturally preferred.
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly fits next item -> huge reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here after placement; penalize proportionally
        let deficit = (next_item_size - post_residual) as f64;
        score += 8.0 + 0.15 * deficit;
    }

    // Reward tight fits relative to bin capacity (waste minimization)
    let waste_ratio = post_residual as f64 / cap;
    score += 20.0 * waste_ratio * waste_ratio;

    // Compare against mean residual across open bins: prefer bins with above-average residual
    // (consume the loosest bin first), leaving tight bins for small future items.
    if post_residual as f64 > mean_residual {
        score -= 0.25 * (post_residual as f64 - mean_residual).min(30.0);
    } else {
        score += 0.25 * (mean_residual - post_residual as f64).min(30.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) > 40.0; // would leave big hole in an existing bin
        if poor_fit && fitting_bins_count > 1 {
            score -= 30.0 + 10.0 * progress;
        } else {
            // discourage opening new bins otherwise
            score += 40.0 + 5.0 * open_bins_count as f64;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

