        score -= 20.0;
    }

    // Penalize post-residual that cannot hold typical small items (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Lookahead coupling: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 25.0;
        } else {
            // Penalize if leftover is close to but below next item (wasted opportunity).
            let gap = (post_residual as f64 - next_item_size as f64).abs();
            if gap < 10.0 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless few bins fit
    // or the fit into existing bins would be very poor.
    if bin_residual == bin_capacity {
        let mut penalty = 45.0;
        if fitting_bins_count == 0 {
            penalty = -50.0;
        } else if fitting_bins_count == 1 {
            penalty = 5.0;
        }
        // Late in stream, prefer reusing bins more aggressively.
        let progress = step_index as f64 / total_items.max(1) as f64;
        penalty += progress * 20.0;
        // If mean residual is large, existing bins have room; discourage new bin.
        penalty += (mean_residual / bin_capacity as f64) * 30.0;
        score += penalty;
    }

    // Mild bonus for filling bins that are already relatively full.
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Global state: many open bins -> encourage consolidation into emptier bins.
    if open_bins_count > 5 {
        score += (post_residual as f64 - mean_residual) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: waste grows superlinearly with residual, modulated by progress
    let pr_norm = pr / cap;
    score += 40.0 * pr_norm * pr_norm * (0.5 + progress);

    // Tight fit reward (smooth bell around small residuals)
    let tight = (1.0 - pr_norm).max(0.0);
    score -= 30.0 * tight * tight * tight;

    // Lookahead: penalize if post_residual can't fit next item, reward if snug
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= 12.0 * (1.0 - g * g) * (0.3 + 0.7 * progress);
        } else {
            score += 10.0 * (-gap / cap) * (1.0 + progress);
        }
    }

    // Last-resort bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - pr_norm);
    }

    // New empty bin candidate: penalize mildly, more early when consolidation matters
    if bin_residual == bin_capacity {
        score += 8.0 + 15.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // Favor bins with residual close to mean (balanced packing)
        score += 3.0 * ((pr - mean_residual) / cap).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Last chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Lookahead chaining: if the next item fits this bin's post-residual, reward
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 60.0;
        // extra reward for exact two-item packing
        if next_item_size == post_residual {
            score -= 120.0;
        }
    }

    // Harmonic classes on post_residual (modulo arithmetic):
    // residuals divisible by 10 are the most reusable classes
    if post_residual > 0 {
        let class = post_residual % 10;
        if class == 0 {
            score -= 20.0;
        } else if class == 5 {
            score -= 10.0;
        } else {
            // awkward residual classes (dead space) get penalized more the smaller they are
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Integer-division thresholds: residual quarters
    let quarter = post_residual / 25;
    match quarter {
        0 => score -= 5.0,   // very tight bin, well used
        3 => score += 0.0,
        _ => {}
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // base reluctance to open a new bin when others could fit
        score += 40.0 + 2.0 * open_bins_count as f64;
        // small items waste a fresh bin; large items leave little dead space in one
        score += (80u32.saturating_sub(item_size)) as f64 * 0.8;
        // but if item is large and would leave a small residual, fresh bin is fine
        if item_size >= 60 {
            score -= 45.0;
        }
        // near end of stream, avoid opening bins unnecessarily
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            if progress > 0.9 {
                score += 60.0;
            }
        }
        // if mean residual across open bins is high, prefer reusing them
        score += 0.3 * mean_residual;
    } else {
        // reusing an open bin: mild reward proportional to how full the bin already is
        score -= 0.2 * (cap - bin_residual as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to be useful later are dead space.
    // Treat residuals below a "usability floor" as doubly costly.
    let dead_floor = 12.0f64;
    if (post_residual as f64) < dead_floor {
        score += 3.0 * (dead_floor - post_residual as f64);
    }

    // Tight fit reward: the smaller the post_residual relative to item size, the better.
    if item_size > 0 {
        score -= 2.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Penalize wasting a large residual on a small item when many bins are open.
    let waste = bin_residual as f64 - item_size as f64;
    score += 0.05 * waste * (open_bins_count as f64).ln().max(1.0);

    // Lookahead: strongly prefer bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins.
    score += 0.3 * open_bins_count as f64;

    // New-bin candidate: only attractive when current bins fit poorly or stream is early.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_penalty = if fitting_bins_count == 0 { 0.0 } else { 10.0 };
        let pressure = 1.5 * open_bins_count as f64;
        score = 100.0 - 6.0 * mean_residual / bin_capacity as f64 - 3.0 * progress + poor_fit_penalty + pressure;
        // If the next item is large, an empty bin is valuable.
        if next_item_size > bin_capacity / 2 {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact or near-exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize small unusable dead space (nonlinear).
        let dead = post_residual as f64;
        score += 40.0 / (dead + 1.0);
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // can host the next item (chained packing).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.5 * slack;
        } else {
            // Next item won't fit here: penalize proportionally to the gap.
            let gap = (next_item_size - post_residual) as f64;
            score += 0.3 * gap;
        }
    }

    // Compare post_residual against mean residual: leaving more than
    // average behind is wasteful when other bins are roomier.
    score += 0.2 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.1 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: prefer reusing open bins unless the fit is bad.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * item_size as f64;
        // Opening a new bin is attractive if no open bin fits well
        // (post_residual small => item nearly fills a bin anyway).
        if post_residual < 10 {
            score -= 200.0;
        }
    }

    // Early in the stream, encourage keeping bins tight for future flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 0.05 * post_residual as f64;

    // Mild penalty for proliferating open bins.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fill_ratio * fill_ratio;

    // Penalize small dead space that no future item (sizes >= 1, typically >= 10) can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Lookahead coupling: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize leaving large awkward residuals
            score += 4.0 * (post_residual as f64 / cap);
        }
    } else {
        // Last item: just minimize leftover.
        score += 2.0 * (post_residual as f64 / cap);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * fill_ratio;
    }

    // Many open bins: encourage closing out nearly-full bins to reduce spread.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap.max(1.0));
    score -= 0.5 * pressure * (1.0 - post_residual as f64 / cap);

    // Time horizon: early in the stream, be slightly more willing to spread load
    // (keeps flexibility); late in the stream, pack tight.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 6.0 * (1.0 - progress) * (post_residual as f64 / cap);

    // New-bin candidate: default penalty so we only open a new bin when the fit
    // into every open bin would be bad, or when flexibility is still cheap.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early stream: opening bins is cheaper (exploration discount).
        score -= 12.0 * (1.0 - progress);
        // If a large item wastes a nearly fresh bin's generality, discourage.
        if item_size > bin_capacity / 2 {
            score += 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_post = post / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = post * (1.0 + 0.6 * progress * progress);

    // Penalize dead space more as stream advances (smooth cubic term)
    let dead = norm_post * norm_post * norm_post * (20.0 + 40.0 * progress);

    // Reward tight fits smoothly: subtract for small post_residual
    let tight = -30.0 * (1.0 - norm_post) * (1.0 - norm_post);

    // Last-chance bin bonus (smooth, not piecewise)
    let last_chance = if fitting_bins_count == 1 { -25.0 * (1.0 - progress) } else { 0.0 };

    // Lookahead coupling: penalize if next item cannot use the post residual
    let lookahead = if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (n - post).max(0.0) / cap;
        15.0 * gap * gap - 10.0 * (1.0 - (n - post).abs() / cap)
    } else { 0.0 };

    // Mild penalty for spreading across many open bins
    let spread = 0.3 * open_bins_count as f64 * norm_post;

    // Mean residual interaction
    let mean_term = 0.2 * (mean_residual - post);

    base + dead + tight + last_chance + lookahead + spread + mean_term
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: reward residuals that fall into
    // "likely fillable" classes via integer-division thresholds (mod 10 buckets).
    let cls = post_residual / 10;
    let class_bonus: f64 = match cls {
        0 => 14.0,   // near-perfect fit, tiny dead space
        1 => 6.0,
        2 => 2.5,
        3 => 0.0,
        4 => -1.5,
        5 => -2.5,
        6 => -3.0,
        _ => -3.5,   // large leftover: penalize less since it may host small items
    };
    score -= class_bonus;

    // Exact-fit detection
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead coupling: does the leftover fit the next item's harmonic class?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            // leftover can host next item: reward, scaled by tightness
            let tight = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - tight / cap);
            // harmonic alignment: leftover mod 10 close to next size mod 10
            let lm = (post_residual % 10) as f64;
            let nm = (next_item_size % 10) as f64;
            let align = (lm - nm).abs();
            score -= 2.0 * (1.0 - align / 10.0);
        } else {
            // leftover too small for next item: dead-space penalty grows with residual
            score += 3.0 + post / cap * 6.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score = cap - 5.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // forced open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 6.0; // fresh bin useful for upcoming larger items
        }
        if open_bins_count > 6 {
            score += 4.0; // discourage bin sprawl
        }
        // early stream: be more willing to open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 5.0 * (1.0 - progress);
    }

    // Mild pressure toward bins with residual close to mean (balance load)
    score += 0.05 * (post - mean_residual).abs();

    // Prefer filling emptier bins when many bins are open
    score += 0.02 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

