    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate logic: opening a new bin wastes the residual of this empty bin.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 10.0;
        // More costly to open new bins when many bins are already open.
        score += 0.5 * open_bins_count as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
        // If the item fits poorly anywhere (large item, few fitting bins), opening
        // a fresh bin is more attractive.
        if fitting_bins_count <= 1 {
            score -= 18.0;
        }
        // If mean residual across open bins is small, open bins are nearly full,
        // so a new bin is reasonable.
        if mean_residual < item_size as f64 + 5.0 {
            score -= 10.0;
        }
    } else {
        // Reward using bins whose residual is above the mean (consume slack where it is).
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    // Mild global pressure: with many open bins, favor filling existing ones.
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 8.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (10.0 + 20.0 * progress);

    // Dead-space penalty: very small post_residual that can't fit typical next items
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr < ni {
            score += (ni - pr) / cap * (15.0 + 25.0 * progress);
        } else {
            score -= 3.0 * (1.0 - (ni / pr).min(1.0)) * (0.5 + progress);
        }
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0 + 10.0 * progress;
    }

    // Mild penalty for many open bins relative to stream progress
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * (1.0 - progress);

    // New-bin candidate: penalize slightly unless current bin is a poor fit
    if bin_residual == bin_capacity {
        let waste = (bin_residual - item_size) as f64 / cap;
        score += 6.0 - 8.0 * (1.0 - waste) * (1.0 - progress);
    }

    // Interaction with mean residual across open bins
    score += 0.05 * (mean_residual - pr) * (0.5 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: classify leftover space into
    // capacity fractions (halves, thirds, quarters) and reward residues
    // that fall into "reusable" harmonic classes.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity remaining

    // Reward post-residuals near harmonic fractions (1/2, 1/3, 1/4, 3/4)
    let harmonics = [0.5f64, 1.0 / 3.0, 0.25, 0.75, 2.0 / 3.0];
    let mut harm_bonus = 0.0f64;
    for h in harmonics.iter() {
        let d = (frac - h).abs();
        if d < 0.08 {
            harm_bonus += (0.08 - d) * 60.0;
        }
    }
    score -= harm_bonus;

    // Penalize tiny dead space that no realistic item (>=1) can use well:
    // post_residual in (0, 10] is nearly unusable -> strong penalty.
    if post_residual <= 10 && post_residual > 0 {
        score += (11 - post_residual) as f64 * 8.0;
    }

    // Integer-division thresholds: post_residual divisible by 4 or 8
    // suggests clean future packing of small items.
    if post_residual % 4 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    if post_residual % 8 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly reward; if next item fits at all, mild reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 12.0;
            // harmonic pairing: post_residual - next small and clean
            let r2 = post_residual - next_item_size;
            if r2 % 4 == 0 {
                score -= 5.0;
            }
            if r2 == 0 {
                score -= 30.0;
            }
        } else {
            // next item cannot follow here: slight penalty proportional to gap
            score += ((next_item_size - post_residual) as f64).min(30.0) * 0.4;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid pushing us
    // to open a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // early in the stream or when no bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Base cost of a fresh bin: grows as stream progresses (amortization)
        score += 55.0 + progress * 45.0;
        // If many bins are open and mean residual is high, discourage new bin
        score += (open_bins_count as f64).sqrt() * 4.0 + (mean_residual / cap) * 10.0;
        // But if the item is huge relative to capacity and mean residual is low,
        // a new bin may still win via the base cost alone.
    } else {
        // Prefer bins whose residual is close to item (tight fit)
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.15;
    }

    // Mild preference for filling more-opened bins when many are open
    if bin_residual != bin_capacity && open_bins_count > 3 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is highly rewarded.
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fit_ratio;

    // Open-bin pressure: many open bins -> discourage spreading, favor filling existing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let base = 55.0 + 3.0 * open_bins_count as f64;
        // If next item is small, a fresh bin is more valuable.
        let next_bonus = if next_item_size > 0 && next_item_size <= 30 { -8.0 } else { 0.0 };
        score = base + next_bonus;
        // Penalize opening new bin when a decent fit exists elsewhere.
        if fitting_bins_count > 0 && (bin_residual - item_size) < 15 {
            score += 20.0;
        }
    }

    // Lookahead: favor bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Mean residual coupling: prefer bins deviating below mean residual (fill the fullest first).
    score -= 1.5 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score += (item_size as f64 / bin_capacity as f64) * 10.0;

    if next_item_size > 0 {
        // Aggressive 2-step lookahead: perfect chain match is heavily rewarded
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual >= next_item_size {
            // Reward proportional to how well the next item fits the leftover
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack.min(60.0);
        } else {
            // Dead space below the next item: penalize proportionally to waste
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 1.5;
        }

        // Extra bonus if the chain leaves exactly the next-next fit potential
        if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 25.0;
        }
    } else {
        // Last item: simply minimize final waste
        score += 5.0;
    }

    // Relative to mean residual: avoid destroying average flexibility
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when item barely fits anywhere
    if bin_residual == bin_capacity {
        let tightness = if fitting_bins_count >= 1 {
            (item_size as f64 / bin_residual as f64).min(1.0)
        } else {
            0.0
        };
        score += 80.0 - 40.0 * tightness;
        if next_item_size > 0 && next_item_size > post_residual {
            score += 30.0; // new bin can't chain the next item either
        }
    }

    // Late in the stream: consolidate rather than open new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (open_bins_count as f64).sqrt();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post-residual so small leftovers dominate.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 15.0;
        } else {
            score -= 8.0 * (1.0 - gap as f64 / bin_capacity as f64);
        }
    }
    // Penalize if next item cannot use the leftover space at all (dead space risk).
    if next_item_size > post_residual && post_residual > 0 {
        score += 5.0;
    }

    // Prefer filling bins that are already relatively empty among open bins
    // (consolidate waste into fewer bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Early in the stream: slight preference for opening new bins keeps options open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins already open or late in stream.
        score += 10.0 + 30.0 * progress + 0.5 * open_bins_count as f64;
        // But if this item is huge relative to capacity, new bin is natural anyway.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 25.0;
        }
    }

    // Late in the stream, discourage leaving medium dead space.
    if progress > 0.7 {
        score += 0.05 * post_residual as f64 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = norm_pr * (1.0 + 0.6 * norm_pr * norm_pr);

    // Smooth quadratic coupling: tight fits matter more as the stream progresses.
    score += 0.8 * norm_pr * norm_pr * (progress * (1.0 - progress) * 4.0 + 0.5);

    // Reward filling bins well (item_size / bin_residual closeness to 1).
    let fill = item_size as f64 / bin_residual as f64;
    score -= 1.5 * fill * fill;

    // Lookahead coupling: if the next item fits the post residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr as f64 {
            score -= 1.2 * (1.0 - (nxt / pr) );
        } else {
            score += 0.4 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening new bins.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 3.0;
    }

    // New-bin candidate: penalize opening a new bin, unless existing bins would leave
    // very fragmented residuals (poor fits) or the stream is early with few bins.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap - 0.5).abs();
        score += 4.0 - 2.0 * fragmentation - 1.5 * (1.0 - fit_ratio) - progress;
    }

    // Mild preference to consolidate across many open bins.
    score += 0.02 * open_bins_count as f64 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead-space bands".
    // Residues near 0 (tight fit) are valuable; residues near 5 are worst (hardest to fill).
    let post = post_residual as i64;
    let residue = ((post % 10) - 5).abs() as f64; // 0 at residue 5 (bad), 5 at residue 0 (good)
    score -= 3.0 * residue;

    // Strong reward for exact or near-exact fills (harmonic alignment with capacity).
    if post == 0 {
        score -= 60.0;
    } else if post <= 10 {
        score -= 25.0 - post as f64;
    }

    // Fractional capacity classes: post_residual / capacity quarters.
    let frac = post_residual as f64 / bin_capacity as f64;
    if frac < 0.25 {
        score -= 8.0; // bin nearly full, good to fill it further
    } else if frac > 0.75 {
        score += 6.0; // leaving a bin mostly empty is wasteful
    }

    // Lookahead: reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.1 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item cannot use leftover: penalize proportionally to dead space
        score += 5.0 * post_residual as f64 / bin_capacity as f64;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive if no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && mean_residual > item_size as f64;
        if good_fit_exists {
            score += 30.0; // discourage opening new bin when decent fits exist
        } else {
            score -= 5.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // Early stream: keep bins open and flexible; late stream: consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Mild penalty for spreading across many open bins when mean residual is high.
    score += 0.05 * open_bins_count as f64 * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold any future item
    // (min item size 1, but small gaps < 10 are effectively dead) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the post residual,
    // strongly favor this placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // post residual can't host the next item: mild penalty scaled by tightness
        score += 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: if this is the only bin that fits, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into new bins
    // and prefer tighter packing (smaller post_residual already does this, add a
    // mild bonus for filling bins deeply when bin count is high).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score -= pressure * 0.5 * (1.0 - progress);

    // New-bin candidate handling: an empty bin gets a baseline cost that grows
    // with the number of already open bins, so it is only chosen when no open
    // bin offers a reasonable fit.
    if bin_residual == bin_capacity {
        score = 60.0 + 3.0 * open_bins_count as f64;
        // If no existing bin fits at all, opening is fine.
        if fitting_bins_count == 0 {
            score -= 70.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins where the next item fits the post-residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly or snugly after placement.
            let lookahead_waste = (post_residual - next_item_size) as f64;
            score -= 150.0 - 0.5 * lookahead_waste;
            if post_residual == next_item_size {
                score -= 500.0; // chain of perfect fits
            }
        } else {
            // Next item won't fit here after placement: penalize dead space
            // proportional to how much of the residual is stranded.
            let stranded = (next_item_size - post_residual) as f64;
            score += 0.3 * stranded;
        }
    }

    // Penalize leaving residuals too small for any plausible item (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Relative to mean residual: prefer bins whose residual is tighter than average.
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = bin_capacity as f64 + 40.0;
        // If current bin is a bad fit (large leftover) and lookahead also mismatches,
        // opening a fresh bin becomes attractive.
        if next_item_size > 0 && item_size <= bin_residual {
            let leftover = bin_residual - item_size;
            if leftover < next_item_size && leftover > 0 {
                score -= 80.0; // poor fit everywhere -> open new bin
            }
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Mild penalty for too many open bins.
    score += 2.0 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize proportionally to how well the item fills the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to be useful later (unusable sliver).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: bonus if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty if post residual is wasted.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_penalty = 45.0;
        // If several bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            new_bin_penalty += 20.0 * (fitting_bins_count as f64).min(4.0);
        }
        // Early in the stream, prefer consolidating; late, tolerate new bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty -= 10.0 * progress;
        // If mean residual across open bins is small, open bins are nearly full anyway.
        new_bin_penalty -= (mean_residual / 10.0).min(15.0);
        score += new_bin_penalty;
    }

    // Mild preference for bins with residual close to item (best-fit style),
    // relative to the mean residual across open bins.
    let dev = (bin_residual as f64 - item_size as f64) - mean_residual;
    score += 0.05 * dev;

    // Slight preference to balance load among many open bins.
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / bin_capacity as f64;

    // Smooth polynomial coupling: dead space penalized more as stream progresses
    let dead_penalty = norm_pr * norm_pr * (0.5 + 2.0 * progress * progress);
    score += 40.0 * dead_penalty;

    // Reward tight fits (small post_residual) with smooth interaction with progress
    let tight_reward = (1.0 - norm_pr).powi(3) * (1.0 + progress);
    score -= 30.0 * tight_reward;

    // Last-chance bin bonus: avoid opening new bin when this is the only fit
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // New-bin candidate: penalize mildly, less so when existing fits are poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let poor_fit = norm_pr; // = 1.0 for new bin
        score += 15.0 * (1.0 + 0.5 * progress) - 20.0 * (mean_residual / bin_capacity as f64).min(1.0);
        let _ = poor_fit;
    }

    // Lookahead: reward if next item fits the post residual smoothly
    if next_item_size > 0 {
        let fits_next = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        let slack = (post_residual as f64 - next_item_size as f64).abs() / bin_capacity as f64;
        score -= 12.0 * fits_next * (1.0 - slack);
    }

    // Mild pressure to consolidate among many open bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residue mod small moduli
    let r = post_residual;
    let m2 = (r % 2) as f64;
    let m5 = (r % 5) as f64;
    let m10 = (r % 10) as f64;
    let m25 = (r % 25) as f64;

    // Penalize dead space that falls in awkward harmonic classes:
    // residuals like 1..9 are nearly unusable (item sizes >= 1, but tiny slivers waste)
    if r > 0 && r < 10 {
        score += 30.0; // unusable sliver
    }
    // penalize residuals that no common item class (10/20/25/50) can use
    let class_usable = (r % 10 == 0) || (r % 20 == 0) || (r % 25 == 0) || (r % 50 == 0);
    if !class_usable && r > 0 {
        score += 4.0 + m5 * 0.4 + m10 * 0.2;
    }
    // small odd residues are worst
    score += m2 * 1.5 + m25 * 0.06;

    // Perfect fit reward
    if r == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == r && r > 0 {
            score -= 40.0;
        } else if next_item_size <= r && r > 0 {
            let next_post = r - next_item_size;
            // reward if next item leaves another harmonic-class-friendly residual
            if next_post % 10 == 0 {
                score -= 12.0;
            } else if next_post % 5 == 0 {
                score -= 6.0;
            }
            score -= (next_item_size as f64) * 0.1;
        } else {
            // next item won't fit here; residual becomes dead space for lookahead
            score += (r as f64) * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate logic: only attractive if no good fit exists among open bins
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        // penalize opening a new bin proportionally to how many bins already fit the item
        score += 20.0 + 8.0 * (fitting_bins_count as f64);
        // but if the item is huge relative to capacity and fit would leave bad residue, allow it
        let fit_residue = bin_capacity - item_size;
        let open_residue = bin_residual - item_size; // same for new bin
        let _ = open_residue;
        if fitting_bins_count == 0 || (fit_residue > 0 && fit_residue < 10) {
            score -= 35.0;
        }
        // early stream: opening bins is cheaper (build diversity)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 10.0;
    } else {
        // favor bins whose residual is close to item (tight fit)
        let tightness = (bin_residual - item_size) as f64;
        score += (mean_residual - tightness) * 0.05;
    }

    // mild preference for consolidating into fewer bins when many are open
    score += (open_bins_count as f64) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize small unusable gaps after placement.
    if post_residual > 0 {
        let max_item = 100u32;
        let unusable = post_residual < next_item_size.max(1) || post_residual < 10;
        if unusable {
            score += (post_residual as f64) * 2.5 + 40.0;
        }
        // Perfect fit reward
        if post_residual == 0 {
            score -= 100.0;
        } else if post_residual <= 5 {
            score -= 30.0;
        }
        // Penalize dead space relative to capacity
        score += (post_residual as f64 / bin_capacity as f64) * 60.0;
    }

    // Lookahead: penalize if post_residual cannot host next item but barely
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            score += 15.0;
        }
    }

    // Last chance bin: this is the only bin that fits -> strong reward
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Open bins pressure: discourage opening new bins when open bins fit well
    if bin_residual == bin_capacity {
        // New bin candidate
        score += (open_bins_count as f64) * 10.0;
        if fitting_bins_count >= 1 {
            score += 80.0; // prefer existing bins generally
        }
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 20.0;
        }
    } else {
        // Favor bins whose residual is close to item size (tight fit)
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.5;
    }

    // Mean residual coupling: avoid bins far from mean residual
    score += ((bin_residual as f64 - mean_residual).abs()) * 0.3;

    // Early stream: be slightly greedy to consolidate; late stream: keep bins open
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits post-residual
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 2.5 * (next_item_size as f64) - 0.05 * slack;
    } else if next_item_size > 0 {
        // next item cannot follow: penalize wasted dead space
        score += 0.6 * (next_item_size as f64);
    }

    // Penalize small unusable residues relative to mean residual
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    score -= 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 150.0 * pressure + 10.0 * (open_bins_count as f64);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual) with a superlinear term.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize dead space: residual that cannot plausibly fit a future item.
    let dead = if post_residual > 0 && post_residual < 10 { 1.0 } else { 0.0 };
    score += 60.0 * dead;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Perfect chaining: next item fills the bin exactly.
            if post_residual == next_item_size {
                score -= 25.0;
            }
        } else {
            // Post-residual too small for the next item: mild penalty proportional to waste.
            score += 0.15 * post_residual as f64;
        }
    } else {
        // Last item: any residual is pure waste; prefer minimal leftover.
        score += 0.5 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin, but discount the penalty
    // when many bins are open (consolidation pressure) or late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_bin_penalty = 55.0;
        new_bin_penalty -= 0.6 * open_bins_count as f64;
        new_bin_penalty -= 15.0 * progress;
        // If the new bin could pair item + next item perfectly, soften penalty.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity && item_size + next_item_size >= bin_capacity as u32 * 9 / 10 {
            new_bin_penalty -= 20.0;
        }
        score += new_bin_penalty.max(5.0);
    }

    // Global balance: prefer bins whose residual deviates from the mean residual
    // in the direction of using up larger residuals first (best-fit-like global view).
    let dev = (bin_residual as f64 - mean_residual) / (bin_capacity as f64);
    score += 8.0 * dev;

    // Slight preference for filling bins with more residual earlier in the stream.
    score += 3.0 * dev * (1.0 - step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit_frac = item_size as f64 / cap;

    // Base: minimize post_residual (tight fit wins)
    let mut score = post;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space is punished more strongly (quadratic/cubic growth)
    let dead = post / cap;
    score += (post * post / cap) * (0.5 + 1.5 * progress * progress);
    score += post * dead * progress * (1.0 - progress);

    // Reward good utilization non-linearly
    score -= 10.0 * fit_frac * fit_frac * (1.0 + progress);

    // Penalize near-new-bin fits (item almost fills bin alone) slightly less late in stream
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if open bins are congested or fits are poor
        let congestion = open_bins_count as f64 / (fitting_bins_count.max(1) as f64);
        score = post + 25.0 - 15.0 * congestion * (0.3 + progress);
        // If lookahead fits well in the fresh bin's future residual, discount
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0 * (1.0 - (next_item_size as f64 / post.max(1.0)).abs());
        }
    } else {
        // Last-chance bonus: if this is the only fitting bin, strongly favor it
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Lookahead synergy: reward if next item fits the post residual
        if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0 * (1.0 - (next_item_size as f64 / post.max(1.0)));
        }
        // Penalize leaving residual that no plausible item fits (dead space)
        if post > 0 && post < 10 {
            score += 15.0 * (1.0 - progress);
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * progress;

    // Deviation from mean residual: prefer bins near the mean (keeps bin profile uniform)
    score += 0.05 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class boundaries: dead space < 10 is nearly unusable (items >= 1, but small items are rare);
    // classes of 10..25, 25..50, 50..100 have different utility.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: strongly reward
    } else if post_residual < 10 {
        score += 45.0; // dead space: heavily penalize
    } else if post_residual <= 25 {
        score -= 12.0; // small residual still usable by tiny items
    } else if post_residual <= 50 {
        score -= 6.0; // half-class: decent
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of 10 pair
    // well with common item sizes (10,20,...) — reward divisibility.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    } else if post_residual % 5 == 0 {
        score -= 3.0;
    }

    // Integer division thresholds: can next item fit in the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 15.0; // lookahead chains nicely
            // bonus if both items nearly fill the bin together
            if (item_size + next_item_size) as f64 >= 0.95 * cap {
                score -= 12.0;
            }
        } else {
            score += 10.0; // lookahead won't fit here
        }
    }

    // Tightness reward: filling a bin deeply is good.
    let fill_frac = (item_size as f64) / cap;
    score -= 20.0 * fill_frac;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open fits are bad.
    if bin_residual == bin_capacity {
        // neutral baseline; slight penalty so we prefer decent existing fits
        score = 0.55 * cap + (1.0 - fill_frac) * 0.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // opening fresh bin helps sequence large items
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // penalize opening new bins when mean residual across open bins is healthy
        if mean_residual > (next_item_size as f64).max(item_size as f64) {
            score += 30.0;
        }
    }

    // Progress-aware: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (1.0 - pr / cap);

    // Discourage proliferation of open bins with large mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // typical items (1..=100) become permanent waste. Penalize small
    // non-zero post_residual heavily; zero residual is perfect.
    if post_residual > 0 {
        // treat residual below the smallest plausible next item as dead space
        let dead_threshold = 12.0f64;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 8.0;
        } else {
            // mild superlinear penalty on leftover space
            score += (post_residual as f64).powi(2) / (bin_capacity as f64);
        }
    } else {
        // perfect fill reward
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }
    // If next item does NOT fit in post_residual but would fit elsewhere,
    // this bin strands the lookahead slightly more.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // few bins are open; encourage compacting when many are open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = open_bins_count as f64 * (0.4 + 0.6 * progress);
    score += pressure * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Make opening a new bin costly by default so we only open when the
    // best existing fit is poor (handled via large residual penalty above).
    if bin_residual == bin_capacity {
        // base cost of a fresh bin, modulated by how bad existing fits are
        score += 40.0;
        // but if the item is large relative to capacity, a fresh bin gives
        // a clean fit; soften the cost.
        let large_item = item_size as f64 / bin_capacity as f64;
        score -= large_item * 20.0;
        // early in stream, opening bins is cheaper (need bins anyway)
        score -= (1.0 - progress) * 15.0;
    }

    // Prefer bins whose residual is close to mean (balanced packing),
    // penalize outliers that would create fragmented space.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.2;

    // Tight-fit bonus: reward when item nearly fills the bin.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.8 {
        score -= (fill_ratio - 0.8) * 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) accommodates the next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let lookahead_match = 1.0 / (1.0 + gap / 12.0);
        score -= 30.0 * lookahead_match;
        // Perfect chain fit: item leaves exactly room for next item.
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual < next_item_size {
            // Dead space relative to next item: penalize proportionally.
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    } else {
        // Last item: only absolute tightness matters.
        score -= 20.0 * tightness;
    }

    // Compare against mean residual: bins tighter than average are more valuable
    // to fill now; looser bins can wait.
    let dev = post_residual as f64 - mean_residual;
    score += 0.15 * dev;

    // Last-chance bin: strongly prefer using the only bin that fits, to avoid
    // opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // no open bin fits well (post_residual would leave large unusable space)
    // or the item perfectly splits a fresh bin relative to lookahead.
    if bin_residual == bin_capacity {
        let fresh_base = 0.55 * bin_capacity as f64;
        // Penalize opening a new bin by default...
        score += 55.0;
        // ...unless existing bins would leave big dead space.
        let waste_elsewhere = (post_residual as f64).min(fresh_base);
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: nothing else fits
        } else if next_item_size > 0 && post_residual == next_item_size {
            score -= 70.0; // perfect two-item split of a fresh bin
        } else if waste_elsewhere > 0.6 * bin_capacity as f64 {
            score -= 45.0; // existing fits are terrible
        } else if fitting_bins_count == 1 {
            score += 30.0; // keep the last-chance bin viable
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild penalty per open bin: encourage consolidation when roughly equal.
    score += 0.6 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly favor tight fits: small post_residual is already the base score.
    // Reward exact/near-exact fits superlinearly.
    if post_residual <= 2 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 2.0 * (11.0 - post_residual as f64);
    }

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual > 0 && (post_residual as u64) < (next_item_size as u64) {
            // dead space unless next item is tiny relative to it
            let waste_frac = 1.0 - (next_item_size as f64 / post_residual as f64).min(1.0);
            score += 8.0 * waste_frac;
        } else if post_residual >= next_item_size {
            // bonus: next item can likely slot in here
            score -= 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        if fit_ratio > 0.5 {
            score -= 25.0 * fit_ratio;
        }
    }

    // New-bin candidate handling: opening a bin is expensive early (many items left),
    // but acceptable late or when open bins are mostly full.
    if bin_residual == bin_capacity {
        let open_penalty = 40.0 * (1.0 - progress) + 10.0;
        // If existing bins would leave huge waste, opening is less bad.
        let avg_fill = bin_capacity as f64 - mean_residual;
        let desperation = (avg_fill / bin_capacity as f64).min(1.0);
        score += open_penalty * (1.0 - 0.6 * desperation);
        // Slight tie-break: prefer new bin whose post_residual matches next item
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 3.0;
        }
    }

    // Prefer fuller bins among open bins (bin_residual small => good).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Mild pressure to keep the number of open bins from exploding.
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalize key quantities
    let post_norm = post_residual as f64 / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_norm = fitting_bins_count as f64;

    // Non-linear waste penalty: quadratic in normalized post residual
    score += 2.0 * post_norm * post_norm * cap;

    // Reward tight fits (small post_residual) more strongly as stream progresses
    let tightness = 1.0 - post_norm;
    score -= 1.5 * tightness * tightness * (0.5 + progress);

    // Penalize when few bins can fit the item (this bin is precious)
    if fitting_bins_count <= 1 {
        score += 8.0;
    } else {
        score -= 0.5 / fit_norm;
    }

    // Lookahead coupling: reward if next item fits in post_residual exactly/well
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) >= nxt {
            let gap = post_residual as f64 - nxt;
            score -= 1.2 * (1.0 - gap / cap);
        } else {
            // dead space that next item cannot use
            score += 0.8 * post_norm * cap;
        }
    }

    // New-bin candidate handling: brand-new empty bin
    if bin_residual == bin_capacity {
        // Default mild penalty so existing bins are preferred
        let mut new_bin_penalty = 3.0 + 2.0 * progress;
        // But if existing bins would leave large unusable gaps, opening a new bin is better
        let existing_gap = post_residual as f64; // for empty bin, post == cap
        if fitting_bins_count >= 1 {
            let worst_gap = cap; // unknown; use mean residual as proxy for open-bin slack
            if mean_residual > 0.0 && existing_gap < worst_gap * 0.0 {
                new_bin_penalty -= 5.0;
            }
        }
        // Opening a new bin is cheap early, expensive late
        score = new_bin_penalty + 0.01 * open_bins_count as f64;
        // If item is large relative to mean residual, new bin is attractive
        if mean_residual > 0.0 && (item_size as f64) > mean_residual {
            score -= 1.0;
        }
    }

    // Smooth open-bin count coupling: slight preference to fill existing bins densely
    score += 0.05 * (open_bins_count as f64).ln().max(0.0) * post_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let mut score = pr as f64;

    // Harmonic dead-space classes on post_residual
    if pr == 0 {
        score -= 60.0; // perfect closure
    } else if pr < 10 {
        score -= 25.0; // near-closed, minimum item size can't fit anyway
    } else {
        // quantize residual into capacity tenths (harmonic class)
        let class = (pr as f64 / cap * 10.0).floor();
        score += class * 1.5;
        // odd/even style modulo class: residuals that are multiples of 10 align
        // with the item grid, making future packing easier
        if pr % 10 == 0 {
            score -= 6.0;
        } else {
            score += (pr % 10) as f64 * 0.4;
        }
    }

    // Lookahead coupling (k=2): does the next item pair with this residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0; // perfect lookahead closure
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 18.0 * (1.0 - slack / cap); // tighter pair = better
        } else {
            // next item won't fit here; slight penalty for stranding space
            score += 4.0;
            // but if residual is small enough to be dead space anyway, no penalty
            if pr < 10 {
                score -= 4.0;
            }
        }
    }

    // Last-chance bin: avoid opening a new bin when only this one fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling (bin_residual == bin_capacity)
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // no open bin fits: opening is mandatory
            score = -50.0;
        } else {
            // opening a new bin: cost grows with how well it would fit elsewhere
            let tightness = 1.0 - (bin_residual - item_size) as f64 / cap;
            score = 45.0 + tightness * 30.0;
            // if the only fitting bin would leave dead space (<10), prefer new bin
            if fitting_bins_count == 1 && (bin_residual - item_size) >= 10 && (bin_residual - item_size) < 10 {
                score -= 5.0;
            }
            // late in the stream, slightly prefer consolidating
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += progress * 5.0;
        }
    }

    // Mild pressure against bin sprawl
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (1..=100, but realistically >= 10) are dead space.
    let dead_threshold = 12u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 40.0 * (dead_threshold - post_residual) as f64;
    }
    // Penalize any nonzero residual super-linearly to prefer tight fits.
    score += 0.15 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 50.0;
        } else if gap < dead_threshold {
            score -= 20.0;
        } else {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && next_item_size <= bin_capacity {
        // Next item won't fit here; slight penalty for leaving bin that will strand it.
        score += 5.0;
    }

    // Open bins pressure: discourage spreading across many bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.5 + 0.5 * progress);

    // Mean residual coupling: prefer bins below mean residual (tighter bins) to keep
    // looser bins available for larger future items.
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strongly reward using the only fitting bin to avoid new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate: opening a fresh bin should be penalized unless the current
    // item is large and no tight fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= 70 && fitting_bins_count == 1 {
            score -= 35.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small dead space)
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Perfect fit: huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if post_residual >= next_item_size {
            // next item can chain into this bin
            score -= 30.0 * (1.0 - gap / cap);
            if gap == 0.0 {
                score -= 500.0; // perfect 2-step chain
            }
        } else {
            // post_residual too small for next item: penalize unusable sliver
            let sliver = pr / cap;
            if pr < 10 {
                score += 40.0 * (1.0 - sliver);
            }
            score += 8.0 * gap / cap;
        }
    }

    // Compare against mean residual: prefer bins with residual below mean (consolidate)
    let pr = post_residual as f64;
    if mean_residual > 0.0 {
        score += 6.0 * (pr - mean_residual) / cap;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere
    if bin_residual == bin_capacity {
        // penalize opening new bins mildly; more so later in the stream
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 + 20.0 * progress;
        // but if next item is large and no residual chain is likely, new bin is fine
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Mild preference for filling more-opened bins (reduce open bin count pressure)
    score += 0.3 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: post_residual that can never fit a typical small item (>= 10)
    // is wasted; the smaller the residual, the worse the waste.
    if post_residual < 10 {
        score += 25.0;
    } else {
        score += 8.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead: if the next item fits exactly in the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: penalize opening a new bin, more so early in the stream
    // and when other bins fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 15.0 + 25.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // Opening bins is more acceptable when many bins are already open and crowded.
        score -= 0.3 * open_bins_count as f64;
    }

    // Global state: prefer bins whose residual is close to the mean residual
    // (keeps residuals balanced, preserving flexibility).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Mild penalty for very full bins late in the stream? No — prefer filling bins fully
    // as the stream progresses (close out bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: quadratic+quartic growth of dead space, amplified by stream progress
    let x = post / cap;
    score += (1.0 + progress) * (x * x * cap * 0.5 + x * x * x * x * cap * 0.5);

    // Reward tight fits: smooth sigmoid-like coupling between item and residual
    let tight = 1.0 - (item_size as f64 / bin_residual.max(1) as f64);
    score -= (1.0 - tight * tight) * 8.0;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that matches the next item
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        score -= (1.0 - gap / cap).max(0.0) * 6.0;
        // Penalize leaving residual that neither fits next item nor is tiny
        if post_residual < next_item_size {
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Coupling with mean residual: prefer bins deviating below mean (consolidate space)
    score += (post - mean_residual) * 0.15 * (1.0 + progress);

    // New-bin candidate: mild penalty early, growing pressure to reuse bins later
    if bin_residual == bin_capacity {
        score += 5.0 + 25.0 * progress + 2.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by integer division
    let post_class = post_residual / 10; // coarse harmonic class (0..10)
    // Reward small post_residual (tight fits) with a non-linear bonus
    let tight_bonus = match post_class {
        0 => 40.0,
        1 => 22.0,
        2 => 12.0,
        3 => 5.0,
        _ => 0.0,
    };
    score -= tight_bonus;

    // Modulo coupling: leftover that pairs with next item (post_residual == next_item_size)
    // is a perfect harmonic match; leftover just below next item is a trap.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0; // perfect chain
        } else if post_residual > next_item_size {
            // leftover that can host next item is reusable
            let ratio = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * ratio;
        } else {
            // dead space relative to lookahead: penalize proportionally
            let gap = (next_item_size - post_residual) as f64;
            score += 0.5 * gap;
        }
    }

    // Penalize post_residual in awkward mid-range classes (hard to fill later)
    let awkward = if post_residual >= 20 && post_residual <= 45 { 8.0 } else { 0.0 };
    score += awkward;

    // Fractional capacity coupling: item filling a large fraction is good
    let fill_frac = item_size as f64 / cap_f;
    score -= 15.0 * fill_frac * fill_frac;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins with high mean residual: encourage consolidation into existing bins
    if open_bins_count > 2 {
        let spread = (mean_residual - post_residual as f64).abs();
        score += 0.1 * spread;
        score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / cap_f);
    }

    // NEW-BIN CANDIDATE handling: empty bin has residual == capacity.
    // Opening a new bin should only win when the item fits nothing well.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap_f * 0.9 + item_size as f64;
        // it's more attractive early in the stream or when few bins are open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 30.0 * (1.0 - progress);
        score -= 2.0 * open_bins_count as f64;
        // if the item is large, a fresh bin wastes little
        if item_size >= 50 {
            score -= 20.0;
        }
        // if next item is huge, fresh bin keeps room
        if next_item_size >= 60 {
            score -= 15.0;
        }
    } else if fitting_bins_count == 1 {
        // make the sole fitting bin strongly preferred over opening a new bin
        score -= 35.0;
    }

    // Early stream: allow more bins to build diversity of residuals
    if step_index < total_items / 10 && bin_residual < bin_capacity {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (low post_residual).
    score += post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable
    // for future items (min item size 1..100 unknown, but small gaps rarely reused).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward bins whose residual closely matches the item (tightness ratio).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fit_ratio;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.8 * open_bins_count as f64 * (1.0 - fit_ratio);

    // Mean residual coupling: a bin far below mean residual is a "junk" bin;
    // filling junk bins is good, keeping rich bins open is good.
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.3 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new one (unless dead space is severe).
    if fitting_bins_count == 1 && !(post_residual > 0 && post_residual < 10) {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big bonus.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 80.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
    } else if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 25.0; // gap can never serve the next item
    }

    // New-bin candidate: an empty bin is attractive when item is large or
    // all fits are poor; it should compete only when current fit wastes space.
    if bin_residual == bin_capacity {
        // Neutral base for a fresh bin; slightly worse than a perfect fit,
        // better than a wasteful placement.
        score = 45.0 + 0.5 * item_size as f64 - 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fits (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            // Next item fits: penalize proportionally to leftover after both placements.
            let after_next = post_residual - next_item_size;
            score -= (next_item_size as f64) * 0.5;
            score += after_next as f64 * 0.3;
        } else {
            // Next item does NOT fit: post_residual becomes dead space (at least for one step).
            let dead = post_residual as f64;
            // Penalize dead space more if it is small-unusable (wasted potential).
            score += dead * 0.4;
            if dead < 10.0 {
                score += 30.0;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are tighter;
    // prefer filling tight bins (reduces open bin spread), penalize dumping into very loose bins.
    let res_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let ratio = res_f / mean_residual;
        if ratio < 0.7 {
            score -= 20.0; // tight bin: good target
        } else if ratio > 1.5 {
            score += 15.0; // loose bin: keep it for future large items
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // item is large relative to capacity and no good fit exists elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fill_frac = item_size as f64 / bin_capacity as f64;
        if fill_frac > 0.6 {
            score -= 40.0; // large item into fresh bin is fine
        } else {
            score += 50.0; // avoid wasting a fresh bin on small items
        }
        // Discourage new bins when many bins already open and item is small.
        if open_bins_count > 4 && fill_frac < 0.4 {
            score += 40.0;
        }
    }

    // Mild stream-progression pressure: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
