pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: large post_residual is increasingly bad as stream progresses.
    let x = pr / cap;
    score += 30.0 * x * x * (0.5 + 0.5 * progress);

    // Reward tight fits (small post_residual) with smooth quadratic bonus.
    score -= 12.0 * (1.0 - x) * (1.0 - x);

    // Exact fit bonus (smooth exponential rather than piecewise).
    score -= 8.0 * (-pr as f64 / 5.0).exp();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - progress * 0.5);
    }

    // Prefer bins whose residual is close to the item (smooth closeness term).
    let closeness = (bin_residual as f64 - item_size as f64) / cap;
    score += 10.0 * closeness * closeness;

    // Lookahead: penalize leaving a residual that neither fits nor pairs with next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 6.0 * (nx - pr) / cap;
        } else {
            score -= 4.0 * (-(pr - nx) / 20.0).exp();
        }
    }

    // New-bin candidate: attractive early or when fit would leave large dead space.
    if bin_residual == bin_capacity {
        let dead = pr / cap;
        score -= 20.0 * (1.0 - progress) - 25.0 * dead * dead;
    }

    // Mild penalty for proliferating bins late in the stream.
    score += (open_bins_count as f64).ln().max(0.0) * progress * 2.0;

    // Mean residual alignment: prefer bins near the mean residual.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose residual falls into
    // "usable" classes (>= 10, or exactly 0) are preferred.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else if pr >= 10 {
        // residual still usable by the smallest possible future item
        score -= 20.0 * ((pr as f64) / (bin_capacity as f64));
    } else {
        // dead space class 1..9: heavily penalize
        score += 35.0 + (10 - pr) as f64 * 3.0;
    }

    // Integer-division thresholds: classify residual into capacity fractions
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if pr >= half {
        score -= 8.0;
    } else if pr >= quarter {
        score -= 2.0;
    } else if pr > 0 {
        score += 5.0;
    }

    // Modulo coupling: does post_residual align with next_item_size?
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 15.0;
            // exact harmonic match: next item exactly fills the bin
            if pr == next_item_size {
                score -= 40.0;
            } else {
                let rem = pr - next_item_size;
                if rem == 0 {
                    score -= 20.0;
                } else if rem < 10 {
                    score += 12.0; // would create dead space
                } else {
                    score -= (rem as f64).sqrt() * 2.0;
                }
            }
        } else {
            // next item cannot use this residual: mild penalty scaled by waste
            score += 6.0 + (next_item_size - pr) as f64 * 0.2;
        }
        // modulo arithmetic on next_item_size class
        let nclass = next_item_size % 10;
        if nclass == 0 {
            score -= 3.0; // round item, easy to pack elsewhere
        }
    } else {
        // last item: prefer tightest bin, ignore future concerns
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // Penalty for spreading too thin: many open bins with high mean residual
    if open_bins_count > 1 {
        let spread = mean_residual - (post_residual as f64);
        if spread > 0.0 {
            score += spread * 0.15;
        }
    }

    // New-bin candidate: only attractive when current fit is bad and
    // item is large relative to capacity (keeps future flexibility)
    if bin_residual == bin_capacity {
        let tight_fit = (bin_residual - item_size) < 10;
        if !tight_fit {
            score += 12.0; // discourage opening new bin on loose fits
            if next_item_size > 0 && next_item_size > bin_residual - item_size {
                score -= 5.0; // but next item may need fresh space
            }
        } else {
            score += 30.0; // an open bin already gives a perfect fit
        }
    }

    // Stream progression: early on, be conservative with open bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Small harmonic tie-breaker based on residual mod capacity fractions
    score += ((pr % quarter.max(1)) as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no plausible item (1..=100) can
    // use well are heavily penalized. Tiny gaps (< 10) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual <= 15 {
        score += 25.0;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Penalize leaving a gap that exactly matches nothing useful:
    // gaps in (15, 30) are hard to fill with typical items.
    if post_residual > 15 && post_residual < 30 {
        score += 12.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open,
    // but allow it when few bins exist (early stream).
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if existing bins fit poorly.
        score = 100.0 + post_residual as f64;
        if fitting_bins_count <= 1 {
            score -= 90.0; // last-chance bin: strongly prefer opening new bin
        }
        if open_bins_count < 3 {
            score -= 15.0; // early stream: new bins are cheap
        }
        score += (open_bins_count as f64).powf(1.3) * 2.0;
    } else {
        // Mild pressure to keep number of open bins from exploding.
        score += open_bins_count as f64 * 0.8;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly favor it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        score -= 15.0;
        // Extra reward if next item fills the gap almost exactly.
        let gap_use = next_item_size as f64 / post_residual.max(1) as f64;
        if gap_use > 0.8 {
            score -= 10.0;
        }
    }
    // Penalize if next item would be stranded by this placement's residual.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual && post_residual < 10 {
        score += 20.0;
    }

    // Mean-residual coupling: if this bin's residual is far above the mean,
    // it is a "loose" bin; prefer packing into tight bins instead.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Stream progression: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for post-residual that is unusable (small dead space)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward exact-ish fit
    if post_residual == 0 {
        score -= 40.0;
    }

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // next item won't fit: penalize wasted lookahead potential
        score += 8.0;
    }

    // Relative to mean residual: prefer bins with below-average residual (tighter packing)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize mildly, less so if current fit is terrible
    if bin_residual == bin_capacity {
        score += 12.0;
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 10.0;
        }
    }

    // Late-stream bias: consolidate more aggressively as stream progresses
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for dynamic time-horizon behavior.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: small post_residual is good, but reward even more
    // when the fit is "perfect enough" (post_residual below small threshold).
    let tight_fit_bonus = if post_residual == 0 {
        500.0
    } else if post_residual <= 5 {
        300.0
    } else if post_residual <= 10 {
        120.0
    } else {
        0.0
    };
    score -= tight_fit_bonus;

    // Penalize creating dead space that no plausible future item can use.
    // Items are 1..100, but small residuals (<10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let bin_pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual != bin_capacity {
        score -= 40.0 * bin_pressure;
    }

    // Lookahead coupling: if the next item fits into post_residual,
    // this placement is doubly valuable.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 80.0 + 0.5 * next_item_size as f64;
        } else if next_item_size > bin_residual {
            // Next item can't fit here anyway; residual quality matters less.
            score += 0.0;
        } else {
            // Next item fits current bin but not after this placement:
            // mild penalty for blocking it.
            score += 30.0;
        }
    }

    // Global residual balance: prefer bins whose residual is below mean
    // (tighter bins) to keep large residuals available for large items.
    if bin_residual != bin_capacity {
        let diff = mean_residual - bin_residual as f64;
        score += 0.3 * diff;
    }

    // Time horizon: early in stream, be conservative about filling bins
    // (leave room); late in stream, aggressively fill existing bins.
    let urgency = progress * 100.0;
    if bin_residual != bin_capacity {
        score -= urgency;
    } else {
        // New-bin candidate: penalize opening new bins, more so early on
        // and when other bins fit.
        let new_bin_penalty = 150.0 + (1.0 - progress) * 100.0 + 20.0 * bin_pressure;
        score += new_bin_penalty;
        // But if mean residual across open bins is very low, opening a
        // fresh bin is reasonable.
        score += 0.5 * mean_residual;
    }

    // Slight preference for bins with larger residual when item is large.
    score -= 0.1 * bin_residual as f64 * (item_size as f64 / 100.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial penalty on post_residual, scaled by normalized residual
    let norm_post = post_residual as f64 / cap;
    score += 2.5 * norm_post * norm_post * cap;

    // Reward tight fits: small post_residual gets a non-linear discount
    let fit_tightness = (bin_residual as f64 - item_size as f64) / bin_residual.max(1) as f64;
    score -= (1.0 - fit_tightness) * (1.0 - fit_tightness) * 8.0;

    // Lookahead: bonus if post_residual exactly accommodates next item (smooth coupling)
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        let lookahead_fit = 1.0 / (1.0 + gap * gap / 25.0);
        score -= 6.0 * lookahead_fit;
        // Penalize leaving residual that is too small for the lookahead item
        if (post_residual as f64) < next_item_size as f64 {
            score += 2.0 * (next_item_size as f64 - post_residual as f64) / cap;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - progress);
    }

    // Stream progress coupling: later in the stream, waste is costlier
    score += progress * norm_post * 4.0;

    // Mean residual interaction: penalize bins far from the fleet mean residual (fragmentation)
    let dev = post_residual as f64 - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: penalize opening a new bin unless residual is very small (poor fit)
    if bin_residual == bin_capacity {
        score += 20.0 - 18.0 * (1.0 - norm_post.min(1.0)) * (1.0 - norm_post.min(1.0));
        // if all open bins fit poorly, allow new bin: reward when item is large relative to residual of others
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fractions /10 classes
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (post_residual / (bin_capacity / 10).max(1)) as f64;

    // Reward near-full bins: small post_residual gets strong discount
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 300.0;
    } else if post_residual <= 20 {
        score -= 150.0;
    } else if post_residual <= 30 {
        score -= 60.0;
    }

    // Penalize dead space: residuals that are too small for any typical item
    // (items between 1 and 100, so residual < min plausible next fill)
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    }

    // Modulo arithmetic on post_residual: residuals congruent to common item sizes
    // are more likely reusable; awkward residues get penalized
    let r = post_residual % 10;
    if r == 0 {
        score -= 20.0;   // round residual, easy to fill
    } else if r >= 7 {
        score += 15.0;   // awkward sliver
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 40.0;
            // harmonic class match: next item leaves another round residual
            if (post_residual - next_item_size) % 10 == 0 {
                score -= 30.0;
            }
        } else {
            // next item cannot use this residual: slight penalty proportional to waste
            score += 10.0 + frac * 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only prefer it when no open bin gives a decent fit
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 60.0;
        // if this is the only fitting option, opening is fine
        if fitting_bins_count == 0 {
            score -= 400.0;
        }
        // late in stream, prefer closing out open bins
        if total_items > 0 && (step_index as f64) / (total_items as f64) > 0.8 {
            score += 100.0;
        }
    }

    // Prefer bins with residual close to item (tight fits) over huge residual bins
    let tightness = (bin_residual - item_size) as f64;
    score -= (bin_capacity as f64 - tightness) * 0.1;

    // Mild penalty for spreading across many open bins
    score += open_bins_count as f64 * 0.5;

    // Alignment with mean residual: bins far from mean waste potential
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Class-based harmonic discount: lower class index (fuller bin) is better
    score -= class * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 30 {
        score += 4.0;
    }

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness;

    // Pressure from number of open bins: discourage spreading when many bins are open.
    score += 0.8 * open_bins_count as f64;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if no open bin fits, new bin should be attractive (fitting_bins_count==1 here means only new bin).
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
    }

    // Lookahead: avoid leaving a gap that barely fails to fit the next item.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && (post_residual as u32) + 10 >= next_item_size {
        score += 15.0;
    }
    // Reward leaving a gap that exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Mild time-progression term: later in stream, prefer consolidating.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (mean_residual / bin_capacity as f64 - 0.5).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact / near-exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0 - (post_residual as f64) * 20.0;
    }

    // Penalize dead space relative to capacity
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += dead_frac * 60.0;

    // Aggressive 2-step lookahead: reward bins whose residual matches the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let match_frac = next_item_size as f64 / post_residual as f64;
        score -= 80.0 * match_frac * match_frac;
        // near-perfect chaining: next item fills bin almost exactly
        if post_residual - next_item_size <= 5 {
            score -= 120.0;
        }
    } else if next_item_size > 0 {
        // bin cannot host the next item: penalize proportionally to wasted potential
        score += 25.0 * (next_item_size as f64 / 100.0);
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score -= (mean_residual - post_residual as f64) * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin, more so as stream progresses
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 120.0 + 80.0 * progress + 5.0 * open_bins_count as f64;
        // but if item is large and no good fit exists, opening is less bad
        if item_size > 60 {
            score -= 60.0;
        }
    }

    // Mild pressure to fill bins with many competitors
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post-residual), with non-linear emphasis.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 {
        if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            // Lookahead: reward bins that can also host the next item.
            let lookahead_fit = 1.0 - (post_residual - next_item_size as u32) as f64 / cap;
            score -= 12.0 * lookahead_fit;
        } else {
            // Dead space: residual too small for the next item (or end of stream).
            let dead = post_residual as f64 / cap;
            score += 15.0 * dead * dead;
            if next_item_size > 0 {
                // Overshoot severity: how much the next item misses this residual.
                let miss = (next_item_size as f64 - post_residual as f64).min(30.0);
                score += 0.8 * miss;
            }
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }
    // Many alternatives: mild penalty to encourage consolidation into fewest-fit bins.
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Global state coupling: prefer filling bins when many bins are open.
    let open_pressure = (open_bins_count as f64 / (1.0 + total_items as f64 * 0.05)).min(3.0);
    score -= 3.0 * open_pressure * (1.0 - post_residual as f64 / cap);

    // Mean residual: if this bin is much emptier than average, deprioritize it
    // (save large residuals for larger future items).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev.max(0.0);

    // Time horizon: early in the stream, be conservative with near-perfect fills;
    // late in the stream, close out bins aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual == 0 {
        score -= 20.0 * (0.5 + 0.5 * progress);
    } else if post_residual < 10 {
        score -= 8.0 * progress;
    } else {
        score += 4.0 * (1.0 - progress) * (post_residual as f64 / cap);
    }

    // New-bin candidate calibration: only open a new bin when the current bin
    // would leave substantial unusable space and alternatives are poor.
    if bin_residual == bin_capacity {
        score = 55.0 + 0.5 * item_size as f64;
        if next_item_size > 0 && (next_item_size as u32) <= bin_capacity {
            score -= 2.0;
        }
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear coupling: residual efficiency decays with progress
    let prn = pr / cap;
    let tightness = 1.0 - prn;
    score -= 40.0 * tightness * tightness * (1.0 + 0.5 * progress);

    // Penalize large post-residual that can't host next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr < nx {
            score += 15.0 * (nx - pr) / cap;
        } else {
            score -= 10.0 * (1.0 - (pr - nx) / cap);
        }
    }

    // Last-chance bonus (smooth)
    let last_chance = if fitting_bins_count <= 1 { 1.0 } else { 0.0 };
    score -= 12.0 * last_chance * (0.5 + 0.5 * progress);

    // New-bin candidate: mildly discourage opening bins early
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Mean-residual deviation penalty (smooth quadratic)
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fills (dead space minimization).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic class of post_residual: residues divisible by small units are
    // more likely to be filled by future items (sizes 1..100 unknown distribution).
    let pr = post_residual as u32;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 15.0; // round-decade residuals are reusable
        } else if pr % 5 == 0 {
            score -= 7.0;
        }
        // Penalize awkward prime-ish / odd residues
        if pr % 2 == 1 {
            score += 4.0;
        }
        // Integer division thresholds: residual in (0,10) is nearly dead
        if pr / 10 == 0 {
            score += 25.0;
        } else if pr / 25 == 0 {
            score += 5.0;
        }
    }

    // Coupling with lookahead item: reward if next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            let slack = post_residual - next_item_size;
            score -= 40.0 / (1.0 + slack as f64);
            if next_item_size == post_residual % 100 && post_residual >= next_item_size * 2 {
                score -= 5.0; // capacity-fraction style bonus
            }
        } else {
            // next item won't fit here; penalize proportional to overshoot
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate handling: opening a bin is expensive; discourage unless
    // the current item would leave a very fragmented residual in existing bins.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin relative to capacity fraction used.
        score = 100.0 - (item_size as f64 / bin_capacity as f64) * 60.0;
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 20.0; // room for the lookahead pair in a fresh bin
        }
        if fitting_bins_count > 0 {
            // only open new bin if existing fits are poor; add pressure
            score += 10.0;
        }
    }

    // Mild pressure against bin sprawl late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 0.15 * (0.5 + progress);

    // Prefer bins tighter than average residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible future item (<= 1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Reward tight fits relative to capacity (fractional waste term).
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading into
    // new bins unless the fit is excellent; when few bins are open, opening
    // is cheap.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 6.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure, discounted by how bad
        // the best alternative fit likely is (approximated by mean_residual).
        score = 30.0 + pressure - mean_residual * 0.15;
        // Late in the stream, avoid proliferating bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    } else {
        // Placing into an existing bin relieves pressure.
        score -= pressure * 0.5;
    }

    // Lookahead coupling: if the next item fits exactly into the resulting
    // residual, big bonus; if next item barely misses, penalty.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size > post_residual {
            score += (next_item_size - post_residual) as f64 * 0.3;
        } else {
            score += (post_residual - next_item_size) as f64 * 0.2;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core waste penalty: squared post-residual punishes unusable dead space.
    score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // Aggressive 2-step lookahead: reward when the next item exactly fills
    // the post-residual (perfect chaining), penalize near-misses.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let diff = pr - nxt;
        if diff == 0.0 {
            // Next item exactly consumes the leftover: excellent.
            score -= 30.0;
        } else if diff > 0.0 && diff <= 20.0 {
            // Next item fits with small slack: good chaining.
            score -= 15.0 - diff;
        } else if diff < 0.0 && diff >= -nxt {
            // Next item does NOT fit: leftover may be dead space unless small.
            if pr < 10.0 {
                score -= 10.0; // tiny leftover is fine
            } else {
                score += diff.abs() * 0.5; // penalize unusable gap
            }
        }
        // Also reward residual that pairs with next item relative to mean residual.
        if (pr - nxt).abs() < (mean_residual - nxt).abs() {
            score -= 3.0;
        }
    }

    // Tight fit bonus: item nearly fills the bin now.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if post_residual <= 5 {
        score -= 20.0;
    } else if fill_ratio > 0.8 {
        score -= 8.0 * fill_ratio;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0;
        // If many bins already fit the item, discourage opening a new one.
        if fitting_bins_count > 0 {
            score += 8.0 * (fitting_bins_count as f64).min(5.0);
        }
        // Early in the stream, keeping bins consolidated is cheaper;
        // late in the stream, opening fresh bins is less costly.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 6.0 * progress;
        // If lookahead item is large, a fresh bin gives flexibility.
        if next_item_size > 0 && (next_item_size as f64) > mean_residual {
            score -= 5.0;
        }
    }

    // Mild preference for bins whose residual is above average (balance load).
    score += ((bin_residual as f64) - mean_residual) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low dead space after placement).
    let tightness = (post_residual as f64) / (bin_capacity as f64);
    score += 40.0 * tightness * tightness;

    // Reward exact or near-exact fills.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 5 {
        score -= 25.0;
    }

    // Lookahead coupling: penalize leaving a residual that is just barely
    // too small for the next item (awkward dead space), but reward leaving
    // exactly enough room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 30.0; // next item fits snugly here
        } else if next_item_size > post_residual && next_item_size - post_residual <= 10 {
            score += 20.0; // just-missed fit creates awkward gap
        }
        // If the next item is large, prefer bins whose residual stays usable.
        if next_item_size >= 60 && post_residual < next_item_size && post_residual > 0 {
            score += 10.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well, or the stream is early and consolidation is cheap.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut penalty = 25.0 + 30.0 * progress; // later in stream: reuse bins harder
        // If many bins fit the item, opening a new bin is wasteful.
        penalty += 15.0 * (fitting_bins_count as f64).min(5.0);
        // If mean residual is large, open bins have plenty of room: don't open new.
        if mean_residual > item_size as f64 {
            penalty += 20.0;
        }
        // Exception: if this bin is the only fitting one and residual is tiny,
        // a fresh bin may beat cramming — reduce the penalty.
        if fitting_bins_count == 1 && bin_residual - item_size < 5 {
            penalty -= 20.0;
        }
        score += penalty;
    }

    // Mild preference for filling bins that are already mostly full
    // (consolidate near-closed bins to free up bookkeeping).
    let fill_ratio = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
    score -= 8.0 * fill_ratio;

    // Slight global pressure: when many bins are open, favor bins below mean
    // residual (balance residuals) to keep a spread of usable capacities.
    if !is_new_bin && open_bins_count > 1 {
        let diff = (bin_residual as f64) - mean_residual;
        score += 0.05 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress;
    score += 8.0 * poly;

    // Reward tight fits more strongly later in the stream.
    let fit = item_size as f64 / bin_residual.max(1) as f64;
    score -= 6.0 * fit * fit * (0.5 + progress);

    // Penalize dead space relative to mean residual.
    score += 0.3 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: penalize leaving residual that can't hold the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 3.0 * (nx / cap);
        } else {
            score += 2.0 * (1.0 - pr / cap);
        }
    }

    // Mild penalty for opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 2.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity scale.
    let pr = post_residual;
    let class = pr % 10;
    // Penalize residuals that fall in "awkward" classes (not multiples of common item sizes).
    let awkward = match class {
        0 => -6.0,
        1 | 2 | 3 | 4 => 4.0,
        5 => -2.0,
        _ => 1.5,
    };
    score += awkward;

    // Integer-division thresholds: how many size-10 slots remain.
    let slots = (pr / 10) as f64;
    score += 0.8 * slots;

    // Lookahead coupling: reward if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 12.0; // perfect follow-up fill
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 3.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        score += 0.5 * (fitting_bins_count as f64 - 1.0);
    }

    // Tight fit reward: post_residual small relative to item size.
    let tightness = post_residual as f64 / item_size.max(1) as f64;
    score -= 4.0 / (1.0 + tightness);

    // New-bin candidate handling: only prefer fresh bin late in stream with many open bins
    // or when this bin would leave large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let dead = (post_residual as f64) / bin_capacity as f64;
        score = 100.0 - 30.0 * progress - 40.0 * dead - 5.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 200.0; // must open a new bin
        }
    } else if post_residual > 80 {
        // leaving a nearly-full residual is fine, but avoid extreme fragmentation
        score += 2.0;
    }

    // Mean-residual drift: discourage bins far below mean residual (fragmented outliers).
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest possible
    // item (size 1) are fine, but residuals in the "unusable gap" band (1..=12,
    // too small for most realistic items) are heavily penalized dead space.
    if post_residual >= 1 && post_residual <= 12 {
        score += 60.0 * (1.0 + (12 - post_residual) as f64 / 12.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio;

    // Dead-space shaping: penalize post_residuals that are "awkward" — large
    // enough to waste, small enough that few items fit (below typical item sizes).
    if post_residual > 12 && post_residual < 25 {
        score += 12.0;
    }

    // Open-bins pressure: when many bins are open, discourage opening new ones
    // and prefer consolidating into existing bins; when few bins are open,
    // a new bin is cheap.
    let pressure = open_bins_count as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to open bins and remaining stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 25.0 + pressure * 3.0 + 20.0 * progress;
        // But if no existing bin fits well (this bin is last chance for others),
        // opening a new bin is more acceptable.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Reward using existing bins more when many are open.
        score -= pressure * 0.8;
        // Last-chance bin: strongly favor filling the only bin that fits.
        if fitting_bins_count == 1 {
            score -= 35.0;
        }
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up — reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 50.0;
        } else if slack <= 10 {
            score -= 15.0;
        } else {
            score += 5.0;
        }
    }

    // Mean-residual alignment: prefer bins whose post_residual moves the bin's
    // residual toward the mean (balanced packing keeps future options open).
    let post_f = post_residual as f64;
    let dev = (post_f - mean_residual).abs();
    score += 0.15 * dev;

    // Mild preference for keeping residuals that are multiples of common sizes.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item also fits here: strong reward, scaled by tightness of the pair
            let pair_tightness = (item_size + next_item_size) as f64 / bin_capacity as f64;
            score -= 50.0 + 100.0 * pair_tightness;
            // Exact chain: post_residual == next_item_size is ideal
            if post_residual == next_item_size {
                score -= 200.0;
            }
        } else {
            // Post-residual is dead space relative to the next item
            let waste = post_residual as f64;
            let rel_waste = waste / bin_capacity as f64;
            // Penalize unusable slivers more as stream progresses (less time to recover)
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 30.0 * rel_waste * (1.0 + progress);
            // Small residuals (<10) are nearly useless: extra penalty
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Compare post_residual against mean residual: prefer leaving typical slack
    if post_residual as f64 > mean_residual {
        score += 0.5 * (post_residual as f64 - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - post_residual as f64);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin
        score += bin_capacity as f64;
        // If item fits snugly in an existing bin, don't open a new one
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 150.0; // extra deterrent when chaining is possible elsewhere
        }
        if fitting_bins_count > 0 {
            score += 80.0;
        }
        // Early in the stream, opening bins is cheaper (more items to fill them)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 100.0 * (1.0 - progress);
    }

    // Mild preference for bins with larger residual (less full) when all else equal
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: squared penalty on residual scaled by capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 40.0;

    // Penalize creating dead space that can't hold the next item.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += (next_item_size - post_residual) as f64 * 0.8;
        } else {
            // Reward residuals that leave room for the lookahead item.
            score -= 6.0;
        }
        // Perfect pairing: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 25.0;
        }
    } else {
        // Last item: purely minimize waste.
        score -= 10.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening new bins unless current bins are crowded
    // or the fit is terrible.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / 20.0;
        let waste = item_size as f64 / bin_capacity as f64;
        score += 45.0 - crowding * 30.0 - waste * 20.0;
        // If mean residual is small (bins nearly full), opening is fine.
        if mean_residual < item_size as f64 {
            score -= 35.0;
        }
        // Early in stream, keep bins open to consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += (1.0 - progress) * 15.0;
    }

    // Mild bonus for using bins with larger residual when many bins are open.
    score -= (bin_residual as f64 / bin_capacity as f64) * (open_bins_count.min(10) as f64) * 0.5;

    // Deviation from mean residual: prefer bins that deviate to reduce variance.
    let dev = bin_residual as f64 - mean_residual;
    score += dev.abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: smooth quadratic coupling of post_residual with progress.
    // Late in stream, tight fits matter more; small post_residual heavily rewarded.
    let tightness = 1.0 - (post / cap);
    score -= 12.0 * tightness * tightness * (0.4 + 0.6 * progress);

    // Penalize leaving a residual that is awkward: near-miss zones (just below typical item sizes)
    // approximated smoothly via a sinusoidal "wasted space" wave.
    let waste_wave = (post / cap * std::f64::consts::PI).sin();
    score += 6.0 * (1.0 - waste_wave.abs()) * (post / cap);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Penalize opening a new bin when other bins can fit the item.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin && fitting_bins_count > 0 {
        // Higher penalty when mean residual across open bins is large (bins are underused).
        let mean_norm = (mean_residual / cap).clamp(0.0, 1.0);
        score += 18.0 + 30.0 * mean_norm * (0.5 + 0.5 * progress);
    }

    // Lookahead coupling: reward if next item could fit the post-residual exactly-ish.
    if next_item_size > 0 {
        let gap = (post - next_item_size as f64).abs();
        score -= 8.0 * (1.0 - gap / cap).max(0.0);
        // Penalize leaving residual just below the next item size (dead space).
        if post < next_item_size as f64 {
            score += 4.0 * (1.0 - post / cap);
        }
    }

    // Mild preference to fill already-open bins rather than proliferate bins late in the stream.
    score += 0.15 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, "usable" remainders
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // modulo classes: remainders divisible by common small sizes are reusable
        if pr % 10 == 0 { score -= 12.0; }
        if pr % 5 == 0 { score -= 5.0; }
        if pr % 25 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        // dead-space penalty: tiny unusable remainders
        if pr < 10 {
            score += (10 - pr) as f64 * 3.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 80.0;
        } else if next_item_size < pr {
            score -= (next_item_size as f64 / cap) * 25.0;
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += ((next_item_size - pr) as f64 / cap) * 10.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize new-bin opening unless existing fit is terrible
    if bin_residual == bin_capacity {
        score += 55.0;
        if open_bins_count == 0 {
            score -= 100.0; // must open first bin
        }
        // as stream progresses, be more reluctant to open bins
        let prog = step_index as f64 / (total_items.max(1) as f64);
        score += prog * 30.0;
    }

    // Prefer bins tighter than the mean residual (good packing)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Integer-division threshold: bins whose residual is in "harmonic" low band
    let band = pr / 10; // 0..10 bands
    score += band as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 - 5.0 * post_residual as f64;
    }
    // Dead space that cannot fit the next item is also wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward tight fits (small post_residual relative to item).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Pressure from number of open bins: discourage spreading across many bins,
    // but a last-chance bin (only fitting bin) is strongly favored.
    score += 2.5 * open_bins_count as f64;
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New empty bin candidate: usually worse than reusing, unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Favor new bin late in stream if mean residual is fragmented.
        if mean_residual > 0.0 && mean_residual < 20.0 {
            score -= 25.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidation).
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    // Slight progression term: early on, be conservative about opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let next = next_item_size as f64;

    // Base: penalize wasted residual space (tight fits preferred).
    let mut score = post;

    // Aggressive 2-step lookahead: reward post_residual matching next item size.
    if next_item_size > 0 {
        let match_err = (post - next).abs();
        // Perfect two-item fill (post == next): strong bonus.
        if match_err < 0.5 {
            score -= 40.0;
        } else {
            // Gradient: closer match gets more reward, normalized by capacity.
            score -= 20.0 * (1.0 - match_err / cap);
        }
        // Penalize residual that neither fits the next item well nor stays useful.
        if post > 0.0 && post < next {
            // Dead space relative to lookahead: can't host next item.
            score += 0.5 * (next - post);
        }
    } else {
        // Last item: simply prefer minimal residual.
        score += 5.0;
    }

    // Compare against mean residual across open bins: placing into a bin
    // whose residual is near mean keeps balance; deviating bins get penalty.
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * mean_gap;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // would leave large unusable residual or too many bins already open.
    if bin_residual == bin_capacity {
        let waste_penalty = if next_item_size > 0 {
            (post - next).abs().min(60.0)
        } else {
            0.0
        };
        score += 25.0 + 0.5 * waste_penalty - 2.0 * open_bins_count as f64;
    }

    // Mild progression term: later in stream, prefer tighter packing.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Core: penalize large post-residual non-linearly (dead space is superlinear bad).
    score += 0.35 * (post / cap).powi(2) * cap;

    // Reward tight fits (small post residual relative to item).
    if post > 0.0 {
        score -= 12.0 * (item / post).min(8.0);
    } else {
        score -= 40.0; // perfect fill
    }

    // Last-chance bin: strongly favor using it, else we open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 0.1 * (bin_residual as f64 - item);
    }

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Base cost of opening a bin; amortize over stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_cost = 18.0 + 20.0 * (1.0 - progress);
        // If other bins fit, discourage new bin unless their fits are terrible.
        if fitting_bins_count >= 1 {
            new_bin_cost += 15.0;
        }
        // More open bins with slack => prefer existing bins.
        new_bin_cost += 1.5 * open_bins_count as f64 * (mean_residual / cap).max(0.0);
        // If next item is large and this new bin would be roomy, slight bonus.
        if next_item_size > 0 && (next_item_size as f64) <= post {
            new_bin_cost -= 4.0;
        }
        score += new_bin_cost;
    } else {
        // Existing bin: reward leaving room compatible with the lookahead item.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            if (post - nxt).abs() < 3.0 {
                score -= 10.0; // post residual chains perfectly into next item
            } else if post >= nxt && post - nxt <= 10.0 {
                score -= 5.0;
            } else if post < nxt && post > 0.0 {
                // stranded space smaller than next item: penalize mildly
                score += 0.15 * (nxt - post);
            }
        }
        // Prefer bins whose residual is already below average (consolidate slack).
        let res = bin_residual as f64;
        if res < mean_residual {
            score -= 3.0 * (mean_residual - res) / cap;
        } else {
            score += 2.0 * (res - mean_residual) / cap;
        }
    }

    // Mild preference for bins that keep many future options (post residual not tiny-but-unusable).
    if post > 0.0 && post < 10.0 {
        score += 6.0; // small unusable scrap
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post_residual, with smooth polynomial coupling to stream progress.
    // Late in the stream, residual waste matters more, so weight grows smoothly.
    let progress_weight = 0.5 + 1.5 * progress * progress;
    let mut score = pr * progress_weight;

    // Non-linear penalty on very small post-residuals (dead space) —
    // a smooth quartic dip that punishes leaving tiny unusable fragments,
    // but only when the fragment is below a soft fraction of capacity.
    let tiny = (1.0 - pr_norm).min(1.0).max(0.0);
    score += 20.0 * tiny * tiny * tiny * tiny * pr_norm;

    // Reward tight fits: smooth gaussian-like bump around small post_residual.
    let tightness = (-pr_norm * pr_norm * 12.0).exp();
    score -= 10.0 * tightness * (0.5 + progress);

    // Lookahead coupling: if next item fits in the post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        let fit_frac = next_item_size as f64 / pr.max(1.0);
        score -= 8.0 * fit_frac * (1.0 - fit_frac) * 4.0 * (0.3 + 0.7 * progress);
    } else if next_item_size > 0 {
        // Next item won't fit: mild smooth penalty scaled by how much it misses.
        let miss = (next_item_size as f64 - pr) / cap;
        score += 6.0 * miss * miss;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // New-bin candidate handling: empty bins get a baseline cost that grows
    // with the number of open bins and mean residual availability.
    if bin_residual == bin_capacity {
        score = 30.0 + 2.0 * open_bins_count as f64 + 0.5 * mean_residual;
        // Early stream: opening bins is cheaper; late stream: prefer filling.
        score *= 1.2 - 0.5 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Residuals that are multiples of common item-size classes (mod 10, mod 25)
    // are more likely to be filled by future items.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -30.0 // perfect fit, best possible
    } else if pr % 10 == 0 {
        -8.0
    } else if pr % 5 == 0 {
        -4.0
    } else if pr <= 10 {
        12.0 // tiny sliver, nearly dead space
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Integer-division thresholds: classify post_residual into usefulness bands.
    let band = pr / 20; // 0..5
    score += match band {
        0 => 15.0,          // 1..19 : mostly dead space
        1 => 4.0,           // 20..39
        2 => -2.0,          // 40..59
        3 => -6.0,          // 60..79
        _ => -10.0,         // 80+  : very reusable
    } as f64;

    // Lookahead coupling: reward residuals that can host the next item exactly.
    if next_item_size > 0 {
        if pr >= next_item_size {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 25.0; // chain fit: next item seals this bin
            } else if slack <= 5 {
                score -= 10.0;
            } else {
                score -= 5.0 * (1.0 - slack as f64 / cap);
            }
        } else {
            // next item cannot go here; leftover must hold until later
            score += 3.0;
        }
        // modulo harmony between post_residual and next item's class
        if pr % 10 == next_item_size % 10 && pr >= next_item_size {
            score -= 3.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // competition: prefer tighter fits among many candidates
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // Prefer filling bins when many are open (bin-count pressure).
    score -= 1.5 * (open_bins_count as f64).ln().max(0.0);

    // Deviation from mean residual: prefer bins tighter than average.
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.15 * progress;

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let desperate = fitting_bins_count == 0
            || (post_residual == bin_capacity && item_size > 70);
        score = if desperate { 5.0 } else { score + 25.0 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder than linear.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 6.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize residual that cannot fit the lookahead item (dead space relative to next need).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.8;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 3.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when current bin leaves a bad gap.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
    }

    // Mild tie-break toward tighter fits early in stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (bin_residual - post_residual) as f64 * (0.1 - 0.05 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when the leftover exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // leftover can still host the next item: mild reward proportional to slack
            score -= 60.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space smaller than the next item: penalize strongly
            let waste = post_residual as f64;
            score += 25.0 + 3.0 * waste;
            // extra penalty if the dead space is below the minimum conceivable item size
            if post_residual < 10 {
                score += 50.0;
            }
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are "tight" -> prefer using them.
    let tightness = (mean_residual - post_residual as f64).max(0.0);
    score -= 1.5 * tightness;

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: make it unattractive unless the item is large relative to capacity
    // and no tight bin exists. Base penalty:
    if bin_residual == bin_capacity {
        score += 220.0;
        // but if the item is huge, opening a fresh bin is natural
        if item_size >= 70 {
            score -= 120.0;
        }
        // if all open bins are tight (mean residual small), opening may be fine
        if mean_residual < 20.0 && open_bins_count > 0 {
            score -= 100.0;
        }
    }

    // Slight stream-phase modulation: early on, be conservative with new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness ratio: how well the item fills the bin's current space
    let tightness = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };
    // Reward tight fits (subtract more for near-perfect fills)
    score -= 30.0 * tightness * tightness;

    // Dead-space penalty: tiny post_residual that nothing useful can fill
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // this placement chains perfectly; reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            // next item still fits: mild reward proportional to slack usage
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize more when post_residual is wasted
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 18.0 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate: opening a new bin is only attractive when existing
    // residuals are fragmented or the stream is near its end with big items.
    if bin_residual == bin_capacity {
        // Base mild penalty so tight fits into open bins usually win
        score += 10.0;
        // If mean residual is large (open bins are roomy), opening new bins is wasteful
        score += 0.15 * mean_residual;
        // But if open bins are nearly full and many items remain, allow new bins
        let roominess = mean_residual / bin_capacity as f64;
        if roominess < 0.15 {
            score -= 12.0;
        }
        // Late in the stream, avoid spawning bins that will stay mostly empty
        if progress > 0.8 {
            score += 8.0 * progress;
        }
        // Many open bins already: discourage further proliferation
        score += open_bins_count as f64 * 0.5;
    }

    // Global fragmentation pressure: when average residual is small, treasure
    // remaining space more; when residuals are large, be lenient.
    let scarcity = 1.0 - (mean_residual / bin_capacity as f64).min(1.0);
    score += 0.1 * post_residual as f64 * scarcity;

    // Mild preference to consolidate into fewer bins when many are open
    if open_bins_count > 3 && bin_residual != bin_capacity {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth polynomial coupling: reward tight fits with progress-dependent weight
    let tightness = (1.0 - x) * (1.0 - x);
    score -= 18.0 * tightness * (0.4 + 0.6 * progress);

    // Penalize mid-range dead space quadratically
    let dead = x * (1.0 - x) * 4.0; // peaks at x=0.5
    score += 6.0 * dead * (1.0 - progress);

    // Lookahead coupling: reward leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let compat = 1.0 - ((x - nx) * (x - nx)) * 4.0;
        if compat > 0.0 {
            score -= 10.0 * compat * nx;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Prefer bins with below-mean residual (fill fuller bins first), smoothly
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev - 3.0 * dev;

    // Mild penalty for spreading across many bins early
    score += 0.8 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let scarcity = 1.0 / fitting_bins_count.max(1) as f64;
        score += 12.0 - 14.0 * scarcity * (0.5 + progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo classes of capacity quarters
    let quarter = bin_capacity / 4;
    let class = (post_residual / quarter.max(1)) as f64;

    // Reward residuals that fall into "usable" harmonic classes (small multiples)
    let rem = (post_residual % quarter.max(1)) as f64;
    if rem == 0.0 && post_residual > 0 {
        score -= 12.0; // perfect quarter-class alignment: highly reusable
    } else {
        score += rem * 0.35; // penalize misaligned dead space
    }

    // Tight fit bonus: residual almost consumed
    if post_residual < 10 {
        score -= 25.0;
    }

    // Penalize large wasted space relative to capacity fractions
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 30.0;

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let nxt_class = (next_item_size % quarter.max(1)) == 0;
        score -= 10.0 + if nxt_class { 8.0 } else { 0.0 };
    } else if next_item_size > post_residual && next_item_size > 0 {
        // next item won't fit here; leftover becomes dead space unless small
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        score += 15.0 + mean_residual * 0.5;
        if post_residual as f64 > mean_residual * 1.5 {
            score += 10.0;
        }
    }

    // Mild preference to spread load across many open bins early in stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (1.0 - progress) * 0.05;

    // Integer division threshold on item size classes (large items pair better with small residuals)
    let item_class = item_size / quarter.max(1);
    score -= item_class as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize unusable small dead-space gaps (post_residual below min item size 1..100 -> treat <10 as dead)
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    } else if post_residual < 25 {
        score += 12.0;
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    }

    // Dead space if next item cannot fit into post_residual
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward if next item fits snugly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= (post_residual - next_item_size) as f64 * 0.3;
    }

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open bins pressure: more open bins -> prefer packing into existing bins, penalize new bin
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 + 15.0 * open_bins_count as f64 + 20.0 * progress;
    } else {
        score -= 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Prefer bins with residual below mean (tighter bins first)
    score += 0.2 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if next item fits exactly in post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here: penalize wasted residual proportional to gap
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize small dead residuals that are hard to fill later
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Relative to mean residual: prefer bins with below-average residual (tighter bins)
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer it only when current bin fit is poor
    if bin_residual == bin_capacity {
        score += 10.0;
        // opening new bin is attractive if lookahead mismatch on open bins
        if next_item_size > 0 && next_item_size > post_residual && post_residual < 20 {
            score -= 150.0;
        }
    }

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Tightness reward: strongly favor placements that nearly fill the bin.
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score -= 12.0 * (1.0 - tightness) * (1.0 - tightness);

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            // Next item fits: reward proportionally to how well it uses the leftover.
            let next_tight = (post_residual as f64 - nxt) / cap;
            score -= 6.0 * (1.0 - next_tight);
        } else {
            // Next item won't fit here: penalize leaving a residual that is
            // too small for the next item (dead space).
            score += 0.5 * (nxt - post) / cap * 20.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits very poorly in existing bins (large post residual waste)
    // or when few bins are open and the stream is early.
    if bin_residual == bin_capacity {
        // Cost of opening a new bin, softened early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_cost = 25.0 - 10.0 * (1.0 - progress);
        score += open_cost;
        // If the item perfectly fills a fresh bin, opening is great.
        if item_size == bin_capacity {
            score -= 1000.0;
        }
    }

    // Penalize bins whose residual is far below the mean residual
    // (i.e., this bin is already crowded; prefer spreading load).
    let dev = mean_residual - post;
    if dev > 0.0 {
        score -= 2.0 * dev / cap;
    } else {
        score += 1.0 * (-dev) / cap;
    }

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = pr + 12.0 * pr_norm * pr_norm * cap;

    // Smooth stream-progress coupling: late in stream, penalize waste more strongly
    score *= 1.0 + 0.8 * progress * progress;

    // Reward filling bins deeply (high fill fraction) with smooth term
    score -= 6.0 * fit_ratio * fit_ratio * cap;

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (1.0 - pr_norm) * (next_item_size as f64 / cap);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Penalize bins far from mean residual (fragmentation avoidance), smooth quadratic
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev * cap;

    // New-bin candidate: make it attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score = pr + 15.0 + 10.0 * progress + 3.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into tightness classes
    // via integer division thresholds (perfect fit, near-fit, half-class, loose).
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: ideal
    } else if pr <= 5 {
        score -= 45.0; // near-perfect: dead space negligible
    } else if pr <= 10 {
        score -= 25.0;
    } else if pr <= 20 {
        score -= 8.0;
    } else {
        // loose leftover: penalize extra beyond base residual
        score += (pr as f64 - 20.0) * 0.35;
    }

    // Half-capacity class: residual near C/2 is valuable for medium items
    let half = cap / 2.0;
    let pr_f = pr as f64;
    if (pr_f - half).abs() <= 5.0 {
        score -= 12.0;
    }

    // Lookahead coupling: reward leaving space exactly matching next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let diff = (pr_f - ns).abs();
        if pr >= next_item_size {
            // next item can fit here afterwards: strong reward scaled by closeness
            score -= 30.0 * (1.0 - diff / cap);
        } else {
            // leftover too small for next item: penalize proportional to waste
            score += 15.0 * (pr_f / cap);
        }
        // modulo class: next item in same decade class as item_size suggests batching
        if next_item_size / 10 == item_size / 10 && pr >= next_item_size {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Prefer filling fuller bins among many open bins (waste-avoidance)
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= 20.0 * fill_frac * fill_frac;

    // New-bin candidate: only attractive when no open bin fits decently
    // (signaled by large mean residual mismatch) or stream is early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 55.0;
        // discount when current item leaves awkward leftovers in any bin
        let awkward = if pr > 0 && pr < 10 { 0.0 } else { 1.0 };
        if mean_residual < item_size as f64 * 1.2 && awkward > 0.0 {
            score -= 50.0; // open bins barely fit: new bin reasonable
        }
        if open_bins_count == 0 {
            score -= 60.0;
        }
        // late in stream, prefer consolidating rather than opening
        score += 25.0 * progress;
    }

    // Mild preference for bins whose residual is harmonic with item size
    // (item divides residual classes: residual % item_size small => good tiling)
    if item_size > 0 {
        let m = (bin_residual % item_size) as f64;
        score -= 6.0 * (1.0 - m / item_size as f64);
    }

    // Small tie-break toward bins below mean residual (use the emptier ones less)
    score += 0.05 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..100 domain -> assume small gap threshold)
    // are unusable dead space; penalize quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * (10 - post_residual) as f64 * 4.0;
    }
    // Perfect fit: reward strongly.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Reward placements that leave room for the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
            // Extra reward if next item fits almost exactly (chain-friendly).
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 8.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Open-bins pressure: with many open bins, discourage spreading; prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (1.5 + progress * 2.0);

    // Pull score toward mean residual context: bins far below mean residual are already tight,
    // prefer them (lower residual = tighter bin = better fit).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let new_bin_base = bin_capacity as f64 - item_size as f64;
        score = new_bin_base + open_bins_count as f64 * 2.0 - 10.0;
        // If exactly one fitting bin exists, opening a new bin is rarely better.
        if fitting_bins_count >= 1 {
            score += 15.0;
        }
        // Early stream: opening bins is cheap-ish.
        score -= (1.0 - progress) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect 2-item packing: post_residual exactly matches next item.
            let slack = (post_residual - next_item_size) as f64;
            score -= 45.0 - slack.min(45.0);
            if post_residual == next_item_size {
                score -= 30.0; // exact chain fill
            }
        } else {
            // Dead space that next item cannot use: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.35 * waste;
        }
    } else {
        // Last item: prefer tightest fit.
        score -= 10.0;
    }

    // Relative to mean residual: bins below-average residual are "tight" — good to fill them.
    let residual_f = bin_residual as f64;
    let tightness = (mean_residual - residual_f) / bin_capacity as f64;
    score -= 25.0 * tightness;

    // Penalize large post_residual relative to bin capacity (wasteful placement).
    let pr = post_residual as f64;
    score += 0.15 * (pr / bin_capacity as f64) * (pr / bin_capacity as f64) * 100.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mildly discourage opening a new bin unless lookahead chain is bad.
    if bin_residual == bin_capacity {
        score += 12.0;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 8.0; // fresh bin could host a clean pair, but existing fits preferred
        }
        // Early in stream, allow opening bins more freely.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize dead space: residual left that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: reward if the post-residual can still fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0; // bin becomes useless for the known next item
        }
        // Bonus for a two-item perfect chain: item + next exactly filling residual
        if item_size + next_item_size == bin_residual {
            score -= 15.0;
        }
    }

    // Last-chance bonus: this is the only bin that fits; avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item fits poorly everywhere (large item, few fitting options).
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        let time_frac = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Penalize new bins generally, but relax when item is big, few bins fit,
        // or many bins are already open with large mean residual (fragmentation).
        let mut new_bin_cost = 30.0
            - 25.0 * pressure * scarcity
            - 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
        if mean_residual > 30.0 {
            new_bin_cost -= 5.0; // existing bins are fragmented anyway
        }
        if time_frac > 0.9 {
            new_bin_cost += 5.0; // late in stream, consolidate
        }
        score += new_bin_cost.max(2.0);
    }

    // Mild preference for bins already below mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post * (1.0 + 0.8 * progress * progress);

    // Non-linear coupling: waste penalized more when it can't hold a future item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > post {
            let unusable = (nxt - post) / cap;
            score += 12.0 * unusable * unusable * (1.0 + progress);
        } else {
            let fit_quality = post - nxt;
            score -= 6.0 * (1.0 - fit_quality / cap) * (1.0 - progress);
        }
    } else {
        // Last item: reward filling bins as tightly as possible
        score -= 8.0 * (1.0 - post / cap);
    }

    // Dead-space penalty: residuals that are too small to ever be useful
    let dead = (post / cap).powi(3);
    score += 15.0 * dead;

    // Last chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: prefer it only when it beats existing residuals,
    // penalize opening new bins when many bins are open with slack
    if bin_residual == bin_capacity {
        let spread = (mean_residual - post).abs();
        score += 4.0 + 0.5 * open_bins_count as f64 - 0.02 * mean_residual + 0.05 * spread;
        if progress > 0.8 {
            score -= 3.0 * progress;
        }
    } else {
        // Reward bins that are tighter than average
        let tightness = (mean_residual - post) / cap;
        score -= 2.0 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity split into 5 classes of 20.
    let class = post_residual / 20;
    score += match class {
        0 => -30.0,          // near-perfect fit: strongly reward
        1 => -8.0,
        2 => 0.0,
        3 => 8.0,
        _ => 18.0,           // large dead space: penalize
    };

    // Exact fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward small post_residual relative to item size (tightness ratio)
    if item_size > 0 {
        score -= 15.0 * (item_size as f64 / (item_size + post_residual) as f64);
    }

    // Last-chance bin: only one bin fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating residual too small for typical next item (harmonic class of next item)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0;
    }
    // Reward leaving room exactly for the next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // New-bin candidate: neutral-ish baseline, but discourage opening new bins
    // when a good fit exists (post_residual small) or when few bins are open.
    if bin_residual == bin_capacity {
        score += 5.0
            + 2.0 * open_bins_count as f64
            + 10.0 * (step_index as f64 / total_items.max(1) as f64);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            // new bin can host current + next: mild encouragement
            score -= 8.0;
        }
    }

    // Coupling with mean residual: prefer bins whose residual deviates below mean
    // (consolidate space into fewer bins).
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // Small late-stream tightening: as stream progresses, be pickier about dead space
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 6.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny post-residuals (< 10) are "dead space"
    // since item sizes can be as small as 1 in this interface; still, gaps that
    // cannot fit the next item are wasted. Penalize unusable gaps heavily.
    if next_item_size > 0 {
        if post_residual < next_item_size && post_residual > 0 {
            // Gap too small for the lookahead item -> dead space penalty,
            // stronger the smaller (more useless) the gap is.
            let deadness = 1.0 - (post_residual as f64 / next_item_size as f64);
            score += 30.0 + 40.0 * deadness;
        } else if post_residual >= next_item_size {
            // Reward leaving a gap that still accommodates the next item,
            // especially a snug one (low slack after the hypothetical next item).
            let slack_after_next = post_residual - next_item_size;
            score -= 12.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: just fill as tightly as possible.
        score -= 15.0;
    }

    // Perfect / near-perfect fit reward.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 2 {
        score -= 25.0;
    }

    // Last-chance pressure: if this is the ONLY bin that fits the item,
    // strongly prefer using it over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: discourage proliferation of open bins; the more bins
    // already open, the stronger the push to consolidate into existing ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64).ln() * (1.0 + 2.0 * progress);
    score += pressure * 3.0;

    // New-bin candidate (empty bin): make it attractive only when the item is
    // large relative to capacity or no good consolidation exists. Base cost of
    // opening a bin, discounted when item is big.
    if bin_residual == bin_capacity {
        let size_frac = item_size as f64 / bin_capacity as f64;
        score = 45.0 - 30.0 * size_frac;
        // If other bins fit and mean residual is large, opening a new bin is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * (mean_residual / bin_capacity as f64).min(1.0);
        }
    } else {
        // Favor bins whose residual is close to what we consume (tight packing)
        // relative to the fleet mean residual.
        score += 5.0 * ((bin_residual as f64 - mean_residual) / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good.
    let progress = step_index as f64 / total_items.max(1) as f64;

    // 2-step lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // partial fit: penalize by leftover after next item
            let leftover_after_next = post_residual - next_item_size;
            score += leftover_after_next as f64 * 0.3;
        } else {
            // next item cannot use post_residual; penalize dead space
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Penalize creating dead space below typical small-item threshold (unusable gap).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Prefer bins tighter than the mean residual (good packing).
    score += (post_residual as f64 - mean_residual) * 0.2;

    // Mild early-stream bonus for opening/keeping bins flexible; later, prefer consolidation.
    score += progress * 5.0;

    // Discourage opening new bins when many bins already fit the item.
    if bin_residual == bin_capacity {
        score += (fitting_bins_count as f64) * 8.0;
        if open_bins_count == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits (best-fit core with sharpening).
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 2.5 * tightness * tightness * bin_capacity as f64;

    // Reward near-perfect fills aggressively.
    if post_residual < 8 {
        score -= 40.0 + (8 - post_residual) as f64 * 6.0;
    } else if post_residual <= 15 {
        score -= 12.0;
    }

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead coupling: favor bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0 + (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // leftover cannot host next item: mild penalty scaled by gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
        // Perfect two-item chaining bonus
        if post_residual == next_item_size {
            score -= 30.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: only attractive when open bins are crowded or fit is poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        let poor_alternatives = if fitting_bins_count == 0 { 60.0 } else { 0.0 };
        let big_item_pull = item_size as f64 * 0.5;
        let _ = progress;
        score = 20.0 + crowded * 2.0 - big_item_pull
            + if next_item_size > 0 && next_item_size >= bin_residual { 0.0 } else { 5.0 }
            + poor_alternatives;
        // Discard new bins late when many bins still have room.
        if mean_residual > item_size as f64 * 2.0 {
            score += 30.0;
        }
    }

    // Mild global pressure: many open bins with high mean residual -> consolidate.
    if bin_residual != bin_capacity {
        let pressure = (open_bins_count as f64).ln() * (mean_residual - post_residual as f64).abs() * 0.05;
        score += pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear coupling of post_residual with stream progress:
    // early on, tolerate loose residuals; later, punish them harder.
    let progress_coupling = progress * post * (post / cap);
    score += 0.6 * progress_coupling;

    // Quadratic dead-space penalty: residuals that are too small to fit
    // typical future items are wasted space.
    let dead = post * post / cap;
    score += 0.25 * dead * (0.5 + progress);

    // Reward tight fits (small post_residual) with a smooth saturating term.
    let tightness = 1.0 - (post / cap);
    score -= 8.0 * tightness * tightness * tightness;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 12.0;
    } else {
        // More competing bins -> slight penalty for wasting a scarce fit.
        score += 0.5 * (fitting_bins_count as f64 - 1.0).min(5.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        let match_quality = 1.0 - ((post - next_item_size as f64) / cap).abs();
        score -= 4.0 * match_quality * match_quality;
    } else if next_item_size > 0 {
        // Next item cannot use this residual: mild penalty scaled by progress.
        score += 1.5 * progress;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the
    // item is large relative to capacity (smooth, not piecewise).
    let is_new_bin = (bin_residual as f64 - cap).abs() < 0.5;
    if is_new_bin {
        let item_frac = item_size as f64 / cap;
        score += 6.0 * (1.0 - item_frac) * (1.0 + progress);
    }

    // Mild preference to fill bins with larger residuals when many are open.
    score += 0.15 * (mean_residual - post) * (open_bins_count as f64).sqrt().min(4.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual (capacity fractions)
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Perfect-fit class: exact closure of the bin
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Near-perfect class: post residual belongs to small dead-space class
    else if post_residual <= 5 {
        score -= 300.0;
    }
    // Mid classes via integer division thresholds on post_residual
    let class = post_residual / 10; // decile class
    match class {
        0 => score -= 150.0,
        1 => score -= 60.0,
        2 => score -= 20.0,
        3 => score += 10.0,
        4 => score += 25.0,
        _ => score += 40.0,
    }

    // Modulo coupling: post_residual that is compatible with common item sizes (10..80)
    let compat = |r: u32| -> bool {
        (10..=80).contains(&r) || r == 0
    };
    if compat(post_residual) {
        score -= 35.0; // residual re-usable by a future item directly
    }
    // Harmonic residue check: post_residual mod 10 == 0 keeps alignment with item grid
    if post_residual % 10 == 0 {
        score -= 15.0;
    } else {
        score += (post_residual % 10) as f64 * 2.0;
    }

    // Lookahead coupling: can next item fill this bin's post residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0; // chain closure
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
        } else {
            score += 20.0; // next item cannot use this residual
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate handling: only open a new bin when current fit is terrible
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: neutral post residual = capacity
        score = cap * 0.75;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 30.0;
        }
        if fitting_bins_count <= 1 {
            score -= 200.0; // nothing else fits well; opening is fine
        }
    }

    // Progress pressure: later in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 20.0 * (1.0 - frac);

    // Mean-residual divergence: penalize bins far from the fleet mean
    score += (pr - mean_residual).abs() * 0.3;

    // Too many open bins: reward closing/reusing existing ones
    score -= (open_bins_count as f64).ln().max(0.0) * (cap - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize residuals that are too small to be
    // usable by typical future items (unusable gap < ~10% of capacity).
    let dead_threshold = bin_capacity as f64 * 0.10;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 4.0;
    }

    // Reward near-perfect fits (small post_residual) super-linearly.
    if post_residual <= 5 {
        score -= 15.0;
    } else if post_residual <= 15 {
        score -= (15.0 - post_residual as f64) * 0.8;
    }

    // Penalize large wasted capacity: post_residual far above item needs
    // means this bin was too empty; prefer tighter bins (best-fit bias).
    score += (bin_residual as f64 - item_size as f64).max(0.0) * 0.15;

    // Open-bin pressure: with many open bins, avoid spreading; favor filling
    // existing bins over opening new ones.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate handling: only attractive if current bins fit badly
    // (dead space would be created) or few fitting options exist.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by pressure.
        score = bin_capacity as f64 * 0.55 + open_bins_count as f64 * 0.8;
        // If this is the last-chance bin, opening new is relatively better.
        if fitting_bins_count <= 1 {
            score -= 20.0;
        }
        // If lookahead item is small, a fresh bin is more flexible.
        if next_item_size > 0 && (next_item_size as f64) < mean_residual {
            score -= 8.0;
        }
    }

    // Last-chance fitting bin: strongly favor using it to avoid new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post_residual, reward it.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 6.0;
        // Extra reward for near-exact lookahead fit.
        let slack = post_residual as f64 - next_item_size as f64;
        if slack < 10.0 {
            score -= 5.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; mild penalty scaled by wasted opportunity.
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.1;
    }

    // Slight progression-aware tightening: late in the stream, be greedier
    // about filling bins tightly (dead space matters more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness: reward near-perfect fills (post_residual close to 0).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Aggressive 2-step lookahead: does the NEXT item fit exactly into the post_residual?
    if next_item_size > 0 && post_residual > 0 {
        let slack = (post_residual as i64 - next_item_size as i64) as f64;
        if slack == 0.0 {
            // Perfect chaining: next item exactly fills the remainder.
            score -= 45.0;
        } else if slack > 0.0 {
            // Next item fits: reward proportional to how snug the chain is.
            let snug = 1.0 - slack / (bin_capacity as f64);
            score -= 25.0 * snug * snug;
        } else {
            // Next item will NOT fit here: penalize leaving a gap smaller than
            // the next item (dead space), scaled by how close the gap is.
            let dead = -slack / (bin_capacity as f64);
            score += 18.0 * dead * dead;
        }
    }

    // Compare post_residual to the mean residual of open bins: leaving more
    // residual than average spreads capacity poorly.
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);
    score -= 0.15 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let pressure = if next_item_size > 0 {
            (item_size + next_item_size) as f64 / bin_capacity as f64
        } else {
            item_size as f64 / bin_capacity as f64
        };
        // New bin is attractive only if the item nearly empties it or few bins are open.
        score += 25.0 * (1.0 - pressure);
        score -= 10.0 * (open_bins_count as f64).recip();
        score -= 15.0 * progress * pressure;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor placements that leave little dead space.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Perfect or near-perfect fill is extremely desirable.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual < 10 {
        // Residual below min item size is dead space; mild penalty handled by base.
        score += 5.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0;
        } else {
            // Next item won't fit here; leaving large residual is wasted potential.
            let waste = post_residual as f64 / bin_capacity as f64;
            score += 10.0 * waste;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when existing fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Early in the stream, opening bins is cheaper (builds a pool).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
        // If few bins fit the item, new bin is more attractive.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // If open bins have lots of mean residual, prefer using them.
        score += 0.3 * mean_residual;
        // Large items prefer fresh bins (less fragmentation risk).
        if item_size >= 60 {
            score -= 15.0;
        }
    } else {
        // Using an existing bin: penalize proportional to fragmentation created.
        let frag = post_residual as f64 / bin_capacity as f64;
        score += 8.0 * frag;
        // Slight reward for keeping number of open bins low.
        score -= 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Late in stream, consolidate: prefer filling existing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early: prefer tight fits (penalize large residuals quadratically).
    // Late: tolerate residual since fewer future items remain to use it.
    let tightness = (pr / cap).powi(2);
    let decay = 1.0 - progress * progress; // smooth 1 -> 0
    score += 6.0 * tightness * decay;

    // Cubic interaction: mid-stream extra pressure on wasted space.
    let mid = progress * (1.0 - progress);
    score += 8.0 * mid * (pr / cap);

    // Lookahead: reward residuals that can host the next item (smooth kernel).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let gap = (pr - n) / cap;
        let kernel = (-gap * gap * 20.0).exp();
        score -= 5.0 * kernel;
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Penalty for scattering across many open bins relative to mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual - pr).abs() / cap;

    // Slight bonus for near-perfect fills.
    score -= 3.0 * (-(pr / cap) * 10.0).exp();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: residues modulo 10 and capacity fractions
    let cap_frac = post_residual as f64 / bin_capacity as f64;
    let res_mod = (post_residual % 10) as f64;

    // Reward near-perfect fits (post_residual in a "harmonic" small class)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 8.0;
    } else {
        // Penalize large dead space, worse if residue is awkward (not divisible by 10)
        score += cap_frac * 25.0 + (10.0 - res_mod) * 0.8;
    }

    // Harmonic compatibility: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            if slack <= 10 {
                score -= 18.0;
            } else {
                score -= 5.0 - (slack as f64 / bin_capacity as f64) * 10.0;
            }
        } else {
            // next item cannot use this bin's residue: mild penalty scaled by waste
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    } else {
        // last item: prefer filling existing bins as tightly as possible
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin
    if fitting_bins_count == 1 {
        score -= 22.0;
    }

    // New-bin candidate: penalize opening a bin when good fits exist,
    // unless current bin would leave a large awkward residue
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
        score += 30.0 + progress * 10.0 - pressure.min(20.0);
        // opening a new bin is acceptable if the current best residual would be terrible
        if post_residual >= bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Slight preference for bins with residual far below mean (tight bins first)
    score += (mean_residual - bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals in the "unusable gap" band
    // (small leftover that few future items can use) are heavily penalized.
    // Non-linear penalty peaking for post_residual in [1, 25].
    let pr = post_residual as f64;
    if post_residual > 0 {
        let dead_zone_center = 12.0;
        let width = 14.0;
        let deadness = (-(pr - dead_zone_center).powi(2) / (2.0 * width * width)).exp();
        score += 45.0 * deadness * (1.0 + 0.5 * (step_index as f64 / total_items.max(1) as f64));
    } else {
        // Perfect fill: strong reward.
        score -= 30.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open bins count pressure: with many open bins, consolidate; with few,
    // spreading is less costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (mean_residual / 10.0 + 1.0);
    score += 0.15 * pressure;

    // Lookahead: if the next item could exactly use the post residual,
    // reward leaving that gap; if next item cannot fit the residual anyway,
    // penalize creating stranded space.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0; // perfect chaining opportunity
        } else if next_item_size > post_residual && post_residual < 10 {
            score += 20.0; // stranded dead space below minimum item size
        } else if next_item_size <= post_residual {
            score -= 8.0; // residual still usable by next item
        }
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (fitting_bins_count == 0 means only the new bin is viable, but if some
    // bins fit, opening a new one should carry a moderate cost) scaled by
    // how much residual the fleet already has.
    if bin_residual == bin_capacity {
        let fleet_slack = mean_residual * open_bins_count as f64;
        score += 12.0 + 0.05 * fleet_slack;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin helps large upcoming items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit for the next item: strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    // Next item fits into the post residual: mild reward scaled by tightness.
    if next_item_size > 0 && post_residual >= next_item_size {
        let tight = (post_residual - next_item_size) as f64;
        score -= 12.0 - tight * 0.25;
    }
    // Dead space: residual too small for the smallest plausible item (1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Penalize post residual far below mean residual (wasted large bin space).
    score += ((mean_residual - post_residual as f64).max(0.0)) * 0.15;

    // Last-chance bin: reward strongly to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless nothing fits well.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += pressure + open_bins_count as f64 * 2.0;
        // If next item is huge and current residual small, opening fresh bin is ok.
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 35.0;
        }
    }

    // Mild late-stream consolidation: favor tighter bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (bin_residual as f64 - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else {
        let tight = post_residual as f64 / bin_capacity as f64;
        score -= (1.0 - tight) * 25.0;
        // Dead space penalty: residuals too small for the smallest item are wasted.
        if post_residual < 10 {
            score += 30.0;
        }
    }

    // Lookahead: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many fitting bins: mild penalty to prefer tighter bins (already via post_residual).
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate logic: open a new bin only when open bins are quite full
    // on average or late in the stream when consolidation matters.
    if bin_residual == bin_capacity {
        let avg_fullness = 1.0 - mean_residual / bin_capacity as f64;
        let urgency = progress * 0.5 + avg_fullness * 0.5;
        if urgency > 0.55 {
            score -= 10.0 + 20.0 * urgency;
        } else {
            score += 15.0 * (1.0 - urgency);
        }
        // Slight penalty for proliferating bins early.
        score += 0.3 * open_bins_count as f64 * (1.0 - progress);
    } else {
        // Prefer bins whose residual deviates favorably from the mean (more packed).
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Late-stream consolidation: favor filling existing bins harder.
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: dead space hurts more as it grows and late in the stream.
    let waste_frac = pr / cap;
    score += 12.0 * waste_frac * waste_frac * (1.0 + 2.0 * progress);

    // Reward tight fits (small post_residual) with a smooth quadratic bonus.
    score -= 6.0 * (1.0 - waste_frac) * (1.0 - waste_frac);

    // Coupling with mean residual: prefer bins whose residual is below mean (denser bins).
    let diff = mean_residual - pr;
    score += 0.08 * diff * diff.abs().sqrt() * (diff.signum());

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits into post_residual; penalize otherwise.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr as u32 >= next_item_size {
            score -= 8.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 5.0 * (nx / cap) * (0.5 + progress);
        }
    }

    // New-bin candidate: make it attractive only when existing fits are poor,
    // i.e., when post_residual would leave a large unusable gap.
    if bin_residual == bin_capacity {
        score = 0.5 * cap + 0.3 * pr - 10.0 * progress;
        // Deter opening new bins when many bins are already open and fit is decent.
        score += 4.0 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // fraction of capacity left after placement

    // Integer division thresholds on post_residual (classes of size 10)
    let class = post_residual / 10;
    match class {
        0 => score -= 25.0,                 // near-perfect fit: strongly reward
        1 => score -= 15.0,                 // excellent fit
        2 => score -= 8.0,                  // good fit
        3 => score -= 3.0,                  // acceptable
        4 | 5 => { score += 2.0; }          // mediocre dead space
        6 | 7 => { score += 8.0; }          // large dead space
        8 | 9 => { score += 15.0; }         // nearly empty bin wasted
        _ => { score += 20.0; }
    }

    // Modulo arithmetic: bins whose residual is divisible by common item sizes
    // (10, 20, 25, 50) are more likely to be filled exactly later.
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 4.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        if post_residual % 50 == 0 { score -= 3.0; }
    }

    // Lookahead coupling: reward residuals that exactly fit the next item
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual >= next_item_size && (post_residual - next_item_size) <= 10 {
            score -= 10.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            // residual too small for next item: penalize proportionally
            score += (next_item_size as f64 - pr) * 0.3;
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current item is large
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let large_item = item_size as f64 > 0.6 * cap;
        if large_item || fitting_bins_count == 0 {
            score -= 5.0;
        } else {
            score += 10.0 + 15.0 * (1.0 - progress);
        }
    }

    // Dead-space penalty scaled by how unusable the remainder is
    if post_residual > 0 && post_residual < 10 {
        score -= 10.0; // tiny remainder is effectively a perfect fit
    }

    // Slight preference for tighter bins overall
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    } else if post_residual == 0 {
        // Perfect fit is the ideal outcome.
        score -= 25.0;
    } else if post_residual <= 20 {
        // Moderately small gaps are risky dead space.
        score += 0.8 * (20.0 - post_residual as f64);
    }

    // Reward tight fits (item fills most of the bin).
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 10.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins
    // unless the fit is good (dead-space penalties dominate).
    score += 0.6 * open_bins_count as f64;

    // Prefer bins whose residual deviates from the mean in a useful way:
    // a below-mean residual bin that still fits is nearly full -> good.
    if (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        } else if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 10.0; // next item cannot use this gap -> dead space
        }
    }

    // New-bin candidate: keep it competitive only when open bins would
    // create bad dead space; otherwise opening bins freely is wasteful.
    if bin_residual == bin_capacity {
        score += 12.0 + 2.5 * open_bins_count as f64;
        if fitting_bins_count == 1 {
            score -= 35.0; // still allow escape hatch when it's the only option
        }
    }

    // Slight stream-position adaptation: later in the stream, consolidate
    // more aggressively (fewer residual bins left to juggle).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 2.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect chain
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 20.0 * (1.0 - chain_waste as f64 / (bin_capacity as f64));
        } else {
            // next item cannot fit here; penalize leaving awkward gap
            let gap = post_residual as f64;
            score += 0.05 * gap;
            if gap < next_item_size as f64 {
                score += 3.0; // dead space relative to lookahead
            }
        }
    }

    // Penalize residual far from mean (avoid fragmenting bins vs pool)
    score += 0.08 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless it enables a chain
    if bin_residual == bin_capacity {
        score += 8.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 4.0;
        }
        // late in stream, prefer reusing open bins
        let progress = step_index as f64 / total_items as f64;
        score += 6.0 * progress;
    }

    // Mild penalty for many open bins (consolidation pressure)
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 5 {
        score -= 10.0;
    }

    // Penalize dead space: residual too small to fit typical future items
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // unusable sliver
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
        // chain fit quality
        let chain_left = post_residual - next_item_size;
        if chain_left < 10 {
            score -= 6.0; // chain nearly exhausts bin
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // post_residual too small for next item: mild penalty unless it's a sliver
        score += 3.0;
    }

    // New-bin candidate logic: opening a new bin wastes capacity; penalize unless
    // current bin would leave a large awkward residual or bin is nearly full anyway.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin scaled by how much capacity is typically wasted
        score = 60.0;
        // cheaper to open new bin late in the stream (less future to serve)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * progress;
        // if many open bins already, spreading load may help
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
        // if next item is large and won't fit current bin after placement, new bin more attractive
        if next_item_size > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
        // if the item is huge relative to capacity, new bin is fine
        if item_size >= bin_capacity * 3 / 4 {
            score -= 8.0;
        }
    } else {
        // penalize leaving a big residual that nothing may fill
        let waste = post_residual as f64 / bin_capacity as f64;
        if waste > 0.5 {
            score += 10.0 * (waste - 0.5);
        }
        // mild preference for bins below mean residual (balance load)
        score += 0.05 * (bin_residual as f64 - mean_residual);
        // many fitting bins: less urgency, slight penalty to discourage hoarding residuals
        if fitting_bins_count > 3 {
            score += 2.0;
        }
    }

    // Early stream: encourage keeping residuals large and flexible
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_post = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;

    // Base: penalize post residual, with progress-dependent curvature
    let mut score = pr * (0.5 + 1.5 * p2 + 2.0 * p3);

    // Smooth interaction: normalized post residual squared, modulated by progress
    score += norm_post * norm_post * cap * (0.3 + 0.7 * progress);

    // Reward tight fits via smooth sigmoid-like term on post residual
    let tightness = (cap - pr) / cap; // fraction filled after placement
    score -= 30.0 * tightness * tightness * (1.0 + progress);

    // Penalize dead space relative to mean residual, smoothed coupling
    score += (pr - mean_residual).abs() * (0.2 + 0.6 * p2);

    // Lookahead: reward leaving room for the next item (smooth)
    let n = next_item_size as f64;
    if n > 0.0 {
        let fit = (pr - n).max(0.0) / cap;
        let miss = if pr < n { 1.0 } else { 0.0 };
        score -= 10.0 * (1.0 - fit) * (1.0 - miss) * (0.5 + progress);
        score += 15.0 * miss * (1.0 + p2);
    }

    // Last-chance bin: strong smooth reward to use it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    }

    // New-bin candidate: mild penalty so it's chosen only for poor fits
    if bin_residual == bin_capacity {
        score += 8.0 * (1.0 + progress);
    }

    // Mild penalty for too many open bins, smooth in progress
    score += open_bins_count as f64 * (0.1 + 0.4 * p2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residual mod 25 defines "waste classes"
    let post_class = post_residual % 25;
    // Residuals in {0, 25, 50, 75} are harmonically aligned (easy to fill later)
    let aligned = (post_class == 0) as f64;
    score -= 14.0 * aligned;

    // Penalize awkward dead space: post_residual in 1..10 is nearly unusable
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    }
    // Sweet spot residuals 25..=50 are highly reusable
    if post_residual >= 25 && post_residual <= 50 {
        score -= 10.0;
    }

    // Integer division thresholds: post_residual / 20 tier reward
    let tier = post_residual / 20;
    score -= 3.0 * tier as f64;

    // Lookahead coupling: does next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0;
            // Exact harmonic match bonus: post_residual - next is aligned or zero
            let gap = post_residual - next_item_size;
            if gap % 25 == 0 || gap == 0 {
                score -= 8.0;
            }
        } else {
            // Next item won't fit here; penalize proportionally to overshoot
            score += 4.0 + (next_item_size - post_residual) as f64 * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // New bins cost more early when open bins are few; discourage mid-stream hoarding
        score += 18.0 + 10.0 * (1.0 - progress) - 0.5 * open_bins_count as f64;
        // If mean residual across open bins is large, opening new bin is wasteful
        score += mean_residual * 0.25;
        // But if item is large relative to capacity, fresh bin is fine
        score -= (item_size as f64 / cap) * 15.0;
    }

    // Mild preference for tighter bins when many bins are open (reduce fragmentation)
    score += (mean_residual - post_residual as f64) * 0.05;

    // Fraction-of-capacity fill reward: item/capacity quartile bonus
    let q = (item_size * 4) / bin_capacity;
    score -= 2.0 * q as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small positive post_residual gaps are hard to fill later.
    if post_residual > 0 {
        let dead_threshold = 12.0;
        if (post_residual as f64) < dead_threshold {
            score += (dead_threshold - post_residual as f64) * 6.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly fits the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // gap too small for the next item: penalize
    }

    // Last-chance bonus: only one bin can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Pressure on number of open bins: prefer tighter bins when many are open.
    score += open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64) * 4.0;

    // Mild preference for bins below mean residual (consolidate slack).
    score += (mean_residual - post_residual as f64) * 0.2;

    // New-bin candidate: keep neutral-ish but slightly penalized so we only
    // open a new bin when existing bins have bad fits.
    if bin_residual == bin_capacity {
        score += 30.0 + open_bins_count as f64 * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact-fit reward: minimal waste is best.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Aggressive 2-step lookahead: reward when post_residual exactly matches
    // next item size (perfect chain), penalize near-misses that strand space.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64 - nxt).abs() < 0.5 {
            score -= 45.0;
        } else if post_residual as u32 >= next_item_size {
            // Next item still fits here: mild reward proportional to tightness.
            score -= (post_residual as f64 - nxt).max(0.0).min(30.0) * 0.4;
        } else {
            // Next item won't fit after this placement: penalize dead space
            // that is too small to be useful for typical items.
            if post_residual < 10 {
                score += 25.0;
            }
        }
    }

    // Tightness relative to mean residual: prefer bins tighter than average
    // (concentrate waste), penalize placing into already-loose bins.
    let tight = post_residual as f64 - mean_residual;
    score += tight * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current placement
    // would be very wasteful (post_residual large and unusable).
    if bin_residual == bin_capacity {
        let waste_pressure = (post_residual as f64 / bin_capacity as f64) * 100.0;
        score += 30.0 - waste_pressure * 0.5;
        // Early in stream, new bins are cheap; late, avoid proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 15.0;
        // Many open bins: discourage opening more.
        score += open_bins_count as f64 * 2.0;
    }

    // Slight preference for filling larger items into tighter bins overall.
    score += (item_size as f64 / bin_capacity as f64) * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space, scaled by capacity.
    let waste = post_residual as f64 / bin_capacity as f64;
    score += waste * waste * 60.0;

    // Perfect or near-perfect fit gets strong bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 + (next_item_size as f64) * 0.15;
        } else {
            // Dead space for the known next item: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64) * 0.25;
        }
    }

    // Compare against mean residual: bins with residual far from mean are
    // either nearly full (good to fill) or oddly empty (leave flexible).
    let dev = bin_residual as f64 - mean_residual;
    if dev < 0.0 {
        score += dev * 0.10; // fuller than average: slight extra reward
    } else {
        score += dev * 0.05; // emptier than average: mild penalty
    }

    // Time horizon: early in the stream, keep bins flexible (favor larger
    // residuals); late in the stream, prioritize consolidation.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * post_residual as f64 * 0.08;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.05;

    // Many open bins: encourage filling existing ones over opening new.
    if open_bins_count > 3 {
        score -= (open_bins_count.min(20) as f64) * 0.8;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (post_residual would be large) or stream is early with few bins.
    if bin_residual == bin_capacity {
        let openness = (1.0 - progress) * 10.0;
        score += 25.0 - openness - (open_bins_count.min(10) as f64) * 1.5;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: post_residual penalized more heavily as stream progresses
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Polynomial dead-space penalty: small post_residuals are good unless too small to be useful
    score += 40.0 * norm_pr * norm_pr * (1.0 - norm_pr);

    // Reward tight fits (small post residual) with smooth decay
    score -= 25.0 * (-norm_pr * 6.0).exp();

    // Lookahead coupling: reward if next item fits the post residual (smooth interaction)
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 12.0 * (1.0 - (next_item_size as f64 / cap)) * (0.5 + 0.5 * progress);
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new one
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (encourage balance)
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // New-bin candidate: penalize slightly so we prefer existing bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 30.0 - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo-10 bands.
    // Residuals that are small multiples of 10 are "harmonic" — future items
    // (sizes 10..80) can land on them exactly. Penalize off-class residuals.
    let resid = post_residual;
    let class = resid % 10;
    if resid > 0 {
        score += match class {
            0 => -14.0,                       // perfectly harmonic residual
            1 | 2 | 8 | 9 => 6.0,             // nearly useless sliver or awkward
            3 | 4 | 5 | 6 | 7 => 2.0,         // mediocre
            _ => 0.0,
        };
    }

    // Integer-division thresholds: how many "average" future items fit.
    let avg_item = 45u32;
    let slots = resid / avg_item;
    score -= 5.0 * slots as f64;

    // Lookahead coupling: does post_residual exactly (or nearly) fit next item?
    if next_item_size > 0 {
        if next_item_size == resid {
            score -= 30.0; // perfect two-item chain
        } else if next_item_size <= resid {
            let gap = resid - next_item_size;
            if gap % 10 == 0 { score -= 12.0; } else { score += gap as f64 * 0.15; }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size - resid).min(40) as f64 * 0.3;
        }
    }

    // Dead-space penalty: tiny residuals that no item (min size 1) wastes.
    if resid > 0 && resid < 4 {
        score += 20.0;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins
    // are badly fragmented (high mean residual spread) or late in stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - (bin_capacity as f64 - item_size as f64)).abs();
        // Base cost of a fresh bin, discounted when open bins are messy.
        score += 60.0 - 0.4 * fragmentation - 20.0 * progress;
    } else {
        // Reward tight fits in existing bins (small post_residual).
        score -= (bin_capacity - post_residual) as f64 * 0.1;
        // Slight preference for bins below mean residual (balancing).
        if (post_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    // Open-bin pressure: many open bins -> discourage new bins implicitly
    // via existing-bin bonus.
    score -= 0.2 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual that cannot plausibly hold a future item is dead space.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < 15.0 + 10.0 * progress {
        score += 60.0 + (15.0 - post_residual as f64) * 4.0;
    }

    // Reward residuals that can still fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0 + next_item_size as f64 * 0.3;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the known next item.
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // Open-bins pressure: discourage spreading across many bins unless fit is tight.
    let tightness = 1.0 - (post_residual as f64) / bin_capacity as f64;
    score += open_bins_count as f64 * (1.0 - tightness) * 3.0;

    // Prefer bins below the mean residual (consolidating waste).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // New empty bin candidate: only attractive when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let decent_fit_exists = post_residual == 0
            || (next_item_size > 0 && post_residual >= next_item_size);
        if fitting_bins_count > 0 && !decent_fit_exists {
            score += 120.0; // keep using existing bins unless this fit is bad
        } else if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference for filling larger residuals early in the stream.
    score -= (bin_residual as f64 / bin_capacity as f64) * (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Small post-residual is good, but penalize tiny unusable slivers
        if post_residual < 10 {
            score += 8.0; // dead space below min item size
        }
        // Tight fit reward relative to capacity
        score -= 30.0 * (1.0 - (post_residual as f64 / bin_capacity as f64).powi(2));
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let pr = post_residual as f64;
        if pr >= nx {
            let gap = pr - nx;
            // exact match for next item is excellent
            if gap == 0.0 {
                score -= 400.0;
            } else if gap < 10.0 {
                score -= 200.0; // next item fits with small waste
            } else {
                score -= 120.0 * (nx / pr); // proportional lookahead reward
            }
        } else {
            // next item does NOT fit this bin after placement: penalize
            // proportionally to how much space would be wasted
            score += 0.5 * (nx - pr);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }
    // Many fitting bins: mild penalty to prefer tighter consolidation elsewhere
    if fitting_bins_count > 2 {
        score += 5.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Prefer bins with residual below mean (consolidating fuller bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: only attractive when item is large relative to
    // capacity and no good existing fit exists
    if bin_residual == bin_capacity {
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        if fill_ratio > 0.5 && fitting_bins_count == 0 {
            score -= 80.0;
        } else {
            score += 60.0 + 40.0 * fill_ratio;
        }
    }

    // Early stream: slightly favor keeping bins open for future flexibility
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post residual).
    score -= 60.0 * ((bin_capacity as f64 - post_residual as f64) / bin_capacity as f64).powi(3);

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 {
        let waste = post_residual as f64;
        if waste < 12.0 {
            score += 45.0 * (1.0 - waste / 12.0); // nearly-full bin: good
        } else {
            score += 8.0 * (waste / bin_capacity as f64).sqrt();
        }
    } else {
        score -= 25.0; // perfect closure reward
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Many fitting bins: mild penalty to prefer spreading load onto fuller bins.
    if fitting_bins_count > 1 {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Lookahead: if next item fits into this bin's post residual, reward.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 18.0;
        } else {
            // Next item won't fit here; penalize wasting a scarce large residual.
            let gap = next_item_size as f64 - post_residual as f64;
            score += 6.0 * (gap / bin_capacity as f64);
        }
    }

    // Global state coupling: prefer bins whose residual is near the mean residual.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 3.0 * (dev / bin_capacity as f64);

    // Time horizon: early in stream, be conservative (penalize low residuals slightly
    // to keep flexible bins); late in stream, exploit tight fits more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no good fit exists or item is huge.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 }
            else if fitting_bins_count == 1 { 0.55 }
            else { 0.0 };
        let big_item = item_size as f64 / bin_capacity as f64;
        score = 75.0 - 90.0 * desperation - 25.0 * big_item + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let x = post / cap; // normalized post residual in [0,1]

    // Base: quadratic penalty on wasted space, weighted by stream progress
    let mut score = post * (1.0 + 0.6 * progress);

    // Non-linear coupling: residual^2 term grows late in the stream
    score += 8.0 * x * x * (0.3 + 0.7 * progress) * cap;

    // Cubic interaction: small dead space is fine early, costly late
    score += 4.0 * x * x * x * progress * cap;

    // Reward tight fits (small post residual) more strongly as stream advances
    score -= 6.0 * (1.0 - x) * (1.0 - x) * (0.4 + 0.6 * progress);

    // Lookahead coupling: if next item fits in post residual, reward this bin
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            score -= 5.0 * (1.0 - nxt / cap) * (0.5 + 0.5 * progress);
        } else {
            // dead space that next item cannot use
            score += 3.0 * (nxt - post) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - x);
    }

    // Prefer bins below mean residual when many bins are open (balance load)
    score += 0.05 * (post - mean_residual) * (open_bins_count as f64).sqrt();

    // Mild penalty for opening a new bin early when alternatives exist
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) + 2.0 * (open_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues divisible by small classes
    // are more reusable. Reward post_residuals in "harmonic" residue classes.
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -50.0 // perfect fit, strongly favored
    } else if pr % 10 == 0 {
        -12.0
    } else if pr % 5 == 0 {
        -6.0
    } else if pr % 2 == 0 {
        -2.0
    } else {
        3.0 // odd residuals are harder to fill
    };
    score += harmonic_bonus;

    // Integer-division threshold: post_residual below half of the smallest
    // plausible item is dead space; penalize heavily via floor division.
    let dead_class = pr / 25; // 0..4 classes of usable space
    score += match dead_class {
        0 => 15.0 + (pr as f64) * 0.4, // tiny unusable gap
        1 => 4.0,
        2 => 0.0,
        _ => -3.0,
    };

    // Lookahead coupling: does next_item_size fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 20.0; // perfect chain
        } else if next_item_size < pr {
            let gap = pr - next_item_size;
            score -= 8.0 - (gap as f64) * 0.15; // tighter next fit is better
            if gap % 5 == 0 { score -= 2.0; }
        } else {
            // next item cannot use this bin's leftover; penalize leftover size
            score += (pr as f64) * 0.1;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // New-bin candidate handling: an empty bin has neutral base but should only
    // win when open bins have bad fits. Give it a mild standing penalty that
    // shrinks as the stream progresses (more bins already committed).
    if bin_residual == bin_capacity {
        score += 8.0 + (open_bins_count as f64) * 0.5
            - (step_index as f64 / total_items.max(1) as f64) * 6.0;
    } else {
        // Prefer bins tighter than the mean residual (good fills).
        score -= (mean_residual - bin_residual as f64) * 0.05;
    }

    // Progress pressure: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Mid-range gaps that few future items can fill are also bad.
    if post_residual >= 10 && post_residual < 25 {
        score += 15.0;
    }

    // Reward tight fits (waste-free placements).
    if post_residual == 0 {
        score -= 80.0;
    } else {
        let fill_ratio = item_size as f64 / bin_residual as f64;
        score -= 30.0 * fill_ratio;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 70.0;
    }
    // If next item fits in the gap, mild bonus.
    if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        score -= 10.0;
    }
    // If the leftover gap is too small for the next item, penalize.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        score += 12.0;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when open bins have poor fits
    // or residual structure is bad. Baseline slightly above a good fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 2.0 * open_bins_count as f64;
        if mean_residual > 30.0 {
            score -= 20.0; // open bins are roomy but this item fits poorly elsewhere? still keep pressure
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing ones.
    score += 0.5 * open_bins_count as f64;

    // Slight preference to use bins with lower residual than the mean (tighter bins first).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect-ish fits: small post_residual is good.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Aggressive 2-step lookahead: if next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 30.0 - 0.25 * slack_after_next as f64;
    } else if next_item_size > 0 {
        // Next item won't fit: penalize proportionally to wasted potential.
        let gap = (next_item_size - post_residual) as f64;
        score += 8.0 * gap / (bin_capacity as f64);
    }

    // Compare against mean residual of open bins: prefer bins with residual below mean
    // (i.e., already well-filled bins) to keep other bins flexible.
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize creating dead space that nothing (min size 1) could still use is trivial;
    // instead penalize very small unusable leftovers relative to typical small items.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Early in stream, be more willing to open fresh bins (keep flexibility);
    // late in stream, prefer closing out open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: reward early, penalize late.
        score -= 20.0 * (1.0 - progress) - 10.0 * progress;
        // If no open bin fits well, new bin more attractive.
        if post_residual as f64 > mean_residual + (bin_capacity as f64) * 0.5 {
            score -= 10.0;
        }
    }

    // Many open bins: prefer filling existing ones rather than spreading.
    score += 1.5 * open_bins_count as f64 * (post_residual as f64) / (bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) extra strongly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use:
    // dead space is bad if post_residual is smaller than the smallest items (1..10 zone).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0 * (10 - post_residual) as f64;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // reward proportional fit quality of the lookahead
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 10.0 * frac;
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64 / bin_capacity as f64;
            score += 6.0 * over;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make empty bins mildly unattractive so we
    // prefer existing bins, but attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 20.0;
        // later in the stream, opening new bins is riskier (less time to fill them)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
        // if many bins are open already, discourage yet another one
        score += 1.5 * open_bins_count as f64;
        // if the item is large, a fresh bin is actually fine
        score -= 0.15 * item_size as f64;
    }

    // Prefer filling bins whose residual deviates favorably from the mean:
    // placing into a bin with residual below mean reduces global fragmentation.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev;

    // Mild penalty for leaving exactly awkward residuals (e.g. 11..20) that
    // only small items can use — encourage either very full or very usable.
    if post_residual >= 11 && post_residual <= 20 {
        score += 3.0;
    }

    // Time-horizon coupling: early in the stream keep scores smooth/exploratory;
    // later, sharpen preference for tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Small tie-breaker favoring bins with more residual consumed relative to capacity.
    score += 0.05 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base waste: penalize leftover space, super-linearly (dead space is costly).
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth non-linear coupling: as the stream progresses, leftover space becomes
    // less recoverable, so amplify the waste penalty with a saturating term.
    let progress_amp = 1.0 + (progress * progress) * (pr / (cap * 0.5)).tanh();
    score *= progress_amp;

    // Reward tight fits: subtract a smooth function of how full the bin becomes.
    let fill = 1.0 - norm_pr;
    score -= (fill * fill * fill) * cap * 0.35;

    // Coupling with mean residual: prefer bins that leave residuals below the
    // mean (compacting bins), penalize those leaving above-mean slack.
    score += 0.25 * (pr as f64 - mean_residual) * (0.5 + progress);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 18.0 + 12.0 * progress;
    }

    // Lookahead: if the next item could exactly use the post-residual, reward it;
    // if the next item cannot fit the post-residual, mildly penalize this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let gap = (pr - nxt).abs();
            score -= (1.0 - gap / cap) * 8.0;
        } else {
            score += 0.15 * (nxt - pr).min(cap);
        }
    }

    // New-bin candidate (empty bin): penalize opening a new bin unless open bins
    // are genuinely congested; smooth ramp with open_bins_count and mean residual.
    if bin_residual == bin_capacity {
        score = cap * 0.6
            + cap * (1.0 - (open_bins_count as f64 / 12.0).tanh())
            - mean_residual * 0.4
            + 14.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space via modulo classes.
    let pr = post_residual;
    let class = pr % 10; // coarse harmonic class of the leftover space
    // Penalize leftovers that are "awkward" (not multiples of common item strides)
    let awkward = match class {
        0 => -6.0,        // perfectly divisible leftover: excellent
        5 => -3.0,        // half-class: decent
        2 | 4 | 6 | 8 => -1.0, // even class: usable
        _ => 4.0,         // odd prime-ish classes: dead-space risk
    };
    score += awkward;

    // Non-linear penalty on tiny unusable residuals (dead space)
    if pr > 0 && pr < 10 {
        score += 12.0; // nearly-full bin but a sliver wasted
    }
    if pr == 0 {
        score -= 15.0; // perfect closure
    }

    // Fractional capacity coupling: how much of the bin is filled by this item
    let fill = item_size as f64 / cap;
    score -= fill * 10.0;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // with many candidates, prefer tighter fits more aggressively
        score += (fitting_bins_count as f64 - 1.0).ln() * 2.0;
    }

    // Lookahead: integer-division harmony between post_residual and next item
    if next_item_size > 0 {
        let n = next_item_size;
        if n <= pr {
            // does the next item also nest here? reward divisible nesting
            if pr % n == 0 {
                score -= 8.0;
            } else {
                score -= 3.0;
            }
            // penalize if placing here leaves residual that barely excludes next item
            if pr < n && pr > 0 {
                score += 6.0;
            }
        } else {
            // next item won't fit here regardless; leftover should be as small as possible
            score += (n - pr) as f64 * 0.05;
        }
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base premium for opening a fresh bin
        score += 25.0;
        // if several bins fit, opening a new bin is wasteful
        if fitting_bins_count > 0 {
            score += fitting_bins_count as f64 * 5.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
        // if open bins are congested (low mean residual), new bin is more acceptable
        score -= (cap - mean_residual) * 0.1;
        // a fresh bin paired with a big item leaves cap - item residual; reward good strides
        let r = (bin_capacity - item_size) % 10;
        if r == 0 { score -= 4.0; } else { score += 2.0; }
    }

    // Slight preference to fill already-open bins when many are open
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: post_residual in the "unusable gap" band
    // (small enough that typical items 1..=30 cannot exploit it) is heavily penalized.
    let gap_limit = 30.0;
    if post > 0.0 && post <= gap_limit {
        let severity = 1.0 - (post / gap_limit);
        score += severity * severity * 40.0;
    }

    // Reward near-perfect fits strongly.
    if post == 0 {
        score -= 25.0;
    } else if post <= 5 {
        score -= 12.0;
    }

    // Perfect pre-fit (item exactly fills residual) is ideal.
    if item_size == bin_residual {
        score -= 30.0;
    }

    // Lookahead synergy: if the next item fits into the post residual, reward it.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 8.0 + 0.1 * (next_item_size as f64);
    } else if next_item_size > 0 && (next_item_size as f64) > post && post < (next_item_size as f64) {
        // post residual blocks the natural next item: mild penalty.
        score += 3.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing bins
    // when the fleet is already large relative to progress.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = (open_bins_count as f64) * (0.5 + progress);
    score += pressure * 0.6;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean-residual coupling: bins far below the mean residual are "loose" fills;
    // prefer bins whose residual is close to the item (tight packing) when mean is low.
    if mean_residual > 0.0 {
        let tightness = (bin_residual as f64 - item_size as f64) / cap;
        score += tightness * 10.0 * (1.0 - mean_residual / cap).max(0.0);
    }

    // New-bin candidate: neutral baseline so it only wins when all open bins score poorly.
    if bin_residual == bin_capacity {
        score = 55.0 + pressure * 0.5 - 15.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.83;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post residual) with a non-linear boost.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += (fit_ratio * fit_ratio) * 40.0;

    // Penalize leaving residuals that are too small to be useful later
    // (dead space: post_residual > 0 but smaller than the minimum item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual as f64) * 20.0;
        } else {
            // Next item cannot use this bin's remainder: mild penalty for large waste.
            score += (post_residual as f64) * 0.15;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: an empty bin has no scarcity value yet.
    // Prefer open bins unless they are all poor fits; make the empty bin
    // attractive only when the fit elsewhere would be very loose.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when many items remain
        // (a fresh bin has more future utility early in the stream).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 55.0 - 30.0 * (1.0 - progress);
        // If open bins are plentiful and residuals are large, new bin is less costly.
        score -= (open_bins_count as f64).min(10.0) * 1.5;
        // If the current item is large relative to capacity, opening fresh
        // avoids fragmenting open bins.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Global state coupling: when mean residual across open bins is high,
    // prefer bins below the mean (spread the load); when low, prefer tight fills.
    if mean_residual > 0.0 {
        let diff = bin_residual as f64 - mean_residual;
        score += diff * 0.05;
    }

    // Time horizon: late in the stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score += progress * 25.0;
    } else {
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn); // peaks for mid-range residuals
    score -= 12.0 * poly * (0.5 + progress);

    // Reward tight fits more strongly as the stream progresses
    let tightness = 1.0 - prn;
    score -= 8.0 * tightness * tightness * progress;

    // Penalize large dead space, growing late in the stream
    score += 6.0 * prn * prn * prn * (0.3 + 0.7 * progress);

    // Last-chance bin bonus (avoid opening a new bin unnecessarily)
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - prn);
    }

    // Lookahead: reward if next item fits into post residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 5.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 3.0 * (1.0 - pr / (next_item_size as f64).max(1.0)).abs();
    }

    // Mild pressure toward consolidating bins when many are open
    score += 0.05 * open_bins_count as f64 * prn;

    // Alignment with mean residual: prefer bins near the mean
    score += 2.0 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "usable" classes (large enough to host typical small items).
    let capacity = bin_capacity as f64;

    // Class bonus: residual divisible into nice chunks (mod 10 buckets).
    let pr = post_residual as i64;
    let class = pr % 10;
    let class_bonus = match class {
        0 => -12.0,                    // perfectly aligned residual
        1..=3 => 6.0,                  // sliver risk
        4..=7 => -4.0,                 // decent
        _ => 0.0,
    };
    score += class_bonus as f64;

    // Reward residuals that can still fit a mid-range item (>= 10).
    if post_residual >= 10 {
        score -= 8.0;
    } else if post_residual > 0 {
        score += 10.0; // dead space
    }

    // Harmonic fraction of bin used: prefer tight fills.
    let fill = 1.0 - (post_residual as f64) / capacity;
    score -= 15.0 * (fill * fill);

    // Last-chance bin: strong bonus to use it rather than open a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post-residual
    // (harmonic pairing), reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 5.0;
        } else {
            score += 4.0;
        }
    }

    // New-bin candidate handling: only attractive when existing bins are poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so a fresh bin is chosen only when fits are bad.
        score += 18.0;
        // If many bins can fit, discourage opening another.
        if fitting_bins_count > 1 {
            score += 25.0;
        }
        // If the only fitting bin leaves a tiny dead residual, allow new bin.
        if fitting_bins_count == 1 {
            let other_post = bin_residual - item_size;
            if other_post < 10 {
                score -= 22.0;
            }
        }
        // Early stream: prefer consolidating; late stream: allow spreading.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (1.0 - progress);
        // If mean residual is large, existing bins are roomy; penalize new bin.
        score += (mean_residual - 25.0).max(0.0) * 0.4;
    }

    // Mild penalty per open bin to encourage consolidation.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (size 1..100 stream) are near-worthless.
    // Penalize small positive post_residuals aggressively.
    if post_residual > 0 {
        if post_residual < 10 {
            // Unusable sliver: heavy penalty scaled by how "wasted" it is.
            score += 60.0 * (1.0 - post_residual as f64 / 10.0);
        } else if post_residual < 25 {
            // Marginal gap: moderate penalty decaying as gap grows.
            score += 25.0 * (25.0 - post_residual as f64) / 15.0;
        }
    } else {
        // Perfect fit: strong reward (subtract).
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item if it fits after placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Next item can also go here: excellent chaining potential.
            score -= 15.0 + 0.1 * (post_residual - next_item_size) as f64;
        } else if next_item_size <= bin_residual {
            // This bin could have held next item but placement kills it:
            // mild penalty proportional to the gap created.
            score += 0.15 * (post_residual + item_size).min(next_item_size) as f64;
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones (penalize the new-bin candidate and spreading).
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.3 + 0.4 * progress);
    if bin_residual == bin_capacity {
        // Brand-new empty bin: penalize proportionally to open-bin pressure.
        score += pressure * 8.0;
        // But if no existing bin fits (last chance), new bin is fine.
        if fitting_bins_count == 0 {
            score -= pressure * 8.0 + 5.0;
        }
    } else if fitting_bins_count == 1 {
        // This is the only bin that fits: strong reward to use it.
        score -= 20.0;
    }

    // Deviation from mean residual: prefer bins tighter than average
    // (fills the fullest bins first, keeping slack bins flexible).
    score += 0.2 * (bin_residual as f64 - mean_residual).max(0.0);

    // Late in the stream, tighten up: value exactness more.
    if progress > 0.8 {
        score *= 1.0 + 0.3 * (progress - 0.8) / 0.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: overwhelming reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward if the next item fits into the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 120.0 - slack.min(120.0);
        // Chain bonus: post-residual exactly matches next item (perfect chain).
        if post_residual == next_item_size {
            score -= 500.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space that cannot host the next item: penalize proportionally.
        score += (next_item_size - post_residual) as f64 * 0.6;
    }

    // Penalize small unusable residuals relative to capacity.
    if post_residual > 0 && post_residual < 10 {
        score += 150.0;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Baseline penalty for opening a new bin; offset by poor fits elsewhere.
        score += 60.0 + 0.5 * mean_residual;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0; // fresh bin can host next item too
        }
        if fitting_bins_count <= 1 {
            score -= 150.0; // no good alternative: opening is fine
        }
    }

    // Mild preference to fill already-open bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 20.0;

    // Prefer bins tighter than the mean residual (better packing).
    score += (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization).
    let tightness = (item_size as f64) / (bin_residual as f64).max(1.0);
    score -= 40.0 * tightness * tightness;

    // Penalize tiny dead space that nothing (min size 1) can still use? Actually
    // small post_residual is good: reward exact/very small leftovers.
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual < 5 {
        score -= 12.0;
    }

    // Dead-space penalty: leftover that is too small for typical follow-ups.
    if post_residual > 0 && next_item_size > 0 && post_residual < next_item_size {
        // Could next-but-one still use it? Penalize proportionally to waste.
        score += 0.5 * (next_item_size - post_residual) as f64;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Bonus if this bin can also host the lookahead item.
        score -= 8.0;
        // Extra bonus if the lookahead fits perfectly after this placement.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin for a good fit.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0 * tightness;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current bin fit is poor or the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Early on, prefer filling open bins to keep bin count low.
        let open_penalty = 6.0 * (open_bins_count as f64).sqrt() * (1.0 - 0.5 * progress);
        score += 25.0 + open_penalty;
        // If item is large (would leave small residue anyway), new bin is fine.
        if item_size >= 70 {
            score -= 20.0;
        }
        // If many bins fit the item, discourage new bin more.
        score += 2.0 * fitting_bins_count as f64;
    }

    // Global state coupling: prefer bins whose residual is above the mean
    // (spreads usage evenly, keeps small residuals concentrated).
    let resid_f = bin_residual as f64;
    if resid_f > mean_residual {
        score -= 0.15 * (resid_f - mean_residual);
    } else {
        score += 0.15 * (mean_residual - resid_f);
    }

    // Time horizon: as the stream nears its end, prioritize closing out bins
    // tightly (pack into nearly-full bins) since future compensation is limited.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    // Mild preference for using already-open bins vs creating many partially
    // filled ones: reward bins that are relatively full.
    let fill = 1.0 - resid_f / (bin_capacity as f64);
    score -= 5.0 * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap;
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early stream: prefer tight fills (small post_residual rewarded).
    // Late stream: tolerate larger post_residual since future items are fewer.
    let early = (1.0 - progress) * (1.0 - progress);
    score -= early * 12.0 * (1.0 - x) * (1.0 - x);
    score += progress * 6.0 * x * x;

    // Smooth penalty for very small residuals scaled by next item size:
    // if next item could use this leftover, dead space is less costly.
    let nx = next_item_size as f64 / cap;
    let waste = x * (1.0 - x) * 4.0; // peaks at x=0.5 (least useful leftover)
    score += waste * (1.0 - nx) * 8.0;

    // Last-chance bin: strongly reward using it to avoid opening a bin.
    if fitting_bins_count == 1 {
        score -= 20.0 + 10.0 * (1.0 - x);
    }

    // Slight reward when bin residual is below mean residual (tighter bin).
    score -= (mean_residual - bin_residual as f64) / cap * 3.0;

    // Mild pressure against accumulating many open bins early.
    score += progress * (open_bins_count as f64) * 0.15;

    // New-bin candidate: prefer it only when item barely fits elsewhere
    // (very tight fit elsewhere means near-zero residual; new bin should win
    // when existing fits are extremely poor, i.e. item_size close to residual).
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / cap;
        score = cap as f64 - 15.0 * tightness * tightness - 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: waste is worst when post_residual
    // is a "dead" class that few item sizes can fill (items are 1..100).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Fraction of capacity consumed by this placement.
    let fill_frac = (bin_capacity - post_residual) as f64 / cap;

    // Reward tight fills (capacity fraction near 1) with a strong subtraction.
    score -= 40.0 * fill_frac * fill_frac;

    // Modulo-class penalty: leftover space in classes {1..9} is nearly dead
    // (only tiny items can use it), class multiples of 10 are reusable.
    let class = post_residual % 10;
    if post_residual > 0 {
        score += match class {
            0 => -6.0,
            1..=3 => 10.0 + (3 - class) as f64 * 4.0,
            4..=6 => 4.0,
            _ => 0.0,
        };
    } else {
        // Perfect fit: huge reward.
        score -= 25.0;
    }

    // Integer-division threshold: leftover that can hold next_item exactly
    // (post_residual / next_item_size >= 1) is valuable for the lookahead.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 8.0 * (post_residual / next_item_size) as f64;
    } else if next_item_size > 0 {
        // Lookahead cannot fit here; penalize proportionally.
        score += 6.0 * (next_item_size as f64 - pr) / cap;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer bins already below mean residual.
    if open_bins_count > 1 {
        let dev = (pr - mean_residual) / cap;
        score += 10.0 * dev;
    }

    // Early in stream, slightly prefer opening fresh bins for large items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive when item is large or few bins fit it.
        score -= 8.0 * (item_size as f64 / 100.0);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if progress < 0.2 {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for typical future items are worthless.
    // Treat a residual as "dead" if it is below the smallest plausible next item (>=1),
    // with escalating penalty for gaps in the classic unusable band (1..=10).
    let dead = if post_residual == 0 {
        -30.0 // perfect fill is gold
    } else if post_residual < 10 {
        40.0 + (10 - post_residual) as f64 * 3.0 // tiny unusable slivers
    } else if post_residual < 20 && next_item_size > post_residual && next_item_size > 0 {
        15.0 // gap can't host the lookahead item
    } else {
        0.0
    };
    score += dead;

    // Reward tight fits: small post_residual relative to capacity.
    score -= (bin_capacity - post_residual) as f64 * 0.15;

    // Open-bin pressure: discourage spreading across many bins unless the fit is good.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64 / post_residual as f64) * 5.0;
    } else if next_item_size > 0 {
        score += 4.0; // next item won't fit here; deprioritize mildly
    }

    // New-bin candidate: prefer it only when no open bin offers a decent fit.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with reasonable fits win.
        score += 18.0 + open_bins_count as f64 * 0.3;
        // But if the only alternative creates dead space, opening a fresh bin is fine.
        if post_residual == bin_capacity && (fitting_bins_count == 0 || mean_residual < item_size as f64 * 0.5) {
            score -= 30.0;
        }
    }

    // Mild mean-residual coupling: prefer bins whose residual is near the item (tight packing).
    score += (mean_residual - bin_residual as f64).abs() * 0.05;

    // Slight stream-progression tilt: later in the stream, close out bins aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward perfect chain fits (post_residual == next_item_size)
    if next_item_size > 0 {
        if post_residual as i64 == next_item_size as i64 {
            score -= 60.0 + 40.0 * progress; // exact 2-step chain: strongly favor
        } else if post_residual >= next_item_size {
            // next item still fits here: mild reward scaled by tightness of the chain
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack.min(25.0); // tighter chain -> bigger reward
        } else {
            // next item cannot fit: post_residual becomes dead space unless another item fits
            let dead = (next_item_size - post_residual) as f64;
            score += dead * (0.6 + 0.4 * progress);
        }
    }

    // Reward tight fits relative to mean residual across open bins
    let resid_f = post_residual as f64;
    if resid_f < mean_residual {
        score -= (mean_residual - resid_f) * 0.5;
    } else {
        score += (resid_f - mean_residual) * 0.25;
    }

    // Last-chance bin: strongly prefer using it over wasting it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Penalize leaving very small unusable slivers (< 10, min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 30.0;
    }

    // New-bin candidate: penalize opening a new bin when good alternatives exist,
    // but allow it when existing bins would create heavy dead space.
    if bin_residual == bin_capacity {
        let waste_elsewhere = if next_item_size > 0 && post_residual == bin_capacity {
            0.0
        } else {
            0.0
        };
        let _ = waste_elsewhere;
        let best_existing_penalty = (bin_capacity as f64 - mean_residual).abs();
        let new_bin_cost = 45.0 + 30.0 * (1.0 - progress) - best_existing_penalty.min(20.0);
        // If the next item is large, a fresh bin is more valuable
        let lookahead_bonus = if next_item_size >= item_size { 12.0 } else { 0.0 };
        score += new_bin_cost - lookahead_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on post residual relative to capacity.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tight * tight;

    // Penalize small dead space that is hard to reuse (below typical small item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: reward bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else {
            score += 8.0;
        }
        // Chain fit: residual after next item also usable.
        if post_residual >= next_item_size {
            let r2 = post_residual - next_item_size;
            if r2 >= 10 {
                score -= 6.0;
            }
        }
    }

    // Prefer filling bins that are already relatively full (below mean residual).
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Time horizon: early in stream, allow more bins to stay open (spread); late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (1.0 - progress) * 5.0 * open_bins_count as f64;
    score -= progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when item is large and no good fit exists.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / bin_capacity as f64;
        score += 20.0 - 25.0 * large;
        if fitting_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild preference for bins with residual close to item size (perfect modular fit).
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.1 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping in progress
    let mut score = pr * (1.0 + 0.8 * progress * progress);

    // Smooth polynomial interaction between normalized post-residual and progress
    let coupling = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 40.0 * coupling;

    // Penalize very small dead space that becomes unusable (smooth quadratic)
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score -= 15.0 * dead * dead;

    // Lookahead: reward if next item fits in post residual (smooth term)
    if next_item_size > 0 {
        let fits = (post_residual >= next_item_size) as i32 as f64;
        let tight = 1.0 - (next_item_size as f64 / cap);
        score -= 12.0 * fits * (0.5 + 0.5 * progress) * (0.5 + 0.5 * tight);
    }

    // Last-chance bonus: only fitting bin, favor using it
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 2.0 * (open_bins_count as f64).ln() * (1.0 - norm_pr);

    // New-bin candidate shaping: empty bin gets smooth progress-dependent penalty
    if bin_residual == bin_capacity {
        score += 30.0 + 25.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // ---- Tightness reward: harmonic classes of post_residual ----
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Classify dead space into harmonic classes by capacity fraction.
        let frac = post_residual as f64 / bin_capacity as f64;
        if post_residual <= 10 {
            score -= 40.0; // near-perfect class (<= C/10)
        } else if post_residual <= 20 {
            score -= 15.0; // C/5 class
        } else if post_residual <= 30 {
            score -= 5.0;  // 3C/10 class
        } else if post_residual <= 50 {
            score += 8.0;  // half-full: mediocre class
        } else {
            score += 18.0; // large dead space class
        }
        // Modulo-10 residue class: small "usable" leftovers are valuable.
        let m = post_residual % 10;
        if m == 0 {
            score -= 6.0; // round leftover, reusable by many sizes
        } else if m <= 3 {
            score += 3.0 * m as f64; // tiny slivers are dead space
        }

        // Integer-division threshold: can next item fit leftover?
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 12.0;
            // Extra reward if next item exactly consumes leftover.
            if next_item_size == post_residual {
                score -= 25.0;
            }
        } else if next_item_size > 0 {
            score += 5.0;
        }

        // Penalize unusable leftover given typical item scale.
        if post_residual < item_size.min(30) {
            score += 10.0;
        }
        let _ = frac;
    }

    // ---- Last-chance logic: strongly prefer using a scarce fitting bin ----
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    } else if fitting_bins_count > 1 {
        score -= 4.0 * (fitting_bins_count.min(4) as f64);
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when existing bins fit poorly
        // or few bins can fit the item.
        let poor_fit = post_residual as f64 / bin_capacity as f64 > 0.5
            && next_item_size > 0 && next_item_size > post_residual;
        let mut new_score = bin_capacity as f64 * 0.55; // baseline penalty
        if poor_fit { new_score -= 15.0; }
        if fitting_bins_count <= 1 { new_score -= 35.0; }
        if open_bins_count > 3 { new_score += 6.0; }
        // Late in stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_score += 10.0 * (1.0 - progress);
        score = score.max(new_score.min(score + 1e-3));
        return new_score.max(score - 0.0) * 0.0 + new_score;
    }

    // ---- Mild preference for fuller (smaller-residual) bins overall ----
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to be useful are heavily punished.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 20.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 + 10.0 * open_bins_count as f64 + 20.0 * progress;
    }

    // Lookahead: prefer bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Prefer bins below mean residual (tighter bins first).
    score -= (mean_residual - post_residual as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit (dead space elimination)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 15 {
        score -= 80.0;
    }

    // 2-step lookahead: bonus if the next item fits the post-residual exactly
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_slack = post_residual - next_item_size;
        if lookahead_slack == 0 {
            score -= 500.0; // perfect 2-item chain: item + next item fills bin
        } else if lookahead_slack <= 10 {
            score -= 200.0;
        } else {
            score -= 60.0 * (1.0 - lookahead_slack as f64 / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item won't fit here; penalize leaving residual that is too
        // small to be useful (dead space) relative to smallest plausible item
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 150.0; // unusable sliver
        } else {
            score += 40.0 * (1.0 - dead / 40.0).max(0.0);
        }
    }

    // Prefer bins tighter than the mean residual (best-fit style)
    score += 0.5 * (bin_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Mild penalty for opening a brand-new bin when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 120.0;
        // But allow new bin if lookahead suggests current bins fit poorly
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 180.0;
        }
    }

    // Late in the stream, consolidate aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 30.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 60.0 * waste_ratio * waste_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 12.0; // near-perfect fit, dead space below min item size
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual > next_item_size {
            score -= 4.0; // leaves room for next item
        } else {
            score += 5.0; // next item won't fit here
        }
        // Penalize leaving a gap just smaller than next item (unusable for it).
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Penalize dumping small items into large-residual bins that could host bigger items.
    let residual_gap = bin_residual as f64 - item_size as f64;
    if item_size < 40 && residual_gap > 50.0 {
        score += 10.0;
    }

    // Global state: when many bins are open with high mean residual, prefer
    // consolidating into existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins are underutilized.
        let avg_fill = mean_residual / bin_capacity as f64;
        score += 15.0 + 40.0 * avg_fill + 10.0 * (open_bins_count as f64 / 20.0).min(1.0);
        // Late in the stream, opening new bins is more costly.
        score += 20.0 * progress;
    } else {
        // Reward filling bins that are already relatively full.
        let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill;
        // Slight bonus for using bins when bin count is high (consolidation).
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let norm_post = post / cap;

    // Core: prefer small post_residual, with non-linear (quadratic/cubic) shaping
    let mut score = post;
    score += 12.0 * norm_post * norm_post * cap;
    score += 20.0 * norm_post * norm_post * norm_post * cap;

    // Stream-progress coupling: as stream advances, dead space becomes more costly
    let progress_penalty = 15.0 * progress * norm_post * norm_post * cap;
    score += progress_penalty;

    // Reward tight fits (small post_residual relative to item size)
    let item = item_size as f64;
    let tightness = item / (bin_residual as f64 + 1.0);
    score -= 8.0 * tightness;

    // Penalize bins far below mean residual (fragmentation signal)
    score += 0.05 * (mean_residual - post).abs();

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 10.0 * (1.0 - post / cap);
        } else {
            // wasted space if next item can't fit here
            score += 5.0 * (next - post).min(cap) / cap * 10.0;
        }
    }

    // Mild penalty for spreading across many open bins when residual is large
    score += 0.02 * open_bins_count as f64 * norm_post;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes are reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit: zero dead space
    } else {
        // residue mod 10: multiples of 10 are highly reusable (item sizes are multiples of 10 in classic streams)
        let r10 = pr % 10;
        score += 3.0 * r10 as f64;
        // residue mod 5
        let r5 = pr % 5;
        score += 2.0 * r5 as f64;

        // integer-division thresholds on post_residual
        let quot = pr / 10; // how many "decades" of space remain
        if quot == 0 {
            score += 25.0; // dead space < 10: unusable
        } else if quot <= 2 {
            score += 8.0; // small leftover, mildly bad
        } else if quot >= 5 {
            score -= 10.0; // large residual stays flexible
        }

        // capacity-fraction coupling: leftover fraction of the bin
        let frac = pr as f64 / cap;
        if frac < 0.1 {
            score += 12.0 * (0.1 - frac) * 10.0;
        } else if frac > 0.5 {
            score -= 6.0;
        }
    }

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 45.0;
        } else if next_item_size < pr {
            let nxt_quot = (pr - next_item_size) / 10;
            score -= 4.0 + 2.0 * nxt_quot as f64;
        } else {
            // next item cannot fit here: penalize proportional to wasted potential
            score += 5.0;
        }
        // harmonic class match: next item size multiple of 10 aligning with post_residual decade
        if next_item_size % 10 == 0 && pr % 10 == 0 && next_item_size <= pr {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bin would leave bad residue
    if bin_residual == bin_capacity {
        let base = 15.0 + 0.3 * open_bins_count as f64;
        // opening a new bin is OK if the best alternative leaves tiny residue
        let bad_leftover = pr > 0 && pr < 10;
        if bad_leftover {
            score -= 20.0; // allow opening fresh bin when fit is terrible
        }
        score += base;
    }

    // progress coupling: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / cap);

    // prefer bins tighter than the mean residual (fill fuller bins first)
    score += 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item * 4 {
        score += 40.0; // tiny dead gap is nearly worthless
    }
    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize leaving residual that cannot fit the lookahead item if it could otherwise fit here
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0; // residual remains useful for lookahead
    }

    // Open bins pressure: discourage spreading across many bins when mean residual is already tight
    let progress = step_index as f64 / total_items.max(1) as f64;
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.15 * bin_pressure * (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        // prefer new bin only when all open bins would leave poor fits
        let poor_fit_elsewhere = fitting_bins_count == 0
            || (post_residual > 0 && post_residual < 10);
        if poor_fit_elsewhere {
            score -= 20.0;
        } else {
            score += 15.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mild preference for tighter bins (smaller residual before placement)
    score += 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 30.0;

    if next_item_size > 0 {
        // Two-step lookahead: reward if the next item fits exactly into post_residual.
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain
        } else if next_item_size <= post_residual {
            // reward proportional to how well next item fills the leftover
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * chain_fill;
            // extra reward if the bin then becomes (nearly) empty
            let post2 = post_residual - next_item_size;
            if post2 <= 5 {
                score -= 25.0;
            }
        } else {
            // next item does NOT fit: penalize dead space that likely goes unused
            let waste = (next_item_size - post_residual) as f64;
            score += 0.6 * waste;
        }
    } else {
        // Last item: just minimize leftover.
        score -= 20.0;
    }

    // Penalize bins with unusually small residual relative to mean (they are nearly full
    // and precious); prefer spreading into bins with more room.
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bonus: if this is the only bin that can fit the item, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when no good fit exists (poor tightness everywhere).
    if bin_residual == bin_capacity {
        // base penalty so we prefer reusing open bins
        score += 35.0;
        // but if other fitting bins are scarce and this is a large item, allow opening
        if fitting_bins_count <= 1 {
            score -= 30.0;
        }
        // early in the stream, opening bins is cheap/normal
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
        // opening a new bin keeps a clean residual for large next items
        if next_item_size >= item_size {
            score -= 8.0;
        }
    }

    // Small nudge: with many open bins, prefer consolidation (lower post_residual wins anyway).
    score += (open_bins_count as f64).ln() * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize (subtract) when the item nearly fills the bin.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if fit_ratio > 0.9 {
        score -= 30.0 * (fit_ratio - 0.9);
    } else if fit_ratio < 0.3 {
        score += 8.0 * (0.3 - fit_ratio); // wasteful low-fill placement
    }

    // Perfect fit: post residual unusable for typical small items.
    if post_residual < 10 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - next_fit / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 6.0; // dead space relative to lookahead
    }

    // Last-chance bonus: only bin that fits the item.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Crowding: many open bins -> prefer reusing existing bins over opening new.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive only early or when mean residual is tiny.
        score -= 10.0 * (1.0 - progress);
        score += 15.0 * (mean_residual / bin_capacity as f64);
        score += 2.0 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Prefer bins below mean residual (consolidate large gaps).
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;
    let norm_item = item / cap;

    // Base: penalize leftover dead space, with a non-linear (quadratic) waste term.
    let mut score = post + 30.0 * norm_post * norm_post * cap;

    // Smooth coupling: tight fits are increasingly valuable as the stream progresses.
    let tightness = 1.0 - norm_post;
    score -= 25.0 * progress * tightness * tightness * item / cap;

    // Non-linear interaction between fill fraction and stream progress.
    score -= 15.0 * (norm_item * (1.0 - progress)) * (norm_post * progress).sin().abs() * cap;

    // Last-chance bonus: strongly prefer the only fitting bin, smoothly scaled by progress.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 20.0 * progress;
    }

    // New-bin candidate: prefer it only when the item fits poorly in open bins
    // (large post_residual relative to capacity), with smooth progression weighting.
    if bin_residual == bin_capacity {
        let lookahead_need = (next_item_size as f64 / cap).max(0.0);
        let waste_penalty = 60.0 * norm_post * norm_post;
        score -= 10.0 * progress - waste_penalty + 8.0 * lookahead_need * (1.0 - progress);
        score += 5.0 * open_bins_count as f64 / (open_bins_count as f64 + 5.0);
    }

    // Prefer bins whose residual deviates smoothly from the mean (balance consolidation).
    let dev = (post - mean_residual) / cap;
    score += 12.0 * dev * dev;

    // Lookahead: reward leaving space compatible with the next item (smooth kernel).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post - nxt) / cap;
        score -= 10.0 * (-diff * diff * 20.0).exp();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: prefer residuals
    // that lie in "friendly" classes for future items (multiples of 5, 10).
    let pr = post_residual;
    if pr > 0 {
        if pr % 10 == 0 {
            score -= 6.0; // perfectly harmonic residual
        } else if pr % 5 == 0 {
            score -= 3.0;
        }
        if pr % 25 == 0 {
            score -= 4.0;
        }
        // Penalize awkward residuals in dead-space ranges
        if pr < 10 && pr > 0 {
            score += 15.0; // unusable sliver (items >= 10... but sizes 1..100)
        }
        if pr >= 10 && pr <= 20 {
            score += 4.0; // fragile zone: only tiny items fit
        }
    } else {
        score -= 12.0; // perfect fill
    }

    // Integer-division thresholds on post_residual relative to next item
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item fits here: strong reward, scaled by tightness
            let tight = (pr - next_item_size) as f64;
            score -= 10.0 + (100.0 - tight) * 0.05;
            if next_item_size % 10 == 0 && pr % 10 == 0 {
                score -= 3.0; // harmonic pair
            }
        } else {
            // Next item won't fit: mild penalty, worse for near-misses
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.08;
        }
    }

    // Last-chance bin: avoid stranding it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Base bias so existing decent bins win
        score += 30.0;
        if post_residual > 0 && item_size > 50 {
            score -= 8.0; // big items pair well in fresh bins
        }
        if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
            score -= 12.0; // guaranteed pair in new bin
        }
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin anyway
        }
        let _ = progress;
    }

    // Coupling with mean residual: prefer bins near the mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.03;

    // Fraction-of-capacity harmonic term
    let frac = post_residual as f64 / bin_capacity as f64;
    score += (frac * std::f64::consts::PI).sin() * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< min plausible item size 10)
    // are unusable; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 3.0;
    }

    // Reward very tight fits (post_residual small but usable).
    if post_residual > 0 && post_residual >= 10 && post_residual <= 25 {
        score -= 12.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize wasting a large residual on a small item (poor utilization).
    let utilization = item_size as f64 / bin_residual as f64;
    score -= utilization * 15.0;

    // Open-bin pressure: discourage spreading across many bins when residual is ample.
    if open_bins_count > 1 {
        score += (open_bins_count as f64).ln() * 4.0 * (1.0 - utilization);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Lookahead: if next item can use the post-residual, reward leaving it.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0;
        if post_residual - next_item_size < 10 {
            score -= 8.0; // next item then nearly fills the bin
        }
    }
    // Penalize leaving a gap that the next item cannot use.
    if next_item_size > post_residual && post_residual > 0 {
        score += 6.0;
    }

    // New-bin candidate handling: prefer new bin only when existing fits are poor.
    if bin_residual == bin_capacity {
        // Mild default preference for existing bins.
        score += 8.0;
        // But if all open bins would leave big dead space, new bin is attractive.
        if post_residual as f64 > mean_residual {
            score -= 5.0;
        }
    }

    // Late-stream tightening: consolidate toward the end.
    let progress = step_index as f64 / total_items as f64;
    score -= progress * 3.0 * (1.0 - utilization);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), normalized by capacity.
    score = (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Aggressive 2-step lookahead: strongly reward exact chain fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits perfectly into the resulting residual -> excellent.
            let chain = post_residual - next_item_size;
            score -= 60.0 - (chain as f64 * 0.5);
            // Perfect 2-item fill (residual fully consumed by both items).
            if chain == 0 {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here -> penalize dead space proportionally.
            score += (next_item_size as f64) * 0.3;
        }
    } else {
        // Last item: pure tightness fit.
        score -= 10.0;
    }

    // Reward exploiting the mean residual structure: bins with residual
    // below mean are "scarce space" bins; using them is good.
    let resid = bin_residual as f64;
    if resid < mean_residual {
        score -= (mean_residual - resid) * 0.4;
    } else {
        score += (resid - mean_residual) * 0.1;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large
    // relative to capacity and current bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let item_frac = item_size as f64 / bin_capacity as f64;
        // Opening new bin is attractive for big items late in the stream
        // with many open bins (fresh bin gives full flexibility).
        score += 55.0 - item_frac * 30.0 - progress * 10.0 - crowding * 0.5;
        // If next item is large, a fresh bin is more valuable.
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.15;
        }
    }

    // Mild penalty for very small leftover fragments (unusable dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins that end nearly full.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 35.0;
    } else if post_residual <= 10 {
        score -= 18.0;
    }

    // Penalize dead space that is too small for the smallest plausible item,
    // scaled by stream progress (late in stream, small leftovers matter less).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * (2.5 - 1.5 * progress);
    }

    // Lookahead: reward bins whose leftover could host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let snug = (post_residual - next_item_size) as f64;
        score -= 12.0 + 8.0 * (1.0 - snug / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        // leftover blocks the next item: mild penalty
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Prefer filling bins that are already well-loaded (fewer active bins).
    let load = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * load * load;

    // Mild pressure to keep number of open bins low.
    score += open_bins_count as f64 * 0.35;

    // Nudge toward bins with below-average residual (more full than average).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0
            && open_bins_count > 0
            && open_bins_count.iter().count() >= 0; // placeholder-free guard
        let _ = good_fit_exists;
        if fitting_bins_count > 1 {
            // a real open bin can take it; make new bin unattractive
            score += 55.0 + 10.0 * (1.0 - progress);
        } else if fitting_bins_count == 1 {
            // the only fitting bin is likely this new one or a marginal one;
            // moderate cost: prefer existing last-chance bin handled above
            score += 20.0;
        } else {
            // nothing fits anywhere else: new bin is the choice
            score -= 25.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post_residual (tight fit), non-linearly
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth interaction: as stream progresses, tighten tolerance for wasted space
    let tightness = 1.0 + progress * progress * 3.0;
    score *= tightness;

    // Penalize dead space that cannot fit the next item (smooth coupling)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * (0.8 + 0.6 * progress);
    }

    // Last-chance bonus: strongly reward using a bin when few fit
    if fitting_bins_count == 1 {
        score -= 12.0 + 8.0 * progress;
    } else {
        score -= (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild preference for bins deviating from mean residual (consolidation)
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (1.0 - progress * 0.5);

    // New-bin candidate: penalize opening a bin unless residual is large (poor fit elsewhere)
    if bin_residual == bin_capacity {
        score += 25.0 - 15.0 * (1.0 - norm_pr) - 10.0 * progress;
        // more attractive late in stream when open bins are fragmented
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues mod 10 create "dead-space classes".
    let residue_class = post_residual % 10;
    score -= (10 - residue_class) as f64 * 0.5; // reward post-residuals near class boundaries

    // Integer-division thresholds: post_residual buckets of size 10.
    let bucket = post_residual / 10;
    score -= bucket as f64 * 2.0; // prefer bins leaving larger structured slack

    // Perfect-fit reward: post_residual exactly in a harmonic class of small items.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 10 {
        score -= 20.0; // leaves room for smallest items (size >= 1..10 range)
    }

    // Lookahead coupling: if next item fits the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (next_item_size as f64) * 0.3;
        // harmonic match: next_item_size divides post_residual nicely
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 {
        // next item won't fit here; penalize proportionally to wasted potential
        score += (next_item_size as f64 - post_residual as f64) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so it's only
    // chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0 - (open_bins_count as f64) * 0.5;
        // early in the stream, opening bins is cheap
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= progress * 10.0;
    }

    // Penalize bins far below mean residual (fragmentation asymmetry).
    score += (mean_residual - bin_residual as f64).abs() * 0.1;

    // Modulo coupling on item_size: items in the "large" harmonic class (>50)
    // should prefer tight fits.
    if item_size > bin_capacity / 2 {
        score += (post_residual as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable gaps (< 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Gaps too small for the smallest plausible next item are near-dead space.
    if post_residual > 0 && post_residual < next_item_size.max(1) {
        score += 12.0;
    }

    // Reward tight fits (post_residual close to zero).
    score -= (1.0 - (post_residual as f64 / bin_capacity as f64)) * 6.0;

    // Perfect fit gets a strong bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // If the next item fits exactly into the post residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 18.0 - slack * 0.5;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here; mild penalty for stranding capacity.
        score += 5.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += (open_bins_count as f64) * 1.5;

    // Mean-residual coupling: prefer bins whose residual deviates favorably from the mean.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when open bins are mostly full or item is large.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fill = 1.0 - mean_residual / bin_capacity as f64;
        let pressure = (open_bins_count as f64) * (1.0 - avg_fill).max(0.0);
        score = 35.0 + pressure * 20.0 - avg_fill * 25.0 - progress * 5.0;
        if next_item_size > 0 && next_item_size >= bin_residual {
            score -= 10.0; // item alone nearly fills a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
