pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) nonlinearly.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio) * 12.0;
    score += fit_ratio * fit_ratio * 20.0;

    // Penalize large dead space strongly.
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill
    }
    if post_residual >= 10 && post_residual < item_size {
        score += 3.0; // dead space smaller than any item but still wasteful
    }

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: prefer it only when the item fits poorly everywhere else.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Penalize opening a new bin when mean residual across open bins is large.
        score += mean_residual * 0.5;
        // Time decay: later in the stream, opening bins is more acceptable if needed.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= t * 5.0;
        // If lookahead item could fill the residual of this new bin later, slight bonus.
        if next_item_size > 0 && next_item_size as f64 >= mean_residual {
            score -= 4.0;
        }
    } else {
        // Reward using existing bins proportionally to how crowded the bin already is.
        let used_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= used_ratio * 8.0;
        // Lookahead synergy: if next item exactly fits the post residual, big reward.
        if next_item_size > 0 && (next_item_size as u32) == post_residual {
            score -= 25.0;
        } else if next_item_size > 0 && (next_item_size as u32) <= post_residual {
            score -= 2.0;
        } else if next_item_size > 0 && (next_item_size as u32) > post_residual {
            score += 5.0; // next item won't fit here anyway; residual is dead space
        }
    }

    // Mild penalty for scattering across many open bins.
    score += open_bins_count as f64 * 0.05;

    // Global pressure: when mean residual is small, conserve space more aggressively.
    score += (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Non-linear tightness reward: strong preference for small post_residual,
    // amplified quadratically and coupled with stream progress.
    let tightness = (post / cap).powi(2);
    score -= tightness * cap * (0.5 + progress);

    // Perfect-fit bonus (smooth decay away from zero residual).
    let perfect = (-post / 8.0).exp();
    score -= 12.0 * perfect;

    // Lookahead coupling: if the next item fits the post-residual, reward this bin.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let fit_quality = (post - nxt) / cap;
            score -= 8.0 * (1.0 - fit_quality).powi(2) * (1.0 - progress * 0.5);
        } else {
            // Next item won't fit here: mild penalty for leaving stranded space.
            score += 2.0 * (post / cap);
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - (post / cap));
    }

    // New-bin candidate: penalize proportional to how many open bins already exist,
    // but soften late in the stream when fragmentation dominates.
    if bin_residual == bin_capacity {
        let open_factor = (open_bins_count as f64).ln() + 1.0;
        score += 6.0 * open_factor * (1.0 - 0.4 * progress);
    } else {
        // Reward using bins that are already fragmented (near mean residual).
        let dev = (post - mean_residual).abs() / cap;
        score += 3.0 * dev * (1.0 - progress);
    }

    // Smooth stream-progress coupling: early on, slightly prefer filling existing bins;
    // later, tolerate more residual since future items are unknown.
    score *= 1.0 - 0.15 * (progress * std::f64::consts::PI).sin();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into modulo classes of 10
    let pr = post_residual as u32;
    let class = pr % 10;
    // Dead-space penalty grows for residuals that are small but unusable (1..=9)
    if pr > 0 && pr < 10 {
        score += 60.0 - 6.0 * pr as f64; // tiny leftovers are worthless
    } else {
        // reward residuals that are harmonic multiples (likely to fit future items)
        let k = pr / 10;
        score -= 8.0 * (k as f64).min(5.0);
        // penalize odd classes slightly (less likely to be hit by generic sizes)
        score += 2.0 * (class % 2) as f64;
    }

    // Perfect fit reward
    if pr == 0 {
        score -= 100.0;
    }

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // reward chaining, scaled by how well it fills the leftover
            let fill = next_item_size as f64 / pr as f64;
            score -= 30.0 * fill;
            if pr - next_item_size == 0 {
                score -= 40.0; // double perfect fit
            }
        } else {
            score += 15.0; // next item cannot follow here
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Prefer bins with residual already below item size (can't be reused anyway)
    if bin_residual < item_size {
        score += 1000.0;
    }

    // Fractional coupling with mean residual: keep diversity of residuals
    let frac = post_residual as f64 / cap;
    score += 10.0 * (frac - mean_residual / cap).abs();

    // New-bin candidate: neutral-ish score that competes only against bad fits
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, discounted early in the stream
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 45.0 + 40.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin has full flexibility for lookahead
        }
        if fitting_bins_count == 1 {
            score += 60.0; // don't open new bin when an existing bin is a last chance
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
