pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but avoid leaving
    // tiny unusable slivers (< 10) that can never be filled.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // dead-space penalty
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Normalized fill ratio of this placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= 15.0 * fill;

    // Lookahead: if the next item fits exactly in the post residual,
    // this placement is highly desirable (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 55.0;
        } else if next_item_size <= post_residual {
            // next item fits but imperfectly; mild reward scaled by fit quality
            let nf = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * nf;
        } else {
            // next item won't fit here; penalize slightly more if residual
            // is too small to ever be useful
            if post_residual < next_item_size && post_residual < 20 {
                score += 15.0;
            }
        }
    } else {
        // Last item: prefer perfect closure, otherwise any bin works.
        score -= 10.0 * fill;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when the item fits
    // poorly everywhere else (large residual waste would result) or when
    // few bins are open early in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening a new bin is cheap early, expensive late.
        let open_cost = 30.0 + 90.0 * progress + 2.0 * open_bins_count as f64;
        score += open_cost;
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If mean residual of open bins is large, prefer reusing them.
        score += 0.3 * mean_residual;
    }

    // Prefer bins with below-average residual (denser bins), keeping
    // looser bins available for future items.
    let diff = bin_residual as f64 - mean_residual;
    score += 0.08 * diff;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
