    let mut score = fit_norm * fit_norm * 100.0 + pr * 0.5;

    // Non-linear coupling of residual with stream progress:
    // late in the stream, dead space becomes more costly
    let late_penalty = fit_norm * fit_norm * fit_norm * (progress * progress) * 120.0;
    score += late_penalty;

    // Reward tight fits (small post_residual relative to item size)
    let tightness = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tightness * tightness * 20.0;

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
