    }

    // Lookahead: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 25.0 * (1.0 - fit_norm);
    } else if next_item_size > 0 {
        score += 10.0 * fit_norm;
    }

    // Penalize bins whose residual deviates from mean (fragmentation control)
    let dev = (pr - mean_residual).abs();
    score += dev * 0.3 * (0.5 + progress);

    // Mild pressure against opening new bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * fit_norm;

    // New-bin candidate: make it attractive only when it genuinely helps
    if bin_residual == bin_capacity {
        score = 55.0 + 30.0 * fit_norm - 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue classes" (1..=9, or exact small multiples) are highly reusable.
    let pr = post_residual;
    let class_penalty = if pr == 0 {
        -60.0 // perfect fit: reward strongly
    } else if pr <= 9 {
        -40.0 + pr as f64 // small dead space, nearly perfect
    } else {
        // harmonic band: residual mod 10 classes
        let m = pr % 10;
        match m {
            0 => -15.0,          // round residual, easy to fill later
            1 | 3 | 7 | 9 => -5.0, // odd classes slightly favored
            2 | 8 => 3.0,
            4 | 6 => 6.0,
            _ => 0.0,            // 5
        }
    };
    score += class_penalty;

    // Lookahead coupling: does next item fit the post residual exactly / well?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0; // chain-perfect: reserve this bin for next item
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: mild penalty scaled by waste
            score += 8.0 * ((next_item_size - pr) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Penalize opening a new bin when decent fits exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // but if mean residual is tiny, new bin is fine
        if mean_residual < item_size as f64 {
            score -= 50.0;
        }
    }

    // Prefer tighter bins relative to current mean residual
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly prefer bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize unusable dead space: gaps too small for any plausible item (1..100 range).
    if post_residual > 0 {
        let dead = if post_residual < 10 { 1.0 } else { 0.0 };
        score += 25.0 * dead;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Dead-space gradient: quadratic penalty on small-but-nonzero gaps.
    if post_residual > 0 && post_residual < 40 {
        score += 0.35 * (40.0 - post_residual as f64);
    }

    // Lookahead: if the next item fits the post-residual, reward leaving that space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0;
    }

    // Last-chance bin: using the only fitting bin avoids opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: mildly favor already-open bins over opening new ones.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    // Mean residual coupling: prefer bins with residual near mean (balanced packing).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but don't leave dead space smaller than the
    // smallest possible item (1). Waste below the minimum item size is pure loss.
    if post_residual == 0 {
        score -= 40.0; // perfect fit reward
    } else if post_residual < 10 {
        score -= 25.0; // near-perfect, unusable for large items anyway
    }

    // Aggressive 2-step lookahead: strongly reward residual that exactly
    // accommodates the next item (chain packing).
    if next_item_size > 0 {
        let nd = next_item_size as f64;
        let diff = (post_residual as f64 - nd).abs();
        if post_residual as f64 >= nd {
            // Next item fits here: reward proportionally to tightness of chain.
            score -= 30.0 * (1.0 - diff / bin_capacity as f64);
            if diff == 0.0 {
                score -= 20.0; // exact 2-step chain
            }
        } else {
            // Next item won't fit: penalize residual just below next size
            // (worst dead space), scaled by stream progress.
            let progress = step_index as f64 / total_items.max(1) as f64;
            score += 10.0 * (1.0 - diff / nd) * (0.5 + progress);
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are "loose";
    // filling them is mildly good; bins already tight should be saved for
    // exact fits only.
    if (bin_residual as f64) > mean_residual + 15.0 {
        score -= 8.0;
    } else if (bin_residual as f64) < mean_residual - 15.0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a
    // new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: make opening a new bin unattractive by default,
    // but attractive when all open bins would leave large awkward residuals.
    if bin_residual == bin_capacity {
        let awkward = if fitting_bins_count == 0 {
            -100.0
        } else {
            let best_alt = post_residual as f64; // this call IS the new-bin case: post = 100 - item
            if best_alt > 50.0 { 5.0 } else { 25.0 }
        };
        score += awkward + 10.0 * (open_bins_count as f64).sqrt();
    }

    // Mild penalty for wasting capacity on small items in big residual bins
    // when item is small relative to residual.
    let waste_ratio = item_size as f64 / bin_residual.max(1) as f64;
    if waste_ratio < 0.3 && post_residual > 0 {
        score += 4.0 * (1.0 - waste_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already the base, amplify it.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 12.0;

    // Penalize dead space: post_residual too small for typical future items (1..100 unknown dist).
    if post_residual > 0 && post_residual < 10 {
        score += 18.0; // unusable sliver
    } else if post_residual >= 10 && post_residual < 25 {
        score += 6.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / post_residual.max(1) as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted potential
            score += 4.0;
        }
    }

    // Global pressure: many open bins with high mean residual -> encourage consolidation
    // into existing bins rather than opening new ones.
    let pressure = mean_residual / bin_capacity as f64;
    if bin_residual < bin_capacity {
        score -= pressure * 8.0;
    }

    // Time horizon: late in the stream, avoid opening new bins (harder to fill them).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 30.0 * progress;
        // But if no open bin fits well (large post_residual elsewhere), opening may be fine:
        if item_size as f64 / bin_capacity as f64 > 0.8 {
            score -= 15.0;
        }
    } else {
        // Existing bin: slightly reward using it late in the stream.
        score -= 5.0 * progress;
    }

    // Mild penalty for spreading across too many bins when mean residual is low (bins nearly full).
    if open_bins_count > 4 && mean_residual < 20.0 && bin_residual == bin_capacity {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let mut score = norm_pr * (1.0 + 0.8 * progress + 0.6 * progress * progress);

    // Reward tight fits: subtract a smooth function of item fraction
    let fill = item_size as f64 / cap;
    score -= 4.0 * fill * (1.0 - norm_pr) * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth hinge)
    if next_item_size > 0 {
        let gap = (next_item_size as f64 - pr).max(0.0) / cap;
        score += 6.0 * gap * gap;
        // Reward leaving room for the lookahead item
        let room = (pr - next_item_size as f64).max(0.0) / cap;
        score -= 2.0 * room * (1.0 - room);
    }

    // Last-chance bonus: only one bin fits, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Prefer bins below mean residual slightly (balance-aware)
    score += 0.3 * (pr - mean_residual) / cap;

    // New-bin candidate: keep it neutral-high unless open bins are poor fits
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo 10: small residues are dead space
    let post_mod = post_residual % 10;
    score += (10 - post_mod) as f64 * 1.5;

    // Bonus if next item fits exactly into the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            score -= 30.0;
        } else {
            // next item cannot use this residue -> penalize large leftover
            score += (post_residual as f64) * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when current bin would leave bad residue
    if bin_residual == bin_capacity {
        // opening a new bin is penalized mildly, but attractive if it would
        // preserve a "harmonic" residue (multiple of 10) for future items
        let new_res = bin_capacity - item_size;
        let frac = (new_res % 10) as f64;
        score = 40.0 + frac * 2.0;
        if next_item_size > 0 && next_item_size <= new_res {
            score -= 20.0;
        }
        if fitting_bins_count > 0 {
            score += 15.0; // discourage opening when existing bins fit fine
        }
    }

    // Tight-fit reward: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 40.0;

    // Prefer bins with residual close to item size (good packing)
    let waste = (bin_residual - item_size) as f64;
    score += waste * waste * 0.01;

    // Late in stream: consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0;

    // Slight preference for bins below mean residual (balance load)
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the smallest
    // plausible item are pure waste; amplify their cost super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual as i32) as f64 * 3.0;
    } else if post_residual == 0 {
        // Perfect fit is ideal.
        score -= 15.0;
    }

    // Reward tight fits relative to current residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 8.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: when many bins are open, discourage spreading;
    // when few are open, filling existing bins is cheap.
    score += (open_bins_count as f64) * 0.35;

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space for the known next item.
        score += 4.0;
    }

    // Slight pull toward bins near the mean residual (balanced packing).
    score += ((bin_residual as f64 - mean_residual) / bin_capacity as f64).abs() * 2.0;

    // Late in the stream, be more conservative about opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive if it enables a good future fit
        // or existing fits are poor.
        score += 20.0 - 10.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 8.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: exact match of post_residual to next item is gold.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let ni = next_item_size as f64;
        let diff = (pr - ni).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect chain: this bin will be exactly filled by next item
        } else if ni <= pr {
            score -= 25.0 * (1.0 - diff / 100.0); // next item also fits here
        } else {
            // next item won't fit; penalize leaving dead space that is too small to be useful
            score += 10.0 * (1.0 - pr / 100.0);
        }
        // Coupling with mean residual: if this bin's post residual is far below mean,
        // it's a well-used bin; reward closing it down toward zero.
        score -= 0.5 * (mean_residual - pr).max(0.0);
    } else {
        // Last item: minimize wasted space only.
        score += 5.0 * (post_residual as f64 / bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: make empty bin moderately attractive only when
    // no open bin fits well (large item relative to residuals).
    if bin_residual == bin_capacity {
        let open_benefit = if open_bins_count > 0 { (open_bins_count as f64).ln() * 2.0 } else { 0.0 };
        let item_pressure = item_size as f64 / bin_capacity as f64;
        // Empty bin score: baseline ~ post_residual (=capacity) minus pressure bonus.
        score = bin_capacity as f64 - 40.0 * item_pressure - open_benefit;
        if next_item_size > 0 && (next_item_size as f64) <= bin_capacity as f64 {
            // fresh bin can also take the next item; slight bonus
            score -= 5.0;
        }
    }

    // Late-stream consolidation: prefer filling existing bins as stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins whose residual closely matches the item.
    let tightness = (bin_residual - item_size) as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * (1.0 - tightness);

    // Penalize small dead space that nothing else can use later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: bonus if next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (post_residual - next_item_size) as f64 / bin_capacity as f64;
        } else {
            // Next item won't fit here; penalize leaving awkward residue.
            score += 8.0 * (next_item_size - post_residual).min(20) as f64 / 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 1 {
        // With alternatives, mildly prefer fuller bins (smaller residual).
        score += 0.15 * bin_residual as f64;
    }

    // Global state: many open bins with slack -> prefer filling existing ones.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 10.0 * (mean_residual / bin_capacity as f64);
    }

    // Time horizon: early in stream, opening new bins is cheaper; late, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 20.0 + 60.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin useful for upcoming large item
        }
    } else {
        score -= 15.0 * progress;
    }

    // Mild preference for bins above mean residual (balance load).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let norm_pr = pr / cap;
    let norm_it = it / cap;

    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let phase = progress * std::f64::consts::PI;
    let smooth = 0.5 * (1.0 + phase.cos()); // 1 early, 0 late
    score += 18.0 * norm_pr * norm_pr * (1.0 - smooth) * 100.0 / 100.0;
    score -= 14.0 * norm_pr * smooth;

    // Penalize large dead space quadratically, scaled by progress
    let dead = norm_pr * norm_pr;
    score += 30.0 * dead * (0.4 + 0.6 * progress);

    // Reward tight fits (small post residual) with cubic decay
    score -= 10.0 * (1.0 - norm_pr).powi(3) * (1.0 - progress);

    // Last-chance bin: strong reward, modulated by how well next item fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 * (1.0 - progress);
    }

    // Lookahead: penalize if post_residual is just barely unusable for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            let gap = (nxt - pr) / cap;
            score += 12.0 * gap * (1.0 - gap);
        } else {
            let slack = 1.0 - ((pr - nxt) / cap);
            score -= 8.0 * slack * slack;
        }
    }

    // Mean residual coupling: prefer bins deviating from mean in useful direction
    let dev = (mean_residual - pr) / cap;
    score += 6.0 * dev * dev * (1.0 - 2.0 * progress);

    // Prefer consolidating into fewer bins when many are open
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Harmonic class of post_residual: dead space classification
    // Residuals that are very small (<10) are unusable dead space -> penalize
    if post_residual < 10 {
        score += 8.0;
    }

    // Does next item fit in post_residual? Reward if yes (chain packing)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact-ish chain: reward proportionally to how well next item fills leftover
            let chain_tight = 1.0 - ((post_residual - next_item_size) as f64) / (bin_capacity as f64);
            score -= 10.0 * chain_tight;
        } else {
            // next item won't fit here; penalize if post_residual is a "trap" class
            // modulo arithmetic: post_residual in awkward bands (e.g. 11..=19, 21..=29) rarely reused
            let m = post_residual % 20;
            if m >= 11 {
                score += 4.0;
            }
            score += 3.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: neutral-ish baseline, but avoid opening new bins
    // when this item fits well in an existing one
    if bin_residual == bin_capacity {
        // new bin: post_residual = capacity - item_size, large; add penalty to prefer reusing bins
        score += 6.0;
        // but if item is huge and would leave tiny residue in any bin, new bin may be better:
        if item_size >= 90 {
            score -= 20.0;
        }
        // early stream: opening bins is fine to build a portfolio
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress < 0.2 {
            score -= 5.0;
        }
    }

    // Prefer bins below mean residual (more filled bins first keeps big gaps available)
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Integer-division threshold: bins whose residual class (residual / 25) is 0 are nearly full
    let quarter = bin_residual / 25;
    if quarter == 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible item are pure waste -> heavy penalty.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Penalize "awkward" residuals: too small for the lookahead item,
    // meaning this bin likely becomes dead space after this placement.
    if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
        score += 8.0;
    }
    // Reward residuals that can still host the lookahead item.
    if next_item_size > 0 && (next_item_size as u32) <= post_residual {
        score -= 5.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading across many open bins;
    // with many bins open, prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 * 1.5;
    if bin_residual == bin_capacity {
        // New-bin candidate: only attractive when existing bins are poor fits.
        score += pressure;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open new bin
        }
        // Late in the stream, opening fresh bins is more acceptable.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 3.0;
    } else {
        score -= pressure * 0.3;
    }

    // Prefer bins whose residual deviates favorably from the mean
    // (filling below-average-residual bins tightens the bin set).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score = post_residual as f64 * 1.0;

    // 2-step lookahead: reward when next item exactly fills the post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let post = post_residual as f64;
        if nxt <= post {
            let gap = post - nxt;
            // Perfect chaining bonus: next item leaves near-zero waste
            score -= (1.0 - gap / bin_capacity as f64) * 40.0;
            // Extra bonus for exact match
            if gap == 0.0 {
                score -= 25.0;
            }
        } else {
            // Next item cannot fit here: mild penalty for leaving awkward space
            score += (nxt - post).min(bin_capacity as f64) * 0.15;
        }
        // Penalize post_residual that is too small for anything useful (<10)
        if post < 10.0 {
            score -= 5.0; // small dead space is fine (bin nearly full)
        }
    } else {
        // Last item: just minimize waste
        score = post_residual as f64;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (denser bins)
    let post_f = post_residual as f64;
    if mean_residual > 0.0 {
        score += (post_f - mean_residual) * 0.2;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so we
    // only open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        // Penalize proportional to how well existing bins could fit;
        // a new bin is a fresh 100 residual, so score it slightly worse
        // than a mediocre fit but better than a terrible one.
        score = (bin_capacity as f64) * 0.95;
        if fitting_bins_count == 0 {
            score -= 100.0; // must open a new bin
        }
        // Late in the stream, be more reluctant to open new bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more strongly than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize large dead space quadratically: residuals that few future items
    // can use are wasted. Dead space threshold ~ half capacity.
    let dead = post_residual as f64;
    if dead > 0.0 && dead < 20.0 {
        // tiny slivers are nearly useless but also nearly full bins are fine
        score += 0.5;
    } else if dead >= 20.0 && dead < 40.0 {
        // awkward mid-range residual: hardest to fill later
        score += 6.0;
    }

    // Lookahead: if next item fits exactly in post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 15.0;
        } else if next_item_size <= post_residual {
            score -= 4.0 * (1.0 - (post_residual - next_item_size) as f64 / 50.0);
        } else {
            // next item won't fit here; slight penalty proportional to overflow
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing open bins are all fairly full (mean residual low) or the item
    // is large and would leave a bad residual everywhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin, modulated by stream progress and
        // how much residual capacity already exists across open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let mut new_bin_penalty = 10.0 + 10.0 * progress;
        // If open bins hold lots of free space collectively, discourage new bin.
        new_bin_penalty += 0.15 * mean_residual * (open_bins_count as f64).sqrt();
        // But if the item is huge and mean residual is small, new bin is fine.
        if (item_size as f64) > mean_residual + 5.0 {
            new_bin_penalty -= 8.0;
        }
        // Exact-fill temptation: a fresh bin paired with a big item leaves
        // capacity - item residual which may be useful; mildly encourage when
        // item is large.
        new_bin_penalty -= 0.05 * item_size as f64;
        score += new_bin_penalty;
    } else {
        // Mild preference for bins that are already relatively full
        // (first-fit-decreasing-like bias): fill emptier-space bins later.
        let fullness = 1.0 - (bin_residual as f64) / (bin_capacity as f64);
        score -= 3.0 * fullness;
    }

    // Global pressure: many open bins -> consolidate into existing bins.
    score += 0.3 * open_bins_count as f64 * (1.0 - tightness);

    // Small time-dependent exploration term: early on, be slightly more
    // willing to spread items (keeps options open); late, pack tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 2.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits, with non-linear polynomial shaping of post_residual
    let mut score = pr * (1.0 + 0.35 * pr_norm * pr_norm);

    // Smooth coupling with stream progress: early on, tolerate loose fits slightly;
    // late in stream, penalize wasted residual more aggressively.
    score *= 1.0 + 0.5 * progress * pr_norm;

    // Penalty if post_residual is too small to ever be useful for typical items
    let dead_zone = (1.0 - pr_norm).powi(3);
    score += 8.0 * dead_zone * (1.0 - progress);

    // Lookahead: reward if next item fits into post_residual (smooth kernel)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let slack = (pr - nx) / cap;
        if slack >= 0.0 {
            score -= 4.0 * (1.0 - slack.abs()) * (1.0 - 0.3 * progress);
        } else {
            score += 2.0 * (-slack * cap / 20.0).min(3.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0 + 4.0 * progress;
    }

    // Mild pressure against accumulating many open bins with high mean residual
    score += 0.05 * (open_bins_count as f64).ln() * (mean_residual / cap);

    // New-bin candidate: neutral-ish baseline, penalized when a decent fit exists
    if bin_residual == bin_capacity {
        score += 10.0 + 15.0 * progress - 2.0 * (fitting_bins_count as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the resulting residual: residuals divisible by common
    // item sizes (or leaving room for them) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else {
        // Class of residual modulo common size buckets (harmonic classes).
        let classes: [u32; 6] = [10, 20, 25, 40, 50, 80];
        let mut harmonic_bonus = 0.0;
        for (k, &c) in classes.iter().enumerate() {
            if pr % c == 0 {
                harmonic_bonus += (6 - k) as f64 * 4.0; // smaller divisors = more reusable
            }
        }
        score -= harmonic_bonus;

        // Dead space: residuals too small for the minimum item (1..=10) are near-useless.
        if pr < 10 {
            score += 45.0;
        }

        // If the lookahead item fits exactly in the post residual, big reward.
        if next_item_size > 0 && next_item_size <= pr {
            if pr - next_item_size < 10 {
                // next item would close this bin: excellent chaining.
                score -= 35.0;
            } else {
                score -= 15.0;
            }
        } else if next_item_size > pr {
            // Lookahead cannot use this bin; penalize proportional to wasted fit.
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer filling bins with below-average residual (tighter bins first),
    // keeping large-residual bins flexible.
    score += (bin_residual as f64 - mean_residual) * 0.25;

    // Mild penalty on opening new bins when many are already open.
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.5;
    }

    // Late in the stream, prefer closing bins out (reduce open bin count).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.8 && post_residual > 0 {
        score += 5.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it is too small for the smallest plausible item.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) > 0.0 && (post_residual as f64) <= dead_threshold {
        score += 1000.0; // unusable sliver: strongly avoid
    } else {
        // Non-linear penalty on wasted space, sharper for small post_residual.
        let pr = post_residual as f64;
        score += (pr / bin_capacity as f64).powi(3) * 40.0;
    }

    // Perfect fit bonus: exact fill is ideal.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Tight fit reward: small post_residual relative to capacity is good.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 25.0;

    // Last-chance pressure: if this is the only bin that fits, prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let open_pressure = (open_bins_count as f64).ln().max(0.0) * 12.0;
    if bin_residual == bin_capacity {
        score += open_pressure;
    } else {
        score -= open_pressure * 0.5;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 120.0; // chains a perfect future fit
        } else if (slack as f64) <= dead_threshold {
            score -= 90.0; // next item consumes the gap completely
        } else {
            score -= (1.0 - slack as f64 / bin_capacity as f64) * 30.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // Next item cannot use the remaining gap: mild penalty for stranding space.
        score += 20.0;
    }

    // Stream progression: late in the stream, be more conservative about
    // wasting residual capacity (fewer chances to recover).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0 * (post_residual as f64 / bin_capacity as f64);

    // Mean-residual coupling: if this bin's residual deviates far above the
    // mean, it is likely an outlier worth filling; if far below, penalize.
    let dev = bin_residual as f64 - mean_residual;
    score -= (dev / bin_capacity as f64).max(-1.0) * 15.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward when next item fits into post_residual (2-step lookahead match)
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 30.0 + 0.5 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 {
        // Penalize dead space that next item cannot use
        score += 10.0 + 0.3 * (post_residual as f64 - (next_item_size as f64).min(post_residual as f64));
    }

    // Relative residual vs mean residual: prefer bins tighter than average
    score += 0.4 * (bin_residual as f64 - mean_residual);

    // Last fitting bin: strong incentive to use it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Discard tiny unusable residuals
    if post_residual < 10 {
        score -= 15.0; // near-perfect fill is excellent
    } else if post_residual < 20 {
        score -= 5.0;
    }

    // Slight bias toward packing into fewer bins early on
    if open_bins_count > 1 {
        score += 2.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when fits are poor
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: best-fit preference with mild tightening
    score += 0.35 * (bin_residual as f64 - item_size as f64) / bin_capacity as f64;

    // Lookahead: strongly reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 6.0 + 4.0 * (1.0 - tightness);
    } else if next_item_size > 0 {
        // Penalize leaving a gap the next item cannot use, scaled by gap size
        let gap = post_residual as f64;
        score += 0.5 * gap * (gap / bin_capacity as f64);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate handling: penalize opening a new bin, but less when
    // the item would leave a very tight fit elsewhere or fits are scarce.
    if bin_residual == bin_capacity {
        let mut penalty = 14.0;
        if fitting_bins_count <= 1 {
            penalty -= 10.0;
        }
        // If no open bin can chain the next item but this new bin could, soften
        if next_item_size > 0 && post_residual >= next_item_size && fitting_bins_count == 0 {
            penalty -= 6.0;
        }
        // Late in the stream, prefer consolidating into open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        penalty += 4.0 * progress;
        score += penalty;
    }

    // Dead-space aversion: tiny post-residuals are excellent (near-perfect fit)
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    } else if post_residual == 0 {
        score -= 9.0;
    }

    // Global pressure: many open bins with low mean residual -> consolidate
    if open_bins_count > 2 && mean_residual < 40.0 && bin_residual != bin_capacity {
        score -= 2.0 * (40.0 - mean_residual) / 40.0;
    }

    // Prefer bins whose residual is close to the item (minimize fragmentation)
    let slack = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 1.5 * (slack / bin_capacity as f64).powi(3);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Base: penalize wasted residual, non-linearly
    let mut score = (x.powf(1.6)) * cap;

    // Smooth polynomial coupling: waste hurts more late in the stream
    let coupling = x * x * (1.0 - x) * (0.5 + 2.0 * progress);
    score += coupling * cap;

    // Tight fits reward: subtract for near-perfect packing, amplified over time
    let tightness = (1.0 - x).powf(3.0);
    score -= tightness * (10.0 + 30.0 * progress);

    // Last-chance bonus: only fitting bin -> strong reward, stronger early
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * (1.0 - progress);
    }

    // Lookahead: reward residual that fits next item smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fit_next = ((x * cap - n) / cap).max(0.0);
        score -= 15.0 * (1.0 - (fit_next / cap).powf(0.8));
    }

    // Penalize divergence from mean residual (keeps bin pool homogeneous)
    score += 0.3 * ((pr - mean_residual) / cap).abs() * (1.0 + progress);

    // Mild penalty for many open bins late in stream
    score += 0.02 * open_bins_count as f64 * progress;

    // New-bin candidate: penalize slightly so it only wins when fits are bad
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize into capacity fractions.
    let cap_f = bin_capacity as f64;
    let post_f = post_residual as f64;
    let frac = post_f / cap_f; // fraction of capacity left

    // Class 0: near-perfect fit (post_residual < 10) -> strong reward.
    if post_residual < 10 {
        score -= 40.0;
    } else if post_residual < 20 {
        score -= 18.0;
    }

    // Dead-space penalty for awkward residues (harmonic classes via integer division).
    // Residues in (30, 50] can rarely host another item (items >= 10 but typical mid sizes).
    if post_residual > 30 && post_residual <= 50 {
        score += 8.0;
    }
    if post_residual > 10 && post_residual < 20 {
        score += 12.0; // unusable for most items: dead space
    }

    // Modulo-class coupling: post_residual divisible classes hint at future fit.
    let r_mod = post_residual % 25;
    if r_mod == 0 {
        score -= 6.0; // clean harmonic slot (25/50/75)
    } else if r_mod < 10 {
        score -= 3.0; // leaves a small-item slot
    } else {
        score += 2.5;
    }

    // Lookahead: does next_item_size fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward chains, more if fit is tight (small leftover after next).
            let next_post = post_residual - next_item_size;
            score -= 10.0 + (next_post as f64).min(20.0) * 0.3;
        } else {
            score += 4.0; // this bin becomes dead after this placement
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 3 {
        score += (fitting_bins_count as f64 - 3.0) * 1.5; // many alternatives: be picky
    }

    // Prefer filling bins below the mean residual (balance toward fullness).
    score += (frac - (mean_residual / cap_f)) * 10.0;

    // Late in the stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and if any bin fits.
        score += 25.0 + progress * 30.0 + (fitting_bins_count as f64) * 10.0;
    } else {
        score -= progress * 5.0;
    }

    // Slight bias toward bins with larger residual generally (best-fit dominance).
    score -= (bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable gaps: dead space below the minimum item size (1..=20 typical)
    if post_residual > 0 {
        let dead = if post_residual < 10 {
            60.0 - post_residual as f64 * 3.0
        } else if post_residual < 20 {
            20.0 - post_residual as f64
        } else {
            0.0
        };
        score += dead;
    }

    // Reward perfect / near-perfect fits
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Penalize if next item almost fits (tempting but blocked gap)
    if next_item_size > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 && post_residual > 0 {
        score += 10.0;
    }

    // Last chance bin: strongly favor using it over opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open bins pressure: with many open bins, prefer consolidating into existing ones
    let pressure = open_bins_count as f64 * 2.0;
    score -= pressure.min(40.0);

    // New-bin candidate handling: empty bin should only win when fits are poor
    if bin_residual == bin_capacity {
        score += 45.0 + mean_residual * 0.2;
    }

    // Slight preference for tighter bins (small residual relative to mean)
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong penalty for wasted space; dead space below next item is worse.
    if next_item_size > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 1.5;
    }

    // Reward perfect chain: post_residual exactly fits next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }

    // Reward leaving usable space relative to mean residual.
    score -= (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Penalize opening a new bin when open bins could fit reasonably well.
    if bin_residual == bin_capacity {
        score += 20.0 + (open_bins_count as f64).sqrt() * 5.0;
        // But if it's a tight fit nowhere else, allow it (post_residual large is fine for fresh bin).
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    }

    // Mild reward for tight fits overall.
    score -= (item_size as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 1.7 * tightness * item_size as f64;

    // Penalize dead space that becomes unusable for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead: if next item fits exactly into the post-residual, reward heavily.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 55.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            // Next item can't use leftover space: penalize large waste.
            score += 0.35 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // New-bin candidate handling: opening a bin is attractive only when the
    // item is large or existing bins are crowded.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowded = mean_residual < item_size as f64 * 1.5;
        let big_item = item_size > bin_capacity / 2;
        if (crowded && open_bins_count > 2) || (big_item && fitting_bins_count > 1) {
            score -= 12.0 + 10.0 * (1.0 - progress);
        } else {
            score += 30.0 + mean_residual * 0.2;
        }
    }

    // Mild preference for filling bins with low residual among many open bins.
    score += 0.05 * (bin_residual as f64 - mean_residual).max(0.0);

    // Encourage consolidation when many bins are open.
    score += 0.03 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear penalty on post_residual, modulated by stream progress:
    // dead space matters more as the stream advances.
    let pr = post_residual as f64;
    let pr_norm = pr / bin_capacity as f64;
    score += (pr_norm * pr_norm) * bin_capacity as f64 * (0.25 + 0.75 * progress);

    // Reward tight fits: small post_residual relative to item size.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * tightness * 20.0 * (1.0 - progress);

    // Last-chance bonus: strongly prefer the only bin that fits.
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead coupling: favor bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 >= nxt {
            score -= 10.0 * (1.0 - pr_norm);
        } else {
            score += 8.0 * (nxt - pr) / bin_capacity as f64;
        }
    }

    // Penalize bins far from mean residual (fragmentation signal), smoothly.
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev * dev;

    // Mild pressure to consolidate into fewer bins when many are open.
    score += 0.05 * open_bins_count as f64 * pr_norm;

    // Slight preference for using existing bins vs opening new ones early.
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) + 6.0 * pr_norm;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Harmonic class of the item: capacity fractions (integer division thresholds)
    let item_class = item_size / (bin_capacity / 4); // 0:tiny,1:small,2:medium,3:large
    let next_class = next_item_size / (bin_capacity / 4);

    // Reward tight fits: post_residual in low harmonic band
    if post_residual <= bin_capacity / 10 {
        score -= 25.0;
    } else if post_residual <= bin_capacity / 4 {
        score -= 8.0;
    } else {
        // penalize large dead space, modulated by mean residual
        score += 0.3 * (pr - mean_residual).abs();
    }

    // Perfect fill bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Pairing logic: can next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // complementary pairing reward, stronger for large+large or large+small harmony
            score -= 12.0 + 0.15 * (next_item_size as f64);
            if item_class + next_class >= 3 {
                score -= 6.0; // dense harmonic combination
            }
        } else {
            // next item won't fit here: penalize if this bin becomes a dead-end
            score += 6.0 + 0.1 * pr;
        }
    } else {
        // last item: prefer minimal waste anywhere
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when no good fits exist
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        } else {
            // discourage opening new bin unless existing fits are terrible
            score += 15.0 + 0.2 * mean_residual;
            if item_class >= 2 {
                score -= 10.0; // big items may warrant fresh space
            }
        }
    }

    // Stream progression: early on, be exploratory (favor new bins slightly); late, consolidate
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress) - 5.0 * progress;
    }

    // Modular threshold on post_residual: residues near multiples of 10 pair well with common sizes
    let residue_mod = post_residual % 10;
    if residue_mod <= 2 {
        score -= 4.0;
    } else if residue_mod >= 8 {
        score += 3.0;
    }

    // Penalize spreading across too many open bins
    score += 0.05 * open_bins_count as f64 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strict dead-space avoidance: gaps too small for the smallest plausible item are wasted.
    // Penalize "unusable" residuals superlinearly (gap < ~15 units is nearly dead space).
    let dead_threshold = 15.0;
    if post > 0.0 && post < dead_threshold {
        score += (dead_threshold - post) * (dead_threshold - post) * 2.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = 1.0 - post / cap.max(1.0);
    score -= tightness * 20.0;

    // Reward perfect fill.
    if post == 0.0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate implicitly via open_bins_count coupling).
    score += open_bins_count as f64 * 0.5;

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 * (1.0 - slack / cap.max(1.0));
    }
    // If next item would NOT fit here, mildly penalize leaving a medium gap that helps nothing.
    else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Progress pressure: later in the stream, be more conservative about residual waste.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += post * progress * 0.5;

    // New-bin candidate (bin_residual == bin_capacity): make it unattractive unless
    // no reasonable existing option exists — the fitting_bins_count==1 bonus above
    // dominates for real bins; add a mild constant penalty here.
    if bin_residual == bin_capacity {
        score += 25.0;
    } else {
        // Mild bonus for using a bin whose residual is below mean (consolidate fragmented bins).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: reward chains where the next item fits into the leftover space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain bonus: leftover space is exactly reusable by the next item.
            score -= (next_item_size as f64) * 0.6;
            // Extra reward for a near-perfect two-item packing.
            let gap = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Penalize dead space relative to what the next item needs.
            let dead = next_item_size.saturating_sub(post_residual) as f64;
            score += dead * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize proportionally to how many open bins
    // could already fit the item.
    if bin_residual == bin_capacity {
        score += 10.0 + 4.0 * fitting_bins_count as f64 + 5.0 * progress;
    }

    // Prefer bins whose residual is tighter than the fleet mean (good fits).
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Penalize tiny unusable fragments of dead space.
    if post_residual > 0 && post_residual < 5 {
        score += 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (below min item size 1..100 -> use ~10 as conservative threshold, but items can be as small as 1).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // nearly unusable sliver
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // perfect pair
        } else if next_item_size < post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // next item cannot follow here; mild penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 6.0 * (over / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin should only win when current fit is poor.
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: its residual equals capacity, which already scores high;
        // add a mild exploration penalty scaled by how many bins are open and stream progress.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 + 3.0 * (open_bins_count as f64).ln().max(0.0) + 10.0 * progress;
        // but if no existing bin fits (this is the only candidate), the above is offset by the
        // last-chance logic only for open bins; give the fresh bin a fair chance when mean
        // residual of open bins is tiny.
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Prefer bins whose residual deviates favorably from the mean (consolidate space).
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild time-horizon adaptation: early in stream, be greedy for tight fits; later, slightly
    // favor balancing residuals to keep future options open.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * ((post_residual as f64 - mean_residual) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: quadratic penalty on wasted residual, modulated by stream progress
    let mut score = norm_pr * norm_pr * (1.0 + 2.0 * progress) * cap;

    // Smooth non-linear coupling: residual vs item size interaction
    score += 8.0 * (norm_pr - norm_item) * (norm_pr - norm_item) * (1.0 - progress);

    // Cubic coupling of post-residual with progress (favor tight fits later)
    score += 6.0 * norm_pr * norm_pr * norm_pr * cap * progress;

    // Lookahead: reward residual that can fit next item (smoothly)
    if next_item_size > 0 {
        let fits_next = if pr >= next_item_size as f64 { 1.0 } else { 0.0 };
        let gap = (pr - next_item_size as f64).abs() / cap;
        score -= 10.0 * fits_next * (1.0 - gap) * (1.0 - 0.5 * progress);
        score += 3.0 * gap * gap * cap;
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - norm_pr) * (1.0 + progress);
    }

    // Mean residual dispersion coupling
    score += 2.0 * (norm_pr - mean_residual / cap).abs() * cap * 0.5;

    // Penalize opening new bins when open bins exist and fit well
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 4.0 + 6.0 * (1.0 - norm_item) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common item sizes
    // (10, 20, 25, 50) is more likely to be filled later -> reward.
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fit
    } else {
        if pr % 10 == 0 { score -= 8.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 6.0; }
        // dead-space penalty: small unusable leftovers
        if pr < 10 {
            score += 25.0 * (10 - pr) as f64;
        } else if pr < 20 {
            score += 6.0;
        }
    }

    // Lookahead coupling: can next item exactly fill the post-residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0; // chain fit
        } else if next_item_size <= pr {
            let rem = pr - next_item_size;
            if rem % 10 == 0 || rem == 0 { score -= 10.0; }
            score += rem as f64 * 0.05;
        } else {
            // next item cannot use this residual: penalize proportionally
            score += (next_item_size.min(80) as f64) * 0.08;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Tightness reward: relative fill quality
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 12.0;

    // New-bin candidate: penalize opening a new bin mildly, more when
    // good fitting bins exist or stream is late.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 18.0 + 20.0 * progress;
        if fitting_bins_count > 0 {
            score += 10.0;
        }
        // opening new bin is attractive if open bins have tiny residuals
        if mean_residual < 15.0 {
            score -= 14.0;
        }
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Mild preference to balance load across many open bins
    if (bin_residual as f64) > mean_residual * 1.5 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item
    // (min item size 1) are heavily penalized; tiny gaps are pure waste.
    if post_residual > 0 {
        score += 12.0 * (1.0 - (post_residual as f64) / 10.0).max(0.0);
        // Non-linear dead-space penalty for residuals that cannot fit a
        // meaningful item (below 10 units is nearly unusable).
        if post_residual < 10 {
            score += 25.0;
        }
    }

    // Reward tight fits (small post_residual relative to bin capacity).
    score -= 8.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Open-bin pressure: discourage spreading across many bins.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the resulting post_residual,
    // reward keeping this bin useful; otherwise slight penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 3.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual is below average
    // (fill the emptiest bins first to keep tight bins available).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: penalize opening a fresh bin unless current bins
    // would leave terrible dead space.
    if bin_residual == bin_capacity {
        score += 10.0;
        // Opening a new bin is more attractive late in the stream when
        // open-bin pressure is high.
        score -= 0.2 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward a perfect fit for the NEXT item.
    if next_item_size > 0 {
        let pr = post_residual as f64;
        let nx = next_item_size as f64;
        if post_residual == next_item_size {
            // Perfect 2-chain: this bin will be exactly consumed by the next item.
            score -= 40.0;
        } else {
            // Smooth closeness reward: the closer post_residual is to next_item_size,
            // the better the expected 2-step packing density.
            let gap = (pr - nx).abs();
            score -= 18.0 * (-gap / 12.0).exp();
            // Penalize overshoot that leaves dead space the next item can't use.
            if pr > nx && pr - nx < 10.0 {
                score += 6.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoids fragmentation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a bin is only attractive when the current
    // item is large (leaving a large, reusable residual) or the stream just started.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large_item_bonus = item_size as f64 * 0.35; // big items start fresh bins well
        score += 30.0 - large_item_bonus + 10.0 * progress;
        // If next item is huge and residual here would be tiny, opening fresh is fine.
        if next_item_size >= post_residual && post_residual < 15 {
            score -= 12.0;
        }
    }

    // Contextual coupling with mean residual: prefer bins whose post_residual sits
    // below the mean (concentrate filling, keep big holes available elsewhere).
    score += 0.15 * (mean_residual - post_residual as f64);

    // Mild preference for tight fits overall (small post_residual), softened so
    // near-zero dead space doesn't dominate the lookahead signal.
    score += 0.05 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize creating small unusable dead space (post_residual below typical min item).
    if post_residual > 0 && post_residual < 10 {
