        let fragmentation = mean_residual / bin_capacity as f64;
        // penalize new bin when open bins are mostly full (well-packed state)
        score += 18.0 * (1.0 - fragmentation);
        // early stream: mild penalty to encourage filling bins first
        score += 10.0 * (1.0 - progress);
        // many open bins: discourage yet another bin
        score += 1.5 * (open_bins_count as f64).sqrt();
        // if the item is large, a fresh bin is more acceptable
        score -= 0.06 * item_size as f64;
    } else {
        // favor bins whose residual is close to the mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.03 * dev;
    }

    // Late stream: prefer exactness more strongly since fewer chances remain.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear coupling of post residual with stream progress:
    // later in the stream, large residuals (wasted space) are penalized more strongly.
    let poly = norm_pr * norm_pr * (norm_pr - 1.0) * (norm_pr - 1.0); // smooth bump in mid-range
    score += poly * cap * (0.5 + progress) * 2.0;

    // Penalize residual that cannot fit the lookahead item (dead space for next item)
    if next_item_size > 0 && (post_residual as u64) < (next_item_size as u64) {
        let gap = (next_item_size as f64 - pr).max(0.0);
        score += gap * (0.5 + progress);
    } else if next_item_size > 0 {
        // reward residuals that nicely fit the next item
        let tight = 1.0 - ((pr - next_item_size as f64).abs() / cap);
        score -= tight * 3.0 * (1.0 - progress);
    }

    // Last-chance bonus: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0 * (0.5 + progress);
    }

    // Mild penalty when this bin is far below mean residual (fragmentation signal)
    let dev = (pr - mean_residual) / cap;
    score += dev * dev * 5.0 * (1.0 - progress);

    // New-bin candidate: make it attractive only when its raw residual beats tight fits
    if bin_residual == bin_capacity {
        score += 2.0 + 6.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "good" classes (small, or near multiples of common item sizes).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize dead space quadratically, but give harmonic-class discounts.
    score += 12.0 * frac * frac;

    // Modulo classes: residuals that are exact multiples of small item sizes
    // (e.g. 20, 25, 50) are more likely to be filled later.
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        30.0 // perfect fit: best possible outcome
    } else if pr % 50 == 0 || pr % 25 == 0 {
        14.0
    } else if pr % 10 == 0 {
        9.0
    } else if pr % 20 == 0 {
        11.0
    } else if pr < 10 {
        2.0 // tiny dead space, nearly full
    } else {
        0.0
    };
    score -= class_bonus;

    // Harmonic threshold on next_item_size: if the lookahead item fits the
    // post-residual exactly or within a good class, reward strongly.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr && pr % next_item_size == 0 {
            score -= 12.0;
        } else if next_item_size > pr {
            score += 6.0; // lookahead won't fit here; mild penalty
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // or many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut nb = 8.0;
        if item_size > 60 { nb -= 6.0; }
        if mean_residual > 35.0 && open_bins_count > 3 { nb += 10.0; }
        if next_item_size > 0 && next_item_size > item_size { nb += 4.0; }
        score += nb * (0.5 + 0.5 * (1.0 - progress));
    }

    // Mild tightness preference: prefer bins that were already partially used
    // (avoid spreading load across many bins).
    let used = (bin_capacity - bin_residual) as f64;
    score -= 0.05 * used;

    // Coupling: prefer bins whose residual is close to mean (balanced packing),
    // but only mid-stream.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.04 * dev * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect or near-perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 300.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1) are pure loss; residuals below the typical item
    // scale are likely unusable gaps -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 250.0;
    } else if post_residual < 25 {
        score += 80.0;
    }

    // Lookahead: if the next item fits exactly into post_residual,
    // strongly favor this bin (chain packing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 400.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // next item cannot use the leftover -> dead space likely
        score += 60.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Open-bins pressure: with many open bins, discourage spreading;
    // with few open bins, opening a new one is cheaper.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0) * (20.0 + 30.0 * progress);
    score += pressure * (post_residual as f64 / bin_capacity as f64);

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is a good consolidation target.
    let residual_diff = mean_residual - bin_residual as f64;
    score -= residual_diff * 0.5;

    // New-bin candidate handling: an empty bin should only win when no
    // open bin offers a tight fit. Make the empty bin attractive only
    // for large items or when the fit elsewhere would be terrible.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        if tightness > 0.6 {
            score -= 120.0; // large item: fresh bin is fine
        } else {
            score += 90.0;  // small/medium item: prefer existing bins
        }
        // Early in the stream with few bins, a new bin is cheap.
        if open_bins_count <= 2 {
            score -= 40.0;
        }
    }

    // Slight preference for filling fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: post_residual is the base; reward tight fits.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let nis = next_item_size as f64;

    // 2-step lookahead: if next item fits exactly into post_residual, strongly reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - gap / cap);
    }

    // Penalize leaving dead space the next item cannot use.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.6 * pr;
    }

    // Relative-to-mean coupling: bins with residual below mean are "used up";
    // placing there is good (tight packing), above mean is wasteful.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev.max(-2.0).min(2.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 6.0 + 0.35 * (post_residual as f64);
        // Early in stream, new bins are cheap; later, prefer filling existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 * progress;
    }

    // Slight preference for larger items into tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (item_size as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (low post_residual)
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 0.0 };
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small dead space that no future item (min size ~1..10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 22.0;
    } else if post_residual >= 10 && post_residual <= 30 {
