            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + slack);
        } else if next_item_size > post_residual && post_residual > 0 {
            score += 6.0; // next item won't fit here; deprioritize slightly
        }
    }

    // Last-chance bonus: only one fitting bin -> avoid opening new bins
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early on, be conservative with tight fits; later, pack tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * fit_ratio;

    // Global pressure: many open bins with high mean residual -> prefer using existing space
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 3.0;
    }
    if open_bins_count > 6 {
        score -= 0.5 * (open_bins_count as f64).ln();
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let poor_fit = fit_ratio < 0.55 && fitting_bins_count > 1;
        if poor_fit {
            score -= 5.0; // allow opening fresh bin when fits are wasteful
        } else {
            score += 25.0; // otherwise prefer existing bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

