    let mut score = pr * (1.0 + 0.8 * progress * norm_pr);

    // Penalize dead space more as the stream progresses (quadratic coupling)
    score += 25.0 * progress * norm_pr * norm_pr;

    // Reward tight fits (small post residual), smoothly scaled by progress
    score -= 20.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - progress);

    // Last-chance bin bonus (avoid opening a new bin)
    if fitting_bins_count == 1 {
        score -= 30.0 + 20.0 * progress;
    }

