            score -= 10.0 * (1.0 - (gap / cap).abs());
        } else {
            score += 8.0 * (-gap / cap);
        }
    }

    // Mild preference for consolidating into fewer bins
    score += 0.5 * open_bins_count as f64 * norm_pr;

    // Mean residual interaction: favor bins near mean residual
    let dev = (pr - mean_residual) / cap;
    score += 6.0 * dev * dev * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity split into 8ths
    let eighth = bin_capacity / 8;
    let class = post_residual / eighth; // 0..=8 harmonic class
    let class_center = (class * eighth + eighth / 2) as f64;

    // Reward placements landing exactly on harmonic boundaries (perfect fits)
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual % (bin_capacity / 4) == 0 {
        score -= 25.0;
    } else if post_residual % (bin_capacity / 8) == 0 {
        score -= 12.0;
    }

    // Penalize dead space in the lowest harmonic classes (unusable slivers)
    if class == 0 {
        score += 30.0 * (1.0 - post_residual as f64 / eighth.max(1) as f64);
    }

    // Lookahead coupling: if next item fits into post_residual, big reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let next_class = next_item_size / eighth.max(1);
        score -= 20.0 + 2.0 * next_class as f64;
        // exact chain fit is excellent
        if next_item_size == post_residual {
            score -= 40.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item won't fit here; penalize leaving a mid-class orphan
        score += 8.0 * (class as f64) / 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: mildly penalize opening a new bin unless
    // the item is large relative to capacity or open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / cap;
        score += 55.0 - 20.0 * (item_size as f64 / cap) - 15.0 * fragmentation - 10.0 * progress;
    }

    // Tight-fit bonus: item fills most of the bin
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.85 {
        score -= 18.0 * fill_ratio;
    }

    // Small global tie-breaker toward bins tighter than the mean residual
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Integer-division threshold on post_residual vs next item harmonic class
    let nr_class = (next_item_size / eighth.max(1)) as i32;
    let pr_class = class as i32;
    if nr_class == pr_class && next_item_size > 0 && next_item_size <= post_residual {
        score -= 10.0; // same harmonic class chain
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
