    score -= 20.0 * (1.0 - norm_post).powi(3) * (0.5 + 0.5 * progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - progress);
    }

    // Penalize bins with residual far from mean (fragmentation avoidance)
    score += 0.3 * (post - mean_residual).abs() * (0.5 + progress);

    // Lookahead: penalize if next item cannot use this bin's post-residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post < next {
            score += 10.0 * (next - post) / cap * (0.5 + progress);
        } else {
            score -= 5.0 * (post - next).min(next) / cap;
        }
    }

    // New-bin candidate: penalize opening new bins early, allow late
    if bin_residual == bin_capacity {
        score += 40.0 * (1.0 - progress) - 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins
    score += 0.5 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // residue classes (mod 10) are near-perfect fits; reward them strongly.
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit
    } else {
        let class = post % 10;
        // Residues 1..3 are dead space (nothing but tiny items fits): penalize.
        if class >= 1 && class <= 3 {
            score += 12.0 + (4 - class) as f64 * 3.0;
        }
        // Residues 8..9 leave useful room: reward.
        if class >= 8 {
            score -= 8.0;
        }
    }

    // Integer-division thresholds on post_residual: quarters of capacity.
    let quarter = bin_capacity / 4;
    if post < quarter {
        score += 6.0; // small leftover, mostly wasted
    } else if post <= 2 * quarter {
        score -= 4.0; // sweet spot: room for medium items
    }

    // Lookahead coupling: if the next item fits the post residual exactly
    // or harmonically (same mod-10 class), reward this bin.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size <= post {
            let gap = post - next_item_size;
            if gap % 10 == 0 {
                score -= 10.0;
            }
            if gap <= 3 {
                score += 5.0; // would create dead space next step
            }
        } else {
            // next item cannot use this bin's leftover: mild penalty
            score += 3.0;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Prefer fuller bins relative to the mean residual of open bins.
    score -= (mean_residual - post_residual as f64) * 0.15;

    // New-bin candidate: penalize opening a bin unless current bins are bad.
    if bin_residual == bin_capacity {
        score += 25.0
            + (open_bins_count as f64).sqrt() * 2.0
            - (mean_residual / bin_capacity as f64) * 20.0;
        // If next item is huge and mean residual is small, new bin is fine.
        if next_item_size >= bin_capacity / 2 && mean_residual < bin_capacity as f64 / 4.0 {
            score -= 30.0;
        }
    }

    // Late-stream tightening: as the stream progresses, waste matters more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += score * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 {
        // A residual is "dead" if it is smaller than the smallest plausible item.
        // Treat residual < 12 as dead space; the closer to zero, the worse the waste
        // relative to the capacity consumed.
        if post_residual < 12 {
            score += 60.0 * (12.0 - post_residual as f64) / 12.0;
        }
        // Moderate gaps (12..=25) are semi-dead: mild penalty to prefer tighter fits.
        else if post_residual <= 25 {
            score += 8.0 * (25.0 - post_residual as f64) / 13.0;
        }
    }

    // Perfect fits are strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Penalize blocking the next item into a gap that cannot hold it.
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Open-bin pressure: discourage opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        // Brand-new empty bin candidate: penalize proportional to open bin count,
        // so it only wins when existing bins are genuinely poor fits.
        score += 25.0 + 2.5 * open_bins_count as f64;
        // Late in the stream, opening new bins is even less attractive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    } else {
        // Reward using already-open bins, more so when many are open.
        score -= 1.5 * open_bins_count as f64;
    }

    // Last-chance bin: strongly prefer filling the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Align with mean residual: bins far below the mean residual are poor fits.
    score += 0.15 * (mean_residual - bin_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits (small post_residual).
    score = post_residual as f64 * 1.0;

    // Aggressive 2-step lookahead: reward when next item exactly matches post_residual.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if nxt <= post {
            let match_bonus = 40.0 * (1.0 - (post - nxt) / post.max(1.0));
            score -= match_bonus;
        } else {
            // Next item can't fit here; penalize large dead space more.
            score += 0.5 * (nxt - post);
        }
        // If post_residual can hold next item AND next item then leaves tiny remainder.
        if next_item_size <= post_residual && post_residual - next_item_size <= 5 {
            score -= 30.0;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    let dev = post_residual as f64 - mean_residual;
    score += 0.3 * dev;

    // Last-chance bin (only fitting bin): strongly favor using it to avoid new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Penalize creating tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let good_fit_exists = fitting_bins_count > 0 && post_residual as f64 <= mean_residual + 5.0;
        if good_fit_exists {
            score += 60.0; // discourage opening new bin
        } else {
            score -= 10.0; // encourage fresh bin when fits are bad
        }
    }

    // Late in stream: consolidate, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = if bin_residual > 0 { item_size as f64 / bin_residual as f64 } else { 1.0 };
    score -= 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 / (1.0 + gap);
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: penalize opening a new bin when open bins exist,
    // unless the item fits poorly everywhere (large residual waste avoided later).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_open_residual = if open_bins_count > 0 { mean_residual } else { bin_capacity as f64 };
        // Opening is attractive only if existing bins have large residuals that would be wasted,
        // or late in the stream when consolidation matters less.
        let waste_threshold = 0.35 * bin_capacity as f64;
        if avg_open_residual < waste_threshold && open_bins_count > 0 {
            score += 45.0 + 20.0 * (1.0 - progress);
        } else {
            score += 10.0 * (1.0 - progress);
        }
    }

    // Mild pressure against hoarding many open bins with small residuals.
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count.min(20) as f64).ln() * (post_residual as f64 / bin_capacity as f64);
    }

    // Prefer bins whose residual is closest to item size (exact-ish packing).
    let slack = (bin_residual as i64 - item_size as i64).unsigned_abs() as f64;
    score += 0.15 * slack;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (low post_residual), with non-linear shaping
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Stream-progress coupling: early on, tolerate waste; later, punish it harder
    let progress_weight = 0.5 + 2.0 * progress * progress;
    score += progress_weight * pr * norm_pr;

    // Penalize leaving dead space that the next item cannot use
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt > pr {
            score += (nxt - pr) * (0.6 + progress);
        } else {
            // Reward exact usability of leftover space
            score -= 3.0 * (pr - nxt).abs().sqrt() * (1.0 - progress);
        }
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 10.0 * progress;
    }

    // New-bin candidate: mildly penalize opening new bins early, allow later
    if bin_residual == bin_capacity {
        let pressure = (open_bins_count as f64) * 0.05 + progress * 2.0;
        score += 8.0 + pr * (0.3 - 0.25 * progress) - pressure;
    }

    // Coupling with mean residual: bins far from the mean get slight regularization
    let dev = (pr - mean_residual).abs();
    score += 0.15 * dev * (0.5 + progress);

    // Reward filling bins deeply (non-linear in fill fraction)
    let fill = (bin_residual as f64 - pr) / cap;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: which capacity tenth it falls into.
    let class = post_residual / 10; // 0..10
    let class_center = (class * 10 + 5) as f64;

    // Reward placements landing in "usable" harmonic classes.
    // Classes 0 (perfect/near-perfect fill) are gold; classes that cannot
    // hold the smallest plausible item (1..10 residual) are dead space.
    match class {
        0 => score -= 40.0,                       // near-perfect fill
        1 => score -= 18.0,                       // holds tiny items
        2 => score -= 10.0,
        3 => score -= 6.0,
        4 => score -= 3.0,
        5 => score -= 1.0,
        6 => score += 1.0,
        7 => score += 3.0,
        8 => score += 6.0,
        9 => score += 10.0,
        _ => {}
    }

    // Lookahead: does next_item_size fit in post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Exact harmonic match: next item leaves a clean class again.
            let next_post = post_residual - next_item_size;
            if next_post % 10 == 0 {
                score -= 25.0;
            } else {
                score -= 12.0;
            }
        } else {
            // Next item cannot use this bin's leftover: penalize dead space.
            score += (next_item_size - post_residual) as f64 * 0.8;
        }
    } else {
        // Last item: prefer tightest fill.
        score -= 15.0;
    }

    // Modulo coupling: residuals that are multiples of 10 partition nicely.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }
    // Odd leftovers below 10 are almost unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current item is large relative
    // to capacity and mean residual across open bins is already low.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap_f;
        score = cap_f - item_frac * 60.0 + (open_bins_count as f64) * 2.0;
        if mean_residual < item_frac * cap_f {
            score -= 20.0;
        }
    }

    // Mild stream-position drift: later in stream, tighten packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item are pure waste. Penalize them quadratically.
    if post_residual < 10 {
        let dead = 10 - post_residual;
        score += 40.0 + (dead as f64) * (dead as f64) * 3.0;
    } else if post_residual < 20 {
        // Semi-dead zone: only large future items could use this gap.
        score += 12.0 + (20 - post_residual) as f64;
    }

    // Perfect fit bonus: fully packed bins are ideal.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post
    // residual, strongly reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 45.0;
        } else if slack < 10.0 {
            score -= 20.0 - slack;
        } else {
            score -= 5.0;
        }
    }
    // If next item would be blocked by a tiny residual, mild penalty.
    if next_item_size > 0 && next_item_size <= item_size && post_residual < next_item_size && post_residual < 10 {
        score += 8.0;
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using
    // it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // with few open bins, a fresh bin is cheaper.
    let openness = (open_bins_count as f64).ln() + 1.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, costly when many bins open.
        score -= 18.0 / openness;
        // Never open a new bin when an existing bin would be a near-perfect fit.
        if post_residual >= 0 && bin_residual - item_size < 15 && fitting_bins_count > 0 {
            score += 25.0;
        }
    } else {
        score -= 4.0 / openness;
    }

    // Mean-residual alignment: prefer bins whose residual is close to the
    // mean (keeps the pool homogeneous and predictable).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Late-stream tightening: as the stream progresses, be greedier about
    // filling existing bins tightly.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with the next item is gold.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // bin becomes exactly filled by next item
        } else {
            let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
            // penalize mismatch, worse when next item is larger (would spill)
            let mut mismatch = gap * 0.9;
            if next_item_size > post_residual {
                mismatch += 15.0;
            }
            score += mismatch;
        }
    }

    // Dead-space penalty: tiny unusable leftovers.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Relative-to-mean coupling: prefer bins whose residual deviates favorably.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = if next_item_size > 0 { next_item_size as f64 } else { item_size as f64 };
        let poor_fit = (post_residual as f64 - pressure).abs();
        score += 12.0 + 0.4 * mean_residual - 0.2 * poor_fit;
        // late in stream, prefer reusing bins
        score += (step_index as f64 / total_items.max(1) as f64) * 10.0;
    }

    // Slight preference for tighter bins overall.
    score += (bin_residual as f64 / bin_capacity as f64) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // If next item is large, prefer keeping bigger bins flexible.
        if next_item_size > 50 {
            score += 0.15 * post_residual as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate logic: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        if fit_ratio > 0.9 || (fitting_bins_count <= 1 && pressure < 0.2) {
            score -= 15.0;
        } else {
            score += 40.0 + 10.0 * pressure;
        }
    }

    // Global state: mildly discourage spreading across many open bins early.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Mean residual alignment: prefer bins close to the average residual (balance).
    score += 0.1 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Smooth polynomial coupling: residual waste weighted by stream progress
    let norm_pr = pr / cap;
    let poly = norm_pr * norm_pr * (1.0 + 2.5 * progress) - norm_pr * progress * 0.8;
    score += poly * cap * 0.5;

    // Tight fit reward: near-zero post residual strongly favored
    let tightness = (-norm_pr * 6.0).exp();
    score -= tightness * 6.0;

    // Lookahead: penalize if post residual can't hold next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += (ns - pr) * 0.6;
        } else {
            let usable = (ns / pr.min(cap)).min(1.0);
            score -= usable * 3.0;
        }
    }

    // Last-chance bonus: only one bin fits, avoid opening new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 4.0 + 3.0 * progress;
    }

    // New-bin candidate handling: prefer it early or when open bins are full-ish
    let is_new = (bin_residual as f64 - cap).abs() < 1e-6;
    if is_new {
        score += 2.0 + 6.0 * (1.0 - progress) + 0.15 * open_bins_count as f64;
        if next_item_size > 0 && (next_item_size as f64) <= cap * 0.5 {
            score -= 1.5;
        }
    }

    // Mean residual coupling: avoid fragmenting bins when average slack is low
    score += (mean_residual - pr).abs() * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "usable" classes
    // (multiples of common small sizes) are penalized less for waste.
    let classes: [u32; 6] = [10, 20, 25, 50, 100, 5];
    let mut harmonic_bonus = 0.0;
    for c in classes.iter() {
        if post_residual >= *c && post_residual % c == 0 {
            harmonic_bonus -= 6.0 * (*c as f64 / 10.0);
        }
