    // Integer-division threshold: post_residual buckets
    let bucket = post_residual / 10;
    score += match bucket {
        0 => -15.0,          // near-perfect fit
        1..=3 => -8.0,       // good fit
        4..=6 => 2.0,        // mediocre
        _ => 6.0,            // large leftover
    };

    score += harmonic_bonus;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless this bin would otherwise leave bad dead space
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // prefer new bin when all open bins would leave awkward residuals
        let awkward = (mean_residual - item_size as f64).abs() < 5.0 && mean_residual < 30.0;
        if awkward {
            score -= 4.0 + 6.0 * progress;
        } else {
            score += 14.0;
        }
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 18.0;
        } else if next_item_size <= post_residual {
            score -= 5.0;
        } else {
            score += 4.0;
        }
    }

    // Prefer filling bins that are already tight relative to mean residual
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Modulo coupling between item_size and bin_capacity
    if bin_capacity % item_size.max(1) == 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64) / 10.0;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 5 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // (penalize the new-bin candidate implicitly by rewarding existing bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 5.0 + 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (0.5 + progress);
    } else {
        // New-bin candidate: penalize more when many bins are already open.
        score += 8.0 * (open_bins_count as f64 / (open_bins_count as f64 + 4.0));
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    }
    // Lookahead mismatch: if next item is large and post-residual is a tiny non-fit, extra penalty.
    if next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // Prefer bins tighter than the mean residual (better consolidation).
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum possible next item is wasted forever.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // 2-step lookahead: perfect match if next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // chain placement: ideal two-step packing
        } else if next_item_size <= post_residual {
            // next item fits here afterward: partial reward, closer match is better
            let gap = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item cannot use this residual: penalize proportionally to waste
            let waste = (next_item_size - post_residual) as f64;
            score += 4.0 + 0.15 * waste.min(50.0);
        }
    }

    // Penalize residuals too small for ANY item (unusable dead space).
    if post_residual < 1 {
        score -= 5.0; // perfect fill, excellent
    } else if post_residual < 10 {
        // residual below the smallest item size: nearly dead space
        score += 8.0 - post_residual as f64;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (mean_residual - post_residual as f64);

    // Early in the stream, prefer keeping residuals large/flexible; later,
    // prefer aggressive consolidation (fill bins as tightly as possible).
    score -= (1.0 - progress) * 3.0 * (post_residual as f64 / bin_capacity as f64);
    score += progress * 0.05 * post_residual as f64;

    // Mildly discourage opening new bins when many bins are already open
    // (consolidation pressure), scaled by stream progress.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is ideal.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space: post_residual too small for any future item (min size 1,
    // but typical items are larger). Penalize residuals that can't hold next_item_size.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // This bin remains useful for the lookahead item: reward.
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Dead space relative to lookahead item: penalize proportionally.
            score += 6.0 * (post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // With multiple fitting bins, prefer the one that wastes least;
        // mild penalty to keep differentiation via residual terms.
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Compare bin residual to mean residual: prefer filling below-average-residual
    // bins (consolidating waste), keep high-residual bins flexible.
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early in the stream, keep bins flexible (penalize very low
    // post_residual slightly to avoid many near-full bins early); late in the
    // stream, be aggressive about filling bins completely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let late_bonus = progress * progress * 15.0;
    score -= late_bonus * tightness;

    // New-bin candidate handling: an empty bin has post_residual == capacity - item_size.
    // Favor opening a new bin only when no open bin fits well (high post_residual
    // everywhere) or item is large.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 18.0;
        // If item is large relative to capacity, new bin is more attractive.
        score -= 0.1 * item_size as f64;
        // If many open bins exist and none fit tightly, opening a new bin is fine.
        if open_bins_count > 3 && post_residual < 30 {
            score -= 10.0;
        }
        // Late in stream, prefer closing out open bins rather than opening new ones.
        score += 10.0 * progress;
    }

    // Small coupling: penalize leaving residual in the awkward 1..=10 band
    // (hard to fill with typical items).
    if post_residual >= 1 && post_residual <= 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - 0.5 * norm_pr * (1.0 - progress);
    score += 8.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 10.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space relative to mean residual across open bins
    score += 0.3 * (pr as f64 - mean_residual).abs() * (1.0 + progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 + progress);
    }

    // Lookahead: reward bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        score += 4.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // New-bin candidate: keep it neutral-to-slightly-worse unless post_residual is large
    if bin_residual == bin_capacity {
        score += 3.0 + 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" the leftover space is.
    // Residuals that are multiples of small capacity fractions (e.g. 10, 20, 25, 50)
    // are more likely to be exactly filled by future items.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Dead-space penalty: tiny leftovers (< 10) are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Reward residuals that align with common item-size harmony classes (mod 10).
    let rem10 = post_residual % 10;
    if rem10 == 0 {
        score -= 8.0; // perfectly harmonious leftover
    } else {
        score += rem10 as f64 * 0.6; // penalize off-harmonic leftovers
    }

    // Integer-division thresholds: classify post_residual into usable bands.
    let quarter = bin_capacity / 4;
    let half = bin_capacity / 2;
    if post_residual >= half {
        score -= 10.0; // half-full-ish leftover: very reusable
    } else if post_residual >= quarter {
        score -= 4.0;
    } else if post_residual > 0 {
        score += 6.0; // thin sliver
    }

    // Lookahead coupling: if the next item fits EXACTLY into the post residual,
    // this is a perfect pairing — reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            let new_post = post_residual - next_item_size;
            // harmonic check on the doubly-post residual
            if new_post % 10 == 0 {
                score -= 6.0;
            }
            score += new_post as f64 * 0.15;
        } else {
            // next item cannot use this bin's leftover; leftover likely wasted
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when the item
    // is large and no open bin offers a good fit.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin, modulated by stream progress
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 40.0 + 20.0 * progress;
        // but if item is huge relative to capacity, new bin is natural
        score -= (item_size as f64 / cap) * 10.0;
    }

    // Mild preference for bins whose residual deviates from the mean
    // (place into atypical bins to keep a spread of usable residuals).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Small tie-breaker favoring earlier-opened (denser) bins via open count.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is unusable waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Small-but-usable residuals are fine; large residuals are mild waste
    // unless the next item can use them.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0; // lookahead compatibility
        } else if post_residual > 0 && (post_residual as f64) < (next_item_size as f64) * 0.6 {
            score += 12.0; // gap too small for the upcoming item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open.
    if bin_residual == bin_capacity {
        score += 30.0 + 5.0 * (open_bins_count as f64).sqrt();
    } else {
        score -= 2.0 * (open_bins_count as f64).min(10.0);
    }

    // Mild alignment with mean residual: prefer bins tighter than average.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Early stream: be slightly more willing to fill existing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 5.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact-ish fits (small post_residual) non-linearly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 15 {
        score -= 15.0;
    }

    // 2-step lookahead: reward when next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover2 = post_residual - next_item_size;
        score -= 25.0 + (leftover2 as f64).min(20.0) * 1.5;
    } else if next_item_size > 0 {
        // Penalize when next item cannot follow into this bin.
        score += 10.0;
    }

    // Dead-space penalty: residual too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last chance: strongly favor using this bin if it's the only fitting one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Prefer tighter bins relative to mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Early in stream: be slightly conservative, avoid scattering items.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress < 0.2 && bin_residual == bin_capacity {
        score += 15.0;
    }

    // Mild penalty for opening a new bin when many bins are open.
    if bin_residual == bin_capacity {
        score += 8.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual)
    score -= (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Penalize opening new bins when existing bins can fit
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, opening bins is cheaper; later, avoid it
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 * progress;
    }

    // Lookahead: penalize leaving a residual that can't hold the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            score += 6.0;
        }
        // Reward residuals that fit next item snugly
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= 10.0 * (1.0 - gap / bin_capacity as f64);
        }
    }

    // Prefer bins with residuals below the mean (consolidate waste)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Prefer filling bins when many bins are open
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Penalize dead space (residual too small for the smallest plausible item)
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: prefer small post residual, with non-linear polynomial shaping.
    let mut score = pr * (1.0 + 0.6 * progress) - 0.9 * (pr * pr) / capacity;

    // Reward tight fits (small relative post residual) more as stream progresses.
    let tightness = 1.0 - pr / capacity;
    score -= 12.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot plausibly hold future items.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr < ns {
            score += 8.0 * (ns - pr) / capacity * (1.0 + progress);
        } else {
            // bonus if this placement still accommodates the next item
            score -= 4.0 * (pr - ns) / capacity;
        }
    }

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 10.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across too many open bins relative to mean residual.
    score += 0.05 * (open_bins_count as f64).ln() * (pr - mean_residual).abs() / capacity;

    // New-bin candidate: neutral-ish baseline; slightly worse early, better late for tiny fits.
    if is_new_bin {
        score += 6.0 * (1.0 - progress) - 3.0 * progress * (1.0 - pr / capacity);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: extremely attractive.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead-space penalty grows for residuals
    // that are hard to fill (small, awkward values). Classify by modulo classes.
    let pr = post_residual;
    let cap_f = bin_capacity as f64;

    // Fraction of capacity remaining.
    let frac = pr as f64 / cap_f;

    // Small unusable residuals are dead space -> penalize mildly (they are low
    // score already since score = pr, so add a non-linear penalty instead for
    // mid-range awkward residuals).
    if pr > 0 && pr < 10 {
        score -= 50.0; // tiny residual is nearly a perfect fit, reward it
    }

    // Awkward mid residuals: 10..30 hard to fill by items >=10 unless lucky.
    if pr >= 10 && pr <= 30 {
        score += 15.0 * (1.0 - frac * 4.0); // penalize proportionally
    }

    // Harmonic classes: residuals that are multiples of common item sizes
    // (10,20,25,50) are more likely to be filled exactly later -> reward.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 25 == 0 && pr > 0 {
        score -= 6.0;
    }
    if pr % 20 == 0 && pr > 0 {
        score -= 4.0;
    }
    if pr == 50 {
        score -= 10.0; // half capacity is a very reusable class
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size == pr {
        score -= 200.0;
    } else if next_item_size > 0 && next_item_size <= pr {
        // reward proportionally to how well next item fills the remainder
        let fill = next_item_size as f64 / pr as f64;
        score -= 20.0 * fill;
    } else if next_item_size > 0 && next_item_size > pr {
        // next item cannot use this residual -> penalize leftover class
        score += 5.0 * (1.0 - frac);
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: it starts attractive only when open bins are
    // fragmented; otherwise discourage hoarding bins.
    if bin_residual == bin_capacity {
        // base score = capacity (100) which is high; adjust by state
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count == 0 {
            score -= 500.0; // must open a bin
        } else {
            // penalize new bin more when mean residual is still large
            score += mean_residual * 0.5;
            // early in the stream, prefer consolidating into open bins
            score += (1.0 - progress) * 20.0;
            // if no open bin fits, opening is necessary
            if fitting_bins_count == 0 {
                score -= 400.0;
            }
        }
    } else if fitting_bins_count == 0 {
        // shouldn't happen for non-new bins, but guard
        score += 0.0;
    }

    // Mild preference for tighter bins among comparable residuals.
    score += (bin_residual as f64 - post_residual as f64) * -0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Hard dead-space penalty: small unusable gaps are the enemy.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward leaving room for the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // gap wasted relative to lookahead
        }
    }

    // Last-chance bin before opening a new one: strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into
    // existing bins rather than spreading; discourage new-bin opening.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 * (0.5 + 0.5 * progress);
    score += pressure * 0.3;

    // New-bin candidate: penalize mildly, but allow it when open bins
    // would create severe dead space (tight fits elsewhere are bad).
    if bin_residual == bin_capacity {
        score += 10.0 + pressure * 0.2;
        // If current item is large, a fresh bin is actually attractive.
        if item_size > 50 {
            score -= 12.0;
        }
    }

    // Prefer bins tighter than the average residual (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 20.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 25.0 / (1.0 + diff);
        // Perfect chain: item + next item fills bin completely.
        if post_residual == next_item_size {
            score -= 40.0;
        }
        // Penalize leaving residual that next item cannot use (dead space).
        if next_item_size > post_residual && post_residual > 0 {
            score += 15.0;
        }
    } else {
        // Last item: pure tightness.
        score -= 10.0 / (1.0 + post_residual as f64);
    }

    // Compare against mean residual: bins tighter than average are attractive.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin before opening a new bin: strong incentive to use it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening new bins when many open bins can still fit the item.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64 * 2.0);
        // But new bin is acceptable if current bin would leave large dead space
        // relative to the next item's needs.
        if next_item_size > post_residual {
            score -= 20.0;
        }
    }

    // Mild stream-progression pressure: as stream advances, prefer consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: squared post-residual penalizes dead space super-linearly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64 * 2.0);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoids bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: penalize if the next item cannot fit in the post-residual
    // (creates stranded space), reward if it can.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // Extra reward if next item nearly fills leftover space.
            let gap = post_residual - next_item_size;
            if gap <= 5 {
                score -= 10.0;
            }
        } else {
            score += 6.0;
        }
    }

    // Prefer bins whose residual is below the mean residual (fill the emptier-trending
    // bins less; prefer tighter bins when mean is low).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Time horizon: early in the stream, be conservative (slight penalty for using
    // many bins is fine); late in the stream, close out bins aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    // New-bin candidate: baseline cost of opening a fresh bin; make it competitive
    // only when it would genuinely help (large item, few fitting bins).
    if bin_residual == bin_capacity {
        let base = 12.0;
        let scarcity = if fitting_bins_count == 0 { -20.0 } else { 0.0 };
        let large_item_bonus = if item_size > bin_capacity / 2 { -6.0 } else { 0.0 };
        score += base + scarcity + large_item_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping.
    let mut score = pr_norm * (1.0 + 2.0 * pr_norm * pr_norm);

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly.
    let progress_weight = 0.5 + 3.0 * progress * progress;
    score += pr_norm * pr_norm * progress_weight;

    // Reward near-perfect fits with a smooth saturating term.
    let fit_quality = 1.0 - pr_norm;
    score -= 2.5 * fit_quality * fit_quality * fit_quality;

    // Lookahead: penalize if the next item cannot use the remaining space.
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns > pr {
            // Dead space for the lookahead item; penalize smoothly.
            let gap = (ns - pr) / cap;
            score += 1.5 * gap * (1.0 + progress);
        } else {
            // Next item fits: reward, more strongly if it nearly fills the bin.
            let after_next = (pr - ns) / cap;
            score -= 1.2 * (1.0 - after_next) * (1.0 - after_next);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 3.0;
    }

    // Mild penalty when this bin is far below mean residual (unbalanced use),
    // scaled by how many bins are open.
    let mean_gap = (mean_residual - pr) / cap;
    if mean_gap > 0.0 {
        score += 0.4 * mean_gap * mean_gap * (open_bins_count as f64).sqrt();
    }

    // Encourage closing bins exactly: zero post_residual is ideal.
    if post_residual == 0 {
        score -= 5.0;
    }

    // New-bin candidate: keep it neutral-ish but slightly discouraged unless
    // current bins would leave large unusable gaps; smooth interaction.
    if bin_residual == bin_capacity {
        score += 1.0 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual modulo capacity fractions
    let cap = bin_capacity;
    let class = post_residual % (cap / 4);
    score += class as f64 * 0.5;

    // Penalize small dead space that is hard to reuse (below min item size 10)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward residuals in reusable harmonic bands (multiples of 10, 20, 25, 50)
    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if post_residual % 25 == 0 {
        score -= 6.0;
    }
    if post_residual % 50 == 0 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 300.0;
        } else if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 20.0;
            if slack % 10 == 0 {
                score -= 10.0;
            }
            if slack < 10 {
                score += 30.0; // would create unusable sliver after next item
            }
        } else {
            // next item cannot use this bin's remainder; penalize proportionally
            score += (next_item_size as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin wastes existing residual
    if bin_residual == bin_capacity {
        // base cost of a fresh bin; attractive only if no good fit exists
        score += 25.0;
        if mean_residual < 15.0 {
            score -= 30.0; // existing bins nearly full -> prefer new bin
        }
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    } else {
        // Prefer bins tighter than average (best-fit flavor)
        if (bin_residual as f64) < mean_residual {
            score -= 10.0;
        }
    }

    // Mild phase-based scaling: early stream, be frugal with bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += (1.0 - progress) * 20.0;
    }

    // Prefer reusing bins over spreading across many open bins
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strong preference for small post_residual.
    score -= 40.0 / (1.0 + post_residual as f64);

    // Dead-space penalty: gaps too small for typical items (<= 10) are wasted.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 15.0; // risky gap: only smallest future items can use it
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many bins open, discourage opening new ones;
    // the new-bin candidate (residual == capacity) gets penalized implicitly.
    if bin_residual == bin_capacity {
        score += 25.0 + 8.0 * open_bins_count as f64;
    }

    // Lookahead: if next item fits in the resulting gap, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 20.0;
        } else if post_residual > 0 {
            score += 10.0;
        }
    }

    // Mean-residual coupling: prefer bins whose residual deviates from mean
    // (consolidate large residuals together, keep tight bins tight).
    score += 0.05 * (bin_residual as f64 - mean_residual).abs();

    // Late in stream: be more conservative, avoid creating unusable gaps.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Near match: next item fits with small leftover
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    }

    // Penalize creating dead space that next item cannot use
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += (post_residual as f64) * 0.4;
    }

    // Last-chance bonus: only one bin can fit the item
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 30.0 + 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual near zero is good.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * 20.0;

    // Penalize small dead space (< ~10) that nothing can use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward heavily.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // next item cannot follow here; penalize proportionally
            score += 8.0;
        } else {
            let slack = (post_residual - next_item_size) as f64;
            score += slack * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + step_index as f64);
    score -= pressure * 3.0;

    // Time horizon: early in stream, be more willing to open new bins (explore);
    // later, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, unattractive late.
        let new_bin_bonus = 40.0 * (1.0 - progress) - 25.0 * progress;
        score += new_bin_bonus;
        // Don't open a new bin if a decent fit exists elsewhere.
        if fit_ratio > 0.5 && progress > 0.1 {
            score += 10.0;
        }
    } else {
        // Existing bin gets a mild preference that grows over time.
        score -= 5.0 + 15.0 * progress;
    }

    // Global residual balance: prefer bins below mean residual (fill emptier bins)
    // when mean is high, otherwise prefer near-mean bins.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, but penalize very small dead space less as stream progresses
    let mut score = pr as f64;

    // Non-linear coupling: polynomial shaping of post-residual with progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * (1.0 + 2.0 * progress);
    score += 20.0 * poly;

    // Reward near-perfect fits more strongly later in the stream
    let tightness = 1.0 - (pr / cap).powf(2.0);
    score -= 15.0 * tightness * (0.5 + progress);

    // Penalize leaving residual that cannot fit the lookahead item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - pr / cap);
        } else {
            score += 10.0 * (1.0 - pr / nxt.min(cap));
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate: smooth dynamic penalty depending on mean residual and progress
    if bin_residual == bin_capacity {
        let dispersion = (mean_residual - pr).abs() / cap;
        score += 30.0 - 20.0 * progress - 10.0 * dispersion;
        if next_item_size > 0 && next_item_size as f64 > pr {
            score -= 5.0;
        }
    }

    // Mild pressure to consolidate among many open bins
    score += (open_bins_count as f64).ln() * (1.0 - progress) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "large" residue classes (>= 50) remain useful; small leftovers are dead space.
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;

    // Reward keeping large residuals, penalize small dead space super-linearly.
    if post_residual >= half {
        score -= 12.0 * (post_residual as f64 / bin_capacity as f64);
    } else if post_residual < quarter {
        // Dead-space penalty, worse the smaller the leftover.
        score += (quarter - post_residual) as f64 * 0.9;
        // Perfect fill is excellent though.
        if post_residual == 0 {
            score -= 60.0;
        }
    }

    // Modulo classes: residuals divisible by common small item sizes stay usable.
    if post_residual > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 50] {
            if post_residual % m == 0 {
                harmony += 3.0;
            }
        }
        score -= harmony;
    } else {
        score -= 8.0; // exact fit closes the bin cleanly
    }

    // Lookahead: if the next item fits exactly in the post-residual, strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if (post_residual - next_item_size) < quarter {
            score += 4.0; // leaves tiny dead space after next item
        } else {
            score -= 6.0;
        }
    }
    // If next item cannot fit here, mild penalty for blocking the stream.
    if next_item_size > bin_residual {
        score += 2.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score -= (open_bins_count as f64) * 0.15;

    // New-bin candidate (empty bin): only attractive when it beats a poor fit.
    if bin_residual == bin_capacity {
        // Baseline: slightly worse than a good existing fit.
        score = 55.0
            - 10.0 * (step_index as f64 / total_items.max(1) as f64)
            - if item_size > 3 * quarter { 10.0 } else { 0.0 };
        // If the only fitting bin is this new one, opening is fine.
        if fitting_bins_count == 1 {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out existing bins.
        if (step_index as f64) / (total_items.max(1) as f64) > 0.8 {
            score += 8.0;
        }
    }

    // Slight nudge toward tightest fits overall.
    score += (bin_residual - item_size).min(bin_capacity) as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftover gaps (< 10) are near-useless.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // Gaps too small for even the next item are partially dead.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }
    // Reward tight fits (exact fill is perfect).
    if post_residual == 0 {
        score -= 15.0;
    } else {
        let fit_ratio = item_size as f64 / bin_residual as f64;
        score -= 12.0 * fit_ratio;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidating into existing bins;
    // a new empty bin gets a penalty that grows with open_bins_count.
    if bin_residual == bin_capacity {
        score += 6.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 1.0 * open_bins_count as f64 / (1.0 + step_index as f64);
    }

    // Prefer bins tighter than the average residual (good consolidation).
    score += 0.3 * (bin_residual as f64 - mean_residual);

    // Lookahead: if the next item fits exactly in the post residual, reward it.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits, penalize large post residuals quadratically.
    score += 0.15 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0; // chain fit: excellent
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // reward proportional to how well next item fills the leftover
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot fit here: penalize leaving a residual that is
            // "almost but not quite" usable (dead space trap)
            let gap = (next_item_size - post_residual) as f64;
            if gap < 30.0 {
                score += 10.0 + 0.5 * gap;
            }
        }
    }

    // Compare residual against mean residual: prefer bins with below-average
    // residual (already well-filled bins), penalize scattering into loose bins.
    let dev = post_residual as f64 - mean_residual;
    score += 0.2 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current item is large and would
    // leave a very tight residual, or when no open bin fits well.
    if bin_residual == bin_capacity {
        // neutral base for new bin; slight penalty so open bins win ties,
        // waived when the item is large relative to capacity.
        let large = (item_size as f64 / bin_capacity as f64) > 0.6;
        if large {
            score -= 15.0;
        } else {
            score += 5.0;
        }
        // late in the stream, prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        if !large {
            score += 10.0 * progress;
        }
    }

    // Mild preference for fewer open bins overall (packing density pressure).
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post-residual is good, but zero-waste fits are excellent).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual <= 15 {
        score -= 8.0;
    }

    // Penalize large dead space quadratically, but less so if item nearly fills bin.
    let waste = post_residual as f64;
    score += 0.05 * waste * waste / (1.0 + (bin_residual as f64) / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + 0.15 * (next_item_size as f64);
    }
    // Penalize leaving a residual that is uselessly small for the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(20) {
        score += 10.0;
    }

    // New-bin candidate handling: opening a new bin is attractive early or when
    // open bins are fragmented, but costly when bins are plentiful and tight.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 { (mean_residual / bin_capacity as f64).abs() } else { 0.0 };
        // Penalize new bin generally; discount when mean residual is high (existing bins too empty)
        score += 35.0 - 20.0 * fragmentation - 15.0 * (1.0 - progress);
        // If no other bin fits well (last chance failed), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    } else {
        // Mildly prefer using emptier existing bins when many are open (balance load).
        score += 0.02 * (bin_residual as f64 - mean_residual).max(-50.0).min(50.0);
    }

    // Time horizon: late in the stream, consolidate aggressively (avoid new bins).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (1.0 - (post_residual as f64) / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = pr_norm * pr_norm * (progress - 0.5) + pr_norm * progress * (1.0 - progress);
    score += 8.0 * poly;
    // Penalize dead space late in stream
    score += (pr_norm * pr_norm) * 6.0 * (1.0 - progress);
    // Reward tight fits strongly (smooth quadratic reward)
    score -= 10.0 * (1.0 - pr_norm) * (1.0 - pr_norm);
    // Last-chance bonus: smooth sigmoid-like coupling with progress
    let last_chance = if fitting_bins_count == 1 { 1.0 } else { 0.0 };
    score -= 7.0 * last_chance * (0.5 + 0.5 * progress);
    // Lookahead: reward leaving room for the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt) / cap;
        let kernel = (-diff * diff * 25.0).exp();
        score -= 5.0 * kernel;
    }
    // Mild penalty when bin residual deviates from mean residual (smooth coupling)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;
    // New-bin candidate: penalize opening a new bin unless residuals are tight
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
        if pr_norm >= 0.0 {
            // empty bin post_residual == capacity; smooth discount if item is large
            let it = item_size as f64 / cap;
            score -= 10.0 * it * it;
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues modulo small divisors.
    // Post-residuals that are multiples of 10 are "clean" slots (likely reusable
    // by typical item sizes); reward them.
    let clean = post_residual % 10 == 0;
    if clean {
        score -= 6.0;
    } else {
        // Penalize awkward dead space: small odd leftovers are hard to fill.
        if post_residual < 10 {
            score += 8.0 * (10 - post_residual) as f64;
        }
        // Mid-range non-aligned leftovers are mildly penalized.
        score += (post_residual % 5) as f64 * 0.75;
    }

    // Exact fit is always excellent.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic class via integer division thresholds on post_residual.
    let class = post_residual / 25; // 0..=4 quartile-ish class
    score += class as f64 * 1.5; // prefer bins left in lower (tighter) classes

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this bin (chained harmonic pairing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            // Next item fits but imperfectly: reward proportional to closeness.
            let gap = post_residual - next_item_size;
            if gap <= 10 {
                score -= 8.0 - gap as f64 * 0.5;
            } else {
                score += gap as f64 * 0.15;
            }
        } else {
            // Next item cannot use this leftover: penalize large unusable space.
            score += (next_item_size - post_residual).min(30) as f64 * 0.2;
        }
    } else {
        // Last item: just minimize leftover.
        score += 2.0;
    }

    // Last-chance bin: if this is the only fitting bin, opening a new bin is
    // costly, so strongly favor using it (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0 + item_size as f64 * 0.05;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    // or no bins fit well. Base penalty decays as the stream progresses.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = post_residual > 40 || (fitting_bins_count == 0);
        if poor_fit {
            score -= 5.0 + progress * 5.0;
        } else {
            score += 18.0 - progress * 6.0;
        }
    }

    // Mean residual context: when open bins are on average roomy, prefer
    // consolidating into tighter-than-average bins.
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    // Slight preference to keep the number of open bins from exploding.
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    // Medium dead space (10..20) is also wasteful for small items.
    if post_residual >= 10 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 4.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; a new empty bin gets a mild penalty scaled by load.
    if bin_residual == bin_capacity {
        score += 15.0 + open_bins_count as f64 * 2.0;
    } else {
        score -= open_bins_count as f64 * 0.5;
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += tightness * 20.0;

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    }
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size {
        // dead space for the known next item: penalize proportionally
        score += (next_item_size - post_residual) as f64 * 0.8;
    }

    // Early in the stream, be more tolerant of opening bins; late, consolidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += progress * 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            score -= 50.0 - (post_residual as f64 - next_item_size as f64) * 0.5;
        } else {
            // Dead space relative to the next item: penalize more when gap is small
            // (wasted potential) but capped so huge gaps aren't over-penalized.
            let gap = (next_item_size - post_residual) as f64;
            score += gap.min(40.0) * 1.5;
        }
    }

    // Compare post_residual against mean residual: leaving a residual far below
    // the mean means we consumed a "valuable" large residual — slight penalty.
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin early in the stream when other bins could fit.
    if bin_residual == bin_capacity {
        score += 120.0;
        // But if no open bin fits well, new-bin becomes attractive: reduce penalty
        // when the item is large relative to capacity.
        score -= (item_size as f64 / bin_capacity as f64) * 100.0;
    }

    // Slight preference for tighter bins overall (small residual before placement).
    score += (bin_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core fit quality: squared waste penalizes leaving awkward dead space.
    score += 0.35 * (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead coupling: reward bins whose post-residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Perfect chain: next item fits exactly or nearly — strong reward.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize more when post_residual is tiny
            // (unusable sliver) and more later in the stream.
            let sliver = post_residual as f64 / bin_capacity as f64;
            score += (6.0 + 10.0 * progress) * (1.0 - sliver);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // Crowding pressure: with many open bins, prefer consolidating into fuller bins
    // (small residual relative to the mean) to close them out.
    if open_bins_count > 1 {
        let fullness_gap = mean_residual - bin_residual as f64;
        score += 0.08 * fullness_gap * (open_bins_count as f64).ln();
    }

    // Exact-fit celebration.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 10 {
        // Near-perfect fit leaves a small but potentially reusable sliver.
        score -= 8.0;
    }

    // New-bin candidate handling: an empty bin gets a neutral-ish score so it wins
    // only when every open bin would produce a bad fit (high post_residual or
    // unusable sliver for the lookahead).
    if bin_residual == bin_capacity {
        // Baseline comparable to a mediocre fit; slightly cheaper late in the
        // stream to allow fresh bins rather than fragmenting old ones.
        score = 0.5 * bin_capacity as f64 - 4.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 2.0; // a new bin always chains with the next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress);
    // reward tight fits quadratically
    score -= (1.0 - norm_pr).powi(2) * 0.5;
    // penalize dead space that cannot fit next item
    if next_item_size > 0 && pr < next_item_size as f64 {
        score += (next_item_size as f64 - pr) / cap * (0.5 + 0.5 * progress);
    }
    // last chance bonus
    if fitting_bins_count == 1 {
        score -= 0.4 * (1.0 - norm_pr);
    }
    // residual dispersion coupling
    score += 0.2 * (norm_pr - mean_residual / cap).abs();
    // mild new-bin penalty late in stream
    if bin_residual == bin_capacity {
        score += 0.3 + 0.4 * (1.0 - progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into "useful"
    // residue classes (multiples of common item sizes) should be favored.
    let pr = post_residual;
    let mut harmonic_bonus = 0.0;
    for m in [10u32, 20, 25, 50].iter() {
        if pr > 0 && pr % m == 0 {
            harmonic_bonus += 15.0;
        }
    }
    // Perfect fit is ideal
    if pr == 0 {
        harmonic_bonus += 200.0;
    }
    // Dead space: residuals that no plausible item (1..=100) can use well
    if pr > 0 && pr < 10 {
        harmonic_bonus -= 30.0; // tiny unusable sliver
    }
    score -= harmonic_bonus;

    // Fraction-of-capacity coupling: prefer bins where item fills a clean
    // fraction of the residual (1/2, 1/3, 1/4)
    if bin_residual > 0 {
        let r = bin_residual;
        if item_size * 2 == r { score -= 60.0; }
        if item_size * 3 == r { score -= 40.0; }
        if item_size * 4 == r { score -= 25.0; }
    }

    // Integer-division threshold on post_residual relative to next item:
    // if the lookahead item fits the post-residual exactly, strong reward.
    if next_item_size > 0 && pr >= next_item_size {
        if pr == next_item_size {
            score -= 120.0;
        } else if pr - next_item_size < 10 {
            score -= 50.0; // leaves only a tiny sliver, but still used
        } else {
            score -= 20.0;
        }
    } else if next_item_size > 0 && pr < next_item_size && pr > 0 {
        // post-residual cannot host the next item: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.5;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no open bin is a decent fit
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so open bins with reasonable fit win
        score += 40.0;
        // If many bins can fit, discourage new bin further
        score += fitting_bins_count as f64 * 10.0;
        // Large item with few fitting bins: new bin may be wise
        if item_size > bin_capacity / 2 && fitting_bins_count <= 2 {
            score -= 70.0;
        }
        // Early in stream, prefer consolidating into open bins less strictly
        let progress = step_index as f64 / total_items.max(1) as f64;
        if progress < 0.2 {
            score += 20.0;
        }
    }

    // Mild preference for fuller bins (lower mean residual overall)
    score += (mean_residual - post_residual as f64) * 0.1;

    // Slight pressure to keep open bin count low
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps (< 10, or below smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: prefer filling existing bins when many are open.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: strongly prefer using the only fitting bin before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits the post-residual exactly, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        if post_residual == next_item_size {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0;
    }

    // New-bin candidate: make it moderately attractive only when current fit is poor
    // and mean residual is high (existing bins are fragmented).
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        score = score * 0.5 + 30.0 * (1.0 - poor_fit);
        if mean_residual < 15.0 {
            score += 20.0; // existing bins tight, opening new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong 2-step lookahead: reward exact/near-exact chain with next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 60.0 - 0.5 * chain_waste; // perfect chain gets biggest reward
        } else {
            // next item cannot chain here; penalize proportionally to leftover dead space
            score += 0.3 * post_residual as f64;
        }
    }

    // Tight fit reward: small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize bins that are already much fuller than average (save roomy bins? no —
    // prefer filling fuller bins to consolidate), so reward high bin fill level
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are poor fits
    if bin_residual == bin_capacity {
        score += 40.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 15.0; // reserving empty bin for big upcoming item can help
        }
        if mean_residual < item_size as f64 {
            score -= 10.0; // no room anywhere anyway
        }
    }

    // Mild stream-progression pressure: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (mean_residual - post_residual as f64).max(0.0) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits strongly (small post_residual relative to capacity).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio;

    // Exact or near-exact fills are excellent.
    if post_residual == 0 { score -= 30.0; }
    else if post_residual < 10 { score -= 12.0; }

    // Penalize dead space that no future item (min size 1..10) can use.
    if post_residual > 0 && post_residual < 10 { score += 6.0; }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item won't fit here; penalize leaving a large unusable gap.
            score += 3.0 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: minimize leftover aggressively.
        score -= 10.0 * (1.0 - fit_ratio);
    }

    // Prefer fuller bins relative to the mean residual across open bins.
    if bin_residual as f64 > mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    // Late in the stream, consolidate into existing bins; early on, allow
    // opening new bins for large items to keep flexibility.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        if item_size >= bin_capacity / 2 {
            score -= 4.0 * (1.0 - progress);
        } else {
            score += 5.0 + 10.0 * progress;
        }
        // Opening new bins is costly when many bins are already open.
        score += open_bins_count as f64 * 0.5;
    }

    // Mild penalty for spreading across too many open bins early.
    score += (open_bins_count as f64 / (1.0 + fit_ratio)) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Base: quadratic coupling of post residual with stream progress.
    // Late in the stream, tight fits (small post_residual) matter more.
    let mut score = x * x * (0.5 + 1.5 * progress) + x * (1.0 - progress);

    // Smooth non-linear penalty for dead space relative to mean residual of open bins.
    let dead = ((pr - mean_residual) / cap).tanh();
    score += 0.8 * dead * dead;

    // Reward last-chance bins smoothly (avoid opening new bins unnecessarily).
    if fitting_bins_count == 1 {
        score -= 2.0 * (1.0 - progress) * (1.0 - progress) + 1.0;
    }

    // Lookahead coupling: prefer bins whose post residual still fits the next item,
    // penalize otherwise with a smooth saturating term.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = ((pr - nxt) / cap).tanh();
            score -= 1.5 * (1.0 - slack * slack);
        } else {
            let gap = ((nxt - pr) / cap).tanh();
            score += 1.2 * gap * gap;
        }
    }

    // Mild pressure against accumulating many open bins late in the stream.
    score += 0.01 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: residual mod small integers predicts future packing.
    let r = post_residual;
    // Reward residuals in friendly classes (multiples of 10, 20, 25, 50).
    if r % 10 == 0 { score -= 6.0; }
    if r % 20 == 0 { score -= 3.0; }
    if r % 25 == 0 { score -= 3.0; }
    if r % 50 == 0 { score -= 4.0; }

    // Penalize small dead space that nothing (1..100) can use well.
    if r > 0 && r < 10 { score += 25.0; }
    if r >= 10 && r < 20 { score += 8.0; }

    // Integer-division thresholds: residual bucket relative to item size.
    let q = r / item_size.max(1);
    score += (q as f64) * 1.5;

    // Lookahead coupling: next item fits perfectly => strong reward.
    if next_item_size > 0 {
        if next_item_size <= r {
            let nres = r - next_item_size;
            if nres % 10 == 0 { score -= 10.0; }
            if next_item_size == r { score -= 15.0; }
            score -= (next_item_size as f64) * 0.15;
        } else {
            // next item cannot use this residual: penalize large leftovers less if next is big
            score += 4.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: prefer opening fresh bins only early in stream
    // or when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 8.0 * (1.0 - progress);
        if fitting_bins_count > 0 && r % 10 == 0 {
            // keep new-bin as fallback: add penalty so existing good fits win
            score += 10.0;
        }
    }

    // Encourage consolidation when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * 2.0;

    // Nudge toward bins near the mean residual (balanced packing).
    score += ((post_residual as f64 - mean_residual).abs()) * 0.05;

    // Capacity-fraction scaling.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += frac * frac * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harder.
    // A gap is "dead" if no plausible future item (>= 1, but realistically
    // small items are rare) can use it. Penalize gaps below a threshold
    // superlinearly.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tight fit reward: item occupies most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 15.0;

    // Lookahead: if the next item fits exactly into post_residual, strongly favor.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; mild penalty for leaving a gap
        // that is "almost" but not quite usable.
        if post_residual > 0 && next_item_size > post_residual && post_residual < next_item_size {
            score += 4.0;
        }
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: discourage proliferating bins; but the new-bin
    // candidate (bin_residual == bin_capacity) gets a base offset so it is
    // only chosen when fits are genuinely poor.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * -0.5;
    } else {
        score -= open_bins_count as f64 * 0.3;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins),
    // penalize dumping into already-loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Slight late-stream tightening: as stream progresses, prefer tighter fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.15 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead matches (post_residual == next_item_size)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if post_residual as u32 == next_item_size {
            score -= 40.0; // perfect 2-step match
        } else if post_residual > next_item_size {
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit here; penalize dead space more strongly
            score += 5.0 + diff / 10.0;
        }
    }

    // Compare post_residual relative to mean residual across open bins
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: prefer it only when no open bin gives a tight fit
    if bin_residual == bin_capacity {
        score += 25.0;
        if next_item_size > 0 && post_residual as u32 == next_item_size {
            score -= 20.0;
        }
    }

    // Late in stream: tighten packing, discourage opening new bins
    let progress = step_index as f64 / total_items as f64;
    score *= 1.0 - 0.2 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear bonus.
    if post_residual == 0 {
        score -= 60.0; // perfect fit: huge reward
    } else {
        let pr = post_residual as f64;
        score -= (bin_capacity as f64 - pr) / bin_capacity as f64 * 20.0;
        // Penalize dead space that is too small for the smallest plausible item.
        if pr < 10.0 {
            score += 35.0 * (10.0 - pr) as f64;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits into post_residual, reward; otherwise penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if (post_residual as f64) >= ni {
            score -= 12.0 + ni * 0.15;
        } else {
            score += 8.0;
            // Extra penalty if the leftover cannot host the next item but a new bin could.
            if post_residual < next_item_size && bin_residual >= item_size + next_item_size {
                score += 6.0;
            }
        }
    }

    // Global state coupling: prefer filling bins when many bins are open.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let open_f = open_bins_count as f64;
    score -= open_f * 0.6 * (0.5 + progress);

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good filler.
    let residual_f = bin_residual as f64;
    if mean_residual > 0.0 {
        let diff = mean_residual - residual_f;
        score -= diff * 0.25;
    }

    // New-bin candidate handling: make empty bin mildly attractive only when
    // no good fit exists (large post_residual waste elsewhere, or no last-chance).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, decaying as stream progresses.
        let mut new_bin_cost = 30.0 - 10.0 * progress;
        // Cheaper to open a new bin when many bins already open (amortization).
        new_bin_cost -= (open_f.min(20.0)) * 0.5;
        // If the next item is large, a fresh bin is more valuable.
        if next_item_size >= 50 {
            new_bin_cost -= 8.0;
        }
        // If item is large relative to capacity, fresh bin handles it cleanly.
        if item_size >= 60 {
            new_bin_cost -= 6.0;
        }
        score = new_bin_cost + post_residual as f64 * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer tight fits (quadratic penalty on post_residual).
    let mut score = post * post / cap;

    // Smooth coupling: tight fits matter more as the stream progresses.
    score += post * (0.5 + 1.5 * progress);

    // Penalize bins whose residual deviates from the mean (keep residuals uniform).
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * dev * 30.0;

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 {
        score -= cap * 2.0;
    }

    // Lookahead: reward leaving post_residual that can host the next item.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post - next_item_size as f64;
        score -= 10.0 * (1.0 - slack / cap);
    } else if next_item_size > 0 {
        // Dead space relative to the next item: penalize smoothly.
        score += (next_item_size as f64 - post) * 0.6;
    }

    // New-bin candidate: mildly discourage opening a new bin when good fits exist,
    // but encourage it late in the stream or when many bins are open with waste.
    if bin_residual == bin_capacity {
        score = cap * (1.2 - 0.8 * progress) + (open_bins_count as f64) * 0.5;
        if fitting_bins_count <= 1 {
            score -= cap; // no alternative anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // remaining fraction

    // Perfect fit / near fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // Harmonic class logic: classify post_residual into residue classes mod 10
    let class = (post_residual % 10) as f64;
    // Dead-space classes: residuals like 1..9 (mod 10) are hard to fill with items >= 10
    if post_residual > 0 && post_residual < 10 {
        score += 500.0; // unusable sliver
    }

    // Reward residuals that are multiples of 10 (likely to be exactly filled)
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 60.0;
    }

    // Coupling with next item lookahead: can next item fit exactly?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0; // perfect chained fit
        } else if next_item_size < post_residual {
            let npr = post_residual - next_item_size;
            score -= (npr as f64) * 1.5;
            if npr % 10 == 0 { score -= 40.0; }
        } else {
            score += 120.0; // next item won't fit here
        }
    }

    // Last-chance bonus: only one bin fits the item
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // Prefer fuller bins (smaller residual fraction) nonlinearly
    score += frac * frac * 80.0;

    // Penalty for opening a new bin when good fits exist
    if bin_residual == bin_capacity {
        score += 150.0 + 0.5 * (open_bins_count as f64);
        if fitting_bins_count > 0 {
            // if some open bin leaves a harmonic residual, discourage new bin
            let best_possible = (bin_residual - item_size) as f64;
            if best_possible >= 0.0 && (best_possible as u32) % 10 == 0 {
                score += 100.0;
            }
        }
    }

    // Mean residual coupling: discourage spreading waste when mean residual already large
    score += 0.3 * (mean_residual - frac * cap).abs();

    // Progression: slightly more conservative early
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 20.0;

    // Integer-division threshold on post_residual / item_size
    if item_size > 0 && (post_residual / item_size) >= 2 {
        score -= 25.0; // room for multiple more items
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to fit the smallest
    // plausible future item (<= 12) are wasted capacity. Penalize hard.
    if post_residual > 0 && post_residual < 12 {
        score += 40.0 + (12 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits: small but still-usable residual is good.
    if post_residual > 0 {
        let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
        score -= tightness * 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            score -= 6.0;
        } else {
            // next item won't fit here; slight penalty for stranded residual
            score += (post_residual as f64) * 0.15;
        }
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonably tight alternative exists, but allow opening when this bin
    // would leave a bad dead space.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.0 + 0.5 * progress);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when it avoids dead space
    // (empty bin residual == capacity gives large post_residual naturally),
    // but add a fixed opening cost so it is not chosen over decent fits.
    if bin_residual == bin_capacity {
        score += 18.0;
        // Late in the stream, opening new bins is fine; early, prefer filling.
        score -= progress * 8.0;
    }

    // Mild alignment with mean residual: prefer bins below mean residual
    // (already tighter than average).
    score -= (mean_residual - post_residual as f64).max(0.0) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // 2-step lookahead: if the next item exactly matches post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // Next item fits here: reward proportionally to how well it fills the remainder.
            let next_fill = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * next_fill;
        } else {
            // Next item cannot fit: penalize leftover dead space.
            score += 12.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Compare against mean residual: bins with residual below mean are more "committed".
    if (bin_residual as f64) < mean_residual {
        score -= 6.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is large and few bins fit.
    if bin_residual == bin_capacity {
        score += 30.0;
        if item_size >= bin_capacity / 2 {
            score -= 20.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items as f64;
    score += 10.0 * progress * (open_bins_count as f64 / (1.0 + mean_residual / 10.0)).min(3.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 100.0;
    } else {
        // Penalize small dead space that nothing (min size 1) can use
        let t = step_index as f64 / total_items.max(1) as f64;
        score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 40.0;

        // Lookahead: reward if next item fits the post residual
        if next_item_size > 0 {
            if next_item_size <= post_residual {
                score -= 25.0 * (next_item_size as f64 / bin_capacity as f64);
            } else {
                // wasted lookahead space penalty scaled by how much next item overflows
                let over = (next_item_size - post_residual) as f64;
                score += 5.0 * (over / bin_capacity as f64).min(1.0);
            }
        }

        // Last chance: strongly favor using the only bin that fits
        if fitting_bins_count == 1 {
            score -= 60.0;
        }

        // Prefer tighter bins relative to current mean residual
        score += (bin_residual as f64 - mean_residual) * 0.3;

        // Late in stream: discourage opening new bins / spreading
        score += t * 10.0 * (post_residual as f64 / bin_capacity as f64);

        // Many open bins: favor consolidation into existing bins
        score -= (open_bins_count as f64).ln().max(0.0) * 2.0;
    }

    // New-bin candidate: only attractive if item is huge and no good fit exists
    if bin_residual == bin_capacity {
        if item_size >= 80 && (fitting_bins_count == 0 || post_residual >= item_size / 2) {
            score -= 30.0;
        } else {
            score += 45.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post residual, with non-linear (quadratic) coupling
    let mut score = pr * (1.0 + pr_norm * pr_norm);

    // Smooth interaction: as stream progresses, tighten preference for tight fits
    score += 12.0 * progress * pr_norm * (1.0 - progress);

    // Penalize residual that is too small to be useful (dead space) smoothly
    let dead = (1.0 - pr_norm).min(1.0);
    score += 8.0 * dead * dead * (1.0 - dead);

    // Lookahead coupling: reward if post_residual can host next item
    if next_item_size > 0 && post_residual >= next_item_size {
        let fit_quality = (post_residual - next_item_size) as f64 / cap;
        score -= 10.0 * (1.0 - fit_quality);
    } else if next_item_size > 0 {
        score += 6.0 * (next_item_size as f64 / cap);
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: mildly penalize early, allow late in stream
    if bin_residual == bin_capacity {
        score += 5.0 - 10.0 * progress;
        score += 0.5 * open_bins_count as f64;
    }

    // Coupling with mean residual: prefer bins deviating from mean smoothly
    score += 0.3 * (mean_residual - pr).abs().powf(1.5) / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post-residual: bins whose leftover falls into
    // "usable" classes (>= 10, i.e. can host the smallest item) are favored.
    let post_class = post_residual / 10;
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Dead space class: penalize proportionally to wasted capacity.
        score += (10 - post_residual) as f64 * 1.5;
    } else {
        // Favor bins whose leftover is a "harmonic" chunk (divisible nicely).
        let harm = post_residual % 10 == 0;
        if harm {
            score -= 5.0;
        }
        // Prefer leaving residual that likely fits the next item exactly.
        if next_item_size > 0 && post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 25.0;
            } else if slack < 10 {
                score -= 12.0;
            } else {
                score -= slack as f64 * 0.1;
            }
        } else if next_item_size > 0 {
            // Next item cannot fit here: leftover becomes dead weight.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
        // Integer-division threshold: reward residual classes in the
        // mid-range (20..=50) which remain re-combinable.
        if (20..=50).contains(&post_residual) {
            score -= 6.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item is huge
    // relative to mean residual (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let pressure = item_size as f64 / bin_capacity as f64;
        let mean_util = 1.0 - mean_residual / bin_capacity as f64;
        score += 40.0 - 30.0 * pressure - 15.0 * mean_util;
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild preference for fuller bins overall.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    } else {
        // Larger post_residual keeps the bin usable; mild reward.
        score -= 2.0;
    }

    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap_fit = (post_residual - next_item_size) as f64;
        if gap_fit < 10.0 {
            score -= 18.0;
        } else {
            score -= 6.0;
        }
    }
    // Lookahead conflict: next item would leave a dead gap if placed here later.
    if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open bins pressure: many open bins -> prefer consolidating into existing bins,
    // penalize the new-bin candidate implicitly via open_bins_count scaling.
    let bin_pressure = open_bins_count as f64 / (1.0 + total_items as f64);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportionally to open bins pressure,
        // but allow it when existing bins would create dead space.
        score += 10.0 + 25.0 * bin_pressure;
    } else {
        score -= 5.0 * bin_pressure;
    }

    // Mild preference toward fuller bins (tight packing as stream progresses).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 4.0 * fill_ratio;

    // Mean residual coupling: if this bin's residual is far below the mean,
    // it is one of the emptier bins; favor filling it to balance residuals.
    let diff = mean_residual - bin_residual as f64;
    if diff > 0.0 {
        score -= diff.min(20.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.85;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Amplify dead-space penalty as the stream matures (residuals matter more later).
    if post_residual > 0 {
        score *= 1.0 + 0.15 * progress;
    }

    // Lookahead chaining: reward bins whose leftover can host the next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            // Penalize leftovers that are too small for the next item (dead space risk).
            score += 0.1 * post_residual as f64 * (1.0 - post_residual as f64 / next_item_size as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin unless the fit is very tight.
    if bin_residual == bin_capacity {
        score += 18.0 + 0.25 * mean_residual;
        if post_residual <= 15 {
            score -= 10.0; // tight fit justifies a fresh bin
        }
    }

    // Mild coupling to global fragmentation state.
    score += 0.05 * (mean_residual - post_residual as f64).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: prefer tight fits (low post_residual), smoothly scaled
    let mut score = pr * (1.0 + 0.5 * progress);

    // Non-linear polynomial coupling of post_residual with progress
    let pn = pr / cap;
    score += 40.0 * pn * pn * (0.5 + progress) - 20.0 * pn * pn * pn;

    // Reward high fill ratio with a smooth saturating term
    score -= 25.0 * fit_ratio * fit_ratio * (1.0 - progress);

    // Dead-space penalty: residuals too small for typical items are wasted
    let dead_threshold = 20.0;
    if pr < dead_threshold {
        let d = (dead_threshold - pr) / dead_threshold;
        score += 30.0 * d * d;
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead coupling: if next item fits the post-residual, reward
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0 * (1.0 - pr / cap);
    } else if next_item_size > 0 && pr > 0.0 {
        // penalize blocking the next item badly
        let waste = ((next_item_size as f64 - pr) / cap).max(0.0);
        score += 10.0 * waste * waste;
    }

    // Prefer spreading across bins when many are open late in stream
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // Slight pull toward mean residual balance
    score += 0.1 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: quantize leftover space into capacity fractions.
    let cap_f = bin_capacity as f64;
    let frac = post_residual as f64 / cap_f; // 0..1
    let class = (frac * 4.0).floor() as i32; // 0: tiny, 1: small, 2: medium, 3: large

    match class {
        0 => score -= 12.0,           // near-perfect fit, strongly reward
        1 => score -= 4.0,            // decent fit
        2 => { score += 2.0; }        // mediocre leftover
        _ => { score += 6.0; }        // large waste, penalize
    }

    // Integer-division thresholds on post_residual: leftover usable by common small items?
    let usable = post_residual >= 10 && (post_residual % 10 == 0 || post_residual >= 25);
    if !usable && post_residual > 0 {
        score += 8.0; // dead-space penalty
    }

    // Lookahead coupling: does post_residual still fit next item (k=2 lookahead)?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0; // bin remains useful for the next arrival
            // exact harmonic match: leftover equals next item size
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else {
            score += 3.0; // bin becomes dead after this placement
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin gets neutral-ish score; prefer it only
    // when no open bin offers a good fit (i.e., when mean residual is small).
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap_f;
        score = cap_f * 0.5 - pressure * 30.0;
        // late in the stream, slightly discourage proliferating bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    }

    // Mild preference to fill already-open bins when many are open
    score += open_bins_count as f64 * 0.05;

    // Modulo harmonic bonus: post_residual divisible into capacity quarters
    if post_residual % (bin_capacity / 4) == 0 && post_residual > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 25.0;
    }
    if post_residual > 0 && post_residual < item_size.min(30) {
        // gap too small even for a small future item
        score += 15.0;
    }

    // Reward tight fits (exact or near-exact).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Prefer bins whose residual was already small-ish (consolidate large gaps).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= tightness * 10.0;

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = post_residual - next_item_size;
        if leftover == 0 {
            score -= 40.0;
        } else if leftover < 10 {
            score += 10.0; // creates a new dead gap
        } else {
            score -= 5.0;
        }
    }

    // New-bin candidate: keep it attractive unless an open bin fits well.
    if bin_residual == bin_capacity {
        score -= 10.0;
        // but if many bins are open with large mean residual, prefer reusing them
        score += mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual matches next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        let perfect = (post_residual as i64 == next_item_size as i64) as f64;
        score -= 30.0 * perfect;
        score += 0.4 * gap;
        // if next item also fits after this placement, strong bonus
        if post_residual >= next_item_size {
            score -= 12.0;
        }
        // dead space that neither this nor next item can use later is penalized
        if post_residual < 10 && post_residual > 0 {
            score += 25.0;
        }
    } else {
        // last item: prefer tightest fit
        score *= 2.0;
    }

    // Prefer tight fit relative to current residual
    let tightness = item_size as f64 / bin_residual as f64;
    score -= 8.0 * tightness;

    // Penalize deviating from mean residual (keep bin population balanced)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    // Last-chance bin: strong incentive to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize unusable dead space: if post_residual can't fit the smallest plausible item.
    if post_residual < 1 {
        score -= 100.0; // perfect fit, strongly favored
    } else if post_residual < item_size.min(10).max(1) {
        score += 10.0; // dead space penalty
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    } else if fitting_bins_count > 1 {
        score += 3.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.2 * next_item_size as f64;
        } else if bin_residual >= next_item_size && post_residual < next_item_size {
            // this placement destroys room for the next item
            score += 8.0;
        }
        // If next item is large, prefer spreading load into emptier bins.
        if next_item_size > bin_capacity / 2 && bin_residual > bin_capacity / 2 {
            score -= 5.0;
        }
    }

    // New-bin candidate handling: empty bin gets a dynamic penalty so we only
    // open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let open_bonus = (open_bins_count as f64).ln().max(0.0);
        score += 25.0 + 20.0 * progress + 5.0 * open_bonus;
        // But if no open bin fits well, opening may be right: handled by
        // comparing against the dead-space/last-chance penalties above.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
        // Avoid hoarding empty bins when mean residual is already large.
        if mean_residual > 40.0 {
            score += 15.0;
        }
    }

    // Mild preference for bins below mean residual (balance load).
    score += 0.05 * ((bin_residual as f64) - mean_residual).max(-50.0).min(50.0);

    // Late-stream: consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post / cap;

    let mut score = post;

    // smooth non-linear coupling of post_residual with stream progress
    let coupling = post_norm * post_norm * (0.5 + 1.5 * progress);
    score += 40.0 * coupling;

    // reward tight fits (low post_residual) more strongly as stream advances
    score -= (1.0 - post_norm) * (1.0 - post_norm) * 15.0 * (0.3 + 0.7 * progress);

    // penalize bins whose residual deviates strongly from mean residual
    let dev = post - mean_residual;
    score += 0.15 * dev * dev / cap;

    // lookahead: bonus if next item fits well into resulting residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 12.0 * (1.0 - slack) * (1.0 - slack);
        } else {
            score += 8.0 + 0.1 * (nxt - post);
        }
    }

    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 20.0 * (1.0 - post_norm);
    }

    // mild pressure to reuse bins when many are open
    score += 0.05 * open_bins_count as f64 * post_norm;

    // new-bin candidate: penalize opening a bin unless item is large / fit elsewhere is bad
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - fit_ratio) * (0.5 + 0.5 * progress);
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, but not zero-waste obsession — penalize tiny residuals
    if post_residual > 0 {
        let cap_frac = post_residual as f64 / bin_capacity as f64;
        // Harmonic classes on post_residual: classify dead space by capacity fraction
        if cap_frac < 0.10 {
            score += 6.0; // unusable sliver
        } else if cap_frac < 0.25 {
            score += 2.0; // small dead space
        } else if cap_frac < 0.50 {
            score -= 1.0; // still useful
        } else {
            score += 3.0; // half-empty bin after placement is wasteful
        }
    } else {
        score -= 8.0; // perfect fit is best
    }

    // Modulo arithmetic on post_residual: residuals that are multiples of small
    // item sizes (10, 20, 25) remain reusable by future items
    let reusable = (post_residual % 10 == 0) || (post_residual % 20 == 0) || (post_residual % 25 == 0);
    if reusable {
        score -= 2.5;
    } else {
        score += 1.5;
    }

    // Integer division thresholds: post_residual / next_item_size
    if next_item_size > 0 && post_residual > 0 {
        let fits_next = post_residual >= next_item_size;
        if fits_next {
            // bin can serve the lookahead item too — reward proportionally
            score -= 3.0 + (next_item_size as f64 / bin_capacity as f64) * 4.0;
        } else {
            // dead space smaller than next item: penalize by how close it is
            let gap = next_item_size - post_residual;
            score += (gap as f64) * 0.15;
        }
    }

    // Last-chance bin: only fitting bin available — strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 5.0;
    } else if fitting_bins_count > 3 {
        // many options: be pickier, keep flexibility for large items
        score += 1.0;
    }

    // Stream progression: early on, prefer opening fresh bins to build flexibility;
    // late in stream, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // new-bin candidate
        let new_bin_bonus = 4.0 - progress * 6.0;
        score += new_bin_bonus; // early: cheap to open; late: expensive
        if next_item_size > 60 {
            score -= 2.0; // big lookahead item benefits from fresh capacity
        }
    } else {
        score -= progress * 2.0; // late stream: favor existing bins
    }

    // Mean residual coupling: if open bins are already loose, prefer filling them
    if mean_residual > 30.0 && bin_residual != bin_capacity {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: gaps too small for the smallest item are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // unusable sliver: heavy penalty
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit: strongly rewarded
    } else {
        // Penalize gaps that cannot fit the lookahead item (dead space for next step)
        if next_item_size > 0 && post_residual < next_item_size {
            score += 15.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
        // Reward leaving a gap that exactly accommodates the next item
        if next_item_size > 0 && post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Tightness reward: prefer bins where the item fills a large fraction of residual
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many bins are open
    if bin_residual == bin_capacity {
        // new-bin candidate: acceptable early, penalized as stream progresses / many bins open
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 40.0 * progress + 2.0 * open_bins_count as f64;
        // If no open bin fits well, opening may still win
        if fitting_bins_count == 0 {
            score -= 55.0;
        }
    } else {
        // Mild preference for bins with residual near mean (keeps bin profile balanced)
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: exact or near-exact fills are excellent.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 20.0;
    }

    // Dead-space penalty: residuals too small for any plausible item (min size 1..10)
    // are wasted space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits exactly in post_residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let after_next = post_residual - next_item_size;
        if after_next == 0 {
            score -= 45.0; // perfect 2-item chain
        } else if after_next <= 10 {
            score -= 25.0;
        } else {
            score -= 8.0;
        }
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: residual likely dead space.
        // Penalize proportionally to how wasted it is, but mildly (item may still be useful).
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 15.0 * waste;
    }

    // Relative to mean residual: prefer bins tighter than average (best-fit flavor).
    let diff = (bin_residual as f64) - mean_residual;
    score += 0.15 * diff.max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
        if post_residual < 10 {
            score -= 30.0; // nearly-full usage of last chance is ideal
        }
    }

    // New-bin candidate: neutral-ish score = capacity, but make it slightly
    // unattractive unless the current fit is bad. Base score already equals
    // post_residual = capacity for empty bin; add mild penalty so tight fits win.
    if bin_residual == bin_capacity {
        score += 10.0;
        // But if lookahead suggests the next item pairs well with a fresh bin,
        // and current fit is poor, ease the penalty.
        if next_item_size > 0 && post_residual as f64 > next_item_size as f64 * 1.5 {
            score -= 15.0;
        }
    }

    // Late in the stream: consolidate harder, avoid opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    } else {
        score += 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: less waste relative to capacity.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.35;

    // Penalize dead space that can never fit a typical item again.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward it.
    if next_item_size > 0 {
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            // Next item won't fit here; slight penalty for wasting the lookahead opportunity.
            score += 4.0;
        }
    }

    // New-bin candidate handling: penalize opening a new bin mildly unless
    // the current item is large and no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Opening new bins is more attractive early when many items remain.
        score = 55.0 + 25.0 * progress;
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a bin
        }
        if item_size >= 80 {
            score += 10.0; // large item into fresh bin is fine later
        }
        // If open bins have lots of mean residual, prefer reusing them.
        score += mean_residual * 0.3;
    }

    // Prefer bins whose residual is close to mean residual (balanced packing),
    // slightly favoring fuller bins as stream progresses.
    let residual_gap = (bin_residual as f64 - mean_residual).abs();
    score += residual_gap * 0.05 * (step_index as f64 / total_items.max(1) as f64 + 0.5);

    // Mild penalty for having too many open bins.
    score += open_bins_count as f64 * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear waste penalty: dead space below typical item size is worse
    let waste = pr / cap;
    score += 40.0 * waste * waste * (1.0 - waste);

    // Tight-fit reward (smooth): small post_residual relative to capacity
    score -= 25.0 * (-pr / (0.15 * cap)).exp();

    // Late in stream: prefer tighter packing (smooth progress coupling)
    score += pr * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly reward using it
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: reward leaving room for the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = (pr - nx).abs();
        let fits_next = ((pr - nx) / cap).max(0.0);
        score -= 15.0 * fits_next * (-gap / (0.3 * cap)).exp();
        // penalize leaving a sliver that next item can't use
        let unusable = ((nx - pr) / cap).max(0.0);
        score += 20.0 * (-unusable / (0.2 * cap)).exp() * (nx / cap);
    }

    // Crowd control: when many bins open, discourage opening more (smooth)
    let nb = open_bins_count as f64;
    if bin_residual == bin_capacity {
        score += 10.0 + 5.0 * (nb / (1.0 + nb));
    }

    // Mean residual deviation: prefer bins near mean residual (balance)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: quarter-decile capacity fractions.
    let item_class = item_size / 10;
    let post_class = post_residual / 10;
    let next_class = next_item_size / 10;

    // Reward exact harmonic fits (post_residual in {0, small multiples of 10}).
    let harmonic_fit = (post_residual % 10 == 0) as f64;
    score -= harmonic_fit * 6.0;

    // Penalize dead space: post_residual in awkward classes (1..=9 mod 10).
    if post_residual % 10 != 0 && post_residual > 0 {
        score += 3.0;
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Chain-fit: if the next item exactly fills the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits in the gap: reward proportional to class closeness.
        let gap = (post_class as i32 - next_class as i32).abs();
        score -= 8.0 - gap as f64 * 1.5;
    }

    // Integer-division threshold: large items (class >= 5) prefer tight bins.
    if item_class >= 5 {
        score -= (bin_capacity - bin_residual) as f64 * 0.05;
    }

    // Last-chance bonus: only one bin fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a bin when reasonable fits exist,
    // unless the item is huge and residual mean is small (fragmented bins).
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        if fragmentation > 0.3 && item_class >= 5 {
            score -= 4.0; // fresh bin for big items when open bins are fragmented
        } else {
            score += 10.0;
        }
        // Early in stream, allow fresh bins more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 5.0;
    }

    // Slight preference for bins with residuals in the same harmonic class as item.
    if bin_residual / 10 == item_class && bin_residual >= item_size {
        score -= 2.0;
    }

    // Mild global balance: pull toward mean residual.
    score += (bin_residual as f64 - mean_residual) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=9) are pure waste.
    if post_residual >= 1 && post_residual <= 9 {
        score += 60.0;
    }
    // Perfect fit is maximally rewarded.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Tight-but-usable fits: reward small usable residuals relative to item scale.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness;

    // If next item fits exactly in the post residual, strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 35.0;
    }
    // Penalize if post residual cannot hold the next item (dead space likely).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Open-bin pressure: fewer open bins preferred; discourage spreading.
    score += open_bins_count as f64 * 0.6;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when existing residuals are fragmented or poor fits.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        // Prefer opening a new bin when mean residual is large but unusable (many small gaps).
        if mean_residual > 25.0 && item_size > 60 {
            score -= 25.0;
        } else if mean_residual < 15.0 {
            // Existing bins nearly full; opening new bin is natural, slight penalty to prefer filling them.
            score += 15.0;
        } else {
            score += 10.0 + fragmentation * 0.1;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Mild penalty for leaving residual close to but above the dead zone (near-dead gaps).
    if post_residual > 9 && post_residual < 20 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact 2-step lookahead match (post_residual == next_item_size)
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score -= 12.0 / (1.0 + diff);

        // Perfect two-item fill is ideal
        if post_residual as i64 - next_item_size as i64 == 0 {
            score -= 20.0;
        }
        // Slight penalty if next item can't fit here and fit is loose
        if post_residual < next_item_size {
            score += 4.0;
        }
    } else {
        // Last item: prefer minimal post_residual
        score += 0.0;
    }

    // Penalize bins whose residual deviates from mean (fragmentation signal)
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev;

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Avoid wasting a nearly-full bin on a tiny item
    if post_residual > 0 && post_residual < 10 {
        score -= 5.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 6.0;
        // If next item is large, opening fresh bin is attractive
        if next_item_size > 50 {
            score -= 4.0;
        }
    }

    // Late in stream: consolidate, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post residual (tight fit), scaled
    score *= 1.0;

    // Lookahead: reward if next item fits exactly into post residual (perfect pairing)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // partial reward proportional to how well next item fills leftover
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // next item cannot fit here: slight penalty if post residual is dead space
            let dead = post_residual as f64 / bin_capacity as f64;
            if dead < 0.10 {
                score += 10.0 * (0.10 - dead) * 100.0;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, strongly prefer it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when decent fits exist elsewhere
    if bin_residual == bin_capacity {
        // new-bin candidate: baseline score is capacity - item_size; add a mild bias
        // so we only open new bins when no open bin gives a tight fit
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 5.0 + 10.0 * (1.0 - progress);
        // if item is small relative to capacity, opening a bin wastes space
        let waste = (bin_capacity - item_size) as f64 / bin_capacity as f64;
        score += 20.0 * waste;
        // if many open bins already, discourage proliferation
        score += (open_bins_count as f64).sqrt() * 2.0;
    } else {
        // Reward using existing bins when mean residual is high (fragmentation control)
        if (bin_residual as f64) > mean_residual {
            score -= 3.0;
        }
    }

    // Prefer filling bins that are already mostly full (reduce bin count)
    let fullness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fullness * fullness;

    // Avoid leaving residuals that nothing in [1,100] could use well later
    if post_residual > 0 && post_residual < 5 {
        score += 5.0; // tiny dead space penalty
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr as f64;

    // Smooth non-linear coupling: penalize large post_residual more as stream progresses
    score += 40.0 * norm_pr * norm_pr * (0.5 + progress);

    // Reward tight fits (small post_residual) increasingly late in the stream
    score -= 30.0 * (1.0 - norm_pr).powi(3) * (0.3 + 0.7 * progress);

    // Penalize dead space relative to mean residual of open bins
    score += 10.0 * (pr - mean_residual) / cap;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Lookahead: reward bins whose post_residual fits the next item
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 15.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // New-bin candidate: penalize mildly so we prefer filling open bins unless fit is poor
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + 10.0 * norm_pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: coarse integer division thresholds.
    // Classes: 0 (perfect fit), 1-9 (tight), 10-24 (medium), 25-49 (loose), 50+ (wasteful)
    let class: u32 = if post_residual == 0 { 0 }
        else if post_residual <= 9 { 1 }
        else if post_residual <= 24 { 2 }
        else if post_residual <= 49 { 3 }
        else { 4 };
    score += match class { 0 => -40.0, 1 => -18.0, 2 => -4.0, 3 => 6.0, _ => 14.0 };

    // Lookahead: reward bins whose residual can host the next item exactly-ish.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 12.0 - slack.min(12.0) * 0.5;
    } else if next_item_size > 0 {
        // Next item cannot follow here: penalize proportionally to its size.
        score += (next_item_size as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when it beats the tightest existing fit.
    if bin_residual == bin_capacity {
        // Neutral base; add mild penalty so existing bins with class 0/1 wins,
        // but allow new bin to win when existing residuals are all loose.
        score += 30.0 - mean_residual * 0.3;
        if next_item_size > 0 {
            score -= (next_item_size as f64) * 0.2;
        }
    }

    // Fraction of capacity used by this placement: reward high fill ratio.
    let fill = item_size as f64 / cap;
    score -= fill * 10.0;

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - post_residual as f64 / cap) * progress * 8.0;

    // Prefer bins below mean residual (consolidate small gaps).
    score -= (mean_residual - bin_residual as f64).clamp(-20.0, 20.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item are pure waste; punish them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward tight fits (small waste relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Pressure from number of open bins: prefer consolidating into existing
    // bins when many bins are already open.
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: make it attractive only when the item is large or
    // no good existing fit exists; otherwise keep it mildly unattractive.
    if bin_residual == bin_capacity {
        score -= 10.0;
        if item_size > 60 {
            score -= 25.0;
        }
        if fitting_bins_count > 1 {
            score += 20.0;
        }
    }

    // Lookahead: if the next item could exactly use the post-residual,
    // reward leaving that gap.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use this gap; small gaps become dead space
        if post_residual < next_item_size && post_residual > 0 {
            score += 15.0;
        }
    }

    // Slight preference for bins below mean residual (balance loads).
    score += 0.1 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post-residual
    // exactly (or near-exactly) matches the next item size.
    if next_item_size > 0 {
        let match_gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match => strong reward (subtract heavily).
        score -= 60.0 * (-match_gap / 8.0).exp();
        // If next item fits exactly too, this bin is a perfect chain.
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Penalize leaving residual too small for the next item (dead space),
        // scaled by how much dead space is created.
        if (post_residual as u64) < next_item_size as u64 {
            score += 1.5 * (next_item_size as f64 - post_residual as f64);
        }
    } else {
        // Last item: just minimize post residual.
        score += 10.0;
    }

    // Prefer tighter fits relative to mean residual.
    score += 0.4 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current open bins are all poor fits.
    if bin_residual == bin_capacity {
        score += 35.0;
        // If no other bin can fit the item, opening a new bin is required.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, favor consolidating rather than opening bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild penalty for leaving tiny unusable slivers (dead space < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Is this the new-bin candidate?
    let is_new_bin = bin_residual == bin_capacity;

    // Tight fit reward: strongly favor minimal post_residual.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 20.0;

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        // Dead space below minimum item size is unusable.
        score += 8.0;
    }

    // Lookahead coupling: if next item fits the post-residual, this bin
    // becomes a two-item chain -> reward; otherwise penalize large leftovers.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            score += (post_residual as f64) * 0.3;
        }
    }

    // Last-chance bin: only bin that fits the item -> strong reward to use it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 30.0;
    }

    // New-bin decision: opening a bin is expensive; penalize unless existing
    // fits are poor or few bins fit the item.
    if is_new_bin {
        score += 25.0;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a bin
        } else if fitting_bins_count == 1 {
            score -= 5.0; // last chance: opening is competitive
        } else {
            score += 10.0 * (fitting_bins_count as f64).ln();
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * progress;
    }

    // Prefer bins with residuals below mean (compact nearly-full bins),
    // penalize dumping into already-loose bins.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Mild penalty for proliferating open bins when many alternatives exist.
    score += 0.5 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: fraction of bin consumed by this placement
    let fill_frac = item_size as f64 / cap;
    let post_frac = post_residual as f64 / cap;

    // Reward tight fits (low post_residual) with a smooth non-linear coupling to progress.
    // Squared/cubic terms make the reward sharper as the stream advances.
    let tightness = 1.0 - post_frac;
    score -= 30.0 * tightness * tightness * (1.0 + progress);

    // Penalize small unusable dead space (post_residual that likely fits nothing),
    // with a smooth bell-shaped penalty peaked around low-but-nonzero post_residual.
    let dead = (post_residual as f64 / 40.0).exp() * (1.0 - (post_residual as f64 / 40.0).exp());
    score += 25.0 * dead * (0.5 + progress);

    // Lookahead coupling: if the next item fits the post residual, reward; else penalize.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let ratio = next_item_size as f64 / cap;
        score -= 12.0 * ratio * (1.0 - progress);
    } else if next_item_size > 0 {
        let gap = (next_item_size as f64 - post_residual as f64).max(0.0) / cap;
        score += 10.0 * gap * gap;
    }

    // Last-chance bonus: strongly favor using the only bin that fits, especially late.
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 - post_frac) * (0.3 + progress);
    }

    // Mild pressure to spread load when many bins are open with high mean residual.
    let mean_over = mean_residual / cap;
    score += 5.0 * (mean_over - post_frac).abs();

    // Slight preference for keeping post residual flexible (divisible chunks)
    score -= 4.0 * (post_frac * std::f64::consts::PI).sin().abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo-10 buckets model
    // "dead space" quality. Residuals that are multiples of 10 are
    // reusable by typical item sizes; odd/tiny residuals are dead space.
    let r = post_residual;
    let class_penalty = match r % 10 {
        0 => -6.0,
        1 | 2 | 3 => 8.0,
        4 | 5 | 6 => 3.0,
        _ => 0.0,
    };
    score += class_penalty;

    // Perfect fit reward (harmonic zero class).
    if r == 0 {
        score -= 50.0;
    } else if r <= 5 {
        score += 10.0; // near-dead sliver
    }

    // Fraction-of-capacity coupling: reward residuals in the "usable band"
    // (10..=50% of capacity), penalize both extremes softly.
    let frac = r as f64 / cap;
    if frac > 0.1 && frac <= 0.5 {
        score -= 4.0 * frac;
    } else if frac > 0.5 {
        score += 2.0 * (frac - 0.5);
    }

    // Lookahead harmonic: if next item fits exactly in post residual,
    // strongly reward; if next item cannot fit any residual class, penalize.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size < r {
            score -= 5.0 * (1.0 - (r - next_item_size) as f64 / cap);
        }
        // Next item shares a harmonic class with current item: chain bonus
        if next_item_size % 10 == item_size % 10 && next_item_size <= r {
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 30.0 + open_bins_count as f64;
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if post_residual < 10 {
            score -= 20.0; // item nearly fills a fresh bin entirely
        }
    }

    // Stream progression: late in stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * progress * (1.0 - post_residual as f64 / cap);

    // Deviation from mean residual: prefer bins below mean (tighter fills).
    score += 0.5 * (bin_residual as f64 - mean_residual).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly worthless.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual matches the current item well (tight fit).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Open-bins pressure: discourage opening new bins when many are open,
    // but slightly favor new bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress + 0.5 * open_bins_count as f64;
    } else {
        score -= 3.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: favor bins that can also fit the next item afterward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // Penalize leaving a gap that just barely fails the next item.
    if next_item_size > 0 && post_residual >= next_item_size.saturating_sub(2) && post_residual < next_item_size {
        score += 20.0;
    }

    // Prefer bins below mean residual (consolidating small leftovers).
    score += 0.15 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward when next item fits the post residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size <= post_residual {
            // Reward proportional to how well the next item fills the leftover.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 200.0 * fill;
        } else {
            // Penalize post residual that cannot host the next item, scaled by
            // how dead the space is relative to mean residual.
            let dead = post_residual as f64 / mean_residual.max(1.0);
            score += 50.0 * dead.min(3.0);
        }
    }

    // Compare post residual against mean residual: leaving less than average
    // leftover is good (tight packing).
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Penalize tiny unusable slivers (dead space), except exact fits.
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    // Late in the stream, prefer tightening existing bins over opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses; allow early
        // opening when current bin fits are poor.
        score += 40.0 + 120.0 * progress;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a nonlinear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize leaving dead space that cannot fit typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable slivers are wasted space
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; penalize slightly to prefer bins keeping flexibility
            score += 8.0;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    } else if fitting_bins_count > 3 {
        score += 2.0 * (fitting_bins_count as f64 - 3.0);
    }

    // Time horizon: early in the stream, be more conservative (prefer filling existing bins);
    // late in the stream, opening new bins is less costly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let new_bin_penalty = 55.0 * (1.0 - 0.5 * progress);
    if bin_residual == bin_capacity {
        // Candidate is a brand-new bin: base cost plus scaling with open bins.
        score = new_bin_penalty + 0.8 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // new bin gives room for the upcoming item too
        }
    } else {
        // Slight preference for bins whose residual deviates from the mean (consolidation).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score -= 0.05 * dev;
    }

    // Prefer placing larger items into already-open bins early (big items first effect).
    if item_size > 50 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual (tight fit), non-linearly.
    let mut score = norm_pr.powf(1.8) * cap;

    // Smooth coupling: late in the stream, tighten preference further.
    let tightness = 1.0 + progress * (norm_pr * (1.0 - norm_pr) * 4.0);
    score *= tightness;

    // Penalize dead space that is too small to be useful (smooth barrier).
    let useless = (10.0 - pr).max(0.0) / 10.0;
    score += useless * useless * 12.0;

    // Reward last-chance bins (avoid opening new bins unnecessarily).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Mild penalty for spreading across many open bins late in stream.
    score += progress * open_bins_count as f64 * 0.15;

    // Lookahead: bonus if next item fits the post-residual (chaining).
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = (post_residual - next_item_size) as f64;
        score -= 5.0 * (1.0 - slack / cap);
    }

    // Slight preference for bins below mean residual (balance residuals).
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fractions
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize residuals in "dead zones" (small unusable slivers)
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (post_residual near zero but usable)
    if post_residual == 0 {
        score -= 100.0; // perfect fit
    }

    // Modulo classes on post_residual: reward residuals divisible by common item classes
    let mod10 = post_residual % 10;
    if mod10 == 0 {
        score -= 8.0;
    } else if mod10 == 5 {
        score -= 3.0;
    } else {
        score += mod10 as f64 * 0.4;
    }

    // Integer division thresholds: post_residual in quarter classes
    let quarter = post_residual / 25; // 0..4
    score += match quarter {
        0 => 15.0, // tiny leftover: bad
        1 => 0.0,
        2 => -4.0,
        3 => -8.0,
        _ => -10.0, // roomy bin, still useful
    } as f64;

    // Lookahead coupling: does next item fit in the post_residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // reward if next item exactly or nearly fits
            let slack = post_residual - next_item_size;
            score -= 20.0 - (slack as f64).min(20.0) * 0.5;
        } else {
            score += 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: keep it neutral-to-slightly-poor so it wins only when fits are terrible
    if bin_residual == bin_capacity {
        score += 35.0 + frac * 10.0;
        // open new bin early in stream when few bins exist (cheap now)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 15.0 * (1.0 - progress);
    }

    // Prefer bins with residual below mean (consolidating fuller bins)
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.15;

    // Mild penalty for many open bins: encourage filling existing ones
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    score -= (bin_capacity as f64 - post_residual as f64) * 0.15;

    // Penalize "dead space": post_residual too small to ever hold a realistic item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    } else if post_residual < 20 {
        score += 8.0; // hard-to-fill gap
    }

    // Reward perfect fit.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, discourage creating more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 0.3 * (0.5 + progress);

    // New-bin candidate (empty bin): make it unattractive unless the fit is genuinely good.
    if bin_residual == bin_capacity {
        // Empty-bin post_residual = capacity - item_size; only attractive if item is large.
        score += 30.0;
        if item_size >= 70 {
            score -= 25.0; // large items fine in fresh bins
        }
    }

    // Lookahead: if next item could exactly fill the resulting gap, reward it.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // Penalize leaving a gap that the next item barely misses (wasted potential).
    if next_item_size > post_residual && post_residual > 0 && post_residual < next_item_size + 5 {
        score += 5.0;
    }

    // Mild tie-break: prefer bins already below mean residual (consolidating fullness).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual to next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (post_residual as f64 - nxt).abs();
        if diff < 0.5 {
            score -= 60.0; // perfect chain: next item exactly fills leftover
        } else if post_residual as f64 >= nxt {
            // next item fits here: reward proportional to tightness of chain
            score -= 25.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space created
            score += 10.0 + 0.5 * diff;
        }
    }

    // Prefer bins tighter than the mean residual (good fits).
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin before opening a new bin: strong bonus.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Penalize opening a brand-new bin unless current fit is truly bad.
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - post_residual) as f64;
        // new bin attractive only if item is large relative to capacity
        let largeness = item_size as f64 / bin_capacity as f64;
        score += 15.0 - 40.0 * largeness + 0.2 * waste;
    }

    // Mild preference for compacting fewer open bins as stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize dead space that is too small to be useful later
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Exact pairing bonus
        if post_residual == next_item_size {
            score -= 20.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score += 55.0 + 0.5 * waste;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
    }

    // Time horizon: later in the stream, prefer consolidation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 15.0 * progress * fit_ratio;

    // Prefer filling bins with larger residuals when many bins are open
    score += 0.05 * (open_bins_count as f64) * (mean_residual - bin_residual as f64).abs() / 100.0;

    // Mild preference for bins near the mean residual to keep balance
    score += 0.02 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    // Early on (progress ~ 0): prefer moderate post_residuals.
    // Late (progress ~ 1): strongly prefer small post_residuals (tight fits).
    let mut score = pr * (1.0 + progress) + norm_pr * norm_pr * (100.0 + 200.0 * progress);

    // Cubic interaction: penalize large dead space increasingly with progress.
    score += 50.0 * norm_pr * norm_pr * norm_pr * (1.0 + 3.0 * progress);

    // Last-chance bonus: if this is the only fitting bin, reward using it.
    if fitting_bins_count == 1 {
        score -= 30.0 + 40.0 * progress;
    }

    // Lookahead: if next item fits in post_residual, reward this placement.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 10.0 + 15.0 * progress;
    }
    // Penalize leaving residual that is too small for the next item (dead space risk).
    if next_item_size > 0 && (next_item_size as f64) > pr {
        score += 5.0 * progress * (1.0 - pr / cap);
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean — placing into below-mean-residual bins keeps large bins open.
    score += 0.3 * (mean_residual - pr) * (0.5 + progress);

    // Slight preference for reusing existing bins over opening new ones
    // (new-bin candidate has bin_residual == bin_capacity, so pr is large,
    // already penalized by the base terms; add small extra nudge).
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify dead space into residue classes mod 10.
    // Small residues (1..10) are "harmonically dead" — hard to fill later; penalize.
    let post = post_residual;
    if post > 0 && post <= 10 {
        score += 25.0 * (11.0 - post as f64); // tiny dead space is worst
    } else if post > 10 && post <= 20 {
        score += 8.0;
    } else if post <= 50 {
        score -= 4.0; // mid-range residual still usable
    }

    // Integer division thresholds: post_residual / 10 class
    let class = post / 10;
    score -= (class as f64) * 2.0;

    // Exact harmonic fit: post_residual divisible by common small sizes (10,20,25,50)
    if post == 0 {
        score -= 40.0; // perfect fill
    } else if post % 10 == 0 {
        score -= 10.0;
    } else if post % 25 == 0 {
        score -= 7.0;
    } else if post % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 30.0;
        } else if next_item_size < post {
            let gap = post - next_item_size;
            if gap <= 10 {
                score -= 12.0;
            } else {
                score -= (gap as f64).min(30.0) * 0.2;
            }
        } else {
            // next item cannot fit here; leftover must hold value
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else if fitting_bins_count > 1 {
        // many options: favor tighter fits relatively more
        score += (fitting_bins_count as f64 - 1.0) * 1.5;
    }

    // Capacity fraction of consumed space
    let fill_frac = (bin_capacity - post) as f64 / bin_capacity as f64;
    score -= fill_frac * 15.0;

    // Mean residual coupling: penalize making this bin deviate far below mean
    // (keeps portfolio of residuals balanced and fillable).
    let dev = mean_residual - post as f64;
    if dev > 0.0 {
        score += dev * 0.3;
    } else {
        score += dev * 0.1;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        if fitting_bins_count == 0 {
            score -= 60.0; // nothing fits: must open new bin
        } else {
            // prefer open bins unless their post_residual would be tiny dead space
            let bad_fit_threshold = 12.0;
            if (post as f64) < bad_fit_threshold && next_item_size > post {
                score -= 5.0 * progress + 2.0; // fresh bin slightly attractive
            } else {
                score += 55.0; // keep using open bins
            }
        }
    }

    // Stream progression: late in stream, consolidate harder (avoid new bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 {
        score -= progress * 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64; // dead space penalty
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight-but-usable fits (post_residual near item thresholds).
        score -= 12.0 * (item_size as f64 / bin_residual.max(1) as f64);
    }

    // Penalize leaving gaps that no plausible item (>=1) can use anyway: covered above.
    // Penalize bins whose remaining space is awkwardly mid-range (hard to fill later).
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when fit is loose.
    score += 0.35 * open_bins_count as f64 * (1.0 - item_size as f64 / bin_residual.max(1) as f64);

    // Last-chance bin: strongly prefer using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when the item is large and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / bin_capacity as f64;
        if fill > 0.6 {
            score -= 15.0 * fill; // large items: fresh bin is fine
        } else {
            score += 20.0; // small items should go into existing space
        }
    }

    // Late in the stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (bin_residual == bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    score -= 0.5 * (bin_residual as f64 - item_size as f64).abs().recip().min(1.0) * 20.0;

    // 2-step lookahead: reward if next item exactly fills post_residual
    if next_item_size > 0 {
        let gap = (post_residual as f64 - next_item_size as f64).abs();
        if post_residual as i64 == next_item_size as i64 {
            score -= 60.0; // perfect chain
        } else if post_residual >= next_item_size {
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // next item won't fit: penalize dead space scaled by gap
            score += 0.3 * gap;
        }
    } else {
        // last item: strongly prefer minimal post_residual
        score += post_residual as f64 * 0.5;
    }

    // Compare against mean residual: bins far below mean residual are precious
    let dev = mean_residual - bin_residual as f64;
    if dev > 0.0 {
        score -= 0.4 * dev; // tighter-than-average bin favored
    } else {
        score += 0.2 * (-dev);
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * open_bins_count as f64;
        if next_item_size > 0 && post_residual as i64 == next_item_size as i64 {
            score -= 55.0; // opening new bin enables perfect chain
        }
    }

    // Late-stream tightening: dead space matters more near the end
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: prefer bins where item fills a large fraction of residual.
    let residual = bin_residual as f64;
    let fill_ratio = item_size as f64 / residual.max(1.0);
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize dead space: small post_residual is good, but exact zero is best.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 {
        score -= 35.0;
    } else {
        score += 4.0 * (fitting_bins_count as f64 - 1.0).min(6.0);
    }

    // Lookahead: reward if next item fits the post residual (chaining).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // Penalize leaving space that next item can't use but is still large.
            let waste = post_residual as f64;
            score += 0.25 * waste;
        }
    }

    // Time horizon: early in stream, be conservative with new bins (pack tight);
    // late in stream, prefer closing bins out.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 20.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin should only win when fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, modulated by how bad alternatives are.
        score = post_residual as f64 + 30.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // forced new bin
        } else {
            // If existing fits are loose (high mean residual, few fitting bins),
            // opening fresh can be better.
            let loose = (mean_residual - item_size as f64).max(0.0);
            score -= 0.4 * loose;
            if fitting_bins_count == 1 {
                score += 10.0; // discourage abandoning the only fitting bin
            }
        }
        if next_item_size > 0 && next_item_size >= 50 && item_size >= 50 {
            score -= 15.0; // big items pair better in fresh bins
        }
    }

    // Mild penalty for spreading across many open bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Reward bins whose residual is close to mean (keep balance).
    score -= 0.1 * (residual - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) growth
    let mut score = pr
        + 40.0 * norm_pr * norm_pr * cap
        + 15.0 * norm_pr * norm_pr * norm_pr * cap;

    // Smooth stream-progress coupling: late in the stream, tight fits matter more
    let late = progress * progress;
    score += 60.0 * late * norm_pr * (1.0 - norm_item);

    // Reward near-perfect fills (post_residual small relative to capacity)
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * tightness;

    // Penalize when this bin is the only fitting one but fit is poor (last-chance pressure)
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Lookahead coupling: if next item fits in post_residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 20.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 10.0 * (1.0 - (next_item_size as f64 / cap));
    }

    // New-bin candidate: mildly discourage opening a new bin when good open bins exist
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64) / (mean_residual.max(1.0) / cap + 1.0);
        score += 5.0 + 3.0 * open_pressure + 20.0 * (1.0 - progress);
    }

    // Slight reward for reducing mean residual spread (consolidation)
    score -= 8.0 * (mean_residual / cap) * norm_item;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity-fraction buckets. Residuals that fall into "small" classes
    // (<= 1/8 of capacity) are near-perfect fills; reward them strongly.
    let cap = bin_capacity as f64;
    let eighth = cap / 8.0;
    let quarter = cap / 4.0;
    let half = cap / 2.0;
    let pr = post_residual as f64;

    if post_residual == 0 {
        score -= 40.0; // perfect fill
    } else if pr <= eighth {
        score -= 20.0; // near-perfect, dead space negligible
    } else if pr <= quarter {
        score -= 5.0;
    } else if pr <= half {
        score += 5.0; // half-empty bin: mediocre
    } else {
        score += 15.0; // mostly empty after placement: wasteful use
    }

    // Modular logic on post_residual: leftovers divisible by common small
    // item sizes (10/20/25) are more likely to be filled by future items.
    if post_residual > 0 && (post_residual % 10 == 0 || post_residual % 20 == 0 || post_residual % 25 == 0) {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect fits).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nr = next_item_size as f64;
            // reward proportional closeness of next item to post-residual
            score -= 8.0 * (nr / pr).min(1.0);
            // penalize if next item is huge and would leave a tiny odd remainder
            let chain_residual = post_residual - next_item_size;
            if chain_residual > 0 && chain_residual <= 5 {
                score += 4.0; // creates awkward dead space for the chain
            }
        } else {
            // next item cannot follow into this bin; slight penalty scaled
            // by how much it overflows
            score += 3.0 * ((next_item_size - post_residual) as f64 / cap).min(1.0);
        }
    }

    // Last-chance logic: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: an empty bin should only win when no open
    // bin offers a decent fit. Penalize opening a new bin progressively
    // with the fraction of the stream already processed and with the number
    // of open bins (avoid bin proliferation).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + 4.0 * (open_bins_count as f64).sqrt() + 6.0 * progress;
        // but if item is large relative to capacity, a fresh bin is fine
        score -= 10.0 * (item_size as f64 / cap);
        // if the mean residual across open bins is too small to matter,
        // opening fresh is more acceptable
        if mean_residual < item_size as f64 {
            score -= 14.0;
        }
    }

    // Tightness reward: the tighter the fit (item fills most of the bin),
    // the better; subtract proportional to fill ratio of the pre-placement
    // residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * fill_ratio;

    // Late-stream consolidation: as the stream ends, prefer packing into
    // existing bins to avoid leaving many partially-filled bins.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * t * (1.0 - pr / cap);

    // Mild penalty for spreading across many open bins when mean residual
    // is large (fragmentation signal).
    if mean_residual > half && open_bins_count > 3 {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // A residual that is too small to hold even the minimum item size (1) is
    // impossible here, but residuals below the typical small-item threshold
    // (<= 10) are "wasted" capacity; penalize them steeply.
    if post_residual > 0 && post_residual <= 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        score += 8.0;
    }

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward residuals that can exactly fit the lookahead item (k=2 lookahead).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 30.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Residual too small for the next item: mild dead-space penalty.
        score += 5.0;
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bins pressure: with many open bins, prefer reusing existing ones
    // (penalize the new-bin candidate more); with few open bins, consolidation
    // is less critical.
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual == bin_capacity {
        score += 20.0 + pressure;
    } else {
        score -= pressure * 0.5;
    }

    // Favor bins whose residual deviates below the mean (tighter bins get used first),
    // keeping large-residual bins available for large future items.
    if bin_residual as f64 > mean_residual {
        score += (bin_residual as f64 - mean_residual) * 0.3;
    } else {
        score -= (mean_residual - bin_residual as f64) * 0.15;
    }

    // Late in the stream, tighten up: dead space matters more when few items remain.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // next item fits exactly-ish: strong reward for tight match
            score -= (30.0 * (1.0 - diff / bin_capacity as f64)).max(0.0);
        } else {
            // next item won't fit here: penalize leftover dead space
            score += diff * 0.5;
        }
        // exact 2-step chain closure
        if post_residual == next_item_size {
            score -= 50.0;
        }
    } else {
        // last item: minimize waste
        score += post_residual as f64 * 0.1;
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize wasting a nearly-full bin's small residual on tiny item mismatch
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        score += 40.0 + open_bins_count as f64 * 0.5;
        if fitting_bins_count == 0 {
            score -= 200.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that cannot fit the average next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (post_residual as f64) < nxt {
            score += 8.0; // dead space for the lookahead item
        } else {
            score -= 4.0 * (1.0 - (nxt / (post_residual as f64 + 1.0)));
        }
        // Perfect lookahead pairing: post_residual exactly fits next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 5.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance bonus: only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fit = (post_residual as f64) / (bin_capacity as f64);
        // Opening new bin is good early or when existing fit leaves big waste.
        score = 25.0 + 40.0 * poor_fit - 20.0 * progress;
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    // Mild pressure toward filling bins when many are open.
    score += 0.05 * open_bins_count as f64;
    score += 0.5 * (mean_residual - post_residual as f64) / (bin_capacity as f64);

    // Time horizon: late in the stream, consolidate harder.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr;

    // Smooth polynomial coupling: prefer small post_residual non-linearly
    score -= 30.0 * (1.0 - norm_pr) * (1.0 - norm_pr);
    score += 20.0 * norm_pr * norm_pr * norm_pr;

    // Stream progress interaction: late in the stream, tighten packing more aggressively
    let late = progress * progress;
    score += 25.0 * late * norm_pr;
    score -= 15.0 * late * norm_item;

    // Lookahead: reward residual that can still fit the next item (smooth kernel)
    if next_item_size > 0 {
        let fit_gap = (pr - next_item_size as f64).abs();
        score -= 18.0 * (-fit_gap / cap).exp() * norm_next;
    }

    // Last-chance bin: strong reward when few fitting bins
    if fitting_bins_count <= 1 {
        score -= 40.0 * (1.0 - norm_item);
    } else {
        score += 5.0 * (fitting_bins_count as f64).ln() * norm_pr;
    }

    // Penalize bins far from mean residual (fragmentation dispersion)
    score += 8.0 * ((pr - mean_residual) / cap).abs();

    // Mild penalty for too many open bins relative to progress
    score += 3.0 * (open_bins_count as f64) * (1.0 - progress) / 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small dead-space" classes (very tight fits) are strongly preferred.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect packing, zero waste
    } else if pr <= 5 {
        score -= 30.0;
    } else if pr <= 10 {
        score -= 12.0;
    } else if pr <= 20 {
        score -= 4.0;
    } else if pr > 50 {
        // large leftover: either a big item fits later (good) or it is waste
        score += 6.0;
    }

    // Modulo-10 harmonic classes: residuals divisible by 10 align with the
    // common item-size grid (sizes are multiples of 10 in classic streams).
    if pr % 10 == 0 {
        score -= 8.0;
    } else if pr % 10 <= 3 {
        score += 3.0; // awkward sliver
    }

    // Integer-division thresholds: leftover can host at least a half-capacity item?
    if pr >= bin_capacity / 2 {
        score -= 5.0; // still broadly reusable
    } else if pr < bin_capacity / 10 {
        score += 2.0; // near-dead space unless it was a perfect fit
    }

    // Lookahead coupling: does the next item fit into the post residual?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 40.0; // next item exactly fills this bin
        } else if next_item_size <= pr {
            // how harmonically aligned is the pair?
            let combo = pr + 0; // placeholder-free: use pr directly
            let _ = combo;
            score -= 10.0 + (pr - next_item_size) as f64 * 0.15;
            if (pr % next_item_size.max(1)) == 0 {
                score -= 6.0; // divisibility harmony
            }
        } else {
            score += 4.0; // next item won't fit here anyway
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate handling: only open a new bin when the item fits
    // poorly everywhere else (tight streams keep bins closed).
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base penalty so we prefer existing bins with decent fits;
        // relax it when many bins are open and mean residual is small.
        let pressure = (open_bins_count as f64) * 2.0 + (bin_capacity as f64 - mean_residual) * 0.5;
        score += 45.0 - pressure.min(35.0);
        // Late in the stream, opening fresh bins is less attractive.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 10.0;
    }

    // Mild preference for tighter bins overall (best-fit flavor).
    score += (bin_residual as f64) * 0.05;

    // Progress-scaled tie-breaking.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (pr as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0 * (1.0 - post_residual as f64 / 20.0);
    }

    // Perfect or near-perfect fits are highly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open bins pressure: with many open bins, prefer filling existing ones.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
    score += pressure * 3.0;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If next item would be blocked by a tiny dead gap, penalize.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: make it unattractive unless current bins are very full/tight.
    if bin_residual == bin_capacity {
        score += 45.0 + open_bins_count as f64 * -0.5;
        // If no open bin fits, opening a new bin becomes acceptable.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core: reward exact/near-exact fills strongly (non-linear).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness * tightness;

    // 2-step lookahead: if next item fits into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit_ratio = next_item_size as f64 / post_residual as f64;
            // reward when next item fills the remaining space well
            score -= 25.0 * next_fit_ratio * next_fit_ratio;
        } else {
            // dead space penalty relative to next item's size
            let waste = post_residual as f64;
            score += 0.15 * waste;
            // extra penalty if next item is large and this bin leaves awkward gap
            if next_item_size > post_residual && post_residual < next_item_size {
                score += 0.1 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Compare against mean residual: prefer bins tighter than average.
    let diff = mean_residual - bin_residual as f64;
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Penalize opening a new bin when decent fits exist, unless item is huge
    // and current bin residual is much larger than item (bad packing).
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of opening a bin
        score += 20.0;
        // but allow opening when open bins are all poorly suited
        if fitting_bins_count > 0 {
            let best_possible = item_size as f64; // perfect fit leaves 0
            let avg_waste = mean_residual - best_possible;
            if avg_waste > 30.0 {
                score -= 15.0;
            }
        }
        // early stream: opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * (1.0 - progress);
    }

    // Slight bonus for using existing bins as stream matures.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (bin_residual != bin_capacity) as i32 as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item,
    // but only if the pairing leaves a reasonable residual afterwards.
    if next_item_size > 0 {
        if post_residual as u32 >= next_item_size {
            let pair_residual = post_residual as u32 - next_item_size;
            if pair_residual == 0 {
                score -= 500.0;
            } else if pair_residual <= 10 {
                score -= 120.0;
            } else {
                score -= 25.0;
            }
        } else {
            // Dead space that cannot host next item: penalize proportionally.
            score += (post_residual as f64) * 0.3;
        }
    }

    // Penalize wasting a large residual bin on a small item.
    let waste = (bin_residual - item_size) as f64;
    score += waste * 0.15;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor
    // and the item is large (little fragmentation expected later).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let avg_fit_gap = (mean_residual - item_size as f64).max(0.0);
        score += 40.0
            - avg_fit_gap * 0.5
            - (item_size as f64) * 0.3
            + progress * 20.0
            + (open_bins_count as f64) * 2.0;
        // If next item is huge, a fresh bin is more valuable.
        if next_item_size > 0 && next_item_size >= 60 {
            score -= 30.0;
        }
    }

    // Prefer bins already below the mean residual (tighter consolidation).
    score += ((bin_residual as f64) - mean_residual).max(0.0) * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual in [0,1]

    // Smooth non-linear coupling: quadratic/cubic shaping of post residual,
    // modulated by stream progress.
    let shaping = x * x * (1.0 - x) * (2.0 - x); // peaks near x ~ 0.5, vanishes at 0 and 1
    score -= shaping * 18.0 * (0.5 + progress);

    // Penalize tiny dead space more strongly as stream advances (wasted space matters late).
    let dead = if pr > 0.0 { (1.0 - x) } else { 1.0 };
    score += dead * dead * 6.0 * progress;

    // Reward tight fits: interaction of item size with residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * fit_ratio * 4.0;

    // Last-chance bin bonus (avoid opening new bin unnecessarily).
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - progress * 0.5);
    }

    // Lookahead: reward leaving room for next item, smooth interaction.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let room = (pr - n).max(0.0) / cap;
        score -= room * (1.0 - room) * 10.0;
        // Penalize if post residual is just barely below next item size (dead space for lookahead)
        if pr < n {
            score += (n - pr) * 0.15;
        }
    }

    // Mild pressure to prefer bins below mean residual (balance residuals smoothly).
    score += ((pr - mean_residual) / cap) * ((pr - mean_residual) / cap) * 3.0;

    // Slight penalty for many open bins to encourage consolidation early.
    score += open_bins_count as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: multiples of common item sizes are valuable
    let pr = post_residual;
    let harmonic_bonus = if pr == 0 {
        -60.0 // perfect fit
    } else if pr <= 10 {
        12.0 // dead space: too small for any item
    } else if pr % 10 == 0 {
        -8.0 * (pr / 10) as f64 // divisible into 10-class items
    } else if pr % 5 == 0 {
        -3.0
    } else if pr < 20 {
        8.0 // small unusable sliver
    } else {
        0.0
    };
    score += harmonic_bonus;

    // Lookahead coupling: does post_residual accommodate the next item?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits here -> reward, scaled by how snugly
            let snug = (pr - next_item_size) as f64;
            score -= 15.0 - snug * 0.15;
            // harmonic class match: next item divides the leftover well
            let left = pr - next_item_size;
            if left == 0 {
                score -= 20.0;
            } else if left % 10 == 0 {
                score -= 5.0;
            }
        } else {
            // next item won't fit here: penalize proportional to the miss
            let miss = (next_item_size - pr) as f64;
            score += miss * 0.25;
        }
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 18.0;
        // extra urgency if the bin is already fairly full
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // base cost of opening a new bin: capacity worth of unused space
        score = bin_capacity as f64;
        // prefer new bin late in the stream or when open bins are fragmented
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 20.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 5.0; // fresh bin can host the next item
        }
        // penalize opening new bins when a decently fitting bin exists
        if fitting_bins_count > 0 {
            score += 10.0;
        }
    }

    // Coupling with mean residual: avoid bins far from the fleet average
    score += ((post_residual as f64) - mean_residual).abs() * 0.05;

    // Slight preference for fuller bins overall
    score -= (bin_capacity - bin_residual) as f64 * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10) are heavily penalized.
    if post_residual < 10 {
        score += 40.0;
    } else if post_residual == 0 {
        score -= 25.0; // perfect fit reward
    } else {
        // Non-linear penalty on dead space relative to capacity
        let frac = post_residual as f64 / bin_capacity as f64;
        score += 12.0 * frac * frac;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item cannot use the gap -> dead space penalty amplified
        score += 8.0;
    }

    // Last-chance bin pressure: strongly favor filling the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 0.8;

    // Slight pull toward bins with residual near the mean (keeps residuals uniform).
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // New-bin candidate: penalize opening a new bin unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Late-stream tightness: as stream progresses, prefer tighter fills.
    let progress = step_index as f64 / total_items as f64;
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when next item fits the post-residual exactly or well
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if (post_residual as f64 - nr).abs() < 1.0 {
            score -= 500.0;
        } else if post_residual as i64 >= next_item_size as i64 {
            // next item fits: reward proportionally to how snugly
            score -= 200.0 * (nr / (post_residual as f64 + 1.0));
        } else {
            // next item won't fit: penalize large dead space
            score += 50.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Prefer bins tighter than mean residual
    score -= (mean_residual - bin_residual as f64) * 0.5;

    // Last-chance bin bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins fit well, unless item is huge
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 120.0 - 40.0 * progress;
        if item_size > bin_capacity / 2 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is already favored by base term.

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 10.0;
    }

    // Penalize leaving dead space that the next item cannot use (lookahead).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless the fit is poor
    // in existing bins. Base score for empty bin is item_size; add a fixed
    // opening cost that tight fits in existing bins can overcome.
    if bin_residual == bin_capacity {
        score += 12.0 + 0.2 * mean_residual;
    }

    // Mild preference for bins with below-average residual (consolidate waste).
    score += 0.1 * (bin_residual as f64 - mean_residual);

    // Early in the stream, be slightly more willing to open bins for diversity.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;

    // Base: penalize wasted space, but discount waste late in the stream
    let mut score = pr * (1.0 + 0.5 * (1.0 - progress) * (1.0 - progress));

    // Non-linear tight-fit reward: strongly favor placements filling most of the bin
    let fill = fit_ratio;
    score -= 8.0 * fill * fill * (1.0 - pr / cap);

    // Coupling with mean residual: penalize bins far from the mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * dev * dev * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Lookahead: reward leaving room compatible with the next item
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        if pr >= nr {
            let slack = pr - nr;
            score -= 2.0 * (1.0 - slack / cap).abs() * (1.0 - progress);
        } else {
            score += 1.5 * (nr - pr) / cap;
        }
    }

    // New-bin candidate: make empty bins moderately attractive only when nothing fits well
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score = cap - 5.0 * fill - (fitting_bins_count as f64) * 2.0 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by small classes are more reusable.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward post-residuals that fall into "harmonic" classes (multiples of 10, 5, 25)
    if post_residual > 0 {
        if post_residual % 10 == 0 { score -= 6.0; }
        else if post_residual % 5 == 0 { score -= 3.0; }
        if post_residual % 25 == 0 { score -= 3.0; }
        // Penalize awkward dead space: tiny non-zero residues are wasted
        if post_residual < 10 { score += 12.0 - pr; }
    } else {
        // Perfect fit is ideal
        score -= 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let nres = post_residual - next_item_size;
            let mut bonus = 8.0;
            if nres % 10 == 0 { bonus += 4.0; }
            if nres == 0 { bonus += 8.0; }
            score -= bonus;
        } else {
            // post_residual too small for lookahead: penalize proportionally
            score += (next_item_size as f64 - pr).min(15.0) * 0.6;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // Fraction-of-capacity structure: bins with residual near half capacity are flexible
    let half = cap / 2.0;
    let dev = (pr - half).abs();
    score += dev * 0.05;

    // Integer-division threshold: residual in [1/3, 2/3] of capacity is highly usable
    let third = cap / 3.0;
    if pr >= third && pr <= 2.0 * third {
        score -= 4.0;
    }

    // Mild stream progression: early on, prefer packing into existing bins less aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Slight preference for consolidating when many bins are open
    score += (open_bins_count as f64) * 0.02;

    // New-bin candidate must look unattractive unless residual is huge and item is large
    if bin_residual == bin_capacity {
        score += 18.0;
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    // Deviation from mean residual: prefer bins tighter than average
    score += (pr - mean_residual).max(0.0) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // future item (sizes >= 1, but realistically small slivers are useless)
    // are heavily penalized.
    let dead_threshold: f64 = 10.0;
    if (post_residual as f64) < dead_threshold {
        // The smaller the unusable gap, the worse the placement.
        score += (dead_threshold - post_residual as f64) * 6.0;
    }

    // Reward near-perfect fits strongly (post_residual close to 0 but usable).
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Open-bins pressure: discourage spreading items across many open bins
    // when few bins can fit the item; encourage consolidating into bins
    // that already exist rather than fragmenting.
    if bin_residual != bin_capacity {
        // Existing bin: reward using it, scaled by how many alternatives exist.
        let pressure = (open_bins_count as f64).ln().max(1.0);
        score -= 8.0 / pressure;
        // Last-chance bin (only one fitting bin): strongly favor using it
        // to avoid opening a new bin unnecessarily.
        if fitting_bins_count == 1 {
            score -= 12.0;
        }
    } else {
        // New-bin candidate: penalize opening a new bin, especially when
        // other bins can fit the item.
        score += 10.0 + (fitting_bins_count as f64) * 4.0;
        // Early in the stream, opening bins is cheaper (more future items
        // to fill them); late in the stream, consolidation matters more.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 15.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual,
    // reward this placement (perfect two-item packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item still fits after this placement: mild reward.
        score -= 5.0;
    }

    // Mean-residual coupling: prefer bins whose residual is below the mean
    // (tighter bins get emptied of slack first), keeping the mean high for
    // future large items.
    if bin_residual != bin_capacity {
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        } else {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact/near-exact fit (small dead space).
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches the next item size.
    if next_item_size > 0 {
        let nr = next_item_size as f64;
        let diff = (post_residual as f64 - nr).abs();
        // Perfect chain: next item exactly fills the residual.
        if post_residual as f64 == nr {
            score -= 500.0;
        } else if post_residual as f64 > nr {
            // Next item fits with leftover; prefer small leftover after chaining.
            score -= 150.0 - diff * 1.5;
        } else {
            // Next item would NOT fit here; penalize leaving residual just below next item.
            score += 60.0 + (nr - post_residual as f64) * 2.0;
        }
    }

    // Relative-to-mean coupling: bins below mean residual are tighter; prefer
    // filling tight bins, penalize dumping into loose bins.
    let res = post_residual as f64;
    score += (res - mean_residual) * 0.5;

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity && open_bins_count > 0 && fitting_bins_count > 0 {
        // New-bin candidate: only attractive if all fits are terrible (large post_residual).
        score += 150.0;
    }

    // Mild progression term: later in stream, be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Penalize dead space that nothing can fill (post_residual < 10 unusable).
    if post_residual < 10 {
        score += 25.0;
    } else if post_residual <= 20 {
        // small leftover is fine, mildly reward
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let next_waste = post_residual - next_item_size;
            score -= 8.0 * (1.0 - next_waste as f64 / post_residual as f64);
        } else {
            // next item cannot follow here; penalize proportionally
            score += 4.0 * (next_item_size as f64 - post_residual as f64) / bin_capacity as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the
    // current fit is poor or the stream is early with few bins.
    if bin_residual == bin_capacity {
        // neutral baseline for a fresh bin
        score += 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing else fits, must open
        }
        if post_residual as f64 > mean_residual && open_bins_count > 2 {
            score += 5.0; // plenty of residual capacity around; avoid new bins
        }
    }

    // Time horizon: early in the stream, keep options open (mildly prefer
    // spreading); late, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress * tightness;

    // Prefer bins with residual below the mean (consolidating waste).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Many open bins: encourage filling existing ones harder.
    if open_bins_count > 4 {
        score += 1.5 * (open_bins_count as f64).ln() * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let pr = post / cap; // normalized post residual

    // Base: prefer tight fits (low post residual), smoothly scaled
    let mut score = post;

    // Non-linear polynomial coupling with stream progress:
    // early on, waste matters less; late, dead space is heavily penalized quadratically.
    let waste_penalty = pr * pr * (1.0 + 3.0 * progress) * cap;
    score += waste_penalty;

    // Smooth reward for exact/near-perfect fits, stronger later in the stream
    let perfect_fit = (pr * (1.0 - pr) * 4.0).powi(2); // peaks at pr = 0.5, zero at pr=0/1
    let tightness = (1.0 - pr).powi(3);
    score -= 8.0 * perfect_fit * (0.5 + progress) + 4.0 * tightness * (0.3 + 2.0 * progress);

    // Lookahead: reward bins whose post residual can host the next item (smooth kernel)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let slack = (post - nxt) / cap;
        let kernel = (-8.0 * slack * slack).exp(); // ~1 if next item fits snugly
        score -= 6.0 * kernel * (1.0 + progress);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 5.0 + 10.0 * progress;
    }

    // Mild penalty when bin residual deviates from mean residual (keep bin pool homogeneous),
    // weighted by number of open bins
    let dev = (post - mean_residual) / cap;
    score += 2.0 * dev * dev * (open_bins_count as f64).min(10.0);

    // New-bin candidate: neutral-to-slightly-high score unless residual is large
    if bin_residual == bin_capacity {
        score += 3.0 + 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space is worse in certain residue classes.
    let cap = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Perfect fit: strong reward.
    if pr == 0 {
        score -= 60.0;
    } else {
        // Integer-division thresholds on post_residual (harmonic classes of capacity / 8).
        let class = pr / (bin_capacity / 8).max(1);
        match class {
            0 => score -= 18.0,          // tiny residue, nearly perfect
            1 => score += 4.0,           // small but usable
            2 => score -= 6.0,           // mid residue, decent
            3 => score += 10.0,          // awkward dead space
            4 => score -= 2.0,           // half-full class
            _ => score += 2.0,           // large residue, still roomy
        }
        // Modulo coupling: residues near multiples of 5 are more reusable by future items.
        let m = pr % 5;
        if m == 0 {
            score -= 5.0;
        } else if m == 3 {
            score += 3.0;
        }
    }

    // Lookahead: does post_residual fit the next item? Reward chain placements.
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Prefer leaving space exactly usable by the next item.
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 - slack.min(12.0) * 0.4;
            if pr == next_item_size {
                score -= 15.0; // perfect chain
            }
        } else {
            // Post-residual cannot host next item: penalize proportionally.
            score += 6.0 * (next_item_size as f64 / cap);
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening fresh is only good for big items or when
    // all open bins would leave terrible dead space.
    if bin_residual == bin_capacity {
        // Base neutral score for a fresh bin: its post_residual = capacity - item.
        // Encourage fresh bin when item is large (poor fit anywhere).
        if item_size > bin_capacity / 2 {
            score -= 8.0;
        }
        if next_item_size > 0 && next_item_size > pr {
            score += 10.0; // fresh bin won't chain well either
        }
        // Late in stream, prefer closing out open bins rather than spawning.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
        // Many open bins with high mean residual: discourage new bins.
        score += (open_bins_count as f64).sqrt() * 2.0 + mean_residual * 0.05;
    }

    // Slight preference to fill bins that are already heavily loaded.
    let fill_ratio = 1.0 - bin_residual as f64 / cap;
    score -= fill_ratio * 8.0;

    // Tight-fit reward: item occupies most of the residual.
    let usage = item_size as f64 / bin_residual.max(1) as f64;
    if usage > 0.9 {
        score -= 10.0;
    } else if usage < 0.3 {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny gaps left after placement are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still host a typical next item (lookahead-aware).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // item won't fit here next round: dead space risk
    }

    // Last-chance bin: avoid opening a new bin when this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: fewer open bins is better; penalize spreading across many bins.
    score += open_bins_count as f64 * 0.8;

    // Deviation from mean residual: prefer bins tighter than average (better packing).
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3;

    // New-bin candidate: only attractive early in the stream or when residuals are tiny.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_tight = mean_residual / bin_capacity as f64;
        score += 30.0 * (1.0 - progress) + avg_tight * 20.0;
        if post_residual == bin_capacity {
            // empty bin's post_residual equals capacity; neutralize base term
            score += (bin_capacity as f64) * -1.0 + 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with slight superlinearity.
    score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 30.0;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // accommodates the next item, penalize near-miss dead space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            // Perfect chain match: strong reward.
            if gap == 0 {
                score -= 25.0;
            } else {
                // Smaller gap after next item => better 2-step packing.
                score -= 20.0 * (1.0 - (gap as f64 / bin_capacity as f64));
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally
            // to how wasted the residual is relative to next item size.
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(40.0);
        }
    } else {
        // Last item: pure best-fit.
        score -= 5.0;
    }

    // Relative to mean residual: bins tighter than average are more valuable.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin mildly, more so when many
    // bins are already open and stream is early (room to consolidate).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 12.0 + 10.0 * (1.0 - progress) + 0.2 * open_bins_count as f64;
        // But if next item matches a fresh bin's natural pairing, soften penalty.
        if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size == 0 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill_ratio * fill_ratio;

    // Penalize dead space that is too small to be useful later (typical item sizes 1..100).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            score += 8.0;
        }
        // Perfect pairing: this item plus next item nearly fills the bin.
        if (item_size + next_item_size) as f64 >= 0.95 * bin_residual as f64
            && (item_size + next_item_size) as u32 <= bin_residual {
            score -= 20.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, prefer using it over a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when the item is large relative to
    // capacity or no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let largeness = item_size as f64 / bin_capacity as f64;
        score += 35.0 - 30.0 * largeness - 40.0 * scarcity;
        // Early in the stream, opening bins is cheap; later, avoid bin proliferation.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Mild preference for bins tighter than average (consolidate waste).
    score += 0.05 * (mean_residual - bin_residual as f64);

    // Slightly favor more-loaded bins among many open bins to encourage consolidation.
    score += 0.02 * (open_bins_count as f64 - (bin_capacity - bin_residual) as f64 / 10.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let quad = norm_pr * norm_pr;
    let cube = quad * norm_pr;
    score += 6.0 * quad * cap * (0.5 + progress);
    score -= 4.0 * cube * cap * (1.0 - progress);

    // Reward tight fits, stronger later in the stream
    score -= 10.0 * (1.0 - norm_pr) * (1.0 - norm_item) * (0.5 + 0.5 * progress) * cap;

    // Penalize dead space relative to mean residual
    score += 2.0 * (pr - mean_residual) * (1.0 + progress);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Lookahead: favor leaving room for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 3.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 2.0 * (nx - pr) / cap * cap;
        }
    }

    // Mild penalty for bin proliferation early on
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is always best.
    if post_residual == 0 {
        score -= 1000.0;
        return score;
    }

    // Harmonic class of the leftover space: residues divisible by small
    // class sizes (10, 20, 25, 50) are more reusable by future items.
    let pr = post_residual;
    let class_bonus = if pr % 50 == 0 {
        60.0
    } else if pr % 25 == 0 {
        40.0
    } else if pr % 20 == 0 {
        30.0
    } else if pr % 10 == 0 {
        20.0
    } else if pr % 5 == 0 {
        10.0
    } else {
        0.0
    };
    score -= class_bonus;

    // Penalize dead space that no plausible item (1..=80) can use well:
    // very small leftovers are wasted capacity.
    if pr < 10 {
        score += 25.0 * (10 - pr) as f64;
    }

    // Reward leaving room for the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 200.0; // perfect chain: next item fits exactly here
        } else if post_residual >= next_item_size {
            // next item could also go here; slightly discourage hoarding
            // unless the fit is tight (leaves a harmonic residue again).
            let after_next = post_residual - next_item_size;
            if after_next % 10 == 0 {
                score -= 30.0;
            } else {
                score += 8.0;
            }
        } else {
            // next item won't fit here — fine, but reward that this bin's
            // residual stays in a usable harmonic class.
            score += 2.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current bins fit poorly (large post_residual relative to
    // capacity) or many bins are open with high mean residual.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64; // = 1.0 for empty bin
        let openness = open_bins_count as f64;
        let pressure = mean_residual / bin_capacity as f64;
        // Prefer new bin when existing bins are crowded or numerous.
        let new_bin_bias = 40.0 + 30.0 * openness + 100.0 * pressure;
        // But if this is a last-chance situation, never open a new bin.
        if fitting_bins_count == 1 {
            score += 10000.0;
        } else {
            score += new_bin_bias - 100.0 * poor_fit;
        }
    }

    // Mild stream-progression term: early on, be slightly more willing
    // to spread items across bins (keeps flexibility), later pack tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * (1.0 - progress);

    // Coupling: penalize creating residual far from mean residual
    // (fragmentation of the bin pool).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=100
    // interface, but conservatively 10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits (post_residual small but usable).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

