        score += 15.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when open bins exist and mean residual is large.
        if open_bins_count > 0 {
            score += 35.0 + 2.0 * open_bins_count as f64 + mean_residual * 0.3;
        }
    } else {
        // Existing bin: mild bonus relative to number of open bins.
        score -= (open_bins_count.min(10) as f64) * 1.5;
    }

    // Late in the stream, be more conservative: prefer filling existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
