    // strongly favor this bin (perfect 2-item packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_post = post_residual - next_item_size;
        score -= 25.0;
        // Extra reward if the pair leaves near-zero residual.
        score -= 12.0 * (1.0 - next_post as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // Next item cannot follow: penalize dead space proportionally to how much
        // it exceeds the next item's need.
        let gap = next_item_size as f64 - post_residual as f64;
        score += 0.35 * gap;
    }

    // Compare against mean residual: prefer bins whose post residual sits near the
    // mean (keeps residual spread balanced), penalize outliers.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current item is large
    // and would leave a big unusable hole elsewhere.
    if bin_residual == bin_capacity {
        let base_penalty = 20.0 + 0.25 * open_bins_count as f64;
        // Discount the penalty when the item is big (poor fit anywhere else).
        let big_item_bonus = if item_size >= bin_capacity / 2 { 12.0 } else { 0.0 };
        // If lookahead chains well in a fresh bin, soften the penalty.
        let chain_bonus = if next_item_size > 0 && post_residual >= next_item_size { 10.0 } else { 0.0 };
        score += base_penalty - big_item_bonus - chain_bonus;
    }

    // Slight late-stream conservatism: waste less as the stream nears its end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 60.0;

    // Penalize large dead space: post_residual that no future item (min size 1..~80) can use well.
    if post_residual > 0 {
        // dead space penalty grows if post_residual is awkwardly small (unusable)
        if post_residual < 10 {
            score += 25.0; // tiny slivers are near-waste
        } else if post_residual > 50 {
            score += 5.0; // large residual still flexible
        }
    }

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post_residual accommodates the next item exactly or well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap = post_residual - next_item_size;
            if gap == 0 {
                score -= 30.0; // chain fit: item + next item fills bin perfectly
            } else {
                score -= 10.0 * (1.0 - gap as f64 / bin_capacity as f64);
            }
        } else {
            // next item cannot follow into this bin: mild penalty scaled by how close
            score += 4.0 * (next_item_size - post_residual) as f64 / item_size.max(1) as f64;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // rather than opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // More competing fitting bins -> less pressure; slight penalty to spread demand.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Global state: prefer filling bins when many bins are open (consolidation).
    score -= (open_bins_count as f64).ln().max(0.0) * 3.0 * (1.0 - tightness);

    // Mean residual coupling: if mean residual is low, preserve large-residual bins
    // for future items; instead use bins with small residual.
    let dev = bin_residual as f64 - mean_residual;
    score += dev * 0.15;

    // Time horizon: early in stream, keep residuals flexible (favor balanced fills);
    // late in stream, prioritize closing bins tightly.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * (1.0 - progress); // early: amplify differences (exploration)
    if progress > 0.8 {
        score -= 8.0 * (1.0 - tightness); // late: push toward tight completion
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open
    // bin fits well — penalize new bins moderately so they're chosen only for poor fits.
    if bin_residual == bin_capacity {
        // base cost of opening a bin, softened when item is large or few bins fit
        let mut nb = 30.0;
        if item_size > 50 {
            nb -= 8.0;
        }
        if fitting_bins_count == 0 {
            nb -= 60.0; // no alternative: new bin is necessary
        } else if fitting_bins_count == 1 {
            nb -= 10.0;
        }
        if next_item_size > 0 && bin_capacity >= next_item_size {
            nb -= 3.0; // fresh bin has room for lookahead
        }
        score += nb;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr_norm = pr / cap;

    // Base: minimize post residual, but with diminishing penalty for tiny dead space
    let mut score = pr_norm.powf(1.5) * cap;

    // Smooth progress coupling: later in the stream, prefer tighter fits more aggressively
    let tightness = (1.0 - pr_norm).powi(2);
    score -= tightness * (10.0 + 30.0 * progress);

    // Penalize residuals that are too small to be useful for typical future items
    // smooth logistic-like penalty around pr ~ 30
    let usefulness = 1.0 / (1.0 + (-(pr - 30.0) / 10.0).exp());
    score += usefulness * 8.0 * (0.5 + progress);

    // Interaction: post_residual vs mean residual — avoid bins far from the mean fit quality
    let deviation = (pr as f64 - mean_residual).abs();
    score += (deviation / cap).powi(2) * 15.0;

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly into post residual, reward heavily (smooth gaussian)
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score -= 20.0 * (-gap * gap / 50.0).exp();
        // penalize if post residual is just barely too small for next item (dead space trap)
        if pr < next_item_size as f64 {
            let shortfall = next_item_size as f64 - pr;
            score += 6.0 * (-shortfall * shortfall / 100.0).exp();
        }
    }

    // Mild penalty for many open bins to encourage consolidation
    score += open_bins_count as f64 * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are preferred (tight packing).
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Reward very tight fits (post_residual in low harmonic buckets).
    if post_residual == 0 {
        score -= 50.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 20.0;
    } else if post_residual <= 20 {
        score -= 10.0;
    } else if post_residual <= 30 {
        score -= 4.0;
    }

    // Penalize dead space that nothing (min size 1) can usefully fill later:
    // residue classes mod 10 matter for integer item sizes.
    let dead = post_residual % 10;
    if post_residual > 0 && dead == 0 {
        score -= 2.0; // clean multiples of 10 are reusable
    } else if dead > 0 && post_residual < 10 {
        score += dead as f64; // tiny unusable slivers are penalized
    }

    // Lookahead coupling: if next item fits exactly in the post residual,
    // strongly reward; if next item cannot ever fit, penalize mildly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            score += 3.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0 + frac * 5.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is large relative to capacity or few bins fit it.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 > 0.6 * cap;
        if large_item || fitting_bins_count == 0 {
            score -= 15.0;
        } else {
            // Prefer reusing open bins with slack; make new bin unattractive.
            score += mean_residual * 0.5 + 10.0;
        }
    }

    // Progress-based mild pressure: late in the stream, consolidate.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 2.0;

    // Prefer bins with residual far below mean (they are "almost done");
    // keeps many half-empty bins available for future items.
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.1;

    // Harmonic integer-division threshold: quarter classes of capacity.
    let quarter = post_residual / (bin_capacity / 4);
    score += quarter as f64 * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // dead space below the minimum item size
    } else if post_residual < 25 {
        score += 18.0; // nearly dead space
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit is best
    }

    // Reward tight fits relative to bin residual.
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Open-bin pressure: discourage spreading when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // Mean-residual coupling: placing into a bin with residual far below mean
    // is good (drains small bins); above mean is wasteful.
    score += (bin_residual as f64 - mean_residual) * 0.4;

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item would fit the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    }
    // If next item cannot fit post-residual but would fit a fresh bin, penalize less.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 && post_residual < 10 {
        score += 10.0;
    }

    // New-bin candidate handling: empty bin is attractive only when this item
    // is large or the stream is early; otherwise keep filling open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 50 {
            score -= 20.0; // big items get fresh bins
        } else if open_bins_count > 0 && progress < 0.9 {
            score += 30.0; // prefer existing bins for small items
        } else {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches the next item size well.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Perfect match bonus: next item exactly fills the leftover space.
        if slack == 0.0 {
            score -= 60.0;
        } else {
            // Penalize proportional to leftover slack after the lookahead item.
            score -= 30.0 * (1.0 - slack / bin_capacity as f64);
        }
    } else if next_item_size > 0 {
        // Next item cannot fit in this bin's post-residual: mild penalty scaled by gap.
        let gap = (next_item_size - post_residual) as f64;
        score += 5.0 + 0.3 * gap;
    }

    // Reward tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness;

    // Compare against mean residual: prefer bins that are already fuller than average.
    let mean_dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score -= 15.0 * mean_dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Dead-space penalty: very small post_residual that likely can't fit future items (min size 1..10).
    if post_residual < 10 && post_residual > 0 {
        score += 8.0;
    }

    // Late in stream: consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that no future item (min size ~1..10) can use.
    if post_residual < 10 {
        score -= 12.0; // near-perfect fill
    } else {
        // waste grows super-linearly for awkward leftovers
        score += 0.35 * (post_residual as f64).powf(1.35) / 10.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        if gap < 10.0 {
            score -= 15.0; // chain fit
        } else {
            score -= 6.0 * (1.0 - gap / (bin_capacity as f64));
        }
    } else if next_item_size > post_residual {
        // next item cannot use this bin's leftover: mild penalty for stranding space
        score += 3.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0;
    }

    // Time horizon: early in the stream, be more liberal about opening bins
    // (spread items); late in the stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // opening a new bin gets more expensive as the stream progresses
        score += 8.0 + 25.0 * progress;
        // opening a bin when many bins are already open is costly
        score += 0.6 * open_bins_count as f64;
    } else {
        // using existing bins is favored more strongly later in the stream
        score -= 4.0 + 6.0 * progress;
    }

    // Global residual context: if mean residual is high, prefer filling bins
    // with large residuals (reduce fragmentation).
    if mean_residual > 0.0 {
        let rel = bin_residual as f64 / mean_residual;
        if rel > 1.0 {
            score -= 2.5 * (rel - 1.0).min(3.0);
        } else {
            score += 2.0 * (1.0 - rel);
        }
    }

    // Prefer bins whose residual is "compatible" with typical item sizes.
    let compat = (post_residual as f64 / 10.0).fract();
    if post_residual > 0 {
        score += 2.0 * compat; // leftovers at nice multiples of 10 are reusable
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling of post_residual with stream progress:
    // early on, prefer tight fills less aggressively; later, penalize waste quadratically.
    let waste_penalty = (pr / cap).powi(2) * (1.0 + 3.0 * progress);
    score += waste_penalty * cap;

    // Reward near-perfect fits with a smooth exponential term.
    let fit_quality = 1.0 - (pr / cap);
    score -= 8.0 * fit_quality.powi(4) * (1.0 + progress);

    // Lookahead: reward residual that can host the next item smoothly.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let slack = (pr - n).max(0.0);
        let coverage = 1.0 - (slack / cap).min(1.0);
        score -= 4.0 * coverage * (n / cap);
        // Penalize residual slightly below next item size (dead space for lookahead).
        let gap = (n - pr).max(0.0) / cap;
        score += 6.0 * gap * (1.0 - progress);
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 10.0 * (1.0 - (pr / cap).min(1.0));
    }

    // Crowding: with many open bins, mildly discourage spreading; prefer using existing space.
    let crowding = (open_bins_count as f64).ln_1p();
    score += 1.5 * (pr / cap) * crowding * (1.0 - progress);

    // Mean residual context: prefer bins near the mean (balanced usage), smooth kernel.
    let dev = ((pr - mean_residual) / cap).abs();
    score += 2.0 * dev * dev * cap * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: dead space is worse when it can't fit
    // common small items. Classify post_residual by integer division thresholds.
    let pr = post_residual;
    // Can a small item (<=10, <=20, <=30) fit afterwards?
    if pr == 0 {
        // already rewarded
    } else if pr < 10 {
        score += 40.0; // guaranteed dead space
    } else if pr < 20 {
        score += 15.0;
    } else if pr < 40 {
        score -= 5.0; // moderate usability
    } else {
        score -= 10.0; // still flexible
    }

    // Modulo arithmetic on post_residual vs typical item granularity:
    // residual congruent to 0 mod 10 pairs well with 10-multiple items.
    if pr % 10 == 0 && pr > 0 {
        score -= 8.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 3.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size <= pr {
            // next item fits: residual is reusable
            score -= (pr - next_item_size) as f64 * 0.5;
        } else {
            // next item will NOT fit in this bin afterwards: penalize tight fills
            score += (next_item_size - pr) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate logic: empty bin should only win when existing fit is bad.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score = cap * 0.85;
        // early in stream: opening bins is cheaper (build a pool)
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 60.0;
        // large items relative to capacity favor fresh bins
        if item_size * 5 as u32 / 4 >= bin_capacity {
            score -= 30.0;
        }
        // many open bins with high mean residual: reuse instead
        if mean_residual > cap * 0.3 {
            score += 40.0;
        }
        // lookahead: if next item is large, a fresh bin is valuable
        if next_item_size > bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Prefer fuller bins generally (tighter packing)
    score -= (bin_capacity - bin_residual) as f64 * 0.2;

    // Slight penalty for too many open bins
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // Gaps smaller than the minimum plausible item (1..100 interface, but
    // sizes up to 100) are worthless; treat "very small" gaps as dead space.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold {
        // Fully consumed or nearly dead bin -> reward strongly.
        score -= 40.0;
    } else if (post_residual as f64) < dead_threshold * 2.0 {
        // Small gap: penalize quadratically as unusable dead space.
        score += (dead_threshold * 2.0 - post_residual as f64).powi(2) * 0.15;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Open-bin pressure: discourage spreading across many open bins.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits the post-residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && (post_residual as f64) < (next_item_size as f64) {
        // Post-residual cannot host next item; penalize if it becomes dead space.
        score += 5.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly
    // (large dead space would be created) or many bins already open.
    if bin_residual == bin_capacity {
        let best_possible_waste = if fitting_bins_count >= 1 {
            // Approximate waste if we used an existing fitting bin.
            0.0
        } else {
            100.0
        };
        let pressure = open_bins_count as f64 * 0.5;
        score = 100.0 + pressure - 10.0 * (fitting_bins_count == 0) as i32 as f64;
        // If the item would leave a large unusable gap in any open bin,
        // opening a new bin is better; approximate via item size extremes.
        if item_size > 90 {
            score -= 80.0; // huge item: new bin is natural
        }
    }

    // Mean residual coupling: if open bins are already tight on average,
    // prefer packing into existing bins (lower score for tight bins).
    score -= (mean_residual / bin_capacity as f64) * 3.0;

    // Stream progression: late in the stream, consolidate harder.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

