        // but perfect fit already handled above.
        if post_residual < 10 {
            score += 40.0 * (10 - post_residual) as f64; // very hard to fill later
        }
    }

    // Aggressive 2-step lookahead: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 800.0;
        } else if next_item_size < post_residual {
            // Next item fits: mild reward, scaled by how snug the chain is.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 50.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // Next item cannot use this bin's leftover: penalize proportionally to waste.
            let overshoot = (next_item_size - post_residual) as f64;
            score += 15.0 * (overshoot / 100.0).min(1.0);
        }
    }

    // Compare post_residual against the mean residual: leaving this bin far below
    // mean residual creates fragmented small pockets; prefer bins that stay near mean.
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate handling: an empty bin has huge residual; make it attractive
    // only when no good fit exists elsewhere (i.e., when item leaves large awkward
    // leftover in any existing bin). Base penalty keeps it from winning by default.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Late in the stream, opening new bins is cheaper than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 80.0 * progress;
        // If many open bins, prefer consolidating instead of opening yet another.
        score += 5.0 * open_bins_count as f64;
    }

    // Mild preference for tighter fits overall (smaller post_residual already in base score,
    // but add non-linear urgency for near-perfect packing).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 20.0 * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale post_residual by how full the bin becomes.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score *= 0.5 + 0.9 * (1.0 - fill_ratio);

    // Penalize small unusable dead space (hard-to-fill slivers).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits the post-residual exactly-ish, reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual >= next_item_size {
            score -= 10.0 * (1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64));
        } else {
            // Next item won't fit here; mild penalty proportional to wasted opportunity.
            score += 5.0;
        }
    }

    // Time horizon: late in the stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (mean_residual / bin_capacity as f64);

    // Many open bins: discourage spreading; prefer bins below mean residual (fuller bins).
    if bin_residual < bin_capacity {
        let dev = (mean_residual - bin_residual as f64) / bin_capacity as f64;
        score -= 12.0 * dev;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (item large relative to typical residual) or few bins open early.
    if bin_residual == bin_capacity {
        let early = progress < 0.15;
        let poor_options = fitting_bins_count == 0 || (item_size as f64 > 0.6 * bin_capacity as f64 && mean_residual < item_size as f64);
        if early || poor_options {
            score -= 20.0;
        } else {
            score += 15.0 + 10.0 * progress;
        }
    }

    // Prefer bins that are already committed (avoid leaving many half-empty bins).
    if bin_residual < bin_capacity {
        score -= 5.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: tight fits are good (minimize post_residual), with quadratic sharpening
    let mut score = post + 0.5 * (post * post) / cap;

    // Smooth non-linear coupling of post_residual with stream progress:
    // early on, moderate residuals are tolerable; late in the stream,
    // dead space becomes progressively more costly (cubic-ish growth).
    let late_penalty = (post / cap) * (0.5 + 2.0 * progress * progress) * cap * 0.25;
    score += late_penalty;

    // Reward filling the bin well: interaction between item size and progress
    score -= item * (0.3 + 0.7 * progress);

    // Lookahead coupling: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let fit_next = 1.0 - gap / cap;
        if post >= nxt {
            score -= 2.5 * fit_next * fit_next * (1.0 + progress);
        } else {
            score += 1.5 * (nxt - post) / cap * (1.0 + progress);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 6.0 + 4.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is an outlier worth consuming; smooth tanh-like saturation.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 3.0 * (dev * std::f64::consts::FRAC_1_PI).tanh() * (0.5 + progress);

    // New-bin candidate handling: it has residual == capacity, so post == cap - item.
    // Penalize opening a new bin unless the item is large and stream is late.
    if bin_residual == bin_capacity {
        let waste = post / cap;
        score += 12.0 * (1.0 - waste) * (1.0 - waste) + 8.0 * (1.0 - progress);
        if next_item_size > 0 && (next_item_size as f64) <= post {
            score += 3.0; // new bin would serve the next item too, but only mildly attractive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "usable" residue classes (large enough for typical future items)
    // get rewarded; tiny dead-space residues get penalized.
    let post = post_residual;
    if post == 0 {
        score -= 60.0; // perfect fit is ideal
    } else if post < 10 {
        score += 40.0; // dead space: unusable residue class
    } else if post <= 25 {
        score -= 15.0; // sweet spot: fits most small items
    } else if post <= 50 {
        score -= 8.0;
    }

    // Modulo structure: multiples of common item sizes (10, 20, 25)
    // are reusable harmonic classes.
    if post % 10 == 0 && post > 0 {
        score -= 6.0;
    }
    if post % 25 == 0 && post > 0 {
        score -= 4.0;
    }

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post {
            score -= 35.0;
        } else if next_item_size <= post {
            let slack = post - next_item_size;
            if slack < 10 {
                score -= 20.0;
            } else if slack <= 25 {
                score -= 10.0;
            } else {
                score += slack as f64 * 0.05;
            }
        } else {
            // next item cannot use the leftover: mild penalty scaled by gap
            score += (next_item_size - post).min(30) as f64 * 0.3;
        }
    } else {
        // Last item: prefer tightest fit overall, ignore future usability
        score = post as f64 * 1.5;
    }

    // Last-chance bin: if this is the only fitting bin, opening a new
    // bin wastes its residual; prefer using it unless post is dead space.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing bins
    // would leave bad residue. Empty bin has post = capacity - item_size.
    if bin_residual == bin_capacity {
        score += 30.0;
        // but if the item is large, a fresh bin is natural
        score -= item_size as f64 * 0.35;
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 10.0;
    }

    // Prefer bins below mean residual (consolidating fuller bins),
    // keeps many partially-filled bins available for large future items.
    score += (mean_residual - bin_residual as f64).max(-50.0) * 0.08;

    // Slight preference for fewer open bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward zero dead space.
    if post_residual == 0 {
        score -= 500.0;
    }

    // Unusable small gaps (1..=9): dead space penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }

    // Gaps that exactly fit the lookahead item: reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 120.0;
    }
    // Gaps too small for the next item (but not dead): mild penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.5 * (next_item_size - post_residual) as f64;
    }

    // Last-chance bin: reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Open-bin pressure: fewer open bins is better; penalize spreading.
    score += open_bins_count as f64 * 2.0;

    // Prefer bins tighter than the mean residual (best-fit flavor).
    score += (mean_residual - bin_residual as f64).max(-50.0) * 0.3;

    // New-bin candidate: penalize slightly so we only open when open bins are bad.
    if bin_residual == bin_capacity {
        score += 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.95;
    score
