pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit bonus: strongly prefer bins that end at exactly 0 residual
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Penalize dead space quadratically, normalized by capacity
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 4.0 * waste * waste * bin_capacity as f64;
    }

    // Lookahead: reward if the next item can fit in the post-residual,
    // penalize if it cannot (this bin would become dead space for the future)
    if next_item_size > 0 {
        if (post_residual as f64) >= next_item_size as f64 {
            score -= 6.0;
        } else {
            score += 3.0 * (next_item_size as f64 - post_residual as f64).min(20.0);
        }
        // If next item fits exactly after this placement, big bonus
        if post_residual as u32 == next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        // With many fitting bins, prefer tighter fits (lower post_residual already does this)
        score += 0.5 * (fitting_bins_count as f64).ln();
    }

    // Mean residual coupling: prefer bins whose residual deviates favorably
    // from the mean; a bin with much larger residual than mean is a good host
    let res_diff = bin_residual as f64 - mean_residual;
    score -= 0.05 * res_diff;

    // Early stream: encourage filling bins tightly (first-fit-decreasing-like);
    // later stream: more willing to open new bins when fits are poor
    let open_bias = 12.0 * t;
    if bin_residual == bin_capacity {
        // New bin candidate: base cost, reduced as stream progresses
        score += 15.0 - open_bias;
        // Opening a new bin is more attractive when mean residual is small
        score -= 0.1 * mean_residual;
    }

    // Prefer bins that are already partially loaded (consolidation)
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let coupling = pr * (1.0 + 0.8 * progress + 0.6 * prog2);

    // Penalize small dead space non-linearly (smooth)
    let dead = pr / cap;
    let dead_penalty = 12.0 * dead * (1.0 - dead) * (1.0 - dead);

    // Reward tight fits smoothly
    let tight_reward = -30.0 * fill * fill * fill;

    // Lookahead: smooth bonus if next item fits the post residual
    let lookahead = if next_item_size > 0 {
        let fits = (pr >= next_item_size as f64) as f64;
        -8.0 * fits * (1.0 - (next_item_size as f64 / pr.max(1.0)).min(1.0))
    } else {
        0.0
    };

    // Last-chance bonus when this is the only fitting bin
    let last_chance = if fitting_bins_count == 1 { -6.0 } else { 0.0 };

    // New-bin candidate: mildly penalize so it's chosen only when fits are poor
    let new_bin = if bin_residual == bin_capacity {
        25.0 + 30.0 * progress
    } else {
        0.0
    };

    // Mild dispersion penalty relative to mean residual
    let disp = 2.0 * (pr - mean_residual).abs() / cap;

    let mut score = coupling + dead_penalty + tight_reward + lookahead + last_chance + new_bin + disp;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls on
    // "usable" residue classes (multiples of common item granularity)
    // are more likely to accept future items.
    let granularity: u32 = 10;
    let residue = post_residual % granularity;
    if residue == 0 {
        score -= 12.0; // perfectly aligned leftover space
    } else {
        score += (granularity - residue) as f64 * 1.5; // misaligned leftover penalized
    }

    // Dead-space cliff: very small post_residual is nearly useless unless zero.
    if post_residual == 0 {
        score -= 30.0; // perfect closure
    } else if post_residual < 10 {
        score += 25.0; // dead space
    }

    // Fractional capacity logic: reward filling a large fraction of the bin.
    let fill_fraction = item_size as f64 / cap_f;
    score -= fill_fraction * 20.0;

    // Lookahead coupling: if the next item fits exactly in post_residual,
    // strongly favor this bin (chained fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let chain_res = post_residual - next_item_size;
            score -= 10.0 - (chain_res as f64) * 0.15;
        } else if next_item_size > post_residual && post_residual > 0 {
            // leftover can't serve the next item: mild penalty scaled by waste
            score += ((next_item_size - post_residual) as f64).min(40.0) * 0.3;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new
    // bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: empty bin should win only when no open bin
    // offers a good fit. Penalize it by how much space would be "wasted"
    // relative to the item, modulated by stream progress.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score += waste * (0.4 + 0.4 * progress);
        // early in the stream, opening bins is cheaper; late, consolidate
        score -= (1.0 - progress) * 5.0;
    }

    // Mean-residual context: when open bins are generally full (low mean
    // residual), favor using existing bins harder; when they are empty-ish,
    // be pickier about fragmentation.
    score += (mean_residual - post_residual as f64) * 0.2;

    // Congestion: many open bins -> consolidate, prefer tight placements.
    score += open_bins_count as f64 * (post_residual as f64 / cap_f) * 2.0;

    // Integer-division threshold on item size: large items (>50% capacity)
    // should go into bins with least residual waste regardless of alignment.
    if item_size > bin_capacity / 2 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even
    // the smallest plausible item are pure waste. Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 15.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 60.0;
    } else {
        // Larger leftover space is reusable; mildly reward leaving room.
        score -= (post_residual as f64).sqrt() * 1.5;
    }

    // Reward tight fits: small post_residual relative to bin capacity.
    score += (item_size as f64 / bin_capacity as f64) * 10.0;

    // Open-bin pressure: discourage scattering items across many bins,
    // but only mildly so tight fits still dominate.
    score += (open_bins_count as f64) * 0.8;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual,
    // reward this placement strongly (enables chaining).
    if next_item_size > 0 {
        if (post_residual as i64 - next_item_size as i64) == 0 {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Next item won't fit in the leftover; penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Deviation from mean residual: prefer bins whose residual differs
    // from the average, enabling complementary pairings.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Mild preference for fuller bins early vs late in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match between post_residual and next_item_size
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        let diff = (post - next).abs();
        // Strong reward for perfect 2-step fill (post_residual == next_item_size -> waste 0 over two items)
        if diff < 0.5 {
            score -= 60.0;
        } else if next <= post {
            // next item fits after this placement: mild reward proportional to tightness
            score -= 15.0 * (1.0 - diff / bin_capacity as f64);
        } else {
            // next item would NOT fit: penalize leaving tempting-but-unusable space
            score += 10.0 + 0.2 * (next - post);
        }
    }

    // Penalize tiny dead space (unusable residuals) more than large ones
    if post_residual > 0 {
        let post = post_residual as f64;
        if post < 10.0 {
            score += 25.0 * (10.0 - post) / 10.0;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin would leave bad residual
    if bin_residual == bin_capacity {
        score += 40.0;
        // but if next item also fits perfectly in fresh bin after this one, allow it
        if next_item_size > 0 && (bin_capacity as f64 - next_item_size as f64 - item_size as f64).abs() < 0.5 {
            score -= 80.0;
        }
    }

    // Slight preference for filling bins as stream progresses (reduce open bins late)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
