pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: tight fits preferred (small post_residual)
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, dead space becomes more costly -> amplify superlinearly
    let progress_weight = 1.0 + 3.0 * progress * progress;
    score += progress_weight * (norm_pr * norm_pr) * cap * 0.5;

    // Penalize residuals that are too large (wasted space) with cubic term
    score += 0.01 * (norm_pr * norm_pr * norm_pr) * cap;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 {
        score -= 40.0 * (1.0 + progress);
    }

    // Lookahead: reward if next item fits into the post-residual (smooth soft version)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr - nxt).max(0.0);
        let fit_quality = 1.0 - (fits_next / cap);
        // smooth gate via sigmoid-like term on whether next fits
        let gate = 1.0 / (1.0 + (-(pr - nxt) / 10.0).exp());
        score -= 15.0 * gate * fit_quality;
        // penalize if post residual is just barely too small for next item (near-miss dead space)
        let near_miss = (-((pr - nxt) / 8.0)).exp();
        score += 8.0 * near_miss;
    }

    // Mild preference toward filling bins with below-average residual (balance)
    score += 0.05 * (mean_residual - pr);

    // Slight preference for consolidating into fewer bins when many are open
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0);

    // New-bin candidate: make empty bin mildly unattractive unless post-residual is large
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - item_size as f64 / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // --- Harmonic class of the post residual: residues near "useful" sizes ---
    let pr = post_residual;
    // Perfect fit reward
    if pr == 0 {
        score -= 1000.0;
    }

    // Classify post_residual by integer division into harmonic bands.
    // Bands: 0 (perfect), 1 (tiny dead space <=10), 2 (medium 11..25), 3 (large 26..50), 4 (half-empty+)
    let band = if pr == 0 { 0 } else if pr <= 10 { 1 } else if pr <= 25 { 2 } else if pr <= 50 { 3 } else { 4 };
    score += match band {
        0 => -600.0,
        1 => 45.0,   // tiny dead space is nearly unusable -> penalize
        2 => 10.0,   // medium: mildly useful
        3 => -8.0,   // large residual still fits future items
        _ => -15.0,  // half-empty bin: very reusable
    };

    // Modulo arithmetic: residuals divisible by common item sizes are more reusable.
    // Common sizes 10,20,25,50 divide residual cleanly -> reward.
    if pr > 0 {
        let mut harmony = 0.0;
        for m in [10u32, 20, 25, 40, 50] {
            if pr % m == 0 {
                harmony += 12.0;
            }
        }
        score -= harmony;
        // Penalize "odd" residuals that no typical item (1..100) can pair with well:
        if pr > 0 && pr < 10 {
            score += 20.0; // sliver
        }
    }

    // --- Lookahead coupling: does post_residual fit next_item_size exactly or well? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            let slack = pr - next_item_size;
            if slack == 0 {
                score -= 250.0; // chains perfectly
            } else if slack <= 15 {
                score += 5.0;   // creates another sliver
            } else {
                score -= 20.0;  // next item fits with room left
            }
        } else {
            // next item won't fit here; residual becomes dead until later
            score += 8.0;
        }
    } else {
        // Last item: any bin works, prefer closing bins tightly.
        score -= 30.0;
    }

    // --- Last-chance bin logic: if this is the only fitting bin, avoid opening a new bin ---
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // --- New-bin candidate handling: brand-new empty bin gets a neutral baseline ---
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no good fit exists:
        // penalize it more when many bins fit the item (good fits available).
        score = cap * 0.55 + (fitting_bins_count as f64) * 25.0;
        // But if the item is huge relative to typical residual, opening fresh is fine
        if item_size as f64 > cap * 0.8 && fitting_bins_count <= 2 {
            score -= 80.0;
        }
        // Late in the stream, prefer consolidating into existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += progress * 40.0;
    }

    // --- Mild preference for tighter (less residual) bins among equals ---
    score += (bin_residual as f64 - post_residual as f64) * 0.05;

    // Tie-break with mean residual context: if open bins are already loose, don't waste them
    if post_residual as f64 > mean_residual {
        score += 3.0;
    } else {
        score -= 3.0;
    }

    // Tiny deterministic jitter to break ties without randomness
    let tie = ((item_size as f64 * 0.017) + (step_index as f64 * 0.003)) % 0.5;
    score += tie;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small for the minimum item
    // (1) are pure waste; penalize them heavily, with a graded zone below 10.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 60.0;
    } else if post_residual < 10 {
        // Unusable dead space for streams with items >= 10; penalize.
        score += 25.0 + (10 - post_residual) as f64 * 3.0;
    } else if post_residual < 20 {
        // Marginal gap: usable only by small items; mild penalty.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Tight-fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill_ratio;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: mildly discourage proliferating bins, but this must
    // not override fit quality; scale with stream progression.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Mean residual coupling: if this bin's post placement residual is far
    // below the mean residual, we are consolidating waste — reward it.
    score -= 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly prefer this bin (chained perfect fit).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual >= next_item_size && post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is only attractive when no open bin offers a
        // good fit. Penalize opening unless the item is large relative to
        // capacity (large items pack cleanly into fresh bins).
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 18.0 - 25.0 * large_item;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual
    // exactly matches the next item size (chain packing).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if diff == 0.0 {
            score -= 500.0;
        } else {
            score += diff * 0.5;
        }
        // Penalize if placing item leaves residual that next item can't use
        if post_residual < next_item_size {
            score += 30.0;
        }
    } else {
        // Last item: just minimize post_residual (already base score).
    }

    // Penalize large dead space relative to mean residual of open bins.
    score += (post_residual as f64 - mean_residual).max(0.0) * 0.3;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer
    // using it over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // Slight penalty for opening a brand-new bin when stream is early/mid,
    // to encourage consolidation; relax late in the stream.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 50.0 * (1.0 - 0.5 * progress);
    }

    // Mild tie-break: prefer bins with lower residual overall.
    score += bin_residual as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + progress) + norm_pr * norm_pr * norm_pr * (2.0 * progress);
    score += 40.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 30.0 * tightness * tightness * (0.5 + progress);

    // Penalize dead space that cannot fit the next item (smooth coupling)
    let waste = if next_item_size > 0 && pr < next_item_size as f64 {
        (next_item_size as f64 - pr) / cap
    } else {
        0.0
    };
    score += 25.0 * waste * waste * (1.0 + 2.0 * progress);

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 15.0 * (1.0 + progress);
    }

    // Prefer bins with residuals near mean (balance) via smooth quadratic term
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Slight penalty for opening new bins early, relaxed late in stream
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress) + 5.0;
    }

    // Mild pressure to close near-full bins
    score -= 10.0 * norm_item * norm_item;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes of post_residual (mod 10): tiny residues are dead space.
    let cls = (post_residual % 10) as f64;
    score += cls * 0.6;

    // Quadratic penalty on wasted space (nonlinear coupling).
    let pr = post_residual as f64;
    score += 0.008 * pr * pr;

    // Reward tight fits relative to bin capacity fraction.
    let fill_frac = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_frac;

    // Lookahead: if next item fits exactly in post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        if next_item_size == post_residual {
            score -= 500.0;
        } else {
            // Harmonic class match: next item's mod-10 class aligning with residual class.
            if (next_item_size % 10) == (post_residual % 10) {
                score -= 60.0;
            }
            score -= 25.0 * (next_item_size as f64 / post_residual as f64);
        }
    } else if next_item_size > post_residual {
        // Next item won't fit here; penalize leaving awkward residue unless tiny.
        if post_residual > 0 && post_residual < 10 {
            score += 30.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        let base = 120.0 + 0.5 * open_bins_count as f64;
        // If the only alternative leaves huge dead space, allow new bin.
        if post_residual == bin_capacity && (item_size <= 20 || fitting_bins_count == 0) {
            score -= 400.0;
        } else {
            score += base;
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - bin_residual as f64).clamp(-50.0, 50.0) * 0.4;

    // Late-stream consolidation: favor filling existing bins as stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 30.0 * progress * fill_frac;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (1.0 - post_residual as f64 / 10.0);
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits relative to bin residual.
    score -= 0.5 * (item_size as f64 / bin_residual.max(1) as f64) * 10.0;

    // Open-bins pressure: prefer consolidating into fewer bins.
    score += open_bins_count as f64 * 0.3;

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize so it's chosen only when open bins are bad.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.2;
        // If the next item could pair with the leftover space, avoid wasting this bin's residual.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score += 10.0;
        }
    }

    // Lookahead: if the next item fits into the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual > 0 {
        score -= 12.0 * (next_item_size as f64 / post_residual as f64);
    }

    // Slight phase pressure: later in the stream, be more frugal with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for exact or near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // 2-step lookahead: reward when next item fits perfectly into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual > next_item_size {
            let chain_waste = post_residual - next_item_size;
            if chain_waste <= 10 {
                score -= 100.0 - chain_waste as f64 * 5.0;
            }
            // Penalize leaving residual too small for next item (dead space)
            if post_residual < next_item_size {
                score += 50.0;
            }
        } else {
            // next item cannot fit here: residual becomes dead space unless small
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus: avoid opening a new bin when this is the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize opening a new bin when open bins exist with reasonable residual
    if bin_residual == bin_capacity {
        score += 80.0 + mean_residual * 0.5;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 30.0;
        }
    }

    // Early stream: be more conservative about wasting large bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
