pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let t = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let cap = bin_capacity as f64;
    let rn = r / cap;
    let mut score = r;

    // Non-linear polynomial coupling of post_residual with stream progress
    score += 8.0 * rn * rn * (1.0 - t) * cap * 0.1;
    score -= 6.0 * rn * (1.0 - rn) * t * cap * 0.1;

    // Reward tight fits, penalize mid-range dead space with smooth terms
    score -= 12.0 * (1.0 - rn) * (1.0 - rn) * (1.0 - rn);

    // Lookahead: favor bins whose post-residual fits next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let match_f = if r >= nx { 1.0 } else { 0.0 };
        score -= match_f * 5.0 * (1.0 - ((r - nx) / cap).abs());
    }

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 7.0;
    }

    // Mild penalty for many open bins relative to progress
    score += 0.3 * open_bins_count as f64 * (1.0 - t);

    // New-bin candidate: keep it competitive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - t) - 4.0 * t;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: modulo arithmetic on capacity fractions
    let pr = post_residual;
    let class = pr % 10; // residue class mod 10
    let quarter = pr / (bin_capacity / 4).max(1); // which quarter of capacity remains

    // Reward post-residuals that are "harmonically clean" (divisible, small classes)
    if pr > 0 {
        if pr % 25 == 0 { score -= 12.0; }
        else if pr % 20 == 0 { score -= 8.0; }
        else if pr % 10 == 0 { score -= 4.0; }
        else if pr % 5 == 0 { score -= 2.0; }
        // small odd residues create dead space; penalize
        if class <= 2 && pr < bin_capacity / 5 { score += 10.0; }
    } else {
        score -= 30.0; // perfect fill
    }

    // Quarter-based shaping: prefer leaving room in the second/third quarter band
    match quarter {
        0 => score += 6.0,             // tiny residual -> dead space risk
        1 => score -= 5.0,             // ~25-50 left: usable
        2 => score -= 3.0,             // ~50-75 left: very usable
        _ => score += 2.0,             // nearly full bin already
    }

    // Lookahead coupling: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            // next item won't fit here; mild penalty proportional to overshoot class
            let over = (next_item_size - pr) % 10;
            score += over as f64;
        }
    } else {
        // last item: prefer tightest fit overall
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive early in the stream or when
    // open bins are nearly full on average
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let openness = mean_residual / cap;
        score = cap * 0.55 + 20.0 * (1.0 - progress) - 15.0 * (openness - 0.5).max(0.0);
        if fitting_bins_count == 0 { score -= 40.0; } // must open a bin
        if open_bins_count == 0 { score -= 50.0; }
    }

    // Global pressure: many open bins -> tighten packing (favor small residuals more)
    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64).sqrt()).min(2.0);
    score *= 1.0 + 0.15 * pressure;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
