    if bin_residual == bin_capacity {
        score += 60.0 + 15.0 * open_bins_count as f64;
    } else {
        // slight preference for tighter bins
        score += (bin_residual as f64) * 0.15;
        // prefer bins below mean residual (already loose bins fill later)
        if (bin_residual as f64) > mean_residual {
            score += 10.0;
        }
    }

    // Late in stream: be more conservative, avoid new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 80.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when next item fits the post residual
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly-ish: strong reward
            let tight = (post_residual as f64 - next_item_size as f64).abs();
            score -= 40.0 * (1.0 - tight / bin_capacity as f64);
        } else {
            // Next item does not fit: penalize wasted residual relative to next size
            let waste = (post_residual as f64 - next_item_size as f64) / bin_capacity as f64;
            score += 15.0 * waste.max(0.0);
        }
    } else {
        // Last item: just prefer tightest fit
        score += 0.0;
    }

    // Relative to mean residual: penalize bins much tighter than average (avoid fragmentation)
    let dev = (bin_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 5.0 * dev;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless current bins have poor fit
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 {
            (post_residual as f64 - next_item_size as f64).abs() > 20.0
        } else { false };
        if poor_fit && fitting_bins_count > 0 {
            // allow opening new bin: reduce default penalty
            score -= 10.0;
        } else {
            score += 60.0;
        }
    }

    // Progress-based scaling: later in stream, be more conservative (prefer filling bins)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // Reward tight fits
    score -= 18.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);
    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 14.0;
        } else {
            score -= 6.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }
    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 22.0;
    }
    // Many open bins: prefer filling existing ones over opening new
    score += 0.35 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);
    // Prefer bins whose residual is close to the mean (keeps residuals uniform)
    score += 0.12 * (bin_residual as f64 - mean_residual).abs();
    // Late in stream: be conservative, avoid small unusable residuals
    if t > 0.6 && post_residual > 0 && post_residual < 10 {
        score += 10.0 * t;
    }
    // New-bin candidate: penalize slightly so we only open when fits are bad
    if bin_residual == bin_capacity {
        score += 8.0 + 5.0 * (1.0 - t);
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score += 6.0; // pairing possible, but existing bins likely fine
        }
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: quadratic waste term (strongly penalize large leftover space)
    let mut score = pr * pr / cap;

    // Smooth coupling of waste with stream progress: later in the stream,
    // tight fits matter more (less room for error)
    score += pr * (0.5 + progress) * 0.35;

    // Interaction between post_residual and mean residual across open bins:
    // a bin whose post-residual deviates strongly from the mean is penalized
    // (keeps residual profile homogeneous and reusable)
    let dev = (pr - mean_residual).abs();
    score += dev * dev / (cap * 4.0);

    // Reward bins where the lookahead item also fits in the post-residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= (next_item_size as f64 / cap) * 6.0 * (1.0 + progress);
    } else if next_item_size > 0 {
        // lookahead won't fit here: mild penalty scaled by how close it was
        score += (next_item_size as f64 / cap) * 2.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 10.0 + 5.0 * progress;
    }

    // Penalize opening a brand-new empty bin when open bins exist
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 8.0 + 4.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Slight preference for fuller bins overall
    score -= (item_size as f64 / cap) * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space in low-modulo classes is harder to reuse.
    let pr = post_residual;
    if pr > 0 {
        let m5 = pr % 5;
        let m10 = pr % 10;
        // penalize awkward remainders
        score += match m5 {
            1 | 4 => 6.0,
            2 | 3 => 3.0,
            _ => 0.0,
        };
        if m10 != 0 && pr % (m10) == 0 && pr > 20 {
            score -= 2.0; // divisible into small chunks, reusable
        }
    } else {
        score -= 15.0; // perfect fit
    }

    // Capacity-fraction coupling: post_residual relative to capacity
    let frac = pr as f64 / bin_capacity as f64;
    if frac < 0.1 {
        score += 5.0; // near-dead space
    } else if frac < 0.25 {
        score += 1.5;
    }

    // Next-item lookahead: reward bins whose residual harmonically matches next item
    if next_item_size > 0 && pr >= next_item_size {
        let diff = pr - next_item_size;
        if diff % next_item_size == 0 {
            score -= 4.0;
        } else {
            score += (diff as f64) * 0.15;
        }
        if diff == 0 {
            score -= 8.0; // sets up perfect second fit
        }
    } else if next_item_size > 0 && pr < next_item_size {
        score += 2.5; // next item cannot use this bin anyway
    }

    // Last-chance bonus: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: only attractive when open bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 8.0 + 20.0 * (1.0 - fragmentation) + 10.0 * progress;
        score += penalty;
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    // Prefer tighter bins when many fit
    if fitting_bins_count > 2 {
        score += (bin_residual as f64 - item_size as f64) * 0.05;
    }

    // Integer-division threshold on residual class size
    let class = pr / 10;
    score += match class {
        0 => -3.0,
        1 => 0.0,
        2 => -1.0,
        3 => 1.0,
        _ => 0.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small to be useful later are wasted.
    // Typical useful minimum item is ~10-20; gaps below a threshold are near-worthless.
    let dead_threshold = 15.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward very tight fits (small positive post_residual) beyond raw value.
    if post_residual <= 5 {
        score -= 8.0;
    }

    // Slightly prefer filling bins with larger residual (reduce fragmentation),
    // but only mildly so dead-space logic dominates.
    score += (bin_residual as f64) * 0.15;

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // (the new-bin candidate has bin_residual == bin_capacity, so it gets
    // penalized here while tight fits in existing bins are favored).
    score += (open_bins_count as f64) * 0.6;

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual > 0 {
        score -= 10.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 15.0;
    }
    // Penalize if next item nearly fits but leaves a dead gap.
    if next_item_size > post_residual && next_item_size - post_residual <= 10 {
        score += 6.0;
    }

    // Mild mean-residual coupling: prefer bins below mean residual (consolidate).
    score += ((bin_residual as f64) - mean_residual) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
