pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * fit_ratio * fit_ratio;

    // Penalize waste proportional to item size relative to residual
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fill;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward if the next item fits into post_residual (chaining)
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0;
        } else {
            // penalize leaving residual that next item cannot use
            score += 8.0;
        }
        // exact pairing bonus
        if next_item_size == post_residual {
            score -= 20.0;
        }
    }

    // Time horizon: late in stream, prefer using existing bins more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 15.0 * progress * (1.0 - fit_ratio);

    // Global state: many open bins with high mean residual -> favor consolidation
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f * (fit_ratio - mean_residual / bin_capacity as f64).abs();

    // Penalize opening a new bin when existing bins fit well
    if bin_residual == bin_capacity {
        let pressure = (fitting_bins_count as f64).max(1.0);
        score += 35.0 / pressure + 20.0 * (1.0 - progress);
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Small nudge against creating tiny unusable residuals
    if post_residual > 0 && post_residual < 10 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial coupling to stream progress
    let mut score = pr * (1.0 + 0.6 * progress * norm_pr * (1.0 - progress));

    // Penalize large post-residuals more as stream progresses (dead space matters late)
    score += 18.0 * norm_pr * norm_pr * progress;

    // Reward tight fits (small post-residual) smoothly
    score -= 12.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.4 + 0.6 * progress);

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    }

    // Lookahead: favor bins whose post-residual fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (1.0 - ((post_residual - next_item_size) as f64) / cap);
    } else if next_item_size > 0 {
        score += 5.0 * progress;
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += (open_bins_count as f64) * 0.3 * (0.5 + progress);

    // Deviation from mean residual: prefer bins near/below average fill
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: capacity fractions via integer division.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let class = (post_residual * 4) / bin_capacity; // 0..=3 harmonic class of leftover

    // Reward tight fits strongly (small post_residual classes get big discounts).
    match class {
        0 => score -= 60.0,                       // near-perfect fit (post_residual < 25)
        1 => score -= 25.0,                       // decent fit
        2 => score -= 8.0,                        // mediocre
        _ => {}                                   // wasteful leftover
    }

    // Modulo-based "dead zone": leftover that cannot fit the mean item (~half capacity)
    let dead = (post_residual >= 1 && post_residual < (bin_capacity + 9) / 10) as i32;
    if dead == 1 { score -= 40.0; } // tiny slivers are great (bin nearly closed)

    // Penalize leftover that fits neither current stream's typical next item nor small items
    if post_residual > 0 && next_item_size > 0 {
        if next_item_size > post_residual {
            score += 18.0; // lookahead cannot use this bin's leftover
        } else if next_item_size == post_residual {
            score -= 35.0; // perfect pairing with lookahead
        } else {
            score -= 10.0;
        }
        // Harmonic pairing: post_residual and next_item in same quarter-class of capacity
        let nclass = ((next_item_size as u32) * 4) / bin_capacity;
        if nclass == class && next_item_size <= post_residual {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: only attractive when open bins are crowded or fit is bad.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = if post_residual + item_size as f64 > 0.0 { pr / cap } else { 1.0 };
        // Opening a new bin is penalized unless existing fits are poor or many bins open.
        let poor_fit = pr > cap * 0.6; // would waste > 60% of an existing bin
        if poor_fit {
            score -= 30.0 + 20.0 * progress;
        } else {
            score += 55.0 + 10.0 * (open_bins_count as f64).ln().max(0.0);
        }
        // Early stream: prefer consolidating into open bins.
        if progress < 0.2 { score += 25.0; }
        let _ = fit_quality;
    }

    // Mild preference to balance residuals toward the mean (avoid extreme fragmentation).
    let dev = (pr - mean_residual).abs();
    score += 0.05 * dev;

    // Slight bonus for filling larger items into larger-residual bins.
    score -= 0.02 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps (1..=10)
    if post_residual > 0 && post_residual <= 10 {
        score += 60.0 * (11.0 - post_residual as f64);
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward post-residuals that can still host typical items
    if post_residual >= 10 {
        score -= 8.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward strongly
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 25.0;
    }
    // Penalize if next item would need this bin's post residual but misses narrowly
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: fewer open bins -> prefer reusing existing bins
    score += 0.8 * open_bins_count as f64;

    // Mean residual coupling: prefer bins tighter than average
    score += 0.3 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: empty bin should only win when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 35.0;
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in stream, avoid opening bins unnecessarily
        score += 10.0 * (step_index as f64 / total_items.max(1) as f64);
    }

