}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact 2-step match: post_residual equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        // Strong reward for perfect lookahead match
        score -= 25.0 * (1.0 - diff / (bin_capacity as f64 * 0.5)).max(0.0);
        // Penalize post_residual that is small but nonzero relative to next item
        if post_residual > 0 && post_residual < next_item_size {
            score += 6.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    } else {
        // Last item: just minimize waste
        score -= 10.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter fill),
    // penalize bins that are much emptier than average.
    let res_f = bin_residual as f64;
    if res_f > mean_residual + 1e-9 {
        score += 0.5 * (res_f - mean_residual);
    } else {
        score -= 0.3 * (mean_residual - res_f);
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are all poor.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin
        score += 15.0;
        // But if existing bins have very little room, opening a new bin is fine
        if mean_residual < item_size as f64 * 0.6 {
            score -= 30.0;
        }
        // Early in stream, slightly prefer consolidating into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 5.0 * (1.0 - progress);
    }

    // Mild penalty for leaving tiny unusable dead space
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Prefer tight fits: reward small post_residual, especially exact fits.
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(6);

    // Penalize dead space that cannot fit the smallest plausible item.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item won't fit here; slight penalty for wasting the lookahead window
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item, favor it heavily.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins (spread load);
    // late in the stream, pack tightly into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // New-bin candidate handling.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when existing bins are crowded or fit is poor.
        let fit_quality = 1.0 - post_residual as f64 / bin_capacity as f64;
        let crowd = if open_bins_count == 0 { 0.0 } else { (mean_residual / bin_capacity as f64).min(1.0) };
        // New bin gets a base cost that shrinks as the stream progresses.
        let new_bin_cost = 30.0 - 20.0 * progress;
        score = new_bin_cost + (bin_capacity as f64 - item_size as f64) * 0.1
            - 10.0 * (1.0 - crowd)   // cheap to open when open bins are full-ish
            + 15.0 * fit_quality * (1.0 - progress); // early on, avoid scattering
    } else {
        // Prefer fuller bins: reward small residual relative to mean.
        score -= 8.0 * (1.0 - bin_residual as f64 / bin_capacity as f64);
        // If many bins fit the item, mildly prefer the emptiest (best future flexibility).
        if fitting_bins_count > 2 {
            score += 6.0 * (bin_residual as f64 / bin_capacity as f64);
        }
        // Late in stream, penalize leaving large residuals behind.
        score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
