    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post residual still fits the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 * (next_item_size as f64 / cap);
    }

    // Mild penalty for proliferating open bins early in the stream
    score += 0.4 * open_bins_count as f64 * (1.0 - t);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residuals divisible by common
    // item sizes (or by half-capacity) are more reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else {
        // Modulo harmonic reward: post_residual divisible by small classes
        if pr % 10 == 0 { score -= 6.0; }
        if pr % 20 == 0 { score -= 4.0; }
        if pr % 25 == 0 { score -= 3.0; }
        if pr % 50 == 0 { score -= 5.0; }

        // Dead space penalty: unusable for typical small items
        if pr < 10 { score += 60.0; }
        else if pr < 20 { score += 25.0 * (20 - pr) as f64 / 10.0; }

        // Lookahead: reward if next item fits the post residual
        if next_item_size > 0 {
            if next_item_size <= pr {
                // harmonic match classes
                if pr % next_item_size.max(1) == 0 { score -= 8.0; }
                score -= 5.0;
            } else {
                let waste = (next_item_size - pr) as f64;
                score += 0.4 * waste;
            }
        }

        // Capacity fraction thresholds (integer division)
        let quarter = bin_capacity / 4;
        let half = bin_capacity / 2;
        if pr > half { score -= 3.0; }
        else if pr > quarter { score += 1.0; }

        // Last-chance bin: strongly favor using it to avoid a new bin
        if fitting_bins_count == 1 { score -= 12.0; }

        // Many open bins: penalize spreading, favor tighter bins
        if open_bins_count > 4 {
            score += 0.05 * (open_bins_count as f64 - 4.0);
        }

        // Mean residual coupling: prefer bins near the mean (balanced packing)
        score += 0.15 * ((pr as f64 - mean_residual).abs());

        // Progress: later in stream, be greedier about tight fits
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 4.0 * (pr % 10) as f64 / 10.0;
    }

    // New-bin candidate: only attractive when current bins are poor fits
    if bin_residual == bin_capacity {
        if next_item_size > 0 && next_item_size > bin_residual - item_size {
            // next item won't fit the fresh bin after placement either
            score += 15.0;
        }
        if fitting_bins_count > 0 {
            score += 30.0 + 2.0 * open_bins_count as f64;
        } else {
            score -= 5.0; // no open bin fits: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    // Gaps below the minimum item size (1) can never be used; gaps in the
    // typical small-item range (1..=10) are near-dead. Penalize them hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0 - 3.0 * post_residual as f64; // small gap => big penalty
    }

    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin residual (high fill ratio).
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Penalize leaving a residual much larger than the next item would need
    // in a wasteful way, but reward residuals that can host the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0; // chain-friendly gap
        } else {
            score += 6.0; // gap too small for lookahead => likely dead space
        }
    }

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // compacting into existing bins unless the fit is poor.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.35 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // nothing fits elsewhere: open a new bin
        } else if mean_gap < 0.0 {
            score += 10.0; // existing bins fit tighter on average: keep them
        } else {
            score += 5.0 + 10.0 * progress; // late stream: consolidate instead
        }
    }

    // Mild alignment with mean residual: prefer bins near the average fill
    // to keep residual distribution balanced.
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact matches of post_residual to next_item_size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff;
        if post_residual == next_item_size {
            score -= 25.0; // perfect 2-chain: item + next item fill bin exactly
        }
        // Penalize leaving residual that neither fits next item nor is tiny
        if post_residual > 0 && post_residual < next_item_size {
            score += 8.0; // dead space blocks next item
        }
        // Bonus if bin can still hold next item after placement (keeps bin flexible)
        if post_residual >= next_item_size {
            score -= 5.0;
        }
    } else {
        // Last item: prefer tightest fit
        score += 10.0;
    }

    // Relative-to-mean coupling: prefer bins with residual below mean (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Penalize creating very small unusable residuals (dead space < min item size 1..10)
    if post_residual > 0 && post_residual < 10 {
        score += 20.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    if bin_residual == bin_capacity {
        // Base penalty so open bins are preferred unless they create dead space
        score = 35.0 + post_residual as f64 * 0.5;
        if fitting_bins_count <= 1 {
            // No (or single poor) alternative: opening a new bin is fine
            score -= 30.0;
        }
        if next_item_size > 0 && next_item_size <= bin_capacity.saturating_sub(item_size) {
            score -= 10.0; // new bin keeps room for lookahead item
        }
    }

    // Mild stream-progression pressure: late in stream, consolidate more aggressively
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small unusable leftovers (dead space below smallest plausible item).
    if post_residual > 0 && post_residual < 10 {
        score += 14.0;
    }

    // Lookahead: bonus if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 22.0;
        } else if next_item_size < post_residual {
            score -= 6.0;
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Crowding pressure: with many open bins, prefer reusing existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.35 * open_bins_count as f64 * (0.4 + 0.6 * progress);

    // Mean-residual coupling: if this bin is much tighter than average, prefer it.
    score -= 2.0 * (mean_residual - bin_residual as f64) / bin_capacity as f64;

    // New-bin candidate handling: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let waste_if_open = (bin_capacity as f64 - item_size as f64) / bin_capacity as f64;
        let desperation = if fitting_bins_count == 0 {
            0.0
        } else {
            let best_possible_waste = (bin_residual - item_size) as f64 / bin_capacity as f64;
            (best_possible_waste - 0.15).max(0.0) * 8.0
        };
        score = 30.0 + 45.0 * waste_if_open - desperation - 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Smooth polynomial coupling of post_residual with stream progress
    let pr_norm = pr / cap;
    let poly = pr_norm * pr_norm * (1.0 - progress) + pr_norm * progress * progress;

    let mut score = pr * (1.0 + 0.5 * poly);

    // Penalize dead space more as stream progresses (less future to absorb waste)
    score += 8.0 * progress * pr_norm * pr_norm * cap * 0.1;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 6.0 * fit_ratio * fit_ratio;

    // Last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // Lookahead: penalize if next item cannot use post_residual
    if next_item_size > 0 {
        if (next_item_size as f64) > pr {
            score += 4.0 * progress;
        } else {
            score -= 2.0 * (pr - next_item_size as f64) / cap;
        }
    }

    // Mild penalty when many bins are open (encourage consolidation)
    score += 0.15 * open_bins_count as f64;

    // New-bin candidate: keep neutral-ish, slightly penalized unless very early
    if bin_residual == bin_capacity {
        score += 3.0 - 4.0 * (1.0 - progress) * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: classify post_residual into
    // residue classes modulo 10 (small dead-space classes).
    let post = post_residual as i64;
    let cls = post % 10;

    // Reward perfect / near-perfect fits strongly.
    if post == 0 {
        score -= 1000.0;
    } else if post <= 5 {
        score -= 300.0;
    } else if post <= 10 {
        score -= 100.0;
    } else if post <= 20 {
        score -= 30.0;
    }

    // Penalize leftovers in "awkward" harmonic classes that few item sizes
    // (1..100, unknown distribution) can fill: residues 1..9 mod 10 leave
    // gaps that only tiny items can absorb.
    if cls >= 1 && cls <= 9 && post > 10 {
        score += (10 - cls) as f64 * 3.0;
    }

    // If the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // next item fits: mildly reward, scaled by how well it fits after.
        let nxt_post = post_residual - next_item_size;
        score -= 40.0 - (nxt_post as f64) * 0.5;
    } else if next_item_size > post_residual {
        // next item won't fit here anyway; penalize wasted big residual.
        score += (post_residual as f64) * 0.3;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 200.0;
    }

    // New-bin candidate handling: an empty bin has high raw score already
    // (post_residual == capacity). Only let it win if no open bin offers a
    // decent fit (e.g. best post residual would be large and awkward).
    if bin_residual == bin_capacity {
        // baseline for a fresh bin: slightly above a good fit
        score = (bin_capacity as f64) + 25.0;
        // if stream is early and many bins open, prefer spreading? no:
        // encourage reuse of open bins unless they waste space.
        if post > 0 {
            // this branch never true for empty bin, but keep guard
        }
        if open_bins_count == 0 {
            score -= 500.0; // must open first bin
        }
        // If the item is huge relative to capacity and mean residual is low,
        // a fresh bin is attractive.
        if (item_size as f64) > 0.6 * (bin_capacity as f64)
            && mean_residual < (item_size as f64) * 1.2
        {
            score -= 60.0;
        }
    }

    // Progress-based tie-break: later in the stream, be greedier about
    // tight fits (dead space is costlier when few items remain to fill it).
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += progress * (post_residual as f64) * 0.2;

    // Slight preference for bins with below-mean residual (denser bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: gaps too small for the minimum item size (1..100 range,
    // but keep a conservative unusable-gap threshold) are wasted forever.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0;
    } else if post_residual < 20 && post_residual > 0 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Lookahead: bonus if the next item fits exactly into the resulting gap.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size < post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: the residual is likely dead space.
            score += 15.0;
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Penalize opening a new bin when open bins could fit the item.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 120.0 + 10.0 * open_bins_count as f64;
        } else {
            score -= 20.0;
        }
    }

    // Open-bin pressure: mild preference to consolidate into fewer bins.
    score += 0.5 * open_bins_count as f64;

    // Slight preference for bins tighter than average residual.
    score -= 0.2 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: reward exact/tight match between post_residual and next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        let gap = (pr - nxt).abs();
        if pr >= nxt {
            // Next item can follow: reward tightness (small gap) strongly.
            score -= 30.0 * (1.0 - gap / bin_capacity as f64);
            if gap == 0.0 {
                score -= 40.0; // perfect chain
            }
        } else {
            // Next item cannot follow: penalize wasted residual, worse when gap small.
            let waste = pr / bin_capacity as f64;
            score += 15.0 * waste;
            if gap < 10.0 {
                score += 10.0; // near-miss is especially wasteful
            }
        }
    }

    // Penalize leaving very small unusable dead space (hard to fill later).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    // (large post_residual relative to mean residual).
    if bin_residual == bin_capacity {
        score += 12.0;
        if (post_residual as f64) < mean_residual {
            score += 8.0;
        }
        if open_bins_count == 0 {
            score -= 100.0; // must open a bin
        }
    } else {
        // Prefer fuller bins: tie-break toward bins with small residual before placement.
        score += (bin_capacity as f64 - bin_residual as f64) * 0.05;
    }

    // Late in the stream, consolidate aggressively to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity as f64 - bin_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, especially relative to capacity.
    let fit_ratio = (item_size as f64) / (bin_residual as f64);
    if fit_ratio > 0.85 {
        score -= 12.0 * fit_ratio;
    } else if fit_ratio < 0.35 {
        // Poor fit: leaves large awkward space, penalize.
        score += 6.0 * (0.35 - fit_ratio);
    }

    // Penalize dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny sliver is nearly unusable
    }

    // Lookahead: if the next item fits exactly into the post-residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 5.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // Next item won't fit here anyway; slight penalty for wasting big residual.
            score += 2.0 * (post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when the item
    // fits badly everywhere else. Base cost for opening a new bin.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in stream or many items remaining: fresh bins are cheaper to open.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
        // If open bins are already crowded on average, a new bin is more attractive.
        score -= (mean_residual / bin_capacity as f64).min(1.0) * 5.0;
    }

    // Global state: prefer consolidating into fewer bins when many are open.
    score += (open_bins_count as f64).sqrt() * 0.3 * (post_residual as f64 / bin_capacity as f64);

    // Time horizon: late in the stream, avoid leaving large residuals behind.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 3.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills a large fraction.
    let fill = item_size as f64 / bin_residual as f64;
    score -= 45.0 * fill * fill;

    // Non-linear penalty on wasted residual relative to capacity.
    let waste = post_residual as f64 / cap;
    score += 30.0 * waste * waste * waste;

    // Stream progress coupling: as the stream matures, prefer tighter fits even more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= (20.0 + 35.0 * progress) * fill * fill;
    score += (10.0 + 25.0 * progress) * waste * waste;

    // Coupling with mean residual: penalize deviating from the fleet's average slack.
    let dev = post_residual as f64 - mean_residual;
    score += 0.08 * dev * dev;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0 + 30.0 * progress;
    }

    // New-bin candidate: open a fresh bin only when fits are poor or fleet is congested.
    if bin_residual == bin_capacity {
        let congestion = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 25.0 + 15.0 * progress - 5.0 * congestion;
        // Lookahead: opening a bin is good if the next item is large.
        score -= 0.15 * next_item_size as f64;
    } else {
        // Lookahead synergy: reward leaving residual close to the next item's size.
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 0.12 * next_item_size as f64;
        score += 0.05 * gap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that no future item (size >= 1)
    // can be trusted to fill gets penalized super-linearly via integer division.
    let class = post_residual / 10; // harmonic classes of width 10
    score += (class * class) as f64 * 0.35;

    // Perfect fit is excellent.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Small post_residual that is unusable for typical items is penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 45.0;
    }

    // Lookahead: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how well it packs
            let nxt_class = (post_residual - next_item_size) / 10;
            score -= 30.0 - (nxt_class as f64) * 5.0;
        } else {
            // next item cannot use this residual: penalize leaving large gaps
            let gap_class = (next_item_size - post_residual) / 10;
            score += gap_class as f64 * 8.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 55.0;
    }

    // New-bin candidate (empty bin): only attractive when residual would be
    // large dead space or no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fit win.
        score += 70.0;
        // If placing here would leave a large unusable residual in an open bin,
        // opening fresh is better: reward new bin when item is large relative
        // to typical residual.
        if post_residual as f64 > mean_residual + 20.0 {
            score -= 45.0;
        }
        if fitting_bins_count == 0 {
            score -= 90.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 15.0;
    }

    // Tie-break toward consolidating into fewer bins.
    score += open_bins_count as f64 * 0.05;

    // Slight preference for bins with residual close to item (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.1;

    // Modulo harmonic: residuals that are multiples of common item sizes
    // (mod 10 == 0) are more reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 15.0;
    }

    // Reward near-perfect fits (post residual very small but zero is best).
    if post_residual == 0 {
        score -= 80.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && post_residual > 0 && next_item_size == post_residual {
        score -= 55.0;
    } else if next_item_size > 0 && next_item_size <= post_residual && post_residual > 0 {
        score -= (next_item_size as f64 / post_residual as f64) * 10.0;
    }

    // Open bins pressure: discourage proliferation of open bins when fit is loose.
    let open_pressure = open_bins_count as f64 * 0.8;
    score += open_pressure * (post_residual as f64 / bin_capacity as f64);

    // Prefer bins with residual below mean (packing tighter bins first).
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.3;
    } else {
        score += (res_f - mean_residual) * 0.15;
    }

    // New-bin candidate: only attractive when current fit is terrible
    // (large dead space) or late in stream with many open bins.
    if bin_residual == bin_capacity {
        let dead = (bin_residual - item_size) as f64;
        if dead < 10.0 {
            score -= 30.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Opening new bin is costly mid-stream; penalize mildly.
        score += 25.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact 2-step lookahead match: item + next item fill bin perfectly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0;
    }
    // Next item fits with small leftover: strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let leftover = (post_residual - next_item_size) as f64;
        score -= 60.0 - leftover * 0.8;
    }
    // Next item cannot fit: penalize wasting lookahead opportunity.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 25.0;
    }

    // Reward tight fits relative to mean residual.
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= (mean_residual - pr) * 0.5;
    } else {
        score += (pr - mean_residual) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // Penalize opening a new bin when decent alternatives exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = (fitting_bins_count as f64).max(1.0);
        score += 120.0 + progress * 40.0 - (pressure - 1.0) * 30.0;
        // If item is small, new bin wastes capacity.
        score += (bin_capacity - item_size) as f64 * 0.2;
    }

    // Slight penalty for large dead space relative to capacity.
    score += pr * pr / (bin_capacity as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect / near-perfect fit bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 60.0 + 4.0 * (10 - post_residual) as f64;
    } else {
        // Penalize creating unusable dead space (nothing can fit in it later).
        let dead = if post_residual < 10 { 0.0 } else { 0.0 };
        score += dead;
    }

    // Waste relative to capacity: normalized post-residual.
    score += (post_residual as f64 / bin_capacity as f64) * 40.0;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when item fits poorly everywhere else.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) > 40.0;
        let many_options = fitting_bins_count as f64 > 2.0;
        if poor_fit && many_options {
            score -= 80.0; // opening fresh bin is fine when this is a big item
        } else {
            score += 120.0; // discourage wasteful new bins
        }
        // Late in the stream, avoid proliferating bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 30.0;
    }

    // Lookahead: if the next item could fill this bin's post-residual well,
    // reward leaving this residual shape.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 90.0;
        } else if next_item_size < post_residual && post_residual - next_item_size < 10 {
            score -= 50.0;
        } else if next_item_size > post_residual {
            // next item won't fit here anyway; residual is dead weight
            score += 15.0;
        }
    }

    // Global state coupling: many open bins with high mean residual ->
    // prefer consolidating into bins below average residual (tighter bins).
    let below_mean = (bin_residual as f64) < mean_residual;
    if below_mean {
        score -= 20.0;
    } else {
        score += 10.0;
    }

    // Prefer bins with large residual for large items (best-fit already does this,
    // add slight first-fit-decreasing flavor for small items).
    if item_size <= 20 {
        score -= 10.0; // small items: keep them anywhere reasonable, avoid new bins
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 1 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear coupling: residual waste grows quadratically with progress pressure
    let pr_norm = pr / cap;
    score += (pr_norm * pr_norm) * cap * (0.5 + 0.5 * progress);

    // Tight fit reward (small post_residual) — subtract for excellent fits, stronger late in stream
    let tightness = 1.0 - pr_norm;
    score -= tightness * tightness * 12.0 * (0.6 + 0.4 * progress);

    // Penalize bins that become near-empty (dead space) more when many bins are open
    let dead = ((20.0 - pr).max(0.0)) / 20.0;
    score -= dead * dead * 8.0 * (open_bins_count as f64).ln().max(1.0) / (1.0 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: reward leaving room for the next item, penalize blocking it
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if pr >= ni {
            score -= 6.0 * (1.0 - (pr - ni) / cap);
        } else {
            score += 4.0 * (ni - pr) / cap;
        }
    }

    // New-bin candidate: mild penalty so it only wins when open bins fit badly
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * (1.0 - progress) + 0.05 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual deviates favorably from mean residual (diversity of gaps)
        let dev = (pr - mean_residual) / cap;
        score += dev * 4.0;
    }

    // Mean residual alignment: keep gap structure coherent
    score += (mean_residual - pr) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residuals that are multiples of
    // common item-size divisors are "usable" future space; odd fragments are dead space.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward residuals that divide evenly into plausible item classes (mod 10 grid).
    if post_residual > 0 {
        let harmonic_bonus = match post_residual % 10 {
            0 => 12.0,
            5 => 6.0,
            _ => 0.0,
        };
        // Perfect-fit reward: residual exactly matches a common item size class.
        if post_residual <= 80 && post_residual >= 10 && post_residual % 10 == 0 {
            score -= 20.0;
        }
        score -= harmonic_bonus * (pr / cap);
    } else {
        // Perfect closure of the bin is ideal.
        score -= 30.0;
    }

    // Penalize dead space: residual too small for any item (1..100 interface, min item 1,
    // but typical min 10 => treat < 10 as unusable).
    if post_residual < 10 && post_residual > 0 {
        score += 25.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Fraction of next item fill: tighter packing favored.
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * fill;
        } else {
            // Next item cannot use this residual: mild penalty proportional to waste.
            score += 0.1 * (post_residual as f64 - (post_residual as f64 % next_item_size as f64)).abs();
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fits are terrible.
    if bin_residual == bin_capacity {
        score += 45.0;
        // But if the item is large relative to capacity, opening fresh is reasonable.
        score -= 30.0 * (item_size as f64 / cap);
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    // Prefer bins whose residual is close to the mean (balance load) mildly.
    score += 0.05 * ((bin_residual as f64) - mean_residual).abs();

    // Tight fit reward: item fills most of the bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tightness * tightness;

    // Slight penalty for proliferating open bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.02 * open_bins_count as f64 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: post-residual, but dead space in small unusable gaps is extra bad.
    // A gap is "unusable" if it is smaller than the smallest plausible item (assume >= 10).
    let min_item = 10u32;
    let dead = post_residual < min_item;
    let dead2 = post_residual > 0 && post_residual < next_item_size && next_item_size > 0;

    score += post_residual as f64;

    if dead {
        score += 60.0; // total waste: gap can never be filled
    } else if dead2 {
        // gap too small for the lookahead item: partial dead-space penalty
        let gap = post_residual as f64;
        score += 20.0 * (1.0 - gap / (next_item_size as f64));
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        let tightness = 1.0 - (post_residual as f64) / (bin_residual as f64).max(1.0);
        score -= 15.0 * tightness * tightness;
    }

    // Last chance bin: strong reward to use it instead of opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and prefer consolidating into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open
        // or late in the stream; slight reward early when few bins exist.
        score += 8.0 + 1.5 * open_bins_count as f64 + 10.0 * progress;
        // If no open bin fits well (this is the fallback), new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Existing bin: reward using it, scaled by how full the fleet is.
        score -= 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    // Prefer bins whose residual is far from the mean (large residual bins
    // should absorb items; near-empty bins stay flexible for big items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 0.05 * dev;

    // If the next item would fit exactly in the post-residual, big bonus.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual is good, but dead space below
    // the minimum item size (1) is pure waste. Penalize unusable slivers.
    if post_residual == 0 {
        score -= 40.0; // perfect fit is excellent
    } else if post_residual < 10 {
        score += 15.0; // tiny sliver likely unusable dead space
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item exactly or well.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let next_fit_tightness = (post_residual - next_item_size) as f64;
            score -= 30.0 - next_fit_tightness * 0.5; // bonus scaled by how well next item fits
            if post_residual == next_item_size {
                score -= 25.0; // chain of perfect fits
            }
        } else {
            // Next item cannot follow in this bin: penalize proportionally
            // to the leftover gap that would be stranded.
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Compare against mean residual: placing into a bin with residual far
    // above the mean tends to leave other bins fragmented; prefer bins
    // whose residual is close to the item (efficient consumption).
    let resid_diff = (bin_residual as f64 - mean_residual).abs();
    score += resid_diff * 0.2;

    // Last chance: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin has full residual. Only
    // attractive when the item is large or the stream is early; otherwise
    // discourage spreading across bins.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let large_item = item_size as f64 / bin_capacity as f64;
        // Prefer new bin for large items early on, or when no tight option exists
        let new_bin_bonus = 10.0 + 40.0 * large_item - 30.0 * progress;
        score += new_bin_bonus;
        // If the next item is small, a fresh bin is wasteful
        if next_item_size > 0 && next_item_size < 20 {
            score += 15.0;
        }
        // If the item fills more than half the bin, fresh bin is good
        if item_size * 2 >= bin_capacity {
            score -= 25.0;
        }
    }

    // Mild preference for consolidating into fewer bins when many are open.
    if open_bins_count > 4 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of the fit: reward small post_residual nonlinearly.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Perfect / near-perfect fits get a strong bonus.
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual < 10 {
        score -= 120.0;
    } else if post_residual <= 20 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits in the post-residual, reward this bin.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let chain_tight = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 30.0 + 25.0 * chain_tight;
        } else {
            // Next item won't fit here: penalize leaving a gap the next item can't use.
            let waste = (post_residual as f64) / (next_item_size as f64);
            score += 10.0 * waste.min(4.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    } else if fitting_bins_count > 1 {
        // When many bins fit, prefer the one with the smallest residual (best fit).
        score += 3.0 * (fitting_bins_count as f64).ln();
    }

    // Global state coupling: penalize using bins whose residual is far from mean
    // (prefer balanced residuals), scaled by number of open bins.
    if open_bins_count > 1 {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.35 * dev / (open_bins_count as f64).sqrt();
    }

    // Time horizon: early in the stream, keep bins flexible (penalize very low residual);
    // late in the stream, prioritize tight packing aggressively.
    let flexibility = (post_residual as f64 / bin_capacity as f64).powf(0.5);
    score += 25.0 * (1.0 - t) * flexibility;
    score -= 30.0 * t * tight;

    // New-bin candidate handling: opening a new bin wastes all open residuals.
    // It is only attractive when no open bin fits well (high post_residual penalty)
    // or few bins are open.
    if bin_residual == bin_capacity {
        let base = 55.0 + 20.0 * (open_bins_count as f64).ln().max(0.0);
        // If this item leaves a large hole in an open bin, new bin becomes competitive.
        let escape = (post_residual as f64 / bin_capacity as f64) * (1.0 - t);
        score = base - 60.0 * escape;
        // Never open a new bin when a near-perfect fit exists.
        if post_residual < 10 && bin_residual < bin_capacity { score += 500.0; }
    }

    // Mild stochastic-free tiebreak on residual to enforce best-fit ordering.
    score += 0.01 * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap; // normalized post residual

    // Base: penalize large leftover space mildly, but reward tight fits.
    let mut score = pr as f64;

    // Non-linear polynomial coupling of post_residual with stream progress:
    // later in the stream, tight fits (small post_residual) matter more.
    let tightness = 1.0 - x; // 1 = perfect fit
    let coupling = progress * (tightness * tightness - 0.5 * tightness * x);
    score -= 40.0 * coupling;

    // Penalize dead space that is too small to be useful (smooth quadratic well)
    let useless = (1.0 - x) * x; // peaks at x=0.5, vanishes at extremes
    score -= 25.0 * useless;

    // Lookahead: reward bins whose post_residual can host next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let fit_next = ((x - nx) / cap).max(0.0);
        score -= 30.0 * (1.0 - (fit_next * cap).min(1.0)) * (0.5 + progress);
        // heavy penalty if post_residual just barely misses next item
        let miss = (x - nx).max(0.0);
        score += 20.0 * (1.0 - miss * cap / 10.0).max(0.0) * (1.0 - progress);
    }

    // Last-chance bin: strong reward to use it rather than open a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0 * (1.0 + progress);
    }

    // New-bin candidate: penalize opening bins unless current fit is terrible
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 45.0 - 30.0 * progress;
        // allow new bin if item is huge relative to mean residual
        let ratio = item_size as f64 / mean_residual.max(1.0);
        score -= 40.0 * (ratio - 1.0).max(0.0).min(1.0);
    }

    // Mild congestion pressure: many open bins -> favor filling existing ones
    score += open_bins_count as f64 * (x * 2.0) * (1.0 - progress);

    // Mean-residual alignment: prefer bins near the mean residual
    score -= 10.0 * (-((pr - mean_residual) / cap).powi(2));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: integer division into capacity-fraction bands.
    let quarter = bin_capacity / 4;
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth; // 0..=8 harmonic class
    let next_class = if next_item_size == 0 { 9 } else { next_item_size / eighth };

    // Reward when next item's harmonic class matches the post-residual class band
    // (i.e., next item fills this bin's leftover into a coarse-aligned band).
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_class as i32 - next_class as i32).abs();
        score -= (8.0 - gap as f64) * 0.9; // aligned classes are highly desirable
        // Exact near-fill: next item almost consumes post_residual
        let slack = post_residual - next_item_size;
        if slack <= 2 {
            score -= 12.0;
        } else if slack <= eighth {
            score -= 5.0;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item cannot use this leftover: penalize leaving medium dead space
        if post_residual > 2 && post_residual < quarter {
            score += 6.0;
        }
    }

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 4 {
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when a decent fit exists among open bins
    if bin_residual == bin_capacity {
        score += 18.0 + mean_residual * 0.15;
        if fitting_bins_count >= 1 && post_residual >= quarter {
            score += 10.0;
        }
    }

    // Mild best-fit tiebreak scaled by stream progress
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (bin_residual as f64 / cap) * (1.0 + progress);

    // Tightness coupling: prefer bins whose residual is close to item size
    score -= (bin_residual - item_size) as f64 * 0.05;

    // Modulo structure: leftover congruent to common item sizes is reusable
    let m = post_residual % 10;
    if m <= 2 {
        score -= 2.0;
    } else if m >= 8 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer tight fits (small post_residual).
    score += post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for the
    // smallest plausible item (1..100 range, but realistically >0) are waste.
    // Penalize small-but-nonzero gaps super-linearly.
    let pr = post_residual as f64;
    if post_residual > 0 && post_residual < 10 {
        score += 25.0 * (10.0 - pr) / 10.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // If post_residual can still fit the next item, reward strongly.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward when next item leaves another tight fit.
        let post2 = post_residual - next_item_size as u32;
        if post2 < 10 && post2 > 0 {
            score -= 6.0;
        }
        if post2 == 0 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Dead space relative to the lookahead: penalize.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: an empty bin should only win when all
    // open fits are poor. Give it a moderate baseline score.
    if bin_residual == bin_capacity {
        score += 15.0;
        // Late in the stream, opening new bins is cheap-ish; early on prefer reuse.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Mild alignment with mean residual: prefer bins whose residual is below
    // average (more filled bins), keeping loose bins for future large items.
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 200.0;
    }
    // Next item fits with small slack (near-perfect lookahead)
    else if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 120.0 - slack * 0.8;
    }
    // Next item cannot fit: penalize proportionally to wasted potential
    else if next_item_size > 0 && post_residual < next_item_size {
        score += 30.0 + (next_item_size - post_residual) as f64 * 0.5;
    }

    // Reward tight fits now (low post_residual relative to capacity)
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * 40.0;

    // Penalize creating dead space below the minimum item size (1..100 unknown, assume ~10)
    let min_item = 10u32;
    if post_residual > 0 && post_residual < min_item {
        score += 150.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // Many fitting bins: prefer the one closest to mean residual alignment (balanced packing)
    if fitting_bins_count > 1 {
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.3;
    }

    // New-bin candidate: baseline moderate score; open new bin only when no open bin
    // offers a good (near-zero) residual fit.
    if bin_residual == bin_capacity {
        score = 60.0 + 0.25 * (open_bins_count as f64);
        if next_item_size > 0 && item_size as f64 + next_item_size as f64 <= bin_capacity as f64 {
            score -= 25.0; // fresh bin can host the lookahead pair cleanly
        }
        if fitting_bins_count == 1 {
            score += 200.0; // never open new bin when a last-chance bin exists
        }
    }

    // Slight early-stream preference for consolidation into existing bins
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square of residual waste penalized more strongly.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Exact fit is golden.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Very small dead space that nothing can use later (min item = 1):
    // residual 1..3 is nearly worthless; penalize leaving it.
    if post_residual > 0 && post_residual < 4 {
        score += 20.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 250.0;
    }
    // If next item cannot fit into post_residual but could fit into this bin
    // before placement, mild penalty (we burned the space).
    if next_item_size > post_residual && next_item_size > 0 && next_item_size <= bin_residual {
        score += 15.0;
    }
    // If next item fits comfortably in post residual, small bonus.
    if next_item_size > 0 && post_residual >= next_item_size + 10 {
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // existing residuals are all poor for the item.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins.
        score = (bin_capacity as f64) + 30.0 + 8.0 * (open_bins_count as f64);
        // If many bins fit the item, discourage opening a new one.
        if fitting_bins_count > 1 {
            score += 60.0 * (fitting_bins_count as f64 - 1.0);
        }
        // If only one bin fits and its residual is small, new bin becomes
        // attractive; emulate by reducing cost when mean residual is tight.
        if fitting_bins_count == 1 {
            score -= 80.0;
        }
        // Perfect-fit potential: item exactly fills a fresh bin.
        if item_size == bin_capacity {
            score -= 500.0;
        }
        // Early in the stream, allow more bins (better packing later).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 40.0 * (1.0 - progress);
    }

    // Global balance: prefer bins whose residual is close to the mean
    // (keeps packing balanced), unless it's a last-chance bin.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.3 * dev;

    // Prefer using bins with less residual overall (best-fit flavor), scaled
    // by stream progress.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.2 * (bin_residual as f64) * (0.5 + 0.5 * progress);

    // Prefer denser bin sets slightly as stream advances (consolidate).
    score -= 2.0 * progress * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress.
    // Squared/cubic terms: small residuals (tight fits) are rewarded, but the
    // reward deepens as the stream progresses (exploit tight fits later).
    let tightness = (1.0 - post_norm).clamp(0.0, 1.0);
    let poly = tightness * tightness * (1.0 + 2.0 * progress)
        + tightness.powi(3) * (0.5 + progress);
    score -= 12.0 * poly;

    // Penalize large dead space non-linearly, amplified late in the stream.
    score += post_norm * post_norm * (5.0 + 10.0 * progress) * cap * 0.1;

    // Reward bins whose residual matches the lookahead item smoothly (k=2 lookahead).
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * (1.0 - gap) * (1.0 - gap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // Smooth penalty if lookahead cannot fit in the leftover space.
        let miss = (next_item_size - post_residual) as f64 / cap;
        score += 6.0 * miss * (0.5 + progress);
    }

    // Last-chance bin: strong smooth reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + 2.0 * progress);
    }

    // New-bin candidate (bin_residual == bin_capacity): penalize so it is only
    // chosen when no open bin offers a decent fit; penalty relaxes slightly
    // with stream progress and when few bins fit the item.
    if bin_residual == bin_capacity {
        let relief = (fitting_bins_count as f64).recip().min(1.0);
        score += 15.0 * (1.0 - 0.3 * progress) * (1.0 - 0.5 * relief);
    }

    // Mild coupling to mean residual: prefer bins below the mean (concentrate filling).
    let dev = (mean_residual - bin_residual as f64) / cap;
    score += 3.0 * dev * (1.0 + progress);

    // Slight preference for fewer open bins, smoothed.
    score += 0.05 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: how "usable" is the leftover space?
    // Residuals that are multiples of common size classes (10, 20, 25, 50) are
    // more likely to be filled by future items -> reward them.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else {
        let mut harmony_bonus = 0.0;
        if pr % 10 == 0 { harmony_bonus += 12.0; }
        if pr % 20 == 0 { harmony_bonus += 8.0; }
        if pr % 25 == 0 { harmony_bonus += 8.0; }
        if pr % 50 == 0 { harmony_bonus += 10.0; }
        score -= harmony_bonus;

        // Dead-space penalty: small awkward leftovers (< 10) are nearly useless
        if pr < 10 {
            score += 25.0;
        } else if pr < 20 {
            score += 8.0;
        }

        // Lookahead: if next item fits exactly in the post-residual, strong reward
        if next_item_size > 0 {
            if next_item_size == pr {
                score -= 45.0;
            } else if next_item_size <= pr {
                // next item fits: leftover after that placement
                let pr2 = pr - next_item_size;
                if pr2 % 10 == 0 { score -= 10.0; }
                if pr2 < 10 { score += 6.0; }
            } else {
                // next item cannot use this bin's leftover
                score += 5.0;
            }
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Its raw score is post_residual = capacity - item_size, which is often
    // large; only allow opening a new bin when the current item is large
    // (poor fit elsewhere) or when all existing fits are bad.
    if bin_residual == bin_capacity {
        // neutralize the raw post_residual for the empty bin, then set a
        // moderate baseline that real bins can beat with good harmony.
        let base = 50.0;
        score = base + (post_residual as f64) * 0.25;

        // Opening a new bin is attractive for large items (>= half capacity)
        if item_size * 2 >= bin_capacity {
            score -= 20.0;
        }
        // Avoid hoarding bins early in the stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += open_bins_count as f64 * 3.0 * (1.0 - progress);
        // If many bins already fit the item, opening a new one is wasteful
        if fitting_bins_count > 2 {
            score += 15.0;
        }
    } else {
        // Real bins: slight preference for tighter existing bins
        // (smaller residual before placement = better fill density)
        score += (bin_residual as f64) * 0.05;

        // Encourage bins whose residual is far below the mean (they are the
        // "almost full" ones we want to finish off).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        }
    }

    // Progress-based mild exploration: late in the stream, prefer closing
    // bins tightly (perfect fits weigh more).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if pr == 0 {
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can never host a plausible
    // future item (small unusable gaps) are heavily penalized.
    // Treat gaps < 10 (or < next item if it's larger) as dead space.
    let min_useful = if next_item_size > 0 { next_item_size.min(80).max(10) } else { 10 };
    if post_residual < min_useful && post_residual > 0 {
        // Dead space: the smaller the gap, the more "wasted" it is.
        score += (min_useful - post_residual) as f64 * 6.0;
        // Absolute dead zones get an extra flat penalty.
        score += 15.0;
    }

    // Perfect-fit reward: leaving exactly zero residual is ideal.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Reward tight fits: post_residual close to 0 is good.
        score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly favor this placement (chained perfect fit).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Next item still fits: mild reward proportional to slack after next item.
        let after_next = post_residual - next_item_size;
        score -= 10.0 * (1.0 - after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        // Next item cannot use this residual: extra dead-space penalty.
        score += 20.0;
    }

    // Last-chance bin pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening new ones
    // and encourage consolidation into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open or late in stream.
        score += 20.0 + 8.0 * pressure + 15.0 * progress;
    } else {
        // Existing bin: reward slightly more when open_bins_count is high.
        score -= 3.0 * pressure;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already tight — using it is efficient consolidation.
    let residual_gap = mean_residual - bin_residual as f64;
    if residual_gap > 0.0 {
        score -= 2.0 * residual_gap.min(50.0);
    } else {
        // Bin is looser than average: mild penalty to prefer tighter bins.
        score += 1.0 * (-residual_gap).min(50.0);
    }

    // Small regularization against pathological scores.
    score += post_residual as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: massive reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: does the next item fit into the post residual?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item also fits here: reward proportional to tightness.
            score -= 40.0 + (next_item_size as f64) * 0.5;
        } else if post_residual > 0 {
            // Dead space that the next item cannot use: penalize small leftovers.
            let waste = post_residual as f64;
            score += 30.0 + (waste / 50.0) * 50.0;
        }
    } else {
        // Last item: prefer minimal leftover.
        score += (post_residual as f64) * 0.1;
    }

    // Relative to mean residual across open bins: bins with less residual
    // (tighter) are better targets; penalize dumping into very empty bins.
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (post residual would be small-but-unusable).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 120.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0;
        }
        // As stream progresses and open bins accumulate, discourage sprawl.
        score += (open_bins_count as f64) * 2.0;
        // Early stream: opening fresh bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 40.0;
    }

    // Slight preference for bins that are already fairly full.
    score += (bin_capacity as f64 - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let mut score = post;

    // Waste ratio: fraction of the bin that becomes dead space
    let waste_ratio = post / cap;
    score += 25.0 * waste_ratio * waste_ratio;

    // Perfect-fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Lookahead: penalize bins whose post-residual is too small OR too large for next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = post - nxt;
            // reward if next item fits snugly afterwards
            score -= 12.0 * (1.0 - slack / cap);
            if slack == 0.0 { score -= 20.0; }
        } else {
            // next item can't use this residual at all
            score += 0.35 * (nxt - post);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Many fitting bins: prefer the tightest (post_residual term already does this),
    // but add mild pressure proportional to congestion
    score += 0.5 * open_bins_count as f64;

    // Mean residual coupling: penalize placing into bins far from the mean residual
    // (keeps residuals homogeneous, improving future packing)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Time horizon: early in the stream, be more willing to open new bins
    // (many items remain); late in the stream, squeeze into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost of opening a bin, discounted early, raised late
        let mut new_bin_score = cap - item + 10.0;
        new_bin_score -= 30.0 * (1.0 - progress);
        new_bin_score += 40.0 * progress;
        // if item is large relative to capacity, opening fresh is fine
        new_bin_score -= 10.0 * (item / cap);
        // if few bins fit the item, opening may be preferable
        if fitting_bins_count <= 1 { new_bin_score -= 15.0; }
        // avoid opening when many open bins already have large residuals
        new_bin_score += 0.1 * mean_residual;
        return new_bin_score;
    }

    // Late-stream squeeze bonus
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 - progress) + norm_pr * progress * progress;
    score += 8.0 * poly;

    // Reward tight fits (small post_residual), scaled by progress
    let tightness = 1.0 - norm_pr;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Lookahead coupling: reward if next item fits the post residual
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0 * (next_item_size as f64 / cap) * (0.5 + 0.5 * progress);
    }

    // Penalize dead space relative to mean residual
    if pr > mean_residual {
        score += 0.5 * (pr - mean_residual);
    }

    // Last-chance bin gets a bonus to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 3.0;
    }

    // Slight preference for reusing bins vs opening new ones as stream progresses
    if bin_residual != bin_capacity {
        score -= 1.0 + 2.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo capacity fractions
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = post_residual % (bin_capacity / 4); // harmonic subclass 0..24

    // Perfect fit harmonic classes are gold
    if class == 0 {
        score -= 12.0;
    } else if class <= 5 {
        score -= 6.0;
    } else if class >= (bin_capacity / 4) - 5 {
        score -= 3.0;
    } else {
        score += 4.0; // mid-class dead space risk
    }

    // Reward tight fills relative to capacity
    let fill = 1.0 - post / cap;
    score -= 8.0 * fill * fill;

    // Lookahead coupling: does post_residual harmonically fit next item?
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            let gap = post - nx;
            if (gap as u32) % (bin_capacity / 4) == 0 {
                score -= 10.0; // next item lands on harmonic boundary
            } else if gap < 10.0 {
                score -= 7.0; // near-perfect chain
            } else {
                score += 2.0;
            }
        } else {
            score += 5.0; // next item cannot use leftover
        }
    } else {
        score += post; // last item: strongly prefer minimal leftover
    }

    // Last-chance bin before opening a new one
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: only attractive if no good fit exists / many open bins
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64 / (mean_residual / cap + 1.0);
        score = cap - 4.0 * pressure + 0.3 * (item_size as f64);
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
    }

    // Stream progression: consolidate more aggressively later
    let t = step_index as f64 / total_items.max(1) as f64;
    score -= 6.0 * t * (1.0 - fill);

    // Penalize waste relative to mean residual across open bins
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are nearly unusable
    // (items are >= 1, but tiny gaps rarely match future demand).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (1.0 - post_residual as f64 / 10.0);
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 100.0;
    }

    // Reward tight fits relative to residual (waste fraction).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Lookahead: if the next item fits exactly in the post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 80.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 10.0; // next item won't fit here; dead end likely
        }
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Open-bin pressure: discourage scattering across many bins when
    // mean residual is already low elsewhere.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (open_bins_count as f64).sqrt() * (2.0 + 3.0 * (1.0 - progress));

    // New-bin candidate handling: only attractive when nothing fits well.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin loses to any decent fit.
        score += 25.0;
        // But if existing bins would leave tiny dead space, opening
        // a fresh bin becomes preferable.
        if post_residual > 0 && post_residual < 10 {
            score -= 70.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Late in the stream, prefer consolidating into open bins.
        score += 20.0 * progress;
    }

    // Mild bonus for using bins with residual close to mean (balance).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score -= 5.0 / (1.0 + dev);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
