    }

    // Open-bin pressure: discourage opening new bins when many are open
    if bin_residual == bin_capacity {
        score += 18.0 + 2.5 * open_bins_count as f64;
    } else {
        score -= 1.5 * open_bins_count as f64;
    }

    // Favor bins below mean residual (less-full bins absorb awkward items)
    score += 0.15 * (post_residual as f64 - mean_residual);

    // Late-stream consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward relative to capacity
    score -= (1.0 - post_residual as f64 / bin_capacity as f64) * 30.0;

    // 2-step lookahead: reward bins whose post_residual matches the next item well
    if next_item_size > 0 && post_residual >= next_item_size {
        let lookahead_waste = post_residual - next_item_size;
        score -= (1.0 - lookahead_waste as f64 / bin_capacity as f64) * 40.0;
    } else if next_item_size > 0 {
        // next item cannot follow into this bin: penalize proportionally
        score += (next_item_size as f64 - post_residual as f64) * 0.8;
    }

    // Compare post_residual against mean residual: prefer leaving residuals near mean
    let dev = (post_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // Penalize opening a new bin when good open bins exist
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items as f64;
        score += 25.0 + 20.0 * (1.0 - progress);
        if next_item_size > 0 && bin_residual >= next_item_size {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor minimal waste, superlinear in waste.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac * (bin_capacity as f64);

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead: reward if next item fits into post_residual, penalize otherwise.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
        } else {
            score += 3.0;
            // Dead space: post_residual too small for anything likely to come.
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize opening a new bin when open bins exist that fit reasonably well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 12.0;
        if fitting_bins_count > 0 {
            // If some existing bin gives near-perfect fit, discourage new bin more.
            let best_possible = (bin_capacity - item_size) as f64;
            if post_residual as f64 > best_possible * 0.5 {
                score += 10.0;
            }
        }
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 8.0 * (1.0 - progress);
    } else {
        // Favor filling bins with larger residuals to consolidate space.
        score -= 0.05 * bin_residual as f64;
    }

    // Global pressure: many open bins with high mean residual -> prefer reusing bins.
    if mean_residual > 0.0 {
        score += 0.02 * mean_residual * open_bins_count as f64 * if is_new_bin { 1.0 } else { -0.5 };
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    // non-linear polynomial coupling of post_residual with stream progress
    let norm_pr = pr / cap;
    score += progress * (norm_pr * norm_pr) * 20.0;
    score -= (1.0 - progress) * (norm_pr * (1.0 - norm_pr)) * 15.0;
    // tight fit reward, smooth
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * 10.0;
    // penalize residual that is small but nonzero (dead space)
    if pr > 0.0 && pr < 10.0 {
        score += 5.0;
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 8.0;
    }
    // lookahead: reward leaving space compatible with next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            score -= 4.0 * (1.0 - (pr - nx) / cap);
        } else {
            score += 3.0;
        }
    }
    // prefer filling bins when many are open, smooth in open count
    let oc = open_bins_count as f64;
    score -= (oc / (oc + 5.0)) * (cap - pr) / cap * 6.0;
    // deviation from mean residual, smooth quadratic
    score += ((pr - mean_residual) / cap) * ((pr - mean_residual) / cap) * 4.0;
    // new bin candidate handling
    if bin_residual == bin_capacity {
        score += 12.0 - progress * 6.0;
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: how well the leftover decomposes into
    // likely future item sizes (integer division into capacity fractions).
    let post = post_residual as u32;
    if post > 0 {
        // Reward residuals that are "clean" fractions of capacity (divisible
        // by 25, 20, 10) — these align with common item-size classes.
        let mut bonus = 0.0;
        if post % 25 == 0 { bonus += 6.0; }
        else if post % 20 == 0 { bonus += 4.0; }
        else if post % 10 == 0 { bonus += 2.0; }
        score -= bonus;

        // Penalize tiny dead space (unusable slivers) quadratically.
        if post < 10 {
            score += (10 - post) as f64 * (10 - post) as f64 * 0.5;
        }

        // Reward residuals that exactly fit the lookahead item (perfect pair).
        if next_item_size > 0 && next_item_size == post {
            score -= 15.0;
        } else if next_item_size > 0 && next_item_size <= post {
            // Reward when lookahead fits within a coarse harmonic band.
            let band = post / 20; // integer division threshold
            let next_band = next_item_size / 20;
            if band == next_band { score -= 4.0; }
            score -= 1.0;
        } else if next_item_size > post && next_item_size > 0 {
            // Lookahead cannot use this residual: penalize proportionally.
            score += (next_item_size - post) as f64 * 0.3;
        }
    }

    // Perfect fit reward: residual exactly consumed.
    if post == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: only prefer a fresh bin when no open bin gives a
    // tight fit (post_residual large) and many bins are open.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let tight_threshold = 0.25 * cap;
        if post_residual as f64 > tight_threshold && open_bins_count > 2 {
            score -= 3.0; // mild encouragement to open fresh bins early in fill
        } else {
            score += 8.0 + 10.0 * (1.0 - progress); // discourage wasting bins
        }
    }

    // Mild preference toward bins below mean residual (consolidating fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps more than proportionally.
    // A residual below the minimum item size (1) is impossible; treat tiny residuals (< 10)
    // as "dead" and apply a super-linear penalty so near-full bins are strongly favored.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        score -= 40.0 * (dead_threshold - post_residual as f64);
    } else {
        // mild convexity: prefer smaller residuals generally
        score += 0.05 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;
    }

    // Reward tight fits: exact or near-exact fills get a strong bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin (avoid fragmentation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage opening yet another bin
    // and encourage consolidating into existing ones.
    let open_pressure = open_bins_count as f64 / (mean_residual.max(1.0));
    score += open_pressure * 2.0;

    // New-bin candidate handling: a brand-new empty bin should only win when the
    // current bin would leave a large, awkward residual. Penalize the empty-bin
    // candidate by its wasted capacity so it loses unless fits elsewhere are terrible.
    if bin_residual == bin_capacity {
        score += 0.5 * bin_capacity as f64;
        // If the next item is large, a fresh bin may still be attractive; soften slightly.
        if next_item_size > item_size {
            score -= 10.0;
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as i64 - next_item_size as i64) == 0 {
        score -= 50.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }

    // Progression: late in the stream, tighten packing (favor filling existing bins harder).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 1000.0 + item_size as f64;
    }

    // Near-match lookahead bonus (small slack after next item would fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 200.0 * (-slack / 10.0).exp();
    }

    // Penalize tiny dead space (unusable fragments) unless it's an exact match.
    if post_residual > 0 && post_residual < 10 {
        score += 50.0;
    }

    // Reward tightening: post_residual relative to mean residual of open bins.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // New-bin candidate: only attractive when many bins fit the item poorly
    // or residual spread suggests fragmentation; otherwise penalize opening.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_bonus = 40.0 * (open_bins_count as f64).ln() * (1.0 - progress);
        score += 500.0 - new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating dead space that no plausible future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chaining
        } else if next_item_size <= post_residual {
            let slack_after = post_residual - next_item_size;
            score -= 8.0 * (1.0 - slack_after as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's remainder; mild penalty for wasted space
            score += 3.0 * (post_residual as f64) / (bin_capacity as f64);
        }
    } else {
        // last item: prefer filling bins as full as possible
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer consolidating into bins below mean residual
    // (keeps residual distribution tight, easier future packing).
    if open_bins_count > 1 {
        let dev = (bin_residual as f64) - mean_residual;
        score += 0.05 * dev;
    }

    // Time horizon: early in stream, opening new bins is cheap (long future to fill them);
    // late in stream, avoid opening new bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: base reluctance grows with progress and open-bin count.
        score += 10.0 + 25.0 * progress + 0.8 * open_bins_count as f64;
        // But if the item is huge relative to capacity, a fresh bin is attractive
        // (keeps large remainder usable elsewhere avoided).
        score -= 0.1 * item_size as f64;
    } else {
        // Late stream: reusing existing bins is increasingly valuable.
        score -= 8.0 * progress;
    }

    // Mild penalty for very large leftover relative to typical item sizes
    // (residual in (0,10) already handled; penalize mid-range awkward remainders less).
    if post_residual >= 10 && post_residual < 20 {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let pr_norm = pr / cap;
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let coupling = pr_norm * pr_norm * (0.5 + 1.5 * p2) + pr_norm * (1.0 - p3);
    score += 8.0 * coupling;

    // Reward tight fits (small post_residual) more strongly later in the stream.
    score -= 6.0 * (1.0 - pr_norm) * (1.0 - pr_norm) * (0.3 + 0.7 * p2);

    // Penalize wasting the last-chance bin.
    if fitting_bins_count == 1 {
        score -= 5.0 * (1.0 - pr_norm);
    }

    // Lookahead: reward leaving space compatible with next item.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let match_term = 1.0 - ((pr - ni).abs() / cap);
        score -= 4.0 * match_term * match_term;
        if ni > pr {
            score += 2.0 * pr_norm; // dead space if next item can't fit anyway
        }
    }

    // Mild penalty for opening new bins late.
    if bin_residual == bin_capacity {
        score += 3.0 * (0.5 + progress);
    }

    // Mean residual spread term: prefer bins far from the mean (consolidation).
    score += 1.5 * ((pr - mean_residual) / cap).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space that is a multiple of small
    // "harmonic" units (10, 20, 25, 50) is reusable by future items -> reward.
    let pr = post_residual;
    let harmonic_bonus: f64 = if pr == 0 {
        60.0 // perfect fill: heavily reward
    } else if pr % 50 == 0 {
        25.0
    } else if pr % 25 == 0 {
        18.0
    } else if pr % 20 == 0 {
        15.0
    } else if pr % 10 == 0 {
        10.0
    } else {
        0.0
    };
    score -= harmonic_bonus;

    // Penalize small awkward dead space (1..=9): hard to fill, likely waste.
    if pr > 0 && pr < 10 {
        score += 12.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this is a chain placement -> strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 35.0;
        } else if next_item_size <= pr {
            // next item fits but leaves another residual: scale by how well
            // the resulting residual is harmonic.
            let pr2 = pr - next_item_size;
            let chain_fit = if pr2 == 0 {
                22.0
            } else if pr2 % 10 == 0 || pr2 % 25 == 0 {
                12.0
            } else {
                4.0
            };
            score -= chain_fit;
        } else {
            // next item will not fit here: mild penalty proportional to gap
            score += ((next_item_size - pr) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using
    // it over opening a new bin (unless post_residual is tiny dead space).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
        if pr < 10 && pr > 0 {
            score += 8.0; // still avoid creating useless slivers
        }
    }

    // New-bin candidate handling: empty bin starts with high base cost so we
    // only open a new bin when existing fits are genuinely bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // If stream is late, opening bins is cheaper (bins carry over less).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 10.0;
        // If mean residual across open bins is small, reusing is hopeless;
        // opening a new bin becomes more attractive.
        score -= (mean_residual * 0.4).min(25.0);
    }

    // Tie-break: prefer bins with larger residual consumed relative to capacity
    // (denser bins first) -> mild reward for high fill ratio.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= fill * 5.0;

    // Integer-division threshold on post_residual: residual >= half capacity
    // keeps the bin very flexible; reward moderately.
    if pr >= bin_capacity / 2 {
        score -= 6.0;
    }

    // Open-bin count pressure: many open bins -> favor consolidation into
    // existing bins (penalize new-bin spread implicitly via density reward).
    if open_bins_count > 4 {
        score += (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    let min_item = 1u32;
    if post_residual < min_item {
        // Perfect fit — big reward.
        score -= 40.0;
    } else if post_residual < 10 {
        // Tiny dead space: nearly unusable for any item (min size 10 in classic
        // setting, but interface allows 1..100 — still, small gaps are risky).
        score += (10.0 - post_residual as f64) * 6.0;
    }

    // Non-linear penalty on post_residual relative to bin capacity.
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    score += 3.0 * (pr / cap) * (pr / cap) * 10.0;

    // Reward tight fits: gap between residual and item size small.
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score -= 20.0 * (1.0 - tightness).max(0.0) * (1.0 - tightness).max(0.0);

    // Open-bin pressure: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only allow opening a new bin if this bin's fit is bad.
    if bin_residual == bin_capacity {
        // Neutral-ish baseline; opening new bin keeps large residual for future.
        score = 55.0 + 0.5 * mean_residual;
        // If lookahead fits well into the fresh residual, mild bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 5.0;
        }
    }

    // Lookahead synergy: if next item fits the post-residual, reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 8.0;
    } else if next_item_size > post_residual && post_residual > 0 {
        // Dead space relative to what's coming next.
        score += 4.0;
    }

    // Late in stream: consolidate, avoid opening bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Aggressive 2-step lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size < post_residual {
            // next item fits, penalize proportional to leftover after next placement
            let post2 = post_residual - next_item_size;
            score -= 20.0 - post2 as f64 * 0.4;
        } else {
            // next item won't fit here; mild penalty scaled by overshoot
            score += (next_item_size - post_residual) as f64 * 0.25;
        }
    }

    // Compare residual against mean residual of open bins: prefer tighter-than-average bins
    score += (post_residual as f64 - mean_residual) * 0.35;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when reasonable fits exist (new-bin candidate gets a base handicap)
    if bin_residual == bin_capacity {
        score += 15.0;
        // But if the item is large and would leave a big residual elsewhere, new bin is fine
        if item_size >= bin_capacity * 3 / 4 {
            score -= 20.0;
        }
        // Late in the stream, opening fresh bins is less costly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
    }

    // Many open bins: encourage consolidation into tighter bins
    if open_bins_count > 4 {
        score += (post_residual as f64 / bin_capacity as f64) * 8.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: quadratic penalty on large post_residual (dead space).
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * frac * frac;

    // Lookahead: strongly reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0 + 8.0 * (next_item_size as f64 / 100.0);
    } else if next_item_size > 0 {
        // Penalize leaving a gap the next item can't use, scaled by gap size.
        let gap = post_residual as f64;
        score += 0.05 * gap;
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin (unless post_residual is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item fits poorly everywhere else. Penalize new bins when many bins fit.
    if bin_residual == bin_capacity {
        let open_penalty = 8.0 + 2.0 * (open_bins_count as f64).ln().max(0.0);
        let fit_pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).min(6.0)
        } else {
            0.0
        };
        score += open_penalty + 3.0 * fit_pressure;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Global state coupling: if mean residual across open bins is high,
    // encourage filling bins rather than spreading items.
    if bin_residual != bin_capacity {
        score -= 0.03 * mean_residual;
    }

    // Slight preference for bins with residual close to item_size (perfect fit).
    if bin_residual >= item_size {
        let tightness = (bin_residual - item_size) as f64;
        score += 0.02 * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let x = pr / cap; // normalized post residual

    // Base: post residual, scaled by smooth progress coupling
    let mut score = pr * (1.0 + 0.6 * t * (1.0 - t) * 4.0);

    // Non-linear penalty for awkward residuals: quadratic bowl around mid-range waste
    score += cap * 0.35 * (x * (1.0 - x)) * (1.0 + 2.0 * t * t);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= cap * 0.8 * (1.0 - x).powi(3) * (0.5 + t);

    // Last-chance bonus: only one fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (1.0 - x);
    }

    // Lookahead: reward if next item fits in post residual, penalize otherwise
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 10.0 * (1.0 - nx / cap);
        } else {
            score += 6.0 * (nx - pr) / cap;
        }
    }

    // New-bin candidate handling: make fresh bin mildly attractive only for large items
    if bin_residual == bin_capacity {
        score = cap - item_size as f64 * 0.8 + 15.0 * t;
    }

    // Mild coupling with mean residual state
    score += 0.05 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover into residue classes mod 10
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.15; // prefer leftovers that are multiples of 10 (cleaner classes)

    // Small dead space is bad: penalize tiny nonzero leftovers more
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 2.0;
    }

    // Exact fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // Harmonic fraction of fill: how full the bin becomes
    let fill = (bin_capacity - post_residual) as f64 / cap;
    score -= fill * fill * 10.0; // superlinear reward for high fill

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Lookahead coupling: does the leftover harmonically fit next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // reward if post_residual is a good class match for next item
            let diff = post_residual - next_item_size;
            score -= 8.0;
            score += (diff % 10) as f64 * 0.2;
            if diff == 0 { score -= 10.0; }
        } else {
            // leftover too small for next item: penalize proportionally
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
    }

    // Late in stream: tighten packing, avoid opening new bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= progress * 6.0;
    }

    // New-bin candidate: penalize unless current bins are fragmented
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual - post_residual as f64).abs();
        score += 20.0 - fragmentation * 0.5;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open new bin
        }
        if next_item_size > 0 && next_item_size > post_residual {
            score += 10.0; // big item coming, keep fresh bin? mild penalty adjust
        }
    }

    // Mean residual alignment: prefer bins whose residual is near the mean (balanced usage)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Integer-division threshold on post_residual: quantized bonuses
    let q = post_residual / 25; // quarter classes
    match q {
        0 => score -= 3.0,   // nearly full bin
        1 => score += 1.0,
        2 => score += 2.0,
        _ => score += 0.0,
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless fit is good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (0.3 + 0.4 * progress);

    // Prefer bins whose residual is close to the item (tight fit).
    score += (bin_residual as f64 - item_size as f64).abs() * 0.5;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0;
    }

    // Slight preference for bins with residual below mean (consolidate small gaps).
    score += (mean_residual - bin_residual as f64) * 0.2;

    // New-bin candidate: baseline cost of opening a bin, plus pressure against
    // opening when a decent fit exists elsewhere.
    if bin_residual == bin_capacity {
        score += 20.0 + mean_residual * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: perfect match with next item is ideal.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 / (1.0 + diff);           // reward tight match for next item
        if post_residual == next_item_size {
            score -= 40.0;                       // exact chain bonus
        }
        // penalize leaving residuals too small for the next item (dead space)
        if post_residual < next_item_size && post_residual > 0 {
            score += 0.5 * (next_item_size - post_residual) as f64;
        }
    } else {
        // last item: prefer tightest fit
        score -= 30.0;
    }

    // Last chance: only bin that fits -> strongly favor using it over new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 100.0;
    }

    // New-bin candidate: penalize opening a new bin, more when open bins fit well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 80.0 + 40.0 * progress;
        if fitting_bins_count > 0 {
            score += 30.0;
        }
        // small lookahead softening: opening a new bin is fine if next item is huge
        if next_item_size >= item_size {
            score -= 20.0;
        }
    }

    // Prefer bins below mean residual (fill emptier bins less, keep tight ones tight)
    score += 0.3 * ((post_residual as f64) - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer smallest post residual, with a slight non-linear bonus
    // for very tight fits (post_residual close to 0).
    let pr = post_residual as f64;
    score += 0.35 * (pr / bin_capacity as f64).sqrt() * pr;

    // Reward bins that are already well-filled (small residual before placement).
    let fill_ratio = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 4.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item could fit into the post residual, reward this bin;
    // if the next item is larger than post residual but would fit elsewhere, mild penalty.
    if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            score -= 3.0;
        } else if (next_item_size as u32) > post_residual && post_residual > 0 {
            score += 0.05 * (next_item_size as f64 - pr);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Global state: penalize spreading across many open bins when mean residual is high.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 0.02 * open_bins_count as f64 * (1.0 - t);

    // Penalize creating dead space relative to the mean residual of open bins.
    if pr > mean_residual {
        score += 0.08 * (pr - mean_residual);
    } else {
        score -= 0.04 * (mean_residual - pr);
    }

    // New-bin candidate handling: opening a new bin is only attractive when the item
    // is large relative to capacity or existing residuals are all small.
    if bin_residual == bin_capacity {
        let scarcity = (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let large_item = item_size as f64 / bin_capacity as f64;
        let mut open_cost = 18.0;
        // If no open bin fits, opening is cheap (fitting_bins_count counts open bins only).
        if fitting_bins_count == 0 {
            open_cost = 2.0;
        } else if fitting_bins_count == 1 {
            // Last chance exists: opening should be expensive unless item is huge.
            open_cost += 10.0 * (1.0 - large_item);
        } else {
            open_cost += 6.0 * scarcity + 8.0 * (1.0 - large_item);
        }
        // Late in the stream, consolidate rather than open.
        open_cost += 6.0 * t;
        score += open_cost;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let x = pr / cap; // normalized post residual

    // Base: prefer small post residual, with non-linear polynomial shaping
    let mut score = pr * (1.0 + 0.8 * x * x);

    // Smooth stream-progress coupling: late in stream, penalize leftover space more
    score += 30.0 * progress * x * (1.0 - x);

    // Lookahead coupling: reward residual that can fit next item, penalize near-miss
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let fits = if pr >= nxt { 1.0 } else { 0.0 };
        score -= 12.0 * fits * (1.0 - (pr - nxt) / cap).max(0.0);
        score += 8.0 * (1.0 - fits) * (nxt / cap);
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize bins far below mean residual (fragmentation pressure)
    score += 0.15 * (mean_residual - pr).max(0.0);

    // Mild pressure against spreading across many open bins
    score += 0.5 * open_bins_count as f64 * x;

    // New-bin candidate: only attractive when current bins are poor fits
    if bin_residual == bin_capacity {
        score = pr + 40.0 - 20.0 * progress - 10.0 * (1.0 - x);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the residual after placement (integer division buckets)
    let residual_class = post_residual / 10;
    // Dead-space penalty: residuals that are too small to be useful (cannot fit
    // the smallest plausible item, ~10) are heavily penalized.
    if post_residual < 10 {
        score += 40.0;
    } else {
        // Reward residuals that are "harmonic" multiples of common item sizes
        let harmonic_bonus = match post_residual % 10 {
            0 => 6.0,
            5 => 2.0,
            _ => 0.0,
        };
        score -= harmonic_bonus;
        // Non-linear waste curve: mid-range residuals are the most wasteful
        let frac = post_residual as f64 / cap;
        score += 18.0 * frac * (1.0 - frac) * 4.0 * 0.5;
    }

    // Lookahead: strongly reward if next item fits the post-residual exactly or well
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 12.0 - (slack as f64).min(12.0);
            if post_residual == next_item_size {
                score -= 10.0; // perfect chaining
            }
        } else {
            score += 6.0; // next item won't fit here: mild penalty
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tight fits
        let tightness = 1.0 - (post_residual as f64 / cap);
        score -= 8.0 * tightness * tightness;
    }

    // New-bin candidate handling: only attractive when the stream is young,
    // few bins are open, or all open bins are nearly full (high mean fill).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mean_fill = 1.0 - (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = open_bins_count as f64 / 20.0;
        let new_bin_bonus = 25.0 * (1.0 - progress) + 30.0 * mean_fill - pressure * 5.0;
        // Harmonic check on item size: items in "big" classes pair well with fresh bins
        let big_item = if item_size % 10 == 0 && item_size >= 50 { 8.0 } else { 0.0 };
        score = 60.0 - new_bin_bonus - big_item;
        if post_residual < 10 {
            score += 40.0;
        }
    }

    // Slight tie-breaking preference for more-filled bins
    score += (bin_residual as f64 / cap) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize small unusable dead space heavily (nonlinear).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (exact fill especially).
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward when post_residual can still fit the lookahead item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Prefer bins with residuals below mean (consolidate large gaps).
    if (bin_residual as f64) > mean_residual {
        score += 3.0;
    } else {
        score -= 2.0;
    }

    // Late in stream: be more conservative with new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-exact fits (small dead space is exponentially better).
    if post_residual == 0 {
        score -= 200.0;
    } else {
        let pr = post_residual as f64;
        score -= 60.0 * (-pr / 20.0).exp();
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs();
        if diff == 0 {
            score -= 90.0;
        } else {
            score -= 45.0 * (-(diff as f64) / 15.0).exp();
        }
        // Penalize post_residual that is too small to ever be useful (dead space).
        if post_residual < 10 && post_residual > 0 {
            score += 25.0;
        }
    } else {
        // Last item: strongly prefer filling a bin completely.
        score -= 120.0;
    }

    // Relative-to-mean coupling: prefer bins with residual close to mean (balanced),
    // but penalize using a bin far above mean when mean is large (waste elsewhere).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate handling: only attractive when current item is small
    // and open bins are crowded.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let crowded = (open_bins_count as f64).ln().max(1.0);
        let small_item_bonus = (100 - item_size) as f64;
        score = 100.0 + crowded * 5.0 - small_item_bonus * 0.4 - 30.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 20.0; // fresh bin can host a pair
        }
    }

    // Mild penalty for spreading across many bins when mean residual is high.
    score += 0.05 * mean_residual;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual)
    let tight = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 3.0 * tight * tight;

    // Penalize dead space: post_residual too small to hold any plausible item
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post-residual fits the next item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 4.0 * (1.0 - gap / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual > 0 {
        // post residual cannot host next item -> mild penalty scaled by wasted potential
        score += 0.5 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    } else if fitting_bins_count > 1 {
        // many alternatives: prefer bins that keep flexibility
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: penalize opening a new bin unless the fit is poor
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_ratio = item_size as f64 / bin_capacity as f64;
        if fit_ratio > 0.5 {
            // large items fill a fresh bin well
            score -= 2.0 * fit_ratio;
        } else {
            // small items: only open a new bin if nothing else fits decently
            score += 30.0 * (1.0 - fit_ratio);
        }
        // fewer open bins -> cheaper to open a new one
        score -= (open_bins_count as f64) * 0.3;
    }

    // Global state coupling: if mean residual is high, prefer consuming existing space
    score -= 0.5 * mean_residual / bin_capacity as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Time horizon: early in stream, be more liberal with opening bins (long future); late, conserve
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if is_new_bin {
        score += 10.0 * progress;
    } else {
        score -= 2.0 * progress * tight;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;

    // Base: prefer tight fits (low post_residual), slightly sub-linear.
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth penalty for dead space relative to capacity, growing with stream progress.
    let waste = pr / cap;
    score += 12.0 * waste * waste * (0.4 + 0.6 * progress);

    // Lookahead coupling: reward bins whose post_residual is close to next item size.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (pr - nxt).abs();
        score -= 6.0 * (1.0 - gap / cap).max(0.0) * (0.5 + 0.5 * progress);
        // Penalize post_residual that is uselessly small (dead space below min item).
        if pr < nxt {
            score += 4.0 * (nxt - pr) / cap * (1.0 + progress);
        }
    }

    // Last chance: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0 + 6.0 * progress;
    }

    // New-bin candidate handling: neutral-ish baseline so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score = cap * 0.55 + 10.0 * (1.0 - progress) - 0.25 * mean_residual;
    }

    // Mild diversification pressure as many bins accumulate.
    score += (open_bins_count as f64).sqrt() * 0.15 * (pr / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: dead space quality by modulo classes
    let pr = post_residual;
    let cap = bin_capacity as f64;

    // Perfect-fit bonus
    if pr == 0 {
        score -= 500.0;
    }

    // Harmonic classes: residuals that are multiples of common item sizes (10,20,25,50)
    // are more reusable; reward them.
    let harmonic_bonus = |r: u32| -> f64 {
        let mut b = 0.0;
        for &m in &[10u32, 20, 25, 50] {
            if r % m == 0 && r > 0 {
                b += 8.0;
            }
        }
        b
    };
    score -= harmonic_bonus(pr);

    // Penalize residuals in awkward classes (e.g., 1..=9 slivers)
    if pr > 0 && pr < 10 {
        score += 60.0;
    }

    // Fraction-of-capacity coupling: prefer filling bins to high fraction
    let fill_frac = (bin_capacity - pr) as f64 / cap;
    score -= 30.0 * fill_frac * fill_frac;

    // Lookahead: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 && next_item_size <= pr {
        score -= 40.0;
        if pr % next_item_size == 0 {
            score -= 20.0;
        }
    } else if next_item_size > 0 && next_item_size > pr {
        score += 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are nearly full
    if bin_residual == bin_capacity {
        score += 25.0;
        if mean_residual < 20.0 && fitting_bins_count > 0 {
            score -= 35.0; // existing bins are cramped; new bin OK
        }
        // fewer open bins relative to progress: prefer reusing
        let progress = step_index as f64 / total_items.max(1) as f64;
        if open_bins_count as f64 > 3.0 + 10.0 * progress {
            score += 20.0;
        }
    }

    // Mild penalty for tight fits that leave tiny unusable gaps
    if pr > 0 && pr < item_size / 2 {
        score += 10.0;
    }

    // Mean residual coupling: prefer bins deviating favorably from mean
    score -= 0.1 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space avoidance: residuals that are too small for the smallest
    // plausible future item are "unusable" and should be heavily penalized.
    let min_item = 1u32;
    if post_residual < min_item {
        score += 1000.0; // perfect fill: ideal, but keep ordering sane
    } else if post_residual > 0 && post_residual < 10 {
        // small dead gap: hard to reuse -> strong penalty
        score += 60.0 * (1.0 - (post_residual as f64) / 10.0);
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit bonus
    }

    // Reward tight fits: fraction of bin used by this placement.
    let tightness = item_size as f64 / bin_capacity as f64;
    score -= 25.0 * tightness;

    // If the next item fits exactly into the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0 - 2.5 * slack; // near-exact lookahead match
        } else {
            score -= 5.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 {
        // next item cannot use this residual -> dead space likely
        score += 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // Open-bin pressure: discourage spreading across many open bins when
    // residual is still large and useful.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if post_residual >= 20 {
        score -= 3.0 * pressure;
    } else {
        score += 2.0 * pressure;
    }

    // Mean residual coupling: if this bin's residual is far below mean, it is
    // already "used up"; placing here keeps clean bins available.
    let dev = mean_residual - post_residual as f64;
    score += 0.15 * dev;

    // New-bin candidate: reserve it for cases where no open bin offers a good
    // fit (post residual too small or bin_residual barely fits).
    if bin_residual == bin_capacity {
        let poor_fit_elsewhere = post_residual >= 0 && fitting_bins_count >= 1
            && (post_residual < 10 || bin_residual - item_size < 10);
        if poor_fit_elsewhere {
            score -= 20.0; // opening fresh bin is fine
        } else {
            score += 55.0; // prefer existing bins with decent fit
        }
    }

    // Slight stream-position drift: early on, be a bit pickier about dead space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next item.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Perfect chain: next item fills bin exactly.
            if next_item_size == post_residual {
                score -= 40.0;
            } else {
                // Reward closeness of next item to post_residual.
                let slack = (post_residual - next_item_size) as f64;
                score -= 20.0 * (1.0 - slack / bin_capacity as f64);
            }
        } else {
            // Next item cannot use the leftover: penalize dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += 0.5 * dead;
        }
    } else {
        // Last item: just minimize leftover.
        score += 0.0;
    }

    // Penalize leaving tiny unusable slivers (< 10, min item size).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Prefer bins tighter than average residual (best-fit coupling).
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Early in the stream, tolerate opening new bins less; late, prefer consolidation.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses.
        score += 10.0 + 30.0 * progress;
        // But if next item chains perfectly into a fresh bin, soften penalty.
        if next_item_size > 0 && next_item_size == bin_capacity - item_size {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Lookahead: reward if the next item can fit into the post residual,
    // penalize if post residual is a "dead" sliver that nothing useful fits.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            let waste = post_residual as f64;
            // Penalize dead space more when it's small-but-unusable relative to item sizes.
            if post_residual < 20 {
                score += 4.0 * (20.0 - waste) / 20.0;
            }
        }
        // If the next item fits exactly in post_residual, big bonus.
        if next_item_size == post_residual {
            score -= 15.0;
        }
    } else {
        // Last item: closing bins tightly is all that matters.
        score -= 5.0 * fit_ratio;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // current item is large relative to capacity or fits nowhere well.
    if bin_residual == bin_capacity {
        let load_frac = item_size as f64 / bin_capacity as f64;
        // A fresh bin is fine for large items, costly for small ones.
        score -= 20.0 * load_frac;
        // If many bins are open and mean residual is high, discourage new bins
        // (there should be room somewhere).
        score += 0.15 * open_bins_count as f64;
        score += 0.05 * mean_residual;
        // Late in the stream, prefer consolidating into existing bins.
        let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 6.0 * t;
        // If this is the only fitting option overall, new bin is acceptable.
        if fitting_bins_count == 0 {
            score -= 15.0;
        }
    }

    // Mild global pressure: when many bins are open with high mean residual,
    // prefer bins whose residual is below mean (denser bins get denser).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear penalty on post_residual: small residuals are dead space.
    let pr_norm = pr / cap;
    score += 12.0 * pr_norm * pr_norm * (1.0 - pr_norm);

    // Progress coupling: tighten packing as stream advances (smooth polynomial).
    score += 8.0 * progress * pr_norm * pr_norm;

    // Perfect fit reward, stronger late in stream.
    let fit_term = 1.0 - (pr / cap - 0.05).powi(2);
    score -= 15.0 * fit_term * (0.5 + progress);

    // Last-chance bonus: avoid opening a new bin unnecessarily.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs();
        score += 0.05 * gap;
        if pr >= next_item_size as f64 {
            score -= 3.0 * (next_item_size as f64 / cap);
        }
    }

    // Penalize bins far below mean residual (fragmentation) with smooth term.
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev;

    // Slight preference for fuller bins when many bins are open.
    score += 0.3 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the item: classify by capacity fraction (eighths).
    let item_class = item_size * 8 / bin_capacity; // 0..=6 class
    let next_class = if next_item_size > 0 { next_item_size * 8 / bin_capacity } else { 0 };

    // Reward tight fits: small post_residual is good, but dead space in
    // awkward bands (post_residual just above a class boundary) is penalized.
    let dead_band = if post_residual > 0 && post_residual < 10 { 40.0 } else { 0.0 };
    score += dead_band;

    // Perfect fill gets a big bonus.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic pairing: if the next item's class complements the post_residual,
    // reward this bin (the leftover can host the next item).
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        score -= 25.0 - (slack as f64) * 0.8; // snug complement is best
        // Modulo coupling: leftover divisible into next item's class multiples
        if next_item_size > 0 && post_residual % next_item_size.max(1) == 0 {
            score -= 8.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // leftover too small for next item: penalize proportionally to wasted fraction
        score += (post_residual as f64) * 0.35;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad
    // and many bins are open with high mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let frag = (mean_residual - post_residual as f64).max(0.0);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 18.0 + frag * 0.2 - progress * 5.0;
        // if item is large, opening fresh bin is more attractive
        score -= (item_class as f64) * 3.0;
    }

    // Prefer bins whose residual is in the same harmonic band as the item
    // (like-with-like packing reduces fragmentation).
    let bin_class = bin_residual * 8 / bin_capacity;
    if bin_class == item_class + 1 || bin_class == item_class + 2 {
        score -= 6.0;
    }

    // Mild penalty for spreading across too many open bins.
    score += open_bins_count as f64 * 0.15;

    // Small tie-breaker favoring fuller bins.
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a plausible item (1..=100) are pure waste. Penalize gaps that
    // fall below the minimum item size, and penalize "awkward" gaps
    // (small but nonzero) super-linearly.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 4.0 * (10 - post_residual) as f64;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 25.0;
    }

    // Coupling with lookahead: if the next item fits exactly into the
    // post_residual, this placement is highly desirable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 && next_item_size <= bin_capacity {
        // If next item cannot fit in the resulting gap, mild penalty for
        // fragmenting space unless the gap is still large.
        if post_residual < next_item_size && post_residual > 0 {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly
    // prefer it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // yet another bin; favor tightening existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / 10.0);
    score += 0.02 * pressure * (0.5 + progress);

    // New-bin candidate: neutral-to-slightly-high baseline so that a new
    // bin is only chosen when all open bins score badly (poor fits).
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.6 + 0.05 * open_bins_count as f64;
        // Allow new bin if no open bin fits at all.
        if fitting_bins_count == 0 {
            score -= 1000.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for near-perfect fits (small dead space).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 40.0 * fit_ratio * fit_ratio;

    // Aggressive 2-step lookahead: reward bins where the next item fits snugly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let snug = next_item_size as f64 / post_residual as f64;
            score -= 30.0 * snug;
        } else {
            // Penalize leaving residual too small for the next item (dead space risk),
            // unless the residual is truly tiny (already committed).
            if post_residual > 0 {
                let waste = (next_item_size - post_residual) as f64;
                score += 0.25 * waste;
            }
        }
    }

    // Penalize moderate residuals that fit nothing typical (fragmentation risk).
    if post_residual > 0 && post_residual < 20 {
        score += 15.0;
    }

    // Relative-to-mean adjustment: bins with residual well below mean are "fuller";
    // prefer filling them further (low residual + placement = good compaction).
    let dev = mean_residual - bin_residual as f64;
    score -= 0.3 * dev;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when current bin fits are poor.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0;
        // Reduce penalty if no open bin can fit (fitting_bins_count includes new bin).
        if fitting_bins_count <= 1 {
            score -= 60.0;
        } else if fitting_bins_count == 2 {
            score -= 5.0;
        }
        // Late in the stream, be more conservative about opening bins.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += 20.0 * progress;
        }
    }

    // Mild preference to keep number of open bins stable.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize post_residual quadratically, but a perfect
    // fit (post_residual == 0) gets a big bonus.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 200.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item is large relative to capacity or the fit elsewhere is bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0;
        // If item is big, a fresh bin is fine (keeps large residual for future).
        score -= (item_size as f64 / bin_capacity as f64) * 80.0;
        // If many bins are open with high mean residual, discourage new bins.
        score += mean_residual * 0.3;
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 40.0;
    } else {
        // Reward using bins whose residual is already small (consolidation).
        score -= (bin_capacity as f64 - bin_residual as f64) * 0.2;
    }

    // Lookahead: if the next item would fit exactly into the post_residual,
    // reward this placement strongly (chained perfect fits).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual > next_item_size {
            // Small penalty for leaving space the next item can partially use.
            score -= 5.0;
        } else {
            // Dead space for the next item: penalize proportionally.
            score += (next_item_size as f64 - post_residual as f64) * 0.5;
        }
    }

    // Global state: many open bins with small residuals -> prefer packing
    // into existing bins to reduce bin count.
    if open_bins_count > 2 {
        score -= (open_bins_count.min(20) as f64) * 1.5;
    }

    // Encourage filling bins that are close to full regardless of post residual.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= fill_ratio * 30.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post / cap;

    // smooth non-linear coupling: post_residual shaped by stream progress
    let shaping = (post / cap).powi(2) * (0.5 + 1.5 * progress) * 2.0;
    score += shaping;

    // prefer tight fits more strongly later in the stream
    let tightness = 1.0 - (post / cap).powf(0.5 + progress);
    score -= tightness * (0.5 + progress);

    // penalize dead space relative to mean residual
    score += ((post - mean_residual) / cap) * (0.3 + 0.7 * progress) * 0.5;

    // lookahead: reward leaving space for the next item, penalize wasting capacity
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            score -= (1.0 - (post - nxt) / cap) * 0.6;
        } else {
            score += (nxt - post) / cap * 0.4;
        }
    }

    // last chance bin bonus: avoid opening a new bin when this is the only fit
    if fitting_bins_count == 1 {
        score -= 1.0 + progress;
    }

    // slight penalty when many bins are open (encourage consolidation)
    score += open_bins_count as f64 * 0.01 * (1.0 - progress);

    // discourage opening new bins mid-stream unless residual is large
    if bin_residual == bin_capacity {
        score += 0.25 + 0.5 * (1.0 - post / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues divisible by common item sizes
    // (10, 20, 25, 50) are more reusable than odd dead space.
    let r = post_residual;
    let mut harmonic_bonus = 0.0;
    if r % 50 == 0 { harmonic_bonus += 14.0; }
    else if r % 25 == 0 { harmonic_bonus += 10.0; }
    else if r % 20 == 0 { harmonic_bonus += 8.0; }
    else if r % 10 == 0 { harmonic_bonus += 5.0; }
    score -= harmonic_bonus;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement is near-perfect (perfect pairing reward).
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0;
        } else if next_item_size <= r {
            // next item fits but leaves more fragmentation; scale by leftover
            score -= 10.0 * (1.0 - (r - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here at all: mild penalty proportional to gap
            score += 3.0 * ((next_item_size - r).min(bin_capacity) as f64 / 100.0);
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin to avoid
    // opening a new bin for a small item.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current item
    // is large relative to capacity or no good fit exists.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / 20.0);
        score += 25.0 + 15.0 * progress - 0.4 * item_size as f64 + 2.0 * pressure;
        // small items should almost never open a new bin
        if item_size <= 30 { score += 20.0; }
    }

    // Tight fit reward: near-zero post residual is ideal.
    if r > 0 && r <= 5 {
        score -= 18.0;
    } else if r > 0 && r < 10 {
        score -= 8.0;
    }

    // Penalize waste relative to mean residual across open bins: leaving far
    // more slack than average indicates poor consolidation.
    score += 0.15 * ((r as f64 - mean_residual).max(0.0));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small leftovers (< 10) are nearly useless
    // for future items; penalize them disproportionately.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual < 20 {
        score += 8.0;
    }

    // Reward tight fits: filling most of the bin is excellent.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 12.0 * fill_ratio;

    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Reward bins whose residual matches the lookahead item exactly
    // (this bin is the natural home for the next item).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 15.0;
        } else if post_residual > next_item_size {
            score -= 3.0;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating
    // into existing bins over spreading out.
    score += (open_bins_count as f64) * 0.15;

    // Mean-residual coupling: bins far below mean residual are "fresher";
    // prefer packing into bins already well-used (residual below mean).
    if (bin_residual as f64) < mean_residual {
        score -= 2.0;
    } else {
        score += 2.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: allow opening a new bin only when the current item
    // is large and no existing bin would end up with a tight dead space.
    if bin_residual == bin_capacity {
        let poor_fit_in_existing = fitting_bins_count == 0
            || (post_residual < 10 && next_item_size > post_residual);
        if poor_fit_in_existing {
            score -= 40.0; // opening a fresh bin is better
        } else {
            score += 35.0; // prefer existing bins generally
        }
    }

    // Slight stream-progression tilt: later in the stream, be a bit more
    // conservative about residual waste.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 1.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: strongly reward when next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect 2-chain: this bin is consumed fully over two items
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            // partial lookahead credit, decaying with leftover slack
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item cannot use post_residual: penalize dead space
            score += 10.0 + 0.3 * (post_residual as f64 - mean_residual).abs();
        }
    }

    // Prefer tight fits relative to mean residual of open bins
    let tightness = (post_residual as f64 - mean_residual) / bin_capacity as f64;
    score += 8.0 * tightness;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: only open a new bin when no open bin fits well
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let late = step_index as f64 / (total_items.max(1) as f64);
        // new bin gets a neutral-ish score; better fits in existing bins will beat it
        score = bin_capacity as f64 * 0.9 - pressure * 40.0 - late * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score += 5.0; // discourage opening fresh bins when lookahead chains poorly anyway
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 2.5 * fit_ratio * (post_residual as f64).sqrt();

    // Penalize large dead space relative to capacity.
    let dead = post_residual as f64 / bin_capacity as f64;
    score += 4.0 * dead * dead;

    // Reward leaving residual that can fit the lookahead item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            score -= 0.05 * next_item_size as f64;
        } else {
            score += 1.5;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless existing
    // fits are scarce or the item fits poorly everywhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = (fitting_bins_count as f64).recip();
        score += 14.0 + 8.0 * (1.0 - progress) + 5.0 * scarcity;
        // If no open bin fits well, soften the penalty.
        if fitting_bins_count == 0 {
            score -= 18.0;
        }
    }

    // Global state coupling: prefer filling bins when many are open.
    score -= 0.15 * (open_bins_count as f64).ln().max(0.0) * (1.0 - dead);

    // Mean residual coupling: avoid bins deviating far below mean residual
    // (keeps a spread of usable residuals across bins).
    let dev = mean_residual - post_residual as f64;
    score += 0.03 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post / cap;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_post * norm_post * (0.5 + 2.0 * progress) + norm_post * (1.0 - progress);

    let mut score = post + 40.0 * poly;

    // Reward tight fits smoothly
    let tightness = 1.0 - norm_post;
    score -= 15.0 * tightness * tightness;

    // Penalize waste relative to mean residual across open bins
    score += 0.15 * (post - mean_residual).abs();

    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post as u32 >= next_item_size {
            score -= 10.0 * (nx / cap) * (1.0 - progress);
        } else {
            score += 5.0 * (nx / cap);
        }
    }

    // Mild penalty for proliferation of open bins late in the stream
    score += 0.05 * open_bins_count as f64 * progress;

    // Slight bias toward keeping new-bin option available early
    if bin_residual == bin_capacity {
        score += 3.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits and small residues are golden.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Integer-division thresholds on post_residual (capacity fraction classes).
        let half = bin_capacity / 2;
        let third = bin_capacity / 3;
        if post_residual <= third {
            score -= 60.0; // tiny dead space class
        } else if post_residual <= half {
            score -= 25.0; // medium class
        } else if post_residual <= 2 * bin_capacity / 3 {
            score -= 5.0; // large residue: still usable
        } else {
            score += 10.0; // awkward class
        }
    }

    // Lookahead coupling: does next item fit into the resulting residue?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // exact/near-exact lookahead fit is highly desirable
            let slack = post_residual - next_item_size;
            if slack == 0 {
                score -= 150.0;
            } else if slack <= bin_capacity / 10 {
                score -= 80.0;
            } else {
                score -= 20.0;
            }
        } else {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 90.0;
    }

    // Penalize spreading across many bins when mean residual is high.
    score += 0.15 * open_bins_count as f64 + 0.05 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.5 * item_size as f64;
    }

    // Stream progression: early on, be slightly more willing to open bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 10.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size are pure waste.
    let min_item = 1u32;
    if post_residual < min_item {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        // small unusable gap: heavy penalty proportional to tightness
        score += (11 - post_residual as i32) as f64 * 25.0;
    } else if post_residual >= 50 {
        // large residual keeps future flexibility: mild reward
        score -= post_residual as f64 * 0.15;
    } else {
        // mid-range residual: penalize relative to mean residual (avoid creating
        // residuals well below the average usability of open bins)
        score += (mean_residual - post_residual as f64).max(0.0) * 0.8;
    }

    // Perfect-fit lookahead: if the next item exactly fills the post-residual, strongly reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 500.0;
    }
    // If next item fits into post-residual, mild reward for chain packing.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 20.0;
    }
    // If post-residual cannot hold the (known) next item but is small, penalize dead space.
    if next_item_size > 0 && post_residual < next_item_size && post_residual <= 20 {
        score += 30.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer tighter packing.
    let pressure = open_bins_count as f64;
    score += pressure * 2.0 + (post_residual as f64) * pressure * 0.02;

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // base cost of opening a bin, reduced when many bins are open and crowded
        let crowding = mean_residual / bin_capacity as f64;
        score = 60.0 + pressure * 3.0 - crowding * 20.0;
        // late in the stream, opening a fresh bin is fine for large leftovers
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 5.0;
        // if the item is large and would leave tiny residual anywhere else,
        // new bin with big residual is good
        if item_size >= 60 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item almost fills the post residual (within 5).
    else if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        score -= 40.0 * (1.0 - gap / 5.0).max(0.0);
    }
    // Next item does NOT fit in post residual: penalize proportionally.
    if next_item_size > 0 && next_item_size > post_residual {
        let overflow = (next_item_size - post_residual) as f64;
        score += 0.15 * overflow;
    }

    // Reward tight fits relative to mean residual of open bins.
    if post < mean_residual {
        score -= (mean_residual - post).min(25.0) * 0.5;
    } else {
        score += (post - mean_residual).min(25.0) * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize leaving large dead space as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (post / cap) * 20.0;

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if next_item_size > 0 && next_item_size <= bin_residual && post_residual >= next_item_size { 0.0 } else { 15.0 };
        score += 10.0 + 5.0 * (open_bins_count as f64).sqrt() + poor_fit;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize relative waste strongly.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio;

    // Penalize leaving dead space that can't hold typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver — actually fine, it's dead space
    }
    if post_residual >= 10 && post_residual < 20 {
        score -= 6.0; // still usable for small items
    }

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early stream: opening bins is cheap; late: consolidate.
        score += 20.0 * progress;
        // If many open bins already, discourage opening another.
        score += 2.0 * open_bins_count as f64;
        // If item is large relative to capacity, new bin is reasonable.
        score -= 0.15 * item_size as f64;
        // If mean residual of open bins is large, prefer existing bins.
        score += 0.3 * mean_residual;
    }

    // Lookahead: if the next item would fit exactly in the post residual,
    // this placement chains nicely — reward it.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 35.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            score -= 15.0; // chain leaves only dead space, still good
        } else if next_item_size > post_residual && next_item_size <= bin_residual {
            // next item fits current bin but not after this placement — mild penalty
            score += 8.0;
        }
    }

    // Fragmentation guard: avoid leaving residuals in the awkward 51..70 range
    // where few items fit well.
    if post_residual > 50 && post_residual < 71 {
        score += 5.0;
    }

    // Prefer filling bins with high residual (largest-first style consolidation).
    score -= 0.05 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let res = bin_residual as f64;

    // Base: prefer minimal post residual, with quadratic penalty on waste.
    let mut score = post + 1.5 * (post / cap).powi(2) * cap;

    // Smooth coupling: waste matters more later in the stream.
    score += 3.0 * progress * post;

    // Fit quality: relative tightness of this placement.
    let tightness = 1.0 - post / res.max(1.0);
    score -= 4.0 * tightness * tightness * (item_size as f64 / cap);

    // Lookahead: reward leaving space exactly usable by the next item.
    let nxt = next_item_size as f64;
    if nxt > 0.0 {
        let gap = (post - nxt).abs();
        score -= 2.5 * (1.0 - gap / cap).max(0.0);
        // Penalize leaving a sliver just below next item's size (dead space).
        if post < nxt {
            score += 2.0 * post;
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        score += 1.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // New-bin candidate: penalize opening a bin when open bins are fragmented,
    // but allow it when existing residuals are small (little usable space left).
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).powi(2);
        score += 12.0 * (1.0 - fragmentation) * (1.0 - 0.5 * progress);
        score += 2.0 * (open_bins_count as f64).ln().max(0.0);
    } else {
        // Prefer bins below mean residual (consolidating emptier bins).
        score += 0.5 * (res - mean_residual) / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: squared waste penalty
    score += (post_residual as f64).powi(2) / cap;

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Small post_residual in a "good" class (divisible well by future items) is favored.
    let class = (post_residual % 10) as f64;
    if post_residual == 0 {
        score -= 60.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 20.0; // nearly full bin, dead space minimal
    } else if class < 2.5 {
        score -= 6.0;  // residue class friendly to common item sizes
    } else if class > 7.5 {
        score += 4.0;  // awkward leftover class
    }

    // Penalize large leftover space that can't host the next item
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 8.0; // next item can't use this bin's remainder
        } else if post_residual == next_item_size {
            score -= 25.0; // next item perfectly fills remainder
        } else {
            let nxt = next_item_size as f64;
            let fit_quality = (post_residual as f64 - nxt) / cap;
            score += fit_quality * 10.0;
            // reward if next item leaves another small remainder
            let post2 = post_residual - next_item_size;
            if post2 <= 10 {
                score -= 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only open a new bin when open bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin grows with number of open bins
        score += 40.0 + 2.0 * open_bins_count as f64;
        // If the item fits an open bin reasonably well (post_residual small),
        // make new bin unattractive.
        if post_residual <= 20 {
            score += 80.0;
        }
        // Early in the stream, allow new bins more freely (build a pool)
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 15.0;
        // If mean residual across open bins is high, prefer spreading load to a new bin
        if mean_residual > 0.5 * cap {
            score -= 20.0;
        }
    } else {
        // Existing bin: slight reward for keeping bins consolidated
        score -= 3.0;
        // Penalize using a very full bin when many bins could fit (save flexibility)
        if fitting_bins_count > 3 && post_residual <= 5 {
            score += 5.0;
        }
    }

    // Progress-aware consolidation: late in stream, pack tighter
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0 * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are tiny but nonzero are
    // "unusable gaps" for future items (min item size 1..100 unknown, but
    // typical streams leave mid-size items). Penalize the 1..=10 band hard.
    if post_residual > 0 && post_residual <= 10 {
        score += 40.0;
    } else if post_residual > 10 && post_residual <= 25 {
        score += 8.0;
    }

    // Reward exact fits and near-exact fits strongly.
    if post_residual == 0 {
        score -= 100.0;
    }

    // If this bin is the last chance before opening a new bin, favor using it
    // (avoid bin proliferation) unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
        if post_residual > 0 && post_residual <= 10 {
            score -= 30.0; // accept small dead space rather than open a bin
        }
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins; opening a new bin (residual == capacity) gets penalized.
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count.min(50) as f64;
        // But if no open bin fits well (large mean residual spread), allow it.
        if mean_residual < item_size as f64 {
            score -= 30.0;
        }
    } else {
        // Reward tight fits relative to what the bin offered.
        score -= 0.3 * item_size as f64;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this placement (chained packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 20.0;
        } else {
            score -= 5.0 * (1.0 - slack / bin_capacity as f64);
        }
    }

    // Late in the stream, be more aggressive about closing bins tightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += progress * (post_residual as f64 * 0.2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 0.90;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits: square the post-residual pressure.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * tightness * 20.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates from the mean (keeps bin pool homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.3;

    // Lookahead: reward bins whose post-residual can still fit the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else {
            // Dead space for the lookahead item: penalize proportionally.
            let waste = (next_item_size - post_residual) as f64;
            score += waste * 0.5;
        }
    }

    // Late in the stream, prefer closing bins out: favor fuller bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity - bin_residual) as f64 * 0.2;

    // Many open bins: discourage new-bin creation to consolidate.
    if bin_residual == bin_capacity {
        let consolidation_bonus = 15.0 + (open_bins_count as f64) * 2.0;
        score += consolidation_bonus;
        // But if item barely fits nowhere else well, new bin is fine — soften when item is large.
        if item_size > bin_capacity / 2 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: quadratic coupling of post_residual with stream progress.
    let mut score = norm_pr * (1.0 + 1.5 * progress * norm_pr) * cap;

    // Dead-space penalty: small post-residuals that are too small for typical items.
    let dead_zone = if pr > 0.0 && pr < 10.0 { (10.0 - pr) / 10.0 } else { 0.0 };
    score += 8.0 * dead_zone * (1.0 + progress);

    // Reward tight fits: smooth interaction of fill fraction with progress.
    let fill = 1.0 - norm_pr;
    score -= 6.0 * fill * fill * (1.0 + progress);

    // Lookahead coupling: penalize if next item can't use the post residual.
    if next_item_size > 0 {
        let fits_next = (pr >= next_item_size as f64) as i32 as f64;
        score -= 4.0 * fits_next * (next_item_size as f64 / cap);
        score += 3.0 * (1.0 - fits_next) * (1.0 - progress);
    }

    // Last-chance bonus: strongly favor the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0 * (1.0 + progress);
    }

    // New-bin candidate: prefer opening a new bin when open bins are fragmented.
    if bin_residual == bin_capacity {
        score -= 2.0 * open_bins_count as f64 * mean_residual / cap;
        score += 3.0 * (1.0 - progress);
    } else {
        // Mild penalty for scattering when many bins share high residuals.
        score += 1.5 * (bin_residual as f64 - mean_residual).abs() / cap;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "usable" is the leftover space?
    // Residuals in fine-grained classes (mod 10) that align with common item sizes
    // are more likely to be filled later; coarse, prime-ish gaps are dead space.
    let pr = post_residual;
    let harmonic_class = pr % 10;
    let fine_fill = match harmonic_class {
        0 => -14.0,   // residual divisible by 10: many item sizes can use it
        5 => -8.0,    // half-class: moderately reusable
        2 | 4 | 6 | 8 => -4.0, // even: decent chance
        1 | 9 => 2.0, // awkward gap
        _ => 5.0,     // 3 | 7: prime-ish dead space
    };
    score += fine_fill;

    // Integer-division thresholds on post_residual: bins that can still hold
    // a "medium" item (>= 20) are valuable; bins below that are nearly dead.
    if pr >= 40 {
        score -= 10.0;
    } else if pr >= 20 {
        score -= 5.0;
    } else if pr > 0 {
        score += 6.0; // tiny sliver: penalize
    }

    // Coupling with lookahead: if the next item fits exactly (or nearly) into
    // the post residual, strongly reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as f64 - nxt).abs() < 1.0 {
            score -= 25.0; // perfect two-item packing
        } else if pr as u32 >= next_item_size {
            score -= 12.0;
            // harmonic bonus when next item also lands on a fine class
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here; slight penalty proportional to waste
            score += (nxt - pr as f64).min(30.0) * 0.15;
        }
    }

    // Tight fit reward: normalized fill ratio of this placement.
    let fill = (item_size as f64) / cap;
    score -= fill * 12.0;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin is only attractive when existing
    // bins would be badly fragmented. Judge by how poorly this placement uses
    // the current bin relative to stream progress.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin grows with the number of open bins
        // (encourages consolidation) but shrinks late in the stream.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 2.0 * (open_bins_count as f64) - 8.0 * progress;
        // If the item is huge (>= 50) and mean residual across open bins is
        // small, opening fresh is reasonable: soften the penalty.
        if item_size >= 50 && mean_residual < item_size as f64 {
            score -= 18.0;
        }
        // Harmonic: item sizes in coarse classes (multiples of 10) pack well
        // into fresh bins; odd sizes fragment them.
        if item_size % 10 == 0 {
            score -= 5.0;
        } else if item_size % 2 == 1 {
            score += 4.0;
        }
    } else {
        // Reward using existing bins, more so when many are open.
        score -= 1.5 * (open_bins_count.min(20) as f64);
        // Penalize placements that leave residual far from mean (fragmentation).
        let dev = (post_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    // Stream-phase modulation: early on, prefer tight packing to build good
    // bins; late, slightly favor closing bins out (accept larger residuals).
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * (post_residual as f64) * 0.08;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible future item are "dead space" -> heavy penalty.
    let dead_threshold: f64 = 10.0; // below typical min item size
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += 25.0 * (dead_threshold - post_residual as f64) / dead_threshold;
    }

    // Reward near-perfect fills strongly (post_residual close to 0 is best).
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Prefer bins whose residual was large (good consolidation of big gaps).
    score -= 0.05 * bin_residual as f64;

    // Open-bin pressure: penalize spreading across many bins slightly,
    // but relieve pressure when this is the only fitting bin (last chance).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    } else {
        score += 0.3 * open_bins_count as f64;
    }

    // Lookahead coupling: if the next item fits the post residual exactly-ish,
    // reward this placement (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 5.0 {
            score -= 12.0;
        } else {
            score -= 4.0;
        }
    } else if next_item_size > post_residual as u32 && post_residual > 0 {
        // next item cannot use leftover -> leftover likely dead space
        score += 6.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first),
    // keeping loose bins available for larger future items.
    score += 0.2 * (mean_residual - bin_residual as f64).max(0.0);

    // New-bin candidate: make empty-bin placement mildly unattractive unless
    // nothing else fits well; strong penalty when other bins can fit.
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 15.0;
        } else {
            score += 2.0;
        }
    }

    // Slight stream-position adaptation: later in the stream, tighten up more
    // aggressively (less room to recover from fragmentation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next_item_size
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += diff * 0.8;

        // Perfect two-item completion: strongly reward
        if post_residual == next_item_size {
            score -= 25.0;
        }
        // Next item fits with small slack: mildly reward
        else if post_residual > next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.15;
        }
        // Next item won't fit here: penalize wasted residual relative to mean
        else {
            score += 5.0 + (post_residual as f64 - mean_residual).abs() * 0.3;
        }
    }

    // Prefer tight fits: penalize large post_residual relative to bin capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += tightness * 12.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize slightly so we only open when open bins are poor fits
    if bin_residual == bin_capacity {
        score += 20.0;
        // But if no open bin fits well, opening is fine (handled by comparisons)
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 5.0; // keep room for pairing in a fresh bin
        }
    }

    // Late in stream: consolidate, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 3.0 * (open_bins_count as f64).ln().max(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream processed (dynamic time horizon).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tight * tight;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bin: strongly reward if this is the only bin that fits,
    // scaled by how late we are (avoid wasting early capacity).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0 + 25.0 * progress;
    }

    // Lookahead: reward if the next item can use the post_residual,
    // penalize if post_residual is dead space that no plausible item (>=1) uses.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else if post_residual > 0 && post_residual < 10 {
            score += 5.0; // small dead sliver, mild penalty
        }
    }

    // Penalize bins whose residual is far below mean (fragmented bins),
    // unless the item fits very snugly.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score += (mean_residual - bin_residual as f64).max(0.0) * 0.3 * (1.0 - fit_ratio);

    // New-bin candidate logic: only attractive when open bins are mostly full
    // or the fit into open bins is poor.
    if bin_residual == bin_capacity {
        let mean_fill = 1.0 - mean_residual / bin_capacity as f64;
        let poor_options = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let openness = (open_bins_count as f64).ln().max(1.0);
        let new_bin_bonus = 20.0 * mean_fill + 40.0 * poor_options - 10.0 / openness;
        score -= new_bin_bonus;
        // Early in the stream, opening bins is cheap and keeps flexibility.
        score -= 10.0 * (1.0 - progress);
    } else {
        // Mild congestion penalty: spreading across many open bins early is fine,
        // late we prefer consolidation.
        score += 2.0 * progress * (open_bins_count as f64).sqrt();
    }

    // Penalize wasting a large residual on a small item when alternatives exist.
    if bin_residual >= item_size && fit_ratio < 0.4 && fitting_bins_count > 1 {
        score += 8.0 * (1.0 - fit_ratio);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on: mildly tolerate large residuals (bins are plentiful).
    // Late: aggressively punish wasted space.
    let late_weight = progress * progress; // smooth ramp
    score += late_weight * (pr * pr) / cap; // quadratic waste penalty grows over time

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (pr / cap);
    score -= tightness * tightness * 10.0;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 25.0 * progress;
    }

    // Lookahead coupling: if next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual as f64 == nxt {
            score -= 30.0;
        } else if post_residual >= next_item_size {
            // partial reward scaled by how well next item fills the leftover
            let fill = nxt / pr.max(1.0);
            score -= 15.0 * fill * fill;
        } else {
            // leftover too small for next item: penalize dead space, more so late in stream
            score += 8.0 + 12.0 * progress;
        }
    }

    // Mild penalty when many bins are already open (encourage consolidation).
    score += open_bins_count as f64 * 0.3 * (1.0 - tightness);

    // Brand-new bin candidate: neutral baseline with slight preference when
    // current item is large (large items start fresh bins well).
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / cap;
        score = cap - pr + 5.0 - 10.0 * large_item * large_item;
        // discourage opening new bins when a decent fit exists elsewhere
        if fitting_bins_count > 0 {
            score += 20.0 * (1.0 - late_weight);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: perfect fits are class 0.
    let class = post_residual % 10;
    if class == 0 {
        score -= 25.0; // residual is a multiple of 10, highly reusable
    } else if class <= 3 {
        score -= 8.0;
    } else if class >= 8 {
        score += 10.0; // awkward sliver, penalize
    }

    // Dead-space penalty: unusable space for the smallest possible item
    if post_residual < 10 && post_residual > 0 {
        score += 30.0;
    }

    // Lookahead coupling: reward if next item fits in post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 20.0 + 0.2 * next_item_size as f64;
        } else {
            // penalize near-misses harder when close
            let gap = next_item_size - post_residual;
            if gap <= 10 {
                score += 12.0 + gap as f64;
            } else {
                score += 5.0;
            }
        }
    } else {
        // last item: prefer tightest fit
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate: discourage opening a new bin unless existing fits are poor
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 40.0;
        }
        // opening new bin is fine if item is large relative to capacity
        score -= 0.1 * item_size as f64;
    }

    // Prefer filling bins that are already partially used when many bins are open
    if open_bins_count > 3 {
        let fill_ratio = 1.0 - (bin_residual as f64 / bin_capacity as f64);
        score -= 10.0 * fill_ratio;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, it's a good squeeze target
    let dev = mean_residual - post_residual as f64;
    score -= 0.15 * dev;

    // Harmonic integer-division threshold on post_residual
    let q = post_residual / 25; // capacity quarters
    score -= match q {
        0 => 6.0,
        1 => 2.0,
        2 => -4.0,
        _ => -8.0,
    };

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum item size (1..=100
    // interface, but streams historically >=10) are near-useless gaps.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        // Perfect fill is great; tiny dead space is heavily penalized.
        score += (dead_threshold - post_residual as f64) * 12.0;
    }

    // Reward exact fills strongly.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin capacity.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 25.0;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 18.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post-residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 45.0;
        } else if next_item_size <= post_residual {
            score -= (next_item_size as f64 / post_residual.max(1) as f64) * 10.0;
        } else {
            // Next item won't fit here; slight penalty proportional to wasted gap.
            score += 3.0;
        }
    }

    // Open-bin pressure: discourage proliferating bins mid-stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64) * (0.4 + 0.6 * progress) * 0.5;

    // Prefer bins with residual below mean (consolidate small gaps into fuller bins).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: baseline cost of opening a fresh bin; only attractive
    // when no open bin offers a decent fit. Empty bin residual == capacity.
    if bin_residual == bin_capacity {
        score += 35.0 - fill_ratio * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Baseline: prefer tight fits
    score -= 0.5 * (item_size as f64) / (bin_capacity as f64) * 10.0;

    if next_item_size > 0 {
        // Perfect 2-step match: post_residual equals next item size -> strong reward
        if post_residual == next_item_size {
            score -= 30.0;
        } else if post_residual > next_item_size {
            // Next item can still fit after this placement
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Dead space: next item cannot use the remainder
            let dead = (next_item_size - post_residual) as f64;
            score += 2.0 * dead;
        }

        // Reward bins where the pair (item, next) exactly fills the bin
        if item_size + next_item_size == bin_residual {
            score -= 25.0;
        }
    }

    // Compare residual against mean residual across open bins
    let diff = post_residual as f64 - mean_residual;
    score += 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Penalize opening new bins when many bins are already open and a fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 + 10.0 * (open_bins_count as f64) * (0.5 + progress);
        // But allow opening when the current item is large and fit is terrible elsewhere
        if item_size >= 60 {
            score -= 12.0;
        }
    }

    // Prefer bins with small residual waste overall
    score += 0.2 * (post_residual as f64 / bin_capacity as f64) * 20.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize residual that is small but nonzero (dead space).
    if post_residual > 0 {
        score += (post_residual as f64).powf(1.3) * 0.15;
    } else {
        score -= 12.0; // perfect fit bonus
    }

    // Reward filling a bin to a high fraction of capacity.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;
    score -= fill * fill * 8.0;

    // Lookahead: if next item fits in post_residual, big bonus for this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 6.0 + (post_residual - next_item_size) as f64 * 0.05;
    }
    // If next item would leave this bin nearly dead, mild penalty.
    if next_item_size > 0 && next_item_size > post_residual && post_residual < next_item_size.min(10) {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: only attractive when existing fit is bad.
    if bin_residual == bin_capacity {
        let tightness = (bin_residual - item_size) as f64; // post_residual for new bin
        let pressure = if fitting_bins_count == 0 { 0.0 } else {
            (mean_residual - item_size as f64).abs()
        };
        score += 14.0;              // base cost of opening a new bin
        score -= tightness * 0.25;  // a fresh bin wastes capacity when item is small
        score -= pressure * 0.3;    // open new bin when open bins fit poorly
        if open_bins_count == 0 {
            score -= 20.0;          // must open first bin
        }
    }

    // Global state: many open bins with large mean residual -> prefer reusing roomy bins less,
    // prefer consolidating into tight bins (handled via fill bonus); add mild time decay.
    let t = step_index as f64 / (total_items.max(1) as f64);
    score -= t * 1.5;

    // Penalize leaving residual just below the smallest plausible item (dead space band).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Slight penalty when bin is much roomier than mean (avoid scattering across many bins).
    if bin_residual as f64 > mean_residual + 20.0 && bin_residual < bin_capacity {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = (bin_residual as u64 == bin_capacity as u64) as f64;

    // Core: reward tight fits with a smooth non-linear (quartic) decay in post_residual.
    let norm_pr = pr / cap;
    let mut score = 12.0 * norm_pr * norm_pr * norm_pr * norm_pr
        + 6.0 * norm_pr * norm_pr;

    // Stream-progress coupling: later in the stream, tolerate less slack (smooth shift).
    score += 4.0 * norm_pr * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && is_new_bin == 0.0 {
        score -= 25.0;
    }

    // New-bin penalty: opening a bin should be costly, more so when other bins fit.
    score += is_new_bin * (18.0 + 10.0 * (1.0 - progress) + 3.0 * (open_bins_count as f64).sqrt());

    // Lookahead coupling: penalize leaving a residual that barely misses the next item,
    // reward residuals that can host it (smooth interaction).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr) / cap;
        if gap > 0.0 {
            score += 5.0 * gap * gap; // next item won't fit here -> dead space risk
        } else {
            score -= 3.0 * (-gap) * (1.0 - (-gap)); // smooth reward for hosting next item
        }
    }

    // Mild penalty for deviating from mean residual across open bins (balance pressure).
    let dev = (pr - mean_residual) / cap;
    score += 1.5 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Harmonic class of post_residual: exact-fit classes are golden.
    let post_u = post_residual;
    if post_u == 0 {
        score -= 60.0; // perfect fit
    } else if post_u <= 10 {
        score -= 25.0;
    } else if post_u % 10 == 0 {
        score -= 15.0; // decadal residual is reusable
    } else if post_u < 20 {
        score += 20.0; // dead-space risk zone
    }

    // Lookahead coupling: does the next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0; // chain placement possible
        } else {
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.4;
        }
    }

    // Last-chance bin before opening a new one.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Prefer filling nearly-full bins early in the stream; spread later.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill_frac = (bin_capacity - bin_residual) as f64 / cap;
    score -= fill_frac * 20.0 * (1.0 - 0.5 * progress);

    // Penalize opening a new bin when good fits exist.
    if bin_residual == bin_capacity {
        let good_fits = if post_u == 0 { 1.0 } else { 0.0 };
        score += 40.0 - 30.0 * good_fits;
        score += (open_bins_count as f64).sqrt() * 3.0;
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    // Mild tie-break toward bins with residual near mean.
    let dev = (post - mean_residual).abs();
    score += dev * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty for small unusable gaps
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 20 {
        score += 15.0; // moderate penalty for awkward mid-range gaps
    } else if post_residual == 0 {
        score -= 40.0; // perfect fit strongly rewarded
    }

    // Reward tight fits relative to item size
    score -= 0.5 * (item_size as f64 / bin_capacity as f64) * 100.0;

    // Open-bin pressure: discourage spreading across many bins
    score += 2.0 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: favor bins whose post_residual can host the next item
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 10.0; // residual too small for lookahead item -> dead space risk
    }

    // New-bin candidate: prefer only when open bins are crowded or fit is poor
    if bin_residual == bin_capacity {
        let crowd = open_bins_count as f64 / 10.0;
        score = 50.0 + crowd - 0.3 * (post_residual as f64);
        if fitting_bins_count > 2 {
            score += 30.0; // plenty of alternatives -> don't open new bin
        }
    }

    // Progress-based mild adjustment: later in stream, consolidate more
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * progress * (mean_residual / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect 2-step match: this bin's leftover exactly fits the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 1000.0; // perfect chain: waste zero over two steps
        } else if post_residual >= next_item_size {
            // Next item fits; reward tighter two-step packing (smaller double leftover).
            let two_step_left = (post_residual - next_item_size) as f64;
            score -= 200.0 - two_step_left * 1.5;
        } else {
            // Next item will not fit here; penalize proportionally to how dead the space is.
            let gap = nxt - post_residual as f64;
            score += gap * 0.8;
        }
        // Slight preference for bins whose post-residual is close to typical sizes (10..80 grid).
        let r = post_residual as f64;
        let near_typ = (r - 10.0).min((r - 20.0).abs()).min((r - 30.0).abs())
            .min((r - 40.0).abs()).min((r - 50.0).abs()).min((r - 60.0).abs())
            .min((r - 70.0).abs()).min((r - 80.0).abs());
        score += near_typ * 0.15;
    }

    // Penalize residuals far below the mean residual of open bins (fragmented bin).
    let r = post_residual as f64;
    if r < mean_residual {
        score += (mean_residual - r) * 0.5;
    } else {
        score -= (r - mean_residual) * 0.1;
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: only attractive when current item nearly fills it and
    // no good 2-step chain exists elsewhere; penalize opening bins when many are open.
    if bin_residual == bin_capacity {
        score += 60.0; // base cost of opening a new bin
        if open_bins_count > 0 {
            score += (open_bins_count as f64) * 2.0;
        }
        if item_size >= 60 {
            score -= 40.0; // big items pack well into fresh bins
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 30.0; // fresh bin also supports the lookahead item
        }
    }

    // Late in the stream, tighten packing aggressively (less future to plan for).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * (bin_capacity - item_size) as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
