pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr_norm = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let coupling = (pr_norm * pr_norm) * (0.5 + 1.5 * progress) - (pr_norm * pr_norm * pr_norm) * (1.0 + 2.0 * progress);
    score += 20.0 * coupling;

    // Reward tight fits, stronger as stream progresses
    score -= (1.0 - pr_norm) * (1.0 + progress) * 10.0;

    // Penalize dead space that cannot fit the next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += (nxt - pr) * (1.0 + progress) * 0.5;
        } else {
            score -= (1.0 - (pr - nxt) / cap) * 2.0;
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 + progress);
    }

    // Mild penalty for opening new bins when many are open with slack
    if bin_residual == bin_capacity {
        score += open_bins_count as f64 * 0.3 + mean_residual * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of post_residual: mod-10 buckets create discrete waste classes
    let pr = post_residual as u32;
    let pr_mod = pr % 10;
    let pr_quot = pr / 10; // integer division threshold on post_residual

    // Reward post-residuals in "usable" harmonic classes (multiples of 10, small dead space)
    if pr_mod == 0 {
        score -= 6.0; // perfect harmonic alignment
    } else if pr_mod <= 2 {
        score -= 2.5;
    } else if pr_mod >= 8 {
        score += 3.0; // awkward leftover sliver
    }

    // Dead-space penalty grows for mid-range unusable residuals
    if pr > 0 && pr < 10 {
        score += 8.0; // worst class: tiny unusable gap
    }

    // Integer-division thresholds: post_residual deciles
    score += match pr_quot {
        0 => -1.0,
        1 => 0.5,
        2 => 1.5,
        3 => 2.5,
        4 => 3.0,
        _ => 3.5,
    };

    // Lookahead coupling: does post_residual fit next item harmonically?
    if next_item_size > 0 && pr >= next_item_size {
        let slack_after_next = pr - next_item_size;
        let nm = slack_after_next % 10;
        if nm == 0 {
            score -= 5.0;
        } else if nm <= 2 {
            score -= 2.0;
        }
        score -= 0.05 * (pr - next_item_size) as f64;
    } else if next_item_size > 0 && pr > 0 {
        // next item cannot fit here: dead space unless it's tiny
        score += 0.04 * pr as f64;
        if next_item_size > pr && pr > 0 && pr < next_item_size {
            score += 2.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize slightly unless open bins are crowded
    if bin_residual == bin_capacity {
        score += 15.0 - 0.3 * open_bins_count as f64;
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 4.0; // pair fits in fresh bin
        }
    }

    // Tight fits rewarded
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio > 0.9 {
        score -= 4.0;
    } else if fill_ratio > 0.75 {
        score -= 2.0;
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins first)
    score -= 0.15 * (mean_residual - bin_residual as f64);

    // Mild stream-phase modulation
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += 1.5 * phase * (pr_mod as f64) / 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small unusable gaps (< 10) are worst.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Last-chance pressure: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Reward bins whose residual is close to mean (harmonic packing),
    // penalize outliers that waste space.
    let diff = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * diff;

    // Lookahead: if next item fits into post_residual, bonus.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra bonus if next item would nearly fill the bin too.
        if post_residual - next_item_size <= 5 {
            score -= 10.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual && post_residual < 10 {
        // Dead space that the next item cannot use.
        score += 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading
    // by slightly penalizing placements, but not enough to open new bins.
    score += 0.5 * open_bins_count as f64;

    // Mild preference to fill older/more-full bins first: smaller residual => lower score.
    score += 0.1 * (bin_residual as f64);

    // New-bin candidate adjustment: opening a new bin is only attractive
    // when the current item leaves a huge residual in any existing bin.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, offset by its large post_residual
        // (which already scores high). Add fixed opening cost.
        score += 20.0;
        // If no existing bin fits well, opening is relatively better:
        if fitting_bins_count == 0 {
            score -= 80.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Lookahead: if next item fits exactly, strongly reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item still fits: reward proportionally to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit: penalize leaving dead space
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste.min(80.0);
        }
    }

    // Reward tight fits of the current item.
    let tightness = 1.0 - post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * tightness;

    // Penalize deviation from mean residual (prefer balanced or full bins).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize mildly so it's chosen only when open bins are bad,
    // but late in the stream slightly discourage opening extra bins.
    if bin_residual == bin_capacity {
        score += 15.0;
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Many open bins: prefer filling existing ones.
    score += 0.5 * open_bins_count as f64;

