pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let x = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.8 * progress * progress) + 30.0 * x * x * (0.5 + progress);

    // Reward near-perfect fits more strongly as stream progresses
    score -= (1.0 - x).powi(2) * 25.0 * (0.4 + progress);

    // Penalize dead space that cannot fit the next item (smooth coupling)
    if next_item_size > 0 {
        let nx = next_item_size as f64 / cap;
        let waste = (pr - next_item_size as f64).max(0.0) / cap;
        score += 40.0 * waste * waste * (1.0 - nx);
    } else {
        score += 20.0 * x * x;
    }

    // Last-chance bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 35.0 * (1.0 + progress);
    }

    // Mild penalty for spreading across many open bins, smoothed by mean residual
    score += 0.15 * open_bins_count as f64 * (mean_residual / cap).max(0.0);

    // Slight preference to keep new bins closed early, open late
    if bin_residual == bin_capacity {
        score += 12.0 * (1.0 - progress) - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "usable" classes (large enough for typical future items) get rewarded.
    let post = post_residual as f64;
    let cap = bin_capacity as f64;
    let frac = post / cap; // capacity fraction of leftover

    // Class boundaries via integer division on post_residual
    let class = post_residual / 10; // 0..=10 harmonic classes
    let class_bonus: f64 = match class {
        0 => 40.0,              // dead space, heavily penalize
        1 => 25.0,
        2 => 12.0,
        3 => 5.0,
        4 => 0.0,
        5 => -6.0,              // half-full leftover is flexible
        6 => -8.0,
        7 => -10.0,
        8 => -12.0,
        9 => -14.0,
        _ => -16.0,             // nearly full bin: excellent closure
    };
    score += class_bonus;

    // Modulo coupling: leftover divisible into chunks of common item sizes
    // (multiples of 10) is more likely reusable.
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 6.0;
    }
    // Odd/awkward remainders create dead space risk
    let awkward = post_residual % 5;
    score += awkward as f64 * 0.8;

    // Lookahead: if the next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            // graded reward by how well next item fills the leftover
            let fill = next_item_size as f64 / post as f64;
            score -= 10.0 * fill;
        } else {
            // leftover too small for next item: penalize more when far from full
            score += 6.0 * (1.0 - frac);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would create bad dead space and the item is large.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 25.0; // must open a bin anyway
        } else if item_size >= 50 && post_residual + item_size == bin_capacity {
            // item exactly fills a fresh bin: attractive
            score -= 8.0;
        } else {
            // generally discourage opening new bins while others fit
            score += 15.0 + 2.0 * (open_bins_count as f64).sqrt();
        }
    }

    // Tight fits are classic best-fit behavior: reward small post residuals.
    if post_residual <= 5 && post_residual > 0 {
        score -= 12.0;
    }

    // Mild stream-progress adaptation: late in stream, prefer closing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * frac * (1.0 - progress);

    // Pull toward mean residual: avoid extreme outliers relative to fleet.
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small gaps (1..15) are nearly unusable for future items.
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Reward residual close to mean (keeps bin population homogeneous).
    score += ((post_residual as f64) - mean_residual).abs() * 0.3;

    // Open-bin pressure: with many open bins, prefer packing into existing ones.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bonus: if this is the only fitting bin, strongly favor it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual - next_item_size < 5 {
            score -= 15.0;
        }
        // Penalize leaving a gap that next item can't use but is small.
        if post_residual > 0 && post_residual < next_item_size && post_residual < 10 {
            score += 10.0;
        }
    }

    // Late in stream: reduce tendency to open new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses and many bins open.
        score += 25.0 + 40.0 * progress + open_bins_count as f64 * 2.0;
        // Allow new bin early if few bins and item is large.
        if open_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fills strongly.
    if post_residual == 0 {
        score -= 500.0;
    } else if post_residual <= 10 {
        score -= 60.0 + 2.0 * (10 - post_residual) as f64;
    }

    // Lookahead (k=2): reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0 + 0.5 * next_item_size as f64;
        } else if next_item_size > 0 && next_item_size <= bin_residual {
            // This bin could take the next item instead; mild penalty for wasting that option.
            score += 8.0;
        }
        // Dead space that cannot fit the next item is worse late in the stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if post_residual < next_item_size {
            score += 10.0 * progress;
        }
    } else {
        // Last item: strongly prefer tightest residual.
        score -= 40.0;
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins tighter than the mean (best-fit flavor).
    score -= 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate: penalize opening new bins unless the item is large
    // and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / bin_capacity as f64;
        let residual_frac = bin_residual as f64 / bin_capacity as f64;
        let mut new_bin_penalty = 45.0;
        // Large items justify fresh bins; small items do not.
        new_bin_penalty -= 40.0 * item_frac;
        // If many bins fit the item, opening a new one is wasteful.
        new_bin_penalty += 5.0 * fitting_bins_count as f64;
        // Late in the stream, consolidating is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_penalty += 20.0 * progress;
        // If mean residual is large, open bins have room; discourage new bins.
        new_bin_penalty += 0.2 * mean_residual;
        score += new_bin_penalty.max(0.0);
        let _ = residual_frac;
    }

    // Mild preference for already-open bins when many are open (avoid bin sprawl).
    if bin_residual < bin_capacity {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post-residual, with non-linear polynomial shaping.
    // Favor tight fits: reward low post_residual super-linearly.
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Dead-space penalty: residuals too small for any plausible item (items >= 1),
    // strongly penalize near-zero residuals late in the stream.
    let dead = (-norm_pr + 0.15).max(0.0);
    score += 40.0 * dead * dead * (0.5 + progress);

    // Stream-progress coupling: early on, prefer keeping flexibility (higher residual);
    // later, prefer tight packing aggressively.
    let flex = (1.0 - progress).powi(2);
    score -= 25.0 * flex * norm_pr;
    score += 15.0 * progress * (1.0 - norm_pr).powi(3);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: neutral baseline with slight discouragement,
    // unless residuals of open bins are poor or none fit.
    if bin_residual == bin_capacity {
        let poor_fits = (mean_residual - pr).abs() < 1e-9;
        let mut bias = 30.0;
        // If mean residual of open bins is small, opening a new bin is attractive.
        bias -= (mean_residual / cap).max(0.0) * 45.0;
        // Late in stream, slightly discourage opening new bins.
        bias += 20.0 * progress;
        // Lookahead: if next item is large, a fresh bin is valuable.
        let n = next_item_size as f64;
        if n > 0.0 {
            bias -= (n / cap).max(0.0) * 20.0 * (1.0 - progress);
        }
        if poor_fits && open_bins_count > 0 {
            bias -= 10.0;
        }
        score = bias;
    }

    // Lookahead synergy: reward leaving post_residual that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 * (1.0 - (post_residual - next_item_size) as f64 / cap);
    } else if next_item_size > 0 {
        // Penalize residuals that block the next item.
        score += 8.0 * (1.0 - progress);
    }

    // Mild penalty for proliferating open bins when residuals are scattered.
    if open_bins_count > 1 {
        score += 2.0 * ((mean_residual - pr).abs() / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    } else if post_residual <= 10 {
        score -= 120.0;
    }

    // Harmonic class: how well post_residual divides into typical item sizes.
    // Dead space that is a multiple of small sizes is more reusable.
    let reusable = (post_residual % 10 == 0) as f64 * 40.0
        + (post_residual % 5 == 0) as f64 * 15.0
        + (post_residual % 20 == 0) as f64 * 20.0;
    score -= reusable;

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = post_residual - next_item_size;
        if slack == 0 {
            score -= 400.0;
        } else if slack <= 10 {
            score -= 100.0;
        } else {
            score -= (20.0 - (slack as f64).min(20.0)) * 2.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this bin's leftover: penalize dead space.
        score += (post_residual as f64).min(50.0) * 0.8;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 250.0;
    }

    // Prefer filling existing bins when many are open (avoid bin proliferation).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += open_bins_count as f64 * 1.5 * (0.5 + progress);

    // New-bin candidate: only attractive if it beats tight fits elsewhere.
    if bin_residual == bin_capacity {
        score += 60.0 + mean_residual * 0.3;
    }

    // Mild preference for bins tighter than average (best-fit flavor).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: heavily penalize small unusable gaps.
    // A residual that cannot fit the smallest plausible item is wasted space.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let min_item = 1.0f64;
    if (post_residual as f64) < min_item {
        score += 1000.0; // unreachable guard, post_residual >= 0
    }

    // Dead-space zone: post_residual in (0, 10) is nearly unusable dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + 8.0 * (10 - post_residual) as f64;
    }

    // Penalize medium awkward gaps (10..=25) proportionally to progress,
    // since late-stream dead space is more costly.
    if post_residual >= 10 && post_residual <= 25 {
        score += 10.0 + 25.0 * progress;
    }

    // Reward exact or near-exact fits.
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 5 {
        score -= 40.0;
    }

    // Reward residuals that can still host the lookahead item (k=2 lookahead).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0;
        } else if post_residual > 0 {
            score += 12.0; // blocks the next item
        }
    }

    // Last-chance pressure: if this is the only bin that fits, prefer using it
    // over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
        if post_residual > 40 {
            score += 20.0; // very poor fit in the only option
        }
    }

    // Open-bin pressure: discourage scattering across many open bins.
    score += 1.5 * open_bins_count as f64;

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Only prefer it when no open bin offers a good fit (large post_residual
    // among fitting bins) or when the item is huge relative to residuals.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 55.0 + 3.0 * open_bins_count as f64;
        // If the current item nearly fills a fresh bin, opening is attractive.
        if item_size >= 70 {
            new_bin_score -= 30.0;
        }
        // Late in the stream, opening fresh bins is less wasteful long-term.
        new_bin_score -= 10.0 * progress;
        // If lookahead is large, a fresh bin preserves flexibility.
        if next_item_size >= 60 {
            new_bin_score -= 12.0;
        }
        score = new_bin_score;
    }

    // Mean-residual coupling: if mean residual is high, prefer bins below the mean
    // (drain the emptiest useful bins first) to consolidate.
    if (bin_residual as f64) < mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual is good).
    score -= 40.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Aggressive 2-step lookahead: perfect chain fit if next item exactly fills post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect two-item completion
        } else if next_item_size <= post_residual {
            let frac = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * frac; // partial lookahead reward, scaled by fit quality
        } else {
            // Next item cannot fit here: penalize wasted space proportional to gap.
            score += 15.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize creating unusable dead space (< smallest plausible item) unless bin nearly full.
    if post_residual > 0 && post_residual < 5 {
        score += 30.0;
    }

    // Mild penalty for leaving large slack late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: make empty bins moderately unattractive unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 25.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (waste minimization core).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio;

    // Penalize very small dead space lightly, but reward "perfect" fits hard.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 10.0;
    } else if post_residual > 50 {
        // Large leftover space after placing: this bin was roomy; mild penalty
        // so we prefer bins that will be well-filled.
        score += 0.2 * (post_residual as f64 - 50.0);
    }

    // Lookahead: if the next item fits exactly into the post-residual, big bonus.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits, but leaves a gap: partial reward proportional to fill.
            score -= 15.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here: slight penalty for creating awkward residual.
            score += 5.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty so that
    // reasonable fits into open bins win, but a good deal if fits are poor.
    if bin_residual == bin_capacity {
        score += 20.0;
        // Early in the stream, opening bins is cheap; later, expensive.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 30.0 * progress;
        // If many bins are already open, discourage opening yet another.
        score += 2.0 * open_bins_count as f64;
    }

    // Global state coupling: prefer bins whose residual is below the mean
    // (i.e., tighten up the emptier bins less aggressively).
    if bin_residual as f64 > mean_residual {
        score += 0.05 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.05 * (mean_residual - bin_residual as f64);
    }

    // Slight time-horizon adaptation: as the stream progresses, prioritize
    // minimizing immediate waste more than preserving flexibility.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * 0.1 * post_residual as f64;
    score -= progress * 0.1 * item_size as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer small post-residual (tight fit), mildly non-linear
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Smooth coupling: tight fits matter more as the stream progresses
    let tightness = 1.0 - pr / cap;
    score -= progress * 12.0 * tightness * tightness;

    // Penalize dead space (very small post residual is good; mid-range residual is wasteful)
    let waste = (pr / cap - 0.5) * (pr / cap - 0.5);
    score += 8.0 * waste;

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Prefer bins with below-mean residual (consolidate space)
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if ns <= pr {
            score -= 6.0 * (1.0 - (pr - ns) / cap);
        } else {
            score += 5.0 * (ns - pr) / cap;
        }
    }

    // Mild new-bin preference when few bins fit and item is large
    let is_new = bin_residual == bin_capacity;
    if is_new {
        score += 3.0 - 4.0 * (item_size as f64 / cap) - progress * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on residual space
    let pr = post_residual;
    let class = pr % 10;
    // Dead space penalty: residuals in awkward classes (small non-zero leftovers)
    if pr > 0 && pr < 10 {
        score += 40.0; // tiny unusable slivers
    } else if class == 0 {
        score -= 30.0; // perfectly divisible residual, great for future harmonic items
    } else if class <= 2 {
        score += 10.0;
    }

    // Reward tight fits (small post_residual but not dead)
    let tightness = 1.0 - (pr as f64) / cap;
    score -= 25.0 * tightness * tightness;

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 60.0;
        } else if next_item_size <= pr {
            score -= 15.0 * (1.0 - (pr - next_item_size) as f64 / cap);
        } else {
            // next item won't fit here; residual likely wasted
            score += 8.0 * (pr as f64) / cap;
        }
    }

    // Last-chance bonus: only bin that fits the item
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a bin is penalized unless current fit is bad
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fit_quality = (bin_capacity - item_size) as f64; // residual if placed here
        let bad_fit = fit_quality < 15.0 || (next_item_size > 0 && next_item_size > fit_quality && next_item_size <= bin_capacity);
        if bad_fit {
            score -= 45.0 + 20.0 * (1.0 - progress);
        } else {
            // prefer reusing open bins; penalize new bin, more so when many open
            score += 35.0 + 2.0 * open_bins_count as f64;
        }
    }

    // Mean residual coupling: prefer bins deviating favorably from mean
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Slight preference for fuller bins late in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 10.0 * (1.0 - (bin_residual as f64) / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (1..12) are heavily penalized
    // so that a fresh empty bin (post_residual = capacity - item, typically large)
    // is preferred over leaving a sliver of waste.
    if post_residual > 0 && post_residual < 12 {
        score += (12 - post_residual) as f64 * 8.0;
    }

    // Perfect fit reward: zero waste gets a strong bonus.
    if post_residual == 0 {
        score -= 10.0;
    }

    // Open-bin pressure: mildly discourage spreading across many bins,
    // but keep the weight small so dead-space logic dominates.
    score += open_bins_count as f64 * 0.5;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // Lookahead coupling: if the next item could exploit the post residual,
    // soften the dead-space penalty slightly.
    if next_item_size > 0 && post_residual > 0 && next_item_size <= post_residual {
        score -= 3.0;
    }

    // Slight preference for bins below the mean residual (balancing loads).
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.8;
        if post_residual as i64 == next_item_size as i64 {
            score -= 50.0; // perfect two-item chain
        }
        // penalize leaving dead space too small for next item
        if post_residual < next_item_size && post_residual > 0 {
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
    }

    // Relative to mean residual: prefer tighter-than-average bins
    score += (mean_residual - post_residual as f64) * 0.3;

    // Last-chance bin bonus: avoid opening new bin when only one fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Penalize new bin opening unless item is large or no good fit exists
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (bin_capacity - item_size) as f64;
        score = waste * (1.0 + 0.2 * (1.0 - progress));
        if next_item_size > 0 && next_item_size <= post_residual {
            score += 30.0; // new bin chains well with next item
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: smaller post_residual relative to capacity is better.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful for typical items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, strongly reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // Next item won't fit here; mild penalty proportional to overshoot.
            let over = (next_item_size - post_residual) as f64;
            score += 5.0 * (over / 100.0);
        }
    }

    // Last-chance bin: strongly prefer using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global pressure: many open bins relative to a full residual mean -> prefer filling existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64) / (1.0 + mean_residual / 10.0);
    score += 3.0 * pressure * (0.5 + progress);

    // Penalize placing into bins whose residual deviates wildly from the mean (fragmentation control).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for larger residual bins early, tighter bins late.
    score += (1.0 - progress) * 0.02 * (bin_residual as f64);
    score -= progress * 0.02 * (bin_residual as f64);

    // New-bin candidate: make it attractive only when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 10.0;
        // But if the current bin would leave very tight post residual elsewhere... handled above.
        if fitting_bins_count <= 1 {
            score -= 12.0; // opening a bin is fine when alternatives are scarce
        }
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can absorb the next item too; small bonus early on.
            score -= 8.0 * (1.0 - progress);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let is_new_bin = (bin_residual as f64 - cap).abs() < 1e-9;

    // Base: prefer small post_residual, with non-linear compression of large residuals.
    let mut score = post - 0.6 * (post * post) / cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // later in the stream, small residuals matter more (dead space is costlier).
    let progress_weight = 0.5 + 1.5 * progress * progress;
    score += progress_weight * (post / cap) * (1.0 - post / cap) * cap * 0.3;

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if post >= nxt {
            let slack = (post - nxt) / cap;
            score -= 4.0 * (1.0 - slack * slack) * (1.0 - 0.5 * progress);
        } else {
            // penalize residuals that just barely exclude the next item
            let miss = (nxt - post) / cap;
            score += 2.0 * miss * (2.0 - miss);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 6.0 * (1.0 - post / cap);
    }

    // Penalize new-bin candidate, more strongly when open bins exist and fit.
    if is_new_bin {
        score += 8.0 + 2.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
    } else if fitting_bins_count > 1 {
        // mild tie-break: prefer bins already deviating from mean residual
        score += 0.05 * (post - mean_residual).abs();
    }

    // Reward near-perfect fits smoothly.
    let tightness = 1.0 - post / cap;
    score -= 3.0 * tightness * tightness * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: post_residual / 10 buckets.
    let class = post_residual / 10;
    // Penalize leftovers in "dead" classes (small, hard-to-fill remainders).
    let dead_penalty: f64 = match class {
        0 => 14.0,           // post_residual < 10: nearly unusable
        1 => 6.0,            // 10..19
        2 => 3.0,            // 20..29
        3 | 4 => 0.0,        // mid-range, useful
        5 | 6 => -1.5,       // 50..69 pairs well with mid items
        _ => -2.5,           // large leftovers still flexible
    };
    score += dead_penalty;

    // Perfect-fit harmonic classes: leftover that exactly matches common item sizes.
    let perfect: [u32; 8] = [0, 10, 20, 30, 40, 50, 60, 80];
    if perfect.contains(&post_residual) {
        score -= 4.0;
    }

    // Lookahead coupling: reward leftovers that exactly fit the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 8.0;
        } else if post_residual >= next_item_size && post_residual < next_item_size + 10 {
            score -= 3.0;
        } else if post_residual < next_item_size {
            // next item cannot go here; slight penalty proportional to mismatch
            score += 0.05 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin unless the item fits poorly
    // everywhere else. Empty-bin baseline sits above well-packed placements.
    if bin_residual == bin_capacity {
        score += 25.0;
        // Early in the stream, keep few bins; late, allow opening more freely.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
        // If the item is large relative to capacity, a fresh bin is reasonable.
        score -= 0.1 * item_size as f64;
    }

    // Prefer bins with below-mean residual (tighter packing target).
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 4 {
        score -= 0.3 * open_bins_count.min(20) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10.0 - post_residual as f64);
    }
    // Perfect fit is heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Tightness bonus: reward filling a large fraction of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill_ratio;

    // Last-chance pressure: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, prefer new bin
    // only when fit is poor; scale penalty with bin count.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - fill_ratio);

    // Lookahead: if the next item fits exactly into the post-residual, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual {
            // next item cannot use the leftover: penalize dead space more
            score += 8.0 * (post_residual as f64 / 10.0).min(1.0);
        }
    }

    // Mean residual coupling: prefer bins below mean residual (tighter bins)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: a fresh bin is attractive only when no open
    // bin fits well (large fill ratio elsewhere would beat it anyway).
    if bin_residual == bin_capacity {
        score += 20.0 + 2.0 * open_bins_count as f64 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good.
    score -= (bin_capacity as f64 - post_residual as f64) * 0.3;

    // 2-step lookahead: reward if the next item also fits in the leftover space.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Chain fit: excellent, strong reward scaled by how snugly it fits.
            let slack_after_next = post_residual as f64 - next_item_size as f64;
            score -= 25.0 + (next_item_size as f64) * 0.5 - slack_after_next * 0.2;
        } else {
            // Leftover dead space relative to next item: penalize proportionally.
            let dead = next_item_size as f64 - post_residual as f64;
            score += dead * 0.8;
        }
    }

    // Compare against mean residual: bins already below mean waste potential;
    // prefer placing into bins with residual above mean (keeps mean low bins for later).
    if (bin_residual as f64) > mean_residual {
        score -= 5.0;
    } else {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when existing bins can fit, unless the fit is perfect.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty so it loses to decent fits,
        // but allow it when the item fills it exactly or near-exactly.
        score += 60.0;
        if item_size >= bin_capacity - 5 {
            score -= 100.0;
        }
        // Late in stream, opening fresh bins is safer than fragmenting.
        if next_item_size > 0 && post_residual < next_item_size {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += open_bins_count as f64 * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits (small dead space)
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 50.0 * (10.0 - post_residual as f64);
    }

    // Penalize large waste relative to capacity
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * waste_frac * waste_frac;

    // Lookahead: bonus if next item fits in the post residual
    if next_item_size > 0 {
        if next_item_size as f64 <= post_residual as f64 {
            score -= 20.0 + 0.5 * next_item_size as f64;
        } else {
            // Penalize leaving residual too small for next item (dead space)
            score += 15.0 * (1.0 - (post_residual as f64 / next_item_size.max(1) as f64).min(1.0));
        }
    }

    // Last-chance bin: strong bonus to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 40.0;
    }

    // Many fitting bins: mild penalty for using a crowded-fit bin, prefer tight fits
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0);
    }

    // Time horizon: later in stream, be more conservative; early, explore new bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early, less attractive late
        score -= 25.0 * (1.0 - progress);
        // Penalize opening new bins when many open bins already exist late
        score += 1.5 * open_bins_count as f64 * progress;
    } else {
        // Favor existing bins more strongly as stream progresses
        score -= 10.0 * progress;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bin)
    score += 0.3 * (mean_residual - bin_residual as f64);

    // Prefer bins whose residual is close to item size (minimize fragmentation)
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.2 * fit_gap;

    // Penalize very small post-residuals that no typical item can use
    if post_residual > 0 && post_residual < 5 {
        score += 60.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear shaping
    let mut score = norm_pr * (1.0 + 2.0 * norm_pr * norm_pr);

    // Smooth coupling of post_residual with stream progress:
    // late in the stream, dead space becomes more costly
    score += norm_pr * (0.5 + 2.5 * progress * progress) * (1.0 - norm_pr);

    // Penalize wasting a near-full bin when post_residual is tiny but nonzero
    if post_residual > 0 && post_residual < 10 {
        score += 3.0 * (1.0 - progress);
    }

    // Reward last-chance bins (only fitting bin) more strongly as stream progresses
    if fitting_bins_count == 1 {
        score -= 4.0 + 6.0 * progress;
    } else if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0).ln() * (1.0 + progress);
    }

    // Lookahead: if next item fits perfectly into post_residual, big reward
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            score -= 3.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 1.5 * (nxt - pr) / cap;
        }
    }

    // Coupling with mean residual: prefer bins deviating smoothly from mean
    let dev = (pr - mean_residual) / cap;
    score += 0.8 * dev * dev * (1.0 + progress);

    // Mild penalty for spreading across many open bins
    score += (open_bins_count as f64).ln().max(0.0) * 0.3 * norm_pr;

    // New-bin candidate: neutral base so it's chosen only when open bins score poorly
    if bin_residual == bin_capacity {
        score += 2.0 + 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity-fraction bands.
    let post_frac = post_residual as f64 / cap;
    let quarter = (post_residual * 4) / bin_capacity; // integer division class 0..4

    // Penalize dead space: tiny post_residual that nothing (>=1..100) can use well.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Modulo arithmetic on residual classes (harmonic 20-unit grid)
    let class_mod = post_residual % 20;
    score += (class_mod as f64) * 0.8;

    // Reward perfect / large usable residuals
    if post_residual == 0 {
        score -= 40.0;
    }
    match quarter {
        0 => score -= 5.0,                 // nearly full bin: good packing
        1 => score += 3.0,                 // 0-25% left: dead-space risk
        2 => score -= 2.0,                 // 25-50%: moderate
        3 => score -= 8.0,                 // 50-75%: roomy
        _ => score -= 12.0,                // >75%: very roomy (but check new-bin)
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 55.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 70.0;
        } else if next_item_size <= post_residual {
            // harmonic class match: next item leaves a further usable residual
            let nxt_post = post_residual - next_item_size;
            if nxt_post % 20 == 0 || nxt_post == 0 {
                score -= 25.0;
            } else {
                score -= 10.0;
            }
        } else {
            // next item won't fit here; slight penalty if this residual becomes waste
            if post_residual < 10 {
                score += 20.0;
            }
        }
    }

    // New-bin candidate handling: empty bin gets a baseline anchored to mean residual.
    if bin_residual == bin_capacity {
        // Prefer a new bin when open bins are crowded and item is large.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = cap * 0.55
            + (item_size as f64) * 0.3
            + (open_bins_count as f64) * 1.5
            - mean_residual * 0.4
            - progress * 5.0;
        // Discard new bin if it is the only option anyway (fitting_bins_count==0 handled by caller),
        // and discourage opening when a last-chance bin exists elsewhere.
        if fitting_bins_count <= 1 {
            score += 45.0;
        }
    }

    // Tie-break: prefer tighter fit (smaller post_residual) with mild nonlinearity.
    score += (post_frac * post_frac) * 10.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold even the
    // smallest plausible item (1..10) are pure waste; punish them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 * (10.0 - post_residual as f64);
    }

    // Perfect fit is the ideal outcome.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Reward bins whose residual is "consumed" by this item relative to mean fill.
    score -= (bin_residual as f64 - mean_residual) * 0.15;

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage opening another.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let new_bin_penalty = 6.0 + 10.0 * (open_bins_count as f64 / 20.0).min(1.0) + 8.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    } else {
        score -= 2.0; // mild preference for using an existing open bin
    }

    // Lookahead coupling: if the next item would fit into the post residual,
    // this placement chains nicely; reward it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // If post residual is nonzero but too small for the next item, slight penalty.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), scaled by mean residual context.
    score += 0.3 * (mean_residual - post_residual as f64);

    // 2-step lookahead: strongly reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 25.0 + 0.5 * next_item_size as f64;
    } else if next_item_size > post_residual {
        // Penalize creating dead space the next item cannot use.
        score += 8.0 + 0.4 * (next_item_size as f64 - post_residual as f64);
    }

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual < 10 {
        score -= 12.0;
    } else if post_residual < 20 {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, avoid wasting it on a bad fit.
    if fitting_bins_count == 1 {
        if post_residual <= 10 {
            score -= 10.0;
        } else {
            score += 6.0;
        }
    }

    // Late in the stream, prefer consolidating into existing bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * post_residual as f64;

    // Discourage opening new bins when existing bins already fit well.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.2 * mean_residual;
        if fitting_bins_count > 0 {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small post-residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 40.0 * (1.0 - tightness * tightness);

    // Penalize dead space that is too small to be useful later (below min item size 1..100 unknown, use ~20).
    if post_residual > 0 && post_residual < 20 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= 15.0;
        } else {
            score += 10.0; // next item won't fit here; slight penalty
        }
        // Bonus if post-residual + next item leaves a nicely reusable gap
        let gap = post_residual.saturating_sub(next_item_size);
        if gap > 0 && gap < 10 {
            score -= 8.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Prefer bins with residual below the mean (consolidate waste into few bins).
    score += 0.15 * (bin_residual as f64 - mean_residual);

    // Time horizon: early on, be more willing to open new bins (explore); later, pack tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize early (encourage using open bins), discount late.
        score += 20.0 * (1.0 - progress) - 5.0 * progress;
        // But if item is huge relative to mean residual of open bins, opening new bin is fine.
        if (item_size as f64) > mean_residual {
            score -= 15.0;
        }
    }

    // Many open bins: encourage filling existing ones harder.
    score += 0.05 * open_bins_count as f64 * (bin_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: post residual, with non-linear polynomial shaping
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Stream-progress coupling: late in stream, penalize large residuals more
    let prog_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream at 1
    score += 20.0 * norm_pr * (1.0 + prog_term);

    // Tight fit reward (smooth): strongly favor small post_residual
    score -= 30.0 * (-2.0 * norm_pr).exp();

    // Lookahead: reward if next item fits the post residual (smooth polynomial)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            let fit_ratio = nx / pr.max(1.0);
            score -= 15.0 * fit_ratio * (1.0 - fit_ratio) * 4.0;
        } else {
            let gap = (nx - pr) / cap;
            score += 10.0 * gap * gap;
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Mean residual coupling: penalize bins far below mean residual (fragmentation)
    let dev = (pr - mean_residual) / cap;
    score += 8.0 * dev * dev;

    // Many open bins: prefer filling existing bins over spreading
    score += (open_bins_count as f64).ln().max(0.0) * 2.0 * norm_pr;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity fractions.
    let c = bin_capacity as f64;
    let pr = post_residual;
    let prf = pr as f64;

    // Reward tight fits (small post_residual) non-linearly.
    if pr == 0 {
        score -= 60.0; // perfect fit
    } else {
        // Quadratic dead-space penalty, amplified for "awkward" residuals.
        score += (prf * prf) / c;
        // Harmonic classes: residuals divisible by small integers are more reusable.
        let div_bonus = if pr % 10 == 0 { 12.0 }
            else if pr % 5 == 0 { 6.0 }
            else if pr % 2 == 0 { 3.0 }
            else { 0.0 };
        score -= div_bonus;
        // Prime / odd residuals are dead space traps.
        if pr > 0 && pr % 2 == 1 && pr < 10 {
            score += 8.0;
        }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 && next_item_size <= pr {
        let slack = (pr - next_item_size) as f64;
        score -= 10.0 + 20.0 / (1.0 + slack); // reward chain-ability
        // Harmonic match: next item lands on a class boundary
        if (pr - next_item_size) % 10 == 0 {
            score -= 5.0;
        }
    } else if next_item_size > pr && pr > 0 {
        // post_residual too small for next item: penalize proportionally
        score += (next_item_size - pr) as f64 * 0.3;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin.
        score += c * 0.9;
        // Justified when item is large or no good open bin exists late in stream.
        let progress = step_index as f64 / total_items.max(1) as f64;
        if item_size >= 60 { score -= 40.0; }
        if post_residual >= 40 { score -= 10.0; }
        if open_bins_count == 0 { score -= c as f64; }
        if progress > 0.8 { score -= 5.0; }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins).
    score += (prf - mean_residual).max(-20.0) * 0.1;

    // Slight favoritism toward fuller bins as stream progresses.
    let fill = (bin_capacity - bin_residual) as f64 / c;
    score -= fill * 5.0 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 * (10 - post_residual) as f64;
    }
    // Perfect fit is strongly rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual tightly matches the item (small waste ratio).
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * waste_ratio;

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading to fresh bins.
    score += 2.0 * open_bins_count as f64;
    // New-bin candidate penalty grows with stream progress and open bins.
    if bin_residual == bin_capacity {
        score += 15.0 + 3.0 * open_bins_count as f64
            + 20.0 * (step_index as f64 / (total_items.max(1) as f64));
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    // If next item leaves an even worse dead gap, penalize.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap > 0 && gap < 10 {
            score += 20.0;
        }
    }

    // Prefer bins below the mean residual slightly (use up emptier bins first).
    score -= 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect match (small slack) -> graded reward
    else if next_item_size > 0 && post_residual > next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack <= 10.0 {
            score -= 40.0 * (1.0 - slack / 10.0);
        } else {
            // residual too big to matter for next item; penalize dead space growth
            score += slack * 0.15;
        }
    }
    // Next item cannot fit in leftover: dead space penalty scaled by size of waste
    else if next_item_size > 0 && post_residual < next_item_size {
        let waste = (next_item_size - post_residual) as f64;
        score += waste * 0.5;
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 0.3;

    // Discourage opening a new bin early in the stream unless residual is truly unusable
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let unusable = next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) as u32;
        if !unusable {
            score += 35.0 + 40.0 * (1.0 - progress);
        } else {
            score -= 5.0;
        }
        // more open bins => new bin slightly cheaper relative to fragmentation
        score += open_bins_count as f64 * 0.5;
    }

    // Mild penalty for very tiny leftovers (hard to fill later)
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 1.2;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect and near-perfect fits
    if post_residual == 0 {
        score -= 30.0;
    } else if post_residual <= 10 {
        score -= 12.0;
    }

    // Penalize creating awkward dead space (leftover smaller than typical items)
    if post_residual > 0 && post_residual < item_size.min(50) {
        score += 4.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Lookahead (k=2): reward leaving space for the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size as u32 {
            score -= 10.0;
        } else if post_residual > 0 {
            score += (next_item_size as f64).min(post_residual as f64 + 20.0) * 0.1;
        }
    }

    // Mild preference for bins that are already fuller (more utilized)
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        score -= 2.0; // slight baseline appeal of fresh capacity
        if fitting_bins_count == 0 {
            score -= 10.0; // no open bin fits: new bin is necessary
        }
        if open_bins_count as f64 > mean_residual {
            score += 1.0; // many open bins with slack: discourage proliferation
        }
    }

    // Dynamic time horizon: consolidate more aggressively as stream progresses
    let t = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * t;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let mut score = pr;

    // Non-linear waste penalty: dead space that is too small to matter vs. large unusable gaps
    score += 12.0 * norm_pr * norm_pr * (1.0 + progress);

    // Reward tight fits (post_residual near 0) with smooth quadratic bonus
    score -= 8.0 * (1.0 - norm_pr) * (1.0 - norm_pr);

    // Coupling with mean residual: prefer bins whose residual deviates favorably from mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 6.0 * dev * dev - 4.0 * dev;

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - norm_pr);
    }

    // New-bin candidate handling: penalize opening a new bin unless no open bin fits
    if bin_residual == bin_capacity {
        let open_penalty = if fitting_bins_count == 0 { -10.0 } else { 40.0 + 30.0 * (1.0 - progress) };
        score += open_penalty;
    } else {
        // Favor using existing bins, more aggressively as stream progresses
        score -= 5.0 * progress;
    }

    // Lookahead coupling: if next item fits in the resulting residual, reward it smoothly
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        let fit_margin = pr - ns;
        if fit_margin >= 0.0 {
            score -= 6.0 * (fit_margin / cap).tanh();
        } else {
            score += 2.0 * (-fit_margin / cap).tanh();
        }
    }

    // Mild pressure to consolidate when many bins are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5 * (1.0 - norm_pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) nonlinearly.
    score -= 40.0 * (-post_residual as f64 / 12.0).exp();

    // Harmonic class: post_residual mod 10 — small residues (<10) are dead space
    // under the min item size of 10, but sizes may be 1..100; penalize only
    // residues below the plausible minimum item size.
    let dead_threshold = 4.0;
    if (post_residual as f64) < dead_threshold {
        score += 30.0 * (dead_threshold - post_residual as f64);
    }

    // Prefer bins whose post_residual can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 15.0 + 0.5 * (post_residual - next_item_size) as f64;
        } else {
            score += 10.0 * (next_item_size - post_residual) as f64 / cap;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current bins are
    // heavily fragmented (high mean residual spread) or many bins already open.
    if bin_residual == bin_capacity {
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        score += 20.0 - 15.0 * fragmentation;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild preference to fill older bins first (reduce open bin count).
    score += 0.3 * open_bins_count as f64;

    // Late in the stream, tolerate slightly larger residuals less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * progress * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item (1..100 stream, but typical items >= 10) are wasted.
    // Penalize hard when post_residual falls into an "unusable gap".
    if post_residual > 0 {
        if post_residual < 10 {
            // Completely dead space -> heavy penalty.
            score += 60.0;
        } else if post_residual < 20 {
            // Narrow gap: usable only by tiny items.
            score += 25.0;
        } else if post_residual < 35 {
            score += 8.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward bins whose residual after placement still accommodates the
    // lookahead item (chaining good fits).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Placement leaves a gap the next item cannot use.
        score += 6.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing bins rather than spreading out; also penalize bins far from
    // the mean residual (fragmentation signal).
    score += open_bins_count as f64 * 0.8;
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin, unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: an empty bin is only attractive when no
    // open bin offers a decent fit. Make the empty-bin baseline high so it
    // loses against reasonable existing fits, but low enough to win when
    // every open bin would create dead space.
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score = 55.0 + pressure * 0.5 - (mean_residual / bin_capacity as f64) * 20.0;
        // Late in the stream, opening fresh bins is less attractive.
        score += (step_index as f64 / total_items.max(1) as f64) * 15.0;
        // If a lookahead item is large, a fresh bin is more valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

