    let dead = post_residual as f64 / bin_capacity as f64;
    score += dead * dead * 20.0;

    // Penalize opening a new bin when open bins could fit (empty-bin candidate).
    if bin_residual == bin_capacity {
        score += 15.0 + fitting_bins_count as f64 * 5.0;
    }

    // Mild late-stream consolidation pressure.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0;

