        // matter less) and with many open bins (fragmentation already high).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 35.0 - 20.0 * progress + 1.5 * open_bins_count as f64;
        // If item is large relative to capacity, a fresh bin is more attractive.
        score -= 0.25 * item_size as f64;
    } else {
        // Favor bins whose residual is below the mean residual (more "used" bins),
        // consolidating occupancy instead of spreading.
        score -= 0.15 * (mean_residual - bin_residual as f64);
    }

    // Mild global pressure: when many bins are open, prefer packing tighter
    // to encourage closing bins out.
    score -= 0.05 * open_bins_count as f64 * fill_ratio;

    // Late-stream tightening: as we approach the end, waste matters more.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Core: wasted space, penalized super-linearly (dead space grows quadratically in cost).
    let mut score = post * (1.0 + 0.9 * (post / cap).powi(2));

    // Smooth non-linear coupling with stream progress:
    // early on, tolerate slack; late in the stream, punish residual waste harder.
    let late_pressure = 0.5 + 0.5 * (progress * std::f64::consts::PI).sin();
    score += 12.0 * late_pressure * (post / cap);

    // Reward near-perfect fits smoothly (tanh coupling of fill ratio).
    let fill = item / cap;
    score -= 10.0 * ((fill * std::f64::consts::PI - std::f64::consts::FRAC_PI_2).tanh()) * (1.0 - post / cap);

    // Lookahead: if the next item fits the post-residual, reward leaving useful space.
    if next_item_size > 0 && (next_item_size as f64) <= post {
        score -= 6.0 * (1.0 - (post - next_item_size as f64) / cap);
    } else if next_item_size > 0 {
        // Next item won't fit here; gently penalize leaving awkward medium gaps.
        score += 3.0 * (post / cap) * (1.0 - late_pressure);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 * (1.0 - post / cap);
    }

    // New-bin candidate handling: an empty bin gets a moderate default score;
    // it should win only when open bins would leave large unusable gaps.
    if bin_residual == bin_capacity {
        score = 0.55 * cap + 0.25 * mean_residual * late_pressure - 2.0 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual is already below the mean (consolidating waste).
        score += 1.5 * ((post - mean_residual) / cap).max(-2.0).min(2.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: classify post_residual into capacity fraction buckets.
    // Small post_residual => good packing; penalize large leftover space.
    let frac = post_residual as f64 / bin_capacity as f64;
    // Class thresholds: 0 (perfect), <=10, <=25, <=50, >50
    if post_residual == 0 {
        score -= 60.0; // perfect fill
    } else if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 15.0;
    } else if post_residual <= 50 {
        score += 10.0;
    } else {
        score += 30.0 + frac * 40.0;
    }

    // Lookahead: reward if next item can fit into post_residual (chaining).
    if next_item_size > 0 && next_item_size <= post_residual {
        // Harmonic bonus scaled by how snugly next item fits.
        let slack = post_residual - next_item_size;
        score -= 25.0 - (slack as f64).min(25.0);
        if slack == 0 {
            score -= 15.0; // perfect chain
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item cannot use leftover; dead-space penalty for large leftovers.
        if post_residual > 30 {
            score += 12.0;
        }
    }

    // Last chance: this is the only bin that fits; strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (penalize opening new bins otherwise; encourage when open bins are crowded).
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 45.0; // must open new bin
        } else {
            // discourage opening new bin if existing bins fit decently
            score += 20.0 + mean_residual * 0.3;
        }
    }

    // Progression: late in stream, be slightly greedier with existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    // Mild preference to balance load across many open bins.
    if bin_residual < bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 4.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item.max(1) {
        score += 1000.0;
    }
    // Gaps too small for the smallest plausible item are dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 8.0;
    }

    // Reward near-perfect fits (post_residual close to 0 but usable).
    if post_residual == 0 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 40.0;
    }

    // Prefer bins whose residual is well-matched to the item (tight packing).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.5;

    // Open-bin pressure: discourage spreading across too many bins.
    score += open_bins_count as f64 * 1.5;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 - slack * 0.2;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item can't use the leftover: this bin is likely to become dead space.
        score += 15.0;
    }

    // Mild mean-residual coupling: prefer bins below mean residual (tighter bins).
    score += (mean_residual - bin_residual as f64) * 0.1;

    // New-bin candidate: only attractive when item is large relative to capacity
    // and no tight fit exists; make empty bin mildly unattractive by default.
    if bin_residual == bin_capacity {
        score += 30.0 - (item_size as f64 / bin_capacity as f64) * 40.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // ---- 2-step lookahead: reward bins whose post_residual matches next item ----
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Perfect 2-chain: post_residual exactly consumed by next item
            score -= 60.0 + 30.0 * (1.0 - progress);
        } else if post_residual > next_item_size {
            // Next item still fits after this placement; reward tight coupling
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / bin_capacity as f64);
            // Extra reward if the chain closes the bin completely in 2 steps
            if post_residual - next_item_size == 0 {
                score -= 20.0;
            }
        } else {
            // Next item cannot use the post_residual: dead space risk
            let gap = (next_item_size - post_residual) as f64;
            // Penalize proportionally, but less if gap is small (may fit later items)
            score += 0.4 * gap * (0.5 + progress);
        }
    } else {
        // Last item: strongly prefer minimal post_residual (tight packing)
        score += 0.2 * post_residual as f64;
    }

    // ---- Relative-to-mean coupling: prefer bins that get closer to average fill ----
    // Placing here should move residual toward the mean; reward if post_residual near mean
    let mean_gap = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // ---- Last-chance bin: if this is the only fitting bin, avoid opening a new bin ----
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // ---- New-bin candidate handling ----
    if bin_residual == bin_capacity && bin_capacity > 0 {
        // Opening a new bin is only attractive when:
        //  - no open bin fits well (post_residual after placement elsewhere would be tiny)
        //  - or the item is large and would leave a nearly full existing bin
        // Base cost of opening a new bin (waste of potential capacity):
        score += 45.0;
        // Discount the cost if the item is large (large items in fresh bins are natural)
        score -= 0.3 * item_size as f64;
        // If there are few fitting bins and existing bins would leave bad residuals,
        // opening a new bin becomes competitive. Approximate badness via mean_residual:
        // high mean residual means open bins are quite empty -> prefer them, penalize new bin
        score += 0.25 * mean_residual;
        // Late in the stream, slightly discourage opening bins (less time to fill them)
        score += 15.0 * progress;
        // If next item is large and would fit in a fresh bin alongside this item,
        // encourage the new bin (2-chain into fresh bin)
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 10.0;
        }
    }

    // ---- Small global tie-breaker favoring tighter bins (smaller residual) ----
    score += 0.05 * bin_residual as f64;

    // ---- Mild open-bin count pressure: keep bin count controlled ----
    score += 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of stream completed.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: quadratic bonus for small post_residual.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize dead space that no plausible future item can use.
    // Items are <= 100, so residual >= 100 is wasted; residual in [1, small] is reusable.
    if post_residual > 0 && post_residual < 10 {
        score -= 3.0; // small usable gap is valuable
    }
    if post_residual > 80 {
        score += 0.5 * (post_residual as f64 - 80.0); // large gap fine only if bin new
    }

    // Lookahead: reward if next item fits in post_residual (pairing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 6.0;
            // Perfect chain: next fills almost exactly.
            let gap_after_next = post_residual as i64 - next_item_size as i64;
            score -= 2.0 * (1.0 - gap_after_next as f64 / bin_capacity as f64);
        } else if next_item_size <= bin_residual {
            // Next item fits now but not after placing current: mild penalty
            score += 2.0;
        }
        // If lookahead can't fit anywhere after this placement, prefer tight fill now.
        if next_item_size > post_residual && post_residual < next_item_size && post_residual > 0 {
            score += 1.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: empty bin gets a baseline penalty that shrinks
    // as the stream progresses or when many bins are already open (amortization).
    if bin_residual == bin_capacity {
        let open_penalty = 12.0 * (1.0 - 0.5 * t);
        let crowding = (open_bins_count as f64).ln().max(0.0);
        score += open_penalty + 0.5 * crowding;
        // But if current item is large and no bin is tight, opening is fine.
        if item_size >= 60 && mean_residual < item_size as f64 {
            score -= 6.0;
        }
    } else {
        // Reward placing into bins whose residual is close to mean (balance),
        // slightly stronger early when many choices exist.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev * (1.0 - t);
    }

    // Prefer filling bins with the smallest residual overall (best-fit core),
    // scaled by how many alternatives exist.
    score += 0.03 * bin_residual as f64 * (fitting_bins_count as f64).min(5.0) / 5.0;

    // Late-stream consolidation: push toward closing bins tightly.
    if t > 0.8 {
        score += 0.02 * post_residual as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, prefer tight fills (low post_residual); later, weight dead space more.
    let pr_norm = pr / cap;
    let p2 = pr_norm * pr_norm;
    let g = 1.0 + 2.0 * progress; // grows smoothly from 1 to 3
    score += 18.0 * g * p2 * p2;  // quartic penalty on wasted space, amplified late

    // Reward using bins that are already partially filled, smoothly.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 6.0 * fill * fill * (1.0 + progress);

    // Last-chance bonus: smooth exponential-style reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 + progress);
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: reward residual that still fits the next item, smoothly.
    if next_item_size > 0 {
        let fits = if post_residual >= next_item_size { 1.0 } else { 0.0 };
        score -= 8.0 * fits * (1.0 + 2.0 * progress);
        // Penalize residuals that are close-but-not-fitting next item (dead space risk),
        // as a smooth bump around the mismatch.
        let gap = (post_residual as i64 - next_item_size as i64) as f64;
        if gap < 0.0 && gap > -20.0 {
            score += 4.0 * (1.0 + gap / 20.0) * (1.0 + gap / 20.0);
        }
    }

    // Mild penalty for spreading across many open bins, scaled by mean residual alignment.
    let align = 1.0 - ((mean_residual - pr).abs()) / (cap + 1.0);
    score += 3.0 * (open_bins_count as f64).ln().max(0.0) * align * progress;

    // New-bin candidate: add a fixed opening cost so it only wins when fits are bad.
    if bin_residual == bin_capacity {
        score += 12.0 + 8.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues divisible by small
    // "harmonic" denominators are more likely to be filled by future items.
    let pr = post_residual;
    if pr > 0 {
        let mut harmony = 0.0;
        for &d in &[1u32, 2, 4, 5, 10, 20, 25, 50] {
            if pr % d == 0 {
                harmony += 1.0 / (d as f64).sqrt();
            }
        }
        score -= 6.0 * harmony;
    }

    // Perfect fit: huge reward.
    if pr == 0 {
        score -= 1000.0;
    }

    // Dead space penalty: residuals below the minimum item size (1) can't
    // happen, but small residuals (< 10) are hard to fill exactly.
    if pr > 0 && pr < 10 {
        score += 15.0;
    }

    // Fractional capacity logic: classify post_residual as a capacity fraction.
    let frac = post_residual as f64 / cap;
    if frac > 0.0 && frac < 0.25 {
        score += 8.0 * (0.25 - frac); // penalize tiny unusable slivers mildly
    } else if frac >= 0.5 {
        score -= 4.0 * frac; // roomy bins are attractive
    }

    // Lookahead coupling: if the next item exactly fills the post-residual,
    // strongly favor this bin (creates a perfect chain).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 400.0;
        } else if next_item_size < pr {
            let chain = pr - next_item_size;
            score -= 20.0 / (1.0 + chain as f64);
            // harmonic check on the chained residual
            if chain % 5 == 0 || chain % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot follow in this bin; slight penalty
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a bad
    // fit unless the fit is tight.
    if fitting_bins_count == 1 {
        score -= 12.0;
        if pr <= 10 {
            score -= 10.0;
        }
    }

    // New-bin candidate (empty bin): only prefer it when no open bin gives a
    // tight fit; i.e., penalize the empty bin unless residuals are all large.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        // If mean residual across open bins is close to the item, opening a
        // new bin wastes the existing slack.
        score += 30.0 + 25.0 * (1.0 - mean_gap / cap);
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            // fresh bin pairs well with next item if next is small
            if next_item_size <= 30 {
                score -= 25.0;
            }
        }
        // late in the stream, consolidating matters more
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Prefer spreading across many open bins when mean residual is high.
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest item
    // (or too small to be useful for the lookahead item) are heavily penalized.
    let dead_zone: u32 = 9;
    if post_residual > 0 && post_residual <= dead_zone {
        score += 40.0 * (1.0 + (dead_zone - post_residual) as f64);
    }

    // If the next item could have fit in the post_residual, reward keeping room for it.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Near-miss: residual becomes near-dead for the lookahead item.
        score += 8.0;
    }

    // Reward tight fits (item fills most of the bin).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill * fill;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones; with few bins, opening is cheaper.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline slightly above a perfect fit, modulated by pressure.
        score = bin_capacity as f64 - 20.0 * (1.0 - pressure);
    } else {
        score -= 10.0 * pressure;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity && post_residual <= dead_zone {
        score -= 30.0;
    }

    // Mild progress term: late in the stream, prefer tighter packing overall.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (mean_residual - post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: exact match between post_residual and next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Lookahead coupling: penalize residuals that are too small OR too large for next item
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += gap * 0.45;

        // Reward bins whose post_residual can host the next item at all
        if post_residual >= next_item_size {
            score -= 12.0;
        } else {
            // dead space relative to next item
            score += (next_item_size - post_residual) as f64 * 0.30;
        }
    }

    // Compare against mean residual: prefer bins tighter than average
    let diff = post_residual as f64 - mean_residual;
    score += diff * 0.20;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize creating small unusable slivers (1..=5 units of dead space)
    if post_residual > 0 && post_residual < 6 {
        score += 15.0;
    }

    // Early in the stream, be more willing to spread items (favor low residuals less aggressively)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.15 * (1.0 - progress);

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let base = 55.0 + 0.5 * (open_bins_count as f64);
        // discourage new bins when a decent fit exists elsewhere
        if post_residual == bin_capacity && next_item_size > 0 {
            score = base + (next_item_size as f64) * 0.1;
        } else {
            score = base;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no future item (min size 1, but realistically >= 10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Lookahead: reward if next item fits exactly in the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - slack / (bin_capacity as f64));
        } else {
            // next item won't fit here; slight penalty proportional to overshoot
            let over = (next_item_size - post_residual) as f64;
            score += 8.0 * (over / (bin_capacity as f64));
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 35.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current fit is poor and global residuals are already fragmented
    if bin_residual == bin_capacity {
        let frag = mean_residual / (bin_capacity as f64);
        // penalty grows with fragmentation of open bins; discount early in stream
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * frag - 10.0 * progress;
        // if item is large, new bin keeps big residual flexibility
        if item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Prefer bins whose residual deviates from mean (consolidate fragmentation)
        let dev = ((bin_residual as f64) - mean_residual).abs();
        score += 0.15 * dev;

        // Mild penalty for spreading across too many open bins
        score += 0.5 * (open_bins_count as f64).ln().max(0.0);
    }

    // Time horizon: late in the stream, be greedier (avoid opening bins)
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;

    // Base: post residual, with a non-linear polynomial shaping that
    // penalizes very small post-residuals (wasted space) super-linearly.
    let poly = pr_norm * (1.0 - pr_norm) * (1.0 - pr_norm);
    let mut score = pr * (1.0 + 0.5 * poly);

    // Stream-progress coupling: late in the stream, compactness matters more,
    // so amplify the residual term smoothly.
    score *= 1.0 + 0.8 * progress * progress;

    // Dead-space penalty: post_residual too small for any plausible item
    // is wasted; penalize quadratically as it approaches zero.
    if pr < 10 {
        score += (10.0 - pr as f64) * (10.0 - pr as f64) * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits in the post residual, reward.
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 3.0 * (next_item_size as f64 / cap) * (1.0 + progress);
    } else if next_item_size > 0 {
        // next item won't fit here; slight penalty scaled by leftover size
        score += 0.5 * pr_norm * pr_norm;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 5.0 + 5.0 * progress;
    }

    // Mean-residual coupling: prefer bins whose residual deviates from mean
    // in a way that leaves balanced space (smooth quadratic).
    score += 0.3 * (pr - mean_residual) * (pr - mean_residual) / cap;

    // New-bin candidate: keep it slightly attractive early, discourage later
    // unless current fit is terrible.
    if bin_residual == bin_capacity {
        score = 40.0 + 30.0 * progress - 0.2 * item_size as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fill classes get strong reward
    let pr = post_residual;
    if pr == 0 {
        score -= 40.0; // perfect fill
    } else if pr <= 10 {
        score -= 20.0;
    } else if pr % 10 == 0 {
        score -= 8.0; // clean harmonic residue
    } else {
        // fractional dead-space penalty, steeper for awkward remainders
        let frac = (pr % 10) as f64 / 10.0;
        score += frac * 5.0;
    }

    // Integer-division threshold: does post_residual admit the next item?
    if next_item_size > 0 {
        if pr >= next_item_size {
            // pair bonus scaled by how snugly next item fits
            let snug = (next_item_size as f64) / pr as f64;
            score -= 15.0 * snug;
            // harmonic class match: both sizes in same decade class
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // next item won't fit here: penalize more when post_residual is small
            score += 6.0 + (pr as f64) * 0.05;
        }
        // lookahead size class coupling (integer division thresholds)
        let next_class = next_item_size / 20; // 0..5
        let item_class = item_size / 20;
        if next_class == item_class {
            score -= 2.0;
        } else {
            score += 1.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, unless current bins are very full
    if bin_residual == bin_capacity {
        let pressure = mean_residual / cap_f;
        score = 45.0 + 10.0 * pressure;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 8.0; // big next item: fresh bin may be wise
        }
    } else if (bin_residual as f64) < mean_residual {
        score -= 3.0; // fuller-than-average bin preferred
    }

    // Mild stream-progression regularization
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 2.0 * progress * (post_residual as f64 / cap_f);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (post_residual as f64) >= n {
            // Perfect chain: next item exactly fills the bin.
            let gap = (post_residual as f64 - n) / bin_capacity as f64;
            score -= 30.0 * (1.0 - gap);
        } else {
            // Penalize residuals that are slightly too small for the next item (dead space).
            let waste = (post_residual as f64) / n;
            score += 8.0 * (1.0 - waste).clamp(0.0, 1.0);
        }
    }

    // Tight fit now is good (small post_residual relative to item size).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize creating residuals far below mean (fragmented dead space).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it less attractive unless it enables a perfect chain.
    if bin_residual == bin_capacity {
        let chain = next_item_size > 0 && (post_residual as f64) >= next_item_size as f64
            && (post_residual as f64 - next_item_size as f64) <= 5.0;
        if !chain {
            score += 20.0 + 0.1 * open_bins_count as f64;
        }
    }

    // Early in stream: slightly prefer consolidating into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 5.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: strongly favor bins whose post_residual is small.
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap; // 1.0 = perfect fit
    score -= 40.0 * tightness * tightness;

    // Penalize dead space that no plausible item can use.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let min_item = 1.0;
    if (post_residual as f64) < min_item {
        score -= 15.0; // perfect fill, ideal
    } else if post_residual > 0 {
        // Dead-space penalty grows as stream progresses (less time to reuse space).
        score += 0.05 * (post_residual as f64) * (0.5 + progress);
    }

    // Lookahead: bonus if the next item fits exactly in the post_residual.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size <= post_residual {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item won't fit here; slight penalty for leaving awkward gaps
            score += 0.03 * (post_residual as f64);
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // Prefer fuller bins relative to the fleet average.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when post_residual equals full capacity minus item and open bins are crowded.
    if bin_residual == bin_capacity {
        // Base new-bin cost grows with number of already open bins.
        score += 10.0 + 2.0 * open_bins_count as f64;
        // But if this is the last item, a new bin is pointless unless necessary.
        if next_item_size == 0 && fitting_bins_count > 0 {
            score += 50.0;
        }
        // If item is large and mean residual across fleet is small, new bin is reasonable.
        let mean_fit = mean_residual - item_size as f64;
        if mean_fit < 0.0 {
            score -= 15.0;
        }
    }

    // Mild time-horizon shaping: early in stream, be frugal with open bins.
    score += 0.1 * (1.0 - progress) * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let post_norm = post / cap;

    // Base: prefer tight fits, with a smooth polynomial shaping of post_residual.
    // Quadratic + cubic coupling: very small residuals rewarded superlinearly,
    // mid-range residuals penalized, large residuals mildly acceptable.
    let mut score = post
        - 18.0 * post_norm * (1.0 - post_norm)
        + 30.0 * post_norm * post_norm * (1.0 - post_norm);

    // Stream-progress coupling: early on, keep bins flexible (penalize tiny residuals
    // slightly less, encourage spreading); late, pack tightly (amplify tight-fit reward).
    let tightness = (1.0 - post_norm).clamp(0.0, 1.0);
    let progress_coupling = 12.0 * progress * tightness * tightness - 8.0 * (1.0 - progress) * post_norm;
    score -= progress_coupling;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count <= 1 && bin_residual < bin_capacity {
        score -= 15.0 + 10.0 * (1.0 - progress);
    }

    // Lookahead: if next item fits the post-residual exactly-ish, reward; if next item
    // would be stranded by a near-full residual, penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let waste_after_next = post - nxt;
            score -= 6.0 * (1.0 - waste_after_next / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // New-bin candidate: only attractive when current bin would leave awkward dead space
    // or when many bins are open and mean residual is small.
    if bin_residual == bin_capacity {
        let awkward = post_norm.max(0.0); // for empty bin, post = capacity, so 1.0
        let _ = awkward;
        let mean_tight = (mean_residual / cap).clamp(0.0, 1.0);
        let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
        score = 20.0 + 25.0 * (1.0 - mean_tight) + 15.0 * pressure + 20.0 * (1.0 - progress);
        // If this bin is the only fitting option, opening a new bin is fine.
        if fitting_bins_count == 0 {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual modulo small divisors
    let r = post_residual;
    let m4 = (r % 4) as f64;
    let m8 = (r % 8) as f64;
    let m10 = (r % 10) as f64;

    // Penalize residuals in awkward harmonic classes (dead space prone)
    score += 0.6 * m10 / 10.0;
    score += 0.3 * m8 / 8.0;
    score -= 0.4 * m4 / 4.0;

    // Capacity fraction classes: reward near-full bins
    let frac = r as f64 / bin_capacity as f64;
    if frac <= 0.1 {
        score -= 8.0; // nearly perfect fill
    } else if frac <= 0.25 {
        score -= 3.0;
    } else if frac >= 0.8 {
        score += 4.0; // large dead space unless it fits next item
    }

    // Integer-division thresholds on post_residual vs next item
    if next_item_size > 0 {
        if next_item_size <= r {
            // lookahead fits: strong reward, scaled by how snugly
            let slack = (r - next_item_size) as f64;
            score -= 10.0 + 6.0 * (1.0 - slack / bin_capacity as f64);
            if r % next_item_size == 0 && next_item_size > 0 {
                score -= 2.0; // exact harmonic division
            }
        } else {
            score += 3.0; // next item won't fit here
        }
    } else {
        // last item: just minimize residual
        score -= 5.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: only attractive when no open bin is decent
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score = 55.0 - 20.0 * pressure
            + (open_bins_count as f64) * 0.5
            - (mean_residual / bin_capacity as f64) * 10.0;
        if next_item_size > 0 && next_item_size >= bin_capacity / 2 {
            score -= 10.0; // big next item benefits from fresh bin
        }
        // late in stream, prefer closing out existing bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 8.0 * progress;
    }

    // Mild preference for tighter bins generally
    score += (bin_residual as f64 / bin_capacity as f64) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize post_residuals that are too small
    // to be usable by typical future items (unusable gap < 10).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0; // tiny unusable gap => strong penalty
    } else if post_residual < 20 {
        // gaps 10..19 are usable only by small items; moderate penalty
        score += 12.0;
    } else if post_residual < 35 {
        score += 4.0;
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    }

    // Coupling with mean residual: prefer bins that are already "tight"
    // relative to the fleet average (consolidation).
    score -= (bin_residual as f64 - mean_residual) * 0.3;

    // Open-bin pressure: when many bins are open, discourage opening new bins
    // and encourage filling existing ones (especially the emptiest-feeling gap).
    let pressure = (open_bins_count as f64).ln().max(0.0) * 3.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: add pressure so it's chosen only when fits are bad.
        score += 25.0 + pressure;
        // But if no other bin fits, new bin is the only option anyway.
    } else {
        score -= pressure * 0.5;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 35.0;
        } else if gap < 10 {
            score -= 10.0;
        }
    }
    // If next item would NOT fit in post_residual, mild penalty (dead space ahead).
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0 {
        score += 6.0;
    }

    // Late in the stream, tighten up: fill existing bins more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual != bin_capacity {
        score -= progress * 8.0;
    } else {
        score += progress * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize leaving
    // residuals too small to ever be useful for typical small items.
    let pr = post_residual as f64;
    if post_residual > 0 {
        // dead space penalty: residuals below 10 are nearly unusable
        if post_residual < 10 {
            score += 8.0;
        }
        // reward residuals that can still host mid-size items
        if post_residual >= 10 && post_residual <= 40 {
            score -= 4.0;
        }
    } else {
        // perfect fill is excellent
        score -= 15.0;
    }

    // Aggressive 2-step lookahead: if the next item fits exactly into the
    // post_residual, strongly reward this placement (chain fit).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr - nxt).abs() < 0.5 {
            score -= 20.0;
        } else if pr >= nxt && pr - nxt < 15.0 {
            score -= 10.0;
        } else if pr < nxt && pr > 0.0 {
            // next item won't fit here afterward: mild penalty for blocking
            score += 3.0;
        }
        // bonus if post_residual can hold next item with usable slack
        if pr >= nxt + 10.0 {
            score -= 2.0;
        }
    }

    // Compare against mean residual: filling a bin that is already tight
    // (below mean residual) is good — it consolidates waste.
    if pr < mean_residual {
        score -= 3.0;
    } else {
        score += (pr - mean_residual) * 0.05;
    }

    // Last-chance bin: if this is the only fitting bin, prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when the item is large relative to capacity and no bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalize new bins mildly; escalate when many bins are open
        score += 10.0 + 0.5 * open_bins_count as f64;
        // but if item is huge and would leave awkward residual elsewhere,
        // new bin becomes more acceptable
        if item_size >= 70 {
            score -= 8.0;
        }
        // lookahead: fresh bin with item leaves room for next item
        if next_item_size > 0 && post_residual as f64 >= next_item_size as f64 {
            score -= 6.0;
        }
    }

    // Slight stream-progression bias: late in the stream, be more eager
    // to close bins tightly (waste matters less long-term).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * (bin_capacity as f64 - pr) * 0.02;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio for a dynamic time horizon.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness reward: prefer bins where the item fills a large fraction of residual.
    let tightness = if bin_residual > 0 {
        1.0 - (post_residual as f64) / (bin_residual as f64)
    } else {
        0.0
    };
    score -= 30.0 * tightness;

    // Lookahead: strongly reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        let chain_fit = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= 18.0 + 12.0 * chain_fit;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize dead space that the next item cannot use.
        let waste = (next_item_size as f64 - post_residual as f64).max(0.0);
        score += 0.35 * waste;
    }

    // Last-chance bonus: if this is the only bin that fits, use it before opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize spreading across too many bins when mean residual is already low.
    if open_bins_count > 1 {
        score += 0.8 * (open_bins_count as f64 - 1.0) * (1.0 - mean_residual / bin_capacity as f64);
    }

    // New-bin candidate handling: residual == capacity means an empty bin.
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin when existing bins fit.
        if fitting_bins_count > 0 {
            score += 20.0 + 10.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // But if the item is large, opening a fresh bin keeps future flexibility;
        // relax the penalty as the stream progresses.
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 22.0;
        score -= large_item_bonus * (0.5 + 0.5 * progress);
        // Late in the stream, prefer filling existing bins harder.
        score += 15.0 * progress;
        // If no open bin fits at all, opening a new bin is necessary: strong reward.
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild global pressure: keep scores comparable across bins via mean residual.
    score += 0.15 * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let fill_ratio = 1.0 - pr / cap;

    let mut score = pr;

    // Reward tight fits more strongly as the stream progresses (smooth polynomial coupling).
    let tight = (fill_ratio).powi(3);
    score -= 12.0 * tight * (0.5 + progress);

    // Penalize dead space that is too small to be useful for typical items.
    let dead = ((pr - 20.0).max(0.0) / cap).powi(2);
    score += 8.0 * dead * (1.0 - progress);

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr as u32 >= next_item_size && next_item_size <= 100 {
            let gap = (pr - nxt).abs();
            score -= 6.0 * (1.0 - gap / cap);
        } else {
            score += 4.0 * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    }

    // Prefer bins below the mean residual (keeps residuals balanced).
    score += 0.05 * (mean_residual - pr);

    // New empty bin candidate: make it attractive only when item is large
    // relative to mean residual of open bins, otherwise discourage.
    if bin_residual == bin_capacity {
        let large = item_size as f64 / cap;
        score -= 5.0 * large.powi(2);
        score += 6.0 * (1.0 - large);
        if open_bins_count == 0 {
            score -= 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: small unusable gaps are heavily penalized.
    // A gap is "dead" if it cannot hold even a minimal item (size 1..10).
    let dead_threshold = 10.0;
    if post_residual > 0 && (post_residual as f64) < dead_threshold {
        score += 1000.0; // creating unusable sliver is terrible
    } else if post_residual == 0 {
        score -= 500.0; // perfect fill: strongly reward
    }

    // Penalize medium dead space (gap too small for typical mid-size items)
    if post_residual > 0 && post_residual < 30 {
        score += (30.0 - post_residual as f64) * 3.0;
    }

    // Open-bins pressure: discourage spreading across many open bins;
    // prefer filling existing bins when many are already open.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * 2.0 * (0.5 + progress);

    // Last-chance bonus: if this is the only fitting bin, strongly favor it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 200.0;
    }

    // Lookahead: if next item fits exactly in the post residual, reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 150.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        // next item can't use the gap; penalize leaving large gap it can't use
        score += (post_residual as f64) * 0.5;
    }

    // New-bin candidate handling: empty bin gets a mild penalty so we only
    // open a new bin when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 60.0 + open_bins_count as f64 * 3.0;
        // but if current bin would leave a tiny dead gap, opening new bin wins
        if post_residual > 0 && (post_residual as f64) < dead_threshold {
            score -= 1200.0;
        }
        // or if the gap left would be unusable for the lookahead item
        if next_item_size > 0 && next_item_size > post_residual && post_residual > 0 && post_residual < 30 {
            score -= 80.0;
        }
    }

    // Slight preference for bins whose residual is close to mean (balanced packing)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for a perfect fit now.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post-residual,
    // this bin is a perfect two-item match.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 500.0;
        } else if next_item_size < post_residual {
            // Next item fits too: reward proportionally to how tight it is.
            let tightness = 1.0 - (post_residual - next_item_size) as f64 / post_residual as f64;
            score -= 200.0 * tightness;
        } else {
            // Next item would NOT fit in post-residual: penalize dead space
            // that is too small to be useful (below min plausible size).
            if post_residual < 10 {
                score += 150.0;
            } else {
                score += 0.5 * (next_item_size - post_residual) as f64;
            }
        }
    }

    // Penalize post-residual that is small and unusable relative to typical sizes.
    if post_residual > 0 && post_residual < 10 {
        score += 100.0;
    }

    // Last-chance bonus: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 300.0;
    }

    // Slightly favor bins whose residual is below the mean residual
    // (concentrate packing into tighter bins).
    if (bin_residual as f64) < mean_residual {
        score -= 10.0;
    } else {
        score += 5.0;
    }

    // Mild penalty for opening a new bin when many bins are already open.
    if bin_residual == bin_capacity {
        score += 20.0 + open_bins_count as f64;
    }

    // Small progression-aware tiebreaker: later in the stream, be more
    // willing to close bins tightly (favor smaller post-residual slightly more).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.1 * progress * post_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Penalize dead space that cannot fit the smallest plausible item (<= 1..100 range).
    if post_residual > 0 && post_residual < 10 {
        score += 12.0; // unusable sliver
    }

    // Lookahead: reward if next item fits into post_residual (chain packing).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 18.0 + 0.15 * next_item_size as f64;
        } else {
            // Next item won't fit here; slight penalty scaled by mismatch.
            let overflow = (next_item_size - post_residual) as f64;
            score += 0.08 * overflow;
        }
    } else {
        // Last item: prefer filling any bin as fully as possible.
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Many open bins: encourage closing out bins (fill existing) over spreading.
    if open_bins_count > 4 {
        score += 0.4 * (open_bins_count as f64 - 4.0);
    }

    // Mean residual coupling: if this bin's residual is far below mean,
    // it is a "small" bin — using it keeps mean residual high for future items.
    let diff = mean_residual - bin_residual as f64;
    score += 0.05 * diff;

    // New-bin candidate handling: penalize opening a new bin unless the item
    // fits poorly everywhere (large item or no tight option).
    if bin_residual == bin_capacity {
        let base_penalty = 30.0;
        // Large items (>= 60% capacity) justify fresh bins more readily.
        let relief = if item_size * 5 >= bin_capacity * 3 { 22.0 } else { 0.0 };
        // Early in the stream, opening bins is cheaper (more future items to pair).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let time_relief = 10.0 * (1.0 - progress);
        score += base_penalty - relief - time_relief;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;

    // Base: post-residual waste, mildly convex to punish large leftovers.
    let pr = post_residual as f64;
    let mut score = pr + 0.35 * (pr * pr) / cap;

    // Tight-fit reward: smooth quadratic trough at zero post-residual.
    let tightness = 1.0 - (pr / cap);
    score -= 12.0 * tightness * tightness * tightness;

    // Smooth non-linear coupling of waste with stream progress:
    // early on, waste is cheap; late, waste is costly.
    let progress_waste = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += 25.0 * progress_waste * (pr / cap);

    // Lookahead: reward residuals that can host the next item, penalize
    // residuals that almost-but-not-quite fit it (dead space).
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / cap);
        } else {
            let miss = (next_item_size - post_residual) as f64;
            score += 6.0 * (miss / cap) * (miss / cap) * cap;
        }
        // Coupling: prefer residual near next item size, smooth kernel.
        let diff = (pr - n).abs();
        score += 0.15 * diff;
    }

    // Last-chance bin: strong reward so we don't open a needless new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // mild penalty for spreading across many fitting bins
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Compare against mean residual: penalize bins that would become
    // outliers (waste far above average), smoothly.
    let dev = pr - mean_residual;
    score += 0.05 * dev * dev / cap;

    // New-bin candidate: residual == capacity. Make it a mid-range default;
    // it should win only when open bins are truly poor fits.
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.3 * progress_waste);
        if next_item_size > 0 && next_item_size as f64 <= cap {
            score -= 2.0;
        }
        if fitting_bins_count == 0 {
            score -= 30.0; // no open bin fits: opening is necessary
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: reward residuals that lie in "useful" residue classes.
    // Small post_residuals that are multiples of common size classes are reusable.
    let pr = post_residual;
    if pr == 0 {
        score -= 60.0; // perfect fit, best possible outcome
    } else if pr <= 10 {
        score -= 25.0; // nearly perfect
    } else {
        // modulo classes: residuals divisible by 10 (harmonic with capacity 100)
        let class10 = pr % 10 == 0;
        let class5 = pr % 5 == 0;
        if class10 {
            score -= 12.0;
        } else if class5 {
            score -= 6.0;
        } else {
            // penalize awkward residues proportionally
            score += (pr % 10) as f64 * 0.8;
        }
        // dead-space penalty: residual too small for the smallest plausible item
        if pr < 5 {
            score += 30.0;
        }
    }

    // integer-division thresholds on next_item_size vs post_residual
    if next_item_size > 0 {
        if next_item_size <= pr {
            // lookahead fits: reward, scaled by how snugly
            let slack = (pr - next_item_size) as f64;
            score -= 15.0 + 10.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // lookahead does not fit: penalize if this bin becomes near-dead
            if pr < 10 {
                score += 20.0;
            } else {
                score += 4.0;
            }
        }
        // harmonic coupling: next item in same residue class family
        if next_item_size % 10 == pr % 10 && pr >= next_item_size {
            score -= 8.0;
        }
    }

    // last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // new-bin candidate handling: opening a new bin should only win when fits are terrible
    if bin_residual == bin_capacity {
        // base cost of a fresh bin: slightly worse than a decent fit
        score = 55.0;
        if fitting_bins_count == 1 {
            // an existing last-chance bin should almost always win
            score += 30.0;
        }
        if post_residual > 0 && post_residual < 10 {
            score += 15.0; // don't open a bin for a nearly-perfect fit elsewhere
        }
    }

    // mild preference to fill older/more crowded bins when many are open
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    // progression-aware tightening: later in stream, prefer tighter fits
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (post_residual as f64) * 0.15;

    // tie-break toward bins below mean residual (already tighter)
    if (post_residual as f64) < mean_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for typical future items are wasted.
    let min_useful = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + (min_useful - post_residual) as f64 * 2.0;
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Tight fit reward: item fills most of the bin.
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Lookahead: bonus if the post residual can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + (next_item_size as f64 / post_residual.max(1) as f64) * 5.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0; // next item won't fit here; residual likely becomes dead space
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; prefer reuse.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pressure = (open_bins_count as f64).ln() * (1.0 + progress);
    score += pressure * 2.0;

    // Prefer bins with residuals close to item size (minimize leftover spread).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    // New-bin candidate: penalize relative to mean residual so a new bin is
    // only chosen when existing bins have poor fits.
    if bin_residual == bin_capacity {
        score += 12.0 + mean_residual * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: small post_residual is good (less dead space).
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powf(3.0);

    // 2-step lookahead: if the next item exactly fills the post_residual,
    // this bin is a perfect chain placement -> strong reward.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 40.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item can also fit here: moderate reward proportional to how snugly.
        let slack = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot use the leftover: penalize leftover relative to next item.
        let waste = (post_residual as i64 - next_item_size as i64).max(0) as f64;
        score += 0.35 * waste;
    }

    // Reward matching against mean residual: bins below mean residual are
    // already tight; prefer filling those first.
    if (post_residual as f64) < mean_residual {
        score -= 6.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;
    } else {
        score += 4.0 * ((post_residual as f64) - mean_residual) / bin_capacity as f64;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent fits exist elsewhere.
    if bin_residual == bin_capacity && bin_capacity - item_size <= 30 {
        // New bin with large leftover after a small item: acceptable fallback.
        score += 15.0;
    } else if bin_residual == bin_capacity {
        score += 8.0;
    }

    // Slight preference to consolidate as stream progresses (fewer open bins).
    score += 0.15 * open_bins_count as f64 * (step_index as f64 / total_items.max(1) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
