    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: reward if the next item fits the post-residual,
    // penalize if the next item is larger than post_residual (wasted potential).
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            let gap = (post_residual - next_item_size) as f64;
            score -= 6.0 * (1.0 - gap / (bin_capacity as f64));
        } else {
