    // Last-chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 8.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Distance from mean residual: prefer bins with residual close to the mean
    // (keeps bin portfolio balanced) unless a very tight fit is available.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // New-bin candidate logic: empty bin gets a moderate base penalty so it
    // is only chosen when no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * (open_bins_count as f64);
        // Early in the stream, opening bins is cheap; later, avoid sprawl.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Slight preference for fuller bins overall.
    score -= 0.02 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post;

    // Non-linear waste penalty: dead space grows quadratically with residual.
    score += 0.35 * (post / cap) * (post / cap) * cap;

    // Reward tight fits more strongly as the stream progresses.
    let tightness = 1.0 - post / cap;
    score -= (1.0 + 2.5 * progress) * 8.0 * tightness * tightness;

    // Lookahead coupling: bonus if next item fits the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 6.0 * progress;
    } else if next_item_size > 0 {
        // Penalize residuals that no plausible item can use.
