    }

    // Mild penalty for scattering across many bins relative to mean residual.
    if post > mean_residual {
        score += 0.05 * (post - mean_residual);
    }

    // New-bin candidate: make empty bins mildly unattractive unless residuals are bad.
    if bin_residual == bin_capacity {
        score += 6.0 + 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fraction of capacity wasted after placement
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 40.0 * waste_frac * waste_frac;

    // Reward near-perfect fits (post_residual in harmonic classes 0..=5)
    if post_residual <= 5 {
        score -= 60.0;
    } else if post_residual <= 10 {
        score -= 30.0;
    }

    // Harmonic class logic: residual classes modulo capacity fractions
    let quarter = bin_capacity / 4;
    let class = post_residual % quarter;
    // Items whose size divides capacity classes are more "compatible"
    let item_class = item_size % quarter;
    if class < item_class {
        // residual too small for the item's own granularity -> dead space risk
        score += 8.0 + (item_class - class) as f64;
    } else {
        score -= 4.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward
    if next_item_size > 0 && next_item_size <= post_residual {
        let nxt_fit = post_residual - next_item_size;
        if nxt_fit <= 5 {
            score -= 50.0;
        } else {
            score -= 15.0;
        }
    } else if next_item_size > 0 && next_item_size > post_residual {
        // residual cannot host the next item: penalize proportionally to how much it misses
        let miss = (next_item_size - post_residual) as f64;
        score += 10.0 * (miss / bin_capacity as f64).sqrt();
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate: only attractive when current bin fits are poor
    if bin_residual == bin_capacity {
        let base_penalty = 25.0 + 10.0 * waste_frac;
        // If no open bin fits well, opening a new bin is fine
        if fitting_bins_count == 0 || mean_residual < item_size as f64 {
            score -= 20.0;
        } else {
            score += base_penalty;
        }
        // Early in the stream, opening bins is cheap; later, prefer consolidation
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    }

    // Slight preference for bins with residual close to the mean (balance)
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals below the minimum possible item size (1)
    // are fine, but residuals in the "unusable small gap" band are heavily penalized.
    // Treat gaps that can hold nothing useful (< smallest plausible item, ~10) as dead.
    let dead_threshold = 10.0f64;
    if (post_residual as f64) < dead_threshold {
        // Perfectly tight fit: reward strongly.
        score -= 60.0;
    } else {
        // Penalize gaps that are small but nonzero relative to capacity.
        let gap_frac = post_residual as f64 / bin_capacity as f64;
        score += 25.0 * (dead_threshold / 10.0) * (1.0 - gap_frac).powi(3);
    }

    // Encourage filling bins that can't fit the next item anyway (no future use).
    if next_item_size > 0 && post_residual < next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 {
        // Bonus if this placement leaves room exactly for the lookahead item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new one
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + progress);
    score += pressure * 0.5;

    // New-bin candidate (empty bin): make it attractive only when the item is large
    // relative to residuals of open bins (mean_residual small => existing bins tight).
    if bin_residual == bin_capacity {
        let mean_gap = mean_residual - item_size as f64;
        if mean_gap < 0.0 {
            // Existing bins are too small on average: opening a new bin is good.
            score -= 30.0 + (-mean_gap) * 0.5;
        } else {
            // Existing bins can typically absorb it: penalize opening a new bin.
            score += 40.0 + mean_gap * 0.3 + open_bins_count as f64 * 2.0;
        }
    }

    // Slight preference for bins whose residual is closest to item size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 10.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact match of post_residual with next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect fit for next item -> huge reward.
        if post_residual == next_item_size {
            score -= 200.0;
        } else if post_residual > next_item_size {
            // Next item still fits here: mild reward proportional to closeness.
            score -= 30.0 / (1.0 + diff);
        } else {
            // Next item won't fit after placement: penalize dead space creation.
            score += 15.0 + diff * 0.3;
        }
    }

    // Tight packing reward: smaller post_residual relative to capacity is better.
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    // Compare against mean residual across open bins: prefer bins that become
    // tighter than average (avoid spreading slack evenly).
    let rel = post_residual as f64 - mean_residual;
    score += rel * 0.25;

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // (i.e., current bin would leave large unusable gap or few fitting bins).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 60.0 + open_bins_count as f64 * 2.0;
        // If placing here would waste a lot (post_residual tiny but next item
        // doesn't fit), opening fresh can win.
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score -= 40.0;
        }
        // Late in stream, prefer consolidating into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 20.0;
    }

    // Slight preference for filling nearly-full bins when many bins are open.
    score -= (open_bins_count as f64).ln().max(0.0) * (bin_capacity - post_residual) as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Perfect fill is ideal.
    if post_residual == 0 {
        score -= 100.0;
    } else if post_residual < 10 {
        // Small dead space is nearly as good as a perfect fill.
        score -= 40.0;
    }

    // Lookahead: reward when the next item exactly fits the post-residual (chain placement).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // Next item can also go here: mild bonus proportional to how well it chains.
            let chain = next_item_size as f64 / post_residual as f64;
            score -= 25.0 * chain;
        } else {
            // Next item won't fit here after placement: slight penalty for wasted lookahead.
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 45.0;
    }

    // New-bin candidate handling: opening a new bin wastes capacity when decent fits exist.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity == 100;
    if is_new_bin {
        // Base penalty for opening a new bin.
        score += 35.0;
        // More penalty when many bins already fit the item (poor excuse to open new).
        score += 10.0 * (fitting_bins_count as f64).min(6.0);
        // Early in the stream, opening bins is cheaper (build diversity); late, avoid it.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If mean residual across open bins is large, open bins are underused -> penalize new bin less
        // (better to spread) ... actually reward new bin when mean residual is tiny (bins nearly full).
        score += 0.3 * mean_residual;
    } else {
        // Existing bin: prefer bins with residual below mean (consolidate fuller bins),
        // keep emptier bins available for large future items.
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Mild penalty for spreading across too many open bins late in the stream.
    score += 0.5 * (open_bins_count as f64).ln().max(0.0);

    // Slight preference to keep large residuals intact for large items: penalize placing
    // small items into very large residuals.
    if item_size < 30 && bin_residual > 70 {
        score += 12.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let norm_next = next_item_size as f64 / cap;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on, tolerate larger residuals (favor spreading items); late, punish waste hard.
    let progress_poly = 1.0 + 4.0 * progress * progress + 2.0 * progress;
    score *= progress_poly;

    // Reward tight fits: quadratic bonus for small normalized post_residual.
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * 12.0 * (1.0 - progress);

    // Lookahead coupling: if the next item fits the post residual, strongly reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let snug = 1.0 - (post_residual - next_item_size) as f64 / cap;
        score -= 8.0 * snug * snug;
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Dead space relative to next item: penalize quadratically.
        let waste = (next_item_size - post_residual) as f64 / cap;
        score += 4.0 * waste * waste;
    }

    // Penalize opening a new bin, more so as the stream matures and bins are plentiful.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 15.0 + 20.0 * progress + 2.0 * open_bins_count as f64;
    } else {
        // Last-chance bin bonus: strongly favor using the only fitting bin.
        if fitting_bins_count == 1 {
            score -= 10.0;
        }
        // Reward bins with residuals below the mean (consolidating waste).
        score -= 0.5 * (mean_residual - pr) / cap;
    }

    // Mild preference for fuller bins overall (cubic in fill ratio).
    let fill = 1.0 - norm_pr;
    score -= 3.0 * fill * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo arithmetic on capacity
    let pr = post_residual;
    let class = match pr {
        0 => 0.0,                    // perfect fit — heavily reward
        c if c <= 10 => 1.0,         // near-perfect sliver
        c if c < 30 => 2.0,          // small dead space
        c if c < 60 => 3.0,          // medium
        _ => 4.0,                    // large residual, still reusable
    };
    score += class * 8.0;

    // Perfect fit: massive reward
    if pr == 0 {
        score -= 200.0;
    }

    // Lookahead coupling: does next item fit the post residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // next item fits exactly or well — reward tight chaining
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 - slack * 0.5;
            if pr == next_item_size {
                score -= 60.0; // exact chain: two perfect fills
            }
        } else {
            // next item won't fit here; penalize leaving awkward residue
            let over = (next_item_size - pr) as f64;
            score += over * 0.6;
            // residue unusable for next item: dead-space penalty by class
            score += class * 4.0;
        }
    } else {
        // last item: only perfect fits matter
        score += 10.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Many fitting bins: mild penalty to preserve diversity of residual sizes
    if fitting_bins_count > 1 {
        score += (fitting_bins_count as f64 - 1.0) * 2.0;
    }

    // Prefer bins tighter than the mean residual (best-fit flavor)
    score += (mean_residual - bin_residual as f64) * 0.3;

    // New-bin candidate: default cost, discounted when open bins are crowded
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let crowding = open_bins_count as f64 / (mean_residual / cap + 0.5);
        score = 55.0 - progress * 10.0 - crowding * 0.5;
        // opening a new bin is attractive if no open bin yields a good class
        if class >= 3.0 && fitting_bins_count <= 2 {
            score -= 15.0;
        }
    }

    // Integer-division threshold: residue in [1,10] is a harmonic "sliver" class
    let sliver = (pr / 10) == 0 && pr > 0;
    if sliver {
        score += 12.0; // slivers are nearly dead space unless exact
        if next_item_size > 0 && next_item_size <= pr {
            score -= 30.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (below min item size) are pure waste.
    if post_residual < 10 && post_residual > 0 {
        score += 60.0; // heavy penalty for creating a dead gap
    } else if post_residual == 0 {
        // Perfect fit: strongly reward closing a bin exactly.
        score -= 40.0;
    } else {
        // Penalize gaps that can't fit the lookahead item (wasted for next step).
        if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
            score += 12.0;
        }
        // Reward tight fits relative to capacity.
        score -= 30.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));
    }

    // Prefer bins that are already mostly full (low residual) — classic best-fit sharpening.
    score += 0.35 * (bin_residual as f64);

    // Open-bin pressure: with many open bins, discourage spreading; favor filling existing ones.
    let pressure = (open_bins_count as f64).ln().max(0.0);
    score += 6.0 * pressure * (post_residual as f64) / (bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no open bin fits well
    // (i.e. mean residual is small relative to the item) or bins are few.
    if bin_residual == bin_capacity {
        let poor_fits = if mean_residual < item_size as f64 { 1.0 } else { 0.0 };
        score += 55.0 - 45.0 * poor_fits + 4.0 * (open_bins_count as f64);
        // Lookahead: opening a fresh bin is good if next item is large.
        if next_item_size >= 70 {
            score -= 15.0;
        }
    }

    // Mild stream-progression tightening: late in the stream, prefer consolidation.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * progress * (post_residual as f64) / (bin_capacity as f64);

    // Coupling with mean residual: placing into a bin below-average residual is good.
    score -= 0.15 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual) nonlinearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 25.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits the post residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Exact or near-exact chain match gets a big bonus.
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 30.0 * (1.0 - chain_waste / cap);
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            // Next item won't fit here: penalize dead space creation.
            score += 12.0 + 0.15 * (post_residual as f64);
        }
    } else {
        // Last item: only the immediate fit matters.
        score -= 20.0 * tightness;
    }

    // Compare against mean residual across open bins.
    score += 0.3 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Penalize opening a new bin when decent open bins exist,
    // unless this is the new-bin candidate with a perfect lookahead chain.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 + 10.0 * (1.0 - progress);
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 15.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.5 * (open_bins_count as f64).sqrt() * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 8.0 * tightness * tightness;

    // Penalize awkward residuals: dead space that is too small for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 2.5;
    }

    // Lookahead: if the next item fits into the post-residual, reward this bin;
    // if post_residual is nonzero but cannot fit next item, penalize.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 5.0;
        } else if post_residual > 0 {
            score += 3.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: default neutral score, adjusted by global state.
    if bin_residual == bin_capacity {
        // Opening a new bin is expensive when many bins are open but few fit;
        // cheap when open bins have poor fits anyway.
        score += 4.0;
        if fitting_bins_count == 0 {
            score -= 20.0; // nothing else fits: must open
        }
        // Late in the stream, avoid leaving many small open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 3.0 * progress;
    }

    // Prefer bins whose residual is close to the item (perfect packing),
    // and bins far below the mean residual (they are the "odd" ones to fill up)
    let diff = (bin_residual as f64 - item_size as f64).abs();
    score += 0.05 * diff;

    if bin_residual != bin_capacity && (bin_residual as f64) < mean_residual {
        score -= 1.5;
    }

    // Slight preference to fill older/more crowded configurations when many bins open
    if open_bins_count > 4 && bin_residual != bin_capacity {
        score -= 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    // non-linear coupling of post_residual with stream progress
    let prn = pr / cap;
    score += 40.0 * prn * prn * (0.5 + progress);
    // reward tight fits more strongly later in the stream
    score -= 12.0 * (1.0 - prn) * (1.0 - prn) * progress;
    // lookahead: penalize if post_residual can't fit next item, reward if it can
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 6.0 * (1.0 - pr / nxt.max(1.0) * 0.0) - 6.0 * (pr - nxt) / cap * 0.0;
            score -= 6.0;
        } else {
            score += 4.0 * (nxt - pr) / cap;
        }
    }
    // last-chance bin bonus
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }
    // new-bin candidate: penalize mildly, less when open bins are crowded
    if bin_residual == bin_capacity {
        score += 15.0 - 5.0 * (open_bins_count as f64 / (open_bins_count as f64 + 3.0));
    }
    // mean residual coupling: prefer bins deviating from mean residual (diversity of sizes)
    score += 3.0 * ((pr - mean_residual) / cap).abs();
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: waste bucketed by capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;
    let class = (frac * 8.0).floor() as u32; // 0..7 harmonic classes
    let class_penalty = match class {
        0 => -30.0,           // perfect fit
        1 => -8.0,            // small sliver, likely dead space -> reward
        2 => 2.0,
        3 => 8.0,
        4 => 14.0,
        5 => 20.0,
        6 => 26.0,
        _ => 32.0,            // huge leftover, wasteful placement
    };
    score += class_penalty;

    // Integer-division threshold: post_residual divisible into useful chunks?
    if post_residual > 0 {
        let div = post_residual / 10;
        if div >= 1 && post_residual % 10 == 0 {
            score -= 4.0; // residual aligns with 10-unit granularity, reusable
        }
    }

    // Lookahead: does the next item fit into the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Harmonic coupling: next item exactly fills remaining space
        if next_item_size == post_residual {
            score -= 25.0;
        }
        // next item leaves a small class-1 sliver again
        let nfrac = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        if nfrac > 0.0 && nfrac <= 0.1 {
            score -= 5.0;
        }
    } else if next_item_size > post_residual {
        score += 6.0; // this bin can't serve the next item
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // Penalize placements far below mean residual utilization (fragmentation).
    let dev = mean_residual - post_residual as f64;
    if dev > 0.0 {
        score += dev * 0.15;
    } else {
        score += dev * 0.05;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = open_bins_count as f64 * 0.7 + progress * 10.0;
        // base cost of opening a bin, reduced if item is large / few alternatives
        score += 55.0 - pressure - (item_size as f64 * 0.2);
        if fitting_bins_count == 0 {
            score -= 60.0; // must open a new bin anyway
        }
        if fitting_bins_count == 1 {
            score += 25.0; // a usable bin exists; discourage new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: post_residual in (0, 10) is nearly unusable
    // (min item size 1, but small gaps attract small items poorly) — heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Perfect fit: strongly reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Tight fit reward: item fills most of the bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    if fill_ratio > 0.7 {
        score -= 10.0 * fill_ratio;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward heavily; if post_residual is too small for the next item,
    // penalize (dead space relative to lookahead).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // New-bin candidate: opening a new bin is only attractive when no open bin
    // gives a good fit. Base it on mean residual pressure.
    if bin_residual == bin_capacity {
        // Penalize opening new bins mildly; the tight-fit/last-chance bonuses
        // on existing bins will usually beat this.
        score = 45.0 + open_bins_count as f64 * 0.5 - mean_residual * 0.2;
        if next_item_size > 0 && item_size >= next_item_size {
            score += 5.0; // large item now, keep fresh bin for pairing
        }
    }

    // Open-bins pressure: mildly discourage scattering across many bins.
    score += open_bins_count as f64 * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: prefer bins where the item fills them exactly.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: strongly reward bins where the next item also fits.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let leftover_after_next = post_residual - next_item_size;
            // Reward tight two-item packing: item + next item nearly fills the bin.
            score -= 2.5 * (next_item_size as f64);
            score -= 0.5 * (bin_capacity as f64 - leftover_after_next as f64);
            if leftover_after_next == 0 {
                score -= 400.0; // exact two-item completion
            }
        } else {
            // Next item won't fit here; penalize proportionally to the wasted gap.
            let gap = next_item_size - post_residual;
            score += 0.3 * (gap as f64);
        }
    }

    // Relative-to-mean-residual matching: prefer bins whose residual is close to
    // (but >=) the item size, i.e., tight fits relative to fleet state.
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 8.0 * tightness;

    // Penalize bins much tighter than the fleet mean (they're precious small-capacity bins)
    if (bin_residual as f64) < mean_residual {
        score += 0.4 * (mean_residual - bin_residual as f64);
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate (empty bin): make it attractive only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base penalty so open bins with decent fits win by default...
        score += 60.0;
        // ...but if very few bins fit, opening fresh is reasonable.
        if fitting_bins_count <= 1 {
            score -= 120.0;
        }
        // Lookahead: an empty bin can host item + next item comfortably.
        if next_item_size > 0 && item_size + next_item_size <= bin_capacity {
            score -= 0.2 * (next_item_size as f64);
        }
    }

    // Mild early-stream preference for opening bins (build a diverse pool),
    // mild late-stream preference for consolidating.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    } else {
        score -= 10.0 * progress;
    }

    // Slight penalty when many bins are open already (consolidation pressure).
    score += 0.5 * (open_bins_count as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tightness reward: strongly favor small post_residual (non-linear).
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 45.0 * tight * tight;

    // Exact / near-exact fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 25.0;
    }

    // Dead-space penalty: residual left below the smallest plausible item is wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 18.0;
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive when open bins are nearly full.
    if bin_residual == bin_capacity {
        let crowded = (open_bins_count as f64).max(1.0);
        let avg_free = mean_residual.max(0.0);
        // Penalize opening new bins while open bins have slack.
        score += 25.0 + 0.5 * avg_free;
        // But if all open bins are nearly full (small mean residual), new bin is fine.
        score -= 35.0 * (1.0 - avg_free / bin_capacity as f64).min(1.0);
        // Late in the stream, prefer consolidation.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 * progress;
        // Few open bins relative to stream length -> cheaper to open.
        score -= (crowded.ln() * 4.0).min(12.0);
    }

    // Mild preference for filling fuller bins among many candidates.
    let fill = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 10.0 * fill;

    // Fragmentation guard: avoid leaving residuals just under common item sizes.
    for r in [10u32, 20, 30, 40, 50] {
        if post_residual > 0 && post_residual < r && bin_residual >= r {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: minimize wasted space after placement (quadratic coupling).
    let mut score = post * (1.0 + 0.012 * post / cap);

    // Smooth non-linear stream-progress coupling: late in the stream, dead
    // space becomes increasingly costly (bins may never be reused again).
    let late = progress * progress;
    score += 24.0 * late * (post / cap);

    // Perfect-fit reward: cubic decay of bonus as post_residual grows.
    score -= 30.0 * (1.0 - post / cap).powi(3);

    // Lookahead: reward if the next item fits snugly into the post residual.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        if nxt <= post {
            score -= 10.0 * (1.0 - gap / cap);
        } else {
            score += 6.0 * (gap / cap);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 {
        score -= 18.0;
    } else if fitting_bins_count > 1 {
        // Among many candidates, prefer tighter fits slightly more.
        score += 2.0 * (fitting_bins_count as f64).ln() * (post / cap);
    }

    // New-bin candidate (empty bin): only attractive when open bins are
    // heavily fragmented (high mean residual) or post_residual is large.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / cap).clamp(0.0, 1.0)
        } else {
            1.0
        };
        score += 30.0 - 25.0 * fragmentation - 15.0 * late;
    } else {
        // Slight penalty for spreading across too many open bins.
        score += 0.4 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Harmonic class of post_residual: residues near multiples of small
    // item sizes (10..20) are reusable dead space; odd primes are not.
    let pr = post_residual as i64;
    let mut residue_bonus = 0.0;
    for m in [10i64, 12, 15, 20, 25, 50] {
        let r = pr % m;
        if r == 0 {
            residue_bonus += 4.0;
        } else if r <= 3 {
            residue_bonus += 2.0;
        }
    }
    score -= residue_bonus;

    // Penalize post_residual that cannot fit the next item (dead space).
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = post_residual - next_item_size;
            score -= 3.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            score += 12.0 + 0.25 * (post_residual as f64);
        }
        // Perfect chain: this bin's leftover exactly hosts the next item.
        if post_residual == next_item_size {
            score -= 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a bin unless nothing decent fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let scarcity = if fitting_bins_count == 0 { 0.0 } else { 1.0 };
        let poor_fit = (post_residual as f64) < 0.5 * (bin_capacity as f64);
        let _ = mean_residual;
        score += 60.0 * scarcity
            + (1.0 - progress) * 5.0
            + if poor_fit { -20.0 } else { 0.0 }
            + open_bins_count as f64 * 0.5;
    }

    // Mild penalty for leaving post_residual in awkward small band (1..10).
    if post_residual > 0 && post_residual < 10 {
        score += 8.0;
    }

    // Integer-division threshold: favor post_residual divisible by 100/4.
    if post_residual % (bin_capacity / 4) == 0 && post_residual > 0 {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Pressure from number of open bins: discourage spreading into many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead: reward leaving a gap that can still hold the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    }
    // Penalize leaving a gap just barely smaller than the next item (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += (next_item_size - post_residual) as f64 * 0.5;
    }

    // Mild progress term: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.3;

    // Deviation from mean residual: prefer bins whose residual is close to item need.
    score += (bin_residual as f64 - mean_residual).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial lookahead: next item fits into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        // Reward closeness of the match, non-linearly.
        score -= 40.0 * (1.0 - slack / bin_capacity as f64).powi(3);
    } else if next_item_size > 0 {
        // Next item won't fit here after placement: penalize dead space.
        score += 25.0;
    }

    // Penalize post_residual far above mean residual (wasteful fragmentation).
    score += 0.3 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 45.0;
    }

    // Slight preference for filling tighter bins as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (item_size as f64 / bin_capacity as f64);

    // New-bin candidate: keep it moderately attractive only when the fit is bad.
    if bin_residual == bin_capacity {
        if post_residual < 20 {
            score -= 20.0; // item nearly fills a fresh bin anyway
        } else {
            score += 15.0; // discourage opening new bins for loose fits
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements leaving small post_residual.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (bin_capacity as f64);

    // Penalize "dead space": residuals too small for the smallest plausible item (1..100 range).
    // If post_residual < 10 it can likely never be reused -> add penalty proportional to waste.
    if post_residual < 10 {
        score += 12.0 + (10 - post_residual) as f64;
    } else if post_residual <= 20 {
        // Small but reusable residual: mild bonus to encourage compact packing.
        score -= 3.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0; // perfect chain
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - slack / 100.0); // good chain, less for loose slack
        } else {
            // Next item won't fit here; slight penalty if we leave a big unusable gap.
            let gap = post_residual as f64;
            if gap < next_item_size as f64 {
                score += 0.15 * gap;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 + 0.1 * (bin_residual as f64);
    }

    // New-bin candidate handling: brand-new empty bin should only win when it is
    // genuinely better. Penalize it mildly by default; the penalty shrinks when
    // open bins have small mean residual (poor reuse prospects) or many bins open.
    if bin_residual == bin_capacity {
        let mean_r = mean_residual;
        let scarcity = (mean_r / bin_capacity as f64).clamp(0.0, 1.0);
        let crowding = (open_bins_count as f64 / 20.0).min(1.0);
        score += 6.0 * scarcity + 4.0 * crowding + 5.0;
        // Late in the stream, avoid opening bins that will stay nearly empty.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 8.0 * progress;
    }

    // Global pressure: when many bins are open with large mean residual,
    // encourage consolidating into existing bins (mild bonus for old bins).
    if bin_residual != bin_capacity {
        let consolidation = (mean_residual - post_residual as f64).max(0.0);
        score -= 0.05 * consolidation;
    }

    // Discourage wasting a large bin on a tiny item when residual stays huge.
    if post_residual > 60 {
        score += 0.1 * (post_residual - 60) as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let fit = item_size as f64 / cap;
    let mut score = post;

    // Reward tight fits: post_residual penalized non-linearly (quartic waste pressure)
    let waste_norm = post / cap;
    score += 30.0 * waste_norm * waste_norm * waste_norm * waste_norm * cap;

    // Reward using a bin whose residual closely matches the item (best-fit coupling)
    let match_quality = 1.0 - (bin_residual as f64 - item_size as f64) / cap;
    score -= 25.0 * match_quality * match_quality;

    // Stream progress: late in the stream, prefer filling existing bins more aggressively
    score -= 20.0 * progress * fit * fit;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Many open bins: mild pressure to consolidate into existing bins
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * waste_norm;

    // Mean residual coupling: if this bin is far below mean residual, it's a good filler
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 8.0 * dev * dev - 4.0 * dev;

    // Lookahead: prefer leaving post_residual that can host the next item
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 {
        score += 4.0 * (1.0 - post / cap);
    }

    // New-bin candidate: only attractive when nothing fits well
    if bin_residual == bin_capacity {
        let scarcity = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        score += 10.0 - 12.0 * scarcity - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: prefer residuals in "good" classes
    // (multiples of small divisors that pair well with common item sizes).
    let pr = post_residual;
    let class_bonus = if pr == 0 {
        -30.0 // perfect fit
    } else if pr <= 10 {
        -18.0 // tiny dead space, nearly perfect
    } else if pr % 10 == 0 {
        -10.0 // residual on the decimal grid: easy to fill later
    } else if pr % 5 == 0 {
        -5.0
    } else {
        6.0 // awkward residual class
    };
    score += class_bonus;

    // Modulo coupling with next item: reward residuals that can host the lookahead item
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 12.0;
            // extra reward if post-residual minus next item is also on the grid
            let rem = pr - next_item_size;
            if rem % 10 == 0 { score -= 6.0; }
        } else {
            score += 4.0;
        }
    }

    // Integer-division threshold on residual fraction
    let frac = bin_residual as f64 / cap;
    let seg = (frac * 4.0).floor() as i32; // quartile class of available space
    score -= seg as f64 * 2.0;

    // Last-chance bin: strong reward to avoid opening a new bin needlessly
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a fresh bin unless current fit is bad
    if bin_residual == bin_capacity {
        let bad_fit = post_residual as f64 > cap * 0.6 && next_item_size > 0 && next_item_size > post_residual;
        score += if bad_fit { -8.0 } else { 25.0 };
    }

    // Late in stream: consolidate into fewer bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (open_bins_count as f64 - mean_residual / cap.max(1.0)) * 0.5;

    // Mild preference for bins below mean residual (balance filling)
    score += 0.05 * (post_residual as f64 - mean_residual).abs().signum() * (post_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold even the
    // smallest plausible item are pure waste. Penalize them heavily, with a
    // non-linear ramp as the gap shrinks into the "unusable" zone.
    let min_useful = 10.0_f64.min(next_item_size as f64).max(1.0);
    let dead_zone = 20.0;
    let pr = post_residual as f64;
    if pr < dead_zone {
        let severity = (dead_zone - pr) / dead_zone; // 0..1
        score += 60.0 * severity * severity;         // quadratic dead-space tax
        if pr < min_useful {
            score += 40.0; // gap can never be filled again
        }
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 25.0 * tightness * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // this placement sets up a perfect chain — reward it.
    if next_item_size > 0 {
        if post_residual as f64 == next_item_size as f64 {
            score -= 45.0;
        } else if (post_residual as u32) >= next_item_size {
            score -= 10.0;
        } else {
            score += 8.0; // next item cannot use this bin's remainder
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than spreading; mild penalty scaled by open bin count.
    score += 2.0 * (open_bins_count as f64).ln().max(0.0) * (pr / bin_capacity as f64);

    // Prefer bins whose residual is below the mean (concentrate fullness).
    score += 0.5 * (mean_residual - bin_residual as f64);

    // New-bin candidate handling: an empty bin is only attractive when no open
    // bin fits well. Penalize opening a new bin unless the current item is
    // large relative to capacity (poor fit elsewhere is likely).
    if bin_residual == bin_capacity {
        let large_item = (item_size as f64) / (bin_capacity as f64);
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits: new bin is the only choice
        } else if large_item > 0.6 && next_item_size > 0 && (next_item_size as f64) > (bin_capacity as f64 - item_size as f64) {
            score -= 5.0; // big item + big follower: fresh bin may be wise
        } else {
            score += 30.0; // discourage abandoning open bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact or near-exact fits
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 300.0;
    }

    // 2-step lookahead: reward when post_residual matches next item size exactly
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 60.0 * (1.0 - gap / (bin_capacity as f64)).max(0.0);
        if post_residual == next_item_size {
            score -= 200.0;
        }
        // Penalize leaving residual too small for next item (dead space)
        if post_residual < next_item_size {
            score += 40.0 * (next_item_size - post_residual) as f64 / 10.0;
        }
    } else {
        // Last item: prefer tightest fit
        score -= 200.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Compare against mean residual: prefer bins with below-average residual
    // (fill fuller bins first), but avoid creating tiny unusable slivers
    let pr = post_residual as f64;
    if pr < mean_residual {
        score -= 2.0 * (mean_residual - pr);
    } else {
        score += 1.5 * (pr - mean_residual);
    }

    // Penalize opening a new bin when open bins could fit reasonably well
    if bin_residual == bin_capacity {
        score += 120.0;
        // But allow new bin if all fits would leave large dead space and next item is big
        if next_item_size > 0 && post_residual as f64 > 0.0 {
            let worst = pr.max(0.0);
            if worst > 30.0 && next_item_size > bin_capacity as u32 / 2 {
                score -= 200.0;
            }
        }
        // Early in stream, slightly cheaper to open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 30.0 * (1.0 - progress);
    }

    // Mild preference for consolidating when many bins are open
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tight-fit reward: strongly prefer bins where the item fills most of the residual.
    let fill_ratio = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * fill_ratio * fill_ratio;

    // Penalize dead space that the lookahead item cannot use.
    if next_item_size > 0 {
        if post_residual < next_item_size {
            // Wasted slack: the next item can't go here anyway.
            score += 0.35 * (next_item_size - post_residual) as f64;
        } else {
            // Reward leaving exactly usable space for the next item.
            let slack_match = 1.0 - ((post_residual - next_item_size) as f64 / bin_capacity as f64);
            score -= 6.0 * slack_match * slack_match;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible.
    if fitting_bins_count == 1 {
        score -= 15.0 + 8.0 * progress;
    }

    // Global pressure: when many bins are open relative to progress, prefer
    // consolidating into existing bins.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * pressure * (1.0 - fill_ratio);

    // Early stream: be a bit more willing to spread out and keep options open.
    score -= 3.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: empty bin gets a baseline score that tight fits should beat,
    // but terrible fits (large leftover dead space) should not.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 - 4.0 - 10.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) + norm_pr * (0.5 + progress);

    // Tight fits rewarded more strongly later in the stream
    let tight_fit = (1.0 - norm_pr).powi(3) * (0.3 + 0.7 * progress);

    // Dead-space penalty: residuals too small for any plausible item (min size 1)
    let dead = if pr > 0.0 && pr < 10.0 { (10.0 - pr) * 1.5 } else { 0.0 };

    // Lookahead: reward if next item fits post residual, penalize otherwise
    let lookahead = if next_item_size > 0 {
        if (next_item_size as f64) <= pr {
            -3.0 * (1.0 - (next_item_size as f64 / pr).min(1.0))
        } else {
            2.0 * (next_item_size as f64 - pr) / cap
        }
    } else {
        0.0
    };

    // Last-chance bonus: avoid opening new bin when only this bin fits
    let last_chance = if fitting_bins_count == 1 && bin_residual < bin_capacity {
        -2.0
    } else {
        0.0
    };

    // Mild penalty for spreading across many open bins
    let spread = open_bins_count as f64 * 0.02 * (0.5 + progress);

    // Slight attraction toward mean residual (prefer balanced bins)
    let mean_pull = (pr - mean_residual).abs() * 0.05;

    pr + poly * 10.0 - tight_fit * 8.0 + dead + lookahead + last_chance + spread + mean_pull
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let c = bin_capacity as f64;

    // Base: prefer tight fits, penalize dead space quadratically.
    score = 0.4 * (post_residual as f64) + 0.6 * (post_residual as f64) * (post_residual as f64) / c;

    // Perfect fit is ideal.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic class of post_residual: small residues (1..10) are near-unusable.
    let small_class = post_residual < 10;
    if small_class {
        score += 18.0;
    }

    // Modulo arithmetic on post_residual: residues mod 10 that pair well with
    // common item sizes (10,20,25,50) are more recoverable.
    let r10 = (post_residual % 10) as f64;
    score += 0.3 * r10;

    // If lookahead item can fit into the post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0;
        // Extra reward for near-exact pairing: post_residual - next_item_size small.
        let pair_gap = (post_residual - next_item_size) as f64;
        if pair_gap < 10.0 {
            score -= 8.0 - 0.5 * pair_gap;
        }
    } else if next_item_size > post_residual && next_item_size > 0 {
        // Next item won't fit here: penalize if post_residual is small dead space.
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: only attractive when current item is large and
    // existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        // Prefer new bin early (long horizon amortizes) or when fit is bad.
        let bad_fit = post_residual as f64 > 0.35 * c; // item leaves >35% waste in any open bin? no: this call IS the new bin
        // For the new-bin call, post_residual == capacity - item_size.
        let waste_elsewhere = mean_residual - (post_residual as f64);
        let _ = bad_fit;
        score = 0.55 * c + 0.25 * (post_residual as f64);
        if progress < 0.5 {
            score -= 10.0 * (0.5 - progress);
        }
        if waste_elsewhere > 0.0 {
            score += 0.05 * waste_elsewhere;
        }
        // Don't open a new bin when only one bin fits (use it).
        if fitting_bins_count <= 1 {
            score += 40.0;
        }
        // Large items (>= 50) justify fresh bins more.
        if item_size >= 50 {
            score -= 8.0;
        }
    }

    // Spread pressure: when many bins are open, consolidate (favor bins below
    // mean residual less if they are far above mean).
    let dev = (bin_residual as f64) - mean_residual;
    score += 0.05 * dev;

    // Integer-division threshold: bins whose residual floor-divides into the
    // item size evenly indicate classic-friendly splits.
    if post_residual > 0 && (bin_residual / item_size.max(1)) * item_size == bin_residual {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual that cannot accommodate even the smallest plausible item (<= 8)
    // is "dead space" — penalize it quadratically.
    if post_residual > 0 && post_residual < 8 {
        score += 60.0 + (8 - post_residual) as f64 * 8.0;
    }

    // Penalize residuals too small for the lookahead item (likely dead space
    // for the near future), scaled by how close the lookahead actually is.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let gap = (next_item_size - post_residual) as f64;
        score += 4.0 * gap.min(30.0);
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * tightness;

    // Perfect fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: discourage opening new bins when few bins are open
    // (early stream); allow consolidation pressure to relax later.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when few bins are open or early on.
        score += 20.0 + 25.0 * (1.0 - progress) + 2.0 * open_bins_count as f64;
        // If no open bin fits well, opening may be fine: soften when mean
        // residual is large (open bins are wasteful anyway).
        if mean_residual > 50.0 {
            score -= 15.0;
        }
    } else {
        // Placing into an existing bin reduces open-bin pressure slightly.
        score -= 1.5 * open_bins_count as f64 * (0.5 + 0.5 * (1.0 - progress));
    }

    // Mild alignment with mean residual: prefer bins whose residual is near
    // the mean (keeps bin set homogeneous, easier future packing).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: next item exactly fills this bin afterwards.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0; // chain two items perfectly
        } else if post_residual >= next_item_size {
            // next item fits too: reward tightness of the pair
            score -= 8.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // dead space relative to next item: penalize proportionally
            let waste = (next_item_size - post_residual) as f64;
            score += 0.5 * waste;
        }
    } else {
        // last item: prefer fullest packing
        score += 5.0;
    }

    // Prefer bins already tighter than average (compact filling).
    score += 0.3 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Slight penalty for opening new bins when many bins are already open.
    if bin_residual == bin_capacity {
        score += 3.0 + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect / near-perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Lookahead: reward bins whose post-residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 30.0 + 0.5 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Penalize dead space that the next item cannot use.
        score += 0.3 * (post_residual as f64 - (next_item_size as f64 - post_residual as f64).max(0.0)).max(0.0);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 50.0;
    }

    // Penalize opening a brand-new bin when decent fits exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let pressure = (open_bins_count as f64) * 0.05 + mean_residual * 0.02;
        score += 40.0 + 60.0 * (1.0 - progress) + pressure;
        // Allow new bins only when residuals across the board are too small.
        if mean_residual < item_size as f64 * 0.5 {
            score -= 45.0;
        }
    }

    // Prefer bins whose residual is close to the item (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 20.0 * tightness;

    // Late in the stream, be greedier about filling bins completely.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 15.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let item = item_size as f64;
    let is_new_bin = bin_residual == bin_capacity;

    // Base: penalize wasted residual, quadratically (dead space is doubly bad).
    let mut score = post * post / cap;

    // Smooth normalized fill coupling: reward high fill ratio non-linearly.
    let fill = 1.0 - post / cap;
    score -= 40.0 * fill * fill * fill;

    // Stream-progress interaction: later in the stream, tightness matters more.
    score += 30.0 * (1.0 - progress) * (post / cap);
    score -= 15.0 * progress * fill * (item / cap);

    // Lookahead coupling: if the next item fits the post-residual, reward; else penalize.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            let slack = (post - nxt) / cap;
            score -= 20.0 * (1.0 - slack) * (1.0 - progress);
        } else {
            let gap = (nxt - post) / cap;
            score += 25.0 * gap * gap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 35.0 * (0.5 + 0.5 * progress);
    }

    // New-bin candidate: mildly penalize opening a bin when alternatives exist,
    // but relax late in the stream or when mean residual across open bins is large.
    if is_new_bin {
        score += 12.0 - 8.0 * progress + 0.05 * mean_residual;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: must open
        }
    } else {
        // Reward using existing bins proportional to how many could fit.
        score -= 3.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Mild penalty for accumulating many open bins with fragmented residuals.
    score += 0.01 * open_bins_count as f64 * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose post_residual is small
    let cap = bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * tightness * tightness;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 60.0;
    }

    // Harmonic classes: post_residual bucketed by modulo classes
    let pr = post_residual as u64;
    let class_penalty = match pr % 10 {
        0 => -12.0,
        1 | 2 | 3 => -4.0,
        4 | 5 | 6 => 3.0,
        7 | 8 | 9 => 8.0,
        _ => 0.0,
    };
    score += class_penalty as f64;

    // Integer-division threshold on post_residual: dead space classes
    let dead_class = pr / 20; // 0..5
    score += dead_class as f64 * 6.0;

    // Lookahead coupling: does the next item fit the post_residual?
    if next_item_size > 0 {
        if (post_residual as u64) >= next_item_size as u64 {
            // reward leaving room for the next item, scaled by how well it fits
            let slack = (post_residual as f64 - next_item_size as f64) / cap;
            score -= 20.0 * (1.0 - slack);
        } else {
            // penalize leaving a gap the next item cannot use
            let gap = next_item_size as f64 - post_residual as f64;
            score += 0.35 * gap;
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: only attractive if the current item is large
    // relative to capacity (poor fit anywhere) or few bins are open
    if bin_residual == bin_capacity {
        let frac = item_size as f64 / cap;
        let new_bin_base = 55.0 - 35.0 * frac;
        // fewer open bins -> cheaper to open a new one
        let openness = 1.0 / (1.0 + open_bins_count as f64);
        score = new_bin_base + 25.0 * (1.0 - openness);
        // if item nearly fills a bin, new bin is great
        if frac > 0.8 {
            score -= 40.0;
        }
        // late in stream, prefer consolidation into existing bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 15.0 * progress;
    }

    // Mild pressure against bins far below mean residual (fragmented bins)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Small bonus for using fuller bins first (best-fit flavor)
    score -= 0.15 * (bin_capacity as f64 - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small non-zero gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable dead space given item sizes >= 1... keep small-gap penalty strong
    }
    if post_residual > 0 && post_residual < item_size.min(20) {
        score += 25.0; // gap too small for likely future items
    }

    // Reward perfect fills heavily.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward residuals that can still fit the lookahead item exactly-ish.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 0.05 * (post_residual - next_item_size) as f64;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 12.0; // lookahead cannot use this bin's remainder
    }

    // Tight-fit preference: waste relative to bin capacity.
    score += 0.35 * (bin_capacity - bin_residual) as f64 / bin_capacity as f64 * 10.0;

    // Open-bin pressure: discourage spreading when many bins are open.
    score += 0.6 * open_bins_count as f64;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when no open bin fits well
    // or all fits create dead space; otherwise push it above open-bin fits.
    if bin_residual == bin_capacity {
        score = 100.0 + 2.0 * open_bins_count as f64;
        if fitting_bins_count == 0 {
            score = 5.0; // must open a new bin
        } else if fitting_bins_count == 1 {
            score = 60.0; // last chance exists; only beat it if it's terrible
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin pairs well with upcoming large item
        }
    }

    // Mild stream-progression term: be more conservative late in the stream.
    score += 2.0 * (step_index as f64 / total_items.max(1) as f64);

    // Nudge toward bins whose residual is near the mean (balanced packing).
    score += 0.15 * (bin_residual as f64 - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize small post_residuals that are too small to be useful later
    // (dead space below the minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // 2-step lookahead: if the next item fits exactly into the post residual,
    // this is a perfect chain -> big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            // next item fits: mild reward proportional to how snugly
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - 0.5 * slack;
        } else {
            // next item won't fit in the leftover: penalize leftover size a bit
            score += 0.15 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative-to-mean coupling: bins with residual far above mean are
    // "wasteful" targets unless the fit is tight; bins below mean are precious.
    let rel = (bin_residual as f64 - mean_residual) / mean_residual.max(1.0);
    score += 8.0 * rel;

    // Last chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 0.2 * fit_ratio * 100.0;
    }

    // New-bin candidate handling: prefer reusing open bins early in the stream;
    // allow opening new bins more freely late in the stream when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 15.0 - 25.0 * progress;
        // if no open bin fits well (high mean fragmentation), opening new is fine
        if mean_residual < item_size as f64 {
            score -= 20.0;
        }
    }

    // Slight preference to keep the number of open bins low.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual), with non-linear shaping.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - tightness) * (1.0 - tightness) * 30.0;

    // Penalize dead space that is too small for a typical future item
    // (residual < 10 wastes space; residual in [10, 40] is reusable).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual <= 40 {
        score -= 8.0;
    }

    // Lookahead: if the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // next item won't fit here: penalize proportionally to wasted gap
            score += (next_item_size - post_residual) as f64 * 0.15;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    score += (open_bins_count as f64) * 0.5;

    // Deviation from mean residual: prefer bins whose residual is below mean
    // (fill fuller bins first), mild effect.
    score += (bin_residual as f64 - mean_residual) * 0.2;

    // Time horizon: early in the stream, be more selective (penalize loose fits);
    // late in the stream, just keep bins count low.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - progress) * tightness * 15.0;

    // New-bin candidate: opening a new bin is only attractive when no good fit
    // exists — give it a baseline penalty that shrinks when the item is large
    // relative to capacity (large items are hard to place later).
    if bin_residual == bin_capacity {
        let large_item_bonus = (item_size as f64 / bin_capacity as f64) * 30.0;
        score += 45.0 - large_item_bonus;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // opening fresh bin helps chain large items
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    let x = pr / cap; // normalized post residual in [0,1]
    let p = progress;
    // Smooth interaction: dead-space penalty grows quadratically late in the stream.
    score += 30.0 * x * x * (0.4 + 1.2 * p);
    // Cubic coupling: mid-size residuals are tolerable early, penalized late.
    score += 18.0 * x * x * x * p;

    // Reward tight fits (small post_residual) more strongly as stream progresses.
    score -= 25.0 * (1.0 - x) * (1.0 - x) * (0.3 + 0.7 * p);

    // Lookahead coupling: if next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let diff = (pr - nxt).abs();
        let fit = (nxt <= pr) as i32 as f64;
        score -= 20.0 * fit * (1.0 - diff / cap).max(0.0);
        // Penalize leaving residual slightly larger than next item (unusable sliver).
        score += 12.0 * fit * (diff / cap) * (diff / cap);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // Mild penalty for many open bins with large mean residual (fragmentation).
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap);

    // New-bin candidate: make empty bin attractive only when current fit is poor.
    if bin_residual == bin_capacity {
        score += 8.0 + 10.0 * (1.0 - p) - 15.0 * (x.min(0.999));
        // Discourage opening new bins when a decent existing fit exists elsewhere.
        if fitting_bins_count > 0 && pr < 0.2 * cap {
            score += 20.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic classes: capacity fraction of the post-residual
    let frac = post_residual as f64 / bin_capacity as f64;

    // Perfect fits are heavily rewarded
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Dead space classes: residual that cannot plausibly host typical items
    // (mod-10 arithmetic on post_residual; sizes commonly multiples of 10)
    if post_residual > 0 && post_residual % 10 == 0 {
        score -= 30.0 * frac; // divisible residual is reusable -> reward
    } else {
        score += 15.0 * frac; // awkward residual -> penalize
    }

    // Harmonic thresholds: quarter classes of capacity
    let quarter = (post_residual * 4) / bin_capacity;
    match quarter {
        0 => score += 40.0,            // < 25% left: nearly dead bin
        1 => score -= 5.0,             // 25-50%: usable
        2 => score -= 10.0,            // 50-75%: good
        _ => score -= 20.0,            // >75%: excellent
    }

    // Lookahead coupling: does this placement let the next item fit?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0; // chain placement enabled
            // exact chain (post_residual == next_item_size) is ideal
            if post_residual == next_item_size {
                score -= 40.0;
            }
        } else {
            score += 10.0; // next item will need another bin anyway
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate handling: prefer opening a fresh bin only when no
    // open bin fits well (tight fit) or few bins fit at all.
    if bin_residual == bin_capacity {
        // fresh bin baseline: waste = capacity - item_size
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
        // late in the stream, consolidate more aggressively
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 40.0 * progress;
        if fitting_bins_count > 2 {
            score += 25.0; // plenty of alternatives -> don't open new bin
        }
    }

    // Mild pressure to keep bin count low: reward filling existing bins
    score -= 2.0 * (open_bins_count as f64).ln().max(0.0) * frac;

    // Mean-residual alignment: prefer bins whose residual tracks the mean
    score -= 0.5 * (mean_residual - post_residual as f64).abs() / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: unusable tiny gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Reward tight fits relative to bin size.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fit_ratio * 15.0;

    // Open-bins pressure: discourage scattering when many bins are open.
    score += open_bins_count as f64 * 1.5;

    // Penalize bins whose residual deviates badly from the mean residual.
    score += (bin_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: mildly penalized so it only wins on genuinely bad fits.
    if bin_residual == bin_capacity {
        score += 25.0 + open_bins_count as f64 * 2.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // If next item is large and this placement leaves too little room, penalize.
    if next_item_size > post_residual && next_item_size > 50 && post_residual > 0 {
        score += 10.0;
    }

    // Late-stream consolidation pressure.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead fit: post_residual exactly matches next item
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-perfect fit for next item (next item leaves tiny unusable gap)
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        if gap <= 10.0 {
            score -= 30.0 - gap * 2.0;
        }
    }
    // Penalize post_residual too small for the next item (dead space)
    if next_item_size > 0 && post_residual < next_item_size && post_residual < 10 {
        score += 40.0;
    }

    // Prefer bins with residual below mean (tight bins fill first)
    score -= (mean_residual - bin_residual as f64) * 0.3;

    // Last-chance bonus: only bin that can fit the item
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably
    if bin_residual == bin_capacity && open_bins_count > 0 {
        score += 35.0 + mean_residual * 0.5;
    }

    // Early in stream: slightly prefer consolidation
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= (1.0 - progress) * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual)
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tight * tight;

    // Penalize dead space that is too small to be useful for typical items
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward bins whose post residual can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
            // extra reward if next item fills bin nearly exactly afterwards
            let after = post_residual - next_item_size;
            if after < 10 {
                score -= 6.0;
            }
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Fragmentation pressure: when mean residual is low, be more greedy for tight fits
    let frag = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
    score -= 10.0 * frag * tight;

    // Time horizon: early in stream, be more willing to open new bins (penalize cramming);
    // late in stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 3.0 * tight;
    score -= progress * 5.0 * (1.0 - tight);

    // Many open bins: prefer filling existing ones over opening new
    let new_bin = (bin_residual == bin_capacity) as i32 as f64;
    if new_bin > 0.0 {
        score += 5.0 + 1.5 * open_bins_count as f64;
        // but if open bins are all fragmented, opening a fresh bin is fine
        if mean_residual < 20.0 {
            score -= 10.0;
        }
    }

    // Prefer placing larger items into emptier bins
    score -= (item_size as f64 / bin_capacity as f64) * (bin_residual as f64 / bin_capacity as f64) * 6.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Non-linear coupling: squared normalized post-residual, scaled by progress
    let norm_pr = pr / cap;
    score += norm_pr * norm_pr * cap * (0.25 + 0.75 * progress);

    // Reward tight fits (small post residual) more strongly as stream progresses
    score -= (1.0 - norm_pr).powi(3) * cap * 0.3 * progress;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Lookahead: penalize if post residual can't fit next item when one exists
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // residual still useful for next item: reward proportionally
            score -= 5.0 * (nx / cap);
        } else {
            // dead space relative to next item: penalize
            score += 8.0 * ((nx - pr) / cap) * (1.0 + progress);
        }
    }

    // Prefer bins with below-mean residual (consolidate large gaps)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += dev * 6.0;

    // Mild penalty for opening new bins when many bins already fit the item
    if bin_residual == bin_capacity {
        score += 4.0 + 3.0 * (fitting_bins_count as f64).sqrt();
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 2.0; // new bin still useful for future
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: prefer residuals in "usable" classes
    // (multiples of common item sizes / halves of capacity).
    let cap = bin_capacity as f64;
    let pr = post_residual as i64;

    // Reward post_residuals that are exact multiples of small harmonic steps
    // (10, 20, 25, 50): these leave space likely reusable by future items.
    let mut harmonic_bonus = 0.0;
    for &m in &[10u32, 20, 25, 50] {
        if post_residual % m == 0 && post_residual > 0 {
            harmonic_bonus += 6.0 * (m as f64 / 10.0);
        }
    }
    score -= harmonic_bonus;

    // Penalize residuals in awkward classes: not divisible by 5 at all.
    if post_residual % 5 != 0 {
        score += 8.0;
    }

    // Integer-division threshold logic on post_residual:
    // dead space = post_residual smaller than the smallest plausible item.
    if post_residual < 10 {
        score += 30.0; // dead space penalty
    } else {
        // fraction of capacity left
        let frac = post_residual as f64 / cap;
        // prefer filling bins to roughly half or more; sweet spot near 0.0..0.5 residual
        score += (frac - 0.35).abs() * 20.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // partial credit scaled by how well it matches
            let waste = (post_residual - next_item_size) as f64;
            score -= 25.0 * (1.0 - waste / cap);
        } else {
            // next item cannot use this residual: mild penalty proportional to leftover
            score += 5.0;
        }
    }

    // Last-chance logic: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (unless post_residual would be dead space).
    if fitting_bins_count == 1 && post_residual >= 10 {
        score -= 15.0;
    }

    // New-bin candidate handling: empty bin should only win when open bins fit poorly.
    if bin_residual == bin_capacity {
        // baseline score for a fresh bin: its "post_residual" is capacity - item.
        // make it slightly worse than a decent existing fit but better than a bad one.
        score += 12.0;
        // early in the stream, opening bins is cheap and useful for future flexibility
        let progress = step_index as f64 / total_items as f64;
        if progress < 0.3 {
            score -= 6.0;
        }
        // if many open bins exist, avoid spreading too thin
        if open_bins_count > 8 {
            score += 6.0;
        }
    }

    // Context: compare against mean residual; bins far below mean are "ragged" —
    // prefer placing into bins whose residual is close to item_size (tight fit).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Mild preference to consolidate into fewer bins as stream progresses.
    let progress = step_index as f64 / total_items as f64;
    score -= (1.0 - progress) * 2.0 * (open_bins_count as f64).ln().max(0.0);

    // Exact fit is perfect.
    if post_residual == 0 {
        score -= 50.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that no future item (min size 1..100)
    // can plausibly use are heavily penalized, especially tiny unusable gaps.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0; // unusable sliver
    } else if post_residual < 25 {
        score += 15.0 * (1.0 - post_residual as f64 / 25.0);
    }

    // Reward tight fits (waste minimization baseline).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // New-bin candidate handling: empty bin has residual == capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Prefer reusing an existing bin unless the fit is poor or it's the only option.
        if fitting_bins_count >= 1 {
            score += 40.0 + mean_residual * 0.2;
        } else {
            score -= 100.0; // forced new bin
        }
        // Late in the stream, avoid opening bins that will stay nearly empty.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 25.0 * progress;
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && !is_new_bin {
        score -= 80.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual.max(1) as f64);
        } else {
            // Next item won't fit here; penalize large leftover slightly.
            score += 5.0;
        }
    }

    // Open-bins pressure: with many open bins, discourage spreading items thin.
    score += (open_bins_count as f64).ln().max(0.0) * 3.0;

    // Slight bonus for bins below mean residual (balancing).
    if (post_residual as f64) < mean_residual {
        score -= 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let capacity_f = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Strongly reward tight fits (low post_residual)
    let tightness = 1.0 - post / capacity_f;
    score -= 6.0 * tightness * tightness * item_size as f64;

    // 2-step lookahead: reward if next item fits into post_residual
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if next <= post {
            score -= 18.0 * (1.0 - (post - next) / capacity_f);
        } else {
            // next item won't fit here: penalize wasted space relative to next size
            score += 4.0 * (next - post) / capacity_f;
        }
        // pair-fill bonus: near-perfect two-item packing
        if (post - next).abs() <= 2.0 {
            score -= 25.0;
        }
    }

    // Relative to mean residual: prefer bins with residual below mean (denser bins)
    let dev = (bin_residual as f64 - mean_residual) / capacity_f;
    score += 10.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening new bins
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Progression: early in stream, be more willing to open new bins; later, consolidate
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // new-bin candidate: penalize more as stream progresses
        score += 20.0 + 30.0 * progress;
        // but if no open bin can fit, opening is fine
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    } else if fitting_bins_count == 0 {
        score -= 45.0;
    }

    // Too many open bins: encourage closing them by filling
    if open_bins_count > 4 {
        score -= 2.0 * (open_bins_count as f64 - 4.0) * tightness;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for tight fits (small dead space), super-linear penalty.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * fit_ratio * fit_ratio * bin_capacity as f64;

    // Penalize using a large-residual bin for a small item (waste of big space).
    let waste = (bin_residual as f64 - item_size as f64).max(0.0);
    score += 0.15 * waste * (bin_residual as f64 / bin_capacity as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward if the next item exactly fills the post-residual,
    // penalize if post-residual could have held the next item but won't after a sloppy fit.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0; // perfect pairing
        } else if post_residual > next_item_size {
            score -= 6.0; // next item can still fit here later
        }
        // If item would fit next_item better elsewhere, mild penalty for blocking
        if bin_residual >= next_item_size && post_residual < next_item_size && post_residual > 0 {
            score += 4.0;
        }
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // current bins are nearly full or the item fits nothing well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        // Penalize opening a bin when open bins still have room.
        score += 30.0 * (1.0 - pressure);
        // Reward opening a new bin when residuals are low (bins nearly full).
        score -= 20.0 * pressure * pressure;
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let t = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * t;
        // If many bins can fit the item, discourage a new bin.
        score += 5.0 * fitting_bins_count as f64;
    } else {
        // Reward placing into bins that are already partially filled (consolidation).
        let fill = 1.0 - bin_residual as f64 / bin_capacity as f64;
        score -= 10.0 * fill;
    }

    // Mild global balance: prefer bins with residual near the mean (avoid outliers).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for keeping the number of open bins stable.
    score += 0.02 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;
    let item = item_size as f64;
    let nxt = next_item_size as f64;

    // Base: penalize leftover space, with non-linear (quadratic) coupling to stream progress.
    // Early on, leftover space is cheap; late in the stream, waste is costly.
    let mut score = pr * (1.0 + 2.0 * progress * pr_norm);

    // Smooth polynomial interaction: tight fits (small post_residual) get a reward that
    // strengthens quadratically with progress.
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (1.0 + progress) * 10.0;

    // Lookahead coupling: reward bins whose post_residual matches the next item well,
    // penalize when next item cannot use the leftover (smooth via normalized difference).
    if nxt > 0.0 {
        let diff = (pr - nxt) / cap;
        score += diff * diff * 30.0 * (1.0 - progress);
        // Bonus if next item fits exactly into the post-residual.
        if nxt <= pr {
            score -= 5.0 * (1.0 - (pr - nxt) / cap) * (1.0 - progress);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0 + 15.0 * progress;
    }

    // New-bin candidate: penalize slightly so it's chosen only when open bins fit poorly,
    // with penalty decaying as stream progresses (late stream: consolidation matters more).
    if bin_residual == bin_capacity {
        score += 12.0 + 25.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Mild pressure against accumulating many open bins with large mean residual.
    score += 0.05 * open_bins_count as f64 * (mean_residual / cap) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "nice" sizes
    // (divisible by common item-size classes 10/20/25/50), penalize awkward ones.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Harmonic bonus: post_residual divisible by 50, 25, 20, 10
    let mut harmony_bonus = 0.0;
    if post_residual % 50 == 0 { harmony_bonus += 18.0; }
    else if post_residual % 25 == 0 { harmony_bonus += 12.0; }
    else if post_residual % 20 == 0 { harmony_bonus += 10.0; }
    else if post_residual % 10 == 0 { harmony_bonus += 7.0; }
    score -= harmony_bonus;

    // Dead-space penalty: small unusable residual
    if post_residual < 10 && post_residual > 0 {
        score += 15.0; // nearly-full bin is actually good, but tiny scraps waste capacity
        score -= 25.0; // net: reward near-perfect fills
    }
    if post_residual == 0 {
        score -= 40.0; // perfect fill
    }

    // Penalize residuals in awkward middle band (11..=19): hard to fill later
    if (11..=19).contains(&post_residual) {
        score += 8.0;
    }
    if (21..=24).contains(&post_residual) || (26..=29).contains(&post_residual) {
        score += 5.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size <= post_residual {
            // next item fits: how harmonically well?
            let nres = post_residual - next_item_size;
            if nres % 10 == 0 { score -= 12.0; }
            if nres < 10 { score -= 10.0; } // near-exact double fill
            score -= 5.0;
        } else {
            // next item won't fit here; penalize less if residual still large/useful
            score += 4.0;
            if post_residual < next_item_size && post_residual > 30 {
                score -= 3.0;
            }
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: prefer it only when no open bin offers a tight fit.
    if bin_residual == bin_capacity {
        // base new-bin score: slightly worse than a decent existing fit
        score += 30.0;
        // but if existing bins are fragmented (high mean residual spread) and many open,
        // opening fresh can consolidate
        if open_bins_count > 4 && mean_residual > (cap * 0.5) {
            score -= 25.0;
        }
        if item_size >= 60 {
            score -= 10.0; // big items: fresh bin often better
        }
    }

    // Tight-fit reward: residual barely above item size
    let slack = (bin_residual - item_size) as f64;
    if slack < 10.0 && bin_residual < bin_capacity {
        score -= 22.0;
    }

    // Progress scaling: early in stream, be slightly more willing to open bins
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= progress * 5.0;
    }

    // Mild penalty for spreading across many bins when mean residual is low (fragmentation)
    if bin_residual < bin_capacity && (mean_residual - pr).abs() < 5.0 && open_bins_count > 3 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is ideal: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Strict dead-space avoidance: residuals in the unusable small-gap
        // band (1..=10) are wasted forever -> heavy penalty.
        if post_residual <= 10 {
            score += 60.0 + (10 - post_residual) as f64 * 4.0;
        } else if post_residual <= 20 {
            // Moderately hard to reuse later.
            score += 15.0;
        } else {
            // Larger residuals remain usable: mild reward proportional to size.
            score -= (post_residual as f64 - 20.0) * 0.3;
        }
    }

    // Prefer tight fits relative to what the bin had.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= fill_ratio * 25.0;

    // Open-bin pressure: discourage spreading across many bins early,
    // but relax late in the stream when consolidation matters less.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (2.0 - progress);

    // Penalize bins far from the mean residual (prefer balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Lookahead: if the next item fits exactly in the post residual,
    // strongly favor this bin (chain placement).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 120.0;
        } else if post_residual >= next_item_size {
            score -= 10.0;
        } else if post_residual > 0 && next_item_size > post_residual && next_item_size - post_residual <= 10 {
            // next item would leave this bin's residual as dead space anyway.
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the item
    // is large relative to capacity or all fits are poor.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        // Base cost of opening a new bin, discounted for big items.
        score += 40.0 - large_item * 30.0;
        if fitting_bins_count == 0 {
            score -= 200.0; // no open bin fits: must open
        }
        if post_residual == 0 {
            score -= 500.0; // item exactly fills a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit component: prefer minimal post_residual.
    score += 0.5 * (post_residual as f64 / bin_capacity as f64).powi(2) * bin_capacity as f64;

    // Aggressive 2-step lookahead: reward when the next item exactly fills post_residual.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0; // perfect chaining: this bin becomes exactly full next step
        } else if next_item_size <= post_residual {
            // next item fits here: reward proportional to how well it fills the remaining space
            let chain_fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * chain_fill;
        } else {
            // next item cannot use this bin's leftover: penalize dead space
            score += 10.0 + 0.3 * (post_residual as f64 - next_item_size as f64).abs();
        }
    }

    // Relative-to-mean coupling: bins tighter than the mean are attractive.
    score -= 0.4 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Penalize opening a new bin when existing bins fit, unless lookahead justifies it.
    if bin_residual == bin_capacity {
        let new_bin_bonus = if next_item_size > 0 && post_residual == next_item_size {
            -10.0 // opening fresh bin that chains perfectly is fine
        } else if next_item_size > 0 && next_item_size <= post_residual {
            -5.0
        } else {
            15.0 // discourage new bin generally
        };
        score += new_bin_bonus + 0.1 * open_bins_count as f64;
    } else if fitting_bins_count > 1 {
        // among multiple fitting bins, mild preference for tighter ones
        score -= 3.0;
    }

    // Early-stream exploration: slightly favor consolidating when few bins open.
    if step_index as f64 / (total_items.max(1) as f64) < 0.2 {
        score -= 2.0 * (bin_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress ratio: later in the stream, waste matters more (less chance to reuse gaps).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Dead-space penalty: post space too small for the lookahead item is likely wasted.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        let dead = (next_item_size - post_residual) as f64;
        score += dead * (1.0 + progress);
    }

    // Reward post_residual that exactly accommodates the next item (perfect pairing).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 6.0 + 4.0 * progress;
    }

    // Reward leaving generous, reusable space when mean residual across bins is low.
    if post_residual as f64 >= mean_residual {
        score -= 2.0;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when other bins could fit the item,
    // unless the item is large and would leave a very fragmented residual elsewhere.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fragmentation_risk = if next_item_size > 0 {
            (post_residual as f64 % next_item_size.max(1) as f64) / 10.0
        } else { 0.0 };
        score += 15.0 + 10.0 * (1.0 - progress) + fragmentation_risk;
        // Perfect fit in a fresh bin (item == capacity) is fine.
        if post_residual == 0 { score -= 25.0; }
    } else {
        // Tight fits in existing bins: reward small relative waste.
        let waste_ratio = post_residual as f64 / bin_capacity as f64;
        score -= (1.0 - waste_ratio) * 3.0 * (0.5 + progress);
    }

    // Slight penalty for scattering across many open bins late in the stream.
    score += open_bins_count as f64 * 0.05 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items.max(1) as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Smooth non-linear coupling: waste matters more as stream progresses.
    let waste_weight = 0.5 + 1.5 * progress * progress;
    score += waste_weight * (post / cap) * (post / cap) * cap * 0.1;

    // Penalize post_residual that is small but nonzero (dead space) via smooth curve.
    let dead = post / cap;
    score += 8.0 * dead * (1.0 - dead) * (1.0 - dead);

    // Lookahead: reward bins whose post-residual can fit the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post >= nx {
            score -= 6.0 * (1.0 - (post - nx) / cap);
        } else {
            // post-residual too small for next item: penalize proportionally to closeness (near-miss waste)
            score += 4.0 * (nx - post) / cap;
        }
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: prefer tightening existing ones; few bins: consolidation bonus.
    let pressure = (open_bins_count as f64 / (total_items.max(1) as f64)).clamp(0.0, 1.0);
    score -= 5.0 * pressure * (1.0 - (post_residual as f64 / cap));

    // Mean-residual coupling: prefer bins deviating below mean (tighter bins).
    score += 0.05 * (mean_residual - post);

    // New empty bin candidate: penalize mildly unless it's clearly better (post == capacity).
    if bin_residual == bin_capacity {
        score += 12.0 - 8.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: perfect fits (residual 0) heavily rewarded.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Penalize residuals that no plausible future item can use.
        let pr = post_residual as u32;
        // Usable zone: next item fits and leaves a good residue.
        if next_item_size > 0 {
            if next_item_size <= pr {
                let next_post = pr - next_item_size;
                score -= 0.5 * (next_post as f64);
                // Harmonic bonus: next item exactly fills this bin.
                if next_post == 0 {
                    score -= 300.0;
                }
                // Modulo-10 harmonic classes: residuals divisible by 10 are more reusable.
                if pr % 10 == 0 {
                    score -= 20.0;
                }
                if next_post % 10 == 0 {
                    score -= 15.0;
                }
            } else {
                // Next item cannot use this bin's leftover: penalize dead space.
                score += 0.4 * (pr as f64);
            }
        }

        // Integer-division thresholds on post_residual: small slivers are dead space.
        let sliver = pr / 10; // residual in units of 10
        if sliver == 0 {
            score += 60.0; // residual < 10: nearly unusable
        } else if sliver <= 2 {
            score += 25.0; // residual 10..29: only tiny items fit
        }

        // Fraction-of-capacity coupling: prefer filling bins close to capacity.
        let fill_frac = (bin_capacity - post_residual) as f64 / cap;
        score -= 40.0 * fill_frac;

        // Last-chance bin: strongly favor using it to avoid opening a new bin.
        if fitting_bins_count == 1 && bin_residual != bin_capacity {
            score -= 120.0;
        }

        // New-bin candidate: only attractive when current bins are crowded.
        if bin_residual == bin_capacity {
            score += 80.0 * (mean_residual / cap) - 30.0;
            if fitting_bins_count == 0 {
                score -= 200.0;
            }
        }

        // Many open bins: prefer tightest fits to consolidate.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * (open_bins_count as f64 / (open_bins_count as f64 + 5.0)) * (1.0 - progress);

        // Distance from mean residual: prefer bins whose leftover deviates usefully.
        score += 0.15 * (post_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: gaps that no plausible item can use.
    // Items are 1..100, but small gaps (< ~10) are nearly unusable.
    if post_residual > 0 && post_residual < 12 {
        score += 60.0;
    }
    // "Awkward zone": gaps that are too small for medium items but too big to ignore.
    if post_residual >= 12 && post_residual < 30 {
        score += 25.0 * (1.0 - (post_residual as f64) / 30.0);
    }

    // Reward near-perfect fits (low post_residual) super-linearly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tight = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
        score -= 15.0 * tight * tight;
    }

    // Exact match of bin_residual to item is ideal.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad.
    let is_new_bin = bin_residual == bin_capacity && bin_capacity > 0;
    if is_new_bin {
        score += 45.0;
        // But if this bin is the only option, allow it.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // If open bins are nearly full / fragmented, new bin is fine.
        if mean_residual < (item_size as f64) {
            score -= 60.0;
        }
    }

    // Open-bin pressure: many open bins -> consolidate into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Lookahead (k=2): reward leaving a gap that fits the next item exactly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let gap_fit = (post_residual - next_item_size) as f64;
            score -= 10.0 / (1.0 + gap_fit);
        }
        // Penalize leaving a gap just barely too small for the next item.
        if post_residual > 0 && post_residual < next_item_size && post_residual >= next_item_size - 2 {
            score += 18.0;
        }
    }

    // Late in the stream, tighten packing (less tolerance for waste).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64) / bin_capacity as f64;

    // Prefer bins whose residual is close to the item (minimize fragmentation).
    let waste_ratio = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score += 8.0 * waste_ratio * waste_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
