            }
        }
    }

    // Last-chance bin bonus: if this is the only fitting bin, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: prefer reusing open bins unless the fit is terrible.
    if bin_residual == bin_capacity {
        score += 150.0;
        // But if mean residual across open bins is small (bins are full-ish),
        // opening a new bin is fine.
        score -= mean_residual * 0.5;
    }

    // Prefer bins with residual below mean (denser bins first) to consolidate.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= dev * 0.3;
    }

    // Slight preference to keep number of open bins low late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // Penalize post_residual that cannot fit the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 - next_item_size as f64).min(20.0) / 20.0;
        } else {
            score += 10.0 * (next_item_size as f64 - post_residual as f64) / 100.0;
        }
    }

    // Last-chance bin: strong bonus to use it rather than open a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Many fitting bins: slight penalty to prefer the tightest (post_residual already does this)
    if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0).min(5.0);
    }

    // Prefer bins with residual below mean residual (denser bins)
    let dev = mean_residual - bin_residual as f64;
    score += 0.15 * dev;

    // Time horizon: early in the stream, keep bins flexible; late, pack aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Penalize opening a new bin when open bins exist with reasonable fit
    if bin_residual == bin_capacity && open_bins_count > 0 {
        let urgency = if next_item_size > 0 && next_item_size > bin_capacity - item_size { 0.0 } else { 1.0 };
        score += 12.0 * urgency + 0.5 * open_bins_count as f64;
    }

    // Small bonus for perfectly empty post residual
    if post_residual == 0 {
        score -= 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fill = 1.0 - pr / cap;

    // Smooth polynomial coupling of post_residual with stream progress
    let p2 = progress * progress;
    let p3 = p2 * progress;
    let f2 = fill * fill;

    let mut score = pr * (1.0 + 0.9 * progress + 0.7 * p2 + 0.5 * p3);

    // Reward tight fits more strongly as stream progresses (smooth interaction)
    score -= f2 * (20.0 + 40.0 * progress + 30.0 * p2);

    // Penalize near-full-but-wasteful residuals via smooth cubic in pr
    let x = pr / cap;
    score += 15.0 * x * x * x;

    // Lookahead: reward residual that can host next item, smoothly
    if next_item_size > 0 {
        let n = next_item_size as f64;
        let fits = (pr - n) / cap;
        if fits >= 0.0 {
            score -= 10.0 * (1.0 + progress) * (fits + 0.05);
        } else {
            score += 8.0 * (-fits) * (1.0 + 0.5 * progress);
        }
    }

    // Last-chance bin bonus (smooth via inverse of fitting count)
    if fitting_bins_count <= 1 {
        score -= 12.0;
    } else {
        score -= 6.0 / fitting_bins_count as f64;
    }

    // Mild penalty for spreading across many open bins late in stream
    score += (open_bins_count as f64).ln() * (2.0 + 3.0 * progress);

    // Encourage balancing residuals toward mean early, differentiation later
    score += 0.05 * (pr - mean_residual).abs() * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are nearly full -> reward tight fits.
    let pr = post_residual;
    let class = pr / 10; // integer-division thresholds on post_residual
    match class {
        0 => score -= 30.0,            // perfect/near-perfect fit
        1 => score -= 22.0,
        2 => score -= 14.0,
        3 => score -= 8.0,
        4 => score -= 3.0,
        5 => score -= 0.0,
        6 => score += 4.0,
        7 => score += 9.0,
        8 => score += 15.0,
        _ => score += 22.0,
    }

    // Modulo coupling: residues that pair well with common item sizes
    // (multiples of 10 / 5) leave usable space for future items.
    if pr % 10 == 0 {
        score -= 6.0;
    } else if pr % 5 == 0 {
        score -= 3.0;
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 25.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / cap);
        } else {
            // next item cannot fit here: penalize blocking it
            score += 8.0 * ((next_item_size - pr) as f64 / cap);
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive
    // when current item is huge and no open bin fits well.
    if bin_residual == bin_capacity {
        let fill = item_size as f64 / cap;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open a new bin
        } else if fill > 0.7 {
            score -= 5.0;  // large item: fresh bin acceptable
        } else {
            score += 25.0 + 20.0 * (1.0 - fill); // discourage wasting fresh bins
        }
    }

    // Stream progression: early on, allow more bins; late, consolidate.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / cap);

    // Penalize bins far below the mean residual (fragmented outliers),
    // reward bins near the mean (balanced packing).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild penalty for accumulating too many open bins.
    score += 0.5 * open_bins_count as f64 * (post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 18.0;
    } else if post_residual < 35 {
        score += 6.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless it looks genuinely better.
    if bin_residual == bin_capacity {
        score += 30.0 + 3.0 * open_bins_count as f64;
        // But if the current item leaves a huge gap elsewhere and next item
        // would need a fresh bin anyway, opening can be reasonable.
        if next_item_size > 0 && post_residual > 0 && next_item_size > post_residual {
            score -= 10.0;
        }
    }

    // Prefer bins whose residual is already tight (filling fuller bins first).
    score += 0.15 * (mean_residual - bin_residual as f64).max(-50.0);

    // Lookahead: bonus if post_residual exactly fits the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    }

    // Mild pressure on number of open bins: keep consolidation tendency.
    score += 0.5 * open_bins_count as f64;

    // Slight late-stream tightening: favor compact fills as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 8.0 * progress * (bin_capacity - bin_residual) as f64 / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step lookahead match: post_residual equals next item size exactly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near match: next item fits with small slack left over.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 30.0 - slack.min(30.0); // reward up to 30, decaying with slack
    }
    // Next item does NOT fit here: penalize dead space that will be wasted.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 15.0;
    }

    // Penalize tiny unusable residuals (dead space).
    if post_residual < 10 {
        score += 8.0;
    }

    // Compare against mean residual: placing in a bin with residual above mean
    // (large leftover) is better than fragmenting a tight bin.
    let diff = post_residual as f64 - mean_residual;
    score -= 0.3 * diff;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists elsewhere.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 40.0 };
        let lookahead_bonus = if next_item_size > 0 && post_residual >= next_item_size { 10.0 } else { 0.0 };
        score += pressure + lookahead_bonus;
    }

    // Mild stream-progression term: be slightly more conservative early.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 5.0 * (1.0 - progress);

    // Small penalty for leaving large residuals relative to capacity.
    score += 0.05 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress through the stream (0..1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Tightness of fit: reward small post_residual relative to capacity
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 25.0 * tightness * tightness;

    // Perfect-fit bonus: leave nothing usable behind
    if post_residual == 0 {
        score -= 60.0;
    }

    // Penalize leaving dead space that the typical/next item cannot use
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0; // residual is dead space for the lookahead item
    } else if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0; // residual remains usable by lookahead
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // When many bins fit the item, prefer the one with the least residual (best fit already covered),
    // but penalize spreading load across too many open bins when few fit
    if fitting_bins_count > 2 {
        score += 1.5 * (fitting_bins_count as f64).ln();
    }

    // Balance against global mean residual: prefer bins whose residual is near/below mean
    // (i.e., fuller bins) to keep a pool of large residuals open for big items
    let dev = bin_residual as f64 - mean_residual;
    score -= 0.08 * dev;

    // Early in the stream: be more willing to open fresh bins (keep large residuals available);
    // late in the stream: consolidate tightly into existing bins.
    let new_bin = bin_residual == bin_capacity;
    if new_bin {
        // New-bin candidate score: base cost of opening a bin
        score = 100.0;
        score -= 40.0 * (1.0 - progress); // cheaper to open bins early
        score += 20.0 * progress;         // expensive late; prefer consolidation
        // If the only alternative is a poor fit, opening a bin is more attractive
        if fitting_bins_count <= 1 {
            score -= 35.0;
        }
        // If the lookahead item is large, a fresh bin preserves capacity for it
        if next_item_size > item_size && next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
        // Many open bins with small mean residual -> avoid opening more
        if open_bins_count > 4 && mean_residual < 25.0 {
            score += 25.0;
        }
    }

    // Slight penalty for very full bins early on (keep some slack), none late
    score += 5.0 * (1.0 - progress) * (1.0 - bin_residual as f64 / bin_capacity as f64);

    // Mild open-bin count pressure: encourage closing out bins
    score += 0.5 * open_bins_count as f64 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;
    let post_norm = post_residual as f64 / cap;

    // Reward tight fits: low post_residual relative to capacity gets a strong discount,
    // amplified non-linearly by stream progress (late stream => pack tighter).
    let tightness = (1.0 - post_norm).powi(2);
    score -= 18.0 * tightness * (0.5 + 0.5 * progress);

    // Penalize small dead space that nothing can use later (smooth non-linear valley):
    // post_residual near the low end is bad unless it is (near) zero.
    let dead = post_norm * (1.0 - post_norm).max(0.0);
    score += 12.0 * dead * dead * 4.0 * (1.0 - fit_ratio);

    // Lookahead: bonus if next item fits exactly into the post residual.
    if next_item_size > 0 && (next_item_size as f64) <= post_residual as f64 {
        let perfect_next = ((post_residual as i64 - next_item_size as i64).abs() as f64) / cap;
        score -= 14.0 * (1.0 - perfect_next).powi(3);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0 + 8.0 * progress;
    } else if fitting_bins_count > 2 {
        // Many alternatives: mild penalty so we keep the best-fitting bins flexible.
        score += 2.0 * (fitting_bins_count as f64).ln();
    }

    // New-bin candidate handling: an empty bin has large residual; make it unattractive
    // unless the item is huge (poor fit elsewhere) or late in the stream with many bins.
    if bin_residual == bin_capacity {
        let big_item_bonus = (fit_ratio - 0.5).max(0.0) * 30.0;
        score += 15.0 + 6.0 * (open_bins_count as f64).sqrt() - big_item_bonus - 10.0 * progress;
    }

    // Mild coupling with mean residual: prefer bins whose residual is below average
    // (i.e., already partially filled) to consolidate.
    let rel = (post_residual as f64 - mean_residual) / cap;
    score += 4.0 * rel;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;

    // Harmonic class of the post-residual: quantize into capacity fractions
    let q = post_residual as f64 / cap; // in [0,1]
    // Dead-space penalty: residuals that can't fit typical small items are bad.
    if post_residual < 10 {
        score += 60.0; // near-perfect fill, reward strongly
    }

    // Lookahead: does the next item fit in the post-residual?
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            // Reward leaving room for the next item, scaled by how snugly it fits
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 + 20.0 * (1.0 - slack / cap);
        } else {
            // Penalize blocking the next item
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins are bad fits
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 10.0;
        }
        // Fewer open bins relative to stream progress -> new bin cheaper
        score += (open_bins_count as f64) * 1.5;
    }

    // Prefer bins whose residual is close to the mean residual (balanced packing)
    score += 0.15 * ((post_residual as f64) - mean_residual).abs();

    // Harmonic modulo structure: reward post_residual divisible into useful classes
    if post_residual % 50 == 0 {
        score -= 5.0;
    } else if post_residual % 25 == 0 {
        score -= 2.5;
    } else if post_residual % 10 == 0 {
        score -= 1.0;
    }

    // Late in stream: tighten packing, avoid spreading
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (q * q);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let min_useful = 10.0_f64.min(bin_capacity as f64);
    if post_residual > 0 && (post_residual as f64) < min_useful {
        score += (min_useful - post_residual as f64) * 4.0;
    }

    // Reward tight fits (low post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) / (post_residual as f64 + item_size as f64) * 8.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Lookahead coupling: if next item fits the post residual, reward this placement.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        score -= 6.0;
    } else if next_item_size > 0 && post_residual > 0 && (next_item_size as f64) > post_residual as f64 {
        score += 3.0; // dead space relative to lookahead
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open.
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score += 20.0 + (open_bins_count as f64) * 3.0 + mean_residual * 0.2;
        // Late in stream, prefer filling existing bins even more.
        score += progress * 15.0;
        // But if no open bin fits well (high mean residual mismatch), allow opening.
        if (mean_residual - item_size as f64).abs() > bin_capacity as f64 * 0.5 {
            score -= 10.0;
        }
    } else {
        // Fitting existing bin: mild reward scaled by how much residual it consumes.
        score -= (bin_residual - post_residual) as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward placements where the leftover exactly matches the next item.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual > next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            // Penalize gap between leftover and next item size (wasted potential).
            score += slack * 0.4;
        } else {
            // Next item won't fit here anyway; leftover is dead space.
            let dead = (next_item_size - post_residual) as f64;
            score += dead * 0.25;
        }
    } else {
        // Last item: just minimize leftover.
        score += 10.0;
    }

    // Reward bins with residual below mean (tighter packing).
    score += (mean_residual - bin_residual as f64) * 0.15;

    // Last-chance bin: penalize opening a new bin if this is the only fitting one.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New empty bin candidate: penalize unless current bin would leave large dead space.
    if bin_residual == bin_capacity {
        score += 30.0;
        if next_item_size > 0 && next_item_size > bin_capacity - item_size {
            score -= 45.0; // item + next item need a fresh bin
        }
    }

    // Mild penalty for many open bins (encourage consolidation early).
    score += open_bins_count as f64 * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post_residual relative to capacity)
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize dead space that cannot fit any plausible future item
    if post_residual > 0 && post_residual < 10 {
        score += 8.0; // tiny unusable sliver
    }

    // Lookahead: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64) / (post_residual as f64);
        } else {
            // next item won't fit here; mildly penalize leaving large gaps
            score += 0.05 * (post_residual as f64 - (bin_capacity - next_item_size) as f64).max(0.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless all fits are bad
    if bin_residual == bin_capacity {
        let pressure = (item_size as f64) / (bin_capacity as f64);
        let scarcity = 1.0 / (fitting_bins_count.max(1) as f64);
        score += 20.0 + 15.0 * pressure - 10.0 * scarcity;
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Prefer bins with residual below mean (compact bins first)
    score += 0.1 * ((mean_residual - bin_residual as f64).max(-50.0).min(50.0));

    // Slight preference for bins already open vs many bins proliferation
    score -= 0.5 * (open_bins_count as f64).ln().max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    let mut score = pr as f64;

    // Non-linear coupling: post_residual quadratic penalized more as stream progresses
    let quad = norm_pr * norm_pr;
    score += (1.0 + progress) * 12.0 * quad * cap * 0.1;

    // Perfect fit reward, stronger late
    let fit_term = (item_size as f64 / cap) * (bin_residual as f64 / cap);
    score -= 8.0 * fit_term * (0.5 + progress);

    // Penalize waste when few bins fit the item (last chance bin)
    if fitting_bins_count == 1 {
        score -= 10.0;
    } else {
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // Dead space: residual too small for typical items
    if pr > 0.0 && pr < 10.0 {
        score += 15.0 * (1.0 - pr / 10.0);
    }

    // Lookahead: reward residual that can hold next item
    if next_item_size > 0 && (pr as u32) >= next_item_size {
        score -= 3.0;
    }

    // Mild preference for bins below mean residual early (spread load), above late
    let dev = mean_residual - pr;
    score += (1.0 - 2.0 * progress) * dev * 0.05;

    // New-bin candidate: penalize opening new bins unless residual is truly unusable
    if bin_residual == bin_capacity {
        score += 6.0 + 20.0 * progress - 5.0 * (open_bins_count as f64).ln().max(0.0);
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 4.0; // pairing large items in fresh bins
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: residues that pair well with common item sizes
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Reward tight fits strongly
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 200.0;
    } else {
        // Penalize dead space in harmonic bands: residuals in awkward modulo classes
        let class = post_residual % 10;
        let class_penalty = match class {
            0 => -30.0,          // round residual: easy to fill later
            1 | 9 => 15.0,       // awkward slivers
            2 | 8 => 8.0,
            5 => -10.0,          // half-decade residuals pair with many sizes
            _ => 0.0,
        };
        score += class_penalty;

        // Fractional capacity classes: post_residual as fraction of capacity
        let frac = pr / cap;
        if frac < 0.1 {
            score -= 50.0;
        } else if frac > 0.6 {
            score += 40.0; // leaving a huge gap means a wasteful placement
        }
    }

    // Last-chance bin: strongly prefer filling the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize unless residual is large relative to item
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score = 60.0 + 40.0 * progress - (mean_residual - pr).abs();
        if fitting_bins_count == 0 {
            score -= 500.0; // must open a new bin
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 80.0; // new bin can also host the lookahead item
        }
    }

    // Lookahead coupling: if next item exactly fills the post-residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += 20.0; // next item cannot use this residual
        }
    }

    // Mild preference for bins below mean residual (consolidate emptier bins)
    score += (mean_residual - pr) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny leftover gaps (unusable for most items) are heavily penalized.
    if post_residual > 0 && post_residual <= 10 {
        score += 45.0 * (1.0 - (post_residual as f64) / 10.0);
    } else if post_residual == 0 {
        // Perfect fit is strongly rewarded.
        score -= 30.0;
    }

    // Reward tight fits relative to bin residual.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Open-bin pressure: with many open bins, prefer consolidating into existing bins
    // and make opening a new bin progressively less attractive.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let new_bin_penalty = 8.0 + 14.0 * open_bins_count as f64 + 10.0 * progress;
    if bin_residual == bin_capacity {
        score += new_bin_penalty;
    } else {
        score -= 6.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual, reward this placement;
    // if post-residual almost fits next item but not quite, penalize slightly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0;
        } else if post_residual > 0 && next_item_size > post_residual && (next_item_size - post_residual) <= 10 {
            score += 10.0;
        }
    }

    // Slight preference for bins whose residual is close to the mean (balanced usage).
    score += 0.15 * ((bin_residual as f64 - mean_residual).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);

    // 2-step lookahead: if next item exactly fills post_residual, strongly favor this bin.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            // next item fits here: reward proportional to how snugly
            score -= 25.0 * (next_item_size as f64) / (post_residual as f64);
            score += 0.5 * (post_residual - next_item_size) as f64;
        } else {
            // next item won't fit in the post residual; penalize leaving a gap
            // that is too small for the next item (dead space risk).
            let gap = post_residual as f64;
            let nxt = next_item_size as f64;
            if gap > 0.0 {
                score += 8.0 * (1.0 - gap / nxt);
            }
        }
    }

    // Relative-to-mean coupling: bins tighter than average are better targets.
    score -= 0.25 * (mean_residual - post_residual as f64);

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Empty new-bin candidate: penalize unless current bin would be left nearly empty
    // (i.e., item is huge relative to residual) — prefer reusing open bins generally,
    // but allow a fresh bin when the fit is very poor.
    if bin_residual == bin_capacity {
        score += 15.0;
        let fill_ratio = item_size as f64 / bin_capacity as f64;
        score -= 10.0 * fill_ratio;
        // If the item is huge and barely fits anywhere, a new bin is fine.
        if item_size as f64 > 0.8 * bin_residual as f64 {
            score -= 20.0;
        }
        // Early in stream, opening bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 8.0 * (1.0 - progress);
    }

    // Prefer bins that become perfectly full.
    if post_residual == 0 {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: penalize when post residual is small relative to item size.
    if item_size > 0 {
        score -= (bin_capacity as f64 - post_residual as f64) * 0.35;
    }

    // Penalize dead space: post residual that is too small to ever be useful.
    if post_residual < 10 && post_residual > 0 {
        score += 12.0; // creates unusable sliver
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: if next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 18.0;
    }
    // If next item is large and would need a fresh bin, slightly favor keeping
    // big residuals for it: penalize using a very full bin when next item huge.
    if next_item_size >= 60 && post_residual > 0 && post_residual < 20 {
        score += 8.0;
    }

    // New-bin candidate handling: empty bin should only win when fits are bad.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 55.0;
        // Cheaper to open new bins early in the stream.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 25.0 * (1.0 - progress);
        // If many bins fit the item, opening a new one is wasteful.
        if fitting_bins_count > 0 {
            score += 10.0 * (fitting_bins_count as f64).min(4.0);
        }
        // If no open bin fits well (item nearly fills residual elsewhere),
        // new bin is more attractive — handled implicitly by other scores.
    }

    // Prefer bins with residuals close to item size (minimize fragmentation).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.15;

    // Global state: spread load when many open bins have high mean residual.
    if open_bins_count > 0 {
        let mean_gap = (mean_residual - bin_residual as f64).abs();
        score += mean_gap * 0.05;
    }

    // Mild penalty for using bins with large residual when item is small
    // (save big space for big items), scaled by stream position.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if item_size < 30 && bin_residual > 70 {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Smooth non-linear polynomial coupling of post_residual with stream progress
    let prn = pr / cap; // normalized post residual in [0,1)
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    // polynomial in progress that reshapes residual preference over the stream
    let poly = 1.0 + 0.8 * progress - 1.2 * prog2 + 0.6 * prog3;
    score -= 18.0 * prn * poly;

    // Penalize very tight fits (dead space) with a smooth quadratic term
    let tightness = 1.0 - prn; // how full the bin becomes
    score += 6.0 * tightness * tightness * (1.0 - progress);

    // Lookahead: reward leaving room for the next item (smooth interaction)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = pr - nxt;
        if gap >= 0.0 {
            let g = gap / cap;
            score -= 10.0 * g * (1.0 - g * g) * (0.5 + 0.5 * progress);
        } else {
            score += 8.0 * (-gap / cap) * (0.5 + 0.5 * progress);
        }
    }

    // Last-chance bin bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 - 0.5 * progress);
    } else if fitting_bins_count > 2 {
        score += 2.0 * (fitting_bins_count as f64 - 2.0);
    }

    // Mild preference toward consolidating into bins below the mean residual
    score += 3.0 * ((pr - mean_residual) / cap);

    // Slight penalty for opening new bins when many bins are already open late in stream
    if bin_residual == bin_capacity {
        score += 4.0 + 6.0 * progress + 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-fit residual: classify dead space by
    // integer division thresholds (coarse vs fine residual).
    let post = post_residual as u32;
    let coarse = post / 20; // class 0..5 : 0-19, 20-39, ...
    // Penalize residuals in "awkward" classes that few item sizes can fill.
    let awkward = match coarse {
        0 => 0.0,               // tiny dead space, fine
        1 => 2.5,               // 20-39: hard to fill
        2 => 0.5,               // 40-59: medium items fit
        3 => 1.5,               // 60-79
        _ => -1.0,              // large residual, still flexible
    };
    score += awkward;

    // Strong reward for near-perfect fit (modulo-style harmony).
    if post == 0 {
        score -= 50.0;
    } else if post <= 5 {
        score -= 15.0;
    } else if post <= 10 {
        score -= 6.0;
    }

    // Lookahead: reward if next item fits into post_residual (chained fit).
    if next_item_size > 0 {
        if next_item_size <= post {
            score -= 8.0;
            // extra harmony: next item fills post residual almost exactly
            let chain_gap = post - next_item_size;
            if chain_gap <= 5 {
                score -= 7.0;
            }
        } else {
            // next item won't fit here: mild penalty proportional to overshoot
            score += ((next_item_size - post) as f64) * 0.08;
        }
    } else {
        // last item: only tightness matters
        score -= 10.0;
    }

    // Last-chance bin: strongly favor using the single fitting bin
    // rather than opening a new one (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
        if post > 60 {
            // fit leaves a huge hole; soften the last-chance bonus
            score += 6.0;
        }
    }

    // New-bin candidate handling: empty bin has residual == capacity.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when current bin fits poorly.
        // Base cost of a fresh bin + its natural flexibility.
        score = 100.0 - (item_size as f64) * 0.3;
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative
        }
        // If an existing bin achieves a near-tight fit, discourage new bin.
        if post == 0 || post <= 5 {
            score += 30.0;
        }
    }

    // Mild pressure to consolidate when many bins are open.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln() * 1.5;
    }

    // Favor bins whose residual deviates favorably from mean residual.
    score -= (mean_residual - post as f64) * 0.05;

    // Stream progression: early on, be a bit more flexible (discount penalties).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

