    // Penalize leaving residuals that are awkwardly small but nonzero
    // (dead space unlikely to be usable).
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    // Compare against mean residual: prefer bins that are already
    // relatively full (residual below mean) to consolidate waste.
    score += 0.25 * (bin_residual as f64 - mean_residual);

    // Last-chance bonus: if this is the only bin that fits, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && post_residual < item_size as f64 as u32 + 1 {
        score -= 15.0;
    }

    // New-bin candidate (empty bin): make it attractive only when the
    // fit into existing bins is poor (large post_residual) or few bins fit.
    if bin_residual == bin_capacity {
        let poor_fit = post_residual as f64 / bin_capacity as f64;
        score = 55.0 + 40.0 * poor_fit;
        if fitting_bins_count <= 1 {
            score -= 30.0; // opening a new bin is reasonable when nothing else fits well
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer small post_residual, non-linearly.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness * tightness;

    // Exact or near-exact fill bonus.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual < 10 {
        score -= 20.0;
    } else if post_residual > 40 {
        // Large dead space penalty, scaled by how much worse than average this is.
        score += 0.6 * ((post_residual as f64) - mean_residual).max(0.0);
    }

    // Lookahead: reward if the next item fits into the post residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let pair_eff = (item_size + next_item_size) as f64 / cap;
        score -= 8.0 * pair_eff;
    } else if next_item_size > 0 && next_item_size <= bin_residual && next_item_size > post_residual {
        // Next item would no longer fit here after this placement: penalize.
        score += 4.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Late in the stream, consolidate into fewer bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if progress > 0.7 && bin_residual < bin_capacity {
        score -= 5.0 * progress;
    }

    // Many open bins: discourage spreading into fresh bins; prefer filling existing ones.
    let spread_penalty = 0.15 * (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize moderately, less if it's a very tight fit.
        score += 10.0 + spread_penalty * 10.0 - 6.0 * tightness;
        // Opening a new bin is good if no existing bin is a decent fit.
        if fitting_bins_count == 0 {
            score -= 25.0;
        }
    } else {
        // Reward using bins that are already partially filled.
        score -= spread_penalty;
    }

    // Mild preference for bins with residual close to item size (best fit).
    score += 0.05 * ((bin_residual as f64) - (item_size as f64)).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
