    if bin_residual == bin_capacity {
        let crowding = 1.0 - (mean_residual / cap).min(1.0);
        let pressure = crowding * (1.0 - progress) + (open_bins_count as f64 / 20.0) * progress;
        score = cap + 10.0 - 14.0 * pressure.min(1.5);
    }

    // Penalize bins whose residual deviates far below mean (fragmentation spread).
    score += 0.4 * ((post - mean_residual).abs() / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residual mod capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;

    // Classify post_residual into harmonic classes (quarters of capacity)
    let quarter = (bin_capacity / 4).max(1);
    let class = post_residual / quarter;
    // Penalize dead-space classes: residual in (0, smallest plausible item) is unusable
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Reward exact/tight fits
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 30.0;
    }

    // Harmonic coupling: post_residual class vs next_item_size class
    if next_item_size > 0 {
        let nq = next_item_size / quarter.max(1);
        // If next item fits perfectly into post_residual, big reward
        if post_residual >= next_item_size {
            let npost = post_residual - next_item_size;
            if npost <= 5 { score -= 45.0; }
            else if npost < 10 { score += 15.0; }
            else {
                // reward when post_residual is a harmonic multiple of next item
                if post_residual % next_item_size.max(1) == 0 {
                    score -= 25.0;
                }
            }
        } else {
            // next item cannot fit here: residual becomes dead space risk
            score += 0.5 * (next_item_size as f64 - pr).max(0.0);
        }
        // modulo-class affinity: same class residual/next-item
        if class == nq && post_residual >= next_item_size {
            score -= 12.0;
        }
    } else {
        // last item: prefer filling as tightly as possible
        score -= 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 35.0;
    }

    // New-bin candidate: only attractive if current bins have poor fits
    if bin_residual == bin_capacity {
        let tightness = mean_residual / cap;
        // opening new bin is penalized when good fits exist elsewhere
        score += 55.0 - 45.0 * tightness;
        if post_residual > 0 { score -= 5.0; } // neutral marker
    }

    // Prefer bins whose residual deviates below mean (more filled)
    score += 0.15 * (mean_residual - bin_residual as f64);

    // Late-stream pressure: consolidate more aggressively as stream ends
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - frac);

    // Slight preference for bins with smaller residual overall
    score += 0.05 * bin_residual as f64 / cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals too small for the smallest plausible item are wasted.
    let dead_threshold = 12.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Reward tight fits relative to bin capacity.
    score -= (1.0 - (post_residual as f64 / cap)) * 8.0;

    // Last-chance bonus: only this bin can fit the item.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Check if next item could use the post_residual.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 12.0; // leaves room for lookahead
        } else {
            score += 5.0; // dead space relative to next item
        }
    }

    // Open-bin pressure: fewer bins -> prefer spreading into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // New-bin candidate: only attractive when existing bins fit poorly or none exist.
    if bin_residual == bin_capacity {
        score = 90.0 + (open_bins_count as f64) * 2.0;
        if fitting_bins_count == 0 {
            score = 10.0;
        }
        if next_item_size > 0 && (next_item_size as u32) <= item_size.saturating_sub(0) && (post_residual as f64) >= (next_item_size as f64) {
            // fresh bin always accommodates lookahead
            score -= 5.0;
        }
        // discourage opening new bins when a decent fit exists
        if fitting_bins_count > 0 {
            let best_gap = mean_residual - (item_size as f64);
            if best_gap >= 0.0 && best_gap < 30.0 {
                score += 60.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strong reward for perfect or near-perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 10 {
        score -= 500.0 - (post_residual as f64) * 20.0;
    }

    // Aggressive 2-step lookahead: reward if next item fits the post-residual
    if next_item_size > 0 {
        let nres = post_residual as u32;
        if nres >= next_item_size {
            let slack_after_next = nres - next_item_size;
            // Reward tight two-item packing
            if slack_after_next == 0 {
                score -= 800.0;
            } else {
                score -= 300.0 * (1.0 - slack_after_next as f64 / cap);
            }
        } else {
            // Penalize residual that is just barely too small for next item (dead space)
            let gap = (next_item_size - nres) as f64;
            if gap <= 10.0 {
                score += 150.0 * (1.0 - gap / 10.0);
            }
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += (post_residual as f64 - mean_residual) * 1.5;

    // Last chance: strongly favor using the only bin that fits to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 400.0;
    }

    // Prefer fuller bins generally (waste-normalized)
    score -= (bin_residual as f64 / cap) * 50.0;

    // Mild penalty for opening new bins early in the stream
    if bin_residual == bin_capacity {
        score += 60.0 + 40.0 * (1.0 - step_index as f64 / total_items.max(1) as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) non-linearly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Penalize dead space that is too small to be useful later (items >= 1,
    // but small residuals below typical next item sizes are wasted).
    if post_residual > 0 {
        let usable = (post_residual as f64) / (bin_capacity as f64);
        score += 6.0 * (1.0 - usable) * (1.0 - usable);
    }

    // Lookahead coupling: reward if next item fits exactly in post_residual,
    // penalize if post_residual is just barely too small for next item.
    if next_item_size > 0 {
        let n = next_item_size as f64;
        if (next_item_size as u32) == post_residual {
            score -= 25.0; // perfect pair
        } else if post_residual >= next_item_size {
            score -= 10.0 * (n / (bin_capacity as f64));
        } else {
            let gap = (next_item_size - post_residual) as f64;
            if gap < 12.0 {
                score += 8.0 * (1.0 - gap / 12.0); // near-miss dead space
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when current fit is poor or many bins
    // already open with low mean residual (fragmentation).
    if bin_residual == bin_capacity {
        let fit_quality = (item_size as f64) / (bin_capacity as f64);
        let poor_fit = 1.0 - fit_quality; // small item in fresh bin => poor
        let fragmentation = mean_residual / (bin_capacity as f64);
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut nb = 12.0 - 10.0 * fragmentation - 6.0 * poor_fit;
        // Late in stream, prefer consolidating into open bins.
        nb += 10.0 * progress;
        // If many bins fit the item, opening a new bin is wasteful.
        if fitting_bins_count > 2 {
            nb += 15.0;
        }
        score += nb;
    }

    // Mild preference for fuller bins when many bins are open.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_norm = pr / cap;

    // Base: waste after placement, softly damped by progress
    let mut score = pr * (1.0 - 0.25 * progress);

    // Non-linear penalty for awkward residuals (mid-range dead space)
    let awkward = (fit_norm - 0.5) * (fit_norm - 0.5);
    score += 20.0 * awkward * (1.0 + progress);

    // Reward tight fits via smooth cubic term
    score -= 15.0 * (1.0 - fit_norm).powi(3);

    // Lookahead coupling: prefer bins whose post-residual matches next item
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let match_term = 1.0 - ((pr - nxt).abs() / cap);
        score -= 10.0 * match_term * match_term;
        // penalize if next item cannot fit
        if pr < nxt {
            score += 8.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bonus: only fitting bin left
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - 0.5 * progress);
    }

    // Slight penalty when many bins open and residual is large
    score += (open_bins_count as f64).ln() * fit_norm * 2.0;

    // Mean residual interaction: favor bins deviating below mean (balance)
    score += 0.15 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: capacity fractions (C/1..C/6)
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut harmonic_bonus = 0.0;
    for k in 1..=6u32 {
        let frac = c / k as f64;
        let dist = (pr - frac).abs();
        harmonic_bonus += (c / 8.0 - dist).max(0.0) / k as f64;
    }
    score -= 0.35 * harmonic_bonus;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual < 10 {
        score -= 150.0; // near-dead space is great
    }

    // Penalize dead space that no future item (min size 1, typical >=10) can use
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }

    // Coupling with next item: reward if next item fits into post_residual
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 60.0;
            // extra reward when next item exactly fills the remainder
            if next_item_size == post_residual {
                score -= 300.0;
            }
        } else {
            score += 0.25 * (next_item_size - post_residual) as f64;
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 200.0;
    }

    // New-bin candidate: keep it competitive only when open bins are crowded
    if bin_residual == bin_capacity {
        let crowding = (mean_residual / c).clamp(0.0, 1.0);
        score = c - 120.0 * crowding + 0.5 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 20.0;
        }
    }

    // Late stream: tighten packing, discourage sprawl
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 0.15 * open_bins_count as f64;

    // Prefer bins tighter than the mean residual
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold any
    // plausible future item (below min item size 1... but practically below
    // ~10) are "dead" — penalize them extra hard.
    if post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Small gap: likely unusable unless a tiny item arrives.
        score += 25.0;
    } else if post_residual < 30 {
        score += 8.0;
    }

    // Reward tight fits: small post_residual relative to residual means the
    // bin was nearly perfectly filled.
    let fit_ratio = if bin_residual > 0 {
        item_size as f64 / bin_residual as f64
    } else {
        0.0
    };
    score -= 30.0 * fit_ratio;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 15.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: discourage opening new bins when many are open,
    // but allow it when few are open (early stream, keep options open).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure from open bins.
        score += 20.0 + 6.0 * open_bins_count as f64 * (0.5 + 0.5 * progress);
        // But if the new bin would be attractive for the lookahead item
        // (large next item unlikely to fit elsewhere), soften the cost.
        if next_item_size > 0 && next_item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    } else {
        // Placing into an existing bin reduces open-bin pressure slightly.
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    // Lookahead coupling: if the resulting residual can exactly host the
    // next item, reward it; if it cannot host next item but could have
    // hosted something, mild penalty.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 20.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            score += 5.0;
        }
    }

    // Prefer bins whose residual is close to the item (waste minimization
    // relative to the fleet mean residual).
    if bin_residual != bin_capacity {
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward exact/near-perfect fits heavily.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else {
        // Penalize dead space that is too small for typical items (unusable gap).
        let min_item = 1.0f64;
        if (post_residual as f64) < min_item {
            score += 50.0;
        }
        // Non-linear penalty for large but awkward residuals.
        let pr = post_residual as f64;
        score += 0.02 * pr * pr / bin_capacity as f64;
    }

    // 2-step lookahead: reward bins whose post_residual matches next item size well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let gap = pr - nxt;
            if gap == 0.0 {
                score -= 500.0; // perfect 2-chain
            } else {
                score -= 150.0 * (1.0 - gap / bin_capacity as f64);
            }
        } else {
            // Next item won't fit here: mild penalty proportional to overshoot.
            score += 0.5 * (nxt - pr);
        }
    } else {
        // Last item: strongly prefer tightest fit.
        score += 0.0;
    }

    // Relative to mean residual: prefer bins already more filled than average.
    let pr = post_residual as f64;
    score += 0.3 * (mean_residual - pr);

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 120.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    // and the item is large (better to keep small residual bins for small items).
    if bin_residual == bin_capacity {
        let fit_quality = item_size as f64 / bin_capacity as f64;
        let pressure = if next_item_size > 0 && next_item_size >= item_size { 1.0 } else { 0.0 };
        // Default penalty; reduced when the fit elsewhere would be poor and item is big.
        score += 80.0 - 60.0 * fit_quality - 40.0 * pressure;
        // Early in stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // Many open bins with low mean residual => avoid spreading.
        if mean_residual > 40.0 {
            score += 30.0;
        }
    }

    // Slight preference for bins with small residual overall (best-fit flavor).
    score += 0.1 * (bin_residual as f64 - item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 0.6 * (next_item_size as f64 - post_residual as f64);
    }
    // Reward residuals that exactly accommodate the next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Prefer bins whose residual deviates below the mean (fill laggard bins).
    score += 0.25 * (mean_residual - bin_residual as f64);

    // Late in the stream, consolidate: penalize spreading across many open bins.
    let progress = step_index as f64 / total_items as f64;
    score += 0.05 * open_bins_count as f64 * (1.0 - progress);

    // New-bin candidate: only attractive when current bin is a very poor fit
    // (item barely fits leaving a large useless residual) or no open bin fits well.
    if bin_residual == bin_capacity {
        let waste = post_residual as f64 / bin_capacity as f64;
        let poor_fit = if fitting_bins_count > 0 {
            (bin_residual - item_size).min(100) as f64
        } else { 0.0 };
        score = 55.0 + 40.0 * waste - poor_fit * 0.3 - 20.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 5.0; // fresh bin can host next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early on (progress ~ 0): mild penalty on large residuals (keep bins flexible).
    // Late (progress ~ 1): strongly prefer tight fits (minimize post_residual harder).
    let tightness = pr / cap;
    let poly = tightness * tightness * (0.5 + 2.0 * progress * progress);
    score += poly * cap * (0.25 + progress);

    // Exact fit reward: smooth non-linear bonus for near-zero post residual.
    let exact = 1.0 - (pr / cap);
    score -= exact * exact * exact * (5.0 + 10.0 * progress);

    // Lookahead coupling: reward residuals that can still host the next item,
    // penalize residuals that are just barely too small (dead space).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let gap = pr - nx;
        if gap >= 0.0 {
            score -= 4.0 * (1.0 - gap / cap); // residual can host next item
        } else {
            // unusable dead space penalty, stronger as stream progresses
            score += (nx - pr) / cap * (6.0 + 8.0 * progress);
        }
    }

    // Last-chance bin: strongly reward using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 8.0 + 12.0 * progress;
    } else if fitting_bins_count > 1 {
        // competition among fitting bins: prefer tighter ones (handled by pr), slight penalty to spread
        score += 1.0;
    }

    // New-bin candidate handling: penalize opening a fresh bin unless the item
    // fits poorly everywhere else. Empty-bin call has pr == cap.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin; decays with progress (late items
        // often need fresh bins, avoid over-penalizing then).
        score += 6.0 * (1.0 - 0.5 * progress);
        // If item is large relative to capacity, a new bin is more acceptable.
        score -= (item_size as f64 / cap) * 4.0;
        // If many bins already open, mild extra penalty to avoid bin explosion.
        score += (open_bins_count as f64).ln().max(0.0);
        // If mean residual across open bins is small, new bin justified.
        score -= (mean_residual / cap).max(0.0) * 3.0;
    } else {
        // Reward reusing existing bins relative to mean residual state.
        score -= (mean_residual - pr) / cap * 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues modulo 10 and integer-division thresholds.
    let post_class = post_residual / 10;
    let post_mod = post_residual % 10;

    // Small usable post-residuals are good: reward post_residual in [0, 10) heavily.
    if post_residual == 0 {
        score -= 1000.0; // perfect fit
    } else if post_residual <= 10 {
        score -= 60.0;
    } else if post_residual <= 20 {
        score -= 20.0;
    } else if post_residual <= 30 {
        score -= 5.0;
    } else {
        // Dead space penalty grows super-linearly beyond 30.
        score += (post_residual as f64 - 30.0) * 0.8;
    }

    // Odd residues (non-multiples of 10) are less likely to be matched by future items
    // drawn from typical distributions: penalize misalignment.
    if post_mod != 0 {
        score += post_mod as f64 * 0.5;
    }

    // Harmonic matching with the lookahead item: if next_item_size fits exactly into
    // post_residual, this placement sets up a perfect follow-up.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 300.0;
        } else if next_item_size <= post_residual {
            let next_post = post_residual - next_item_size;
            // Reward follow-up placements that leave small residuals again.
            score -= (next_post <= 10) as i32 as f64 * 40.0;
            score += next_post as f64 * 0.15;
        } else {
            // The next item cannot use the leftover at all: mild penalty scaled by waste.
            score += (next_item_size - post_residual) as f64 * 0.05;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when the item fits poorly
    // everywhere else (large dead space would be created in every open bin).
    if bin_residual == bin_capacity {
        // Neutral base for a new bin; tie-break against mediocre fits.
        score += 25.0;
        // If mean residual across open bins is large, opening a new bin wastes it: penalize.
        score += mean_residual * 0.3;
        // Late in the stream, prefer consolidating into existing bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += progress * 40.0;
    } else {
        // Favor tighter (more full) bins: use residual fraction as a harmonic reward.
        let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
        score -= fill * 30.0;
    }

    // Prefer placing into bins that are already well-filled among many open bins.
    if open_bins_count > 4 && bin_residual < bin_capacity {
        score -= 5.0;
    }

    // Integer-division threshold coupling: residual classes above 50 are half-empty bins,
    // discourage dumping small items there when a tighter bin exists.
    if post_class >= 5 {
        score += 15.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = 0.0;

    // Base: prefer minimal post_residual (tight fit), with superlinear penalty
    // for dead space that becomes "unusable" (too small for typical items).
    let pr = post_residual as f64;
    score += pr * 0.7;

    // Strict dead-space avoidance: residuals in (0, 10) are essentially dead
    // (min item size 1, but small gaps rarely combine usefully); residuals in
    // [10, 30) can only host small items. Penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual < 30 {
        score += 12.0;
    } else if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 30.0;
    }

    // Dead space relative to capacity: penalize wasting a mostly-empty bin.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= fill_ratio * 8.0;

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // this is an excellent pairing; if the post_residual cannot fit the next
    // item but residual could have, penalize.
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        if next_item_size <= post_residual {
            // Next item can go in this bin afterwards: reward, more so if snug.
            let snug = 1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 6.0 + 10.0 * snug;
        } else {
            // Post-residual unusable for the next item: mild penalty scaled by
            // how much of the gap is wasted.
            let waste = (post_residual as f64) / bin_capacity as f64;
            score += 4.0 * waste;
        }
    }

    // Open-bin pressure: when many bins are open, prefer consolidating into
    // existing bins (avoid spreading); when few bins are open, opening a new
    // one is cheaper.
    let pressure = (open_bins_count as f64).ln() * 3.0;
    score += pressure * (pr / bin_capacity as f64);

    // Last-chance bonus: if this is the only bin that fits the item, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: an empty bin has large post_residual, which
    // the base term already penalizes; add a mild bias so a new bin is chosen
    // only when existing bins would create truly dead gaps.
    if bin_residual == bin_capacity {
        score += 6.0;
        // Early in the stream, opening bins is cheaper; late, discourage.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 * (1.0 - progress) - 8.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far below the mean,
    // it is already fragmented; prefer bins with above-mean residual.
    let res = bin_residual as f64;
    if mean_residual > 0.0 {
        score += (mean_residual - res) * 0.15;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = (post_residual as f64) * 1.17;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (tiny post residual).
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 5 {
        score -= 120.0;
    } else if post_residual <= 10 {
        score -= 60.0;
    }

    // Fractional tightness reward: closer fit => bigger discount.
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 80.0 * fill * fill;

    // Lookahead (k=2): reward bins whose post_residual can host the next item,
    // with a bonus for an exact pair match (item + next fills the bin).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 150.0;
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // Next item cannot follow here: slight penalty proportional to overflow.
            let over = (next_item_size - post_residual) as f64;
            score += 0.3 * over;
        }
    }

    // Last chance bin: if this is the only bin that fits, prefer using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 70.0;
        if post_residual <= 10 {
            score -= 40.0;
        }
    }

    // New-bin candidate handling: opening a bin is only attractive when no
    // open bin offers a decent fit, or the stream is early and bins are few.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        // If mean residual barely exceeds the item, existing bins are poor fits
        // => make new bin competitive.
        score -= 25.0 + 0.5 * mean_gap;
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // Early in the stream, opening fresh bins is cheaper long-term.
        score -= 60.0 * (1.0 - progress);
        if open_bins_count == 0 {
            score -= 100.0;
        }
    } else {
        // Penalize placing into bins whose residual is far above the item
        // (wasteful large hole creation) relative to global mean residual.
        let waste = (bin_residual - item_size) as f64;
        if waste > mean_residual {
            score += 0.4 * (waste - mean_residual);
        }
    }

    // Mild penalty for proliferating open bins late in the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 1.5 * open_bins_count as f64 * progress;

    // Small nudge toward using larger residuals when item is large.
    if item_size > bin_capacity / 2 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let fill = 1.0 - pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic/cubic) shaping
    let mut score = pr * (1.0 + 0.35 * fill * fill);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early stream -> tolerate larger residuals; late stream -> punish them harder
    let progress_coupling = pr * progress * (1.0 + 0.8 * progress * (1.0 - fill));
    score += 1.2 * progress_coupling;

    // Reward tight fits via cubic fill term
    score -= 12.0 * fill * fill * fill;

    // Dead-space penalty: residuals too small for typical future items
    let dead = if pr < next_item_size as f64 && next_item_size > 0 { pr } else { 0.0 };
    score += 2.5 * dead * (0.5 + progress);

    // Lookahead: favor bins whose post-residual accommodates next item
    if next_item_size > 0 && pr >= next_item_size as f64 {
        let nxt = next_item_size as f64;
        score -= 6.0 * (nxt / cap) * (1.0 - (pr - nxt) / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 15.0 * fill;
    }

    // Scarcity pressure: many open bins -> prefer consolidation
    let pressure = (open_bins_count as f64 / (1.0 + mean_residual / cap)).ln();
    score += 1.5 * pr * (1.0 / (1.0 + pressure.abs()));

    // New-bin candidate: neutral-ish baseline, slightly worse as stream matures
    if bin_residual == bin_capacity {
        score = cap * (0.9 + 0.6 * progress) - 4.0 * fit_ratio;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into coarse buckets.
    let q = bin_capacity / 10; // quantum = 10
    let post_class = post_residual / q;
    let fit_class = (bin_residual.saturating_sub(item_size)) % q;

    // Reward exact / near-exact fills (waste minimization).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= q / 2 {
        score -= 25.0;
    }

    // Penalize dead space quadratically within its harmonic class.
    score += (post_class as f64) * (post_class as f64) * 4.0;

    // Modulo coupling: residuals that are multiples of the quantum are reusable
    // by typical item sizes; odd remainders are harder to fill.
    if fit_class == 0 {
        score -= 12.0;
    } else {
        score += fit_class as f64 * 1.5;
    }

    // Lookahead harmony: prefer bins whose post residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 18.0;
            // Extra harmony if post residual minus next item stays tiny.
            let two_step = post_residual - next_item_size;
            if two_step <= q / 2 {
                score -= 15.0;
            }
        } else {
            score += 8.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only open a new bin when existing fits are bad
    // (large post residual relative to item) or few bins are open.
    if bin_residual == bin_capacity {
        let tightness = item_size as f64 / bin_capacity as f64;
        let open_fit_bad = fitting_bins_count == 0
            || (post_residual as f64) > 0.6 * bin_capacity as f64;
        if open_fit_bad || tightness > 0.7 {
            score -= 55.0;
        } else {
            score += 45.0 + open_bins_count as f64 * 2.0;
        }
    }

    // Mild preference to consolidate into emptier bins early on.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (mean_residual - post_residual as f64) * 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small for any
    // plausible future item (<= 10) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 12.0;
    }
    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Reward tight fits nonlinearly (smaller post_residual, bigger bonus).
        let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
        score -= tightness * tightness * 15.0;
    }

    // If the next item fits exactly in the post_residual, big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 20.0;
        } else if gap < 10 {
            score -= 8.0;
        } else {
            score -= 4.0;
        }
    }
    // Penalize leaving a gap that cannot host the next item.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: baseline near capacity residual, penalized by pressure.
        score = bin_capacity as f64 * 0.5 + pressure * 2.0 + mean_residual * 0.3;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    } else {
        // Favor bins whose residual deviates less from mean (keeps residuals uniform).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.15;
        // Mild bonus for using already-open bins scales with open-bin count.
        score -= pressure * 0.4;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 25.0;
    }

    // 2-step lookahead: reward when next item fits exactly into post_residual
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if nxt <= pr {
            let match_quality = 1.0 - ((pr - nxt) / cap).abs();
            score -= 8.0 * match_quality;
            if (pr - nxt) as u32 == 0 {
                score -= 20.0; // chain of perfect fits
            }
        } else {
            // next item won't fit here; penalize leaving a large unusable gap
            score += 0.05 * (pr - (pr % nxt.max(1.0)));
        }
    }

    // Compare post_residual to mean residual: keep residual diversity
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.10 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is terrible
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 10.0;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
    }

    // Mild pressure to fill bins tightly as stream progresses
    score -= 0.02 * (item_size as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (non-linearly).
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 14.0 * fit_ratio * fit_ratio;

    // Penalize dead space: post_residual that no future item can use.
    if post_residual > 0 && post_residual < 10 {
        score += 30.0; // tiny unusable sliver
    }

    // Lookahead coupling: if next item fits into post_residual, big reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 12.0 + 0.1 * next_item_size as f64;
    } else if next_item_size > post_residual {
        score += 3.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let poor_fits = (fitting_bins_count == 0) as f64
            + (bin_residual - item_size > 60) as f64; // item would leave big hole in any bin
        score += 20.0 - 25.0 * poor_fits - 8.0 * progress;
        // penalize opening bins when many already open with slack
        score += 0.5 * open_bins_count as f64;
        score -= 0.2 * mean_residual;
    }

    // Global slack awareness: prefer bins below mean residual (balance load lightly).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    // Slight time-horizon term: late in stream, consolidate more aggressively.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Non-linear polynomial coupling of post_residual with stream progress.
    // Early in the stream: aggressively fill bins (penalize large post_residual quadratically).
    // Late in the stream: prefer tight fits too, but weight differently.
    let pr = post_residual as f64 / bin_capacity as f64;
    let poly = pr * pr * (1.0 - progress) + pr * pr * pr * progress;
    score += 40.0 * poly;

    // Reward near-perfect fits smoothly.
    let tightness = 1.0 - pr;
    score -= 12.0 * tightness * tightness;

    // Last-chance bin: strong bonus to use it rather than open a new one.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Lookahead: if next item fits exactly in post_residual, reward strongly (smoothly).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 10.0 * (1.0 - gap / bin_capacity as f64).max(0.0) * (1.0 - gap / bin_capacity as f64);
    }

    // Penalize bins whose residual deviates from mean (fragmentation signal).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.5 * dev / (1.0 + progress);

    // Slight preference for keeping number of open bins low late in stream.
    score += 0.05 * open_bins_count as f64 * progress;

    // New-bin candidate: only attractive when no good fit exists (large post_residual elsewhere).
    if bin_residual == bin_capacity {
        score += 20.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residues are dead space
    let pr = post_residual;
    if pr <= 10 {
        score -= 30.0; // tiny dead space is fine
    } else if pr <= 20 {
        score -= 5.0;
    } else if pr <= 35 {
        score += 10.0;
    } else {
        score += 25.0; // large leftover risks waste
    }

    // Modulo classes: residues divisible by 10 pair well with common item sizes
    if pr % 10 == 0 && pr > 0 {
        score -= 12.0;
    }
    if pr % 5 == 0 && pr > 0 {
        score -= 4.0;
    }
    // Odd awkward residues
    if pr % 2 == 1 && pr > 15 {
        score += 6.0;
    }

    // Lookahead coupling: can next item fill the leftover?
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0; // chain fit
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 40.0 * (1.0 - slack / cap);
        } else {
            // next item cannot use leftover; larger leftover is more wasteful
            score += 0.3 * (pr as f64 - (cap - next_item_size as f64)).max(0.0);
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a new bin unless existing fits are bad
    if bin_residual == bin_capacity {
        score = cap + 40.0 - (fitting_bins_count as f64) * 5.0;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0;
        }
    }

    // Late-stream consolidation: fewer open bins preferred as stream ends
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 10.0 * (open_bins_count as f64).sqrt() * 0.1;

    // Prefer bins tighter than average
    score -= 0.5 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to hold the minimum
    // item (1) are pure waste; treat gaps below a "dead zone" as heavily
    // penalized unusable space.
    let dead_threshold = 10.0_f64.min(bin_capacity as f64 * 0.1);
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    if post_residual == 0 {
        // Perfect fit: strong reward.
        score -= 40.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 15.0;

    // Coupling with lookahead: if next item fits exactly in post_residual,
    // this placement chains perfectly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
        } else {
            // Next item cannot use this residual: residual likely becomes dead.
            score += (post_residual as f64) * 0.5;
        }
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * (2.0 + 3.0 * progress);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: an empty bin is attractive when no open bin
    // fits well (post_residual large relative to capacity) or many bins are
    // already open with poor residuals.
    if bin_residual == bin_capacity {
        let poor_fit = (post_residual as f64) / bin_capacity as f64 > 0.5;
        let crowded = open_bins_count as f64 > 3.0 && mean_residual < item_size as f64;
        if poor_fit || crowded || fitting_bins_count == 0 {
            score -= 35.0;
        } else {
            // Prefer reusing an existing bin with decent fit.
            score += 20.0;
        }
    }

    // Mild preference for balancing residuals toward the mean.
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (small post_residual), but penalize leaving
    // dead space that no plausible item can fill (post_residual < 10 is fine,
    // 1..=9 dead space is worst).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // 2-step lookahead: reward when the next item exactly fills the post_residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain
        } else if next_item_size < post_residual {
            // next item fits here afterward: good, closer is better
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item can't use the leftover: penalize proportionally to waste
            score += 12.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Compare post_residual against mean residual: avoid making this bin an outlier
    // with much more leftover than average unless it's a near-perfect fit.
    score += 0.35 * (post_residual as f64 - mean_residual).max(0.0);

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // New-bin candidate handling: make the empty bin attractive only when the item
    // is large relative to capacity or current fits are poor.
    if bin_residual == bin_capacity {
        // base cost of opening a new bin
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && next_item_size <= item_size {
            score -= 15.0; // next item likely fits the new bin's residual too
        }
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
        // late in the stream, avoid spawning bins with big residuals
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Slight preference for using fuller bins overall
    score += 0.1 * (bin_capacity - bin_residual) as f64 * -0.0
        - 0.1 * (bin_capacity - bin_residual) as f64 * 0.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong preference for tight fits: square the waste.
    score += (post_residual as f64).powi(2) / (bin_capacity as f64);

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0 + (next_item_size as f64) * 0.15;
    } else if next_item_size > 0 {
        // Penalize leaving a residual just below the next item (dead space).
        score += (next_item_size as f64 - post_residual as f64).min(30.0) * 0.4;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        // Small unusable residue is nearly a perfect fit.
        score -= 15.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize scattering across many open bins when few are needed.
    if fitting_bins_count > 1 {
        // Prefer bins whose residual deviates from the mean (consolidate similar bins).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    }

    // New-bin candidate logic: only attractive when no decent fit exists.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 {
            1.0
        } else {
            // Compare best possible post-residual in existing bins vs this item's demand.
            let waste_elsewhere = (bin_residual as f64 - item_size as f64).max(0.0);
            if waste_elsewhere > 35.0 { 0.7 } else { 1.5 }
        };
        // Early in stream: more willing to open bins; late: consolidate.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let open_penalty = (open_bins_count as f64) * 1.5 * (0.5 + progress);
        score = 60.0 * poor_fit + open_penalty;
        if next_item_size > 0 && (bin_capacity as u32 - item_size) >= next_item_size {
            score -= 10.0; // fresh bin can host next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let fit_ratio = item_size as f64 / cap;

    let mut score = pr;

    // Non-linear reward for tight fits (small post_residual), stronger as stream progresses.
    let tightness = (pr / cap).powi(3);
    score += tightness * 40.0 * (0.5 + progress);

    // Penalize leaving residual just below a "useful" band: quadratic coupling
    let useful = 10.0 + fit_ratio * 30.0;
    if pr > 0.0 && pr < useful {
        score += (useful - pr).powi(2) * 0.05;
    }

    // Reward bins whose residual matches the next item (lookahead coupling)
    if next_item_size > 0 {
        let diff = (pr - next_item_size as f64).abs();
        score -= (1.0 - diff / cap).max(0.0) * 8.0;
    }

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize so we only open when open bins fit poorly
    if bin_residual == bin_capacity {
        score += 30.0 + mean_residual * 0.1 + open_bins_count as f64 * 0.5;
    } else {
        // Slight preference for bins below mean residual (consolidate fullness)
        score += (bin_residual as f64 - mean_residual) * 0.05;
    }

    // Smooth stream-progress scaling of dead-space penalty
    score += pr.powi(2) / (cap * cap) * 20.0 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: exact-fit class heavily rewarded.
    let pr = post_residual;
    if pr == 0 {
        score -= 1000.0; // perfect fit
    } else if pr <= 5 {
        score -= 200.0;
    } else if pr <= 10 {
        score -= 60.0;
    } else if pr <= 20 {
        score -= 15.0;
    }

    // Dead-space class: residuals that few item sizes can fill (sizes 1..100).
    // A residual r is "usable" if next item or typical sizes land in it.
    let usable = |r: u32, n: u32| n > 0 && n <= r;
    if pr > 0 && next_item_size > 0 {
        if usable(pr, next_item_size) {
            score -= 120.0; // next item slots perfectly into this bin
        } else if next_item_size > pr {
            // next item too big for this residual: penalize small wasted residuals
            score += (next_item_size - pr) as f64 * 0.8;
        }
    }

    // Modulo-based harmonic classes on residual (quantized dead space)
    let q = pr / 10;
    score += match q {
        0 => -30.0,
        1 => -10.0,
        2 => 0.0,
        3 => 5.0,
        4 => 10.0,
        _ => 15.0,
    };

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 400.0;
        // but if no open bin fits well, new bin becomes attractive
        if fitting_bins_count == 0 {
            score -= 800.0;
        }
        // early stream: allow more bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 50.0;
    }

    // Prefer bins with residual close to item size (tight fit) among open bins.
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * 40.0;

    // Coupling with mean residual: placing into a bin far below mean residual
    // balances the fleet.
    score += (mean_residual - post_residual as f64).abs() * 0.3;

    // Many open bins: discourage spreading, favor filling existing bins.
    score += open_bins_count as f64 * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 18.0;
    }

    // Perfect fits are heavily rewarded.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Penalize opening a new bin when open bins exist and fit.
    if bin_residual == bin_capacity {
        score += 25.0 + 3.0 * (open_bins_count as f64).sqrt();
        // But if the next item is large and this bin would be nearly wasted anyway,
        // opening fresh is less bad.
        if next_item_size as f64 > post_residual as f64 + 40.0 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins (small residual relative to mean residual).
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead: if next item fits exactly in the post residual, reward this placement.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 30.0;
    } else if next_item_size > 0 && next_item_size > post_residual {
        score += 8.0; // next item won't fit here; dead space likely
    }

    // Mild pressure against accumulating many open bins.
    score += 0.5 * open_bins_count as f64;

    // Early in stream, be slightly more willing to open bins (build diversity).
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity {
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
