pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual)
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * fit_ratio * fit_ratio;

    // Penalize leaving residuals that are awkward: too small for typical items but wasted
    if post_residual > 0 && post_residual < 10 {
        score -= 6.0; // near-perfect fill bonus
    }
    if post_residual >= 10 && post_residual <= 20 {
        score += 3.0; // dead zone: residual that few items can use
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: only attractive when existing bins fit poorly
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        // base penalty for opening a bin, reduced when many bins already open or late in stream
        let mut new_penalty = 10.0 + 0.15 * open_bins_count as f64;
        if progress > 0.7 {
            new_penalty -= 4.0; // late stream: consolidation matters more
        }
        // if the next item is large, a fresh bin is more valuable
        if next_item_size >= 60 {
            new_penalty -= 5.0;
        }
        // if the best alternative leaves big dead space, new bin less penalized
        if post_residual as f64 > mean_residual {
            new_penalty -= 2.0;
        }
        score += new_penalty;
    } else {
        // Reward bins whose residual matches item well relative to mean state
        let dev = bin_residual as f64 - mean_residual;
        score += 0.05 * dev;
    }

    // Lookahead coupling: prefer bins that still accommodate the next item after this placement
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 4.0;
    }
    // Penalize placements that leave residual just barely below next item (wasted)
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size && post_residual + 10 >= next_item_size {
        score += 2.5;
    }

    // Mild time-horizon scaling: early on, be conservative about fragmentation
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score *= 1.0 + 0.3 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let prn = pr / cap;
    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = prn * prn * (1.0 - prn) * (1.0 - prn);
    score -= 12.0 * poly * (0.5 + progress);
    // Tight fits rewarded more as stream advances
    score -= 8.0 * (1.0 - prn) * (1.0 - prn) * prn * (0.3 + 0.7 * progress);
    // Penalize dead space far from mean residual (wasted potential)
    let dev = (pr - mean_residual) / cap;
    score += 3.0 * dev * dev;
    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 10.0 * (1.0 - prn);
    }
    // Lookahead: reward if next item fits the post residual
    if next_item_size > 0 {
        let fits_next = if (pr as u32) >= next_item_size { 1.0 } else { 0.0 };
        score -= 6.0 * fits_next * (prn * (1.0 - prn) * 4.0);
    }
    // Mild pressure to consolidate when many bins open
    score += 0.05 * open_bins_count as f64 * prn;
    // New-bin candidate: penalize unless post residual is small relative to item range
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - prn) * (1.0 - prn) * (0.5 + progress);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward small, "usable" residuals.
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Class A: perfect fit -> huge reward
    if post_residual == 0 {
        score -= 1000.0;
    }
    // Class B: residual small enough to be "dead" (< 10) -> mildly good (nothing fits anyway)
    else if post_residual < 10 {
        score -= 200.0;
    }
    // Class C: residual usable by typical items (10..=80)
    else {
        // fraction of capacity remaining
        let frac = pr / cap;
        // Harmonic penalty: residual in awkward middle zone (e.g. 41..59 fits few items)
        if post_residual >= 41 && post_residual <= 59 {
            score += 60.0;
        }
        // Reward residuals that match common size classes (multiples of 10 zones)
        let class = (post_residual / 10) as f64;
        score -= 8.0 * (10.0 - class.min(10.0));
        // mild quadratic waste penalty
        score += 0.05 * frac * frac * 100.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item fits: reward proportional to tightness
            let slack = (post_residual - next_item_size) as f64;
            score -= 150.0 / (1.0 + slack * 0.05);
        } else {
            // next item cannot fit here: penalize leaving large unusable gaps
            if post_residual > 0 && post_residual < next_item_size {
                score += 20.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }
    // Many fitting bins: prefer tighter ones; add mild penalty scaled by choice abundance
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64 - 1.0).ln();
    }

    // New-bin candidate handling: opening a new bin should only win when fit is bad
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 180.0;
        // cheaper to open a bin early in the stream (more future items to fill it)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 120.0 * (1.0 - progress);
        // if item is large relative to capacity, new bin gives good residual structure
        let ifrac = item_size as f64 / cap;
        score -= 80.0 * ifrac;
        // if next item is large, fresh bin likely needed anyway
        if next_item_size >= 60 {
            score -= 40.0;
        }
    }

    // Modulo-harmonic nudge on post_residual: residuals divisible by 10 align with size grid
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 15.0;
    }

    // Spread pressure: many open bins with high mean residual -> favor filling existing bins
    if open_bins_count > 2 && mean_residual > (item_size as f64) {
        score -= 30.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
