            score -= 60.0;
        }
        // Make new bin slightly worse than a decent existing fit.
        score += 8.0;
    }

    // Mild pressure to fill older/bins when many bins are open.
    score += open_bins_count as f64 * 0.05;
    // Slight late-stream tightening: waste less as the stream ends.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if the next item can fit into the post residual, this bin
    // remains useful — reward. If post residual is small but nonzero and
    // smaller than the minimum plausible next item, penalize dead space.
    if next_item_size > 0 {
        if (next_item_size as u32) <= post_residual {
            score -= 8.0;
        } else if post_residual > 0 {
            // dead space unless a future tiny item arrives
            let dead = post_residual as f64;
            score += 0.15 * dead;
            if dead < 10.0 {
                score += 6.0; // tiny unusable sliver
            }
        }
    } else {
        // Last item: just minimize post residual (already default).
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e. when mean residual is low relative to the item or many bins
    // are open with fragmented space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = (mean_residual / cap).clamp(0.0, 1.0);
        // Opening a fresh bin costs a full capacity slot; penalize base,
        // discount when existing bins are fragmented and item is large.
        let mut new_bin_score = cap * 0.75;
        new_bin_score -= 25.0 * (1.0 - fragmentation);
        new_bin_score -= 15.0 * progress * (item_size as f64 / cap);
        if open_bins_count == 0 {
            new_bin_score = -50.0; // must open a bin
        }
        score = new_bin_score;
    } else {
        // Mild preference for bins already below mean residual
        // (consolidate space into emptier bins).
        let res = bin_residual as f64;
        if res > mean_residual {
            score += 0.05 * (res - mean_residual);
        } else {
            score -= 0.05 * (mean_residual - res);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - pr / cap; // 1.0 = perfect fit

    // Core: quadratic reward for tight packing, stronger as stream progresses.
    let mut score = pr * (1.0 + 0.9 * progress) - 6.0 * tightness * tightness;

    // Smooth coupling: prefer bins whose residual is close to the item size (low waste).
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 4.0 * fit_ratio * fit_ratio;

    // Penalize wasting a nearly-full bin when other bins could also fit.
    if fitting_bins_count > 1 {
        score += 1.5 * (fitting_bins_count as f64 - 1.0).ln().max(0.0);
    } else {
        score -= 3.0; // last-chance bin: strong reward to use it
    }

    // Lookahead: bonus if the post residual can host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 2.5 * (next_item_size as f64 / cap);
    }

    // Mild preference to keep mean residual balanced (avoid many near-empty bins).
    score += 0.3 * (mean_residual - pr).abs() / cap;

    // New empty bin candidate: post_residual is large -> naturally high score;
    // add explicit penalty that decays with progress so early stream may open bins.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit is ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose leftover falls into
    // "useful" modulo classes (multiples of common item sizes) are favored.
    let pr = post_residual;
    let useful = |r: u32| -> f64 {
        let mut bonus = 0.0;
        for m in [10u32, 20, 25, 50] {
            if m > 0 && r % m == 0 {
                bonus += 3.0;
            }
        }
        bonus
    };
    score -= useful(pr);

    // Penalize dead space: leftover too small to fit even the smallest item
    if pr > 0 && pr < 10 {
        score += 30.0;
    }

    // If the next item fits exactly in the leftover, reward strongly
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 200.0;
        } else if next_item_size <= pr {
            score -= 10.0;
        } else {
            // leftover unusable by next item: mild penalty scaled by tightness
            score += 5.0 + (pr as f64) * 0.05;
        }
    }

    // Last chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 150.0;
    }

    // Reward filling bins when many bins are open (bin consolidation)
    score -= (bin_residual - post_residual) as f64 * 0.2;

    // New-bin candidate: penalize opening a new bin unless all open bins
    // would leave large unusable residue.
    if bin_residual == bin_capacity {
        score += 250.0 + open_bins_count as f64 * 2.0;
        // Early in the stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 100.0;
    }

    // Mild preference for bins tighter than average
    score -= (mean_residual - bin_residual as f64).max(-50.0) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold
    // even the smallest plausible future item are "dead space".
    let min_useful = 10u32.min(bin_capacity);
    if post_residual > 0 && post_residual < min_useful {
        score += 60.0 + (min_useful - post_residual) as f64 * 4.0;
    }

    // Small-but-marginal gaps: penalize residuals below ~20 harshly
    // (unlikely to fit future items of unknown distribution cleanly).
    if post_residual >= min_useful && post_residual < 20 {
        score += 25.0 - (post_residual - min_useful) as f64;
    }

    // Reward when the lookahead item fits exactly into the post residual.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + (post_residual - next_item_size) as f64 * 0.5;
    }
    // Penalize when lookahead item almost fits but not quite (wasted potential).
    if next_item_size > post_residual && post_residual > 0 && next_item_size > 0
        && next_item_size - post_residual <= 10 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins unless the
    // fit is genuinely good.
    score += open_bins_count as f64 * 0.8;

    // Last chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: only attractive when current bin fit is bad
    // (large post residual relative to capacity or dead space).
    if bin_residual == bin_capacity {
        // Baseline for a fresh bin: its residual is maximal, so start neutral
        // and adjust based on how wasteful the best alternative would be.
        score = (bin_capacity - item_size) as f64;
        if next_item_size > 0 && (bin_capacity - item_size) >= next_item_size {
            score -= 10.0;
        }
        // If an existing bin would leave a near-perfect fit, prefer it.
        if post_residual < 5 && bin_residual != bin_capacity {
            score += 50.0;
        }
    }

    // Mild preference for tighter fits overall relative to mean residual.
    score -= (mean_residual - post_residual as f64) * 0.3;

    // Slight late-stream conservatism: consolidate as stream progresses.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: reward when post_residual matches next item size exactly
    if next_item_size > 0 {
        let lookahead_diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 2.5 * (100.0 - lookahead_diff.min(100.0)) / 100.0;

        // If next item fits exactly into post_residual, big reward
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // If next item cannot fit in post_residual, penalize wasted small residual
        if post_residual > 0 && post_residual < next_item_size {
            score += 3.0;
        }
    }

    // Penalize tiny dead space that nothing (min size 1) could use — relative to capacity
    if post_residual > 0 && post_residual < 10 {
        score += 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is very poor
    if bin_residual == bin_capacity {
        score += 30.0;
        // Less penalty late in the stream
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score -= 10.0 * progress;
        }
        // If next item is large, a fresh bin is more attractive
        if next_item_size > 60 {
            score -= 10.0;
        }
    }

    // Prefer bins with residual below mean residual (tighter packing)
    score -= 0.5 * (mean_residual - bin_residual as f64);

    // Prefer bins that leave post_residual close to mean residual of remaining space
    let post_mean_gap = (mean_residual - item_size as f64 - post_residual as f64).abs();
    score += 0.2 * post_mean_gap;

    // Mild pressure to consolidate when many bins are open
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly penalize opening a new bin unless the fit is bad elsewhere.
    if bin_residual == bin_capacity {
        let new_bin_cost = bin_capacity as f64 * 0.9 + post_residual as f64 * 0.8;
        // If this is the only fitting option, opening a new bin is forced/acceptable.
        if fitting_bins_count <= 1 {
            score = post_residual as f64 * 0.5 + new_bin_cost * 0.2;
        } else {
            score = post_residual as f64 + new_bin_cost;
        }
        return score;
    }

    // Reward tight fits: quadratic penalty on wasted space relative to capacity.
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += waste_frac * waste_frac * 40.0;

    // Lookahead: if the next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // Next item cannot use this residual: penalize leaving medium dead space.
            if post_residual < 10 {
                score -= 5.0; // small residual is fine (near-full bin)
            } else {
                score += (post_residual as f64) * 0.15;
            }
        }
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Time horizon: early in stream, be conservative (keep bins open for future);
    // late in stream, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 8.0;

    // Global state coupling: many open bins with high mean residual -> favor
    // filling this bin to reduce fragmentation.
    if open_bins_count > 1 {
        let frag = (mean_residual - post_residual as f64).abs();
        score += frag * 0.05;
        score -= (open_bins_count as f64).ln() * 2.0;
    }

    // Prefer bins whose residual was already small (tight packing pressure).
    score += (bin_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_ratio = item_size as f64 / cap;
    let pr_norm = pr / cap;

    // Smooth non-linear coupling of post_residual with stream progress
    let progress_term = progress * (1.0 - progress) * 4.0; // peaks mid-stream
    let mut score = pr;

    // Reward tight fits more strongly as stream progresses (smooth polynomial coupling)
    let tightness = (1.0 - pr_norm).powi(3);
    score -= tightness * (20.0 + 60.0 * progress) * progress_term.max(0.25);

    // Penalize residual that no plausible future item can use
    let next_fit_bonus = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -1.0
    } else {
        1.0
    };
    score += next_fit_bonus * pr_norm * 30.0 * (0.5 + progress);

    // Dead-space penalty: quadratic in normalized residual, weighted by item size
    score += pr_norm * pr_norm * 40.0 * fit_ratio;

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0 * (1.0 + progress);
    }

    // New-bin candidate: mild penalty so we prefer reusing open bins unless fit is bad
    if bin_residual == bin_capacity {
        score += 15.0 + 25.0 * progress;
        // Allow opening a new bin if the item is large and fits would be very loose
        score -= 40.0 * fit_ratio * fit_ratio;
    }

    // Slight preference for bins below mean residual (balance load smoothly)
    score += (mean_residual - pr) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residual divisible by common sizes
    // (10, 20, 25, 50) is more reusable than arbitrary dead space.
    let pr = post_residual;
    if pr == 0 {
        score -= 100.0; // perfect fit
    } else {
        let mut bonus = 0.0;
        if pr % 50 == 0 { bonus += 18.0; }
        else if pr % 25 == 0 { bonus += 12.0; }
        else if pr % 20 == 0 { bonus += 10.0; }
        else if pr % 10 == 0 { bonus += 8.0; }
        else { bonus -= 6.0; } // awkward dead space penalty
        score -= bonus;

        // Fractional capacity classes: small post_residual relative to capacity
        let frac = pr as f64 / bin_capacity as f64;
        if frac < 0.05 { score -= 20.0; }      // nearly full, good
        else if frac < 0.10 { score -= 10.0; }
        else if frac < 0.30 { score += 4.0; }  // medium waste
        // large residual is naturally attractive via base score

        // Integer-division threshold: can next item also fit here?
        if next_item_size > 0 && next_item_size <= pr {
            score -= 14.0;
            // harmonic pairing: next item exactly consumes residual
            if pr == next_item_size { score -= 25.0; }
            else if pr % next_item_size == 0 { score -= 10.0; }
        } else if next_item_size > pr && pr > 0 {
            score += 6.0; // next item won't fit here; residual likely stranded
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize opening new bins when many open bins have ample room
    if bin_residual == bin_capacity {
        score += 15.0 + 2.0 * open_bins_count as f64;
        if next_item_size > 0 && next_item_size > item_size {
            score += 5.0; // new bin better if next item is large? keep slight penalty anyway
        }
    }

    // Prefer tighter bins as stream progresses (less re-shuffling late)
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * (mean_residual - post_residual as f64) * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps harshly.
    let dead_zone = 12.0;
    if post_residual > 0 && post_residual < 12 {
        score += (12.0 - post_residual as f64) * 6.0;
    }

    // Reward tight fits.
    score -= (item_size as f64 / bin_capacity as f64) * 10.0;

    // Last-chance bin bonus: if this is the only bin that fits, strongly favor it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are open.
        score += open_bins_count as f64 * (2.0 + 4.0 * progress);
        // But if post_residual of best fit would be tiny, allow new bin sometimes:
        // (handled implicitly via dead-space penalty on other candidates)
    } else {
        // Mild reward for using existing bins.
        score -= 1.5;
    }

    // Lookahead: if next item fits the post-residual, reward this placement.
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 8.0;
    }
    // If next item cannot fit post-residual and post-residual is small, penalize.
    if next_item_size > 0 && post_residual > 0 && (post_residual as f64) < next_item_size as f64 && post_residual < 25 {
        score += 5.0;
    }

    // Coupling with mean residual: prefer bins below mean residual (tighter bins).
    score -= (mean_residual - post_residual as f64) * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward exact/near matching of post_residual with next item.
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        if post_residual as i64 >= next_item_size as i64 {
            // Next item can also fit here after this placement.
            score -= 25.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // Post residual is dead space relative to next item.
            score += 8.0 * (gap / bin_capacity as f64);
        }
    }

    // Relative to mean residual: prefer bins that leave less slack than average.
    score -= 5.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening new bins when a decent fit exists.
    if bin_residual == bin_capacity {
        score += 45.0;
        if next_item_size > 0 && item_size < 40 {
            score += 10.0;
        }
    }

    // Early in stream: encourage consolidation to build tight bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * (1.0 - progress) * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly reward tight fits (small post_residual).
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 45.0 * tightness * tightness;

    // Penalize leaving dead space that the next item cannot use.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let pr = post_residual as f64;
        if pr > 0.0 && pr < nxt {
            score += 25.0 * (1.0 - pr / nxt.max(1.0));
        } else if pr >= nxt {
            // Reward leaving space exactly usable by the lookahead item.
            score -= 12.0 * (1.0 - ((pr - nxt) / cap).abs());
        }
    }

    // Last-chance bin: heavy bonus to avoid opening a needless new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless item is huge relative to capacity
    // or existing residuals are all poor fits.
    if bin_residual == bin_capacity {
        let load_ratio = item_size as f64 / cap;
        let mut base = 55.0 - 40.0 * load_ratio;
        if fitting_bins_count > 0 {
            base += 20.0 * (fitting_bins_count as f64).ln().max(0.0);
        }
        // Late in the stream, prefer consolidating into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        base += 30.0 * progress;
        score += base;
    }

    // Prefer bins whose residual is close to the mean (balanced packing),
    // but only when there are several open bins.
    if open_bins_count > 1 && bin_residual != bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.35 * dev;
    }

    // Mild bonus for filling bins that are already quite full.
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 8.0 * fill * fill * fill;

    // Discourage many simultaneous open bins early on.
    score += 0.6 * open_bins_count as f64 * (1.0 - (item_size as f64 / cap));

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalize quantities
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_n = pr / cap;                       // normalized post residual in [0,1)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial penalty on dead space: convex quadratic in normalized residual,
    // growing stronger as the stream progresses (coupling with progress).
    let dead_space_penalty = pr_n * pr_n * (1.0 + 3.0 * progress) * cap;
    score += dead_space_penalty;

    // Smooth interaction: reward tight fits (small post_residual relative to item size)
    let item_f = item_size as f64;
    let tightness = item_f / (bin_residual as f64 + 1.0); // in (0,1]
    score -= 8.0 * tightness * tightness * cap;

    // Lookahead coupling: smooth polynomial interaction between post_residual and next item.
    if next_item_size > 0 {
        let next_f = next_item_size as f64;
        // If next item fits into post residual, reward this bin (smooth bump).
        let gap = next_f - pr;
        let fit_next = (-gap * gap / 200.0).exp(); // ~1 when next item exactly fills residual
        score -= 6.0 * fit_next * (1.0 + progress);

        // Penalize large residuals that waste space relative to the upcoming item
        let waste = pr - next_f;
        if waste > 0.0 {
            let w_n = waste / cap;
            score += 10.0 * w_n * w_n * cap * (0.5 + progress);
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 25.0 * (1.0 + progress);
    } else if fitting_bins_count > 1 {
        // Mild competition bonus proportional to scarcity
        score -= 2.0 / fitting_bins_count as f64;
    }

    // New-bin candidate handling: an empty bin has bin_residual == bin_capacity.
    // Its post_residual is large, but we must control when opening a new bin is preferred.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Base cost of opening a new bin: increases with number of open bins,
        // decays as stream progresses (toward the end, consolidating matters more).
        score = cap * (1.0 + 0.05 * open_bins_count as f64) * (1.2 - 0.5 * progress);

        // Opening a new bin is attractive only if no open bin fits well:
        // compare post_residual achievable elsewhere implicitly through item tightness.
        // If the item is large relative to capacity, a fresh bin is natural.
        score -= 4.0 * (item_f / cap) * cap * (0.5 + 0.5 * progress);

        // If other bins fit and their residuals are small on average, penalize new bin.
        let mean_res_n = mean_residual / cap;
        score += 6.0 * (1.0 - mean_res_n) * (1.0 - mean_res_n) * (1.0 - progress);
    } else {
        // Existing-bin alignment with mean residual: prefer bins with residual below mean
        // (filling fuller bins first keeps many partially-filled bins flexible).
        let res_n = bin_residual as f64 / cap;
        let mean_n = mean_residual / cap;
        let d = res_n - mean_n;
        score += 3.0 * d * d * (1.0 + progress);
        score -= 1.5 * d; // slight preference for fuller bins
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover: residues modulo common item-size classes.
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;

    // Perfect fit is best possible.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Lookahead harmony: does the next item fit exactly / well in the post residual?
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 40.0 + nxt * 0.5;
        if post_residual == next_item_size {
            score -= 200.0; // exact pairing
        }
        // Harmonic alignment: post_residual divisible by next item size
        if post_residual % next_item_size == 0 {
            score -= 60.0;
        }
    } else if next_item_size > 0 {
        // Next item cannot use this leftover: penalize proportionally.
        score += 0.3 * (nxt - post).min(80.0);
    }

    // Modulo-10 harmonic classes: leftovers that are multiples of 10 are reusable
    // by a wide class of items (sizes 10..80 in tens).
    if post_residual % 10 == 0 && post_residual > 0 {
        score -= 25.0;
    }
    // Small dead-space classes (< 10) are nearly unusable.
    if post_residual < 10 && post_residual > 0 {
        score += 15.0;
    }

    // Fraction-of-capacity classes: prefer residuals in the "medium" band
    // (roughly 30..70) which remain packable; penalize extremes.
    let frac = post / cap;
    if frac > 0.7 {
        score += 10.0 * (frac - 0.7);
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: only attractive when no open bin fits or mean residual is huge.
    if bin_residual == bin_capacity {
        score += 500.0;
        if fitting_bins_count == 0 {
            score -= 600.0;
        } else {
            score += mean_residual * 0.5;
        }
        // Late in the stream, avoid proliferating bins.
        score += 30.0 * (step_index as f64 / total_items.max(1) as f64);
    }

    // Mild pressure to prefer bins below mean residual (tighter packing).
    if bin_residual != bin_capacity {
        score += 0.2 * (mean_residual - bin_residual as f64).max(-50.0);
    }

    // Many open bins: discourage spreading, reward filling existing ones.
    score += 0.05 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible item are wasted; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0 + (10 - post_residual) as f64 * 6.0;
    }

    // "Awkward gap" zone: residual just above the minimum item size is
    // risky; mildly penalize to prefer bins leaving larger, reusable space.
    if post_residual >= 10 && post_residual < 20 {
        score += 12.0;
    }

    // Reward leaving space that exactly accommodates the lookahead item
    // (k=2 lookahead chaining).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }
    if next_item_size > 0 && post_residual > next_item_size && post_residual < next_item_size + 10 {
        score += 8.0; // near-miss for lookahead: mildly bad
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 80.0;
    }

    // Open-bins pressure: with many open bins, favor consolidation into
    // existing bins over opening new ones.
    let pressure = open_bins_count as f64 * 2.5;
    if bin_residual == bin_capacity {
        // Candidate for a brand-new bin: penalize increasingly as open
        // bins grow, so new bins only win when fits are terrible.
        score += 40.0 + pressure;
    } else {
        score -= pressure.min(30.0);
    }

    // Progress-based tightening: later in the stream, waste matters more.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * 0.5 * progress;

    // Prefer bins whose residual deviates favorably from the mean
    // (tighter-than-average bins are closer to closure).
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res).min(25.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let score = post_residual as f64 / bin_capacity.max(1) as f64;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little waste.
    let frac_used = item_size as f64 / bin_capacity as f64;
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness * frac_used;

    // Penalize creating small unusable dead space (residual below typical min item).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead coupling: if the next item fits the post residual, reward heavily.
    if next_item_size > 0 && next_item_size <= post_residual {
        let combo_waste = (post_residual - next_item_size) as f64;
        score -= 14.0 - 0.12 * combo_waste;
    } else if next_item_size > post_residual {
        // Next item won't chain here: mild penalty proportional to leftover.
        score += 0.10 * post_residual as f64;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when the
    // item is large relative to capacity or open bins are badly fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let fragmentation = if open_bins_count > 0 {
            (mean_residual / bin_capacity as f64).min(1.0)
        } else {
            1.0
        };
        // Penalize new bins generally; relax the penalty when fragmentation is
        // high (open residuals large but unusable) or item is big.
        let mut new_bin_penalty = 30.0;
        new_bin_penalty -= 15.0 * (1.0 - fragmentation);
        new_bin_penalty -= 10.0 * frac_used;
        new_bin_penalty -= 8.0 * progress;
        score += new_bin_penalty.max(2.0);
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64 * (1.0 - frac_used);

    // Time horizon: early in the stream, keep bins tidy for the future;
    // late in the stream, prioritize immediate tight packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 6.0 * progress * tightness;
    score += 4.0 * (1.0 - progress) * (post_residual as f64 / bin_capacity as f64);

    // Deviation from mean residual: prefer bins whose residual is close to the
    // item size (natural fit) — penalize overshooting far beyond need.
    let residual_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.06 * residual_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Reward tight fits: strongly discount small post_residual (quadratic coupling).
    let tight = 1.0 - (post / cap);
    score -= 40.0 * tight * tight;

    // Penalize dead space that no plausible next item can use.
    if next_item_size > 0 && (next_item_size as f64) > post {
        let unusable = (next_item_size as f64 - post) / cap;
        score += 25.0 * unusable * (1.0 + progress);
    } else if next_item_size > 0 {
        // Reward bins whose residual exactly hosts the lookahead item.
        let match_deg = 1.0 - ((post - next_item_size as f64).abs() / cap);
        score -= 15.0 * match_deg * match_deg;
    }

    // Last-chance bin: strongly favor using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0 * (1.0 - post / cap);
    }

    // New-bin candidate: penalize opening bins, more so early and when fits exist.
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64).ln().max(0.0);
        score += 10.0 + 8.0 * open_pressure * (1.0 - progress) + if fitting_bins_count > 0 { 20.0 } else { 0.0 };
    }

    // Mild dispersion penalty: prefer bins deviating from mean residual (consolidation).
    let dev = (post - mean_residual).abs() / cap;
    score += 5.0 * dev * (1.0 - progress);

    // Smooth progress coupling: later in stream, squeeze harder.
    score -= 10.0 * progress * tight;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: classify dead space by residue mod 10
    let pr = post_residual;
    let class = pr % 10;
    // Residues that pair well with common small items (10..=20) are less "dead"
    let usable = match class {
        0 => 0.0,          // perfectly divisible residual
        1..=3 => 2.0,
        4..=7 => 6.0,
        _ => 10.0,
    };
    score += usable;

    // Reward tight fits: post_residual in the lowest harmonic band
    if pr <= 5 {
        score -= 25.0;
    } else if pr <= 10 {
        score -= 12.0;
    }

    // Integer-division threshold: does next item fit into post_residual?
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Next item chains nicely: reward proportional to how snugly it fits
            let snug = (pr - next_item_size) as f64;
            score -= 8.0 + 10.0 * (1.0 - snug / bin_capacity as f64);
            // Harmonic bonus if next item exactly consumes a residual class
            if (pr - next_item_size) % 10 == 0 {
                score -= 6.0;
            }
        } else {
            // Next item won't chain: penalize proportional to overshoot class
            let gap = next_item_size - pr;
            score += 4.0 + (gap % 10) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral baseline slightly above average good fits,
    // but attractive when all open bins would leave large dead space
    if bin_residual == bin_capacity {
        let avg_dead = mean_residual;
        score = bin_capacity as f64 * 0.55 + avg_dead * 0.5;
        if fitting_bins_count == 0 {
            score -= 40.0;
        }
    }

    // Progress-aware pressure: later in stream, prefer consolidation into open bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 5.0;
    if bin_residual == bin_capacity {
        score += progress * 10.0;
    }

    // Penalize bins whose residual is far from the mean (fragmentation)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.15;

    // Modulo coupling between item size and residual: aligned classes pack better
    if (bin_residual % item_size.max(1)) == 0 && item_size > 0 {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..10) are pure waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Near-perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Prefer tighter fits generally (relative fill ratio).
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 25.0 * fill;

    // Pressure from number of open bins: discourage spreading across many bins,
    // but allow opening a new bin when the new-bin candidate is truly better.
    score += 2.0 * open_bins_count as f64;

    // If this bin is the last chance to fit, strongly favor using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 35.0;
    }

    // Lookahead coupling: if the next item could use the post_residual, reward leaving that gap.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Gap left is useless for the next item: mild penalty.
        score += 8.0;
    }

    // New-bin candidate: make it attractive only when the item fits badly everywhere.
    // Baseline new-bin score ~ post_residual == capacity; add mild cost so it loses
    // against decent fits but wins over heavily penalized dead-space placements.
    if bin_residual == bin_capacity {
        score += 20.0 + 0.5 * mean_residual.min(50.0);
    }

    // Slight early-stream conservatism: keep bins more packable while stream is young.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * (1.0 - progress) * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item size -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Near-match: next item fits with small slack -> moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size && post_residual - next_item_size <= 10 {
        score -= 25.0 - 2.0 * (post_residual - next_item_size) as f64;
    }
    // Next item cannot fit here: penalize proportionally (dead space until later).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 0.35 * (next_item_size - post_residual) as f64;
    }

    // Penalize tiny unusable dead space (below minimum plausible item size).
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    }
    // Reward tight fits overall.
    let fill = (item_size as f64) / (bin_capacity as f64);
    score -= 30.0 * fill * fill;

    // Deviation from mean residual: prefer bins with residual close to mean (balance),
    // but prefer below-mean residual (packing tighter bins first).
    let dev = post_residual as f64 - mean_residual;
    score += 0.25 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive if no open bin fits well
    // (i.e., many fitting bins means we should reuse one, so penalize new bin).
    if bin_residual == bin_capacity {
        if fitting_bins_count > 0 {
            score += 15.0 + 5.0 * fitting_bins_count as f64;
        } else {
            score += 5.0;
        }
        // Late in the stream, slightly discourage hoarding new bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward near-perfect fits (small post_residual).
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else {
        // Penalize large dead space nonlinearly.
        let waste = post_residual as f64 / bin_capacity as f64;
        score += 40.0 * waste * waste;
    }

    // Favor bins whose residual tightly matches the item (good tightness ratio).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * tightness;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits in the post residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 {
        // Penalize if next item almost fits (wasted opportunity).
        let gap = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        score += 0.1 * gap;
    }

    // Global state coupling: if mean residual is high and this bin is above mean,
    // prefer packing into fuller bins (keep roomy bins for big future items).
    if (bin_residual as f64) > mean_residual {
        score += 0.3 * (bin_residual as f64 - mean_residual);
    } else {
        score -= 0.2 * (mean_residual - bin_residual as f64);
    }

    // Time horizon: early in the stream, be more conservative about fragmenting bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 5.0 * progress;

    // Many open bins: prefer consolidating into existing bins over spreading.
    score += 0.5 * open_bins_count as f64;

    // New-bin candidate penalty: only open a new bin when nothing fits well.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 0.0 } else { 30.0 };
        score += desperation + 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Smooth non-linear coupling: large post_residual is increasingly penalized
    // as the stream progresses (waste matters more later).
    let waste_pressure = norm_pr * norm_pr * (1.0 + 2.0 * progress);
    score += 6.0 * waste_pressure;

    // Smooth interaction between post_residual and mean residual across open bins:
    // penalize bins whose leftover will deviate strongly from the fleet mean
    // (keeps residual distribution tight and usable).
    let dev = (pr - mean_residual) / cap;
    score += 4.0 * dev * dev * (0.5 + progress);

    // Lookahead coupling: if the next item fits exactly in the post_residual,
    // reward this bin smoothly (perfect chain).
    if next_item_size > 0 {
        let gap = (pr - next_item_size as f64).abs() / cap;
        let chain_bonus = (-8.0 * gap).exp();
        score -= 8.0 * chain_bonus * (1.0 - 0.5 * progress);
    }

    // Last-chance bonus: if this is the only bin that fits, strongly favor using it
    // to avoid opening a new bin — unless the fit is terrible (large leftover),
    // via a smooth multiplicative gate on normalized post_residual.
    if fitting_bins_count == 1 {
        let gate = (-3.0 * norm_pr).exp();
        score -= 15.0 * gate;
    }

    // New-bin candidate (bin_residual == bin_capacity): naturally high post_residual,
    // add a mild smooth penalty so it only wins when fits elsewhere are truly bad.
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - progress);
    }

    // Mild reward for tightening full bins early.
    score -= 2.0 * (1.0 - norm_pr) * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual), with a non-linear sharpening
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap;
    score += 12.0 * frac * frac * cap * 0.1; // quadratic dead-space penalty

    // Harmonic class logic: classify post_residual by modulo classes of common item sizes
    // post_residual that lies in a "usable" harmonic class (divisible by small sizes 10/20/25/50)
    // is more likely to be filled later -> reward it.
    let mut harmonic_bonus = 0.0;
    if post_residual > 0 {
        if post_residual % 10 == 0 { harmonic_bonus += 2.0; }
        if post_residual % 20 == 0 { harmonic_bonus += 1.5; }
        if post_residual % 25 == 0 { harmonic_bonus += 1.5; }
        if post_residual % 50 == 0 { harmonic_bonus += 2.5; }
        // integer-division threshold: residual >= 25 is "reusable", < 25 is near-dead
        if post_residual >= 25 { harmonic_bonus += 1.0; } else { harmonic_bonus -= 3.0; }
    } else {
        harmonic_bonus += 8.0; // perfect fit
    }
    score -= harmonic_bonus;

    // Lookahead: does next_item_size fit exactly / well into post_residual?
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            let nxt_post = post_residual - next_item_size;
            // reward chains where the lookahead also leaves a small or harmonic remainder
            let chain = if nxt_post == 0 { 10.0 }
                        else if nxt_post % 10 == 0 { 5.0 }
                        else if nxt_post < 10 { 1.0 }
                        else { 0.0 };
            score -= chain;
        } else {
            // next item won't fit here: mild penalty scaled by how much it overshoots
            let over = (next_item_size - post_residual) as f64;
            score += 0.05 * over;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }
    // Many fitting bins: prefer the tightest one (already via post_residual), but
    // discourage spreading across too many open bins when mean residual is high
    if open_bins_count > 0 {
        let spread = (mean_residual - pr).abs();
        score += 0.02 * spread;
    }

    // New-bin candidate handling: an empty bin has large post_residual (= capacity - item),
    // which is naturally penalized by the base term; add extra penalty so new bins are
    // only opened when no open bin gives a decent fit.
    if bin_residual == bin_capacity {
        // escalate penalty late in the stream when many bins are already open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 10.0 + 15.0 * progress + 0.5 * open_bins_count as f64;
        // but allow a new bin if the item is huge and would leave a harmonic residual
        let pr_after = bin_capacity - item_size;
        if item_size > 70 && pr_after % 10 == 0 {
            score -= 12.0;
        }
    }

    // Mild stream-phase modulation: early on, be slightly more willing to open bins
    // (keeps options open); late, consolidate tightly.
    if total_items > 0 {
        let t = step_index as f64 / total_items as f64;
        score += 2.0 * (0.5 - t) * frac * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: hard penalty when post_residual falls into
    // an "unusable" gap band (too small for typical future items but not zero).
    if post_residual > 0 && post_residual < 10 {
        score += 100.0; // worst dead space: nothing will ever fit
    } else if post_residual < 20 {
        score += 40.0;
    } else if post_residual < 35 {
        score += 12.0;
    }

    // Reward tight fits: small post_residual relative to item size.
    if item_size > 0 {
        score -= (item_size as f64) / (bin_residual as f64).max(1.0) * 10.0;
    }

    // Perfect-fill bonus.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Open-bin pressure: discourage spreading across many bins when a
    // reasonably tight alternative exists.
    score += (open_bins_count as f64) * 1.5;

    // Prefer bins whose residual is close to the item (best-fit coupling).
    let gap = (bin_residual as f64 - item_size as f64).abs();
    score += gap * 0.3;

    // Lookahead: if next item fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 4.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins are
    // quite full or none fit well.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        score = 60.0 + pressure * 80.0 + (open_bins_count as f64) * 2.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += 5.0;
        }
    }

    // Stream progression: as stream nears end, prioritize closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near match of post_residual with next item.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        if post_residual as f64 >= next {
            let gap = post_residual as f64 - next;
            score -= (1.0 - gap / bin_capacity as f64) * 30.0;
        } else {
            // next item cannot follow here; penalize proportionally to leftover dead space
            score += (next - post_residual as f64) * 0.5;
        }
    }

    // Reward tight fits relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= tightness * 20.0;

    // Penalize residual far from mean residual (avoid fragmenting outliers).
    score += (post_residual as f64 - mean_residual).abs() * 0.3;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it unattractive unless the fit is terrible everywhere.
    if bin_residual == bin_capacity {
        score += 60.0;
    }

    // Early in the stream, be slightly more open to new bins for flexibility.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= (1.0 - progress) * 20.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base preference: tight fits. Reward small post_residual nonlinearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 30.0 * tightness * tightness;

    // Penalize leaving residuals that are too small to ever be useful
    // (dead space). Residuals below the minimum plausible item size are wasted.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }
    // "Awkward zone" residuals that few items can use.
    if post_residual >= 10 && post_residual < 25 {
        score += 8.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly reward; if next item cannot fit, mildly penalize.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.1 * (post_residual as f64);
    }

    // Global state: many open bins with high mean residual -> prefer consolidating
    // into existing bins rather than opening new ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if open_bins_count > 3 {
        score -= 4.0 * (open_bins_count as f64).ln();
    }
    // If this bin's residual is above the mean residual, it is roomier than
    // average: slightly penalize using it for small items, reward for large.
    let residual_gap = bin_residual as f64 - mean_residual;
    score += 0.05 * residual_gap * (1.0 - item_size as f64 / bin_capacity as f64);

    // New-bin candidate handling: empty bin. Only attractive when no existing
    // bin fits well (score of empty bin should sit between good and bad fits).
    if bin_residual == bin_capacity {
        // Neutral-ish baseline: worse than a tight fit, better than a bad one.
        score = bin_capacity as f64 * 0.55;
        // Late in the stream with many bins open, discourage proliferation.
        score += 10.0 * progress;
        if open_bins_count > 6 {
            score += 2.0 * (open_bins_count as f64 - 6.0) as f64;
        }
        // If the item is large relative to capacity, a fresh bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 12.0;
        }
    }

    // Small time-horizon modulation: early on, be slightly exploratory
    // (prefer tight fits even more), late in stream, be conservative.
    score -= 5.0 * (1.0 - progress) * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;
    let pr = post_residual as f64 / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    // smooth polynomial coupling: waste grows super-linearly in residual, modulated by progress
    score += 8.0 * pr * pr * (1.0 + 2.0 * progress);
    // reward tight fits
    score -= 12.0 * (item_size as f64 / cap) * (1.0 - pr);
    // lookahead: residual that fits next item is valuable
    if next_item_size > 0 {
        let ni = next_item_size as f64;
        let fits_next = (post_residual as u32 >= next_item_size) as f64;
        score -= 6.0 * fits_next * (ni / cap);
        score += 4.0 * pr * (ni / cap);
    }
    // last-chance bin: strongly favor using it
    if fitting_bins_count == 1 {
        score -= 15.0;
    }
    // penalize opening new bins when many bins are open and mean residual is high
    score += 3.0 * (open_bins_count as f64).ln() * (pr - mean_residual / cap).abs();
    // new-bin candidate: only attractive when item is large relative to mean residual
    if bin_residual == bin_capacity {
        score += 10.0 - 20.0 * (item_size as f64 / cap);
    }
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual;

    // Harmonic class of post_residual (decades of capacity): reward near-perfect fills hard
    let cls = pr / 10;
    score += match cls {
        0 => -10.0,               // almost exact fit -> dead space < 10
        1 => -4.0,                // still usable for mid items
        2 => 0.0,
        3 => 2.5,
        4 => 5.0,
        _ => 7.0,                 // large leftover -> wasteful
    };

    // Lookahead coupling (k=2): prefer leaving residual that can host next item
    if next_item_size > 0 {
        if pr >= next_item_size {
            score -= 5.0;
            // bonus if leftover exactly in a harmonic class that fits next item tightly
            if pr - next_item_size < 10 {
                score -= 3.0;
            }
        } else {
            // leftover blocks the next item: penalize proportionally to wasted potential
            score += 6.0 + (next_item_size - pr) as f64 * 0.15;
        }
        // tiny stranded leftover that nothing (10..80) can use
        if pr > 0 && pr < 10 {
            score += 9.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly favor using it
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }
    // Many alternatives: slight penalty for consuming a scarce tight bin
    if fitting_bins_count > 2 && cls == 0 {
        score += 2.0;
    }

    // Progress-aware pressure: late in the stream, consolidate aggressively
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += (1.0 - progress) * 1.5;

    // Spread-awareness: many open bins with high mean residual -> prefer filling existing ones
    if open_bins_count > 3 && mean_residual > 30.0 {
        score -= (mean_residual - 30.0).min(20.0) * 0.1;
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            // forced open: make it the clear winner
            score = 5.0;
        } else {
            // base reluctance to open a new bin
            score = 60.0 + item_size as f64 * 0.35;
            // if next item is large and this item barely fits anywhere, opening fresh may be wise
            if next_item_size > 0 && next_item_size > bin_capacity - next_item_size {
                score -= 10.0;
            }
            // early stream: opening bins is cheaper (builds a pool of residuals)
            if progress < 0.3 && open_bins_count < 4 {
                score -= 15.0;
            }
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for typical future
    // items are "dead space". Penalize sharply when post_residual falls
    // into the unusable gap band (0 < post_residual < next_item_size,
    // or generally below the smallest plausible item size).
    let min_plausible = 1u32;
    let lookahead = if next_item_size > 0 { next_item_size } else { min_plausible };

    if post_residual > 0 && post_residual < lookahead {
        // Dead space: this bin's leftover can never serve the next item.
        score += 25.0 + (lookahead - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // tiny sliver, almost certainly dead
    }

    // Reward perfect / tight fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else {
        let tightness = item_size as f64 / bin_residual as f64;
        score -= 20.0 * tightness * tightness;
    }

    // Last-chance bin: if this is the only bin that fits, heavily favor
    // using it rather than opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // yet another bin; the empty-bin candidate gets a mild penalty that
    // grows with open_bins_count, so consolidation wins unless fit is bad.
    if bin_residual == bin_capacity {
        score += 8.0 + 2.0 * open_bins_count as f64;
        // But if no open bin fits well, opening a new bin is fine:
        // handled implicitly since fitting bins get their own scores.
    }

    // Prefer bins whose residual is below the mean (denser bins first),
    // keeping the packing front compact.
    score += 0.05 * (mean_residual - bin_residual as f64).abs().signum()
        * (mean_residual - bin_residual as f64);

    // Early in the stream, be slightly more willing to open bins
    // (long horizon amortizes); later, consolidate aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        score -= 6.0 * (1.0 - progress);
    } else {
        score += 4.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    // Small deterministic tie-breaker favoring lower residuals.
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward: post_residual exactly matches the next item (perfect 2-step chain).
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }

    // Partial reward: next item could still fit in the leftover space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.25 * (next_item_size as f64);
    } else if next_item_size > 0 {
        // Dead space relative to the lookahead item: penalize proportionally.
        score += 0.5 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward tight fits relative to bin capacity.
    score -= 20.0 * (1.0 - (post_residual as f64) / (bin_capacity as f64));

    // Penalize bins whose residual deviates above the mean (fragmented bins).
    score += 0.3 * ((bin_residual as f64) - mean_residual).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        let tight_fit_exists = next_item_size > 0 && post_residual >= next_item_size;
        if fitting_bins_count > 0 && tight_fit_exists {
            score += 80.0; // keep using open bins when a decent fit exists
        } else {
            score += 5.0; // mild preference to open a new bin on poor fits
        }
    }

    // Late in the stream: prefer consolidating into fewer bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 10.0 * progress * (open_bins_count as f64).recip().min(1.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: strongly favor tight fits (small post_residual), with quadratic waste penalty.
    let waste = post_residual as f64;
    score += 0.35 * waste * waste / bin_capacity as f64;

    // Lookahead: if the next item fits into the post_residual, reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= 8.0 * (1.0 - slack_after_next as f64 / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Next item cannot follow here: slight penalty proportional to leftover dead space.
        score += 3.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual <= 5 {
        score -= 12.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item, strongly prefer it
    // over opening a new bin (unless the fit is terrible).
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0 + 0.2 * item_size as f64;
    }

    // New-bin candidate handling: opening a fresh bin is penalized, but the penalty
    // shrinks when current open bins have large residuals (poor fits available) or
    // many bins are open (consolidation pressure is low).
    if bin_residual == bin_capacity {
        let open_f = open_bins_count as f64;
        let poor_fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let mean_res = mean_residual / bin_capacity as f64;
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let penalty = 40.0
            - 18.0 * poor_fit_pressure
            - 6.0 * mean_res
            - 4.0 * (open_f / (open_f + 5.0))
            - 5.0 * progress;
        score += penalty.max(6.0);
    }

    // Coupling with global mean residual: prefer bins whose residual deviates
    // below the mean (they are "tighter" than average) when the fit is good.
    if bin_residual < bin_capacity {
        let dev = mean_residual - bin_residual as f64;
        score -= 0.15 * dev;
    }

    // Mild time-horizon effect: early in the stream, be more willing to keep bins
    // compact for the future; late, prioritize immediate tightness.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * 2.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Small stochastic-free tie-breaker based on bin index proxy (residual pattern).
    score += 0.01 * ((bin_residual as f64).sin().abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let it = item_size as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_ratio = it / cap;

    // Base: prefer minimal post-residual, non-linearly coupled with progress
    let mut score = pr * (1.0 + 0.6 * progress * fit_ratio);

    // Tightness reward: strongly reward small post_residual relative to item
    let tight = 1.0 - pr / cap;
    score -= 12.0 * tight * tight * fit_ratio;

    // Dead-space penalty: post_residual too small for any plausible item (1..100)
    if pr > 0 && pr < 10 {
        score += 25.0 * (10.0 - pr as f64);
    } else if pr == 0 {
        score -= 15.0; // perfect fit
    }

    // Lookahead: if next item fits in post_residual, bonus; else penalty
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if (pr as u32) >= next_item_size {
            score -= 8.0 * (nxt / cap) * (1.0 - progress);
        } else {
            score += 4.0 * (nxt / cap);
        }
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a new bin unless all open bins fit poorly
    if bin_residual == bin_capacity {
        let waste = if fitting_bins_count == 0 { 0.0 } else { pr };
        let poor_fit_penalty = (pr as f64 - it).abs() / cap; // unused for new bin
        let _ = waste;
        let _ = poor_fit_penalty;
        score += 30.0 + 20.0 * (1.0 - progress);
        // allow new bin when no open bin fits at all
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // early stream: opening bins is fine
        score -= 25.0 * (1.0 - progress);
    }

    // Mild spread regularization vs mean residual
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post.powf(1.25) / 4.0;

    // Tight fit reward: small post_residual relative to capacity.
    if post_residual <= 5 {
        score -= 40.0;
    } else if post_residual <= 10 {
        score -= 25.0;
    } else if post_residual <= 20 {
        score -= 12.0;
    }

    // Harmonic class: item occupies a large fraction of residual -> good.
    let fill_frac = item_size as f64 / bin_residual.max(1) as f64;
    score -= 15.0 * fill_frac;

    // Lookahead: next item fits into the resulting residual.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 10.0;
            // Perfect pairing: post_residual exactly consumed later.
            if post_residual == next_item_size {
                score -= 20.0;
            }
        } else {
            score += 5.0;
        }
    }

    // Last-chance bin: strongly prefer using it to avoid opening a bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Penalize leaving residual in awkward harmonic class (11..=19 dead zone).
    if post_residual >= 11 && post_residual <= 19 {
        score += 8.0;
    }

    // New-bin candidate: only attractive when item is large or stream early.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_score = 55.0 - 0.35 * item_size as f64 + 10.0 * progress;
        score = score.min(new_bin_score);
        score = new_bin_score.max(score);
        score = new_bin_score;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // plausible future item (<= 10) are pure waste.
    if post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 25.0;
    } else if post_residual < 35 {
        score += 8.0;
    }

    // Reward near-perfect fits.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Favor bins whose residual was already small (tight packing pressure).
    let tightness = 1.0 - (bin_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness;

    // Open-bin pressure: with many open bins, discourage spreading; prefer
    // filling existing bins and only open new ones on genuinely bad fits.
    score += 2.0 * (open_bins_count as f64).sqrt();

    // Last-chance bin: strongly prefer using the single fitting bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: only attractive when it enables a good pair with
    // the lookahead item, otherwise penalize.
    if bin_residual == bin_capacity {
        score += 18.0;
        if next_item_size > 0 {
            let pair = item_size + next_item_size;
            if pair >= bin_capacity {
                score -= 45.0; // new bin will be perfectly consumed by the pair
            } else if pair > bin_capacity.saturating_sub(10) {
                score -= 20.0;
            }
        }
    }

    // Lookahead compatibility: reward leaving a gap that fits the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 10.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 6.0; // gap likely wasted w.r.t. lookahead
    }

    // Early in the stream, allow slightly more freedom to open bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 8.0 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Perfect fit: huge reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits here too: strong bonus, scaled by how snugly it fits.
            score -= 10.0 + (next_item_size as f64) * 0.1;
        } else if post_residual > 0 {
            // Dead space: post_residual too small for the next item -> penalize proportionally.
            score += 15.0 + (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Last-chance bin: avoid opening a new bin if this is the only one that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 8.0;
    }

    // Mild preference for packing into tighter bins vs. emptier ones as stream progresses.
    score += (mean_residual - bin_residual as f64) * 0.05 * progress;

    // New-bin candidate (untouched bin): only wins when all open bins score poorly.
    if bin_residual == bin_capacity {
        score = 60.0;
        // Slightly favor a fresh bin if the next item would fit well in it.
        if next_item_size > 0 && next_item_size <= bin_residual {
            score -= 5.0;
        }
        // Late in the stream, be a bit more willing to open new bins (fewer future chances to consolidate).
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) with a non-linear boost.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that no future item can plausibly use.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0; // tiny slivers are usually wasted
    }

    // Lookahead: if the next item fits exactly into the post-residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            let waste = (post_residual - next_item_size) as f64;
            score -= 8.0 * (1.0 - waste / bin_capacity as f64);
        } else {
            // next item cannot follow here: mild penalty scaled by overshoot
            score += 2.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: prefer filling existing bins fully.
        score -= 20.0 * tightness;
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current
    // bins are crowded or the fit is poor.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowded = open_bins_count as f64 / (mean_residual.max(1.0) / bin_capacity as f64).max(1.0);
        let poor_fit = (bin_residual - item_size) as f64 >= 30.0;
        let mut new_bin_penalty = 18.0;
        if fitting_bins_count <= 1 {
            new_bin_penalty -= 20.0; // no real alternative
        }
        if poor_fit && mean_residual < item_size as f64 {
            new_bin_penalty -= 12.0;
        }
        if crowded > 3.0 {
            new_bin_penalty -= 5.0 * progress;
        }
        score += new_bin_penalty.max(-25.0);
    }

    // Global state: prefer bins with residual close to the mean (balanced packing)
    // early on; late in the stream, prefer filling the largest residuals.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += (1.0 - progress) * 0.05 * dev;
    score -= progress * 0.05 * (bin_residual as f64 - mean_residual);

    // Slight preference for bins that keep post_residual in "usable" mid range.
    let usable = ((post_residual as f64) / 10.0).floor().min(9.0);
    score -= 0.3 * usable;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let r = post_residual as f64;
    let c = bin_capacity as f64;
    let rn = r / c;

    let mut score = r;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 12.0 * (rn * rn) * (progress - 0.5) * 2.0;
    score -= 8.0 * (rn * (1.0 - rn)) * (1.0 - progress);

    // Penalize near-fit dead space more as stream progresses
    score += 15.0 * (rn * rn * rn) * (0.5 + progress);

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 20.0 + 30.0 * progress;
    }

    // Prefer bins tighter than the mean residual
    score -= (mean_residual - r) * 0.3;

    // Lookahead: reward residual that can still hold the next item
    if next_item_size > 0 {
        if (r as u32) >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0 * (1.0 - progress);
        }
    }

    // Mild pressure against hoarding many open bins
    score += (open_bins_count as f64) * 0.05 * progress;

    // Favor opening a new empty bin only for very tight fits
    if bin_residual == bin_capacity {
        score += 10.0 * (1.0 - rn) * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual modulo small divisors: residues near
    // common item sizes (10..80) are "usable" dead space; odd/tiny residues are dead.
    let r = post_residual;
    let mod10 = (r % 10) as f64;
    let mod20 = (r % 20) as f64;
    let class = (r / 10) as f64; // integer-division threshold class

    // Penalize unusable slivers: post_residual in 1..10 is dead space.
    if r > 0 && r < 10 {
        score += 25.0;
    }
    // Reward post_residuals that are exact harmonic multiples (perfectly packable).
    if r % 10 == 0 && r > 0 {
        score -= 8.0 + 0.5 * class;
    }
    if r % 20 == 0 && r > 0 {
        score -= 4.0;
    }
    // Penalize odd residues (cannot pair with even item sizes).
    if r % 2 == 1 {
        score += 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 40.0;
        } else if next_item_size < r {
            score -= (r - next_item_size) as f64 * 0.6;
        } else {
            // next item cannot fit here; mild penalty proportional to overshoot class
            score += ((next_item_size - r) % 20) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Late in the stream, prefer tighter fills (waste minimization dominates).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.5 * progress;

    // New-bin candidate: make it attractive only when existing fits are poor
    // (large post_residual waste or dead slivers).
    if bin_residual == bin_capacity {
        let poor_fit_penalty = if r < 10 { 20.0 } else { 0.0 };
        score = bin_capacity as f64 * 0.9 - poor_fit_penalty
            - if next_item_size > 0 && next_item_size <= bin_capacity { 5.0 } else { 0.0 };
    }

    // Mild pressure toward consolidating into few bins.
    score += open_bins_count as f64 * 0.05 - mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: tiny unusable gaps are heavily penalized.
    // A residual below the minimum plausible item size (~1/10 of capacity) is waste.
    let min_item = bin_capacity as f64 / 10.0;
    if (post_residual as f64) < min_item && post_residual > 0 {
        score += (min_item - post_residual as f64) * 6.0;
    }

    // Perfect fit bonus: nothing left over is highly desirable.
    if post_residual == 0 {
        score -= bin_capacity as f64 * 0.5;
    }

    // Reward leaving room for the lookahead item (k=2) if it fits exactly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= next_item_size as f64 * 0.8;
        } else if (post_residual as u64) < next_item_size as u64 && post_residual > 0 {
            // Post-residual too small for next item: dead space relative to lookahead.
            score += (next_item_size as f64 - post_residual as f64) * 2.5;
        }
    }

    // Last-chance pressure: if this is the only fitting bin, prefer using it
    // over opening a new bin (penalize the alternative implicitly).
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 12.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor tight fills.
    let pressure = open_bins_count as f64 / (1.0 + mean_residual.max(1.0) / bin_capacity as f64);
    score += pressure * 1.5;

    // Slight stream-phase term: late in stream, waste matters more (no future to reuse gaps).
    let phase = step_index as f64 / (total_items.max(1) as f64);
    score += phase * (post_residual as f64) * 0.3;

    // New-bin candidate: only attractive when current bin fits are poor
    // (large dead space would be created) or no bins fit.
    if bin_residual == bin_capacity {
        score = bin_capacity as f64 * 0.9 + pressure * 0.5;
        if fitting_bins_count == 0 {
            score -= bin_capacity as f64 * 0.8;
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // fresh bin can host the next item too
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer minimal post_residual (tight fits).
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;

    // Perfect 2-step lookahead match: post_residual exactly equals next item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 60.0;
    }
    // Next item fits into post_residual: strong reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0 + 0.5 * (post_residual - next_item_size) as f64;
    }
    // Dead space: post_residual too small for next item (and too small for min-size item later).
    if next_item_size > 0 && post_residual < next_item_size {
        score += 10.0 + 0.3 * (next_item_size - post_residual) as f64;
    }
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // unusable sliver
    }

    // Relative to mean residual: bins tighter than average are more precious.
    if mean_residual > 0.0 {
        score += 0.4 * (pr - mean_residual);
    }

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bin is a poor fit.
    if bin_residual == bin_capacity {
        // Opening fresh bin is only good if item is huge relative to capacity
        // or no existing bin fits well.
        let waste_if_open = (bin_capacity - item_size) as f64;
        score += 55.0 - 0.3 * waste_if_open;
        if item_size >= 80 {
            score -= 30.0; // big items fine in fresh bins
        }
    }

    // Late in stream: consolidate more aggressively.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 10.0 * progress * (pr / cap);
    }

    // Prefer keeping many open bins from growing further.
    if open_bins_count > 8 {
        score -= 0.5 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post residual) with a non-linear bonus.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(3) * 30.0;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 {
        if post_residual < 10 {
            score += 12.0; // near-zero residual is wasted space
        }
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            score -= 10.0 * (1.0 - (post_residual - next_item_size) as f64 / bin_capacity as f64);
        } else {
            // next item won't fit here; slight penalty proportional to wasted opportunity
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Time horizon: early in the stream, be more willing to open new bins
    // (favor spreading); late in the stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // Opening a new bin: baseline penalty that shrinks as stream progresses
        // and grows with the number of already open bins.
        score += 20.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
        // If current item is large and would leave a big gap elsewhere, new bin is fine.
        if item_size as f64 > 0.6 * bin_capacity as f64 {
            score -= 8.0;
        }
    } else {
        // Using an existing bin: small bonus that grows with progress.
        score -= 5.0 * progress;
        // Prefer bins whose residual is below the mean (consolidating fuller bins).
        if (bin_residual as f64) < mean_residual {
            score -= 4.0;
        } else {
            score += 2.0;
        }
    }

    // Mild preference for bins with many open alternatives (avoid stranding unique bins).
    if fitting_bins_count > 1 {
        score += 1.5; // keep the "last chance" bin free unless this fit is great
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress.
    let norm_pr = pr / cap;
    score += 18.0 * norm_pr * norm_pr * (0.5 + 0.5 * progress);

    // Reward tight fits more aggressively as stream progresses.
    let tightness = 1.0 - norm_pr;
    score -= 22.0 * tightness * tightness * tightness * (0.4 + 0.6 * progress);

    // Lookahead: penalize residual that cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            score -= 8.0 * (1.0 - (pr - nxt) / cap);
        } else {
            score += 10.0 * (nxt - pr) / cap;
        }
    }

    // Last-chance bin bonus to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 14.0 * (0.5 + 0.5 * progress);
    }

    // Slight preference for bins below mean residual (consolidating slack).
    score -= 4.0 * ((bin_residual as f64 - mean_residual) / cap);

    // Mild new-bin penalty that relaxes late in the stream.
    if bin_residual == bin_capacity {
        score += 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover lies in "usable"
    // residue classes (multiples of small granules) are preferred.
    let post = post_residual as i64;
    let granule = 10i64;
    let residue = post % granule;
    // Penalize awkward leftovers (not near a granule multiple, not near zero).
    let awkward = if post == 0 { 0.0 } else {
        let r = residue as f64;
        let dist = r.min((granule - residue) as f64);
        dist * 1.7
    };
    score += awkward;

    // Reward perfect fits strongly.
    if post == 0 {
        score -= 250.0;
    }

    // Reward leaving room for the lookahead item (harmonic coupling of
    // post_residual and next_item_size via integer division classes).
    if next_item_size > 0 {
        let nxt = next_item_size as i64;
        if post >= nxt {
            // Next item could fit here later; reward closeness of match.
            let slack = (post - nxt) as f64;
            score -= 30.0 + 0.6 * slack.max(0.0).min(40.0);
            // Exact harmonic class match: post is an exact multiple of next size
            if nxt > 0 && post % nxt == 0 {
                score -= 15.0;
            }
        } else {
            // Dead space relative to lookahead: penalize proportionally.
            score += 0.8 * (nxt - post) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 90.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, softened when many bins are open
        // and mean residual is high (fragmentation already present).
        let frag = mean_residual / bin_capacity as f64;
        score += 120.0 - 40.0 * frag.min(1.0);
        // Late in the stream, opening fresh bins is cheaper than fragmenting.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 25.0 * progress;
        // Large items prefer fresh bins (harmonic class: item > half capacity).
        if item_size > bin_capacity / 2 {
            score -= 20.0;
        }
    }

    // Prefer tighter bins overall (small residual before placement).
    score += 0.15 * (bin_residual as f64 - item_size as f64).max(0.0);

    // Mild penalty for spreading across too many open bins.
    score += 0.05 * open_bins_count as f64;

    // Harmonic threshold classes on post_residual: leftovers in [1,9] and
    // [51,59] are least reusable for typical size ranges.
    if post > 0 && post < 10 {
        score += 25.0;
    }
    if post >= 51 && post <= 59 {
        score -= 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

