        score -= 5.0;
    }

    // Relative to mean residual: bins tighter than average are more valuable
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin unless current bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 60.0 - progress * 10.0;
        // If next item is large and won't co-exist, new bin is more attractive
        if next_item_size > post_residual.max(1) {
            score -= 20.0;
        }
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
    }

    score
