pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong best-fit core: penalize large post residual with a squared term.
    score += 0.35 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    // Perfect fits are highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 5 {
        score -= 25.0;
    } else if post_residual < 10 {
        // dead space below minimum item size is wasted
        score += 12.0 * (10 - post_residual) as f64;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Lookahead: reward bins whose post residual can still hold the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 8.0 + 0.05 * (post_residual as f64 - next_item_size as f64);
        } else {
            // post residual cannot host next item: mild penalty scaled by wasted capacity
            score += 0.08 * post_residual as f64;
        }
        // If next item would exactly fill post residual, big reward (chained perfect fit)
        if post_residual == next_item_size {
            score -= 30.0;
        }
    } else {
        // Last item in stream: just minimize residual.
        score -= 15.0;
    }

    // Time horizon: early in stream, be more willing to open new bins (spread load);
    // late in stream, consolidate into existing bins.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more as stream progresses or many bins open.
        score += 18.0 + 55.0 * progress + 1.2 * open_bins_count as f64;
        // But if mean residual is high (fragmentation), opening fresh bin is attractive.
        score -= 0.25 * mean_residual;
        // If next item is large and current open bins are fragmented, new bin helps.
        if next_item_size > 50 {
            score -= 12.0;
        }
    } else {
        // Existing bin: slight reward for tighter bins relative to mean residual.
        let diff = mean_residual - bin_residual as f64;
        score += 0.10 * diff;
    }

    // Many open bins: encourage filling existing ones rather than spreading.
    if open_bins_count > 8 {
        score += 0.6 * open_bins_count as f64 * (bin_residual == bin_capacity) as i32 as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear coupling to progress
    let mut score = pr * (1.0 + 0.5 * progress * progress);

    // Quadratic dead-space penalty, amplified late in the stream
    score += 30.0 * norm_pr * norm_pr * (0.3 + 0.7 * progress);

    // Reward tight fits (post_residual near 0) with smooth saturation
    score -= 20.0 * (-norm_pr * 8.0).exp();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening new bins when good fits exist,
    // but allow it when the item is large relative to typical residual
    if bin_residual == bin_capacity {
        let fit_pressure = (item_size as f64 / cap) * (1.0 - progress);
        let residual_gap = (mean_residual - item_size as f64).max(0.0) / cap;
        score += 10.0 - 8.0 * fit_pressure - 12.0 * residual_gap;
        // Lookahead: opening a new bin is good if next item also large
        if next_item_size > 0 {
            let next_large = next_item_size as f64 / cap;
            score -= 10.0 * next_large * next_large;
        }
    } else {
        // Penalize wasting a bin that could hold the next item too
        if next_item_size > 0 && post_residual > 0 && (next_item_size as u32) > post_residual {
            score += 3.0;
        } else if next_item_size > 0 {
            score -= 2.0 * (next_item_size as f64 / cap);
        }
    }

    // Mild penalty for spreading across many open bins
    score += 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Mean-residual coupling: prefer bins near the mean residual (keeps bin sizes homogeneous)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 5.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize dead space into capacity fractions.
    let frac = post_residual as f64 / bin_capacity as f64;

    // Reward tight fits: post_residual near zero is excellent.
    score -= 40.0 * (1.0 - frac).powi(6);

    // Penalize dead space in awkward "unfillable" classes.
    // Residuals that are too small for typical items (1..100) but nonzero are wasteful.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Harmonic classes via integer division on post_residual:
    // residuals divisible by common item sizes (e.g. 10, 20, 25, 50) are more reusable.
    let reusable = (post_residual % 10 == 0) as f64 * 8.0
        + (post_residual % 25 == 0) as f64 * 6.0
        + (post_residual % 50 == 0) as f64 * 4.0;
    score -= reusable;

    // Penalize residuals in "dead zones" that few item sizes can fill:
    // e.g. (90,100) can only be filled by tiny items; (60..90) moderately reusable.
    let dead_zone = if post_residual >= 90 { 25.0 } else if post_residual >= 70 { 10.0 } else { 0.0 };
    score += dead_zone * (1.0 - frac);

    // Next-item coupling: if the next item fits the post residual exactly or well, reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 50.0;
        } else if next_item_size <= post_residual {
            let slack = post_residual - next_item_size;
            score -= 15.0 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to gap
            score += 5.0 * ((next_item_size - post_residual) as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a fresh bin should only win when no open bin
    // offers a decent fit. Give the empty bin a baseline cost plus a penalty that grows
    // with how many bins are already open.
    if bin_residual == bin_capacity {
        score += 55.0 + 3.0 * open_bins_count as f64;
        // But if the item is large and likely to need a fresh bin anyway, ease the cost.
        if item_size >= bin_capacity / 2 {
            score -= 25.0;
        }
    }

    // Prefer bins below the mean residual (denser bins) to keep packing tight.
    score += 0.15 * (bin_residual as f64 - mean_residual).max(0.0);

    // Stream progression: early on, be more willing to open bins (spread risk);
    // late, consolidate tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score -= 20.0 * (1.0 - progress);
    }

    // Modulo class of item size: items in awkward classes (prime-ish / odd sizes)
    // benefit more from exact fits; already covered, but add slight preference for
    // placing odd items into bins whose residual shares parity.
    if item_size % 2 == 1 && post_residual % 2 == 0 && post_residual > 0 {
        score += 2.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

