    // Dead space relative to capacity (non-linear squashing).
    let dead_frac = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * dead_frac * dead_frac;

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Pressure from many open bins: discourage spreading items across bins.
    score += open_bins_count as f64 * 0.8;

