    }

    // Mild stream-progression tightening: later in stream, favor tighter packing.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += dead_frac * 20.0 * progress;
    }

    // New-bin candidate handling: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
