    let frag_threshold = 10.0;
    if (post_residual as f64) < frag_threshold {
        score += 6.0; // tiny dead space penalty
    }

    // 2-step lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let post = post_residual as f64;
        if next <= post {
            let slack = post - next;
            if slack < frag_threshold {
                score -= 25.0; // perfect chain: next item fills this bin nearly exactly
            } else {
                score -= 12.0 * (1.0 - slack / post.max(1.0));
            }
        } else {
            // next item cannot fit: penalize proportionally to overshoot
            score += 8.0 * ((next - post) / 100.0).min(1.0);
        }
    }

    // Relative to mean residual: bins tighter than average are better targets.
    score -= (mean_residual - post_residual as f64).clamp(-50.0, 50.0) * 0.15;

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: discourage opening a new bin early in the stream,
    // allow it later when open bins would create large dead space.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let waste = (post_residual as f64) - (bin_capacity as f64 - item_size as f64);
        let _ = waste;
        let poor_fit = (post_residual as f64) > 45.0 && next_item_size > post_residual;
        if poor_fit || open_bins_count == 0 {
            score -= 15.0 + 10.0 * progress;
        } else {
            score += 18.0 - 8.0 * progress;
        }
    }

    // Small nudge toward filling bins more completely over time.
    score += (post_residual as f64 / bin_capacity as f64) * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
