    // Early stream: slightly favor consolidating into fewer bins
    if step_index < total_items / 4 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fills.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Penalize dead space that the next item cannot use.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            score += 0.5 * (next_item_size - post_residual) as f64;
        } else {
            // Dead space reusable by next item: reward proportionally.
            score -= 0.3 * (post_residual as f64 / next_item_size as f64).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 40.0;
    }

    // Penalize bins whose residual deviates from the mean (keep residuals homogeneous).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.2 * dev;

    // New-bin candidate: only attractive when no open bin fits well,
    // i.e., when this empty bin is compared against poor fits.
    if bin_residual == bin_capacity {
        // Base penalty so a new bin is only chosen when alternatives are bad.
        score += 25.0;
        // Late in the stream, opening fresh bins is cheaper (less time to waste them).
        score -= 20.0 * progress;
        // If many bins are open, prefer consolidating instead of adding.
        score += 1.5 * open_bins_count as f64;
        // If next item is large, an empty bin guarantees future fit.
        if next_item_size > bin_capacity / 2 {
            score -= 15.0;
        }
    } else {
        // Prefer tighter bins overall (waste minimization via squared residual).
        score += 0.02 * (post_residual as f64) * (post_residual as f64) / 10.0;
    }

    // Small tie-breaker: favor bins that become nearly full.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * fill_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Quadratic waste penalty: large post-residuals are increasingly bad.
    score += 12.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling of residual with stream progress:
    // early on, tight packing matters less; later, waste compounds.
    score += 20.0 * norm_pr * (progress * progress);

    // Cubic interaction term favoring exact-ish fits as stream matures.
    score -= 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) * (1.0 - norm_pr) * (0.5 + progress);

    // Lookahead: reward residual that can host the next item smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fit = if pr >= nxt { 1.0 - (pr - nxt) / cap } else { 0.0 };
        score -= 10.0 * fit * fit;
    } else {
        score -= 8.0 * (1.0 - norm_pr);
    }

    // Last-chance bin: strongly discourage opening a new bin when this is the only fit.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0 * (1.0 - norm_pr);
    }

    // Many open bins with high mean residual: prefer filling existing space.
    let open_f = open_bins_count as f64;
    score += 0.5 * open_f * norm_pr - (mean_residual / cap) * (1.0 - norm_pr) * 5.0;

    // New-bin candidate: penalize opening a fresh bin unless existing fits are terrible.
    if bin_residual == bin_capacity {
        score += 30.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // --- Harmonic class of the post-residual: exact-divisor residuals are "usable" ---
    // Residuals divisible by small harmonics (e.g. 10, 20, 25, 50) are reusable slots.
    let pr = post_residual;
    let mut harmony_bonus = 0.0;
    if pr > 0 {
        if pr % 10 == 0 { harmony_bonus += 2.0; }
        if pr % 20 == 0 { harmony_bonus += 1.5; }
        if pr % 25 == 0 { harmony_bonus += 1.5; }
        if pr % 50 == 0 { harmony_bonus += 2.5; }
        if pr == 0 { harmony_bonus += 6.0; } // perfect fill
    }
    score -= harmony_bonus;

    // Dead-space penalty: residuals that no plausible item (1..=100) can use well.
    // Tiny residuals (1..9) are almost dead; large residuals are fine.
    if pr > 0 && pr < 10 {
        score += (10 - pr) as f64 * 1.2;
    }

    // --- Coupling with next item: can the next item fit into post_residual? ---
    if next_item_size > 0 {
        if next_item_size <= pr {
            // Great: this bin can also serve the next item.
            score -= 3.0 + (next_item_size as f64 / bin_capacity as f64) * 4.0;
            // Harmonic match: next item exactly consumes a harmonic fraction.
            if pr % next_item_size.max(1) == 0 {
                score -= 2.0;
            }
        } else {
            // Next item cannot follow here; penalize more if the gap is small
            // (wasted near-fit) and if many bins are open (fragmentation).
            let gap = (next_item_size - pr) as f64;
            score += gap * 0.15 * (1.0 + open_bins_count as f64 * 0.05);
        }
    }

    // --- Last-chance bin: if this is the only bin that fits, strongly prefer it ---
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 4.0;
    }

    // --- Prefer tight fits: relative waste vs capacity ---
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= tightness * 5.0;

    // --- New-bin candidate logic: only attractive when open bins are crowded ---
    if bin_residual == bin_capacity {
        // Base reluctance to open a new bin while others could fit.
        score += 3.0 + open_bins_count as f64 * 0.3;
        // But if the item is large relative to mean residual space, opening fresh
        // is harmonic: item exactly matches a capacity fraction -> good fresh slot.
        if bin_capacity % item_size.max(1) == 0 {
            score -= 4.0;
        }
        // If mean residual is small (bins nearly full), new bin is fine.
        if mean_residual < item_size as f64 {
            score -= 5.0;
        }
        // Late in stream, avoid hoarding open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= progress * 2.0;
    }

    // --- Fragmentation control: penalize when this bin's residual deviates from mean ---
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.05;

    // Small tie-break toward fewer open bins.
    score += open_bins_count as f64 * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any future item (1..=100)
    // are pure waste; penalize the unusable gap quadratically.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + 4.0 * (10 - post_residual) as f64;
    } else if post_residual >= 10 && post_residual < 30 {
        // Semi-usable gap: mild penalty, worse the smaller it is.
        score += 0.35 * (30 - post_residual) as f64;
    }

    // Reward tight fits (near-perfect packing).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Open-bins pressure: penalize placements that keep many bins alive,
    // unless the bin is nearly full (consolidation is fine).
    let fill_frac = 1.0 - (post_residual as f64) / bin_capacity as f64;
    score += 0.6 * open_bins_count as f64 * (1.0 - fill_frac);

    // New-bin candidate: default attractiveness of a fresh empty bin.
    if bin_residual == bin_capacity {
        // Attractive early or when open bins are mostly full; unattractive
        // if open bins have plenty of room and this is a small item.
        score = 55.0
            - 3.0 * open_bins_count as f64
            - 0.25 * mean_residual
            + 0.4 * item_size as f64;
        // Avoid opening a new bin for a small item when a good gap exists elsewhere.
        if item_size < mean_residual {
            score += 15.0;
        }
        // Late in the stream, prefer closing out existing bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If exactly one bin fits and it's not this new bin, make new bin less appealing.
        if fitting_bins_count <= 1 {
            score += 20.0;
        }
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 35.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let nxt = next_item_size as f64;
    let mut score = post;

    // Reward perfect or near-perfect matches with the next item (2-step lookahead).
    if next_item_size > 0 && next_item_size <= post_residual {
        let fit_quality = nxt / (post + 1.0); // 1.0 = perfect fill
        score -= 18.0 * fit_quality * fit_quality;
    }
    // Penalize residuals that can never fit the next item (dead space).
    if next_item_size > post_residual {
        score += 6.0;
    }

    // Tightness of current fit: prefer bins where item fills a large fraction.
    let tight = item_size as f64 / bin_residual.max(1) as f64;
    score -= 10.0 * tight;

    // Compare against mean residual: prefer bins with small residual (tight packing).
    let dev = (post - mean_residual) / cap;
    score += 8.0 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Early in stream, slightly prefer opening fresh bins for future flexibility.
    let progress = step_index as f64 / (total_items as f64).max(1.0);
    if bin_residual == bin_capacity {
        score -= 4.0 * (1.0 - progress);
    } else {
        score += 2.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 60.0;
    } else {
        // Penalize small dead space that nothing can realistically use
        let dead = post_residual as f64;
        if dead < 10.0 {
            score += 25.0;
        }
        // Favor residual that can still host typical items
        if dead >= 10.0 && dead <= 40.0 {
            score -= 5.0;
        }
    }

    // Tightness ratio: reward filling bin proportionally
    let fill = item_size as f64 / bin_residual.max(1) as f64;
    score -= 20.0 * fill;

    // Last-chance bin: strongly prefer using the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Lookahead: bonus if next item fits the post-residual
    if next_item_size > 0 {
        if post_residual >= next_item_size && post_residual > 0 {
            score -= 12.0 * (next_item_size as f64 / post_residual as f64);
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 8.0;
        }
    }

    // Global state: penalize scattering across many open bins when mean residual is large
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if bin_residual < bin_capacity {
        score += 0.4 * open_bins_count as f64 * (1.0 - progress);
        // Reward bins below mean residual (relatively full bins)
        if (bin_residual as f64) < mean_residual {
            score -= 6.0;
        }
    }

    // New-bin candidate handling: only attractive when item is huge relative to
    // typical residual or many bins are already crowded
    if bin_residual == bin_capacity {
        let crowding = mean_residual / bin_capacity as f64;
        score = 45.0 + 30.0 * (1.0 - crowding) - 10.0 * progress;
        if item_size >= 70 {
            score -= 15.0; // big items justify fresh bins
        }
        if next_item_size > 0 && next_item_size >= 60 && item_size >= 60 {
            score -= 10.0; // pair two big items in a fresh bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize leftover space, with non-linear (quadratic) growth
    let mut score = pr + 40.0 * norm_pr * norm_pr * cap;

    // Smooth polynomial coupling of post_residual with stream progress:
    // late in the stream, tight fits matter more
    let coupling = 1.0 + 2.0 * progress * progress;
    score *= coupling;

    // Interaction: post_residual vs mean residual — avoid bins that become outliers
    let dev = (pr - mean_residual) / cap;
    score += 15.0 * dev * dev * cap;

    // Penalize waste relative to item size (large items leaving large gaps)
    let item_f = item_size as f64;
    let waste_ratio = pr / (item_f + 1.0);
    score += 8.0 * waste_ratio.sqrt();

    // Lookahead: reward residual that can still fit the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if pr >= ns {
            score -= 6.0 * (1.0 - pr / cap) * (1.0 + progress);
        } else {
            // dead space for next item: penalize smoothly
            score += 5.0 * (ns - pr) / cap * cap * (0.5 + progress);
        }
    }

    // Last-chance bin: strongly reward using it (avoids opening a new bin)
    if fitting_bins_count == 1 {
        score -= 25.0 + 20.0 * progress;
    } else {
        // mild reward for spreading across bins when many fit
        score += 2.0 * (fitting_bins_count as f64).ln().max(0.0);
    }

    // New-bin candidate: only attractive when no good fit exists
    if bin_residual == bin_capacity {
        let pressure = 1.0 / (fitting_bins_count.max(1) as f64);
        let gap = (mean_residual - item_f).max(0.0) / cap;
        score = cap * (0.6 + 0.5 * progress) - 30.0 * pressure * (1.0 + gap) + 10.0 * norm_pr;
    }

    // Mild penalty for proliferating bins late in the stream
    score += 0.5 * (open_bins_count as f64) * (0.3 + 0.7 * progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "useful" sizes
    // (small, or exactly matching common item sizes via modulo structure).
    let pr = post_residual;
    let cls = pr % 10;
    let half = bin_capacity / 2;

    // Reward near-perfect fits strongly.
    if pr == 0 {
        score -= 500.0;
    } else if pr <= 5 {
        score -= 120.0;
    } else if pr <= 15 {
        score -= 40.0;
    }

    // Dead-space penalty: residuals in the awkward (half-cap, cap) band are hard to fill.
    if pr > half && pr < bin_capacity {
        score += 0.35 * (pr - half) as f64;
    }

    // Harmonic reward: residual divisible into fine classes (multiples of 10 or 5)
    // matches typical item granularity.
    if cls == 0 {
        score -= 12.0;
    } else if cls == 5 {
        score -= 6.0;
    } else {
        score += 4.0;
    }

    // Lookahead: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 300.0;
        } else if next_item_size < pr {
            let slack = (pr - next_item_size) as f64;
            score -= (60.0 * (1.0 - slack / cap)).max(0.0);
        } else {
            // next item cannot fit here; mild penalty proportional to overshoot class
            score += ((next_item_size - pr) % 10) as f64;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 80.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins.
    if bin_residual == bin_capacity {
        let good_open = (mean_residual - item_size as f64).abs() < 10.0 && fitting_bins_count > 0;
        if good_open {
            score += 250.0; // discourage wasting a fresh bin
        } else {
            score -= 30.0; // fresh bin keeps full flexibility
        }
        // Late in the stream, prefer consolidation into open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 150.0 * progress;
    }

    // Prefer spreading across many open bins slightly less than cramming when
    // mean residual is high (lots of slack available overall).
    if open_bins_count > 0 && mean_residual > 50.0 {
        score += 0.1 * (mean_residual - 50.0);
    }

    // Tie-break: prefer bins with residual closest to the item (tightest fit).
    score += 0.05 * (bin_residual - item_size) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small nonzero gaps are the worst outcome.
    if post_residual > 0 {
        let dead = post_residual as f64;
        if dead < 10.0 {
            // tiny unusable sliver -> heavy penalty
            score += (10.0 - dead) * 4.0;
        } else {
            // larger leftovers are more reusable; mild superlinear decay
            score += 40.0 / (1.0 + dead / 20.0);
        }
    } else {
        // perfect fit: strong reward
        score -= 30.0;
    }

    // Last-chance bin: strongly prefer using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing bins fit poorly
    // (large dead space would be created) or no bin fits.
    if bin_residual == bin_capacity {
        let fit_penalty = if post_residual < 10.0 { 60.0 } else { 0.0 };
        score += 5.0 + fit_penalty + open_bins_count as f64 * 0.5;
        // if next item could combine with current leftover, discourage new bin
        if next_item_size > 0 && post_residual >= next_item_size {
            score += 15.0;
        }
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // leaving room exactly for the lookahead item is valuable
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // leftover too small for lookahead: dead space risk
        score += (next_item_size - post_residual) as f64 * 0.4;
    }

    // Open-bin pressure: discourage spreading across many bins slightly.
    score += open_bins_count as f64 * 0.3;

    // Mild normalization toward mean residual state.
    score += (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: quadratic penalty on wasted space
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // 2-step lookahead: if next item fits into post_residual, big reward
    if next_item_size > 0 && post_residual >= next_item_size {
        let next_fit_quality = (post_residual - next_item_size) as f64;
        score -= 18.0 * (1.0 - next_fit_quality / bin_capacity as f64);
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that next item cannot use: penalize proportionally
        score += 6.0 * (post_residual as f64 / next_item_size.max(1) as f64);
    }

    // Perfect chain: item + next item exactly fills the bin
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 40.0;
    }

    // Last chance bin: strongly favor using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // Compare residual against mean residual: prefer bins tighter than average
    score -= 4.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Early in stream: slightly prefer consolidating into few bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 8.0 * (1.0 - progress) * (open_bins_count as f64 / 20.0);

    // Brand-new empty bin candidate: penalize unless item is large relative to capacity
    if bin_residual == bin_capacity {
        score += 12.0 - 10.0 * (item_size as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

