    }

    // New-bin candidate: penalize opening a new bin, but relax the penalty when
    // no good fit exists (post_residual here equals capacity - item_size).
    if bin_residual == bin_capacity {
        let mut new_bin_penalty = 30.0;
        // If existing bins would leave large waste, opening fresh is less bad.
        if fitting_bins_count > 0 {
