        // Early in the stream, slightly prefer consolidating (fewer bins later);
        // late in the stream, opening new bins is fine.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        new_bin_penalty *= 1.0 - 0.4 * progress;
        // Many open bins: discourage spreading further.
        new_bin_penalty += (open_bins_count as f64).ln().max(0.0) * 2.0;
        score += new_bin_penalty;
    }

    // Lookahead coupling: if the next item fits the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + next_item_size as f64 * 0.1;
    }
    // If next item almost fits, slight penalty (waste risk).
    if next_item_size > post_residual && next_item_size - post_residual <= 5 && post_residual > 0 {
        score += 3.0;
    }

    // Prefer bins whose residual deviates favorably from the mean residual
    // (use the bin that is "most full" relative to average).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Mild global pressure: when many bins are open, favor filling existing ones.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear waste penalty: post_residual dominates quadratically
    let pr = post_residual as f64;
    score += 0.35 * (pr * pr) / cap;

    // Reward tight fits (small post_residual relative to item)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Perfect fit bonus
    if post_residual == 0 {
        score -= 25.0;
    }

    // Stream progress: later in the stream, favor consolidating into open bins
    let progress = step_index as f64 / total_items as f64;
    score -= 8.0 * progress * (1.0 - pr / cap);

    // New-bin candidate: penalize opening a bin mildly, but allow it when
    // existing residuals are poor relative to the item
    if bin_residual == bin_capacity {
        let avg_gap = (mean_residual - item_size as f64).max(0.0);
        let openness = open_bins_count as f64 / (1.0 + progress * 5.0);
        score += 6.0 + 0.05 * openness - 0.15 * avg_gap;
    } else {
        // Existing bin: slight bonus when it is the last fitting option
        if fitting_bins_count == 1 {
            score -= 15.0;
        }
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        score -= 10.0 * (next_item_size as f64 / cap);
    } else if next_item_size > 0 && next_item_size >= bin_residual {
        // next item won't fit here anyway; less pressure on tight fit
        score -= 3.0;
    }

    // Penalize bins far below mean residual (fragmented outliers)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 4.0 * dev * dev;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the leftover space: residuals divisible by small
    // integers are more reusable by typical item sizes.
    let r = post_residual;
    if r > 0 {
        if r % 10 == 0 {
            score -= 6.0;
        } else if r % 5 == 0 {
            score -= 3.0;
        }
        if r % 25 == 0 {
            score -= 4.0;
        }
        // Dead-space penalty: leftover too small for the smallest plausible item
        if r < 10 {
            score += 40.0;
        } else if r < 20 {
            score += 12.0;
        }
    }

    // Lookahead coupling: does the next item fit exactly into the post residual?
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 30.0; // perfect pair
        } else if next_item_size <= r {
            score -= 8.0; // next item still fits
            // harmonic class match between leftover and next item
            if r % next_item_size == 0 {
                score -= 6.0;
            }
        } else {
            score += 5.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when this bin's fit is poor.
    if bin_residual == bin_capacity {
        // base cost of opening a bin
        score += 15.0;
        // more attractive early in the stream or when many bins are open
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
        if open_bins_count > 0 {
            // if mean residual is large, prefer packing into existing bins
            if mean_residual > item_size as f64 * 1.5 {
                score += 20.0;
            }
        } else {
            score -= 50.0; // must open the first bin
        }
    }

    // Prefer tight fits: small post_residual relative to capacity fraction classes
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 10.0 * (frac - 0.5).abs();

    // Mild preference for bins with below-mean residual (consolidate fullness)
    score += 0.3 * (mean_residual - bin_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to ever
    // hold a realistic item (below ~10) are pure waste -> heavy penalty.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Small gaps (10..=25) are rarely reusable -> escalating penalty.
    if post_residual >= 10 && post_residual <= 25 {
        score += 18.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward near-perfect fits strongly.
    if post_residual == 0 {
        score -= 40.0;
    } else if post_residual <= 5 {
        score -= 20.0;
    }

    // Last-chance pressure: if this is the only bin that fits, strongly
    // prefer using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading;
    // prefer packing into existing bins rather than opening new ones.
    score += open_bins_count as f64 * 0.6;

    // New-bin candidate (empty bin): make it unattractive unless current
    // fit is terrible or the item would leave a large awkward gap elsewhere.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 30.0;
        // But if placing into an existing bin would create unusable dead
        // space, opening fresh is competitive: soften the penalty.
        if post_residual >= 10 && post_residual <= 25 {
            score -= 20.0;
        }
        // Late in the stream, prefer closing out bins (less future need).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * progress;
    }

    // Lookahead coupling: if the next item fits exactly in the post
    // residual, reward this placement (chained packing).
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 25.0;
    }
    // If next item fits in post residual, mild reward.
    if next_item_size > 0 && next_item_size < post_residual {
        score -= 6.0;
    }
    // If next item would NOT fit in post residual, mild penalty for
    // leaving a gap that strands the lookahead item.
    if next_item_size > post_residual && post_residual > 0 {
        score += 8.0;
    }

    // Mean-residual coupling: if this bin is far above mean residual
    // (i.e., unusually full), placing here is efficient -> reward.
    let diff = mean_residual - post_residual as f64;
    if diff > 0.0 {
        score -= 0.25 * diff;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect-fit reward: squash post_residual so tiny residuals are heavily favored.
    let pr = post_residual as f64;
    let tightness = (pr / bin_capacity as f64).powf(2.0);
    score += tightness * 30.0;

    // 2-step lookahead: reward when the post residual can host the next item exactly or well.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr >= nxt {
            let slack = pr - nxt;
            score -= (1.0 - slack / bin_capacity as f64) * 18.0; // next item fits snugly
        } else {
            score += (nxt - pr) / bin_capacity as f64 * 12.0; // next item won't fit: penalize
        }
    } else {
        // Last item: strongly prefer minimal residual.
        score += pr * 0.4;
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious; using them
    // should be encouraged when the fit is tight, discouraged when it creates dead space.
    let dev = pr - mean_residual;
    score += dev * 0.15;

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 8.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item is large
    // relative to capacity or open-bin fits are all poor.
    if bin_residual == bin_capacity {
        let large_item = item_size as f64 / bin_capacity as f64;
        score += 10.0 - large_item * 12.0;
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 4.0; // fresh bin can also host the next item
        }
    }

    // Late-stream conservatism: as the stream progresses, prefer reusing open bins
    // to avoid leaving many half-empty bins at the end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual != bin_capacity {
        score -= progress * 3.0;
    }

    // Slight preference for consolidating into fewer bins when many are open.
    if bin_residual != bin_capacity {
        score -= (open_bins_count as f64).ln().max(0.0) * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: post_residual near zero is ideal.
    score += (post_residual as f64 / bin_capacity as f64).powi(3) * 40.0;

    // Reward if the lookahead item can also fit in the remaining space.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
        // Extra reward when next item fills the bin almost exactly.
        let gap = post_residual - next_item_size;
        score -= (gap == 0) as i32 as f64 * 15.0;
    }
    // Penalize residuals too small for typical future items (dead space).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size.min(10) {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin, more so when many bins
    // are open or the item is small enough to fit elsewhere harmlessly.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 30.0 + 20.0 * (1.0 - progress) + item_size as f64 * 0.2;
        // If no open bin fits well, opening is less bad.
        if fitting_bins_count == 0 {
            score -= 35.0;
        }
    }

    // Mildly prefer bins with residual close to the item (best-fit flavor).
    let fit_gap = (bin_residual as f64 - item_size as f64).abs();
    score += fit_gap * 0.1;

    // Prefer bins below mean residual (fill emptier bins first).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Slight time-varying pressure: later in the stream, pack tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits, non-linearly scaled by stream progress.
    let mut score = norm_pr * (1.0 + 0.8 * progress * progress);

    // Quadratic dead-space penalty: small residuals are wasteful, large ones fine.
    score += 0.35 * norm_pr * norm_pr * (1.0 - progress);

    // Lookahead: reward if next item fits the post-residual exactly or well.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            let slack = pr - nx;
            score -= 0.6 * (1.0 - slack / cap);
        } else {
            score += 0.3 * (nx - pr) / cap;
        }
    }

    // Last-chance bonus: if this is the only fitting bin, strongly favor using it.
    if fitting_bins_count == 1 {
        score -= 1.5 + 1.0 * progress;
    }

    // Mean-residual coupling: penalize bins far from the mean residual (outliers).
    let dev = (pr - mean_residual) / cap;
    score += 0.25 * dev * dev;

    // New-bin candidate: empty bin should only win when open bins are fragmented.
    if bin_residual == bin_capacity {
        let fragmentation = if open_bins_count > 0 { mean_residual / cap } else { 0.0 };
        score = 0.9 + 0.5 * fragmentation - 0.4 * progress;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score += 0.1;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

