        else if pr % 5 == 0 { class_bonus += 3.0; }
        if pr % 25 == 0 { class_bonus += 4.0; }
        // Dead space penalty: tiny unusable slivers
        if pr < 10 { class_bonus -= 15.0; }
        if pr > 0 && pr < 5 { class_bonus -= 10.0; }
    } else {
        class_bonus += 12.0; // perfect fill
    }
    score -= class_bonus;

    // Coupling with next item: reward post_residual that exactly hosts the lookahead item
    if nis > 0 {
        if pr == nis { score -= 20.0; }
        else if pr >= nis {
            let slack = (pr - nis) as f64;
            score -= 8.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // post_residual can't host next item: penalize proportional shortfall
            score += 4.0 * ((nis - pr) as f64 / cap);
        }
    }

    // Fractional fill of the bin before placement
    let fill = 1.0 - (bin_residual as f64) / cap;
    score -= 5.0 * fill * fill;

    // Last-chance bin: strongly prefer using it over opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it moderately attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        let base_open = 30.0;
        let pressure = if fitting_bins_count == 0 { 40.0 } else {
            (mean_residual - item_size as f64).max(0.0) * 0.3
