        score = base_open - pressure + 10.0 * (open_bins_count as f64).sqrt().min(5.0);
        if nis > 0 && nis >= item_size as i64 && pr == 0 {
            score -= 5.0; // fresh bin pairs well with big lookahead
        }
    }

    // Stream progression: tighten packing later in the stream
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 3.0 * progress * (1.0 - (post_residual as f64) / cap);

    // Mean residual alignment: prefer bins near the mean residual
    let dev = ((post_residual as f64) - mean_residual).abs();
    score += 0.05 * dev;

    score
}

