pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fits are ideal
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: small residuals are dead space
    let cap = bin_capacity as f64;
    let frac = post_residual as f64 / cap;

    // Penalize residuals that fall into "awkward" classes (e.g. 1..=9, or just above common sizes)
    if post_residual > 0 {
        let awkward = if post_residual < 10 { 60.0 }
            else if post_residual <= 20 { 30.0 }
            else if post_residual <= 30 { 15.0 }
            else { 0.0 };
        score += awkward * (1.0 + frac);
    }

    // Modulo-harmonic bonus: residuals divisible by common item sizes are reusable
    let harmonics: [u32; 6] = [10, 20, 25, 30, 40, 50];
    for h in harmonics {
        if post_residual % h == 0 && post_residual > 0 {
            score -= 12.0;
            break;
        }
    }

    // Lookahead coupling: if next item fits exactly in post_residual, strong reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 400.0;
        } else if next_item_size < post_residual {
            let gap = post_residual - next_item_size;
            score -= 40.0 - (gap as f64).min(40.0);
            // next item leaves a harmonic residual too
            if gap > 0 && (post_residual - next_item_size) % 10 == 0 {
                score -= 10.0;
            }
        } else {
            // next item cannot use this bin's remainder: mild penalty for tight fits
            if post_residual < 10 {
                score += 10.0;
            }
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // New-bin candidate: prefer keeping it closed early; prefer opening late when open bins are fragmented
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let fragmentation = (mean_residual - post_residual as f64).abs() / cap;
        score += 80.0 - 60.0 * progress - 30.0 * fragmentation;
        if open_bins_count == 0 {
            score -= 500.0;
        }
    } else {
        // Favor bins whose residual is close to the mean (balanced packing)
        score += 0.3 * (bin_residual as f64 - mean_residual).abs();
    }

    // Mild preference for using many open bins when stream is long
    if open_bins_count > 0 && bin_residual != bin_capacity {
        score -= 2.0 * (open_bins_count as f64).ln().max(0.0);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps (< 10, or gaps that no
    // plausible future item can use) are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 25.0;
    } else {
        // Non-linear penalty on wasted fraction of the residual before placement.
        let waste_frac = post_residual as f64 / bin_residual as f64;
        score += 8.0 * waste_frac * waste_frac;
    }

    // Favor bins whose residual is close to the item (tight relative fit).
    let tightness = (bin_residual as f64 - item_size as f64) / bin_capacity as f64;
    score += 5.0 * tightness;

    // Lookahead coupling: if the next item fits the post residual exactly,
    // this placement chains well.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
            if post_residual == next_item_size {
                score -= 10.0;
            }
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 4.0; // dead space relative to the known future demand
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin (unless fit is terrible).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: when many bins are open, avoid spreading; prefer
    // filling existing bins and penalize opening new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize when many bins already open or mean
        // residual is still large enough to absorb items.
        score += 20.0 + 3.0 * open_bins_count as f64 + mean_residual * 0.3;
    } else {
        score -= pressure.min(10.0);
    }

    // Mild preference for bins with residual above the mean (keep balanced
    // capacity distributed).
    if bin_residual as f64 > mean_residual {
        score += 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward near-perfect fits
    if post_residual == 0 {
        score -= 200.0;
    } else if post_residual <= 2 {
        score -= 150.0;
    } else if post_residual <= 5 {
        score -= 100.0;
    }

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // exactly (or nearly) matches the next item's size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs();
        if diff == 0 {
            score -= 120.0;
        } else if diff <= 3 {
            score -= 80.0 - 10.0 * diff as f64;
        } else if (post_residual as f64) > next_item_size as f64 {
            // next item could still fit here afterwards: mild bonus proportional to slack
            score -= 20.0 * (1.0 - diff as f64 / bin_capacity as f64);
        } else {
            // next item cannot use the leftover: penalize dead space
            score += 0.3 * diff as f64;
        }
    }

    // Compare post_residual against mean residual: leaving more than average
    // is wasteful; leaving less is good.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate: only attractive when few bins fit or the fit would be bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let good_fit_elsewhere = fitting_bins_count > 0 && (post_residual as f64) <= mean_residual;
        let _ = good_fit_elsewhere;
        // Penalize opening a new bin, scaled by how many bins could fit and stream progress.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 90.0 + 25.0 * fitting_bins_count as f64 - 20.0 * progress;
        // But if placing in an existing bin would leave a big awkward remainder
        // and next item is large, opening a fresh bin is competitive.
        if next_item_size > 0 && post_residual > 0 && (post_residual as u32) < next_item_size && post_residual > 20 {
            score -= 70.0;
        }
        if post_residual == bin_capacity && item_size == 0 {
            score -= 300.0;
        }
    }

    // Slight preference for tighter bins overall
    score += 0.1 * (bin_capacity - bin_residual) as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead: penalize residual that cannot host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Residual useful for next item: mild reward, stronger if it's a snug fit.
            let snug = (post_residual - next_item_size) as f64 / bin_capacity as f64;
            score -= 4.0 * (1.0 - snug);
        } else {
            // Dead space relative to the lookahead item.
            score += 6.0 * (next_item_size - post_residual) as f64 / 100.0;
        }
    }

    // Penalize wasting a nearly-empty bin's potential on a small item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    if fill_ratio < 0.35 && bin_residual < bin_capacity {
        score += 10.0 * (1.0 - fill_ratio);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate logic: only attractive if open bins fit poorly.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let poor_fit_penalty = (post_residual as f64).max(0.0); // post_residual = capacity - item
        let mut new_bin_score = 30.0 + poor_fit_penalty * 0.5;
        // Late in the stream, prefer closing out open bins.
        new_bin_score += 20.0 * progress;
        // Many open bins with slack: discourage opening another.
        new_bin_score += 2.0 * open_bins_count as f64;
        // If mean residual is large, open bins likely absorb the item fine.
        new_bin_score += 0.3 * mean_residual;
        // But if no open bin can even fit (fitting_bins_count==0 handled elsewhere),
        // still allow new bin when item is huge.
        if item_size > 70 {
            new_bin_score -= 15.0;
        }
        score = score.max(0.0) + new_bin_score;
    }

    // Mild preference to balance residuals across bins (avoid many tiny + one huge).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * dev;

    // Small noise-free deterministic tie-breaker based on stream position.
    score += 0.01 * ((step_index % 7) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear penalty on dead space (quadratic coupling)
    let pr = post_residual as f64;
    score += 0.35 * (pr / cap) * (pr / cap) * cap;

    // Reward placements that leave room for the lookahead item (smooth coupling)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (nxt - pr).abs();
        score -= 12.0 * (1.0 - gap / cap).powi(2);
        if pr >= nxt {
            score -= 8.0; // next item can fit exactly in this bin's leftover
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Stream progress: early on, allow spreading (favor tight fits more later)
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let tightness = 1.0 - (item_size as f64 / cap);
    score += progress * 10.0 * tightness * (pr / cap);

    // Prefer filling bins with above-average residual (reduce fragmentation)
    score -= 0.10 * (bin_residual as f64 - mean_residual);

    // New-bin candidate: make it moderately attractive only when no good fit exists
    if bin_residual == bin_capacity {
        score += 6.0 + 0.05 * open_bins_count as f64;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: prefer residuals that are "reusable" classes.
    let pr = post_residual;
    // Perfect fits are excellent.
    if pr == 0 {
        score -= 60.0;
    } else {
        // Class by integer division thresholds on post_residual (dead-space classes).
        let class = pr / 10; // 0..9 harmonic classes
        // Small residuals are dead space; large residuals are useful.
        let class_bonus: f64 = match class {
            0 => -5.0,   // 1..9: nearly dead
            1 => 0.0,    // 10..19
            2 => 2.0,
            3 => 4.0,
            4 => 6.0,
            5 => 7.0,
            6 => 8.0,
            7 => 9.0,
            8 => 10.0,
            _ => 11.0,
        };
        score -= class_bonus;

        // Modulo arithmetic: residuals that are multiples of 5 (common item sizes)
        // are more likely to be exactly filled later.
        if pr % 5 == 0 {
            score -= 6.0;
        }
        if pr % 10 == 0 {
            score -= 4.0;
        }
    }

    // Lookahead coupling: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // How snugly the next item fits: prefer post_residual close to next_item_size.
            let slack = (post_residual - next_item_size) as f64;
            score -= 25.0 - slack.min(25.0) * 0.6;
            if post_residual == next_item_size {
                score -= 20.0; // chain of perfect fits
            }
        } else {
            // Next item cannot fit here: penalize proportionally to the shortfall.
            let shortfall = (next_item_size - post_residual) as f64;
            score += shortfall * 0.4;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits, avoiding a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate handling: opening a new bin is expensive unless current fit is bad.
    if bin_residual == bin_capacity {
        // Fresh bin: base penalty so we prefer existing bins with decent fits,
        // but attractive when the current item would leave awkward residuals elsewhere.
        score += 35.0;
        // If many bins are open and mean residual is high, prefer packing into open bins.
        if open_bins_count > 0 {
            score += (open_bins_count as f64).ln() * 8.0;
            if mean_residual > item_size as f64 {
                score -= 5.0;
            }
        }
        // Late in the stream, opening bins is less costly to consolidate? Keep neutral.
    }

    // Prefer bins whose residual is close to the item (tight fit) beyond raw post_residual.
    let tightness = (bin_residual - item_size) as f64 / cap;
    score += tightness * 10.0;

    // Mild preference to fill bins with larger residual first when many bins open.
    score += (bin_residual as f64 - mean_residual) * 0.15;

    // Progress-based tie-breaker: as stream advances, tighten packing slightly.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= progress * 3.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are the worst outcome.
    if post_residual > 0 && post_residual < 10 {
        score += 120.0;
    }
    // Penalize gaps too small for the smallest plausible item (1..100 range: gaps < ~15 are nearly dead).
    if post_residual > 0 && post_residual < 15 {
        score += (15.0 - post_residual as f64) * 4.0;
    }

    // Reward tight fits (small post_residual) with a non-linear bonus.
    if post_residual > 0 {
        score -= 40.0 / (post_residual as f64 + 2.0);
    } else {
        // Perfect fit: strong reward.
        score -= 60.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap < 10 {
            score -= 35.0; // sets up a near-perfect chain
        } else {
            score -= 12.0;
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Post residual cannot host next item: mild dead-space penalty.
        score += 8.0;
    }

    // Last-chance bin: if this is the only bin that fits, prefer it over opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Open-bin pressure: discourage proliferation of open bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is below the mean (consolidate the emptier bins elsewhere).
    score += (mean_residual - bin_residual as f64) * 0.3;

    // Mild stream-phase modulation: later in the stream, tighten up more.
    let phase = step_index as f64 / total_items.max(1) as f64;
    score += phase * 3.0;

    // New-bin candidate: only attractive when fit into existing bins would be poor.
    if bin_residual == bin_capacity {
        // Base threshold: opening a bin must beat bad fits but not good ones.
        score = 45.0 + open_bins_count as f64 * 1.5 - phase * 5.0;
        if fitting_bins_count == 0 {
            score -= 100.0; // no alternative: new bin is fine
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits (low post_residual), scaled by capacity.
    score = 0.6 * score + 0.4 * (post_residual as f64 / bin_capacity as f64) * 100.0;

    // Aggressive 2-step lookahead: reward exact match between post_residual
    // and next item size (perfect chaining).
    if next_item_size > 0 {
        let gap = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 12.0 * (1.0 - gap / bin_capacity as f64).max(0.0).powi(3);
        // If next item fits exactly, strong bonus.
        if post_residual == next_item_size {
            score -= 20.0;
        }
        // Penalize leaving residual smaller than next item (dead space).
        if post_residual > 0 && post_residual < next_item_size {
            score += 0.35 * post_residual as f64;
        }
    }

    // Compare post_residual relative to mean residual of open bins:
    // leaving residual far below mean wastes usable space.
    score += 0.25 * (mean_residual - post_residual as f64).max(0.0);

    // Last-chance bin: strongly favor using it to avoid opening new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is bad.
    if bin_residual == bin_capacity {
        score += 30.0;
        // But if it's early in the stream and many bins open, allow spread.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 10.0 * (1.0 - progress);
    }

    // Late in stream: be more conservative, keep bins tight.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Dead-space penalty grows steeply for small unusable leftovers
        let pr = post_residual as f64;
        if pr < 10.0 {
            score += 20.0; // tiny sliver is nearly useless
        }
        // Prefer tight fits relative to item size
        score += (item_size as f64 / (bin_residual as f64).max(1.0)) * 5.0;
    }

    // Lookahead: reward leaving space that can host the next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // post residual exactly or nearly matches next item => great
            let gap = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - gap / bin_capacity as f64);
        } else {
            // post residual cannot host next item: mild penalty scaled by waste
            let waste = (next_item_size - post_residual) as f64;
            score += 0.15 * waste.min(30.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // spread preference toward larger residual bins when many fit
        score += 0.05 * (fitting_bins_count as f64);
    }

    // New-bin candidate handling
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive when current bins fit poorly
        // or the mean residual is small (fragmented space).
        let fragmentation = 1.0 - (mean_residual / bin_capacity as f64).clamp(0.0, 1.0);
        let base = 30.0 + 40.0 * fragmentation;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score += base;
            // discourage new bin if next item could also use a fresh bin together later? keep neutral
        } else {
            score += base * 0.5;
        }
        // Late in stream, prefer closing out open bins
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 20.0 * (1.0 - progress);
        // Too many open bins: penalize opening more
        score += 2.0 * (open_bins_count as f64).sqrt();
    }

    // Mild penalty for bins whose residual deviates far from mean (balance)
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Slight preference for filling larger-residual bins early, tighter bins later
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (1.0 - 2.0 * progress) * 0.03 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_post = post_residual as f64 / bin_capacity as f64;
    // Non-linear polynomial coupling: quadratic in normalized post residual, modulated by progress
    score += 18.0 * norm_post * norm_post * (1.0 - progress);
    score += 30.0 * norm_post * norm_post * norm_post * progress;
    // Penalize tight fits less as stream progresses (favor filling existing bins late)
    let tight_fit = 1.0 - norm_post;
    score -= 12.0 * tight_fit * tight_fit * (0.5 + 0.5 * progress);
    // Last-chance bonus: strongly prefer the only fitting bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }
    // Lookahead: reward leaving space for the next item
    if next_item_size > 0 {
        let ns = next_item_size as f64;
        if post_residual as f64 >= ns {
            score -= 8.0 * (1.0 - (post_residual as f64 - ns) / bin_capacity as f64);
        } else {
            score += 6.0 * (ns - post_residual as f64) / bin_capacity as f64;
        }
    }
    // New-bin candidate: penalize mildly so it only wins when fits are terrible
    if bin_residual == bin_capacity {
        score += 25.0 + 15.0 * (1.0 - progress);
    }
    // Deter spreading across many open bins when residuals are large
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * norm_post;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: reward residuals that fall into
    // "usable" classes (small or exactly reusable), penalize mid-range dead space.
    let pr = post_residual;
    let cls = if pr == 0 { 0.0 } else if pr <= 10 { 1.0 } else if pr <= 20 { 2.0 } else { 3.0 };
    score -= cls * 15.0;

    // Modulo logic: residuals that are multiples of common item classes (10/20/25/50)
    // are more likely to be exactly filled later.
    if pr % 10 == 0 { score -= 8.0; }
    if pr % 20 == 0 && pr > 0 { score -= 5.0; }
    if pr % 25 == 0 && pr > 0 { score -= 4.0; }
    if pr % 50 == 0 && pr > 0 { score -= 6.0; }

    // Integer-division threshold: how many "typical" items (size ~ next_item_size)
    // still fit; reward deeper nesting.
    if next_item_size > 0 {
        let fits_next = (pr / next_item_size.max(1)) as f64;
        score -= fits_next * 6.0;
        // Perfect lookahead fit bonus
        if next_item_size == pr {
            score -= 40.0;
        } else if next_item_size < pr {
            score -= (pr - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot follow here: slight penalty
            score += 5.0;
        }
    }

    // Tightness reward: minimal waste placements preferred.
    let waste = (bin_residual - item_size) as f64;
    score += waste * 0.1;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    } else if fitting_bins_count > 1 {
        // prefer bins where item fits relatively tighter among many options
        score += (fitting_bins_count as f64).ln() * 2.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open bins
    // would leave large dead space.
    if bin_residual == bin_capacity {
        let open_pressure = open_bins_count as f64;
        let mean_r = mean_residual.max(0.0);
        // fresh bin baseline: neutral score around mean residual of open bins
        score = cap * 0.55 + mean_r * 0.4 - open_pressure * 1.5;
        if fitting_bins_count == 0 {
            score -= 30.0; // no alternative: must open
        }
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // pairing potential in fresh bin
        }
    }

    // Stream progression: late in stream, consolidate aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;
    score += (open_bins_count as f64) * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps.
    // A residual gap is "unusable" if it is smaller than the smallest plausible item.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item.max(1.0) {
        score += 1000.0;
    }

    // Penalize post_residual that cannot fit the lookahead item (dead space for k=2).
    if next_item_size > 0 {
        if (post_residual as u32) < next_item_size {
            // gap too small for next item: penalize proportionally
            score += (next_item_size - post_residual as u32) as f64 * 0.8;
        } else {
            // gap fits next item: reward tight fit with lookahead
            score -= (next_item_size as f64 - (post_residual as f64 - next_item_size as f64)).abs() * 0.3;
        }
    }

    // Reward tight fits (small post_residual relative to item size)
    score -= (item_size as f64) / ((post_residual as f64) + item_size as f64 + 1.0) * 10.0;

    // Open-bin pressure: discourage spreading across too many bins
    score += (open_bins_count as f64) * 0.05;

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless current residuals are tight
    if bin_residual == bin_capacity {
        // Opening new bin is penalized more when many bins are open with usable space
        score += 30.0 + mean_residual * 0.2;
        // But if no open bin fits well, allow it: handled by fitting_bins_count == 0 case
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Stream progression: late in stream, be more conservative about opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += progress * 2.0;

    // Mean residual coupling: if mean residual is high, prefer filling existing bins
    score += mean_residual * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual exactly
    // matches the next item size (perfect 2-chaining).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score += 0.5 * diff; // penalize mismatch with lookahead size
        if post_residual == next_item_size {
            score -= 40.0; // exact 2-step match: strongly favor
        }
        // if lookahead can't fit anywhere else but fits here after placement
        if next_item_size <= post_residual && fitting_bins_count <= 1 {
            score -= 25.0;
        }
    }

    // Penalize dead space (small unusable residuals)
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // Perfect closure reward
    if post_residual == 0 {
        score -= 30.0;
    }

    // Relative to mean residual: prefer bins that are tighter than average
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin bonus
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // Early stream: be less picky; late stream: consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: prefer it only when item leaves large residual and
    // few fitting bins exist (poor fit elsewhere)
    if bin_residual == bin_capacity {
        score += 8.0;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size >= post_residual {
            score += 10.0; // new bin won't chain with next item
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 22.0 * tightness * tightness;

    // Penalize large dead space that no future item (10..80, or 1..100) could use.
    if post_residual > 0 {
        let dead = (post_residual as f64) / (bin_capacity as f64);
        score += 30.0 * dead * dead * dead;
    }

    // Exact fill is perfect.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: reward if next item fits the post-residual (chain packing).
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 8.0 + 4.0 * (next_item_size as f64) / (post_residual as f64);
    } else if next_item_size > 0 && next_item_size > post_residual {
        // Next item won't fit here anyway; slight penalty for wasting residual.
        score += 3.0 * (post_residual as f64) / (bin_capacity as f64);
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new one.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Many open bins: prefer consolidating into existing bins rather than spreading.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 0.6 * open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Favor bins with residual below the mean (denser bins get preference).
    score += 0.15 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        let poor_fit = if fitting_bins_count == 0 { 0.0 } else {
            (item_size as f64) / (bin_residual as f64)
        };
        // Base cost of a fresh bin, discounted when the item is large (little to lose).
        score += 45.0 - 0.3 * item_size as f64;
        // If open bins exist but fit poorly, opening a new bin becomes relatively better.
        if fitting_bins_count >= 1 {
            score += 20.0 * (1.0 - poor_fit);
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let prn = pr / cap;

    // Base: quadratic waste penalty on post-residual
    let mut score = pr * pr / cap + pr;

    // Smooth non-linear coupling with stream progress:
    // late in the stream, tight fits (small post_residual) matter more
    let tightness = (1.0 - prn).max(0.0);
    score -= 25.0 * tightness * tightness * (0.5 + progress);

    // Reward near-perfect fits with smooth exponential falloff
    score -= 30.0 * (-prn * 12.0).exp();

    // Penalize bins whose post-residual can't fit the lookahead item
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if pr >= nx {
            // reward leaving room for the next item, smoothly scaled
            let slack = (pr - nx) / cap;
            score -= 18.0 * (-slack * 6.0).exp() * (1.0 - progress);
        } else {
            let miss = (nx - pr) / cap;
            score += 20.0 * miss * miss;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 15.0 + 10.0 * progress;
    }

    // Mild penalty for spreading across many open bins relative to mean residual
    score += 0.05 * (open_bins_count as f64) * (prn - mean_residual / cap).abs();

    // New-bin candidate: keep it neutral-slightly-high so it's chosen only
    // when all open bins score poorly (poor fits / dead space)
    if bin_residual == bin_capacity {
        score += 8.0 + 12.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: bins whose leftover falls into
    // "small residue" classes are prized (dead space minimization).
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // capacity fraction left over

    // Reward tight fits: post_residual small relative to capacity
    score -= 30.0 * (1.0 - frac).powi(3);

    // Harmonic (modulo) classes on post_residual: residues 0 and small
    // remainders are reusable by common item sizes; odd/tiny slivers penalized.
    let r = post_residual % 10;
    if post_residual > 0 {
        match r {
            0 => score -= 8.0,   // multiple of 10: highly reusable
            1 | 2 | 3 => score -= 3.0, // near-multiple: decent
            _ => score += 4.0,   // awkward sliver
        }
        // exact zero residual is a perfect fill
        if post_residual == 0 {
            score -= 25.0;
        }
    }

    // Integer-division thresholds: post_residual usable by next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // this bin remains useful for the lookahead item
            score -= 6.0;
            // harmonic pairing: next item exactly divides leftover
            if post_residual % next_item_size.max(1) == 0 && post_residual > 0 {
                score -= 5.0;
            }
        } else {
            // leftover too small for the next item -> dead space risk
            score += (next_item_size - post_residual) as f64 * 0.5;
        }
        // lookahead almost fills current bin's leftover: strong pairing
        if next_item_size <= post_residual && post_residual - next_item_size < 10 {
            score -= 10.0;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new one
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Many open bins: discourage spreading; prefer fuller bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += (open_bins_count as f64).ln().max(0.0) * frac * 5.0;

    // Prefer bins whose residual is close to the mean (keeps balance),
    // unless it's a fresh empty bin.
    if bin_residual < bin_capacity {
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.1;
    } else {
        // New-bin candidate: penalize mildly so it only wins when fits are bad,
        // less so early in the stream or when open bins are numerous.
        score += 12.0 - 6.0 * progress;
        if fitting_bins_count == 0 {
            score -= 20.0; // no open bin fits: must open new bin
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: penalize large post_residual quadratically (wasted space grows superlinearly).
    let pr = post_residual as f64;
    score += 0.004 * pr * pr;

    // Strict dead-space avoidance: post_residual in a "unusable" gap (too small for the
    // smallest plausible item) is pure loss — penalize hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bin pressure: discourage spreading across many bins; favor filling existing ones.
    score += 0.35 * open_bins_count as f64;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when no open bin
    // offers a good fit (bin_residual == bin_capacity marks the new-bin candidate).
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin, reduced when open bins are mostly full
        // (mean_residual low) or many bins are open and fragmented.
        let mean_r = mean_residual.max(0.0);
        let mut new_bin_score = 30.0 + 0.10 * mean_r;
        // If a future item could pair with this item in a fresh bin, slight discount.
        if next_item_size > 0 {
            let pair_gap = 100u32.saturating_sub(item_size + next_item_size);
            new_bin_score += 0.15 * pair_gap as f64;
        }
        // Late in the stream, closing out is cheaper.
        let progress = step_index as f64 / total_items.max(1) as f64;
        new_bin_score -= 8.0 * progress;
        score = score.max(new_bin_score);
        score = new_bin_score;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - slack / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit (post_residual == 0)
    if post_residual == 0 {
        score -= 100.0;
    }

    // 2-step lookahead: reward if next item exactly fills the post residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: reward proportional to how tightly it fits
            score -= 30.0 * (next_item_size as f64 / post_residual as f64);
        } else {
            // next item cannot use the residual: penalize large dead space
            score += 0.5 * (next_item_size as f64 - post_residual as f64);
        }
    }

    // Penalize residuals that are small-but-unusable (dead space below min item size)
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Compare against mean residual: bins tighter than average are good targets
    score -= 0.3 * (mean_residual - post_residual as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize moderately so we prefer good fits into open bins,
    // but allow opening when residual waste would be large.
    if bin_residual == bin_capacity {
        score += 55.0;
        // if the item is large relative to capacity, opening a fresh bin is fine
        score -= 0.2 * item_size as f64;
    }

    // Late in the stream: consolidate, prefer filling existing bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Many open bins: encourage closing them out by filling
    score -= 0.5 * open_bins_count as f64 * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: low post_residual is good, but dead space in (0, item_size) is worst.
    if post_residual > 0 {
        let waste_ratio = post_residual as f64 / item_size as f64;
        score += waste_ratio * 8.0;
        if post_residual < 10 {
            score -= 15.0; // near-perfect fit
        }
    } else {
        score -= 25.0; // perfect fill
    }

    // Lookahead: if next item fits exactly into post_residual, strong reward.
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 30.0;
        } else if gap < 10 {
            score -= 12.0;
        } else {
            score += gap as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly prefer using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Time horizon: early in stream, be conservative (avoid fragmenting); late, pack greedily.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= progress * 6.0 * (post_residual as f64 / bin_capacity as f64);

    // Global state: many open bins with high mean residual -> encourage consolidating into open bins.
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 5.0;
    }

    // New-bin candidate: penalize opening a new bin unless current fit is poor.
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / bin_capacity as f64;
        let poor_fit = (bin_residual - item_size) as f64 > 0.6 * bin_capacity as f64;
        if poor_fit && next_item_size > post_residual {
            score -= 10.0; // opening fresh bin is fine
        } else {
            score += 18.0 + 20.0 * (1.0 - fit_quality);
        }
    }

    // Penalize leaving residuals that no typical item (1..100) can use usefully.
    if post_residual > 0 && post_residual < 5 {
        score += 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let poly = norm_pr * norm_pr * (1.0 + 2.0 * progress) - norm_pr * progress;
    score += 6.0 * poly;

    // Reward tight fits more strongly as stream progresses
    let tightness = 1.0 - norm_pr;
    score -= 4.0 * tightness * tightness * (0.5 + progress);

    // Penalize leaving residual close to but below the next item (dead space)
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if pr < nxt {
            score += 2.5 * (nxt - pr) / cap * (1.0 + progress);
        } else {
            score -= 1.5 * (1.0 - ((pr - nxt) / cap).powi(2)) * 0.5;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 {
        score -= 3.0 + 2.0 * progress;
    }

    // Mild penalty when many bins are open and this fit is loose
    score += 0.05 * open_bins_count as f64 * norm_pr;

    // Coupling with mean residual: prefer bins below mean residual (tighter)
    score += 0.3 * (mean_residual - pr) / cap;

    // New-bin candidate: make it unattractive unless post_residual is perfectly usable
    if bin_residual == bin_capacity {
        score += 8.0 - 3.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity fractions (1/8 granularity). Small classes are "dead space".
    let eighth = bin_capacity / 8;
    let post_class = post_residual / eighth.max(1);
    score += match post_class {
        0 => -12.0,                    // near-perfect fill
        1 => -6.0,                     // excellent
        2 => -2.0,                     // good
        3 => 0.0,
        4 => 1.5,
        5 => 3.0,
        6 => 5.0,
        _ => 8.0,                      // large waste (bin nearly empty used poorly)
    };

    // Exact / tight fit rewards via modulo arithmetic on post_residual.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 3 {
        score -= 10.0;
    } else if post_residual % 10 == 0 {
        // residual is a clean multiple of 10: likely reusable by common sizes
        score -= 4.0;
    } else if post_residual < 10 {
        // tiny unusable sliver: penalize
        score += 4.0;
    }

    // Lookahead coupling: does the next item fit exactly into post_residual?
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 14.0;             // perfect chaining
        } else if next_item_size <= post_residual {
            let slack = (post_residual - next_item_size) as f64;
            if slack <= 5.0 {
                score -= 7.0;          // near-exact chain
            } else {
                score -= 3.0 * (1.0 - slack / cap);
            }
        } else {
            // next item won't fit here: residual becomes stranded
            let gap = (next_item_size - post_residual) as f64;
            if post_residual < 10 {
                score += 3.0;          // stranded sliver before a big item
            }
            score += 0.02 * gap;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // this bin's residual would be badly fragmented anyway.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // penalty proportional to how many bins could already fit the item
        score += 6.0 + 3.0 * (fitting_bins_count as f64);
        // but if item is huge relative to mean residual, opening fresh is fine
        let mean_r = if mean_residual.is_finite() { mean_residual } else { 0.0 };
        if (item_size as f64) > mean_r + 0.5 * cap {
            score -= 4.0;
        }
        // early stream: allow more bins (spreading load helps later)
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 3.0 * (1.0 - progress);
    } else {
        // mild bonus for consolidating into open bins when many are open
        if open_bins_count > 4 {
            score -= 1.0;
        }
        // prefer bins whose residual is close to mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.03 * dev;
    }

    // Harmonic threshold coupling: reward placing items that leave residuals
    // in "friendly" integer-division classes for typical item sizes.
    let friendly = post_residual / 4;
    if friendly >= 2 && friendly <= 20 && post_residual % 4 == 0 {
        score -= 1.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps.
    // A post_residual in [1, 9] is nearly worthless (min item size is 1,
    // but small gaps rarely match future items); treat it as total waste.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }
    // Perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Penalize post_residual that is too small for the lookahead item
    // (dead space relative to known future demand).
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 12.0 + 0.25 * (next_item_size - post_residual) as f64;
    }
    // Reward gaps that can still host the next item.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0;
    }

    // Open-bin pressure: discourage spreading across many open bins
    // unless the fit is good.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of opening a new bin.
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if post_residual < 10 {
            score += 60.0;
        }
    }

    // Mild stream-progression tie-breaker: later in the stream,
    // consolidate more aggressively (favor fuller bins).
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins below mean residual (keeps residuals balanced).
    score += 0.05 * (mean_residual - post_residual as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Reward tight fits: small post_residual relative to capacity.
    let tightness = 1.0 - (post_residual as f64) / cap;
    score -= 30.0 * tightness * tightness;

    // Perfect 2-step lookahead match: post_residual exactly equals next item size.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 40.0 / (1.0 + diff);
        // Penalize leaving residual that next item cannot use (dead space).
        if post_residual < next_item_size {
            score += 8.0 * (post_residual as f64) / cap;
        }
    } else {
        // Last item: prefer minimal waste.
        score += 2.0 * (post_residual as f64) / cap;
    }

    // Penalize bins with residual far below the mean (fragmented bins),
    // unless this is a last-chance fit.
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 10.0 * dev * dev;
    if post_residual > 0 {
        score += 5.0; // general penalty for not filling exactly
    }
    if post_residual == 0 {
        score -= 25.0; // perfect fill
    }

    // Last-chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate handling: only attractive when current item is large
    // and few bins fit it.
    if bin_residual == bin_capacity {
        let item_frac = item_size as f64 / cap;
        let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / (fitting_bins_count as f64) };
        let openness = (step_index as f64) / (total_items.max(1) as f64);
        score = 100.0 - 60.0 * item_frac * fit_pressure - 20.0 * (1.0 - openness);
        // discourage hoarding new bins when many are open
        score += 3.0 * (open_bins_count as f64).sqrt();
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits: small post_residual is good.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fit_ratio;

    // Penalize dead space that is too small for typical future items
    // (post_residual < 10 is nearly unusable waste).
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    }

    // Lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 25.0;
        } else {
            // Penalize creating residuals just below the next item size.
            score += 15.0;
        }
        // Bonus for chains: post_residual fits next item with tight slack.
        if post_residual >= next_item_size && (post_residual - next_item_size) < 10 {
            score -= 20.0;
        }
    } else {
        // Last item: purely minimize waste, any bin that fits is fine.
        score -= 10.0;
    }

    // Last-chance bin: if this is the only bin that can fit the item,
    // strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive
    // when the item is large and current bins are fragmented.
    if bin_residual == bin_capacity {
        // Base penalty for opening a new bin.
        score += 55.0;
        // If item is large, a fresh bin gives flexibility for future items.
        if item_size >= 50 {
            score -= 30.0;
        }
        // If many bins are open with large mean residual, prefer reusing them.
        score += 0.3 * mean_residual;
        // As the stream progresses, avoid bin proliferation.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 40.0 * progress;
        // If few fitting bins exist, opening new bin is less costly.
        if fitting_bins_count <= 1 {
            score -= 45.0;
        }
    }

    // Mild preference for bins with above-average residual when item is small:
    // keep tight bins for tight occasions.
    if item_size <= 30 && bin_residual != bin_capacity {
        let rel = bin_residual as f64 / bin_capacity as f64;
        score += 10.0 * (1.0 - rel);
    }

    // Encourage consolidation when many bins are open.
    if open_bins_count > 8 {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;

    // Base: prefer tight fits (small post_residual), with a mild quadratic
    // penalty on wasted space that strengthens as the stream progresses.
    let base = pr + (pr / cap) * (pr / cap) * cap * (0.3 + 0.9 * progress);

    // Reward filling bins deeply: larger item fraction reduces score.
    let fill_reward = -3.0 * (item_size as f64 / cap) * (1.0 + progress);

    // Penalize opening new bins, more so later in the stream.
    let new_bin_penalty = if bin_residual == bin_capacity {
        12.0 + 25.0 * progress + 0.15 * open_bins_count as f64
    } else {
        0.0
    };

    // Last-chance bin: strongly favor using it to avoid a new bin.
    let last_chance = if fitting_bins_count == 1 && bin_residual != bin_capacity {
        -8.0 * (1.0 + progress)
    } else {
        0.0
    };

    // Lookahead coupling: if the next item fits the post-residual exactly
    // or well, reward leaving that much space.
    let lookahead = if next_item_size > 0 && next_item_size as f64 <= pr {
        -2.5 * (next_item_size as f64 / pr.max(1.0)) * (1.0 - progress)
    } else if next_item_size as f64 > pr {
        1.5 * progress // dead space that can't serve the next item
    } else {
        0.0
    };

    // Deviation from mean residual: prefer bins whose residual is near the mean
    // (keeps residual diversity for future items), softly coupled with progress.
    let mean_coupling = ((pr - mean_residual) / cap).abs() * (2.0 + 4.0 * progress);

    base + fill_reward + new_bin_penalty + last_chance + lookahead + mean_coupling
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits, scaled by capacity fraction.
    let frac = post_residual as f64 / bin_capacity as f64;
    score += 12.0 * frac * frac;

    // Harmonic class of post_residual: residues modulo small integers.
    let r4 = post_residual % 4;
    let r5 = post_residual % 5;
    let r10 = post_residual % 10;
    // Dead-space classes: residuals like 1,2,3 are nearly unusable.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0; // tiny unusable sliver
    } else if post_residual == 0 {
        score -= 30.0; // perfect closure
    } else {
        // reward "usable" residuals that pair with common item sizes (multiples of 5/10)
        if r10 == 0 {
            score -= 8.0;
        } else if r5 == 0 {
            score -= 5.0;
        }
        // penalize awkward residues
        if r4 == 1 || r4 == 3 {
            score += 2.0;
        }
        if r10 == 9 || r10 == 1 {
            score += 3.0;
        }
    }

    // Lookahead coupling: does post_residual fit the next item?
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // exact match is gold
            if post_residual == next_item_size {
                score -= 20.0;
            } else {
                let gap = post_residual - next_item_size;
                // reward closeness of next item to residual
                if gap < 10 {
                    score -= 10.0 - gap as f64 * 0.5;
                } else {
                    score += gap as f64 * 0.15;
                }
            }
        } else {
            // next item cannot use this residual: penalize proportionally
            score += 4.0;
        }
        // harmonic class of next item size (multiples of 10 pair well)
        if next_item_size % 10 == 0 && post_residual >= next_item_size {
            score -= 4.0;
        }
    } else {
        // last item: strongly prefer closing bins
        score -= 15.0;
    }

    // Last-chance bin: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 18.0;
    }

    // New-bin candidate handling: only open a new bin when current fits are bad.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        // neutral-ish baseline; becomes attractive when open bins have bad fits
        score = bin_capacity as f64 * 0.45;
        if fitting_bins_count == 0 {
            score -= 40.0; // must open
        }
        if post_residual >= 50 {
            score -= 10.0; // fresh bin keeps large flexibility
        }
        // open new bin late in stream only if very worthwhile
        let progress = step_index as f64 / (total_items.max(1) as f64);
        if progress > 0.9 {
            score += 5.0;
        }
        // discourage opening when many open bins and mean residual is healthy
        if mean_residual > 30.0 && open_bins_count > 2 {
            score += 15.0;
        }
    } else {
        // mild pressure to consolidate: prefer fuller bins when many are open
        score += open_bins_count as f64 * 0.3;
        // prefer bins whose residual is below the mean (filling the emptiest-ish)
        if (bin_residual as f64) < mean_residual {
            score -= 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_item = 1u32;
    if post_residual > 0 && post_residual < min_item {
        score += 1000.0;
    }
    // Penalize gaps that no plausible future item can use well.
    if post_residual > 0 && post_residual < 20 {
        score += (20 - post_residual) as f64 * 6.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    if item_size > 0 {
        score -= (item_size as f64) * 0.8;
    }
    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Lookahead: if the next item fits exactly in the post residual, reward strongly.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 60.0;
        } else if post_residual < next_item_size && post_residual > 0 {
            score += 15.0; // next item cannot use this bin's remainder
        }
    }

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Open bins pressure: with many open bins, discourage opening new bins
    // and encourage filling existing ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).sqrt() * (1.0 + progress);
    if bin_residual == bin_capacity {
        // New-bin candidate: base cost plus pressure.
        score += 30.0 + pressure * 8.0;
        // But if no open bin fits, new bin must look attractive: it is the
        // only call with residual == capacity, handled implicitly.
    } else {
        // Reward filling already-open bins more when many bins are open.
        score -= pressure * 2.5;
        // Prefer bins with residual below the mean (denser bins).
        if (bin_residual as f64) < mean_residual {
            score -= 8.0;
        } else {
            score += 4.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact/near-exact fits (post_residual near zero).
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score -= (1.0 - fit_ratio).powi(6) * 40.0;

    // 2-step lookahead: if next item fits into post_residual, big bonus.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 15.0;
        let chain_tightness = (post_residual - next_item_size) as f64 / bin_capacity as f64;
        score -= (1.0 - chain_tightness) * 10.0;
    } else if next_item_size > 0 && post_residual < next_item_size {
        // Dead space that next item cannot use: penalize, worse if post_residual small.
        score += (next_item_size as f64 - post_residual as f64) * 0.3;
        if post_residual < 10 {
            score += 8.0; // nearly unusable sliver
        }
    }

    // Compare residual against mean residual: prefer bins tighter than average.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening a new bin, more when good fits exist
    // or early in the stream (packing density matters more later).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 + 10.0 * (1.0 - progress);
        if fitting_bins_count > 0 {
            score += 15.0;
        }
        // Opening a new bin is more attractive if it can chain the next item.
        if next_item_size > 0 && bin_capacity >= item_size + next_item_size {
            score -= 10.0;
        }
    }

    // Mild preference to fill bins with many occupants already open (consolidation).
    if open_bins_count > 0 && bin_residual < bin_capacity {
        score -= (open_bins_count as f64).ln() * 0.5;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Reward tight fits: post_residual near 0 is best.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals that are too small to fit a typical item.
    let min_item = 1.0f64;
    if post_residual > 0 && (post_residual as f64) < min_item {
        score += 50.0;
    }
    // Small-but-unusable residuals are worse than exactly-full bins.
    if post_residual > 0 && post_residual < 5 {
        score += 15.0;
    }

    // Lookahead coupling: if the next item fits exactly in the post residual,
    // strongly favor this bin (chained perfect packing).
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 25.0;
        } else if post_residual >= next_item_size {
            score -= 8.0 * (post_residual as f64 / (post_residual + next_item_size) as f64);
        } else {
            // Next item won't fit here: mild penalty proportional to wasted opportunity.
            score += 4.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Many open bins: encourage consolidation into existing bins.
    let open_pressure = open_bins_count as f64 / (1.0 + progress * 10.0);
    if bin_residual < bin_capacity {
        score -= 2.0 * open_pressure.min(10.0);
    }

    // Mean residual coupling: if this bin's residual is far above the mean,
    // it is a good candidate to absorb the item (keeps bin loads balanced).
    let residual_diff = bin_residual as f64 - mean_residual;
    if bin_residual < bin_capacity {
        score -= 0.05 * residual_diff;
    }

    // New-bin candidate handling: opening a new bin is expensive early and
    // when open bins exist; it becomes more acceptable late in the stream
    // or when many bins are already open anyway (amortized).
    if bin_residual == bin_capacity {
        let new_bin_penalty = 35.0
            - 15.0 * progress
            - (open_bins_count as f64).min(20.0) * 0.5
            + 10.0 * (item_size as f64 / bin_capacity as f64);
        score += new_bin_penalty.max(0.0);
        // A fresh bin wastes capacity if the item is small.
        score += (bin_capacity - item_size) as f64 * 0.15;
    }

    // Slight preference for placing larger items into emptier bins.
    score -= 0.03 * item_size as f64 * (bin_residual as f64 / bin_capacity as f64);

    // Mild noise-free tie-break by bin index proxy: prefer bins with more residual
    // filled (lower residual) when everything else is close.
    score += 0.01 * bin_residual as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Non-linear tightness: reward small post_residual quadratically
    let pr = post_residual as f64;
    let tightness = 1.0 - (pr / bin_capacity as f64);
    score -= 6.0 * tightness * tightness;

    // Smooth polynomial coupling of post_residual with progress:
    // early on, prefer filling bins tightly; later, weight residual waste more heavily
    let progress_poly = progress * progress * (3.0 - 2.0 * progress); // smoothstep
    score += progress_poly * (pr * pr) / (bin_capacity as f64);

    // Penalize residual relative to mean residual across open bins (dead-space pressure)
    score += 0.15 * (pr - mean_residual).abs();

    // Last-chance bonus: strongly favor the only bin that fits
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Lookahead coupling: reward if next item fits in post_residual (smooth reward)
    if next_item_size > 0 {
        let gap = post_residual as i64 - next_item_size as i64;
        if gap >= 0 {
            let fit_quality = 1.0 - (gap as f64 / bin_capacity as f64);
            score -= 8.0 * fit_quality * fit_quality;
        } else {
            // penalize blocking next item, scaled by how badly it misses
            let miss = (-gap) as f64;
            score += 0.05 * miss + 0.0005 * miss * miss;
        }
    }

    // Mild penalty for opening a new bin when other bins fit
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 10.0 + 2.0 * open_bins_count as f64;
    }

    // Slight preference to consolidate when many bins are open
    score += 0.05 * open_bins_count as f64 * (pr / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" the leftover is.
    // Residuals that are multiples of common item sizes (10, 20, 25, 50) are valuable.
    let r = post_residual;
    if r == 0 {
        score -= 30.0; // perfect fit, best outcome
    } else if r % 50 == 0 {
        score -= 12.0;
    } else if r % 25 == 0 {
        score -= 8.0;
    } else if r % 20 == 0 {
        score -= 6.0;
    } else if r % 10 == 0 {
        score -= 4.0;
    } else {
        // awkward leftover: penalize dead space more strongly
        score += 6.0;
    }

    // Small leftovers (< 10, minimum item size) are dead space.
    if r > 0 && r < 10 {
        score += 15.0;
    }

    // Lookahead: if the next item fits exactly into post_residual, reward heavily.
    if next_item_size > 0 {
        if next_item_size == r {
            score -= 25.0;
        } else if next_item_size <= r {
            score -= (r - next_item_size) as f64 * 0.3;
        } else {
            // next item cannot use this bin's remainder: slight penalty
            score += 3.0;
        }
    }

    // Last chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 10.0;
    }

    // Prefer bins with larger residual used (tighter fit relative to residual).
    score += (bin_residual as f64 - item_size as f64) * 0.1;

    // New-bin candidate: keep it attractive only when current bins fit poorly.
    if bin_residual == bin_capacity {
        // baseline cost of opening a new bin
        score += 8.0;
        // but if no existing bin gives a good fit (high post residual), new bin wins
        if post_residual >= 60 {
            score -= 20.0;
        }
        if open_bins_count == 0 {
            score -= 50.0;
        }
    }

    // Mild pressure against proliferating bins over the stream.
    score += open_bins_count as f64 * 0.05;

    // Progress-scaled tightening: later in the stream, prefer tighter packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += mean_residual * 0.05 * (1.0 - progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong dead-space penalty: gaps too small for the smallest plausible item are worthless.
    if post_residual < 10 && post_residual > 0 {
        score += 40.0 + (10 - post_residual) as f64 * 4.0;
    }

    // Reward very tight fits (near-perfect packing).
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual <= 3 {
        score -= 15.0;
    }

    // Favor bins whose residual is close to the item (best-fit style, sharpened).
    let tightness = (bin_residual as f64 - item_size as f64).abs();
    score += tightness * 0.3;

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }
    // Penalize leaving a gap that almost-but-doesn't fit the next item.
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        score += 8.0;
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin (avoid bin proliferation).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Open-bin pressure: when many bins are open, discourage opening another.
    if bin_residual == bin_capacity {
        score += (open_bins_count as f64) * 6.0 + mean_residual * 0.5;
        // Late in the stream, opening new bins is especially costly.
        if total_items > 0 {
            let progress = step_index as f64 / total_items as f64;
            score += progress * 25.0;
        }
        // But if mean residual is tiny, a new bin is fine.
        if mean_residual < 5.0 {
            score -= 20.0;
        }
    }

    // Mild pressure to fill already-open bins as stream progresses.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual) more aggressively than linear.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 18.0 * tightness * tightness;

    // Aggressive 2-step lookahead: reward if next item fits into post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let leftover_after_next = post_residual - next_item_size;
        score -= 22.0 * (1.0 - (leftover_after_next as f64) / (bin_capacity as f64));
    } else if next_item_size > 0 {
        // Penalize leaving a gap the next item cannot use (dead space risk).
        score += 8.0 + 0.15 * (post_residual as f64);
    }

    // Compare post_residual against mean residual of open bins:
    // prefer bins whose residual stays near/below the mean (balanced packing).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin unless item is large
    // and no open bin offers a decent fit.
    if bin_residual == bin_capacity {
        let poor_fit = fitting_bins_count == 0
            || (item_size as f64) / (bin_capacity as f64) < 0.35;
        if poor_fit {
            score -= 10.0;
        } else {
            score += 25.0;
        }
    }

    // Early in stream, be more willing to open fresh bins for large items.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if bin_residual == bin_capacity && item_size >= 60 {
        score -= 6.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let item = item_size as f64;
    let post = post_residual as f64;
    let residual = bin_residual as f64;

    // Base: minimize leftover space after placement.
    let mut score = post;

    // Tight-fit reward: strongly favor near-perfect fills.
    let tightness = 1.0 - (post / cap);
    score -= tightness * tightness * cap * 0.6;

    // Dead-space penalty: leftover space that no future item (>=10, or >=1) can use.
    let min_item = if total_items > 0 && item_size >= 10 { 10.0 } else { 1.0 };
    if post > 0.0 && post < min_item {
        score += cap * 2.0; // unusable sliver
    } else if post > 0.0 && post < 2.0 * min_item {
        score += cap * 0.5; // hard-to-fill small gap
    }

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= cap * 1.5;
    }

    // New-bin candidate handling: opening a fresh bin is only attractive when
    // current bins fit poorly and the item is large relative to capacity.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let fit_quality = item / cap; // large items deserve a fresh bin
        let crowded = (open_bins_count as f64).ln() + 1.0;
        let mean_gap = (mean_residual - item).max(0.0) / cap;
        score += cap * (0.8 + mean_gap * 2.0) - fit_quality * cap * 1.2 + crowded * 5.0;
        // Lookahead: if next item is small, a fresh bin wastes its large residual.
        if next_item_size > 0 {
            let nxt = next_item_size as f64;
            let pair_fill = (item + nxt) / cap;
            if pair_fill <= 1.0 {
                score -= cap * 0.8; // fresh bin could host both items
            } else {
                score += cap * 0.4;
            }
        }
    } else if next_item_size > 0 {
        // Lookahead coupling for existing bins: reward bins whose post-residual
        // exactly accommodates the next item (chained packing).
        let nxt = next_item_size as f64;
        let diff = (post - nxt).abs();
        if diff < min_item {
            score -= cap * 1.0;
        } else {
            score += diff * 0.35;
        }
    }

    // Time horizon: early in the stream, be conservative (keep bins balanced);
    // late in the stream, prioritize immediate compaction.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += (mean_residual - post) * (0.4 - 0.6 * progress);

    // Mild preference to fill bins with larger residuals when many bins are open.
    score -= residual / cap * (open_bins_count as f64).min(10.0) * 2.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let fit_ratio = item_size as f64 / bin_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer minimal post residual, but smooth-saturating so tiny
    // differences near zero matter more than large ones.
    let mut score = (pr * pr) / (pr + 12.0) + 0.35 * pr;

    // Reward high fill ratio (tight fit), smoothly coupled with progress:
    // later in the stream, tight packing matters more.
    score -= 45.0 * fit_ratio * fit_ratio * (1.0 + 0.8 * progress);

    // Penalize waste relative to capacity, non-linearly.
    let waste = 1.0 - (post_residual as f64 / cap);
    score += 30.0 * (1.0 - waste * waste);

    // Lookahead coupling: bonus if next item fits exactly in post_residual,
    // penalty if next item barely doesn't fit (dead space for lookahead).
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx <= pr {
            score -= 18.0 * (nx / pr) * (1.0 - (pr - nx) / cap);
        } else {
            score += 10.0 * ((nx - pr) / cap).min(1.0);
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 20.0 * progress;
    }

    // New-bin candidate: penalize opening a bin unless current bins are
    // quite full or many bins are already open (spread load late).
    if bin_residual == bin_capacity {
        let avg_fill = 1.0 - mean_residual / cap;
        score += 55.0 * (1.0 - avg_fill * avg_fill) - 8.0 * (open_bins_count as f64).ln().max(0.0);
        // Allow opening bins more freely late in the stream.
        score -= 15.0 * progress;
    }

    // Mild penalty for bins far below mean residual (fragmentation pressure).
    score += 0.15 * ((mean_residual - pr).abs() / cap) * (1.0 + progress);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: reward tight fits (small post_residual).
    score -= 12.0 * (1.0 - post_residual as f64 / bin_capacity as f64).powi(3);

    // Harmonic class of post_residual: dead space in (0,10) is unusable for
    // typical items; modulo classes tell us how "wasted" the leftover is.
    let dead = post_residual < 10 && post_residual > 0;
    if dead { score += 25.0; }

    // Perfect closure bonus: exact fill.
    if post_residual == 0 { score -= 30.0; }

    // Modulo-10 harmonic class of post_residual: leftovers divisible by 10
    // align with common item size grids, making them more reusable.
    let class_align = post_residual % 10 == 0;
    if class_align { score -= 6.0; }

    // Lookahead coupling: if next item fits exactly into post_residual,
    // strongly favor this bin (chained perfect fit).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size < post_residual {
            // Reward proportional leftover after the hypothetical chain fill.
            let chain_left = post_residual - next_item_size;
            score -= 10.0 * (1.0 - chain_left as f64 / bin_capacity as f64);
            if chain_left % 10 == 0 { score -= 4.0; }
        } else {
            // Next item cannot follow here: penalize mildly, more if this
            // placement creates awkward odd-class residue.
            score += 5.0;
            if post_residual % 2 == 1 { score += 3.0; }
        }
    }

    // Last-chance bin: if this is the only fitting bin, prefer it over
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // New-bin candidate handling: an empty bin has residual == capacity.
    // Penalize opening a new bin when decent fits exist; scale penalty with
    // how many bins are already open (consolidation pressure).
    if bin_residual == bin_capacity {
        let pressure = open_bins_count as f64;
        score += 18.0 + pressure.min(20.0);
        // But if the item is huge relative to mean residual space, new bin
        // may be warranted: relax penalty.
        if item_size as f64 > mean_residual * 0.9 {
            score -= 22.0;
        }
    }

    // Slight preference for bins below mean residual (use laggard bins first),
    // keeping fuller bins' space for future larger items.
    if (bin_residual as f64) < mean_residual {
        score -= 3.0;
    }

    // Stream progression: late in the stream, be greedier about tight fits.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 5.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    // Integer-division threshold: post_residual in [10, 20) is a sweet spot
    // for mid-size items; mildly reward it.
    if post_residual / 10 == 1 { score -= 2.0; }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small to ever hold a minimum
    // item (size 1) are less costly than gaps that are "almost useful" but
    // unusable for typical items. Penalize the awkward mid-range gaps hardest.
    if post_residual > 0 {
        if post_residual < 10 {
            // Tiny sliver: nearly dead space, mild penalty since it can only
            // hold very small items anyway.
            score += 8.0;
        } else if post_residual <= 20 {
            // Awkward gap: too small for most items but large enough to hurt.
            score += 25.0;
        } else {
            // Usable gap: reward proportionally.
            score -= (post_residual as f64).sqrt() * 3.0;
        }
    }

    // Perfect fit bonus: strongly reward zero waste.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Last-chance pressure: if this is the only fitting bin, avoid forcing
    // open of a new bin unless the fit is decent.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, prefer consolidating into
    // existing ones rather than opening new bins.
    let open_pressure = open_bins_count as f64 * 2.0;
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize more when many bins are already open.
        score += open_pressure;
    } else {
        score -= open_pressure * 0.5;
    }

    // Lookahead coupling: if next item fits into the post residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 20.0;
    }

    // Mean residual coupling: if this bin is much tighter than average,
    // prefer filling it (reduce fragmentation across bins).
    let dev = mean_residual - bin_residual as f64;
    score += dev * 0.3;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: item exactly fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: if the next item exactly fills the post residual,
    // this is a perfect chain placement.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 600.0;
    }

    // Next item fits into the post residual: good lookahead match.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack_after_next = post_residual - next_item_size;
        score -= 150.0 * (slack_after_next as f64 / bin_capacity as f64);
    }

    // Penalize dead space that is too small for typical future items.
    if next_item_size > 0 && post_residual < next_item_size && post_residual > 0 {
        score += 200.0 * (1.0 - post_residual as f64 / next_item_size as f64);
    }

    // Compare residual against the mean residual of open bins:
    // prefer consuming bins with larger-than-average residual (tight bins first).
    if mean_residual > 0.0 {
        score += 0.5 * (post_residual as f64 - mean_residual);
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 250.0;
    }

    // New-bin candidate: penalize opening a new bin unless open bins are crowded.
    if bin_residual == bin_capacity {
        let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
        score += 80.0 + 20.0 * crowding;
    }

    // Early in the stream, be slightly more willing to open bins for structure.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score -= 30.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post-residual) super-linearly.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space: residuals too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // Lookahead: if the next item fits exactly in post_residual, reward heavily.
    if next_item_size > 0 && post_residual >= next_item_size {
        let gap = post_residual - next_item_size;
        if gap == 0 {
            score -= 40.0;
        } else if gap < 10 {
            score -= 20.0;
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item won't fit here; penalize leaving awkward leftover.
        score += 8.0;
    }

    // New-bin candidate handling: only attractive when current bins fit poorly.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let mut new_score = 35.0;
        // Later in the stream, prefer consolidating into existing bins.
        new_score += 40.0 * progress;
        // Many open bins with large mean residual: discourage another bin.
        if mean_residual > item_size as f64 {
            new_score += 15.0;
        }
        // If no open bin can fit except this call context (fitting==1 means one bin fits),
        // opening a new bin is usually wasteful.
        if fitting_bins_count >= 1 {
            new_score += 20.0;
        }
        // Perfect-fit potential: item exactly fills a fresh bin.
        if item_size == bin_capacity {
            new_score -= 100.0;
        } else if item_size > bin_capacity / 2 {
            new_score -= 10.0;
        }
        score = score.min(score) + new_score; // blend: new-bin score dominates baseline
        score = new_score + 5.0; // baseline residual for empty bin is capacity-ish anyway
    }

    // Mild penalty for spreading across too many open bins when mean residual is high.
    if !is_new_bin && mean_residual > 40.0 && post_residual as f64 > mean_residual {
        score += 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;
    let norm_item = item_size as f64 / cap;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let coupling = norm_pr * norm_pr * (1.0 + t) - norm_pr * norm_item * t;
    score += 30.0 * coupling;

    // Reward tight fits more strongly later in the stream
    score -= (1.0 - norm_pr) * (1.0 - norm_pr) * (20.0 + 40.0 * t);

    // Penalize dead space that next item cannot use
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if nx > pr {
            score += (nx - pr) * (0.5 + t);
        } else {
            score -= 0.3 * (1.0 - nx / (pr + 1.0)) * (1.0 + t);
        }
    }

    // Last-chance bin bonus: strongly favor using the only fitting bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 50.0 * t;
    }

    // New-bin candidate: penalize opening new bins early, mildly late
    if bin_residual == bin_capacity {
        score += 15.0 * (1.0 - t) + 2.0 * open_bins_count as f64;
    }

    // Mild preference for bins below mean residual (fill emptier bins first)
    score += 0.1 * (mean_residual - pr);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Fractional capacity logic: treat residual as fraction of capacity
    let frac = post_residual as f64 / bin_capacity as f64;

    // Harmonic class of post_residual: bins whose leftover falls into
    // "small" classes (<=10, <=20) are valuable; penalize mid-range dead zones.
    let class = post_residual / 10;
    match class {
        0 => score -= 30.0,                       // near-perfect fit
        1 => score -= 22.0,                       // very good fit
        2 => score -= 12.0,                       // decent fit
        3 => score -= 4.0,                        // acceptable
        4 | 5 => score += 10.0,                   // dead zone: 40-60 residual
        _ => score += 6.0 + 8.0 * frac,           // large leftover
    }

    // Modulo coupling: if next item could exactly fill the leftover, reward heavily
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if post_residual % next_item_size == 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
        // Penalize if next item almost fits but not quite (fragmentation risk)
        if next_item_size > post_residual && next_item_size - post_residual <= 5 {
            score += 12.0;
        }
        // Reward if next item fits comfortably in the post residual
        if next_item_size <= post_residual {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Many open bins: discourage spreading, prefer tight fills
    if open_bins_count > 4 {
        score += mean_residual * 0.05;
    }

    // New-bin candidate: neutral baseline with mild scaling by stream progress;
    // only wins if all open bins score poorly.
    if bin_residual == bin_capacity {
        score = 55.0 + frac * 20.0 - (step_index as f64 / total_items.max(1) as f64) * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the minimum item
    // (size 1) are pure waste; residuals that cannot fit typical items
    // (e.g. < 10) are heavily penalized as unusable dead space.
    if post_residual == 0 {
        // Perfect fit: strongly reward.
        score -= 1000.0;
    } else if post_residual < 10 {
        // Unusable gap: penalize proportionally to how "dead" it is.
        score += (10 - post_residual) as f64 * 50.0;
    } else {
        // Usable residual: reward tight fits, scaled by gap size.
        score -= (post_residual as f64).sqrt() * 5.0;
    }

    // Penalize leaving a gap that exactly matches the next item poorly:
    if next_item_size > 0 {
        if post_residual == next_item_size {
            // Residual perfectly hosts the lookahead item.
            score -= 300.0;
        } else if post_residual > next_item_size && post_residual - next_item_size < 10 {
            // Would create dead space after hosting next item.
            score += (post_residual - next_item_size) as f64 * 30.0;
        } else if post_residual < next_item_size && post_residual >= 10 {
            // Residual unusable for the known next item: mild penalty.
            score += 40.0;
        }
    }

    // Open-bins pressure: discourage scattering across many bins when
    // alternatives exist; encourage consolidation when few bins are open.
    score += open_bins_count as f64 * 2.0;

    // Last-chance bonus: if this is the only bin that fits, prefer using it
    // over opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 150.0;
    }

    // Mean-residual coupling: prefer bins whose residual deviates from the
    // mean in the direction of a tight fit.
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += dev * 0.5;

    // New-bin candidate: make opening a new bin costly unless nothing fits well.
    if bin_residual == bin_capacity {
        score += 500.0 + open_bins_count as f64 * 10.0;
        // But allow new bin early in the stream to build a diverse pool.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= progress * 100.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Strongly reward exact / near-exact fits (post_residual small).
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize large dead space non-linearly (quadratic waste).
        score += (post_residual as f64) * (post_residual as f64) / (bin_capacity as f64);
    }

    // 2-step lookahead: reward when the next item fits perfectly into post_residual.
    if next_item_size > 0 {
        let next = next_item_size as f64;
        let pr = post_residual as f64;
        if next <= pr {
            let gap = pr - next;
            // Perfect chaining: next item exactly fills the leftover space.
            if gap == 0.0 {
                score -= 150.0;
            } else {
                // Reward proportionally to how close next_item_size is to post_residual.
                score -= 80.0 * (1.0 - gap / pr);
            }
        } else {
            // Next item cannot fit in the leftover: penalize by the overshoot.
            score += 0.5 * (next - pr);
        }
    } else {
        // Last item: prefer minimal leftover.
        score -= 50.0;
    }

    // Relative-to-mean coupling: bins with residual below mean are "tighter";
    // placing there preserves loose bins for awkward future items.
    let mr = if mean_residual.is_finite() { mean_residual } else { bin_capacity as f64 };
    if (post_residual as f64) < mr {
        score -= 0.6 * (mr - post_residual as f64);
    } else {
        score += 0.3 * ((post_residual as f64) - mr);
    }

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 60.0 * (1.0 - progress * 0.5);
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the item fits poorly everywhere else (large item, few open bins).
    if bin_residual == bin_capacity {
        let tight_fit_elsewhere = fitting_bins_count > 0
            && (post_residual as f64) <= 0.25 * (bin_capacity as f64);
        if tight_fit_elsewhere {
            // A fresh bin gives perfect post_residual == capacity - item;
            // reward if item is large (leaves little waste) or many bins open.
            if item_size >= bin_capacity / 2 {
                score -= 40.0;
            } else {
                score += 30.0; // wasteful to open a new bin for a small item
            }
        } else {
            // Default: mildly discourage opening new bins early in the stream.
            score += 20.0 + 40.0 * (1.0 - progress);
        }
    }

    // Mild preference to fill bins that are already partially used heavily.
    score -= 0.1 * (bin_capacity as f64 - bin_residual as f64);

    // Small term coupling open bins count: with many open bins, prefer
    // consolidation (lower post_residual bins) to avoid bin proliferation.
    score += 0.05 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly prefer bins where the item nearly fills the space.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 12.0 * fill_ratio * fill_ratio;

    // Lookahead: if the next item can fit in the post residual, reward leaving room for it.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // The residual remains useful; reward proportional to how well next item fits.
            let next_fit = next_item_size as f64 / post_residual as f64;
            score -= 6.0 * next_fit;
        } else {
            // Residual becomes dead space relative to the known next item; penalize.
            let dead = (post_residual as f64) / bin_capacity as f64;
            score += 8.0 * dead;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Penalize bins whose residual deviates wildly from the mean residual
    // (keeps the pool of open bins homogeneous and reusable).
    let dev = (post_residual as f64 - mean_residual).abs();
    score += 0.05 * dev;

    // Mild pressure to consolidate into fewer bins as the stream progresses.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual < bin_capacity {
        score -= 3.0 * progress;
    }

    // New-bin candidate: opening a new bin is generally wasteful; make it
    // unattractive unless it would beat a very poor fit (large post_residual
    // with no lookahead compatibility). New-bin call has post_residual == capacity.
    if bin_residual == bin_capacity {
        // Base cost of a fresh bin plus mild time discount late in the stream.
        score = bin_capacity as f64 * 0.75 + 5.0 - 2.0 * progress;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // A fresh bin can always host the next item; slight bonus.
            score -= 2.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Base: prefer larger post_residual (better fill), but with diminishing returns.
    let mut score = post;

    // Smooth non-linear penalty on unusable dead space: residuals that are too small
    // to fit typical future items are wasted. Penalize a "danger window" smoothly.
    let dead_zone = (cap * 0.15 - post).max(0.0);
    score += 2.0 * (dead_zone / cap) * (dead_zone / cap) * cap;

    // Reward tight fits (small post_residual) more strongly as the stream progresses,
    // via a smooth coupling term.
    let tightness = 1.0 - post / cap;
    score -= 6.0 * tightness * tightness * (0.5 + progress);

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly
    // (smooth quadratic decay of reward as mismatch grows).
    if next_item_size > 0 {
        let mismatch = (post - next_item_size as f64).abs();
        score -= 4.0 * (1.0 - (mismatch / cap).min(1.0)).powi(3);
    }

    // Last-chance bin: strongly favor using it rather than opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
    }

    // New-bin candidate: penalize opening a new bin, more so late in the stream
    // and when decent fitting bins exist.
    if bin_residual == bin_capacity {
        score += cap * (1.2 + 0.8 * progress);
        if fitting_bins_count > 0 {
            score += 5.0;
        }
    }

    // Slight penalty when this bin's residual deviates from the mean residual,
    // encouraging homogeneity of open bins (smooth quadratic coupling).
    score += 0.5 * ((post - mean_residual) / cap).powi(2) * cap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic class of post_residual: bins whose residual falls into
    // "reusable" classes (small multiples of common item sizes) are favored.
    let pr = post_residual;
    let class_bonus: f64 = if pr == 0 {
        0.0
    } else if pr <= 10 {
        -50.0 // tiny dead space, essentially full
    } else if pr % 10 == 0 {
        -30.0 // residual matches harmonic grid (10s)
    } else if pr % 5 == 0 {
        -15.0
    } else {
        15.0 // awkward residual, penalize
    };
    score += class_bonus;

    // Lookahead coupling: reward residuals that exactly fit the next item,
    // penalize residuals that would strand the next item.
    if next_item_size > 0 {
        if pr == next_item_size {
            score -= 80.0;
        } else if pr >= next_item_size {
            score -= 10.0;
        } else {
            score += 20.0; // next item won't fit here anyway
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 60.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // the current item is large and no open bin is a good host.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        // Penalize proliferation of open bins
        score += 40.0 + 5.0 * open_bins_count as f64;
        // But if the item is huge (>= 2/3 capacity) and few bins fit it,
        // a fresh bin is decent.
        if item_size * 3 >= bin_capacity * 2 && fitting_bins_count <= 2 {
            score -= 70.0;
        }
        // Late in stream, prefer consolidation into open bins.
        if progress > 0.8 {
            score += 30.0;
        }
        // Empty bin has full residual; base term already 100, keep it competitive
        // only when mean residual across open bins is small.
        score -= (mean_residual - pr as f64).max(0.0) * 0.5;
    } else {
        // Prefer bins with residual close to item (tight fit) beyond raw post_residual:
        score += (bin_residual as f64 - item_size as f64 - post_residual as f64).abs() * 0.01;
        // Mild preference for bins below mean residual (filling emptier bins first
        // keeps tight bins for tight items).
        if (bin_residual as f64) < mean_residual {
            score -= 5.0;
        }
    }

    // Slight normalization of the base term for large residuals
    score += (post_residual as f64 / bin_capacity as f64) * 10.0;

    score
}

