    // New-bin candidate logic: prefer opening a new bin only when existing residuals are large
    // (poor fits elsewhere) or when the item is huge relative to capacity.
    if bin_residual == bin_capacity {
        let pressure = mean_residual / bin_capacity as f64;
        let t = step_index as f64 / total_items.max(1) as f64;
        // Opening a fresh bin is penalized normally, but less when open bins are full-ish
