    let mut score = pr * pr / cap;

    // Smooth polynomial coupling with stream progress:
    // early on, tolerate larger residuals (keep bins flexible);
    // later, tighten packing by penalizing residual more.
    let progress_coupling = norm_pr * (1.0 + 3.0 * progress * progress);
    score += progress_coupling * cap * 0.5;

