    // Mild reward for using existing bins when many are open
    score -= (open_bins_count as f64).ln().max(0.0) * 0.5;

    // New-bin candidate: neutral-ish baseline, penalized unless residual is large
    if bin_residual == bin_capacity {
        score += 20.0 - 15.0 * (1.0 - norm_pr) * (1.0 - norm_pr) - 10.0 * progress;
        // opening new bin is good when item is large
        score -= 0.1 * item;
