    if post_residual % 10 == 0 {
        score -= 8.0;
    }
    if item_size % 10 == 0 && post_residual % item_size.max(1) == 0 && post_residual > 0 {
        score -= 6.0;
    }

    // Capacity fraction thresholds: tight fits are valuable
    let fill = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill;

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: only attractive if no decent fit exists
    if bin_residual == bin_capacity {
        // baseline score for opening a new bin
        score = (bin_capacity - item_size) as f64;
        if fitting_bins_count == 0 {
            score -= 30.0; // must open a bin
        } else {
            // discourage opening when open bins can fit, unless fits are terrible
            let worst_fit = mean_residual < item_size as f64 * 1.05;
            if !worst_fit {
