            if next_item_size > 0 && next_item_size + item_size <= bin_capacity {
                score -= 10.0; // new bin can host pair with lookahead
            }
        }
        // late in stream, prefer consolidation into open bins
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 20.0 * progress;
    } else {
        // mild preference for bins with residuals near mean (balance)
        score += 0.15 * (bin_residual as f64 - mean_residual).abs();
    }

    // Slight bonus for many open bins to prefer filling existing ones
    score -= 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
