    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Penalize opening a new bin when many bins already fit the item well.
    if bin_residual == bin_capacity {
        // New-bin candidate: base penalty grows with number of fitting bins.
        score += 25.0 + 8.0 * fitting_bins_count as f64;
        // But if the item is large relative to capacity, a fresh bin is fine.
        score -= 0.2 * item_size as f64;
        // Late in the stream, prefer consolidating into open bins.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 20.0 * progress;
    }

    // Global balance: prefer bins with residual near the mean residual
    // (keeps open bins homogeneous, leaving big bins for big items).
    let dev = (bin_residual as f64 - mean_residual).abs();
    score += 0.08 * dev;

    // Slight preference for bins that are already fairly full (small residual).
    score += 0.05 * bin_residual as f64;

    // Tie-break: prefer bins opened earlier (lower index approximated by count).
    score -= 0.01 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let fit = item_size as f64 / cap;
    let tight = 1.0 - fit;

    // Reward tight fits with a smooth polynomial in fit quality, amplified by stream progress.
    score -= 30.0 * (1.0 - tight * tight) * (0.4 + 0.6 * t);

    // Penalize large post-residual non-linearly (dead space grows super-linearly).
    score += 0.010 * pr * pr / cap;

    // Smooth interaction: small post-residual that can host the lookahead item is valuable.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (pr - next_item_size as f64) / cap;
        score -= 12.0 * (1.0 - slack) * (1.0 - slack) * (1.0 - t);
    }

    // Penalize when this is one of many fitting bins (prefer scarce options) smoothly.
    let fbc = fitting_bins_count as f64;
    score += 6.0 * (fbc / (fbc + 3.0)) * (1.0 - fit);

    // Last-chance bonus: smooth reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 15.0 * (0.5 + 0.5 * t);
    }

    // Mild preference to fill bins with low mean residual (consolidation), smooth coupling.
    score += 0.05 * (mean_residual - pr) * (1.0 - t);

    // New-bin candidate: penalize opening a new bin unless the item is large and stream is early.
    if bin_residual == bin_capacity {
        let early = 1.0 - t;
        score += 10.0 - 18.0 * fit * (0.3 + 0.7 * early);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: quantize leftover space into capacity fractions
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Penalize residuals that fall into "dead" classes: too small to be useful
    let class = (pr as u32 / 10).min(10); // integer division thresholds: 0..10
    let dead_penalty = match class {
        0 => 40.0,               // perfect fit — strongly reward
        1 => 5.0,
        2 | 3 => 12.0,           // awkward slivers
        4 | 5 => 6.0,
        6 | 7 => 2.0,
        _ => 0.0,
    };
    score += dead_penalty;

    // Modulo arithmetic on post_residual: residuals that are multiples of common item
    // granularities are more reusable
    let mod_bonus = if pr > 0 {
        if pr % 10 == 0 { 8.0 }
        else if pr % 5 == 0 { 4.0 }
        else if pr % 20 == 0 { 10.0 }
        else { 0.0 }
    } else { 0.0 };
    score -= mod_bonus;

    // Lookahead: reward if next item fits exactly into the post residual (harmonic pairing)
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size <= post_residual {
            // fraction of next item consumed by this residual
            let fill = post_residual as f64 / next_item_size as f64;
            score -= 6.0 * fill.min(3.0);
        } else {
            // next item cannot use this bin's leftover: mild penalty proportional to overshoot
            score += 3.0 * ((next_item_size - post_residual) as f64 / cap);
        }
    } else {
        // last item: prefer tightest fit
        score -= 5.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all open bins
    // would leave large dead space
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap * 0.95;
        // cheaper to open new bin when many bins are open (spread load) and item is large
        score -= 4.0 * (open_bins_count as f64).ln().max(0.0);
        score -= 10.0 * (item_size as f64 / cap);
        // if current bin would fit poorly anyway, new bin is attractive
        if post_residual < 20 && bin_residual != bin_capacity { score -= 5.0; }
    }

    // Progress-based mild regularization: late in the stream, tighten packing
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 4.0 * progress * (pr / cap);

    // Prefer bins whose residual is below the mean (consolidate emptier space)
    score += 2.0 * ((pr - mean_residual) / cap);

    // Small tie-break toward bins with more residual (keeps big bins available is bad;
    // actually prefer filling fuller bins): invert
    score -= 0.5 * (bin_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: small leftover gaps are hard to reuse.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        // Moderate gap: mildly penalized unless it can fit the lookahead item.
        if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 8.0;
        } else {
            score += 10.0;
        }
    }

    // Perfect fit reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward bins whose residual is well-utilized (tight fill).
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 12.0 * fill;

    // Open-bin pressure: prefer consolidating into existing bins.
    score += (open_bins_count as f64) * 1.5;

    // Last-chance bonus: if this is the only fitting bin, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: make fresh bins attractive only when existing
    // fits are poor (large post_residual) or when the next item needs space.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        let mut new_bin_score = 55.0 + (open_bins_count as f64) * 0.8;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            // Fresh bin preserves full capacity for the lookahead item.
            new_bin_score -= 10.0;
        }
        // Late in the stream, opening new bins is less costly (no need to close them).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        new_bin_score -= 20.0 * progress;
        return new_bin_score;
    }

    // Lookahead coupling: if this placement leaves room exactly for next item, reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 12.0;
    }

    // Slight preference for bins below mean residual (rebalance large gaps).
    score += 0.05 * (bin_residual as f64 - mean_residual);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: perfect fills are ideal.
    if post_residual == 0 {
        score -= 200.0;
    } else {
        // Penalize small unusable dead space (below min item size 1 => none, but tiny gaps are bad).
        let dead = 10.0 - post_residual.min(10) as f64; // gap < 10 is fully dead
        score += dead * 2.0;
    }

    // 2-step lookahead: reward if the next item fits exactly into post_residual.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 60.0 - slack * 0.5;
            if slack == 0.0 {
                score -= 80.0; // exact 2-chain
            }
        } else {
            score += 15.0; // next item won't reuse this bin's remainder
        }
    }

    // Relative-to-mean coupling: bins with residual far below mean are precious; waste them only if tight.
    let res_f = bin_residual as f64;
    if res_f < mean_residual {
        score -= (mean_residual - res_f) * 0.3;
    } else {
        score += (res_f - mean_residual) * 0.1;
    }

    // Last-chance bonus: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: only attractive when no open bin gives a good fit.
    if bin_residual == bin_capacity {
        score = 90.0 + post_residual as f64 * 0.1;
        if fitting_bins_count == 0 {
            score -= 100.0; // nothing fits, must open
        }
    }

    // Late-stream consolidation: fewer bins preferred as stream nears end.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += open_bins_count as f64 * progress * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Progress fraction of the stream.
    let t = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Relative fill of this placement.
    let fill = (bin_capacity - post_residual) as f64 / bin_capacity as f64;

    // Reward tight fits strongly (non-linear).
    score -= 40.0 * fill * fill;

    // Penalize dead space that nothing small could ever use.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0; // nearly unusable sliver
    }
    if post_residual >= 10 && post_residual < 20 {
        score += 6.0;
    }

    // Lookahead coupling: if next item fits exactly in the post residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size < post_residual {
            let slack = (post_residual - next_item_size) as f64;
            score -= 20.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            // next item won't fit here regardless; mild penalty for wasting space
            score += 5.0;
        }
    } else {
        // Last item: only care about closing bins tightly.
        score -= 30.0 * fill;
    }

    // Last-chance bin: strongly prefer using the only fitting bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // Many open bins with high mean residual -> encourage consolidating into fuller bins.
    if open_bins_count > 3 {
        let pressure = (open_bins_count as f64).ln();
        score += pressure * (post_residual as f64 / bin_capacity as f64) * 10.0;
        score -= pressure * fill * 5.0;
    }

    // Early in stream: be more willing to open new bins (keep residuals balanced).
    if t < 0.3 {
        if bin_residual == bin_capacity {
            score -= 10.0;
        }
    } else {
        // Late stream: opening new bins is costly.
        if bin_residual == bin_capacity {
            score += 25.0 * t;
        }
    }

    // New-bin candidate scoring: prefer it when current bin fit is terrible
    // (post_residual small and next item doesn't match) but penalize otherwise.
    if bin_residual == bin_capacity {
        // Fresh bin: score is its full unused capacity minus item, i.e. post_residual.
        // Reward it when mean residual of open bins is fragmented.
        score -= mean_residual * 0.3;
        if fitting_bins_count == 0 {
            score -= 20.0;
        }
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 15.0;
        }
    } else {
        // Existing bin: bonus for reducing mean residual spread.
        let dev = (post_residual as f64 - mean_residual).abs();
        score += 0.2 * dev;
    }

    // Mild preference for bins that are already partially filled.
    score -= (bin_capacity - bin_residual) as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let post = post_residual as f64;

    // Base: prefer tight fits (small post_residual), non-linearly.
    let mut score = post * (1.0 + 0.5 * (post / cap).powi(2));

    // Reward near-perfect fits more aggressively.
    score -= 8.0 * (1.0 - post / cap).powi(6);

    // Dead-space penalty: residual too small for typical future items.
    let small_zone = (post / cap - 0.1).max(0.0) * (0.25 - post / cap).max(0.0);
    score += 6.0 * small_zone.max(0.0);

    // Lookahead coupling: bonus if next item fits the post-residual exactly-ish.
    if next_item_size > 0 && (post_residual as f64) >= next_item_size as f64 {
        let slack = post - next_item_size as f64;
        score -= 5.0 * (1.0 - slack / cap).powi(2);
    } else if next_item_size > 0 {
        // Next item won't fit here: mildly penalize wasting large residuals.
        score += 2.0 * (post / cap);
    }

    // Last-chance bin: strong reward to use it rather than open a new bin.
    if fitting_bins_count == 1 {
        score -= 12.0;
    }

    // New-bin candidate: penalize opening bins, more so early/mid stream.
    if bin_residual == bin_capacity {
        score += 10.0 + 8.0 * (1.0 - progress) + 0.5 * open_bins_count as f64;
    }

    // Slight preference to fill bins with larger residuals relative to mean.
    score += 1.5 * (post - mean_residual) / cap;

    // Smooth progress coupling: tighten packing as stream advances.
    score *= 1.0 + 0.3 * progress * (post / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post-residual: quantize leftover space into
    // capacity fractions (integer division thresholds).
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let class = (post_residual * 10) / bin_capacity; // 0..=10 harmonic class
    let class_bonus: f64 = match class {
        0 => 40.0,               // perfect fit, nearly zero waste
        1 => 30.0,               // tiny leftover (1..10% of capacity)
        2 => 18.0,
        3 => 12.0,
        4 => 6.0,
        5 => 0.0,                // half-full leftover: neutral
        6 => -4.0,
        7 => -8.0,
        8 => -14.0,
        9 => -20.0,
        _ => -26.0,              // bin left almost empty: wasteful placement
    };
    score -= class_bonus;

    // Coupling: post_residual vs. next item size (lookahead k=2).
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= post {
            // Next item fits exactly in the leftover: strongly reward tight chains.
            let snug = (post - nxt).abs();
            score -= 12.0 * (1.0 - snug / cap);
            // Harmonic class of the chain: post mod nxt near zero is ideal.
            let m = post_residual % next_item_size.max(1);
            score -= 6.0 * (1.0 - m as f64 / nxt);
        } else {
            // Leftover too small for next item: penalize dead space unless
            // it is negligible (class 0/1 already rewarded).
            if post_residual > 0 {
                score += 5.0 * (nxt - post) / cap;
            }
        }
    }

    // Last-chance bin: if this is the only fitting bin, avoid forcing a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 {
        score -= 8.0;
    } else if fitting_bins_count > 1 {
        // Competition: prefer bins where the item is a large fraction of residual.
        score += 4.0 * (1.0 - item_size as f64 / bin_residual.max(1) as f64);
    }

    // New-bin candidate (bin_residual == bin_capacity): only attractive when
    // nothing fits well (no open bin fits, or all fits are very loose).
    if bin_residual == bin_capacity {
        let loose_threshold = bin_capacity / 2;
        if fitting_bins_count == 0 || (item_size <= loose_threshold && post_residual > loose_threshold) {
            score -= 15.0; // opening a fresh bin is fine
        } else {
            score += 25.0; // penalize opening new bin when a decent fit exists
        }
    }

    // Progress-aware mild pressure: late in the stream, consolidate more.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= 3.0 * progress * (1.0 - post / cap);

    // Deviation from mean residual: prefer bins whose leftover tracks the mean
    // to keep the open-bin population balanced.
    score += 0.15 * (post - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are rewarded strongly: small post_residual gets nonlinear bonus.
    if post_residual <= 10 {
        score -= 40.0;
    } else if post_residual <= 25 {
        score -= 18.0;
    } else if post_residual <= 45 {
        score -= 6.0;
    }

    // Penalize dead space that is too small to hold typical future items.
    // A gap below ~15 is nearly unusable; a gap of 0 is perfect (waste-free).
    if post_residual > 0 && post_residual < 15 {
        score += 25.0;
    }

    // Reward bins whose residual was already fragmented (low residual being consumed well).
    if bin_residual < 50 {
        score -= 8.0;
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (1.5 + 3.0 * progress);

    // Mean residual coupling: if open bins are already loose, discourage spreading.
    if (mean_residual - post_residual as f64).abs() < 5.0 {
        score -= 4.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Lookahead: if the next item fits in the post residual, bonus; if the
    // next item barely misses, mild penalty for wasting the gap.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 12.0;
        } else if post_residual > 0 && next_item_size - post_residual <= 5 {
            score += 8.0;
        }
    }

    // New-bin candidate: only attractive when current bins fit poorly.
    if bin_residual == bin_capacity {
        // Base cost for opening a new bin.
        score += 55.0;
        // But if no existing bin fits well (large post_residual everywhere implied),
        // a fresh bin is fine: offset when open bins are few.
        if fitting_bins_count == 0 {
            score -= 60.0;
        } else if fitting_bins_count == 1 {
            score -= 20.0;
        }
        score -= progress * 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly prefer post_residual exactly matching the next item size (perfect 2-step chain).
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).unsigned_abs() as f64;
        if diff == 0.0 {
            score -= 60.0;
        } else if diff <= 5.0 {
            score -= 25.0 - diff * 4.0;
        } else {
            // Penalize large gaps between post_residual and next item (dead space risk).
            score += diff * 0.35;
        }
        // If next item cannot fit this bin after placement, penalize mildly.
        if next_item_size > post_residual {
            score += 8.0;
        }
    } else {
        // Last item: just minimize residual.
        score -= 5.0;
    }

    // Relative to mean residual: bins with less residual than average are tighter fits;
    // prefer them slightly to consolidate filling.
    let rel = mean_residual - bin_residual as f64;
    score += rel * 0.4;

    // Last-chance bin: only bin that fits -> strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Penalize creating tiny unusable residuals.
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    }

    // New-bin candidate: default slight penalty so we only open when no good fit exists.
    if bin_residual == bin_capacity {
        score += 12.0;
        // Open a new bin more readily early in the stream or when many bins are open.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 10.0 * (1.0 - progress);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: prefer bins where post_residual is small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 18.0 * tightness;

    // Penalize dead space that cannot fit a typical next item.
    if next_item_size > 0 && post_residual < next_item_size {
        score += 12.0 * (next_item_size as f64 - post_residual as f64);
    }

    // Reward bins that leave room for the lookahead item (chained fit).
    if next_item_size > 0 && post_residual >= next_item_size {
        let chained = (post_residual - next_item_size) as f64;
        score -= 6.0 * (1.0 - chained / bin_capacity as f64);
    }

    // Last-chance bonus: this is the only bin that fits the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when plenty of open bins could fit the item.
    if bin_residual == bin_capacity {
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        let scarcity = 1.0 / (fitting_bins_count as f64 + 1.0);
        score += 30.0 + 25.0 * scarcity + 20.0 * (1.0 - progress) - 0.15 * open_bins_count as f64;
        // If fit is very tight elsewhere, new bin is less attractive.
        if post_residual == 0 && item_size == bin_capacity {
            score -= 40.0;
        }
    }

    // Mild coupling with global mean residual: prefer bins near the mean (keeps balance).
    score += 0.08 * (bin_residual as f64 - mean_residual).abs();

    // Encourage filling bins fully as the stream progresses.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score -= 8.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let prog2 = progress * progress;
    let prog3 = prog2 * progress;
    let coupling = norm_pr * (1.0 + 2.0 * prog2 + 3.0 * prog3);
    score += 4.0 * coupling;

    // Reward near-perfect fits, stronger as stream progresses
    let fit = 1.0 - norm_pr;
    score -= 8.0 * fit * fit * (0.5 + progress);

    // Penalize residuals that are too small to be useful, smoothly
    let min_useful = next_item_size as f64;
    if min_useful > 0.0 && pr < min_useful {
        let gap = (min_useful - pr) / cap;
        score += 6.0 * gap * gap * (1.0 + progress);
    }

    // Lookahead coupling: if next item fits post_residual, reward smoothly
    if next_item_size > 0 && (post_residual as u32) >= next_item_size {
        let ratio = next_item_size as f64 / cap;
        score -= 5.0 * ratio * (1.0 - norm_pr) * (0.5 + prog2);
    }

    // Last-chance bin: reward strongly with smooth saturation
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        let sat = progress / (1.0 + progress);
        score -= 10.0 * (1.0 + sat);
    }

    // New-bin candidate: penalize mildly early, more later unless current fit is bad
    if bin_residual == bin_capacity {
        let base = 3.0 + 6.0 * progress;
        let fit_quality = item_size as f64 / cap;
        score += base * (1.2 - fit_quality);
    }

    // Mean residual alignment: prefer bins whose residual tracks the mean
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score += 2.0 * dev * dev * (0.5 + prog2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: dead space penalty grows for small leftovers
    let pr = post_residual as f64;
    if post_residual > 0 {
        let class = bin_capacity / post_residual.max(1); // integer division threshold
        let dead_penalty = match class {
            0 => 60.0,
            1 => 12.0,   // residual > cap/2, very reusable
            2 => 4.0,
            3 => 2.0,
            4 => 1.0,
            _ => (cap_f / pr) * 0.5,
        };
        score += dead_penalty;
    } else {
        score -= 40.0; // perfect fill
    }

    // Coupling with lookahead item: reward residual that fits next item exactly-ish
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 8.0 - (slack as f64).min(8.0) * 0.5;
        if slack == 0 {
            score -= 15.0; // next item fills perfectly
        }
    } else if next_item_size > post_residual {
        score += 3.0; // next item won't fit here; mild penalty
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize unless current fit is terrible or stream is early
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        let open_pressure = (open_bins_count as f64) * 2.0;
        score += 25.0 + open_pressure - 10.0 * (1.0 - progress);
        if post_residual == bin_capacity {
            // opening a fresh bin leaves full residual; acceptable if mean residual is low
            if mean_residual < cap_f * 0.15 {
                score -= 18.0;
            }
        }
    }

    // Favor bins whose residual is far from mean (better consolidation)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    // Harmonic tie-break on item size class
    let h = (item_size % 10) as f64;
    score += h * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Dead-space penalty: residuals too small for the smallest possible item (1..=6)
    // are effectively wasted capacity.
    if post_residual > 0 && post_residual < 7 {
        score += 25.0;
    }
    // Moderate dead space (7..=12) is also risky for unknown distributions.
    if post_residual >= 7 && post_residual < 13 {
        score += 8.0;
    }

    // Reward perfect or near-perfect fits.
    if post_residual == 0 {
        score -= 15.0;
    } else if post_residual <= 3 {
        score -= 6.0;
    }

    // Lookahead: if the next item fits exactly into the post residual, reward strongly.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 20.0;
    } else if next_item_size > 0 && next_item_size < post_residual {
        // next item fits but leaves another residual; mild penalty proportional to
        // the resulting dead space.
        let nxt = next_item_size as f64;
        let second_residual = post - nxt;
        if second_residual < 7.0 {
            score += 5.0;
        } else {
            score -= 3.0;
        }
    }

    // Last-chance bonus: if this is the only bin that can fit the item, avoid
    // opening a new bin unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 10.0;
        if post_residual >= 0 && item_size as f64 / bin_residual as f64 > 0.7 {
            score -= 5.0; // good fill ratio too
        }
    }

    // Pressure from number of open bins: discourage spreading across many bins.
    score += open_bins_count as f64 * 1.5;

    // Prefer bins whose residual is close to the item (best-fit flavor).
    let tightness = (bin_residual as f64 - item_size as f64) / cap;
    score += tightness * 10.0;

    // Prefer bins below mean residual (emptier bins absorb large items better).
    if (bin_residual as f64) > mean_residual {
        score += 2.0;
    } else {
        score -= 1.0;
    }

    // New-bin candidate handling: opening a new bin is expensive early on but
    // acceptable when many open bins are nearly full.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let avg_fill = 1.0 - mean_residual / cap;
        // Penalize new bins; relax penalty as bins fill up.
        score += 12.0 + 20.0 * (1.0 - avg_fill) - 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit reward: strongly prefer bins where the item fills the bin.
    if post_residual == 0 {
        score -= 1000.0;
    } else {
        // Tightness reward: smaller post_residual is better.
        score -= (bin_capacity as f64 - post_residual as f64) * 0.5;
    }

    // Aggressive 2-step lookahead: reward if next item exactly fits post_residual.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        if slack == 0.0 {
            score -= 500.0; // chain fit: next item perfectly fills leftover
        } else {
            score += slack * 0.3; // mild penalty for imperfect chaining
        }
    } else if next_item_size > post_residual && post_residual > 0 {
        // next item cannot use the leftover: dead-space penalty scaled by leftover size
        score += post_residual as f64 * 0.4;
    }

    // Compare post_residual relative to mean residual across open bins.
    score += (post_residual as f64 - mean_residual) * 0.25;

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 200.0;
    }

    // New-bin candidate handling: penalize opening a new bin unless current bins
    // would leave large unusable space.
    if bin_residual == bin_capacity {
        score += 50.0 + (mean_residual * 0.2);
    }

    // Late in stream, be more conservative: keep bins tighter.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += post_residual as f64 * progress * 0.2;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Core tightness: reward near-perfect fits strongly.
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 2.5 * tightness * tightness * (item_size as f64);

    // Penalize leaving a large, awkward residual (dead space that few items can use).
    if post_residual > 0 {
        let dead = (post_residual as f64) / 100.0;
        score += 3.0 * dead * dead;
    }
    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item fits into the post residual, this bin stays productive.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 4.0 + 0.05 * (next_item_size as f64);
    } else if next_item_size > post_residual {
        // Residual that cannot serve the next item is more likely wasted.
        score += 1.5;
    }

    // Last chance: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate: only attractive when no good fit exists among open bins
    // or open bins are nearly full on average.
    if bin_residual == bin_capacity {
        let desperation = if fitting_bins_count == 0 { 1.0 } else { 0.0 };
        let fullness = 1.0 - (mean_residual / (bin_capacity as f64));
        score += 12.0 - 10.0 * desperation - 8.0 * fullness;
        // Early in the stream, opening fresh bins is cheaper.
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= 3.0 * (1.0 - progress);
        // A fresh bin is better if the current item is large (leaves useful residual).
        score -= 0.05 * (item_size as f64);
    }

    // Mild pressure to consolidate: with many open bins, prefer filling existing ones.
    score += 0.15 * (open_bins_count as f64).ln().max(0.0);

    // Prefer bins whose residual deviates favorably from the fleet mean (fill the emptiest-first
    // among equally tight options to consolidate waste).
    score += 0.3 * ((bin_residual as f64) - mean_residual).abs() * 0.1;

    // Small tie-breaker toward bins that fit snugly relative to item size.
    score += 0.02 * ((bin_residual - item_size) as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer tight fits (low post_residual), with non-linear shaping.
    let mut score = post;

    // Quadratic penalty on large post_residual: dead space becomes worse over time.
    let norm_post = post / cap;
    score += 20.0 * norm_post * norm_post * (0.5 + progress);

    // Cubic coupling: extreme leftover space penalized more as stream progresses.
    score += 8.0 * norm_post.powi(3) * (1.0 + 2.0 * progress);

    // Interaction of post_residual with the next item's size:
    // reward residuals that can still accommodate the lookahead item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let gap = (post - nxt).abs();
        let norm_gap = gap / cap;
        score += 10.0 * norm_gap - 6.0 * (1.0 - norm_gap).powi(2);
        // Bonus if post_residual exactly leaves a usable window for next item.
        if post >= nxt {
            score -= 5.0 * (1.0 - (post - nxt) / cap);
        } else {
            score += 4.0 * (nxt - post) / cap;
        }
    }

    // Smooth coupling with mean residual: bins deviating far from the mean
    // residual are less attractive (keeps residual distribution compact).
    let dev = (post - mean_residual).abs() / cap;
    score += 6.0 * dev * dev;

    // Last-chance bin: strong reward when this is the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 12.0 * (1.0 - norm_post);
    } else if fitting_bins_count > 2 {
        // Many alternatives: slight penalty to encourage consolidation elsewhere.
        score += 2.0 * (fitting_bins_count as f64 - 2.0).ln().max(0.0);
    }

    // Early stream: mildly favor opening/using bins evenly; late stream: punish waste.
    let open_factor = 1.0 / (1.0 + open_bins_count as f64);
    score -= 4.0 * open_factor * (1.0 - progress) * (item_size as f64 / cap);

    // Small smooth tie-breaker toward fuller bins.
    score -= 3.0 * (1.0 - norm_post).powi(2);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Strongly prefer tight fits: post_residual near zero.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    } else if post_residual <= 10 {
        score -= 80.0;
    }

    // Harmonic classes: classify post_residual into residue classes mod 10.
    // Small residues (1..10) are "dead zones" unless they can host a future small item.
    let pr = post_residual as i64;
    let dead = pr > 0 && pr < 10;
    if dead {
        score += 60.0;
        // If lookahead item can use this residue, cancel the penalty.
        if next_item_size > 0 && (next_item_size as i64) <= pr {
            score -= 90.0;
        }
    }

    // Modulo-25 harmonic bands: residuals in [25,50) and [50,75) are "half-class" zones.
    let band = (post_residual / 25) as f64;
    score += band * 15.0;

    // Reward using bins with large residual when item is large (first-fit-decreasing flavor).
    let frac = post_residual as f64 / cap;
    score += frac * frac * 40.0;

    // Last-chance bin: strongly favor to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 120.0;
    }

    // New-bin candidate: penalize slightly unless current fit is terrible.
    if bin_residual == bin_capacity {
        score += 30.0;
        if post_residual as f64 > 0.45 * cap {
            score += 40.0;
        }
        if next_item_size > 0 && post_residual >= next_item_size {
            score -= 20.0;
        }
    }

    // If next item fits in post_residual, reward pairing.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = post_residual - next_item_size;
        score -= 50.0 - (slack as f64).min(50.0);
    }

    // Late in stream, consolidate: prefer already-open bins over new ones.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 50.0 * progress;
    }

    // Mild tie-break toward fewer open bins.
    score += (open_bins_count as f64) * 0.01;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let dead = if post_residual > 0 && post_residual < 10 { 60.0 } else { 0.0 };
    score += dead;

    // Reward tight fits (small post_residual relative to item size).
    let tightness = item_size as f64 / (bin_residual as f64).max(1.0);
    score -= 25.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Open-bins pressure: penalize placements into bins when many bins are open,
    // encouraging consolidation into fewer bins.
    score += 0.35 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Lookahead coupling: if next item fits into post_residual, reward this placement.
    if next_item_size > 0 && next_item_size <= post_residual {
        score -= 15.0;
    }
    // If next item cannot fit post_residual but would fit a fresh bin, penalize leaving a dead gap.
    if next_item_size > post_residual && post_residual < 10 && post_residual > 0 {
        score += 20.0;
    }

    // New-bin candidate handling: opening a new bin should only win when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score = 45.0;
        // Opening a new bin is more attractive when few bins fit the item (poor fits elsewhere).
        if fitting_bins_count <= 1 {
            score -= 25.0;
        }
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 10.0;
        }
        // Late in the stream, prefer consolidation into existing bins.
        score += 20.0 * (step_index as f64 / total_items.max(1) as f64);
        // If mean residual across open bins is large, prefer using existing bins.
        if mean_residual > item_size as f64 {
            score += 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward bins whose post_residual can host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Next item fits exactly-ish: strong reward scaled by tightness of the chain fit.
            let chain_slack = (post_residual - next_item_size) as f64;
            score -= 45.0 - chain_slack.min(40.0);
        } else {
            // Next item won't fit here: penalize proportionally to wasted chain opportunity.
            score += 12.0 + 0.25 * (post_residual as f64);
        }
    } else {
        // Last item: pure tight-fit preference.
        score -= 5.0;
    }

    // Prefer bins that are already well-filled (small residual relative to capacity).
    let fill_ratio = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 20.0 * fill_ratio;

    // Penalize creating dead space far from mean residual (fragmentation risk).
    let dead = post_residual as f64 - mean_residual;
    if dead > 0.0 {
        score += 0.15 * dead;
    }

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Mild pressure to consolidate when many bins are open.
    score += 0.05 * open_bins_count as f64;

    // Slight preference for new-bin opening early vs late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New empty bin: only attractive if the item is large or bins are scarce.
        score -= 10.0 * item_size as f64 / bin_capacity as f64;
        score += 15.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item fills most of the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 18.0 * fit_ratio * fit_ratio;

    // Penalize small leftover slivers that likely become dead space.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    } else if post_residual >= 10 && post_residual < 20 {
        score += 8.0;
    }

    // Lookahead: if the next item fits the post-residual, reward this placement;
    // if next item is large and this bin would be nearly empty anyway, slight penalty.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 10.0;
        } else if next_item_size > bin_residual {
            // next item won't fit here regardless; neutral
        } else {
            score += 6.0;
        }
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer it
    // to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 40.0;
    }

    // Global state: many open bins with high mean residual -> prefer reusing
    // existing bins over opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    if open_bins_count > 2 && mean_residual > item_size as f64 {
        score -= 4.0 * (mean_residual - item_size as f64) / bin_capacity as f64;
    }

    // New-bin candidate handling: an empty bin starts from post_residual == capacity - item.
    // Make it attractive only when no open bin fits well (fit_ratio low here means bad reuse).
    if bin_residual == bin_capacity {
        // Slight time-dependent bias: early in the stream, opening bins is cheap;
        // late in the stream, consolidation matters more.
        score += 3.0 + 10.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 8.0;
        }
    }

    // Mild noise-free diversification via open bin count pressure.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = (step_index as f64 / total_items as f64).clamp(0.0, 1.0);
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with polynomial shaping.
    let mut score = pr * (1.0 + 0.5 * norm_pr * norm_pr);

    // Smooth progress coupling: as stream advances, weight residual waste more heavily.
    score += progress * 20.0 * norm_pr * (1.0 - norm_pr);

    // Lookahead: penalize residuals that cannot fit the next item.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let fits_next = (pr >= nxt) as i32 as f64;
        score -= 8.0 * fits_next * (nxt / cap);
        score += 6.0 * (1.0 - fits_next) * (nxt / cap) * (1.0 - progress);
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0 * (1.0 - norm_pr);
    }

    // Penalize leaving a near-empty but unusable bin when many bins are open.
    let mean_r = mean_residual / cap;
    score += 0.3 * open_bins_count as f64 * (norm_pr - mean_r).abs();

    // New-bin candidate: give it a mild baseline penalty so we prefer existing bins,
    // unless the fit in open bins would be terrible.
    if bin_residual == bin_capacity {
        score += 10.0 + 30.0 * norm_pr;
        if next_item_size > 0 && (next_item_size as f64) <= cap {
            score -= 5.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Tightness reward: heavily favor small post_residual (quadratic).
    let pr = post_residual as f64;
    score -= 2.0 * (1.0 - pr / cap) * (1.0 - pr / cap) * 30.0;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 100.0;
    }

    // Harmonic classes: post_residual in low residue classes is more reusable.
    // Class by integer division thresholds on post_residual.
    let cls = post_residual / 10; // 0..10 classes
    score -= (10 - cls.min(10)) as f64 * 1.5;

    // Lookahead: reward if next item exactly fills the post_residual.
    if next_item_size > 0 && post_residual > 0 {
        if next_item_size == post_residual {
            score -= 80.0;
        } else if next_item_size <= post_residual {
            // next item fits: penalize leftover dead space after that.
            let after = post_residual - next_item_size;
            score += after as f64 * 0.3;
        } else {
            // next item cannot use this residual: penalize proportionally.
            score += (next_item_size as f64 / cap) * 15.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate: penalize opening a new bin unless it's early
    // or the item is large relative to capacity and fits poorly elsewhere.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let mut pen = 60.0;
        if item_size >= 50 {
            pen -= 15.0;
        }
        if fitting_bins_count == 0 {
            pen = -1000.0; // no alternative
        }
        if next_item_size > 0 && next_item_size >= item_size && progress < 0.3 {
            pen -= 20.0; // early stream: keep flexibility for big items
        }
        score += pen;
    }

    // Slight preference for bins below mean residual (consolidate slack).
    score += (mean_residual - bin_residual as f64) * 0.05;

    // Mild pressure to use open bins when many are open.
    score += (open_bins_count as f64).ln().max(0.0) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize unusable small gaps hard.
    // A residual that is too small for the smallest plausible item (1) is fine,
    // but tiny-but-nonzero residuals that fit nothing typical are wasted space.
    let pr = post_residual;
    if pr > 0 && pr < 10 {
        // Dead space in the classic 10..80 regime; still mildly penalize in 1..100.
        score += 60.0;
    } else if pr >= 10 && pr < 20 {
        // Risky gap: only very small items fit; heavy penalty.
        score += 35.0;
    } else if pr < 40 {
        // Medium gap: moderately useful.
        score += 10.0;
    } else {
        // Large residual: desirable, reward.
        score -= 15.0;
    }

    // Perfect fit bonus.
    if pr == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward this placement.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= 8.0;
        } else {
            // Next item won't fit here; the gap becomes dead space for the lookahead.
            score += 12.0;
        }
    }

    // Open-bins pressure: with many open bins, prefer consolidating into existing
    // bins (especially tight fits) rather than spreading out.
    let pressure = open_bins_count as f64;
    score += 0.8 * pressure * (post_residual as f64 / bin_capacity as f64);

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Mean residual coupling: if this bin's post-residual is far below the mean,
    // it is a tight, efficient fill; reward it.
    score -= 0.5 * (mean_residual - post_residual as f64);

    // New-bin candidate handling: an empty bin has post_residual == bin_capacity.
    // It should only win when no open bin offers a decent fit, i.e. when all
    // alternatives have bad scores. Add a mild bias so open bins with reasonable
    // fits beat the empty bin, but keep it winnable for large items.
    if bin_residual == bin_capacity {
        score += 5.0 + 1.5 * pressure;
    }

    // Late-stream tightening: as the stream progresses, be more tolerant of
    // imperfect fits to close out bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * progress * (1.0 - post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward exact/near-exact matches with next item
    if next_item_size > 0 && next_item_size <= post_residual {
        let gap = (post_residual - next_item_size) as f64;
        // Perfect 2-chain: post_residual exactly equals next item size
        if gap < 0.5 {
            score -= 60.0;
        } else {
            // Reward proportionally tighter matches (post_residual consumed by next item)
            let fill = next_item_size as f64 / post_residual as f64;
            score -= 40.0 * fill * fill;
        }
    } else if next_item_size > 0 {
        // Next item cannot fit here: penalize leaving a dead space trap
        let waste = (post_residual as f64) * (next_item_size as f64 / bin_capacity as f64);
        score += 15.0 + 0.25 * waste;
    }

    // Penalize residuals relative to mean residual (avoid leaving atypically small fragments)
    if (post_residual as f64) < mean_residual * 0.6 {
        score += 8.0;
    }

    // Last-chance bin: strongly favor using the only bin that fits
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 50.0;
    }

    // Prefer tight fits overall
    score -= 30.0 * (1.0 - post_residual as f64 / bin_capacity as f64);

    // New-bin candidate: keep it neutral-ish; only attractive when existing bins fit poorly
    if bin_residual == bin_capacity {
        score += 10.0 + 0.1 * open_bins_count as f64;
    }

    // Late in stream: tighten packing, avoid opening bins
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post-residual)
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= 12.0 * fit_ratio * fit_ratio;

    // Penalize very small post-residual that is likely dead space unless exact fit
    if post_residual > 0 && post_residual < 10 {
        score += 15.0;
    } else if post_residual == 0 {
        score -= 20.0; // perfect fill
    }

    // Dead space penalty relative to mean residual
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Lookahead: penalize if post-residual can't fit next item
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else {
            score += 4.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // New-bin candidate handling: only attractive when open bins fit poorly
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let poor_fit_penalty = (bin_residual - item_size) as f64 / bin_capacity as f64;
        // Base new-bin score: slightly above a decent fit, below a bad one
        score = 60.0 + 40.0 * poor_fit_penalty - 20.0 * progress;
        if next_item_size > 0 && next_item_size >= item_size {
            score -= 10.0; // empty bin good for chaining large items
        }
        if fitting_bins_count <= 1 {
            score -= 30.0; // no real alternative, opening is fine
        }
    }

    // Mild penalty for too many open bins
    score += 0.3 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let norm_pr = pr / cap;

    // Non-linear polynomial coupling of post_residual with stream progress
    let base = pr * (1.0 + 0.35 * progress * progress);
    let poly = norm_pr * norm_pr * (1.0 - progress) * 40.0
        + norm_pr * progress * 15.0;

    // Reward tight fits (small post_residual), scaled non-linearly
    let tight_bonus = -(1.0 - norm_pr).powi(3) * 20.0;

    // Penalize dead space that likely can't be used (relative to mean residual)
    let dead = if pr > mean_residual { (pr - mean_residual) * 0.15 } else { 0.0 };

    // Last-chance bin bonus
    let last_chance = if fitting_bins_count == 1 { -30.0 } else { 0.0 };

    // Lookahead coupling: reward if next item fits in post_residual
    let lookahead = if next_item_size > 0 && (next_item_size as f64) <= pr {
        -10.0 * (1.0 - (next_item_size as f64 / pr))
    } else if next_item_size > 0 {
        5.0
    } else {
        0.0
    };

    // New-bin candidate: mild penalty so it's chosen only when fits are poor
    let new_bin = if bin_residual == bin_capacity {
        pr + 25.0 * (1.0 - progress) + open_bins_count as f64 * 0.5
    } else {
        0.0
    };

    base + poly + tight_bonus + dead + last_chance + lookahead + new_bin
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: reward residuals that are "usable slots"
    // for common small item sizes (1..=20). Residuals divisible into clean
    // classes are more likely to be filled later.
    let pr = post_residual as i64;
    let next = next_item_size as i64;

    // Reward when next item fits exactly into post_residual (perfect chaining).
    if next > 0 && next <= pr {
        score -= 30.0 + 0.5 * next as f64;
        if pr == next {
            score -= 40.0; // exact fill: zero waste
        }
    } else if next > pr && next > 0 {
        // Next item cannot use this bin's leftover: penalize dead space mildly.
        score += 8.0;
    }

    // Modulo classes: residuals that are multiples of common denominators
    // (10, 20, 25, 50) are "harmonic" and easier to pack later.
    let harmonic = (pr % 10 == 0) as f64 * 6.0
        + (pr % 25 == 0) as f64 * 4.0
        + (pr % 20 == 0) as f64 * 3.0
        + (pr % 50 == 0) as f64 * 5.0;
    score -= harmonic;

    // Penalize awkward mid-range residuals (hard to fill).
    if pr > 0 && pr < 10 {
        score += 25.0; // nearly dead space
    } else if pr >= 10 && pr <= 20 {
        score += 5.0;
    } else if pr > 60 {
        score += (pr - 60) as f64 * 0.3; // too roomy: wasteful placement
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // New-bin candidate handling: only prefer opening a new bin when the
    // current bin would leave a large awkward residual and many bins exist.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let crowding = open_bins_count as f64 / (1.0 + mean_residual.max(1.0));
        // Default: new bin is worse than a decent fit.
        score += 45.0
            - 20.0 * progress
            - 10.0 * crowding.min(2.0);
        if pr == 0 {
            score -= 60.0; // item exactly fills a bin: perfect, prefer new bin
        }
    }

    // Tight fit bonus: residual just above item size means efficient packing.
    let tightness = (bin_residual - item_size) as f64 / bin_capacity as f64;
    score -= 15.0 * (1.0 - tightness);

    // Late in stream: consolidate aggressively.
    if total_items > 0 && step_index * 2 >= total_items {
        score -= 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly.
    if post_residual == 0 {
        score -= 50.0;
    } else {
        // Strict dead-space avoidance: penalize small unusable gaps.
        if post_residual < 10 {
            score += (10 - post_residual) as f64 * 8.0; // tiny gap < min item size is dead space
        }
        // Smooth preference for small residuals (best-fit core), superlinear.
        score += (post_residual as f64 / bin_capacity as f64).powf(2.0) * 20.0;
    }

    // Reward bins whose residual after placement can still host the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 {
            score += 4.0; // leftover too small for the known next item
        }
    }

    // Last-chance pressure: if this is the only fitting bin, strongly favor using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few bins,
    // opening a new one is cheap so don't over-penalize the empty-bin candidate.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = (open_bins_count as f64).ln().max(0.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: attractive early or when mean residual of open bins is small,
        // penalized when open bins already have plenty of room.
        score = 45.0 + pressure * 3.0 + mean_residual * 0.3 - progress * 10.0;
        if fitting_bins_count == 1 {
            score += 20.0; // don't open a new bin when exactly one bin fits
        }
    } else {
        // Mild penalty for bins far below mean residual (fragmented bins).
        if (bin_residual as f64) < mean_residual * 0.5 {
            score += 3.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor bins where the item nearly fills the residual.
    let fit_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * fit_ratio * fit_ratio;

    // 2-step lookahead: reward when next item exactly matches post_residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect chain: bin fully consumed by next item
        } else if next_item_size <= post_residual {
            let chain_waste = post_residual - next_item_size;
            score -= 25.0 * (1.0 - chain_waste as f64 / bin_capacity as f64);
        } else {
            // next item won't fit: residual becomes potential dead space
            score += 8.0 * (next_item_size - post_residual) as f64 / bin_capacity as f64;
        }
    }

    // Compare against mean residual: placing into a bin with residual near the mean
    // balances open bins; avoid leaving a bin far below mean residual.
    let mean_gap = (bin_residual as f64 - mean_residual).abs();
    score += 0.15 * mean_gap;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate (empty bin): penalize opening new bins unless the fit is bad.
    if bin_residual == bin_capacity {
        score += 45.0;
        // Allow new bin if it would leave a large unusable residual in existing bins
        if fit_ratio < 0.35 {
            score -= 50.0;
        }
        // Later in the stream, slightly discourage bin proliferation
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 10.0 * progress;
    }

    // Mild penalty for many open bins to encourage consolidation.
    score += 0.5 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64) / (bin_capacity as f64);
    score -= 45.0 * tightness * tightness;

    // Penalize dead space that cannot fit the next item (lookahead coupling).
    if next_item_size > 0 {
        if post_residual < next_item_size {
            score += 18.0 * ((next_item_size - post_residual) as f64);
        } else {
            // Reward bins that can still host the next item.
            score -= 6.0;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Penalize opening a new bin when good open alternatives exist.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        score += 25.0 + 8.0 * (fitting_bins_count as f64);
    }

    // Global state: many open bins with large mean residual -> prefer reusing existing space.
    if mean_residual > (item_size as f64) {
        score -= 5.0 * (mean_residual / bin_capacity as f64);
    }
    score += 0.6 * (open_bins_count as f64);

    // Time horizon: later in the stream, be more conservative (prefer filling existing bins).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Slight preference for bins with residual close to item size (best-fit flavor).
    let exact_gap = (bin_residual as f64 - item_size as f64).abs();
    score += 0.15 * exact_gap;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    let pr = post_residual as f64 / bin_capacity as f64;
    let progress = step_index as f64 / total_items as f64;
    let fit_pressure = if fitting_bins_count == 0 { 1.0 } else { 1.0 / fitting_bins_count as f64 };

    // Smooth non-linear coupling: dead-space penalty grows quadratically with
    // small residuals, modulated by stream progress.
    score += 12.0 * (1.0 - pr) * pr * pr * (0.5 + progress);

    // Reward tight fits more strongly as the stream advances.
    score -= 20.0 * (1.0 - pr) * (1.0 - pr) * (0.3 + 0.7 * progress);

    // Last-chance bin bonus (smooth via fit pressure).
    score -= 15.0 * fit_pressure * (1.0 - pr);

    // Lookahead: reward residuals that can still host the next item.
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let usable = (pr * bin_capacity as f64 - nx).max(0.0) / bin_capacity as f64;
        score -= 8.0 * usable * (1.0 - progress);
    }

    // Slight penalty when bin residual deviates from mean residual (balance).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more strongly when many bins fit.
    if bin_residual == bin_capacity {
        score += 5.0 + 3.0 * fitting_bins_count as f64 - 4.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: residues mod 10 / 20 create discrete tiers
    let pr = post_residual as u32;
    let residue = pr % 10;
    let tier = pr / 20; // integer division thresholds: 0..5

    // Penalize "awkward" residuals: small odd remainders are hard to fill later
    let awkward = match residue {
        0 => 0.0,
        1..=3 => 6.0,
        4..=6 => 3.0,
        _ => 1.5,
    };
    score += awkward;

    // Reward perfect fits and harmonic residuals (multiples of 10/20)
    if pr == 0 {
        score -= 25.0;
    } else if residue == 0 {
        score -= 8.0 - tier as f64;
    }

    // Coupling with next item: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 30.0;
        } else if next_item_size < pr {
            let slack = pr - next_item_size;
            let slack_res = slack % 10;
            score -= 12.0 - (slack_res as f64) * 0.8 - (slack / 20) as f64 * 1.5;
        } else {
            // next item won't fit here: mild penalty scaled by wasted fraction
            let waste = (next_item_size - pr) as f64 / cap;
            score += 10.0 * waste;
        }
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // New-bin candidate: penalize opening a bin unless current fit is poor
    if bin_residual == bin_capacity {
        let fit_quality = post_residual as f64 / cap;
        let pressure = open_bins_count as f64 / (1.0 + mean_residual / cap);
        // prefer new bin when existing bins would leave very tight fits
        score += 55.0 - 30.0 * fit_quality - pressure.min(15.0);
        if next_item_size > 0 && next_item_size <= pr {
            score -= 10.0; // fresh bin pairs well with next item
        }
    }

    // Tightness reward: smaller post_residual fraction is generally better
    score += 5.0 * (post_residual as f64 / cap);

    // Progression term: late in stream, consolidate harder
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 4.0 * progress * (1.0 - post_residual as f64 / cap);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that can hold nothing else are pure waste.
    // Assume typical minimum item footprint; treat gaps below a threshold as dead.
    let dead_threshold = 20u32;
    if post_residual > 0 && post_residual < dead_threshold {
        score += 45.0; // unusable sliver -> heavy penalty
    }

    // Perfect or near-perfect fit is highly desirable.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into the post residual,
    // strongly favor this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack = (post_residual - next_item_size) as f64;
        score -= 25.0 * (1.0 - slack / bin_capacity as f64);
    } else if next_item_size > post_residual && post_residual > 0 {
        // Next item cannot use what remains -> residual likely becomes dead space.
        score += 12.0;
    }

    // Open-bin pressure: with many bins open, prefer consolidation into existing bins
    // rather than opening new ones.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 / (1.0 + mean_residual / 50.0);
    score += 0.35 * pressure * (0.5 + progress);

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is terrible.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 18.0;
    }

    // New-bin candidate (empty bin): penalize so it is chosen only when no open bin
    // offers a decent fit.
    if bin_residual == bin_capacity {
        score += 30.0 + 0.5 * open_bins_count as f64;
        // But if the item is large relative to mean residual, opening fresh may help.
        if (item_size as f64) > mean_residual + 15.0 {
            score -= 40.0;
        }
    }

    // Mild reward for tightening toward the mean residual (balance avoidance of
    // fragmentation).
    let dev = (post_residual as f64 - mean_residual).abs();
    score -= 0.05 * (bin_capacity as f64 - dev);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let mut score = post_residual as f64;

    // Strong reward for perfect 2-step lookahead match: next item exactly fills this bin.
    if next_item_size > 0 && post_residual as u32 == next_item_size {
        score -= 40.0;
    }

    // Reward near-matches: small gap between post_residual and next item.
    if next_item_size > 0 && post_residual > next_item_size {
        let gap = (post_residual - next_item_size) as f64;
        score -= 20.0 * (1.0 - gap / cap).max(0.0);
    }

    // Penalize if next item cannot use the leftover space (dead space risk).
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = (next_item_size as f64 - post_residual as f64) / cap;
        score += 15.0 * dead;
    }

    // Mild penalty for deviating from the mean residual (prefer balanced fills).
    score += 0.15 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: strongly favor using it before opening a new bin.
    if fitting_bins_count == 1 {
        score -= 18.0;
    }

    // New-bin candidate: penalize opening a fresh bin when other bins fit,
    // unless the empty bin offers a better lookahead pairing.
    if bin_residual == bin_capacity {
        let mut new_bin_bonus = 0.0;
        if next_item_size > 0 && post_residual as u32 >= next_item_size {
            new_bin_bonus = 12.0;
        }
        score += 30.0 - 8.0 * progress - new_bin_bonus;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: scale by fraction of bin consumed.
    let fit_ratio = item_size as f64 / bin_residual as f64;
    score -= fit_ratio * bin_capacity as f64 * 0.6;

    // Penalize large dead space nonlinearly (small residuals are most valuable).
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0;
    } else if post_residual >= 10 && post_residual < 25 {
        score += 3.0;
    } else if post_residual >= 25 {
        score += (post_residual as f64 - 20.0).powf(1.15) * 0.35;
    }

    // Perfect fit is gold.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Lookahead coupling: if next item fits in the post residual, this placement chains nicely.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if next_item_size <= post_residual {
            score -= 8.0 + (nxt / post_residual as f64) * 10.0;
        } else {
            // Wasted potential if post residual can't hold next item.
            score += (post_residual as f64 / bin_capacity as f64) * 6.0;
        }
        // If next item is big and this bin is a poor fit, prefer conserving this bin's residual.
        if nxt > post_residual as f64 && fit_ratio < 0.7 {
            score += 2.0;
        }
    }

    // Last chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0 + (item_size as f64 / bin_residual as f64) * 20.0;
    }

    // New-bin candidate: prefer it only when no open bin fits well.
    if bin_residual == bin_capacity {
        // Baseline cost of a fresh bin.
        score = bin_capacity as f64 * 0.55;
        if fitting_bins_count == 0 {
            score -= 40.0; // no alternative
        } else if fitting_bins_count == 1 {
            score += 25.0; // there is a last-chance open bin, avoid opening new
        }
        // Early in the stream, opening bins is cheaper (more future items to fill them).
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= (1.0 - progress) * 12.0;
        // If mean residual across open bins is large, prefer packing into existing bins.
        score += (mean_residual / bin_capacity as f64).max(0.0) * 10.0;
    }

    // Global pressure: many open bins -> prefer consolidating into existing bins.
    if bin_residual < bin_capacity {
        score += (open_bins_count as f64).ln().max(0.0) * 2.0;
        // Deviation from mean residual: prefer bins with residual close to item need.
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;

    // Base: prefer small post-residual with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * pr / cap) - 0.3 * (pr / cap) * (pr / cap) * cap;

    // Reward when the lookahead item fits the post-residual (chained fit)
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        if post_residual >= next_item_size {
            score -= 8.0 + 10.0 * nx / cap;
        } else {
            // penalize residual too small OR too large for the next item
            let gap = (nx - pr).abs() / cap;
            score += 4.0 * gap * (1.0 + progress);
        }
    }

    // Last-chance bin: strongly reward using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 12.0;
    }

    // Penalize opening a new bin when decent open bins exist (unless residual is perfect fit)
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let tightness = (pr / cap).powi(2);
        score += 6.0 + 4.0 * (1.0 - tightness) + 0.05 * open_bins_count as f64;
        // early stream: opening bins is fine; late stream: prefer filling
        score += 8.0 * (1.0 - progress);
    } else {
        // smooth coupling with mean residual: prefer bins near the mean (balanced filling)
        let dev = (pr - mean_residual).abs();
        score += 0.15 * dev;
        // late stream: reward tight packing more aggressively
        score -= 6.0 * progress * (1.0 - pr / cap);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap_f = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: modulo classes on capacity
    let post_class = (post_residual % 10) as f64;
    score += post_class * 0.35;

    // Integer-division thresholds: reward residuals that partition capacity cleanly
    let q = post_residual / 10;
    if q == 0 {
        score -= 40.0; // near-perfect fill
    } else if q <= 2 {
        score -= 15.0;
    } else if q >= 6 {
        score += 12.0; // large dead space penalty on top of raw residual
    }

    // Reward small post_residual that exactly matches next item size (perfect chaining)
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 45.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.5;
        } else {
            score += (next_item_size - post_residual) as f64 * 0.3;
        }
        // modulo coupling: next item in same harmonic class as post residual
        if next_item_size % 10 == post_residual % 10 && post_residual >= next_item_size {
            score -= 8.0;
        }
    }

    // Last-chance bin: strong reward to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: penalize unless current bins are badly fragmented
    if bin_residual == bin_capacity {
        let fragmentation = mean_residual / cap_f;
        if fragmentation < 0.25 || fitting_bins_count == 0 {
            score -= 25.0;
        } else {
            score += 35.0 + fragmentation * 20.0;
        }
    }

    // Progress-aware scaling: tighten packing as stream advances
    let progress = step_index as f64 / total_items.max(1) as f64;
    score *= 1.0 + 0.3 * progress;

    // Mean-residual deviation coupling
    score -= (mean_residual - post_residual as f64).abs() * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead space avoidance: heavily penalize small unusable gaps.
    // A gap is "unusable" if it is smaller than the smallest plausible item
    // and cannot even hold the lookahead item. Scale penalty sharply.
    if post_residual > 0 && post_residual < 10 {
        score += (10 - post_residual) as f64 * 8.0;
    }
    if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size as f64 {
        score += (next_item_size as f64 - post_residual) * 6.0;
    }

    // Reward tight fits: post_residual near 0 is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Perfect fit detection: residual exactly consumed relative to capacity.
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += fit_ratio * fit_ratio * 20.0;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 25.0;
    }

    // Open-bin pressure: with many open bins, discourage opening new ones
    // and prefer consolidating into existing bins.
    let pressure = open_bins_count as f64 / (open_bins_count as f64 + 4.0);
    if bin_residual == bin_capacity {
        // New-bin candidate: penalize proportional to pressure.
        score += 30.0 * pressure;
        // But if no existing bin fits well (post_residual large), allow it.
        if post_residual == bin_capacity as u32 - item_size.min(&bin_capacity) {
            score -= 15.0 * (1.0 - pressure);
        }
    } else {
        score -= 10.0 * pressure;
    }

    // Prefer bins whose residual is close to mean residual (balance),
    // slightly favoring below-mean bins to consolidate.
    score += (bin_residual as f64 - mean_residual) * 0.3;

    // Lookahead coupling: if next item fits exactly in post_residual, reward.
    if next_item_size > 0 && (post_residual as u32) == next_item_size {
        score -= 20.0;
    }

    // Mild progression term: early in stream, be more conservative about
    // spreading items; later, allow more freedom.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Aggressive 2-step lookahead: reward when post_residual exactly matches next item.
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        // Perfect match for the next item is a strong reward.
        if diff < 0.5 {
            score -= 40.0 + next_item_size as f64;
        } else {
            // Penalize leftover that is too small to ever be useful (< min item size 1..10).
            if post_residual < 10 && post_residual > 0 {
                score += 30.0;
            }
            // Reward leftovers close to the next item size (soft match).
            score -= 20.0 * (1.0 - diff / bin_capacity as f64);
        }
    } else {
        // Last item: pure waste minimization.
        score = post_residual as f64;
    }

    // Compare post_residual relative to mean residual across open bins.
    score -= 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly favor using the only bin that fits, to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when decent existing fits exist.
    if bin_residual == bin_capacity {
        score += 15.0 + 0.1 * open_bins_count as f64;
        // New bin is attractive only if the item would leave a large useful residual
        // and no existing bin fits well (post_residual large means item small).
        if post_residual < 20 {
            score -= 10.0;
        }
    }

    // Slight preference for tighter fits overall (non-linear coupling).
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 5.0 * tightness;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins where the item fills most of the residual.
    let fill_ratio = item_size as f64 / bin_residual.max(1) as f64;
    score -= 40.0 * fill_ratio * fill_ratio;

    // Penalize leaving small, hard-to-use slivers (dead space).
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Lookahead: reward if next item fits exactly in the post residual (perfect chain).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0;
        } else if next_item_size <= post_residual {
            let nfrac = next_item_size as f64 / post_residual as f64;
            score -= 15.0 * nfrac;
        } else {
            // Next item won't fit here; penalize residuals too small for typical items.
            score += 8.0 * (1.0 - post_residual as f64 / bin_capacity as f64);
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 {
        score -= 30.0;
    }

    // Prefer bins with residuals below the mean residual (consolidate emptier space elsewhere).
    score += 0.4 * (mean_residual - bin_residual as f64);

    // Time horizon: as the stream progresses, be more conservative about residual quality.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 10.0 * progress * (post_residual as f64 / bin_capacity as f64);

    // Many open bins: encourage filling existing ones rather than spreading.
    score += 0.15 * open_bins_count as f64 * (post_residual as f64 / bin_capacity as f64);

    // New-bin candidate handling: opening a new bin is only attractive when no good fit exists.
    if bin_residual == bin_capacity {
        // Base cost of opening a new bin.
        score += 45.0;
        // Cheaper to open a bin early in the stream (future items can use fresh space).
        score -= 35.0 * (1.0 - progress);
        // If very few bins fit, opening fresh space is more reasonable.
        score -= 6.0 * (fitting_bins_count as f64);
        // If the current item is large, a fresh bin guarantees a clean high residual.
        if item_size > bin_capacity / 2 {
            score -= 12.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Normalized stream progress in [0,1]
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Fraction of the bin consumed by this placement
    let fill = item_size as f64 / bin_capacity as f64;
    let post_frac = post_residual as f64 / bin_capacity as f64;

    // Non-linear dead-space penalty: quadratic in leftover space, amplified
    // as the stream progresses (late waste is more costly to recover from).
    let dead_space = (post_frac * post_frac) * (1.0 + 2.0 * progress) * 40.0;
    score += dead_space;

    // Reward tight fits (small post_residual relative to capacity) with a
    // smooth saturating term: exp decay of post_frac.
    score -= (1.0 - (-post_frac * 8.0).exp()) * 15.0;

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // strongly reward; if it nearly fits (within 10), mild reward; otherwise
    // penalize wasted potential proportionally to the gap.
    if next_item_size > 0 {
        let gap = post_residual as f64 - next_item_size as f64;
        if gap >= 0.0 {
            score -= (1.0 - (-gap / 10.0).exp()) * 12.0;
        } else {
            score += (-gap) * (0.05 + 0.15 * progress);
        }
    }

    // Last-chance bonus: if this is the only fitting bin, heavily penalize
    // opening a new bin instead (score of new-bin candidate stays at base).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 * (0.5 + 0.5 * progress);
    }

    // Penalize spreading across too many open bins when mean residual is
    // already low (fragmentation pressure), smooth in open_bins_count.
    let frag = (open_bins_count as f64).ln1p() * mean_residual / bin_capacity as f64;
    score += frag * 3.0;

    // Mild global progress tilt: later in the stream, prefer consolidating
    // into existing bins rather than opening new ones.
    if bin_residual == bin_capacity {
        score += 5.0 + 20.0 * progress * progress;
    } else {
        score -= 2.0 * progress * fill;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Base: prefer tight fits via quadratic penalty on wasted space fraction
    let waste_frac = post_residual as f64 / bin_capacity as f64;
    score += 8.0 * waste_frac * waste_frac;

    // Harmonic classes: classify post_residual into residue classes mod 10
    // and mod 4 (common small-item sizes). Residuals in "friendly" classes
    // (divisible by 5 or 10) are more reusable by future items.
    let pr = post_residual as i64;
    let mod10 = pr % 10;
    let mod5 = pr % 5;
    let mod4 = pr % 4;
    if mod10 == 0 {
        score -= 6.0; // perfectly harmonic residual
    } else if mod5 == 0 {
        score -= 3.0;
    } else if mod4 == 0 {
        score -= 1.5;
    }
    // Penalize "dead zone" residuals: too small to fit typical items (1..100 unknown,
    // but small leftovers under ~10 are nearly useless).
    if post_residual < 10 {
        score += 12.0;
    } else if post_residual < 20 {
        score += 4.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 20.0;
        } else if next_item_size <= post_residual {
            score -= 4.0;
            // harmonic match: next_item and post_residual share class
            if (post_residual % next_item_size.max(1)) == 0 {
                score -= 3.0;
            }
        } else {
            // next item won't fit here; slight penalty scaled by how close it is
            let gap = (next_item_size - post_residual) as f64;
            score += (gap / bin_capacity as f64) * 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening new
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate handling: opening a new bin should be discouraged unless
    // current fit is terrible. Empty-bin call has post_residual == capacity.
    if bin_residual == bin_capacity {
        score += 25.0; // default cost of a new bin
        // but if item is huge relative to capacity, new bin is fine
        if item_size * 2 >= bin_capacity {
            score -= 10.0;
        }
        // late in stream with many open bins, prefer consolidation less strongly
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 5.0 * progress;
    }

    // Mean-residual coupling: if this bin's residual is far below mean, its space
    // is scarce; using it is good (subtract). If far above mean, penalize mildly.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Many open bins: reward placements that reduce fragmentation (low post_residual)
    if open_bins_count > 4 {
        score += 0.02 * (post_residual as f64) * (open_bins_count as f64).ln();
    }

    // Small modulo-classes bonus on item itself: items near capacity fractions
    let half = bin_capacity / 2;
    let quarter = bin_capacity / 4;
    if item_size == half || item_size == bin_capacity {
        score -= 2.0; // canonical sizes pair well
    } else if item_size == quarter || item_size == 3 * quarter {
        score -= 1.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fits are strongly preferred: post_residual == 0 is perfect.
    if post_residual == 0 {
        score -= 50.0;
    } else if post_residual <= 10 {
        // Unusable dead space: heavy penalty, worse the smaller the gap.
        score += (11.0 - post_residual as f64) * 8.0;
    }

    // Bonus if the leftover could still fit a typical future item (>= 10).
    if post_residual >= 10 {
        score -= 6.0;
    }

    // Lookahead: reward if next item fits the post residual exactly-ish.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 30.0;
        } else if next_item_size <= post_residual {
            score -= 10.0;
        } else {
            // Next item won't fit here: slight penalty for stranding space.
            score += 4.0;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing ones
    // rather than opening new bins (which would be the empty-bin candidate).
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    score += open_bins_count as f64 * (0.5 + 0.5 * progress);

    // Last-chance bin: strongly prefer using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: make it attractive only when existing bins would
    // waste a lot (mean residual already large) or few bins are open.
    if bin_residual == bin_capacity {
        let waste_pressure = mean_residual - post_residual as f64;
        score -= 20.0 + waste_pressure.max(0.0) * 0.5;
    } else {
        // Prefer bins whose residual is close to the item (best-fit flavor).
        let tightness = (bin_residual - item_size) as f64;
        score += tightness * 0.2;
        // Deviation from mean residual: prefer below-mean bins (fuller bins).
        score += (mean_residual - bin_residual as f64).max(0.0) * -0.1;
        score += (bin_residual as f64 - mean_residual).max(0.0) * 0.1;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong base preference for tight fits
    let fit_ratio = post_residual as f64 / bin_capacity as f64;
    score += 30.0 * fit_ratio;

    // 2-step lookahead: reward if next item exactly fills the post-residual
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 200.0; // perfect chaining: bin closed by next item
        } else if next_item_size <= post_residual {
            let chain_waste = (post_residual - next_item_size) as f64;
            score -= 120.0 * (1.0 - chain_waste / bin_capacity as f64);
        } else {
            // next item cannot chain here: penalize dead space it would leave
            score += 25.0 + 0.3 * (next_item_size - post_residual) as f64;
        }
    }

    // Relative to mean residual: prefer bins tighter than average
    score += 0.8 * (mean_residual - post_residual as f64);

    // Last-chance bin: avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // New-bin candidate: penalize unless current bin would leave bad dead space
    if bin_residual == bin_capacity {
        score += 55.0;
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 20.0 * (1.0 - (item_size as f64 + next_item_size as f64) / bin_capacity as f64);
        }
    }

    // Early in stream: slightly favor opening fresh bins to build structure
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 10.0 * (1.0 - progress) * (fit_ratio - 0.5);

    // Many open bins: discourage spreading, prefer consolidation
    score += 2.0 * open_bins_count as f64 * fit_ratio;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits strongly (small post_residual relative to capacity).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Penalize dead space that is too small for typical future items.
    if post_residual > 0 && post_residual < 10 {
        score += 25.0;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 20.0;
    }

    // Lookahead: if the next item can fit into post_residual, reward this placement.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 8.0 + 0.1 * next_item_size as f64;
        } else {
            // Next item won't fit here; mild penalty proportional to wasted potential.
            score += 3.0;
        }
    }

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 15.0;
    }

    // Crowding penalty: when many bins are open, prefer filling existing ones
    // over opening new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let crowding = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.5 * crowding * (1.0 - progress);

    // New-bin candidate handling: an empty bin is penalized unless the fit here
    // is bad or open bins are nearly full.
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - item_size as f64).max(0.0);
        score += 18.0 - 0.3 * mean_gap;
        if mean_residual < item_size as f64 {
            score -= 30.0; // no open bin is a good fit -> open new bin
        }
    } else {
        // Reward placing into bins whose residual is close to the item size.
        let fit_gap = (bin_residual - item_size) as f64;
        score -= 6.0 * (1.0 - fit_gap / bin_capacity as f64);
    }

    // Mild time-horizon scaling: later in the stream, consolidation matters more.
    score *= 1.0 + 0.3 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = step_index as f64 / total_items.max(1) as f64;
    let fit_norm = pr / cap;

    // Base: penalize post_residual with a smooth non-linear (quadratic) coupling
    let mut score = pr + 40.0 * fit_norm * fit_norm * cap;

    // Stream-progress coupling: later in stream, dead space matters more
    let prog_term = 1.0 + progress * progress;
    score *= prog_term;

    // Reward tight fits: subtract when post_residual is small relative to item
    let tightness = item_size as f64 / bin_residual.max(1) as f64;
    score -= 30.0 * tightness * tightness;

    // Last-chance bonus: strongly favor the only fitting bin
    if fitting_bins_count == 1 {
        score -= 60.0;
    }

    // Lookahead: if next item fits the post residual, reward this placement
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 15.0;
    } else if next_item_size > 0 {
        // penalize if next item nearly fits but not quite (dead space risk)
        let gap = pr - next_item_size as f64;
        if gap > 0.0 && gap < 10.0 {
            score += 10.0 * (1.0 - gap / 10.0);
        }
    }

    // Mean-residual coupling: prefer bins deviating from the mean (consolidation)
    let dev = (bin_residual as f64 - mean_residual) / cap;
    score -= 20.0 * dev;

    // New-bin candidate handling: mildly discourage opening new bins early,
    // more acceptable late in the stream
    if bin_residual == bin_capacity {
        score += 25.0 * (1.0 - progress) + pr;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Harmonic classes of post_residual: classify leftover space into
    // capacity-fraction buckets. Small classes (0..=10) are near-perfect fits.
    let pr = post_residual;
    let class: u32 = if pr == 0 { 0 } else if pr <= 10 { 1 }
        else if pr <= 20 { 2 } else if pr <= 33 { 3 }
        else if pr <= 50 { 4 } else if pr <= 66 { 5 }
        else { 6 };

    // Reward tight fits strongly (subtract), penalize wasteful classes.
    let class_bonus: f64 = match class {
        0 => -60.0,               // perfect fill
        1 => -40.0,               // near-perfect: dead space almost unusable anyway
        2 => -15.0,
        3 => 5.0,
        4 => 15.0,
        5 => 25.0,
        _ => 35.0,                // huge leftover: wasteful placement
    };
    score += class_bonus;

    // Exact modulo arithmetic: leftover that matches common small item sizes
    // (harmonic residue classes 10,20,25,33,50) is still reusable.
    let reusable = pr != 0 && (pr % 10 == 0 || pr % 25 == 0 || pr % 33 == 0 || pr % 50 == 0);
    if reusable { score -= 12.0; }

    // If next item fits exactly in post_residual, big reward (chain fit).
    if next_item_size > 0 {
        if next_item_size == pr {
            score -= 55.0;
        } else if next_item_size <= pr {
            let slack = (pr - next_item_size) as f64;
            score -= 25.0 * (1.0 - slack / cap).max(0.0);
        } else {
            // next item cannot use this leftover: mild penalty proportional to gap
            score += 6.0 * ((next_item_size - pr) as f64 / cap).min(1.0);
        }
    }

    // Last-chance bin: if this is the only bin that fits, avoid opening a new bin
    // unless the fit is truly terrible (class >= 5).
    if fitting_bins_count == 1 && class <= 4 {
        score -= 30.0;
    } else if fitting_bins_count == 1 && class >= 5 {
        score += 20.0; // poor fit on last chance -> prefer new bin
    }

    // New-bin candidate handling: empty bin has large post_residual.
    if bin_residual == bin_capacity {
        // Opening a new bin is attractive early in the stream or when open bins
        // are mostly full (low mean residual means poor future capacity).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        let new_bin_score = 45.0
            - 25.0 * (mean_residual / cap).max(0.0).min(1.0)   // open bins have room -> don't open
            - 15.0 * (1.0 - progress);
        // Compare implicitly: return a score that competes with open bins.
        // If open bins fit well they will score below this; keep new bin moderately costly.
        score = new_bin_score + (item_size as f64) * 0.1;
        if next_item_size > 0 && next_item_size <= pr {
            score -= 10.0; // fresh bin can host the next item too
        }
        return score;
    }

    // Prefer filling bins with larger residual among equals (consolidation):
    score += (bin_residual as f64) * 0.05;

    // Slight preference for balancing across many open bins late in stream.
    if open_bins_count > 8 {
        score += (open_bins_count as f64) * 0.3;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    let min_useful = 10u32;
    if post_residual > 0 && post_residual < min_useful {
        score += 40.0 + 2.0 * (min_useful - post_residual) as f64;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = (item_size as f64) / (bin_residual.max(1) as f64);
    score -= 6.0 * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Lookahead: if next item fits exactly into post_residual, big reward.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size > post_residual {
            // next item won't fit here; penalize leaving a gap that wastes capacity
            score += 0.15 * (post_residual as f64);
        } else {
            score -= 0.05 * (post_residual - next_item_size) as f64;
        }
    }

    // Open-bin pressure: with many open bins, prefer filling existing bins
    // over opening new ones (raise new-bin score implicitly by lowering this).
    score -= 0.8 * open_bins_count as f64;

    // Last-chance bin: strongly favor using the only bin that fits.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 20.0;
    }

    // Mean residual coupling: prefer bins with residual below mean when mean is high
    // (consolidate space), i.e. penalize bins that deviate upward.
    score += 0.3 * ((bin_residual as f64) - mean_residual);

    // New-bin candidate: make empty bins moderately attractive only when
    // the item is large relative to capacity or no good fits exist.
    if bin_residual == bin_capacity {
        let size_ratio = item_size as f64 / bin_capacity as f64;
        score += 12.0 - 10.0 * size_ratio;
        if fitting_bins_count == 0 {
            score -= 50.0; // must open a new bin
        }
    }

    // Late-stream consolidation: as the stream progresses, avoid spreading.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 4.0 * progress * (post_residual as f64) / bin_capacity as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect 2-step match: post_residual exactly equals next item -> strong reward
    if next_item_size > 0 {
        let diff = (post_residual as i64 - next_item_size as i64).abs() as f64;
        score -= 30.0 * (1.0 - diff / bin_capacity as f64);

        // Penalize dead space that cannot hold the next item but is small enough to be wasted
        if post_residual < next_item_size && post_residual > 0 {
            score += 25.0 * (1.0 - post_residual as f64 / next_item_size as f64);
        }
    } else {
        // Last item: prefer tightest fit
        score += 0.0;
    }

    // Reward bins whose residual was already tight (efficient packing)
    let tightness = 1.0 - bin_residual as f64 / bin_capacity as f64;
    score -= 10.0 * tightness;

    // Deviation from mean residual: prefer bins below mean residual (already used)
    score -= 3.0 * (mean_residual - post_residual as f64) / bin_capacity as f64;

    // Last-chance bin: strong bonus to avoid opening a new bin unnecessarily
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: make it attractive only when no open bin fits well
    if bin_residual == bin_capacity {
        // Base penalty so open bins win when they fit decently
        score += 20.0;
        // But if the item is large relative to capacity, opening fresh is fine
        score -= 10.0 * (item_size as f64 / bin_capacity as f64);
        // If many bins are open and this is early in the stream, spreading is okay
        if open_bins_count > 5 {
            score -= 5.0;
        }
        // If next item is huge, keeping a fresh bin around helps
        if next_item_size >= bin_capacity / 2 {
            score -= 8.0;
        }
    }

    // Mild stream-progression pressure: later in stream, favor closing bins tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += 5.0 * progress * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight-fit reward: strongly favor placements that leave little dead space.
    let tightness = post_residual as f64 / bin_capacity as f64;
    score += 18.0 * tightness * tightness;

    // Perfect-fit bonus.
    if post_residual == 0 {
        score -= 60.0;
    } else if post_residual < 10 {
        score -= 25.0;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // New-bin candidate handling: opening a new bin is only attractive when
    // no open bin fits well (large post_residual everywhere) and there are
    // already many open bins with scattered residuals.
    if bin_residual == bin_capacity {
        // Base cost of a new bin, modulated by global fragmentation.
        score += 55.0;
        let frag = (mean_residual - post_residual as f64).abs();
        score -= 30.0 * (frag / bin_capacity as f64).min(1.0);
        // Later in the stream, prefer consolidation into open bins.
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score += 25.0 * progress;
        // If the next item would fit nicely in a fresh bin, mild bonus.
        if next_item_size > 0 && next_item_size <= post_residual {
            score -= 8.0;
        }
    } else {
        // Placing into an existing bin reduces open-bin pressure slightly.
        score -= 2.0 / (open_bins_count as f64 + 1.0);
    }

    // Lookahead: penalize leaving a residual that fits the next item poorly
    // but not exactly — dead space the next item cannot use.
    if next_item_size > 0 && post_residual > 0 {
        if post_residual < next_item_size {
            // Residual too small for next item: mostly dead space.
            score += 6.0 * (post_residual as f64 / next_item_size as f64);
        } else {
            let next_waste = post_residual - next_item_size;
            score += 4.0 * (next_waste as f64 / bin_capacity as f64);
        }
    }

    // Discourage spreading across many nearly-full bins when a good
    // consolidation exists: compare bin residual to mean residual.
    let dev = bin_residual as f64 - mean_residual;
    score += 0.05 * dev;

    // Mild nonlinearity on fill ratio to break ties toward fuller bins.
    let fill = (bin_capacity - bin_residual) as f64 / bin_capacity as f64;
    score -= 10.0 * fill * fill;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let mut score = post_residual as f64;

    // Smooth non-linear coupling of post_residual with normalized stream progress.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;

    // Later in the stream: dead space becomes more costly (quartic ramp).
    let progress_weight = 0.5 + 1.5 * progress * progress * progress * progress;
    score += progress_weight * (pr * pr) / cap;

    // Reward tight fits: post_residual near zero gets a smooth quadratic discount.
    let tightness = 1.0 - pr / cap;
    score -= 8.0 * tightness * tightness * (1.0 - progress * 0.5);

    // Last-chance bin: strongly favor using it (smooth, scaled by fit scarcity).
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0 + 15.0 * progress;
    }

    // Lookahead coupling: if the next item fits the post-residual, reward this placement.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        if nxt <= pr {
            let slack_after_next = pr - nxt;
            let fit_quality = 1.0 - slack_after_next / cap;
            score -= 6.0 * fit_quality * fit_quality;
        } else {
            // Next item cannot use this bin's remainder: penalize large leftovers smoothly.
            let waste = (pr - nxt).max(0.0) / cap;
            score += 3.0 * waste * waste;
        }
    }

    // Penalize bins whose residual deviates strongly from the mean residual (imbalance),
    // smoothly scaled with open bins count.
    let dev = (pr - mean_residual).abs();
    score += (open_bins_count as f64).ln().max(0.0) * dev / cap;

    // New-bin candidate: keep it neutral-to-slightly-attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        // Attractive early (cheap to open), unattractive late (prefer consolidating).
        score = 40.0 + 60.0 * progress + 0.5 * (item_size as f64);
        // If item is small relative to capacity, opening a bin wastes space potential.
        score += 10.0 * (1.0 - item_size as f64 / cap);
        if fitting_bins_count == 1 {
            score -= 30.0; // still allow opening if it's the only option
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residuals divisible by large divisors
    // (e.g. 50, 25, 20, 10) are more reusable by future items.
    let r = post_residual;
    let mut bonus = 0.0;
    if r % 50 == 0 { bonus += 12.0; }
    else if r % 25 == 0 { bonus += 8.0; }
    else if r % 20 == 0 { bonus += 6.0; }
    else if r % 10 == 0 { bonus += 4.0; }
    else if r % 5 == 0 { bonus += 2.0; }

    // Harmonic class of next_item_size: if the lookahead item divides into
    // the post residual evenly, this placement sets up a perfect follow-up.
    if next_item_size > 0 && r >= next_item_size {
        if r % next_item_size == 0 {
            bonus += 15.0;
        } else {
            let slack = (r % next_item_size) as f64;
            bonus += 6.0 * (1.0 - slack / next_item_size as f64);
        }
    } else if next_item_size > r && next_item_size > 0 {
        // Lookahead won't fit here regardless; slight reward for tight fit now.
        bonus += 3.0;
    }

    // Penalize very small dead space that is hard to fill (below typical item sizes).
    if r > 0 && r < 10 {
        score += 20.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // New-bin candidate: penalize opening a new bin early in the stream,
    // reward it late when open bins are fragmented.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 - 25.0 * progress;
        if open_bins_count == 0 { score -= 30.0; }
    }

    // Prefer bins whose residual deviates favorably from the mean (tighter bins first).
    score -= (mean_residual - bin_residual as f64) * 0.15;

    // Mild tightness term: quadratic in post residual to prefer fuller packing.
    score += 0.02 * (post_residual as f64) * (post_residual as f64) / bin_capacity as f64;

    score -= bonus;
    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Penalize dead space that is too small to be reusable later.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0;
    } else if post_residual < 20 {
        score += 12.0;
    }

    // Reward tight fits (small post_residual relative to item size).
    let tightness = post_residual as f64 / (item_size.max(1) as f64);
    score -= 8.0 / (1.0 + tightness);

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Pressure from number of open bins: discourage spreading when many bins open.
    score += 1.5 * open_bins_count as f64;

    // Lookahead: reward leaving room for the next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0;
        } else if post_residual > 0 && post_residual < next_item_size {
            score += 5.0;
        }
    }

    // New-bin candidate: penalize slightly unless open bins are crowded or fit is bad,
    // so a fresh bin is chosen only when placements would create large dead space.
    if bin_residual == bin_capacity {
        let bad_fit_pressure = if fitting_bins_count == 0 { 0.0 } else { 10.0 + 2.0 * open_bins_count as f64 };
        score += bad_fit_pressure;
        // Opening a new bin is attractive when existing residuals are small/fragmented.
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 12.0;
        }
    }

    // Mild progression scaling: later in the stream, be more conservative with new bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 1.0 + 0.1 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual).
    score -= 2.0 * (bin_capacity as f64 - post_residual as f64).ln().max(0.0);

    // Aggressive 2-step lookahead: if the next item exactly fills post_residual,
    // heavily reward this bin.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 100.0;
    }
    // If next item fits into post_residual, mild reward proportional to fill.
    else if next_item_size > 0 && next_item_size < post_residual {
        score -= 0.5 * next_item_size as f64;
    }
    // If next item cannot fit into post_residual, penalize wasted space.
    else if next_item_size > 0 && next_item_size > post_residual {
        score += 0.3 * (post_residual as f64 - mean_residual).abs();
    }

    // Penalize deviation of post_residual from the mean residual of open bins
    // (prefer balanced residuals unless lookahead rewards dominate).
    score += 0.05 * (post_residual as f64 - mean_residual).abs();

    // Last-chance bin: if this is the only bin that fits, strongly favor it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate: penalize opening a new bin unless the current item
    // is large and residuals across bins are already low (poor fits elsewhere).
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / total_items.max(1) as f64;
        let residuals_low = mean_residual < 0.25 * bin_capacity as f64;
        let large_item = item_size > 60;
        if !(residuals_low && large_item) {
            score += 40.0 + 20.0 * progress;
        }
        // Even in the favored case, new bins must beat exact-lookahead matches.
        score += 10.0;
    }

    // Slight penalty for leaving awkward small residuals (10..=20) that
    // few future items can use.
    if post_residual >= 10 && post_residual <= 20 {
        score += 8.0;
    }

    // Prefer consolidating into fewer bins when many are open.
    score += 0.1 * open_bins_count as f64;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: post_residual small relative to capacity.
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 12.0 * tightness * tightness;

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 25.0;
    } else if post_residual < 10 {
        score -= 10.0;
    }

    // Penalize small unusable dead space that no future item (>=1) can still use well.
    if post_residual > 0 && post_residual < 20 {
        score += 8.0 * (20.0 - post_residual as f64) / 20.0;
    }

    // Lookahead: if next item fits exactly in the post-residual, reward strongly.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let chain_fit = (post_residual - next_item_size) as f64;
            score -= 15.0 * (1.0 - chain_fit / bin_capacity as f64);
        } else {
            // Next item cannot follow here; penalize proportionally to how close it was.
            let gap = (next_item_size - post_residual) as f64;
            score += 5.0 * (gap / 100.0).min(1.0);
        }
        // If next item would perfectly chain, extra reward.
        if next_item_size == post_residual && post_residual > 0 {
            score -= 12.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 20.0;
    }

    // Global state: many open bins with large mean residual -> prefer filling existing bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let bin_pressure = open_bins_count as f64 / (1.0 + mean_residual / 10.0);
    score += 0.05 * bin_pressure * (1.0 - progress);

    // Penalize placing into bins with residual far above item size when alternatives exist.
    let slack = (bin_residual - item_size) as f64;
    score += 0.1 * slack * (1.0 - tightness);

    // Time horizon: late in the stream, consolidation matters more.
    score -= 10.0 * progress * tightness;

    // New-bin candidate handling: only prefer a fresh bin when current fit is terrible
    // and there is meaningful lookahead demand that no open bin serves.
    if bin_residual == bin_capacity && bin_capacity == 100 {
        score += 30.0; // default penalty: prefer existing bins
        if fitting_bins_count == 0 {
            score -= 60.0; // no alternative: new bin is fine
        } else if post_residual as f64 > mean_residual + 40.0 {
            score -= 15.0; // existing fits are bad, fresh bin competitive
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };

    // Non-linear polynomial coupling of post_residual with stream progress
    let mut score = pr * (1.0 + 0.6 * progress * progress);

    // Reward tight fits (small post_residual) more strongly as stream progresses
    score -= (cap - pr) / cap * 12.0 * (1.0 + progress);

    // Penalize dead space that is too small to be useful (non-linear in pr)
    if pr > 0.0 {
        let usefulness = pr / cap;
        score += 8.0 * usefulness * (1.0 - usefulness) * (1.0 - usefulness);
    }

    // Lookahead: reward if next item fits into the post-residual
    if next_item_size > 0 && (next_item_size as f64) <= pr {
        score -= 6.0 * (1.0 - (next_item_size as f64) / cap);
    }

    // Last-chance bin: strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Mild penalty for opening new bins early
    if bin_residual == bin_capacity {
        score += 5.0 * (1.0 - progress);
    }

    // Mean residual coupling: prefer bins deviating from mean to balance residuals
    score += 0.15 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: bins whose leftover falls into small
    // "dead" residue classes (unusable for typical items) are penalized.
    let dead_zone = post_residual < 10 && post_residual > 0;
    if dead_zone {
        score += 25.0; // tiny unusable sliver
    }

    // Modulo-10 harmonic band: leftover congruent to small mod classes is
    // harder to fill later; reward leftovers aligned to coarse buckets.
    let mod10 = post_residual % 10;
    score += (mod10 as f64) * 0.6;

    // Integer-division threshold: leftover big enough to host half-capacity
    // chunks is valuable.
    if post_residual >= bin_capacity / 2 {
        score -= 15.0;
    } else if post_residual >= bin_capacity / 4 {
        score -= 6.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual,
    // strongly reward this placement (harmonic resonance k=2).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            score -= 8.0;
            // penalize leaving a gap that only barely swallows next item
            let gap = post_residual - next_item_size;
            if gap < 10 {
                score += 6.0;
            }
        } else {
            score += 4.0; // next item won't fit here
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: prefer opening a fresh bin only when no open bin
    // gives a tight fit; make empty-bin score track item_size waste.
    if bin_residual == bin_capacity {
        score = (bin_capacity - item_size) as f64 * 1.1;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 5.0;
        }
        if fitting_bins_count > 0 && item_size >= 60 {
            score += 10.0; // discourage opening bins for large items if one fits
        }
    }

    // Tight-fit reward: near-perfect packing.
    if post_residual == 0 {
        score -= 50.0;
    }

    // Slight pressure to consolidate when many bins are open.
    score += (open_bins_count as f64) * 0.05;
    score -= (mean_residual - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for any item (1..=100 range)
    // are pure waste; penalize them heavily.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual < 25 {
        // Small-but-usable gaps: mild penalty to prefer fuller packing.
        score += 8.0;
    }

    // Reward tight fits: post_residual near zero is excellent.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Reward leaving a gap that exactly accommodates the lookahead item.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    } else if next_item_size > 0 && post_residual > next_item_size {
        // Gap large enough for next item is less dead than a smaller one.
        score -= (next_item_size.min(post_residual) as f64) * 0.15;
    }

    // Last-chance bin: strongly prefer using the only bin that fits,
    // avoiding a new bin opening.
    if fitting_bins_count == 1 && bin_residual >= item_size {
        score -= 30.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // yet another bin; a new empty bin candidate gets penalized too.
    score += (open_bins_count as f64) * 2.0;

    // New-bin candidate (empty bin): penalize so it is only chosen when
    // all open bins fit poorly (its post_residual = C - item is large,
    // so base score already high; add extra pressure).
    if bin_residual == bin_capacity {
        score += 20.0;
    }

    // Slight preference for bins whose residual deviates favorably from
    // the mean: tighter-than-average bins are more valuable to fill.
    let dev = (bin_residual as f64) - mean_residual;
    if dev < 0.0 {
        score += dev * 0.3; // below-average residual (tighter bin) favored
    }

    // Late-stream consolidation: as the stream progresses, pack tighter.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += post_residual as f64 * progress * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (low post residual).
    score -= (item_size as f64 / bin_capacity as f64) * 30.0;

    // Exact fit bonus.
    if post_residual == 0 {
        score -= 50.0;
    }

    // 2-step lookahead: if next item exactly fits the post residual, big reward.
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 40.0;
        } else if post_residual >= next_item_size {
            score -= (post_residual - next_item_size) as f64 * 0.3;
        } else {
            // Next item cannot fit in the leftover: penalize dead space proportionally.
            score += (next_item_size - post_residual) as f64 * 0.2;
        }
    }

    // Compare against mean residual: prefer bins that keep residuals balanced/large.
    if post_residual as f64 > mean_residual {
        score -= (post_residual as f64 - mean_residual) * 0.1;
    } else {
        score += (mean_residual - post_residual as f64) * 0.1;
    }

    // Last chance bin: strong reward to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // New bin candidate: make it attractive only when no good fit exists.
    if bin_residual == bin_capacity {
        let good_fit = post_residual == 0 || (next_item_size > 0 && post_residual == next_item_size);
        if good_fit {
            score += 100.0; // never prefer a new bin for a perfect fit elsewhere
        } else {
            // Prefer new bin when residual waste would be large relative to capacity.
            let waste_ratio = post_residual as f64 / bin_capacity as f64;
            score -= waste_ratio * 60.0;
            if fitting_bins_count == 0 {
                score -= 20.0;
            }
        }
    }

    // Late in the stream, consolidate more aggressively.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= progress * 5.0 * (post_residual as f64 / bin_capacity as f64);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward tight fits (low post_residual) with a non-linear bonus.
    score -= (bin_capacity as f64 - post_residual as f64).powi(2) / (bin_capacity as f64 * 4.0);

    // Penalize bins that are already nearly full if the item barely fits
    // (fragile placements create risk), unless the fit is exact.
    if post_residual > 0 && post_residual < 5 {
        score += 8.0;
    }

    // Exact fit is excellent: reward heavily.
    if post_residual == 0 {
        score -= 25.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 15.0;
    }

    // Lookahead coupling: if the next item fits into the post-residual,
    // reward this placement; otherwise penalize leaving awkward gaps.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            score -= 6.0 + (next_item_size as f64 / 20.0);
        } else if post_residual > 0 {
            // Dead space that the next item cannot use.
            score += (post_residual as f64).min(next_item_size as f64) * 0.4;
        }
        // If next item exactly fills the post-residual, big reward.
        if post_residual == next_item_size {
            score -= 12.0;
        }
    }

    // Time horizon: early in the stream, be conservative (prefer filling
    // existing bins); later, allow more freedom since future matters less.
    let progress = if total_items > 0 {
        step_index as f64 / total_items as f64
    } else {
        0.0
    };
    score += (1.0 - progress) * 3.0;

    // Global state: when many bins are open relative to mean residual,
    // prefer consolidating into bins below the mean residual (larger gaps).
    if post_residual as f64 > mean_residual {
        score += (post_residual as f64 - mean_residual) * 0.15;
    } else {
        score -= (mean_residual - post_residual as f64) * 0.05;
    }

    // Penalize opening a new bin when open bins can fit, scaled by how
    // many alternatives exist and how much residual would be wasted.
    if bin_residual == bin_capacity && fitting_bins_count > 0 {
        score += 20.0 + (fitting_bins_count as f64 * 2.0);
    } else if bin_residual == bin_capacity {
        // No alternative: opening a new bin is fine, slight bonus for fresh space.
        score -= 5.0;
    }

    // Mild penalty for using a very large bin residual when the item is small
    // (wasting a big gap on a small item), non-linear in waste ratio.
    let waste_ratio = post_residual as f64 / bin_capacity as f64;
    if waste_ratio > 0.5 {
        score += (waste_ratio - 0.5) * 10.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let mut score = pr;

    // Non-linear polynomial coupling of post_residual with stream progress
    let t = progress;
    let poly = t * t * (3.0 - 2.0 * t); // smoothstep-style weight
    score += poly * pr * (pr / cap) * 0.5;

    // Penalize waste that cannot fit the lookahead item
    if next_item_size > 0 && (post_residual as u32) < next_item_size {
        score += 5.0 + (next_item_size as f64 - pr) * 0.3;
    } else if next_item_size > 0 {
        score -= 2.0;
    }

    // Reward tight fits: small post_residual relative to item
    let tight = item_size as f64 / (bin_residual.max(1) as f64);
    score -= tight * 4.0 * (1.0 - poly);

    // Last-chance bonus: only bin that fits -> strongly favor using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate: penalize unless open bins are nearly full
    if bin_residual == bin_capacity {
        let mean_gap = (mean_residual - cap).abs();
        score += 15.0 - 10.0 * poly;
        if mean_residual < 20.0 {
            score -= 8.0;
        }
        let _ = mean_gap;
    }

    // Mild penalty for many open bins to encourage consolidation early
    score += (open_bins_count as f64).sqrt() * (1.0 - t) * 0.5;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: residues that are "dead space"
    // (too small to ever host a typical item) are heavily penalized.
    let dead_threshold = 10u32; // smallest conceivable item
    if post_residual < dead_threshold {
        score -= 40.0; // perfect fill: excellent
    } else if post_residual <= 15 {
        score -= 12.0;
    } else {
        // modulo-class penalty: residues in awkward classes (e.g. mod 10 in 1..9 handled above)
        let r = post_residual % 10;
        score += 0.6 * (r as f64) * (1.0 - (post_residual as f64) / bin_capacity as f64);
    }

    // Lookahead coupling: reward bins where the next item also fits.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 6.0 + 0.15 * (next_item_size as f64);
    } else if next_item_size > 0 {
        score += 2.0;
    }

    // Last-chance bin: strongly favor using it instead of opening a bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 15.0;
    }

    // New-bin candidate: penalize opening a new bin, unless the item is large
    // and no open bin gives a tight fit (post_residual small).
    if bin_residual == bin_capacity {
        let tightness = post_residual as f64 / bin_capacity as f64;
        if tightness <= 0.2 {
            // Item nearly fills a fresh bin: opening is fine.
            score -= 8.0;
        } else {
            score += 25.0 + 0.5 * (open_bins_count as f64);
        }
    }

    // Slight preference for fuller bins early in the stream.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score -= (1.0 - progress) * (bin_residual as f64 / bin_capacity as f64) * 4.0;

    // Tie-break with mean residual spread: prefer bins below mean residual (fuller).
    score += 0.3 * (mean_residual - bin_residual as f64).max(0.0);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Dead-space penalty: residuals that are too small to hold even the
    // minimum plausible item are pure waste — hit them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 60.0;
    } else if post_residual >= 10 && post_residual <= 25 {
        // Small but potentially usable gap: mild penalty so we don't
        // create awkward slivers unless the fit is otherwise tight.
        score += 12.0 * (1.0 - (post_residual as f64 - 10.0) / 15.0);
    }

    // Reward near-perfect fits (post_residual close to 0 but not dead).
    let tightness = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 25.0 * tightness * tightness;

    // Last chance: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 40.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // this placement sets up a perfect follow-up — big reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        if slack < 10.0 {
            score -= 30.0;
        } else {
            score -= 10.0 * (1.0 - slack / 100.0);
        }
    } else if next_item_size > 0 && post_residual > 0 && post_residual < next_item_size {
        // Next item cannot use this leftover: penalize proportionally.
        score += 8.0;
    }

    // Open-bin pressure: discourage spreading across many bins when the
    // mean residual is already large (bins are mostly empty).
    if bin_residual != bin_capacity {
        let mean_r = mean_residual.max(0.0);
        if mean_r > 50.0 {
            score += 2.0 * (open_bins_count as f64).sqrt();
        } else {
            score -= 1.5 * (open_bins_count as f64).ln().max(0.0);
        }
    }

    // New-bin candidate: make it attractive only when nothing fits well.
    if bin_residual == bin_capacity {
        // Baseline: new bin costs one unit of "bin count".
        score = 50.0 + post_residual as f64;
        // If existing bins fit but all leave bad residue, new bin is fine.
        if fitting_bins_count == 0 {
            score -= 100.0;
        }
        // Early in the stream, opening fresh bins is cheap and flexible.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 20.0 * (1.0 - progress);
        // If next item is large, a fresh bin is valuable.
        if next_item_size > 50 {
            score -= 15.0;
        }
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let cap = bin_capacity as f64;
    let post = post_residual as f64;
    let mut score = post;

    // Perfect 2-step match: post_residual exactly fits next item -> strong reward.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 25.0;
    }
    // Near-match: next item fits with small slack -> moderate reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        let slack = (post_residual - next_item_size) as f64;
        score -= 10.0 * (1.0 - slack / cap);
    }
    // Dead space: post_residual too small for next item -> penalize, worse if tiny.
    if next_item_size > 0 && post_residual < next_item_size {
        let dead = post / cap;
        score += 12.0 * dead;
        if post_residual > 0 && post_residual < 10 {
            score += 8.0;
        }
    }

    // Tight fit reward: residual mostly consumed by this item.
    let fill_ratio = item_size as f64 / bin_residual as f64;
    score -= 8.0 * fill_ratio;

    // Penalize leaving residual far from mean residual (fragmentation guard).
    let dev = (post - mean_residual).abs();
    score += 0.05 * dev;

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 15.0;
    }

    // Late in the stream: consolidate, discourage opening new bins.
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        score += 20.0 * progress + 5.0;
    } else {
        score -= 5.0 * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits (small post_residual relative to capacity).
    let tightness = post_residual as f64 / bin_capacity as f64;
    score -= 20.0 * (1.0 - tightness) * (1.0 - tightness);

    // Penalize dead space that no future item can plausibly fill.
    if post_residual > 0 && post_residual < 10 {
        score -= 15.0; // near-perfect fit bonus
    }
    if post_residual > 0 && post_residual < item_size.min(80) {
        score += 8.0; // residual below typical item size -> dead space risk
    }

    // Lookahead: strongly reward bins whose residual after placement fits next item.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            let slack = (post_residual - next_item_size) as f64;
            score -= 12.0 * (1.0 - slack / bin_capacity as f64);
        } else {
            score += 6.0; // this bin can't serve the next item
        }
    }

    // Last-chance bin: strongly prefer using it over opening a new bin.
    if fitting_bins_count == 1 {
        score -= 25.0;
    }

    // Many fitting bins: mild penalty to prefer best-fit discrimination.
    if fitting_bins_count > 1 {
        score += 2.0 * (fitting_bins_count as f64 - 1.0).sqrt();
    }

    // Global state: when many bins are open with large mean residual,
    // discourage opening new bins (encourage consolidation).
    let progress = step_index as f64 / total_items.max(1) as f64;
    if bin_residual == bin_capacity {
        // New-bin candidate scoring.
        let mut nb = 0.5 * bin_capacity as f64;
        nb += 30.0 * (1.0 - progress);              // early stream: new bins cheap
        nb -= 20.0 * progress;                       // late stream: consolidate
        nb += (open_bins_count as f64).sqrt() * 2.0; // many open bins: penalize more
        if mean_residual > 30.0 {
            nb += (mean_residual - 30.0) * 0.5;      // lots of slack available
        }
        if fitting_bins_count == 1 {
            nb += 40.0; // never open new bin when a last-chance bin exists
        }
        if next_item_size > 0 && next_item_size >= bin_capacity {
            nb -= 10.0;
        }
        score = score.max(0.0) * 0.1 + nb;
    } else {
        // Mild consolidation pressure scaled by open bin count.
        score += open_bins_count as f64 * 0.15 * progress;
        // Prefer bins with residual close to mean (balanced packing).
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += dev * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: penalize wasted space quadratically
    let mut score = pr + 40.0 * norm_pr * norm_pr;

    // Smooth non-linear coupling of waste with stream progress:
    // late in the stream, small residuals matter more (less room to recover)
    let late_weight = progress * progress;
    score += late_weight * 60.0 * norm_pr;

    // Lookahead coupling: reward residuals that fit the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = if pr >= nx { 1.0 } else { 0.0 };
        let gap = (pr - nx).abs() / cap;
        score += fits_next * (-30.0 * (1.0 - gap * gap)) + (1.0 - fits_next) * 15.0 * (gap + 0.5);
    }

    // Last-chance bin: strong reward to avoid opening a new bin needlessly
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0 + 30.0 * progress;
    }

    // Many fitting bins: prefer tight fits; slight penalty scaled by open bins
    if fitting_bins_count > 1 {
        score += 5.0 * (fitting_bins_count as f64).ln();
    }

    // Mean residual coupling: penalize bins deviating from mean residual (keep pool homogeneous)
    score += 0.3 * (pr - mean_residual).abs();

    // New-bin candidate: encourage opening a new bin early or when item is large
    if bin_residual == bin_capacity {
        let early_bonus = 1.0 - progress;
        score -= 20.0 * early_bonus + 0.2 * item_size as f64;
        score += 10.0 * progress * progress;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: how "reusable" is the leftover space?
    // Class residuals into buckets of 10 (capacity fractions), rewarding leftovers
    // that align with common item sizes (multiples of 10) and punishing odd slivers.
    let residual_mod = post_residual % 10;
    let residual_class = post_residual / 10; // 0..=10 harmonic class

    // Penalize non-decimal leftover slivers (dead space that rarely matches items).
    score += (residual_mod as f64) * 0.8;

    // Reward large reusable leftover classes, but strongly punish tiny class 0/1
    // leftovers (wasted bin bottoms).
    match residual_class {
        0 => score += 25.0,
        1 => score += 10.0,
        2 => score -= 2.0,
        3 => score -= 5.0,
        4 => score -= 8.0,
        5 => score -= 10.0,
        _ => score -= 12.0,
    }

    // Perfect fit gets a massive reward.
    if post_residual == 0 {
        score -= 60.0;
    }

    // Lookahead coupling: if the next item fits exactly into post_residual,
    // reward this bin strongly (chain packing).
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 40.0;
        } else if next_item_size <= post_residual {
            // Next item fits but imperfectly: mild reward scaled by tightness.
            let slack = (post_residual - next_item_size) as f64;
            score -= 10.0 - slack.min(10.0);
        } else {
            // Next item cannot use this leftover: penalize proportional to waste.
            score += ((next_item_size - post_residual) as f64) * 0.15;
        }
    }

    // Last-chance bin: if this is the ONLY bin that fits, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate logic: an empty bin scores post_residual == capacity (100).
    // Make opening a new bin expensive unless no good alternative exists:
    // penalize it more when many bins are open and mean residual is healthy.
    if bin_residual == bin_capacity {
        score += 35.0 + (open_bins_count as f64).sqrt() * 5.0
            + (mean_residual / bin_capacity as f64) * 20.0;
        // Early in the stream, opening bins is fine (need spread).
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score -= (1.0 - progress) * 25.0;
    } else {
        // Prefer fuller bins: reward bins whose residual is close to item size.
        let tightness = (bin_residual - item_size) as f64;
        score += 0.0 - (1.0 - tightness / bin_capacity as f64) * 5.0;
    }

    // Mean-residual shaping: if this bin's post-residual is far below mean residual,
    // it's consolidating space well — reward it.
    score += (mean_residual - post_residual as f64) * 0.05;

    // Harmonic modulo coupling between item and residual: aligned parities pack well.
    if (item_size % 10) == (bin_residual % 10) && bin_residual < bin_capacity {
        score -= 3.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals that are too small to hold the
    // smallest plausible item (<= 10) are pure waste -> heavy penalty.
    if post_residual < 10 {
        score += 25.0 + (10 - post_residual) as f64 * 4.0;
    } else if post_residual < 20 {
        // Small awkward gaps: moderate penalty scaled by how close to unusable.
        score += (20 - post_residual) as f64 * 1.5;
    }

    // Reward tight fits: small post_residual relative to item size is good.
    if item_size > 0 {
        score -= (item_size as f64) * 0.6;
    }

    // Perfect fit bonus.
    if post_residual == 0 {
        score -= 15.0;
    }

    // Lookahead: if the next item fits exactly into the post_residual, reward strongly.
    if next_item_size > 0 && post_residual == next_item_size {
        score -= 20.0;
    } else if next_item_size > 0 && post_residual >= next_item_size {
        // Mild reward if the next item can still fit after this placement.
        score -= 4.0;
    } else if next_item_size > 0 && post_residual > 0 {
        // Penalize blocking the next item.
        score += 6.0;
    }

    // Open-bins pressure: discourage spreading items across many bins.
    score += open_bins_count as f64 * 0.8;

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 30.0;
    }

    // New-bin candidate: neutral-ish baseline; only chosen when open bins score poorly.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 1.5;
    } else {
        // Prefer bins with less residual overall (better packing density),
        // relative to the mean residual across open bins.
        score += (mean_residual - bin_residual as f64) * 0.3;
    }

    // Slight late-stream tightening: as the stream progresses, favor denser packing.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += progress * (bin_residual as f64 - post_residual as f64) * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward perfect or near-perfect fits (low dead space).
    let tightness = (bin_capacity as f64 - post_residual as f64) / bin_capacity as f64;
    score -= 12.0 * tightness;

    // Aggressive 2-step lookahead: strongly reward bins whose post_residual
    // can host the next item (chained packing), scaled by how snugly it fits.
    if next_item_size > 0 && next_item_size <= post_residual {
        let chain_slack = (post_residual - next_item_size) as f64;
        score -= 8.0 * (1.0 - chain_slack / bin_capacity as f64);
    } else if next_item_size > 0 {
        // Penalize leaving a residual that the next item cannot use.
        score += 4.0;
    }

    // Compare against mean residual across open bins: bins tighter than the
    // mean are more valuable to fill now.
    score += 0.5 * (post_residual as f64 - mean_residual);

    // Last-chance bin: strongly prefer using it to avoid opening a new bin.
    if fitting_bins_count == 1 {
        score -= 20.0;
    }

    // New-bin candidate: only attractive when no open bin fits well.
    let is_new_bin = bin_residual == bin_capacity;
    if is_new_bin {
        let pressure = if fitting_bins_count > 0 {
            (fitting_bins_count as f64).recip()
        } else {
            1.0
        };
        // Base penalty for opening a new bin, softened when few fitting bins
        // exist or the item would leave large unusable space anywhere.
        score += 15.0 * pressure;
        // As stream progresses, discourage proliferation of open bins.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += 10.0 * progress;
        // If item is large relative to capacity, a fresh bin is more tolerable.
        score -= 5.0 * (item_size as f64 / bin_capacity as f64);
    }

    // Mild penalty for creating very small unusable slivers.
    if post_residual > 0 && post_residual < 10 {
        score += 6.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Tight fit reward: strongly favor bins whose residual after placement is small.
    let tight = 1.0 - (post_residual as f64 / bin_capacity as f64);
    score -= 3.0 * tight * tight;

    // Penalize dead space that the next item cannot use.
    if next_item_size > 0 {
        if post_residual >= next_item_size {
            // Reward leaving room exactly exploitable by the lookahead item.
            let slack = post_residual - next_item_size;
            score -= 1.5 * (1.0 - slack as f64 / bin_capacity as f64);
        } else {
            // Dead space: unusable by next item; penalize proportionally.
            score += 0.8 * (post_residual as f64 / bin_capacity as f64);
        }
    } else {
        // Last item: pure tight fit.
        score -= 2.0 * tight;
    }

    // Last-chance bonus: if this is the only bin that fits, strongly prefer using it.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 6.0;
    }

    // New-bin candidate handling: opening a new bin should be reserved for
    // genuinely poor fits elsewhere. Base penalty grows with open bins.
    if bin_residual == bin_capacity {
        let progress = step_index as f64 / (total_items.max(1) as f64);
        score += 4.0 + 0.5 * open_bins_count as f64 + 2.0 * (1.0 - progress);
        // If item nearly fills a fresh bin, opening is cheap.
        if item_size * 4 >= bin_capacity * 3 {
            score -= 3.0;
        }
    } else {
        // Slight preference for bins with residuals near the mean (balanced packing)
        let dev = (bin_residual as f64 - mean_residual).abs();
        score += 0.05 * dev;
    }

    // Early stream: be more tolerant of spreading across bins.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score *= 0.8 + 0.4 * progress;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let norm_pr = pr / cap;

    // Base: prefer tight fits (small post_residual), with non-linear emphasis
    let mut score = pr * (1.0 + 0.8 * norm_pr * norm_pr);

    // Smooth polynomial coupling of post_residual with stream progress:
    // early on, waste is cheap; later, waste is penalized quadratically.
    let waste_weight = 0.5 + 2.0 * progress * progress;
    score += waste_weight * norm_pr * pr;

    // Penalize near-full residual that becomes dead space, smoothly.
    if next_item_size > 0 {
        let nxt = next_item_size as f64;
        let unusable = ((nxt - pr) / cap).max(0.0);
        score += 6.0 * unusable * unusable * cap;
    }

    // Reward using bins when many are open (consolidation pressure).
    score -= 0.3 * (open_bins_count as f64).ln().max(0.0);

    // Last-chance bin: strongly reward placing here to avoid a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: penalize unless the item leaves a large residual
    // that matches the lookahead, or few bins are open.
    if bin_residual == bin_capacity {
        let mut penalty = 30.0 + 40.0 * progress;
        if next_item_size > 0 && post_residual >= next_item_size {
            penalty -= 20.0;
        }
        if open_bins_count == 0 {
            penalty = 0.0;
        }
        score += penalty;
    }

    // Smooth alignment bonus: residual after placement close to mean residual
    // keeps the fleet homogeneous.
    score -= 0.5 * (-((pr - mean_residual) / cap).abs());

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of the post residual: which capacity-fraction slot does it land in?
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let frac = pr / cap; // 0..1

    // Class boundaries at 1/4, 1/2, 3/4 of capacity. Dead space in low classes is worse.
    let class = if post_residual == 0 {
        0u32 // perfect fit: best possible
    } else if frac <= 0.25 {
        1u32 // tiny residual, mostly wasted
    } else if frac <= 0.5 {
        2u32
    } else if frac <= 0.75 {
        3u32
    } else {
        4u32 // large residual, still very usable
    };

    // Integer-division thresholds on post_residual (harmonic slots of 10 units)
    let slot = post_residual / 10;
    score += (slot % 3) as f64 * 1.5; // mild modulo penalty to break ties non-linearly

    // Reward perfect fit strongly
    if post_residual == 0 {
        score -= 40.0;
    } else {
        // Non-linear penalty: quadratic in wasted fraction, weighted by class rarity
        score += frac * frac * 30.0;
        score -= (class as f64) * 2.0;
    }

    // Lookahead coupling: if next item fits exactly into post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 25.0;
        } else if next_item_size < post_residual {
            let nf = next_item_size as f64 / cap;
            // favor residuals that keep a "harmonic" size for the next item
            score += (pr - next_item_size as f64) * 0.15;
            if (next_item_size % 25 == 0) && post_residual >= next_item_size {
                score -= 5.0;
            }
            let _ = nf;
        } else {
            // next item won't fit here; residual becomes dead unless class is large
            if class <= 1 {
                score += 8.0;
            }
        }
    } else {
        // last item: any residual is pure waste; minimize it
        score += 10.0;
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 12.0;
    }

    // New-bin candidate handling: opening a new bin should only win when all open fits are bad
    if bin_residual == bin_capacity {
        // base cost of a fresh bin
        score = cap * 0.9;
        // cheaper to open a new bin when many bins are open and mean residual is fragmented
        score -= (open_bins_count as f64).min(20.0) * 0.5;
        if mean_residual < 0.2 * cap {
            score -= 10.0; // existing bins are nearly full anyway
        }
        // don't open a new bin for tiny items if a decent fit exists
        if item_size <= 25 && mean_residual >= item_size as f64 * 1.5 {
            score += 15.0;
        }
        // lookahead: new bin guarantees next item fits if it's small
        if next_item_size > 0 && next_item_size <= bin_capacity {
            score -= 3.0;
        }
    }

    // Stream progression: late in the stream, be more conservative about waste
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += frac * progress * 10.0;
    }

    // Mean residual coupling: prefer bins whose residual is near the mean (balanced packing)
    score += ((bin_residual as f64) - mean_residual).abs() * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: small unusable gaps are heavily penalized.
    if post_residual > 0 && post_residual < 10 {
        score += (10.0 - post_residual as f64) * 8.0;
    }
    // Perfect fit gets a strong reward.
    if post_residual == 0 {
        score -= 30.0;
    }

    // Reward fitting tightly relative to the item size (small waste ratio).
    score -= (item_size as f64 / bin_residual.max(1) as f64) * 15.0;

    // Lookahead: if the next item fits exactly into post_residual, reward.
    if next_item_size > 0 && post_residual >= next_item_size {
        score -= 12.0;
    } else if next_item_size > 0 && post_residual > 0 {
        score += 6.0;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Open-bin pressure: many open bins -> discourage spreading, favor consolidation.
    score += (open_bins_count as f64) * 0.8;

    // New-bin candidate: only attractive when nothing fits well or stream is early.
    if bin_residual == bin_capacity {
        let pressure = if fitting_bins_count == 0 { 0.0 } else { 15.0 };
        score += pressure + (open_bins_count as f64) * 1.5;
        if next_item_size > 0 && next_item_size > bin_residual {
            score -= 5.0;
        }
    }

    // Mild preference to fill bins with larger mean residual less eagerly.
    score += mean_residual * 0.05;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // 2-step lookahead: reward exact/near match with the next item's size.
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 60.0; // perfect fill on the next step
        } else if next_item_size <= post_residual {
            let leftover = (post_residual - next_item_size) as f64;
            score -= 40.0 - leftover * 0.8; // reward fit, penalize leftover
        } else {
            // next item cannot fit here; slight penalty scaled by overflow gap
            let gap = (next_item_size - post_residual) as f64;
            score += gap * 0.3;
        }
    } else {
        // Last item: reward tight fills aggressively
        score -= (bin_capacity - post_residual) as f64 * 0.5;
    }

    // Prefer bins whose residual is already below mean (compact bins get filled)
    let res = post_residual as f64;
    if res < mean_residual {
        score -= (mean_residual - res) * 0.15;
    } else {
        score += (res - mean_residual) * 0.15;
    }

    // Last-chance bin: strongly favor using it to avoid opening a new bin
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 25.0;
    }

    // Penalize creating tiny unusable dead space (< next smallest plausible item)
    if res > 0 && res < 10.0 {
        score += 15.0;
    }

    // Early in stream: keep bins open/flexible; late: consolidate tightly
    let progress = step_index as f64 / (total_items.max(1) as f64);
    score += res * 0.1 * (1.0 - progress);

    // Slight preference to reuse existing bins over opening new ones
    if bin_residual == bin_capacity {
        score += 8.0 + open_bins_count as f64 * 0.05;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Reward tight fits: square the post residual to strongly penalize wasted space.
    score += (post_residual as f64).powi(2) / bin_capacity as f64;

    // Lookahead: if the next item fits exactly into post_residual, strongly reward this bin.
    if next_item_size > 0 && next_item_size <= post_residual {
        let slack_after_next = post_residual - next_item_size;
        score -= (1.0 - slack_after_next as f64 / bin_capacity as f64) * 15.0;
    }

    // Last-chance bin: strongly favor using the only bin that can fit the item.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 20.0;
    }

    // Penalize opening a new bin when existing bins fit reasonably well.
    if bin_residual == bin_capacity {
        score += 10.0 + open_bins_count as f64 * 0.5;
        // But if mean residual across open bins is small (fragmented), opening new bin is less bad.
        score -= mean_residual * 0.05;
        // Late in the stream, prefer closing out bins rather than opening new ones.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score += progress * 5.0;
    } else {
        // Slightly prefer bins with residual close to item_size (best-fit flavor).
        score -= (bin_residual as f64 - item_size as f64).abs() * 0.02;
    }

    // Mild pressure to keep number of open bins low.
    score += open_bins_count as f64 * 0.1;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let cap = bin_capacity as f64;
    let pr = post_residual as f64;
    let pr_norm = pr / cap;

    // Base: prefer small post-residual, with smooth non-linear shaping
    let mut score = pr * (1.0 + 0.5 * pr_norm * pr_norm);

    // Polynomial coupling of post_residual with stream progress:
    // early on, tolerate slack; late in the stream, penalize it more strongly
    let progress_weight = 1.0 + 2.0 * progress * progress;
    score += 8.0 * progress_weight * pr_norm * pr_norm;

    // Lookahead coupling: reward residual that can still fit the next item smoothly
    if next_item_size > 0 {
        let nx = next_item_size as f64;
        let fits_next = ((pr - nx) / cap).max(0.0);
        score -= 6.0 * (1.0 - (fits_next * cap / 40.0).min(1.0)) * (1.0 - progress * 0.5);
        // exact next-item fit bonus (smooth gaussian-like)
        let diff = (pr - nx).abs();
        score -= 10.0 * (-(diff * diff) / 50.0).exp();
    } else {
        // last item: heavily reward tight closure
        score -= 15.0 * (1.0 - pr_norm);
    }

    // Last-chance bin: strongly favor using it before opening a new bin
    if fitting_bins_count == 1 {
        score -= 20.0;
    } else if fitting_bins_count > 1 {
        // mild penalty when many bins compete, scaled by mean residual alignment
        let align = 1.0 - ((pr - mean_residual).abs() / cap);
        score += 2.0 * (fitting_bins_count as f64).ln() * (1.0 - align);
    }

    // Penalize bins whose residual deviates from the mean residual (smooth dispersion term)
    score += 3.0 * ((pr - mean_residual) / cap).abs();

    // Mild new-bin penalty so open bins are preferred unless they are truly bad
    if bin_residual == bin_capacity {
        score += 5.0 + 10.0 * progress;
    }

    // Smooth crowding term: many open bins -> encourage consolidation
    score += 0.5 * (open_bins_count as f64).ln().max(0.0) * pr_norm;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Perfect fit: strongly reward zero post_residual.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Harmonic classes: classify post_residual by capacity fractions.
    // Residuals in (0, small] are nearly dead space; penalize harshly.
    let c = bin_capacity as f64;
    let pr = post_residual as f64;
    let small_dead = bin_capacity / 20; // 5% of capacity
    if post_residual > 0 && post_residual <= small_dead {
        score += 300.0;
    }

    // Class bins by residual magnitude using integer division thresholds.
    // post_residual / (C/4): 0 -> tiny, 1 -> quarter, 2 -> half, 3 -> large.
    let quarter = bin_capacity / 4;
    let class = post_residual / quarter.max(1);
    score += match class {
        0 => 120.0,
        1 => 40.0,
        2 => 0.0,
        _ => -30.0,
    } as f64;

    // Lookahead coupling: if the next item exactly matches post_residual,
    // this is a perfect chain placement — reward heavily.
    if next_item_size > 0 && next_item_size == post_residual {
        score -= 800.0;
    } else if next_item_size > 0 && next_item_size <= post_residual {
        // Next item fits here: reward proportionally to how well it fills.
        let fill = next_item_size as f64 / pr.max(1.0);
        score -= 100.0 * fill;
    } else if next_item_size > post_residual {
        // Next item cannot use this residual; penalize leaving medium gaps.
        score += 0.5 * pr;
    }

    // Harmonic pairing: next_item_size and post_residual share a divisor class
    // (e.g., both multiples of 10 or 25) — likely reusable gap.
    if next_item_size > 0 && post_residual > 0 {
        let both10 = next_item_size % 10 == 0 && post_residual % 10 == 0;
        let both25 = next_item_size % 25 == 0 && post_residual % 25 == 0;
        if both10 || both25 {
            score -= 60.0;
        }
        // Parity/mismatch penalty: odd residual rarely reused.
        if post_residual % 2 == 1 {
            score += 15.0;
        }
    }

    // Last-chance bin: strongly favor using the only fitting bin.
    if fitting_bins_count == 1 {
        score -= 500.0;
    }

    // New-bin candidate handling: only prefer a fresh bin when all open
    // residuals are too fragmented (low mean_residual relative to item needs)
    // and few bins fit the item.
    if bin_residual == bin_capacity {
        let crowded = open_bins_count as f64 * 0.05;
        let desperation = if mean_residual < item_size as f64 { 1.0 } else { 0.0 };
        score = 250.0 + crowded - 400.0 * desperation
            - if fitting_bins_count == 0 { 200.0 } else { 0.0 };
        // Early in the stream, opening bins is cheap and useful.
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 50.0 * (1.0 - progress);
        // If next item is huge, a fresh bin is attractive.
        if next_item_size > bin_capacity / 2 {
            score -= 80.0;
        }
    }

    // Mild preference to balance load across many open bins.
    score += 0.01 * open_bins_count as f64;

    // Small tie-break favoring fuller bins late in the stream.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score -= 20.0 * progress * (1.0 - pr / c);

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: penalize small unusable gaps after placement.
    let dead_threshold = 10.0;
    if (post_residual as f64) < dead_threshold && post_residual > 0 {
        score += (dead_threshold - post_residual as f64) * 6.0;
    }
    // Perfect fit reward.
    if post_residual == 0 {
        score -= 40.0;
    }

    // Penalize creating gaps that cannot fit the lookahead item but could have.
    if next_item_size > 0 && post_residual > 0 && (post_residual as u64) < next_item_size as u64 {
        score += 8.0;
    }
    // Reward leaving room for the lookahead item.
    if next_item_size > 0 && (post_residual as u64) >= next_item_size as u64 {
        score -= 10.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading; with few, encourage filling.
    let progress = step_index as f64 / (total_items.max(1) as f64);
    let pressure = open_bins_count as f64 * (0.5 + progress);
    score += pressure * 0.8;

    // Last-chance bin: strongly favor using it before opening a new one.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // New-bin candidate: only attractive when existing residuals are poor fits.
    if bin_residual == bin_capacity {
        let tight = (mean_residual - item_size as f64).abs();
        score += 15.0 - tight * 0.5;
        if fitting_bins_count == 0 {
            score -= 60.0;
        }
    }

    // Mild preference for bins with residuals close to mean (balanced packing).
    score += (bin_residual as f64 - mean_residual).abs() * 0.15;

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strong reward for perfect fit
    if post_residual == 0 {
        score -= 1000.0;
    }

    // 2-step lookahead: exact match of next item into post_residual
    if next_item_size > 0 {
        if post_residual == next_item_size {
            score -= 400.0;
        } else if post_residual >= next_item_size {
            // next item can also fit here: mild bonus scaled by leftover
            let two_left = post_residual - next_item_size;
            score -= 60.0 - (two_left as f64).min(60.0);
        } else {
            // next item cannot fit here: penalize tight fits that strand space
            let gap = (next_item_size - post_residual) as f64;
            if gap < 10.0 {
                score += 30.0 * (10.0 - gap);
            }
        }
    }

    // Reward bins tighter than average (good fills)
    let dev = mean_residual - post_residual as f64;
    score += 0.5 * dev.max(0.0) - 0.3 * (-dev).max(0.0);

    // Last chance bin: strongly favor using it to avoid a new bin
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 250.0;
    }

    // New-bin candidate: only attractive when current fit is poor
    if bin_residual == bin_capacity {
        let waste = (bin_capacity - item_size) as f64;
        score = waste + 50.0;
        if next_item_size > 0 && next_item_size <= bin_capacity - item_size {
            score -= 40.0;
        }
        if fitting_bins_count == 1 {
            score += 300.0; // prefer using the existing last-chance bin
        }
    }

    // Penalize creating small unusable slivers
    if post_residual > 0 && post_residual < 10 {
        score += 80.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Exact fit is perfect: strong reward.
    if post_residual == 0 {
        score -= 1000.0;
    }

    // Tight fit reward: fraction of bin consumed by this placement.
    let fill_ratio = item_size as f64 / bin_capacity as f64;
    score -= 40.0 * fill_ratio;

    // Penalize leaving awkward dead space (nonzero but unusable-looking).
    if post_residual > 0 {
        // Dead space penalty grows for small leftovers that few items can use.
        let awkward = (post_residual as f64 / 20.0).powi(2);
        score += awkward;
    }

    // Lookahead: if next item fits into the resulting residual, reward chaining.
    if next_item_size > 0 {
        if next_item_size <= post_residual {
            score -= 30.0;
            // Extra reward if next item nearly fills the remaining space too.
            let next_tightness = next_item_size as f64 / post_residual as f64;
            score -= 20.0 * next_tightness;
        } else {
            // Leaving a residual that the next item cannot use is mildly bad.
            score += 10.0;
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer it
    // over opening a new bin.
    if fitting_bins_count == 1 && bin_residual < bin_capacity {
        score -= 50.0;
    }

    // New-bin candidate handling: an empty bin starts with a base cost so we
    // only open a new bin when existing fits are poor.
    if bin_residual == bin_capacity {
        score += 120.0;
        // Open new bins more freely early in the stream (future flexibility).
        let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
        score -= 60.0 * (1.0 - progress);
        // If existing bins are already fragmented (high mean residual spread),
        // opening a fresh bin is more attractive.
        score -= (mean_residual - post_residual as f64).abs().min(50.0) * 0.5;
        // Avoid opening too many bins at once.
        score += 5.0 * open_bins_count as f64;
    } else {
        // Prefer bins whose residual is below the mean (tighter bins first),
        // keeping looser bins available for larger future items.
        score += 0.3 * (bin_residual as f64 - mean_residual).max(0.0);
    }

    // Late in the stream, prioritize closing out bins tightly.
    if total_items > 0 {
        let progress = step_index as f64 / total_items as f64;
        score += 25.0 * progress * (post_residual as f64 / bin_capacity as f64);
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let progress = step_index as f64 / total_items.max(1) as f64;
    let pr = post_residual as f64;
    let cap = bin_capacity as f64;
    let pr_norm = pr / cap;
    let fit = fitting_bins_count as f64;
    let next = next_item_size as f64;

    let mut score = pr;

    // Smooth non-linear coupling of post_residual with stream progress
    score += 40.0 * (pr_norm * pr_norm) * (0.5 + progress);
    score -= 25.0 * (pr_norm * (1.0 - pr_norm)) * (1.0 - progress);

    // Reward tight fits more strongly as stream progresses
    score -= (1.0 - pr_norm) * (1.0 - pr_norm) * (20.0 + 30.0 * progress);

    // Penalize when many bins fit (weaker urgency), reward scarcity
    score -= 15.0 / (fit + 1.0);

    // Lookahead: if next item fits the post residual, reward this placement
    if next > 0.0 && next <= pr {
        score -= 12.0 * (1.0 - pr_norm) * (0.5 + 0.5 * progress);
    } else if next > pr {
        score += 6.0 * (next - pr) / cap;
    }

    // Dead-space penalty: small but nonzero post residual is wasteful
    if pr > 0.0 && pr < 10.0 {
        score += 8.0 * (1.0 - pr / 10.0);
    }

    // New-bin candidate: mild penalty so it loses to good fits, wins over bad fits
    if bin_residual == bin_capacity {
        score += 18.0 - 10.0 * progress;
    }

    // Dampen preference for bins far from mean residual
    score += 0.05 * (pr - mean_residual).abs();

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Harmonic class of post_residual: classify leftover space by capacity fraction
    let c = bin_capacity as f64;
    let post = post_residual as f64;
    let quarter = c / 4.0;

    // Dead-space penalty: residuals that are too small to be useful
    if post_residual == 0 {
        score -= 40.0; // perfect fit is ideal
    } else if post_residual < 10 {
        score += 30.0; // unusable sliver
    } else if post_residual < 20 {
        score += 18.0;
    }

    // Harmonic band reward: residual in {C/4, C/2, 3C/4} neighborhoods is reusable
    let band = (post - quarter).abs();
    let band2 = (post - 2.0 * quarter).abs();
    let band3 = (post - 3.0 * quarter).abs();
    let band_min = band.min(band2).min(band3);
    if band_min < 8.0 {
        score -= 10.0;
    }

    // Integer-division class of post_residual by 10: prefer class 0 (exact decades)
    if post_residual % 10 == 0 {
        score -= 5.0;
    }

    // Lookahead coupling: if next item fits exactly in post_residual, big reward
    if next_item_size > 0 {
        if next_item_size == post_residual {
            score -= 35.0;
        } else if next_item_size < post_residual {
            score -= 8.0;
        } else {
            score += 6.0; // next item won't fit here; bin becomes dead-ish
        }
    }

    // Last-chance bin: if this is the only fitting bin, strongly prefer using it
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 25.0;
    }

    // Penalize opening a new bin when good fitting bins exist
    if bin_residual == bin_capacity {
        // new-bin candidate: base cost of opening a bin
        score += 50.0;
        if fitting_bins_count > 0 {
            score += 15.0; // extra penalty since an open bin could fit
        }
        // but if open bins are all fragmented (high mean residual, poor fits), soften
        if mean_residual < 15.0 && open_bins_count > 0 {
            score -= 20.0;
        }
        // early in stream, opening bins is cheaper
        let progress = step_index as f64 / total_items.max(1) as f64;
        score -= 10.0 * (1.0 - progress);
    }

    // Slight preference for tighter bins among equals
    score -= (bin_capacity - bin_residual) as f64 * 0.05;

    // Mild load-balancing: many open bins with high mean residual -> prefer filling them
    if open_bins_count > 3 && mean_residual > c / 3.0 && bin_residual != bin_capacity {
        score -= 5.0;
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strict dead-space avoidance: residuals too small for the smallest
    // possible item (1..10) are "dead space". Penalize them hard.
    if post_residual > 0 && post_residual < 10 {
        score += 40.0 + (10 - post_residual) as f64 * 6.0;
    } else if post_residual == 0 {
        // Perfect fit: reward strongly.
        score -= 60.0;
    } else if post_residual >= 10 {
        // Usable residual: mild reward scaled by how well it matches
        // the upcoming item (lookahead k=2).
        if next_item_size > 0 && (post_residual as u32) == next_item_size {
            score -= 25.0; // residual exactly fits next item
        } else if next_item_size > 0 && (post_residual as u32) >= next_item_size {
            score -= 8.0; // residual can still host next item
        }
    }

    // Last-chance bin: if this is the only bin that fits, strongly prefer
    // using it over opening a new bin.
    if fitting_bins_count == 1 && bin_residual != bin_capacity {
        score -= 35.0;
    }

    // Open-bin pressure: with many open bins, discourage spreading into
    // new/partially-filled bins; consolidation is favored.
    let pressure = open_bins_count as f64 * 1.5;
    score += pressure * (bin_residual as f64 / bin_capacity as f64);

    // New-bin candidate: only attractive when no open bin fits well.
    if bin_residual == bin_capacity {
        if fitting_bins_count == 0 {
            score -= 100.0; // forced: must open a new bin
        } else {
            // Opening a new bin wastes the residual of existing bins;
            // penalize proportionally to mean residual left behind.
            score += 55.0 + mean_residual * 0.4;
        }
    } else {
        // Prefer bins whose residual is already tight (good fill ratio).
        score -= (bin_capacity - bin_residual) as f64 * 0.3;
    }

    // Slight late-stream tightening: as the stream progresses, favor
    // closing out bins (exact-ish fits) a bit more aggressively.
    let progress = if total_items > 0 { step_index as f64 / total_items as f64 } else { 0.0 };
    if post_residual > 0 && post_residual < 20 {
        score += progress * 10.0; // dead-ish space costs more late in stream
    }

    score
}

pub fn score_bin(item_size: u32, bin_residual: u32, bin_capacity: u32, step_index: usize, total_items: usize, open_bins_count: usize, mean_residual: f64, next_item_size: u32, post_residual: u32, fitting_bins_count: usize) -> f64 {
    let mut score = post_residual as f64;

    // Strongly reward exact / tight fits.
    if post_residual == 0 {
        score -= 1000.0;
    } else if post_residual <= 5 {
        score -= 200.0;
    }

    // Aggressive 2-step lookahead: reward bins whose post_residual matches next_item_size.
    if next_item_size > 0 {
        let post = post_residual as f64;
        let nxt = next_item_size as f64;
        if post_residual == next_item_size {
            score -= 500.0;
        } else if post_residual >= next_item_size {
            // Slack after hypothetically placing the next item too: smaller is better.
            score -= 60.0 * (1.0 - (post - nxt) / bin_capacity as f64);
        } else {
            // Next item won't fit here: penalize proportionally to the wasted gap.
            score += 40.0 * (nxt - post) / nxt.max(1.0);
        }
    }

    // Prefer bins with residuals below the mean (consolidate fullness).
    score += (post_residual as f64 - mean_residual) * 0.5;

    // Last-chance bonus: if this is the only bin that fits, avoid opening a new bin.
    if fitting_bins_count == 1 && bin_residual >= item_size && bin_residual != bin_capacity {
        score -= 150.0;
    }

    // Penalize the brand-new empty bin unless existing fits are bad.
    if bin_residual == bin_capacity {
        score += 120.0 + 0.3 * mean_residual;
        // If next item is large and post_residual leaves a big hole, opening fresh is fine.
        if next_item_size > 0 && post_residual > next_item_size && post_residual < item_size {
            score -= 100.0;
        }
    }

    // Late in the stream, favor closing bins tightly.
    let progress = step_index as f64 / total_items.max(1) as f64;
    score += 0.2 * post_residual as f64 * progress;

    score
}
